    public static function loadXmlDocument(string $xml, string $label = 'XML document', bool $preserveWhiteSpace = true): \DOMDocument
    {
        self::assertSafeSource($xml, $label);
        self::assertNoDoctype($xml, $label);

        $previous = libxml_use_internal_errors(true);
        $dom = new \DOMDocument();
        $dom->preserveWhiteSpace = $preserveWhiteSpace;
        $dom->resolveExternals = false;
        $dom->substituteEntities = false;
        $loaded = $dom->loadXML($xml, LIBXML_NONET | LIBXML_NOERROR | LIBXML_NOWARNING);
        $errors = libxml_get_errors();
        libxml_clear_errors();
        libxml_use_internal_errors($previous);

        if (!$loaded) {
            throw new \InvalidArgumentException(self::parseErrorMessage('Unable to parse ' . $label, $errors));
        }

        self::assertNoProcessingInstructions($dom, $label);

        return $dom;
    }

    public static function loadHtmlFragment(string $html, string $label = 'HTML fragment', bool $protectRawTextContentForParse = false): \DOMDocument
    {
        self::assertSafeSource($html, $label);
        $preflight = self::protectHtmlRcdataElements(
            $html,
            protectTemplateContent: true,
            protectIframeContent: true,
            protectRawTextContent: true,
            protectNoscriptContent: true
        );
        self::assertNoDoctype($preflight, $label);
        self::assertNoHtmlFragmentDeclarations($preflight, $label);
        $html = self::protectHtmlRcdataElements(
            $html,
            protectTemplateContent: true,
            protectIframeContent: true,
            protectRawTextContent: $protectRawTextContentForParse,
            protectNoscriptContent: true
        );

        $wrapped = '<!DOCTYPE html><html><head><meta charset="utf-8"></head><body><div '
            . self::FRAGMENT_ROOT_ATTRIBUTE . '="1">' . $html . '</div></body></html>';

        $previous = libxml_use_internal_errors(true);
        $dom = new \DOMDocument('1.0', 'UTF-8');
        $dom->preserveWhiteSpace = true;
        $dom->resolveExternals = false;
        $dom->substituteEntities = false;
        $loaded = $dom->loadHTML($wrapped, LIBXML_NONET | LIBXML_NOERROR | LIBXML_NOWARNING);
        $errors = libxml_get_errors();
        libxml_clear_errors();
        libxml_use_internal_errors($previous);

        if (!$loaded || self::fragmentRoot($dom) === null) {
            throw new \InvalidArgumentException(self::parseErrorMessage('Unable to parse ' . $label, $errors));
        }

        return $dom;
    }

    public static function rootElement(\DOMDocument $dom, ?string $localName = null, ?string $namespace = null): ?\DOMElement
    {
        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement || !self::elementMatches($root, $localName, $namespace)) {
            return null;
        }

        return $root;
    }

    public static function elementMatches(\DOMElement $element, ?string $localName = null, ?string $namespace = null): bool
    {
        if ($localName !== null && $element->localName !== $localName) {
            return false;
        }

        if ($namespace !== null && ($element->namespaceURI ?? '') !== $namespace) {
            return false;
        }

        return true;
    }

    /**
     * @return list<\DOMElement>
     */
    public static function childElements(\DOMElement $element, ?string $localName = null, ?string $namespace = null): array
    {
        $children = [];
        foreach ($element->childNodes as $child) {
            if (!$child instanceof \DOMElement || !self::elementMatches($child, $localName, $namespace)) {
                continue;
            }

            $children[] = $child;
        }

        return $children;
    }

    public static function firstChildElement(\DOMElement $element, ?string $localName = null, ?string $namespace = null): ?\DOMElement
    {
        foreach (self::childElements($element, $localName, $namespace) as $child) {
            return $child;
        }

        return null;
    }

    /**
     * @return list<\DOMElement>
     */
    public static function descendantElements(\DOMElement $element, ?string $localName = null, ?string $namespace = null): array
    {
        $descendants = [];
        $stack = [];
        for ($index = $element->childNodes->length - 1; $index >= 0; --$index) {
            $child = $element->childNodes->item($index);
            if ($child instanceof \DOMElement) {
                $stack[] = $child;
            }
        }

        while ($stack !== []) {
            $node = array_pop($stack);
            if (!$node instanceof \DOMElement) {
                continue;
            }

            if (self::elementMatches($node, $localName, $namespace)) {
                $descendants[] = $node;
            }

            for ($index = $node->childNodes->length - 1; $index >= 0; --$index) {
                $child = $node->childNodes->item($index);
                if ($child instanceof \DOMElement) {
                    $stack[] = $child;
                }
            }
        }

        return $descendants;
    }

    public static function firstDescendantElement(\DOMElement $element, ?string $localName = null, ?string $namespace = null): ?\DOMElement
    {
        $stack = [];
        for ($index = $element->childNodes->length - 1; $index >= 0; --$index) {
            $child = $element->childNodes->item($index);
            if ($child instanceof \DOMElement) {
                $stack[] = $child;
            }
        }

        while ($stack !== []) {
            $node = array_pop($stack);
            if (!$node instanceof \DOMElement) {
                continue;
            }

            if (self::elementMatches($node, $localName, $namespace)) {
                return $node;
            }

            for ($index = $node->childNodes->length - 1; $index >= 0; --$index) {
                $child = $node->childNodes->item($index);
                if ($child instanceof \DOMElement) {
                    $stack[] = $child;
                }
            }
        }

        return null;
    }

    public static function attribute(\DOMElement $element, string $localName, ?string $namespace = null): ?string
    {
        if ($namespace !== null && $namespace !== '') {
            return $element->hasAttributeNS($namespace, $localName)
                ? $element->getAttributeNS($namespace, $localName)
                : null;
        }

        return $element->hasAttribute($localName) ? $element->getAttribute($localName) : null;
    }

    /**
     * @return array<string, mixed>
     */
    public static function summarizeXmlNamespaceUsage(\DOMDocument $dom, ?string $xmlSource = null): array
    {
        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement) {
            throw new \InvalidArgumentException('XML namespace review packet requires a document element');
        }

        $source = $xmlSource ?? ($dom->saveXML($root) ?: '');
        $namespaceScopeSummary = self::summarizeXmlNamespaceScopes($dom, $source);
        $sourceUsageSummary = self::xmlNamespaceSourceUsageSummary(
            $source,
            $xmlSource === null ? 'serialized-dom' : 'provided-source'
        );
        $elements = self::xmlElementsIncludingRoot($root);
        $elementUses = [];
        $attributeUses = [];
        $prefixUses = [];
        $uriUses = [];
        $namespaceUris = [];
        $defaultNamespaceUris = [];
        $defaultNamespaceUseCount = 0;
        $defaultNamespaceTransitions = [];
        $attributeCount = 0;
        $namespacedElementUseCount = 0;
        $unnamespacedElementUseCount = 0;
        $namespacedAttributeUseCount = 0;
        $unnamespacedAttributeUseCount = 0;

        foreach ($elements as $element) {
            $namespaceUri = self::xmlNamespaceUri($element->namespaceURI);
            if ($namespaceUri !== '') {
                $namespaceUris[$namespaceUri] = true;
                $namespacedElementUseCount++;
            } else {
                $unnamespacedElementUseCount++;
            }
            self::appendXmlNamespaceUse($elementUses, $element->localName, $namespaceUri, $element->tagName);
            $prefix = self::xmlNamespacePrefix($element->prefix, true);
            self::appendXmlNamespaceFrequencyUse($prefixUses, $prefix, $namespaceUri, $element->tagName, 'element');
            self::appendXmlNamespaceFrequencyUse($uriUses, $namespaceUri, $prefix, $element->tagName, 'element');
            if ($prefix === 'default' && $namespaceUri !== '') {
                $defaultNamespaceUris[$namespaceUri] = true;
                $defaultNamespaceUseCount++;
            }

            $parent = $element->parentNode instanceof \DOMElement ? $element->parentNode : null;
            $fromDefaultNamespace = $parent instanceof \DOMElement
                ? self::xmlNullableNamespaceUri($parent->lookupNamespaceURI(null))
                : null;
            $toDefaultNamespace = self::xmlNullableNamespaceUri($element->lookupNamespaceURI(null));
            if ($fromDefaultNamespace !== $toDefaultNamespace) {
                $defaultNamespaceTransitions[] = [
                    'path' => self::xmlElementUsagePath($element),
                    'element' => $element->tagName,
                    'fromNamespaceUri' => $fromDefaultNamespace,
                    'toNamespaceUri' => $toDefaultNamespace,
                ];
            }

            foreach ($element->attributes ?? [] as $attribute) {
                if (!$attribute instanceof \DOMAttr || self::isXmlNamespaceDeclarationAttribute($attribute)) {
                    continue;
                }

                $attributeCount++;
                $attributeNamespaceUri = self::xmlNamespaceUri($attribute->namespaceURI);
                if ($attributeNamespaceUri !== '') {
                    $namespaceUris[$attributeNamespaceUri] = true;
                    $namespacedAttributeUseCount++;
                } else {
                    $unnamespacedAttributeUseCount++;
                }
                self::appendXmlNamespaceUse(
                    $attributeUses,
                    $attribute->localName,
                    $attributeNamespaceUri,
                    $attribute->nodeName
                );
                $attributePrefix = self::xmlNamespacePrefix($attribute->prefix, false);
                self::appendXmlNamespaceFrequencyUse(
                    $prefixUses,
                    $attributePrefix,
                    $attributeNamespaceUri,
                    $attribute->nodeName,
                    'attribute'
                );
                self::appendXmlNamespaceFrequencyUse(
                    $uriUses,
                    $attributeNamespaceUri,
                    $attributePrefix,
                    $attribute->nodeName,
                    'attribute'
                );
            }
        }

        $namespaceUris = array_keys($namespaceUris);
        sort($namespaceUris, SORT_STRING);
        $defaultNamespaceUris = array_keys($defaultNamespaceUris);
        sort($defaultNamespaceUris, SORT_STRING);
        $prefixFrequencies = self::xmlNamespaceFrequencySummaries(
            $prefixUses,
            'prefix',
            'namespaceUris',
            'namespaceUriCount'
        );
        $prefixFrequencySummaries = self::xmlNamespaceFrequencySummaries(
            $prefixUses,
            'prefix',
            'namespaceUris',
            'namespaceUriCount',
            true
        );
        $uriFrequencies = self::xmlNamespaceFrequencySummaries(
            $uriUses,
            'namespaceUri',
            'prefixes',
            'prefixCount'
        );
        $uriFrequencySummaries = self::xmlNamespaceFrequencySummaries(
            $uriUses,
            'namespaceUri',
            'prefixes',
            'prefixCount',
            true
        );
        $sameUriMultiplePrefixes = self::xmlNamespaceUriAliasSummaries($uriFrequencies);
        $samePrefixMultipleUris = self::xmlNamespacePrefixAliasSummaries($prefixFrequencies);
        $elementNamespaceUsageSummaries = self::xmlNamespaceUseSummaries($elementUses);
        $attributeNamespaceUsageSummaries = self::xmlNamespaceUseSummaries($attributeUses);
        $elementNamespaceCollisions = self::xmlNamespaceCollisionSummaries($elementUses);
        $attributeNamespaceCollisions = self::xmlNamespaceCollisionSummaries($attributeUses);
        $defaultNamespaceTransitions = array_slice(
            $defaultNamespaceTransitions,
            0,
            self::XML_NAMESPACE_REVIEW_MAX_ITEMS
        );
        $directReaderDiagnostics = self::xmlDirectReaderDiagnostics(
            count($elementNamespaceCollisions),
            count($attributeNamespaceCollisions),
            count($defaultNamespaceTransitions),
            $defaultNamespaceUseCount,
            count($sameUriMultiplePrefixes),
            count($samePrefixMultipleUris),
            $sourceUsageSummary['unboundNamespacePrefixUseCount'],
            $sourceUsageSummary['unusedNamespaceDeclarationCount'],
            $sourceUsageSummary['reservedNamespaceUseCount']
        );

        return [
            'formatFamily' => 'xml-html5-generic-dom',
            'reviewPolicy' => 'xml-namespace-usage-diagnostics-review-only',
            'directReaderParity' => false,
            'namespaceReview' => 'xml-namespace-usage',
            'namespaceScopeReview' => $namespaceScopeSummary['namespaceReview'],
            'namespaceUsageSourceMode' => $sourceUsageSummary['sourceMode'],
            'directReaderDiagnosticCodes' => array_map(
                static fn (array $diagnostic): string => (string) $diagnostic['code'],
                $directReaderDiagnostics
            ),
            'directReaderDiagnosticCount' => count($directReaderDiagnostics),
            'directReaderDiagnostics' => $directReaderDiagnostics,
            'rootName' => $root->localName,
            'rootQualifiedName' => $root->tagName,
            'rootNamespaceUri' => self::xmlNullableNamespaceUri($root->namespaceURI),
            'elementCount' => count($elements),
            'attributeCount' => $attributeCount,
            'namespacedElementUseCount' => $namespacedElementUseCount,
            'unnamespacedElementUseCount' => $unnamespacedElementUseCount,
            'namespacedAttributeUseCount' => $namespacedAttributeUseCount,
            'unnamespacedAttributeUseCount' => $unnamespacedAttributeUseCount,
            'namespaceUris' => $namespaceUris,
            'namespaceUriCount' => count($namespaceUris),
            'declaredNamespacePrefixes' => $namespaceScopeSummary['namespacePrefixes'],
            'declaredNamespacePrefixCount' => $namespaceScopeSummary['namespacePrefixCount'],
            'declaredNamespaceUris' => $namespaceScopeSummary['namespaceUris'],
            'declaredNamespaceUriCount' => $namespaceScopeSummary['namespaceUriCount'],
            'namespaceDeclarationCount' => $namespaceScopeSummary['namespaceDeclarationCount'],
            'namespaceDeclarationLimit' => $namespaceScopeSummary['namespaceDeclarationLimit'],
            'namespaceDeclarationTruncated' => $namespaceScopeSummary['namespaceDeclarationTruncated'],
            'namespaceDeclarations' => $namespaceScopeSummary['namespaceDeclarations'],
            'defaultNamespaceDeclarationCount' => $namespaceScopeSummary['defaultNamespaceDeclarationCount'],
            'defaultNamespaceDeclarations' => $namespaceScopeSummary['defaultNamespaceDeclarations'],
            'namespaceScopeElementCount' => $namespaceScopeSummary['namespaceScopeElementCount'],
            'namespaceScopeLimit' => $namespaceScopeSummary['namespaceScopeLimit'],
            'namespaceScopeTruncated' => $namespaceScopeSummary['namespaceScopeTruncated'],
            'namespaceScopes' => $namespaceScopeSummary['namespaceScopes'],
            'defaultNamespaceScopeCount' => $namespaceScopeSummary['defaultNamespaceScopeCount'],
            'defaultNamespaceScopes' => $namespaceScopeSummary['defaultNamespaceScopes'],
            'prefixRedefinitionCount' => $namespaceScopeSummary['prefixRedefinitionCount'],
            'prefixRedefinitions' => $namespaceScopeSummary['prefixRedefinitions'],
            'duplicatePrefixSummaryCount' => $namespaceScopeSummary['duplicatePrefixSummaryCount'],
            'duplicatePrefixSummaries' => $namespaceScopeSummary['duplicatePrefixSummaries'],
            'duplicateUriSummaryCount' => $namespaceScopeSummary['duplicateUriSummaryCount'],
            'duplicateUriSummaries' => $namespaceScopeSummary['duplicateUriSummaries'],
            'reservedNamespaceDiagnosticCount' => $namespaceScopeSummary['reservedNamespaceDiagnosticCount'],
            'namespaceDiagnosticCount' => $namespaceScopeSummary['namespaceDiagnosticCount'],
            'namespaceDiagnosticCodes' => $namespaceScopeSummary['namespaceDiagnosticCodes'],
            'namespaceDiagnostics' => $namespaceScopeSummary['namespaceDiagnostics'],
            'elementNamespaceUsageSummaryCount' => count($elementNamespaceUsageSummaries),
            'elementNamespaceUsageSummaries' => $elementNamespaceUsageSummaries,
            'attributeNamespaceUsageSummaryCount' => count($attributeNamespaceUsageSummaries),
            'attributeNamespaceUsageSummaries' => $attributeNamespaceUsageSummaries,
            'unboundNamespacePrefixUseCount' => $sourceUsageSummary['unboundNamespacePrefixUseCount'],
            'unboundNamespacePrefixes' => $sourceUsageSummary['unboundNamespacePrefixes'],
            'unboundNamespacePrefixUses' => $sourceUsageSummary['unboundNamespacePrefixUses'],
            'unusedNamespaceDeclarationCount' => $sourceUsageSummary['unusedNamespaceDeclarationCount'],
            'unusedNamespaceDeclarations' => $sourceUsageSummary['unusedNamespaceDeclarations'],
            'reservedNamespaceUseCount' => $sourceUsageSummary['reservedNamespaceUseCount'],
            'reservedNamespaceUseCodes' => $sourceUsageSummary['reservedNamespaceUseCodes'],
            'reservedNamespaceUses' => $sourceUsageSummary['reservedNamespaceUses'],
            'namespacePrefixFrequencyCount' => count($prefixFrequencies),
            'namespacePrefixFrequencies' => $prefixFrequencies,
            'namespacePrefixFrequencySummaryCount' => count($prefixFrequencySummaries),
            'namespacePrefixFrequencySummaries' => $prefixFrequencySummaries,
            'namespaceUriFrequencyCount' => count($uriFrequencies),
            'namespaceUriFrequencies' => $uriFrequencies,
            'namespaceUriFrequencySummaryCount' => count($uriFrequencySummaries),
            'namespaceUriFrequencySummaries' => $uriFrequencySummaries,
            'defaultNamespaceUseCount' => $defaultNamespaceUseCount,
            'defaultNamespaceUris' => $defaultNamespaceUris,
            'defaultNamespaceUriCount' => count($defaultNamespaceUris),
            'sameUriMultiplePrefixCount' => count($sameUriMultiplePrefixes),
            'sameUriMultiplePrefixes' => $sameUriMultiplePrefixes,
            'samePrefixMultipleUriCount' => count($samePrefixMultipleUris),
            'samePrefixMultipleUris' => $samePrefixMultipleUris,
            'elementNamespaceCollisionCount' => count($elementNamespaceCollisions),
            'elementNamespaceCollisions' => $elementNamespaceCollisions,
            'attributeNamespaceCollisionCount' => count($attributeNamespaceCollisions),
            'attributeNamespaceCollisions' => $attributeNamespaceCollisions,
            'defaultNamespaceTransitionCount' => count($defaultNamespaceTransitions),
            'defaultNamespaceTransitions' => $defaultNamespaceTransitions,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    public static function summarizeXmlNamespaceSourceUsage(string $xmlSource): array
    {
        self::assertSafeSource($xmlSource, 'XML namespace source usage');
        self::assertNoDoctype($xmlSource, 'XML namespace source usage');

        return self::xmlNamespaceSourceUsageSummary($xmlSource, 'provided-source');
    }

    public static function fragmentRoot(\DOMDocument $dom): ?\DOMElement
    {
        foreach ($dom->getElementsByTagName('div') as $element) {
            if ($element instanceof \DOMElement && $element->getAttribute(self::FRAGMENT_ROOT_ATTRIBUTE) === '1') {
                return $element;
            }
        }

        return null;
    }

    /**
     * @return list<array<string, mixed>>
     */
    public static function summarizeHtmlFragment(\DOMDocument $dom): array
    {
        $root = self::requireFragmentRoot($dom);

        return self::summarizeChildNodes($root);
    }

    public static function serializeHtmlFragment(\DOMDocument $dom): string
    {
        $root = self::requireFragmentRoot($dom);

        return self::serializeHtmlChildren($root);
    }

    public static function serializeHtmlChildren(\DOMNode $node): string
    {
        if (self::shouldRepairOrphanHtmlTableChildren($node)) {
            return self::serializeHtmlChildrenWithTableRepair($node);
        }

        return self::serializeHtmlChildrenPlain($node);
    }

    public static function serializeHtmlNode(\DOMNode $node): string
    {
        return self::serializeNode($node);
    }

    private static function serializeHtmlChildrenPlain(\DOMNode $node): string
    {
        $html = '';

        foreach ($node->childNodes as $child) {
            $html .= self::serializeNode($child);
        }

        return $html;
    }

    public static function htmlElementName(\DOMElement $element): string
    {
        $name = strtolower($element->tagName);
        $foreignContext = self::htmlForeignContext($element);

        return $foreignContext !== null
            ? self::adjustHtmlForeignElementName($name, $foreignContext)
            : $name;
    }

    /**
     * @return array<string, string>
     */
    public static function htmlAttributes(\DOMElement $element): array
    {
        $attributes = [];
        $isForeignElement = self::isHtmlForeignElement($element);
        foreach ($element->attributes ?? [] as $attribute) {
            if (!$attribute instanceof \DOMAttr) {
                continue;
            }

            $name = strtolower($attribute->name);
            if ($name === self::FRAGMENT_ROOT_ATTRIBUTE) {
                continue;
            }
            if ($isForeignElement) {
                $name = self::adjustHtmlForeignAttributeName($name);
            }
            $attributes[$name] = $attribute->value;
        }
        ksort($attributes);

        return $attributes;
    }

    public static function adjustHtmlForeignElementName(string $lowercaseName, ?string $foreignContext = null): string
    {
        if ($foreignContext !== null && $foreignContext !== 'svg') {
            return $lowercaseName;
        }

        return self::HTML5_FOREIGN_ELEMENT_NAMES[$lowercaseName] ?? $lowercaseName;
    }

    public static function adjustHtmlForeignAttributeName(string $lowercaseName): string
    {
        return self::HTML5_FOREIGN_ATTRIBUTE_NAMES[$lowercaseName] ?? $lowercaseName;
    }

    public static function protectHtmlRcdataElements(
        string $html,
        bool $protectTemplateContent = false,
        bool $protectIframeContent = false,
        bool $protectRawTextContent = false,
        bool $protectNoscriptContent = false
    ): string
    {
        $offset = 0;
        $protected = '';
        $rawTextNames = 'script|style|xmp|noembed|noframes|title|textarea|plaintext'
            . ($protectNoscriptContent ? '|noscript' : '')
            . ($protectIframeContent ? '|iframe' : '')
            . ($protectTemplateContent ? '|template' : '');
        $pattern = '~<(?P<name>' . $rawTextNames . ')(?=[\s/>])(?:[^>"\']+|"[^"]*"|\'[^\']*\')*>~is';

        while (preg_match($pattern, $html, $matches, PREG_OFFSET_CAPTURE, $offset) === 1) {
            $startTag = (string) $matches[0][0];
            $startOffset = (int) $matches[0][1];
            $name = strtolower((string) $matches['name'][0]);
            $contentStart = $startOffset + strlen($startTag);

            $protected .= self::normalizeHtml5NamedCharacterReferences(
                self::protectHtmlCdataSections(substr($html, $offset, $startOffset - $offset))
            ) . $startTag;

            if ($name === 'title' && self::isHtmlTitleStartInSvgContext($html, $startOffset)) {
                $offset = $contentStart;
                continue;
            }

            if ($name === 'plaintext') {
                $protected .= self::escapeHtmlRawTextContent(substr($html, $contentStart)) . '</plaintext>';

                return $protected;
            }

            $endMatch = self::findHtmlRcdataEndTag($html, $name, $contentStart);
            if ($endMatch === null) {
                $protected .= self::protectHtmlRcdataElementContent($name, substr($html, $contentStart), $protectRawTextContent)
                    . '</' . $name . '>';

                return $protected;
            }

            [$endTag, $endOffset] = $endMatch;
            $content = substr($html, $contentStart, $endOffset - $contentStart);
            $protected .= self::protectHtmlRcdataElementContent($name, $content, $protectRawTextContent);
            $protected .= $endTag;
            $offset = $endOffset + strlen($endTag);
        }

        return $protected . self::normalizeHtml5NamedCharacterReferences(
            self::protectHtmlCdataSections(substr($html, $offset))
        );
    }

    /**
     * @return array{0:string, 1:int}|null
     */
    private static function findHtmlRcdataEndTag(string $html, string $name, int $contentStart): ?array
    {
        if ($name === 'template') {
            return self::findHtmlTemplateEndTag($html, $contentStart);
        }

        return self::findHtmlElementEndTag($html, $name, $contentStart);
    }

    /**
     * @return array{0:string, 1:int}|null
     */
    private static function findHtmlElementEndTag(string $html, string $name, int $contentStart): ?array
    {
        $endPattern = '~</\s*' . preg_quote($name, '~') . '\s*>~i';
        if (preg_match($endPattern, $html, $endMatches, PREG_OFFSET_CAPTURE, $contentStart) !== 1) {
            return null;
        }

        return [(string) $endMatches[0][0], (int) $endMatches[0][1]];
    }

    /**
     * @return array{0:string, 1:int}|null
     */
    private static function findHtmlTemplateEndTag(string $html, int $contentStart): ?array
    {
        $offset = $contentStart;
        $depth = 1;
        $tagPattern = '~<(?P<closing>/?)\s*(?P<name>[A-Za-z][A-Za-z0-9:-]*)(?=[\s/>])(?:[^>"\']+|"[^"]*"|\'[^\']*\')*>~is';

        while (($tagStart = strpos($html, '<', $offset)) !== false) {
            if (str_starts_with(substr($html, $tagStart, 4), '<!--')) {
                $commentEnd = strpos($html, '-->', $tagStart + 4);
                if ($commentEnd === false) {
                    return null;
                }
                $offset = $commentEnd + 3;
                continue;
            }

            if (str_starts_with(strtolower(substr($html, $tagStart, 9)), '<![cdata[')) {
                $cdataEnd = strpos($html, ']]>', $tagStart + 9);
                if ($cdataEnd === false) {
                    return null;
                }
                $offset = $cdataEnd + 3;
                continue;
            }

            if (str_starts_with(substr($html, $tagStart, 2), '<!') || str_starts_with(substr($html, $tagStart, 2), '<?')) {
                $declarationEnd = strpos($html, '>', $tagStart + 2);
                if ($declarationEnd === false) {
                    return null;
                }
                $offset = $declarationEnd + 1;
                continue;
            }

            if (preg_match($tagPattern, $html, $matches, PREG_OFFSET_CAPTURE, $tagStart) !== 1 || (int) $matches[0][1] !== $tagStart) {
                $offset = $tagStart + 1;
                continue;
            }

            $tag = (string) $matches[0][0];
            $isClosing = (string) $matches['closing'][0] === '/';
            $tagName = strtolower((string) $matches['name'][0]);

            if (!$isClosing && self::isHtmlTemplateRawTextBoundaryElement($tagName)) {
                if ($tagName === 'title' && self::isHtmlTitleStartInSvgContext($html, $tagStart)) {
                    $offset = $tagStart + strlen($tag);
                    continue;
                }

                if ($tagName === 'plaintext') {
                    return null;
                }

                $rawTextEnd = self::findHtmlElementEndTag($html, $tagName, $tagStart + strlen($tag));
                if ($rawTextEnd === null) {
                    return null;
                }

                $offset = $rawTextEnd[1] + strlen($rawTextEnd[0]);
                continue;
            }

            if ($tagName === 'template') {
                if ($isClosing) {
                    --$depth;
                    if ($depth === 0) {
                        return [$tag, $tagStart];
                    }
                } else {
                    ++$depth;
                }
            }

            $offset = $tagStart + strlen($tag);
        }

        return null;
    }

    private static function isHtmlTemplateRawTextBoundaryElement(string $tagName): bool
    {
        return in_array($tagName, ['script', 'style', 'xmp', 'noembed', 'noframes', 'title', 'textarea', 'plaintext', 'noscript', 'iframe'], true);
    }

    /**
     * @return list<array<string, int|string|bool>>
     */
    public static function htmlRawTextBoundaryDiagnostics(string $html): array
    {
        $offset = 0;
        $diagnostics = [];
        $rawTextNames = 'script|style|xmp|noembed|noframes|title|textarea|plaintext|noscript|iframe|template';
        $pattern = '~<(?P<name>' . $rawTextNames . ')(?=[\s/>])(?:[^>"\']+|"[^"]*"|\'[^\']*\')*>~is';

        while (preg_match($pattern, $html, $matches, PREG_OFFSET_CAPTURE, $offset) === 1) {
            $startTag = (string) $matches[0][0];
            $startOffset = (int) $matches[0][1];
            $name = strtolower((string) $matches['name'][0]);
            $contentStart = $startOffset + strlen($startTag);

            if ($name === 'title' && self::isHtmlTitleStartInSvgContext($html, $startOffset)) {
                $offset = $contentStart;
                continue;
            }

            if ($name === 'plaintext') {
                $content = substr($html, $contentStart);
                $diagnostic = self::htmlRawTextBoundaryDiagnostic(
                    'plaintext-boundary',
                    $name,
                    'plaintext',
                    'plaintext-consumes-fragment-tail',
                    'fragment-eof',
                    $html,
                    $startOffset,
                    strlen($content)
                );
                if (preg_match('~</\s*plaintext\s*>~i', $content) === 1) {
                    $diagnostic['ignoredEndTag'] = true;
                }
                $diagnostics[] = $diagnostic;

                return $diagnostics;
            }

            $endMatch = self::findHtmlRcdataEndTag($html, $name, $contentStart);
            if ($endMatch === null) {
                $diagnostics[] = self::htmlRawTextBoundaryDiagnostic(
                    'raw-text-boundary',
                    $name,
                    self::htmlRawTextBoundaryKind($name),
                    'missing-end-tag-synthesized',
                    'synthetic-eof',
                    $html,
                    $startOffset,
                    strlen(substr($html, $contentStart))
                );

                return $diagnostics;
            }

            [$endTag, $endOffset] = $endMatch;
            $offset = $endOffset + strlen($endTag);
        }

        return $diagnostics;
    }

    /**
     * @return array<string, int|string|bool>
     */
    private static function htmlRawTextBoundaryDiagnostic(
        string $code,
        string $name,
        string $kind,
        string $reason,
        string $closedBy,
        string $source,
        int $startOffset,
        int $contentBytes
    ): array {
        [$line, $column] = self::sourceLineColumn($source, $startOffset);

        return [
            'code' => $code,
            'tag' => $name,
            'kind' => $kind,
            'reason' => $reason,
            'closedBy' => $closedBy,
            'syntheticEndTag' => '</' . $name . '>',
            'contentBytes' => $contentBytes,
            'line' => $line,
            'column' => $column,
        ];
    }

    private static function htmlRawTextBoundaryKind(string $name): string
    {
        if (in_array($name, ['title', 'textarea'], true)) {
            return 'rcdata';
        }
        if (in_array($name, ['template', 'iframe', 'noscript'], true)) {
            return 'inert-raw-text';
        }

        return 'raw-text';
    }

    /**
     * @return array{0:int, 1:int}
     */
    private static function sourceLineColumn(string $source, int $offset): array
    {
        $prefix = substr($source, 0, $offset);
        $line = substr_count($prefix, "\n") + 1;
        $lastNewline = strrpos($prefix, "\n");
        $column = $lastNewline === false ? $offset + 1 : $offset - $lastNewline;

        return [$line, $column];
    }

    private static function protectHtmlRcdataElementContent(string $name, string $content, bool $protectRawTextContent = false): string
    {
        if (in_array($name, ['script', 'style'], true)) {
            return $protectRawTextContent ? self::escapeHtmlRawTextContent($content) : $content;
        }

        if (in_array($name, ['title', 'textarea'], true)) {
            return self::escapeHtmlRcdataContent(self::normalizeHtml5NamedCharacterReferences($content));
        }

        return self::escapeHtmlRawTextContent($content);
    }

    private static function isHtmlTitleStartInSvgContext(string $html, int $startOffset): bool
    {
        $prefix = substr($html, 0, $startOffset);
        if ($prefix === '') {
            return false;
        }

        $tagCount = preg_match_all(
            '~<\s*(/?)\s*([A-Za-z][A-Za-z0-9:-]*)(?=[\s/>])(?:[^>"\']+|"[^"]*"|\'[^\']*\')*>~is',
            $prefix,
            $matches,
            PREG_SET_ORDER
        );
        if ($tagCount === false || $tagCount === 0) {
            return false;
        }

        $stack = [];
        foreach ($matches as $match) {
            $fullTag = (string) $match[0];
            $isClosing = (string) $match[1] === '/';
            $name = strtolower((string) $match[2]);
            $name = str_contains($name, ':') ? substr($name, (int) strrpos($name, ':') + 1) : $name;

            if ($isClosing) {
                for ($index = count($stack) - 1; $index >= 0; --$index) {
                    if ($stack[$index] === $name) {
                        array_splice($stack, $index, 1);
                        break;
                    }
                }
                continue;
            }

            if (str_ends_with(rtrim($fullTag), '/>') || isset(self::HTML5_VOID_ELEMENTS[$name])) {
                continue;
            }

            $stack[] = $name;
        }

        $lastSvgIndex = null;
        for ($index = count($stack) - 1; $index >= 0; --$index) {
            if ($stack[$index] === 'svg') {
                $lastSvgIndex = $index;
                break;
            }
        }

        if ($lastSvgIndex === null) {
            return false;
        }

        $htmlIntegrationAncestors = ['foreignobject' => true, 'desc' => true, 'title' => true];
        foreach (array_slice($stack, $lastSvgIndex + 1) as $ancestor) {
            if (isset($htmlIntegrationAncestors[$ancestor])) {
                return false;
            }
        }

        return true;
    }

    public static function normalizedText(\DOMNode $node): string
    {
        $text = preg_replace('/[ \t\r\n\f]+/u', ' ', $node->textContent) ?? $node->textContent;

        return trim($text);
    }

    /**
     * @return array<string, mixed>
     */
    public static function summarizeXmlNamespaceDeclarations(\DOMDocument $dom): array
    {
        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement) {
            throw new \InvalidArgumentException('XML namespace declaration review packet requires a document element');
        }

        $declarations = [];
        $declarationKeys = [];
        $namespaceXPath = new \DOMXPath($dom);
        $elementCount = 0;
        $namespacedElementCount = 0;
        $namespacedAttributeCount = 0;
        $maxDepth = 0;

        foreach (self::xmlElementWalk($root) as $entry) {
            $element = $entry['element'];
            $path = $entry['path'];
            $depth = $entry['depth'];
            ++$elementCount;
            $maxDepth = max($maxDepth, $depth);

            if (($element->namespaceURI ?? '') !== '') {
                ++$namespacedElementCount;
            }

            $namespaceNodes = $namespaceXPath->query('namespace::*', $element);
            if ($namespaceNodes !== false) {
                foreach ($namespaceNodes as $namespaceNode) {
                    self::recordXmlNamespaceDeclaration(
                        $declarations,
                        $declarationKeys,
                        self::xmlNamespaceNodePrefix($namespaceNode),
                        (string) $namespaceNode->nodeValue,
                        $path,
                        $depth,
                        'namespace-axis'
                    );
                }
            }

            foreach ($element->attributes ?? [] as $attribute) {
                if (!$attribute instanceof \DOMAttr) {
                    continue;
                }

                if (self::isXmlNamespaceDeclaration($attribute)) {
                    continue;
                }

                if (($attribute->namespaceURI ?? '') !== '') {
                    ++$namespacedAttributeCount;
                }
            }
        }

        self::sortXmlNamespaceDeclarations($declarations);
        $byPrefix = self::xmlNamespaceDeclarationSummaryByPrefix($declarations);
        $prefixReuses = [];
        $prefixConflicts = [];

        foreach ($byPrefix as $summary) {
            if ($summary['declarationCount'] > 1) {
                $prefixReuses[] = $summary;
            }
            if (count($summary['namespaceUris']) > 1) {
                $prefixConflicts[] = $summary;
            }
        }

        $namespaceUris = self::xmlNamespaceUris($declarations);
        $directReaderDiagnostics = self::xmlNamespaceDirectReaderDiagnostics(
            count($declarations),
            count($prefixReuses),
            count($prefixConflicts)
        );

        return [
            'formatFamily' => 'xml-html5-jats-dom',
            'format' => 'xml',
            'reviewPolicy' => 'xml-namespace-declaration-review-only',
            'directReaderParity' => false,
            'directReaderDiagnosticCodes' => array_map(
                static fn (array $diagnostic): string => (string) $diagnostic['code'],
                $directReaderDiagnostics
            ),
            'directReaderDiagnosticCount' => count($directReaderDiagnostics),
            'directReaderDiagnostics' => $directReaderDiagnostics,
            'rootName' => $root->localName,
            'rootQualifiedName' => self::xmlQualifiedName($root),
            'rootNamespacePrefix' => $root->prefix === '' ? null : $root->prefix,
            'rootNamespaceUri' => $root->namespaceURI === '' ? null : $root->namespaceURI,
            'elementCount' => $elementCount,
            'maxDepth' => $maxDepth,
            'namespacedElementCount' => $namespacedElementCount,
            'namespacedAttributeCount' => $namespacedAttributeCount,
            'namespaceDeclarationCount' => count($declarations),
            'namespacePrefixCount' => count($byPrefix),
            'namespaceUriCount' => count($namespaceUris),
            'namespaceUris' => $namespaceUris,
            'namespacePrefixes' => array_keys($byPrefix),
            'namespaceDeclarations' => $declarations,
            'namespaceDeclarationsByPrefix' => $byPrefix,
            'namespacePrefixReuses' => $prefixReuses,
            'namespacePrefixReuseCount' => count($prefixReuses),
            'namespacePrefixConflicts' => $prefixConflicts,
            'namespacePrefixConflictCount' => count($prefixConflicts),
            'hasNamespacePrefixConflicts' => $prefixConflicts !== [],
        ];
    }

    /**
     * @return array<string, mixed>
     */
    public static function summarizeXmlNamespaceScopes(\DOMDocument $dom, ?string $xmlSource = null): array
    {
        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement) {
            throw new \InvalidArgumentException('XML namespace scope review requires a document element');
        }

        $source = $xmlSource ?? ($dom->saveXML($root) ?: '');
        $declarations = self::xmlNamespaceDeclarationRecords($source);
        $elements = self::xmlElementList($root);
        $knownPrefixes = self::xmlNamespaceKnownPrefixes($elements, $declarations);
        $scopes = [];
        $defaultScopes = [];

        foreach ($elements as $element) {
            $scope = self::xmlNamespaceScopeForElement($element, $knownPrefixes);
            if (count($scopes) < self::XML_NAMESPACE_SCOPE_MAX_ELEMENTS) {
                $scopes[] = $scope;
            }

            if ($scope['defaultNamespaceUri'] !== null && count($defaultScopes) < self::XML_NAMESPACE_SCOPE_MAX_ELEMENTS) {
                $defaultScopes[] = [
                    'elementPath' => $scope['elementPath'],
                    'elementName' => $scope['elementName'],
                    'uri' => $scope['defaultNamespaceUri'],
                ];
            }
        }

        $collisionSummary = self::xmlNamespaceCollisionSummary($declarations);
        $diagnostics = self::xmlNamespaceDiagnostics($collisionSummary, $declarations);
        $namespaceUris = [];
        foreach ($declarations as $declaration) {
            if ($declaration['uri'] !== '') {
                $namespaceUris[$declaration['uri']] = true;
            }
        }
        ksort($namespaceUris);

        $defaultDeclarations = array_values(array_filter(
            $declarations,
            static fn (array $declaration): bool => (bool) $declaration['default']
        ));

        return [
            'namespaceReview' => 'xml-namespace-scope',
            'directReaderParity' => false,
            'sourceMode' => $xmlSource === null ? 'serialized-dom' : 'provided-source',
            'rootName' => $root->tagName,
            'rootNamespaceUri' => $root->namespaceURI !== '' ? $root->namespaceURI : null,
            'namespacePrefixes' => $knownPrefixes,
            'namespacePrefixCount' => count($knownPrefixes),
            'namespaceUris' => array_keys($namespaceUris),
            'namespaceUriCount' => count($namespaceUris),
            'namespaceDeclarationCount' => count($declarations),
            'namespaceDeclarationLimit' => self::XML_NAMESPACE_DECLARATION_MAX_RECORDS,
            'namespaceDeclarationTruncated' => count($declarations) > self::XML_NAMESPACE_DECLARATION_MAX_RECORDS,
            'namespaceDeclarations' => array_slice($declarations, 0, self::XML_NAMESPACE_DECLARATION_MAX_RECORDS),
            'defaultNamespaceDeclarationCount' => count($defaultDeclarations),
            'defaultNamespaceDeclarations' => array_slice($defaultDeclarations, 0, self::XML_NAMESPACE_DECLARATION_MAX_RECORDS),
            'namespaceScopeElementCount' => count($elements),
            'namespaceScopeLimit' => self::XML_NAMESPACE_SCOPE_MAX_ELEMENTS,
            'namespaceScopeTruncated' => count($elements) > self::XML_NAMESPACE_SCOPE_MAX_ELEMENTS,
            'namespaceScopes' => $scopes,
            'defaultNamespaceScopeCount' => count($defaultScopes),
            'defaultNamespaceScopes' => $defaultScopes,
            'prefixRedefinitionCount' => $collisionSummary['prefixRedefinitionCount'],
            'prefixRedefinitions' => $collisionSummary['prefixRedefinitions'],
            'duplicatePrefixSummaryCount' => $collisionSummary['duplicatePrefixSummaryCount'],
            'duplicatePrefixSummaries' => $collisionSummary['duplicatePrefixSummaries'],
            'duplicateUriSummaryCount' => $collisionSummary['duplicateUriSummaryCount'],
            'duplicateUriSummaries' => $collisionSummary['duplicateUriSummaries'],
            'reservedNamespaceDiagnosticCount' => count(array_filter(
                $diagnostics,
                static fn (array $diagnostic): bool => str_starts_with((string) $diagnostic['code'], 'reserved-')
            )),
            'namespaceDiagnosticCount' => count($diagnostics),
            'namespaceDiagnosticCodes' => array_values(array_map(
                static fn (array $diagnostic): string => (string) $diagnostic['code'],
                $diagnostics
            )),
            'namespaceDiagnostics' => $diagnostics,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    public static function summarizeJatsFrontMatter(\DOMDocument $dom, string $format = 'jats'): array
    {
        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement) {
            throw new \InvalidArgumentException('JATS/BITS review packet requires a document element');
        }

        $format = strtolower(trim($format));
        if (!in_array($format, ['jats', 'bits'], true)) {
            throw new \InvalidArgumentException('JATS/BITS review packet format must be jats or bits');
        }

        $rootName = $root->localName;
        if (!in_array($rootName, ['article', 'book', 'book-part'], true)) {
            throw new \InvalidArgumentException('JATS/BITS review packet root must be article, book, or book-part');
        }

        $metadata = self::jatsMetadataElement($root);
        $body = self::jatsBodyElement($root);
        $backMatter = self::jatsBackMatterElement($root);

        $articleIds = $metadata instanceof \DOMElement
            ? self::jatsTypedTextRecords($metadata, ['article-id'], ['pub-id-type'])
            : [];
        $bookIds = $metadata instanceof \DOMElement
            ? self::jatsTypedTextRecords($metadata, ['book-id'], ['book-id-type', 'pub-id-type'])
            : [];
        $titleMetadata = $metadata instanceof \DOMElement
            ? self::jatsFirstTextRecord($metadata, ['article-title', 'book-title', 'title'])
            : null;
        $subtitleMetadata = $metadata instanceof \DOMElement
            ? self::jatsFirstTextRecord($metadata, ['subtitle'])
            : null;
        $abstracts = $metadata instanceof \DOMElement ? self::jatsAbstractSummaries($metadata) : [];
        $keywordGroups = $metadata instanceof \DOMElement ? self::jatsKeywordGroupSummaries($metadata) : [];
        $contributors = $metadata instanceof \DOMElement ? self::jatsContributorSummaries($metadata) : [];
        $dates = $metadata instanceof \DOMElement ? self::jatsPublicationDateSummaries($metadata) : [];
        $publicationMetadata = self::jatsPublicationMetadataSummary($root, $metadata);
        $sections = $body instanceof \DOMElement ? self::jatsSectionSummaries($body) : [];
        $sectionTitlePaths = array_values(array_filter(
            array_map(static fn (array $section): array => $section['titlePath'], $sections),
            static fn (array $path): bool => $path !== []
        ));
        $sectionMetadataDiagnostics = self::jatsSectionMetadataDiagnostics($sections);
        $bookParts = self::jatsBookPartSummaries($root);
        $elementIdMap = self::jatsElementIdMap($root);
        $xrefs = self::jatsXrefSummaries($root, $elementIdMap);
        $bodyXrefs = $body instanceof \DOMElement ? self::jatsXrefSummaries($body, $elementIdMap) : [];
        $xrefTargets = self::jatsXrefTargetsFromSummaries($xrefs);
        $referenceBackMatter = self::jatsReferenceBackMatterSummary($root, $xrefs);
        $referenceIds = $referenceBackMatter['referenceIds'];
        $fundingReview = self::jatsFundingReviewSummary($root, $referenceBackMatter);
        $acknowledgments = self::jatsAcknowledgmentSummaries($root, $referenceIds);
        $figureIds = self::jatsElementIds($root, 'fig');
        $tableWrapIds = self::jatsElementIds($root, 'table-wrap');
        $rootProvenance = self::xmlRootProvenance($root);
        $backMatterReferenceLists = $backMatter instanceof \DOMElement ? self::jatsReferenceListSummaries($backMatter) : [];
        $backMatterReferences = $backMatter instanceof \DOMElement ? self::jatsBackMatterReferenceSummaries($backMatter) : [];
        $backMatterReferenceIds = self::jatsFlattenUniqueStringField($backMatterReferences, 'id');
        $inlineXrefDiagnostics = self::jatsInlineXrefDiagnostics($root, $backMatterReferenceIds, $elementIdMap);
        $inlineXrefLocalReferenceIds = self::jatsFlattenUniqueStringField($inlineXrefDiagnostics, 'localBackReferenceIds');
        $inlineXrefUnsupportedTargetIds = [];
        foreach ($inlineXrefDiagnostics as $diagnostic) {
            foreach ($diagnostic['unsupportedTargets'] as $unsupportedTarget) {
                if (is_array($unsupportedTarget) && isset($unsupportedTarget['id']) && is_string($unsupportedTarget['id'])) {
                    $inlineXrefUnsupportedTargetIds[] = $unsupportedTarget['id'];
                }
            }
        }
        $inlineXrefUnsupportedTargetIds = self::jatsUniqueNonEmptyStrings($inlineXrefUnsupportedTargetIds);
        $citationXrefs = self::jatsCitationXrefSummaries(
            $root,
            $backMatterReferenceIds !== [] ? $backMatterReferenceIds : $referenceIds
        );
        $citationTargetIds = self::jatsFlattenUniqueStringField($citationXrefs, 'targets');
        $resolvedCitationReferenceIds = self::jatsFlattenUniqueStringField($citationXrefs, 'resolvedReferenceIds');
        $missingCitationReferenceIds = self::jatsFlattenUniqueStringField($citationXrefs, 'missingReferenceIds');
        $figures = self::jatsFigureSummaries($root, $xrefs);
        $figurePermissionSummaries = self::jatsFigurePermissionSummaries($figures);
        $figurePermissionIssues = self::jatsFigurePermissionIssues($figurePermissionSummaries);
        $figurePermissionLicenseTargets = self::jatsFigurePermissionLicenseTargets($figurePermissionSummaries);
        $figurePermissionLicenseTargetIssues = self::jatsFigurePermissionLicenseTargetIssues($figurePermissionIssues);
        $figureMediaTargets = self::jatsFigureMediaTargets($figurePermissionSummaries);
        $figureMetadataCounts = self::jatsFigureMetadataCounts($figures);
        $duplicateFigureLabels = self::jatsDuplicateFigureLabels($figures);
        $figureMetadataIssues = self::jatsFigureMetadataIssues($figures, $duplicateFigureLabels);
        $figureMetadataIssueCodes = self::jatsFigureIssueCodes($figureMetadataIssues);
        $figureDuplicateLabelCount = self::jatsFigureIssueCount($figureMetadataIssues, 'duplicate-label');
        $figureXrefLinks = self::jatsFigureXrefLinks($root, $figureIds);
        $figureXrefTargetIds = self::jatsFigureXrefTargetIds($figureXrefLinks);
        $figureMediaReferences = self::jatsFigureMediaReferenceList($figures);
        $figureMediaIssueCodes = self::jatsFigureMediaIssueCodes($figureMediaReferences);
        $figureMediaMissingTargetCount = self::jatsFigureMediaIssueCount($figureMediaReferences, 'missing-target');
        $figureMediaExternalReferenceCount = self::jatsFigureMediaIssueCount($figureMediaReferences, 'unsupported-external-reference');
        $tableWraps = self::jatsTableWrapSummaries($root, $xrefs);
        $tableBodyCount = array_sum(array_map(static fn (array $tableWrap): int => (int) $tableWrap['tbodyCount'], $tableWraps));
        $tableBodyRowCount = array_sum(array_map(static fn (array $tableWrap): int => (int) $tableWrap['bodyRowCount'], $tableWraps));
        $tableBodyCellCount = array_sum(array_map(static fn (array $tableWrap): int => (int) $tableWrap['bodyCellCount'], $tableWraps));
        $bookPartCount = count($bookParts);
        $relationshipDiagnostics = self::jatsRelationshipDiagnostics($root);
        $directBodySectionCount = $body instanceof \DOMElement
            ? count(self::childElements($body, 'sec'))
            : 0;
        $directReaderDiagnostics = self::jatsDirectReaderDiagnostics(
            $format,
            $rootProvenance,
            $body instanceof \DOMElement,
            $directBodySectionCount,
            (int) $referenceBackMatter['referenceCount'],
            (int) $fundingReview['fundingGroupCount'],
            (int) $fundingReview['awardGroupCount'],
            count($acknowledgments),
            count($figureIds),
            $figureMetadataCounts['withLabel'],
            $figureMetadataCounts['withCaption'],
            $figureMetadataCounts['withTitle'],
            $figureMetadataCounts['missingLabel'],
            $figureMetadataCounts['missingCaption'],
            $figureMetadataCounts['missingTitle'],
            $figureDuplicateLabelCount,
            count($figureMediaReferences),
            $figureMediaMissingTargetCount,
            $figureMediaExternalReferenceCount,
            count($tableWrapIds),
            $bookPartCount,
            (int) $referenceBackMatter['refListCount'],
            (int) $referenceBackMatter['resolvedBibrXrefCount'],
            (int) $referenceBackMatter['unresolvedBibrXrefCount'],
            (int) $referenceBackMatter['unreferencedReferenceCount'],
            (int) $referenceBackMatter['referenceMetadataSummaryCount'],
            (int) $referenceBackMatter['safeReferenceLabelCount'],
            (int) $referenceBackMatter['safeReferenceAuthorCount'],
            (int) $referenceBackMatter['safeReferenceDateCount'],
            (int) $referenceBackMatter['safeReferenceYearCount'],
            (int) $referenceBackMatter['referenceIdentifierCount'],
            (int) $referenceBackMatter['referenceIdentifierSourceSummaryCount'],
            (int) $referenceBackMatter['resolvedBibrIdentifierTargetCount'],
            (int) $referenceBackMatter['duplicateReferenceIdentifierCount'],
            (int) $referenceBackMatter['referencesMissingIdentifierCount'],
            (int) $referenceBackMatter['blockedCitationTextPayloadCount'],
            count($sectionMetadataDiagnostics)
        );
        $namespaceSummary = self::summarizeXmlNamespaceScopes($dom);

        return [
            'formatFamily' => 'xml-html5-jats-dom',
            'format' => $format,
            'reviewPolicy' => 'jats-bits-front-matter-and-body-diagnostics-review-only',
            'payloadBytesExposed' => false,
            'directReaderParity' => false,
            'directReaderParityStatus' => 'unsupported',
            'unsupportedDirectReaderReason' => 'bounded-review-packet-only',
            'unsupportedDirectReaderDetail' => 'Bounded XML/JATS/BITS review diagnostics are available, but full Pandoc direct reader parity is not implemented.',
            'directReaderDiagnosticCodes' => array_map(
                static fn (array $diagnostic): string => (string) $diagnostic['code'],
                $directReaderDiagnostics
            ),
            'directReaderDiagnosticCount' => count($directReaderDiagnostics),
            'directReaderDiagnostics' => $directReaderDiagnostics,
            'namespaceReview' => 'xml-namespace-scope',
            'namespaceDeclarationCount' => $namespaceSummary['namespaceDeclarationCount'],
            'namespaceScopeElementCount' => $namespaceSummary['namespaceScopeElementCount'],
            'defaultNamespaceScopeCount' => $namespaceSummary['defaultNamespaceScopeCount'],
            'prefixRedefinitionCount' => $namespaceSummary['prefixRedefinitionCount'],
            'duplicatePrefixSummaryCount' => $namespaceSummary['duplicatePrefixSummaryCount'],
            'duplicateUriSummaryCount' => $namespaceSummary['duplicateUriSummaryCount'],
            'reservedNamespaceDiagnosticCount' => $namespaceSummary['reservedNamespaceDiagnosticCount'],
            'namespaceDiagnosticCodes' => $namespaceSummary['namespaceDiagnosticCodes'],
            'namespaceDiagnosticCount' => $namespaceSummary['namespaceDiagnosticCount'],
            'namespaceSummary' => $namespaceSummary,
            'rootName' => $rootName,
            'rootAttributes' => self::xmlAttributeMap($root),
            'rootProvenance' => $rootProvenance,
            'documentType' => self::jatsDocumentType($root),
            'dtdVersion' => self::attribute($root, 'dtd-version'),
            'language' => self::attribute($root, 'lang', self::XML_NAMESPACE)
                ?? self::attribute($root, 'lang'),
            'metadataRoot' => $metadata instanceof \DOMElement ? $metadata->localName : null,
            'hasFrontMatter' => $metadata instanceof \DOMElement,
            'title' => $titleMetadata['text'] ?? null,
            'titleMetadata' => $titleMetadata,
            'subtitle' => $subtitleMetadata['text'] ?? null,
            'subtitleMetadata' => $subtitleMetadata,
            'journalTitle' => self::jatsFirstText($root, ['journal-title']),
            'publisherName' => self::jatsFirstText($root, ['publisher-name']),
            'articleIds' => $articleIds,
            'bookIds' => $bookIds,
            'identifierCount' => count($articleIds) + count($bookIds),
            'publicationMetadataReviewPolicy' => 'jats-bits-publication-metadata-review-only',
            'publicationMetadata' => $publicationMetadata,
            'publicationMetadataMappedCaseKinds' => $publicationMetadata['mappedCaseKinds'],
            'publicationMetadataMappedCaseCount' => $publicationMetadata['mappedCaseCount'],
            'publicationMetadataDiagnosticCodes' => $publicationMetadata['diagnosticCodes'],
