            'relationshipDiagnostics' => $relationshipDiagnostics,
            'relationshipDiagnosticCount' => $relationshipDiagnostics['diagnosticCount'],
            'unresolvedXrefTargetCount' => $relationshipDiagnostics['unresolvedXrefTargetCount'],
