    /**
     * @param array<string, mixed> $rootProvenance
     * @return list<array{code:string, severity:string, message:string, directReaderParity:bool, coveredByPacket:bool, details:array<string, mixed>}>
     */
    private static function jatsDirectReaderDiagnostics(
        string $format,
        array $rootProvenance,
        bool $hasBody,
        int $sectionCount,
        int $referenceCount,
        int $fundingGroupCount,
        int $awardGroupCount,
        int $acknowledgmentCount,
        int $figureCount,
        int $figureWithLabelCount,
        int $figureWithCaptionCount,
        int $figureWithTitleCount,
        int $figureMissingLabelCount,
        int $figureMissingCaptionCount,
        int $figureMissingTitleCount,
        int $figureDuplicateLabelCount,
        int $figureMediaReferenceCount,
        int $figureMediaMissingTargetCount,
        int $figureMediaExternalReferenceCount,
        int $tableWrapCount,
        int $bookPartCount,
        int $refListCount,
        int $resolvedBibrXrefCount,
        int $unresolvedBibrXrefCount,
        int $unreferencedReferenceCount,
        int $referenceMetadataSummaryCount,
        int $safeReferenceLabelCount,
        int $safeReferenceAuthorCount,
        int $safeReferenceDateCount,
        int $safeReferenceYearCount,
        int $referenceIdentifierCount,
        int $referenceIdentifierSourceSummaryCount,
        int $resolvedBibrIdentifierTargetCount,
        int $duplicateReferenceIdentifierCount,
        int $referencesMissingIdentifierCount,
        int $blockedCitationTextPayloadCount,
        int $sectionMetadataDiagnosticCount
    ): array {
        $formatLabel = strtoupper($format);
        $diagnostics = [
            self::jatsDirectReaderDiagnostic(
                'direct-reader-unsupported',
                'unsupported',
                $formatLabel . ' direct reader parity is not implemented; this packet exposes bounded XML diagnostics only.',
                false,
                true,
                [
                    'format' => $format,
                    'rootName' => $rootProvenance['name'],
                    'rootQualifiedName' => $rootProvenance['qualifiedName'],
                    'rootNamespaceUri' => $rootProvenance['namespaceUri'],
                    'rootPrefix' => $rootProvenance['prefix'],
                    'rootId' => $rootProvenance['id'],
                    'rootXmlId' => $rootProvenance['xmlId'],
                    'rootLanguage' => $rootProvenance['language'],
                    'rootAttributeCount' => $rootProvenance['attributeCount'],
                    'rootAttributeNames' => $rootProvenance['attributeNames'],
                    'rootAttributes' => $rootProvenance['attributes'],
                ]
            ),
        ];

        if (!$hasBody) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'body-missing',
                'warning',
                'No JATS/BITS body element was found for bounded body diagnostics.',
                false,
                true
            );
        } elseif ($sectionCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'body-sections-review-only',
                'unsupported',
                'Body sections are inventoried for review but are not mapped as a full Pandoc direct reader AST.',
                false,
                false,
                ['sectionCount' => $sectionCount]
            );
        }

        if ($referenceCount > 0 || $refListCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'references-review-only',
                'unsupported',
                'Reference elements are inventoried for review but are not mapped as full citation-reader output.',
                false,
                false,
                [
                    'referenceCount' => $referenceCount,
                    'refListCount' => $refListCount,
                    'resolvedBibrXrefCount' => $resolvedBibrXrefCount,
                    'unresolvedBibrXrefCount' => $unresolvedBibrXrefCount,
                    'unreferencedReferenceCount' => $unreferencedReferenceCount,
                    'referenceMetadataSummaryCount' => $referenceMetadataSummaryCount,
                    'safeReferenceLabelCount' => $safeReferenceLabelCount,
                    'safeReferenceAuthorCount' => $safeReferenceAuthorCount,
                    'safeReferenceDateCount' => $safeReferenceDateCount,
                    'safeReferenceYearCount' => $safeReferenceYearCount,
                    'referenceIdentifierCount' => $referenceIdentifierCount,
                    'referenceIdentifierSourceSummaryCount' => $referenceIdentifierSourceSummaryCount,
                    'resolvedBibrIdentifierTargetCount' => $resolvedBibrIdentifierTargetCount,
                    'duplicateReferenceIdentifierCount' => $duplicateReferenceIdentifierCount,
                    'referencesMissingIdentifierCount' => $referencesMissingIdentifierCount,
                    'blockedCitationTextPayloadCount' => $blockedCitationTextPayloadCount,
                ]
            );
        }

        if ($safeReferenceLabelCount > 0 || $blockedCitationTextPayloadCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'reference-citation-text-policy',
                'warning',
                'Reference labels are exposed as safe summaries; citation text payloads remain blocked from raw packet text.',
                false,
                true,
                [
                    'safeReferenceLabelCount' => $safeReferenceLabelCount,
                    'blockedCitationTextPayloadCount' => $blockedCitationTextPayloadCount,
                ]
            );
        }

        if ($safeReferenceAuthorCount > 0 || $safeReferenceDateCount > 0 || $safeReferenceYearCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'reference-author-date-policy',
                'warning',
                'Reference author, date, and year metadata are exposed as bounded summaries while citation text payloads stay blocked.',
                false,
                true,
                [
                    'safeReferenceAuthorCount' => $safeReferenceAuthorCount,
                    'safeReferenceDateCount' => $safeReferenceDateCount,
                    'safeReferenceYearCount' => $safeReferenceYearCount,
                    'blockedCitationTextPayloadCount' => $blockedCitationTextPayloadCount,
                ]
            );
        }

        if ($referenceIdentifierCount > 0 || $referencesMissingIdentifierCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'reference-identifier-policy',
                'warning',
                'Reference identifiers are exposed as bounded DOI/PMID/PMCID/ISBN/URI provenance summaries while citation text payloads stay blocked.',
                false,
                true,
                [
                    'referenceIdentifierCount' => $referenceIdentifierCount,
                    'referenceIdentifierSourceSummaryCount' => $referenceIdentifierSourceSummaryCount,
                    'resolvedBibrIdentifierTargetCount' => $resolvedBibrIdentifierTargetCount,
                    'duplicateReferenceIdentifierCount' => $duplicateReferenceIdentifierCount,
                    'referencesMissingIdentifierCount' => $referencesMissingIdentifierCount,
                    'blockedCitationTextPayloadCount' => $blockedCitationTextPayloadCount,
                ]
            );
        }

        if ($duplicateReferenceIdentifierCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'reference-identifiers-duplicate',
                'warning',
                'Duplicate reference identifiers were found across back-matter references.',
                false,
                true,
                [
                    'duplicateReferenceIdentifierCount' => $duplicateReferenceIdentifierCount,
                    'referenceIdentifierCount' => $referenceIdentifierCount,
                ]
            );
        }

        if ($referencesMissingIdentifierCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'reference-identifiers-missing',
                'warning',
                'Some back-matter references do not expose DOI/PMID/PMCID/ISBN/URI identifiers.',
                false,
                true,
                [
                    'referencesMissingIdentifierCount' => $referencesMissingIdentifierCount,
                    'referenceCount' => $referenceCount,
                ]
            );
        }

        if ($unresolvedBibrXrefCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'bibliography-xrefs-unresolved',
                'warning',
                'Some bibliography xref targets do not resolve to ref-list reference entries.',
                false,
                true,
                [
                    'unresolvedBibrXrefCount' => $unresolvedBibrXrefCount,
                    'resolvedBibrXrefCount' => $resolvedBibrXrefCount,
                ]
            );
        }

        if ($fundingGroupCount > 0 || $awardGroupCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'funding-review-only',
                'unsupported',
                'Funding metadata is summarized for review but is not mapped as full JATS/BITS reader output.',
                false,
                true,
                [
                    'fundingGroupCount' => $fundingGroupCount,
                    'awardGroupCount' => $awardGroupCount,
                ]
            );
        }

        if ($acknowledgmentCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'acknowledgments-review-only',
                'unsupported',
                'Acknowledgment sections are summarized for review but are not mapped as full JATS/BITS reader output.',
                false,
                true,
                ['acknowledgmentCount' => $acknowledgmentCount]
            );
        }

        if ($figureCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'figures-review-only',
                'unsupported',
                'Figure elements are inventoried for review but are not mapped as full figure blocks.',
                false,
                false,
                [
                    'figureCount' => $figureCount,
                    'withLabelCount' => $figureWithLabelCount,
                    'withCaptionCount' => $figureWithCaptionCount,
                    'withTitleCount' => $figureWithTitleCount,
                    'missingLabelCount' => $figureMissingLabelCount,
                    'missingCaptionCount' => $figureMissingCaptionCount,
                    'missingTitleCount' => $figureMissingTitleCount,
                    'duplicateLabelFigureCount' => $figureDuplicateLabelCount,
                ]
            );

            if ($figureMissingLabelCount > 0) {
                $diagnostics[] = self::jatsDirectReaderDiagnostic(
                    'figure-label-metadata-missing',
                    'warning',
                    'One or more figure elements do not expose bounded label metadata.',
                    false,
                    true,
                    ['missingLabelCount' => $figureMissingLabelCount]
                );
            }

            if ($figureMissingCaptionCount > 0) {
                $diagnostics[] = self::jatsDirectReaderDiagnostic(
                    'figure-caption-metadata-missing',
                    'warning',
                    'One or more figure elements do not expose bounded caption metadata.',
                    false,
                    true,
                    ['missingCaptionCount' => $figureMissingCaptionCount]
                );
            }

            if ($figureMissingTitleCount > 0) {
                $diagnostics[] = self::jatsDirectReaderDiagnostic(
                    'figure-title-metadata-missing',
                    'warning',
                    'One or more figure elements do not expose bounded title metadata.',
                    false,
                    true,
                    ['missingTitleCount' => $figureMissingTitleCount]
                );
            }

            if ($figureDuplicateLabelCount > 0) {
                $diagnostics[] = self::jatsDirectReaderDiagnostic(
                    'figure-label-duplicate',
                    'warning',
                    'Figure labels are duplicated across figure ids.',
                    false,
                    true,
                    ['duplicateLabelFigureCount' => $figureDuplicateLabelCount]
                );
            }
        }

        if ($figureMediaReferenceCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'figure-media-references-review-only',
                'unsupported',
                'Figure graphic/media references are exposed as metadata-only targets; payload bytes are not extracted.',
                false,
                true,
                [
                    'mediaReferenceCount' => $figureMediaReferenceCount,
                    'payloadBytesExposed' => false,
                ]
            );
        }

        if ($figureMediaMissingTargetCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'figure-media-target-missing',
                'warning',
                'One or more figure graphic/media elements omit an href target.',
                false,
                true,
                ['missingTargetCount' => $figureMediaMissingTargetCount]
            );
        }

        if ($figureMediaExternalReferenceCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'figure-media-external-reference-unsupported',
                'unsupported',
                'External figure graphic/media references are recorded for review but are not fetched.',
                false,
                true,
                ['externalReferenceCount' => $figureMediaExternalReferenceCount]
            );
        }

        if ($tableWrapCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'table-wraps-review-only',
                'unsupported',
                'Table-wrap elements are inventoried for review but are not mapped as full table blocks.',
                false,
                false,
                ['tableWrapCount' => $tableWrapCount]
            );
        }

        if ($bookPartCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'book-parts-review-only',
                'unsupported',
                'Book-part elements are counted for review but are not mapped as nested Pandoc documents.',
                false,
                false,
                ['bookPartCount' => $bookPartCount]
            );
        }

        if ($sectionMetadataDiagnosticCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'section-metadata-diagnostics-review-only',
                'warning',
                'JATS/BITS section metadata diagnostics are exposed for review but are not full direct-reader section AST parity.',
                false,
                true,
                ['sectionMetadataDiagnosticCount' => $sectionMetadataDiagnosticCount]
            );
        }

        return $diagnostics;
    }

    /**
     * @param array<string, mixed> $details
     * @return array{code:string, severity:string, message:string, directReaderParity:bool, coveredByPacket:bool, details:array<string, mixed>}
     */
    private static function jatsDirectReaderDiagnostic(
        string $code,
        string $severity,
        string $message,
        bool $directReaderParity,
        bool $coveredByPacket,
        array $details = []
    ): array {
        return [
            'code' => $code,
            'severity' => $severity,
            'message' => $message,
            'directReaderParity' => $directReaderParity,
            'coveredByPacket' => $coveredByPacket,
            'details' => $details,
        ];
    }

    /**
     * @return list<array{code:string, severity:string, message:string, directReaderParity:bool, coveredByPacket:bool, details:array<string, int|string|bool>}>
     */
    private static function docBookDirectReaderDiagnostics(
        string $format,
        int $structuralBlockCount,
        int $admonitionCount,
        int $figureCount,
        int $mediaObjectCount,
        int $imageDataRefCount,
        int $mediaTargetManifestCount,
        int $repeatedMediaTargetCount,
        int $missingMediaTargetMetadataCount,
        int $mediaObjectAssociationDiagnosticCount,
        int $mediaLinkendReferenceCount,
        int $linkendReferenceCount,
        int $xmlIdTargetCount,
        int $unsupportedChildDiagnosticCount
    ): array {
        $diagnostics = [
            self::docBookDirectReaderDiagnostic(
                'direct-reader-unsupported',
                'unsupported',
                'DocBook direct reader parity is not implemented; this packet exposes bounded XML diagnostics only.',
                false,
                true,
                ['format' => $format]
            ),
        ];

        if ($structuralBlockCount > 0) {
            $diagnostics[] = self::docBookDirectReaderDiagnostic(
                'structural-blocks-review-only',
                'unsupported',
                'DocBook structural blocks are inventoried for review but are not mapped as a full Pandoc direct reader AST.',
                false,
                false,
                ['structuralBlockCount' => $structuralBlockCount]
            );
        }

        if ($admonitionCount > 0) {
            $diagnostics[] = self::docBookDirectReaderDiagnostic(
                'admonitions-review-only',
                'unsupported',
                'DocBook admonition-like blocks are summarized but are not converted into Pandoc admonition/body blocks.',
                false,
                false,
                ['admonitionCount' => $admonitionCount]
            );
        }

        if ($figureCount > 0) {
            $diagnostics[] = self::docBookDirectReaderDiagnostic(
                'figures-review-only',
                'unsupported',
                'DocBook figure elements are summarized for review but are not converted into Pandoc figure blocks.',
                false,
                false,
                ['figureCount' => $figureCount]
            );
        }

        if ($mediaObjectCount > 0) {
            $diagnostics[] = self::docBookDirectReaderDiagnostic(
                'mediaobjects-review-only',
                'unsupported',
                'DocBook mediaobject elements are summarized for review but are not mapped as media-bearing blocks.',
                false,
                false,
                ['mediaObjectCount' => $mediaObjectCount]
            );
        }

        if ($imageDataRefCount > 0) {
            $diagnostics[] = self::docBookDirectReaderDiagnostic(
                'image-references-review-only',
                'unsupported',
                'DocBook imagedata references are inventoried but are not loaded or converted into image resources.',
                false,
                false,
                ['imageDataRefCount' => $imageDataRefCount]
            );
        }

        if (
            $mediaTargetManifestCount > 0
            || $repeatedMediaTargetCount > 0
            || $missingMediaTargetMetadataCount > 0
            || $mediaObjectAssociationDiagnosticCount > 0
            || $mediaLinkendReferenceCount > 0
        ) {
            $diagnostics[] = self::docBookDirectReaderDiagnostic(
                'media-target-manifest-review-only',
                'unsupported',
                'DocBook media target manifests and media linkend/id associations are summarized without loading media payloads or claiming direct-reader parity.',
                false,
                false,
                [
                    'mediaTargetManifestCount' => $mediaTargetManifestCount,
                    'repeatedMediaTargetCount' => $repeatedMediaTargetCount,
                    'missingMediaTargetMetadataCount' => $missingMediaTargetMetadataCount,
                    'mediaObjectAssociationDiagnosticCount' => $mediaObjectAssociationDiagnosticCount,
                    'mediaLinkendReferenceCount' => $mediaLinkendReferenceCount,
                    'payloadBytesExposed' => false,
                ]
            );
        }

        if ($linkendReferenceCount > 0 || $xmlIdTargetCount > 0) {
            $diagnostics[] = self::docBookDirectReaderDiagnostic(
                'linkend-targets-review-only',
                'unsupported',
                'DocBook xml:id/id targets and linkend references are summarized without full cross-reference conversion.',
                false,
                false,
                [
                    'linkendReferenceCount' => $linkendReferenceCount,
                    'xmlIdTargetCount' => $xmlIdTargetCount,
                ]
            );
        }

        if ($unsupportedChildDiagnosticCount > 0) {
            $diagnostics[] = self::docBookDirectReaderDiagnostic(
                'unsupported-children-review-only',
                'unsupported',
                'DocBook child elements outside the bounded review packet are reported as unsupported direct-reader gaps.',
                false,
                false,
                ['unsupportedChildDiagnosticCount' => $unsupportedChildDiagnosticCount]
            );
        }

        return $diagnostics;
    }

    /**
     * @param array<string, int|string|bool> $details
     * @return array{code:string, severity:string, message:string, directReaderParity:bool, coveredByPacket:bool, details:array<string, int|string|bool>}
     */
    private static function docBookDirectReaderDiagnostic(
        string $code,
        string $severity,
        string $message,
        bool $directReaderParity,
        bool $coveredByPacket,
        array $details = []
    ): array {
        return [
            'code' => $code,
            'severity' => $severity,
            'message' => $message,
            'directReaderParity' => $directReaderParity,
            'coveredByPacket' => $coveredByPacket,
            'details' => $details,
        ];
    }

    /**
     * @return array{
     *     name:string,
     *     qualifiedName:string,
     *     namespaceUri:string|null,
     *     prefix:string|null,
     *     id:string|null,
     *     xmlId:string|null,
     *     language:string|null,
     *     attributes:array<string, string>,
     *     attributeNames:list<string>,
     *     attributeCount:int
     * }
     */
    private static function xmlRootProvenance(\DOMElement $root): array
    {
        $attributes = self::xmlAttributeMap($root);

        return [
            'name' => $root->localName,
            'qualifiedName' => $root->tagName,
            'namespaceUri' => $root->namespaceURI !== '' ? $root->namespaceURI : null,
            'prefix' => $root->prefix !== '' ? $root->prefix : null,
            'id' => $root->hasAttribute('id') ? $root->getAttribute('id') : null,
            'xmlId' => self::attribute($root, 'id', self::XML_NAMESPACE),
            'language' => self::attribute($root, 'lang', self::XML_NAMESPACE)
                ?? self::attribute($root, 'lang'),
            'attributes' => $attributes,
            'attributeNames' => array_keys($attributes),
            'attributeCount' => count($attributes),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    public static function summarizeDocBookReviewPacket(\DOMDocument $dom, string $format = 'docbook'): array
    {
        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement) {
            throw new \InvalidArgumentException('DocBook review packet requires a document element');
        }

        $format = strtolower(trim($format));
        if (!in_array($format, ['docbook', 'docbook4', 'docbook5'], true)) {
            throw new \InvalidArgumentException('DocBook review packet format must be docbook, docbook4, or docbook5');
        }
        if (!self::docBookRootLooksLikeDocBook($root)) {
            throw new \InvalidArgumentException('DocBook review packet root must be a DocBook structural element');
        }

        $structuralBlocks = self::docBookStructuralBlockSummaries($root);
        $admonitions = self::docBookReviewAdmonitionSummaries($root);
        $figures = self::docBookFigureSummaries($root);
        $mediaObjects = self::docBookMediaObjectSummaries($root);
        $mediaTargetManifest = self::docBookReviewMediaTargetManifest($mediaObjects['items']);
        $repeatedMediaRoleTargetPairs = self::docBookRepeatedMediaRoleTargetPairs($mediaObjects['items']);
        $mediaDiagnostics = self::docBookMediaObjectDiagnostics($mediaObjects['items'], $repeatedMediaRoleTargetPairs);
        $imageDataRefs = self::docBookImageDataReferences($root);
        $targetSummary = self::docBookTargetSummary($root);
        $crossReferences = self::docBookCrossReferenceSummaries($root, self::docBookElementIdMap($root));
        $mediaReview = self::docBookMediaTargetReviewSummary($root, $crossReferences);
        $unsupportedChildDiagnostics = self::docBookUnsupportedChildDiagnostics($root);
        $directReaderDiagnostics = self::docBookDirectReaderDiagnostics(
            $format,
            $structuralBlocks['count'],
            $admonitions['count'],
            $figures['count'],
            $mediaObjects['count'],
            $imageDataRefs['count'],
            $mediaReview['mediaTargetManifest']['count'],
            $mediaReview['repeatedMediaTargets']['count'],
            $mediaReview['missingMediaTargetMetadata']['count'],
            $mediaReview['mediaObjectAssociationDiagnostics']['count'],
            $mediaReview['mediaLinkendReferences']['count'],
            count($targetSummary['linkendReferences']),
            count($targetSummary['xmlIdTargets']),
            $unsupportedChildDiagnostics['count']
        );

        return [
            'formatFamily' => 'xml-html5-docbook-dom',
            'format' => $format,
            'reviewPolicy' => 'docbook-structural-media-review-only',
            'directReaderParity' => false,
            'directReaderDiagnosticCodes' => array_map(
                static fn (array $diagnostic): string => (string) $diagnostic['code'],
                $directReaderDiagnostics
            ),
            'directReaderDiagnosticCount' => count($directReaderDiagnostics),
            'directReaderDiagnostics' => $directReaderDiagnostics,
            'rootName' => $root->localName,
            'rootNamespace' => $root->namespaceURI,
            'rootAttributes' => self::xmlAttributeMap($root),
            'version' => self::attribute($root, 'version'),
            'language' => self::attribute($root, 'lang', self::XML_NAMESPACE)
                ?? self::attribute($root, 'lang'),
            'title' => self::docBookReviewTitleText($root),
            'bounded' => true,
            'maxReviewItems' => self::DOCBOOK_REVIEW_PACKET_MAX_ITEMS,
            'structuralBlocks' => $structuralBlocks['items'],
            'structuralBlockCount' => $structuralBlocks['count'],
            'structuralBlockNames' => array_values(array_unique(array_map(
                static fn (array $item): string => (string) $item['name'],
                $structuralBlocks['items']
            ))),
            'structuralBlocksTruncated' => $structuralBlocks['truncated'],
            'admonitions' => $admonitions['items'],
            'admonitionCount' => $admonitions['count'],
            'admonitionTypes' => array_values(array_unique(array_map(
                static fn (array $item): string => (string) $item['type'],
                $admonitions['items']
            ))),
            'admonitionsTruncated' => $admonitions['truncated'],
            'figures' => $figures['items'],
            'figureCount' => $figures['count'],
            'figureXmlIds' => array_values(array_filter(array_map(
                static fn (array $item): ?string => $item['xmlId'],
                $figures['items']
            ), static fn (?string $id): bool => $id !== null && $id !== '')),
            'figuresTruncated' => $figures['truncated'],
            'mediaObjects' => $mediaObjects['items'],
            'mediaObjectCount' => $mediaObjects['count'],
            'mediaObjectRoles' => self::docBookMediaObjectStringValues($mediaObjects['items'], 'roles'),
            'mediaCaptionTexts' => self::docBookMediaObjectStringValues($mediaObjects['items'], 'captionText'),
            'mediaTextAlternativeTexts' => self::docBookMediaObjectStringValues($mediaObjects['items'], 'textAlternativeTexts'),
            'mediaTargetManifest' => $mediaTargetManifest,
            'mediaTargetManifestCount' => count($mediaTargetManifest),
            'repeatedMediaRoleTargetPairs' => $repeatedMediaRoleTargetPairs,
            'repeatedMediaRoleTargetPairCount' => count($repeatedMediaRoleTargetPairs),
            'mediaDiagnosticCodes' => array_map(
                static fn (array $diagnostic): string => (string) $diagnostic['code'],
                $mediaDiagnostics
            ),
            'mediaDiagnosticCount' => count($mediaDiagnostics),
            'mediaDiagnostics' => $mediaDiagnostics,
            'mediaObjectsTruncated' => $mediaObjects['truncated'],
            'imageDataRefs' => $imageDataRefs['items'],
            'imageDataRefCount' => $imageDataRefs['count'],
            'imageDataRefsTruncated' => $imageDataRefs['truncated'],
            'mediaImageTargetManifest' => $mediaReview['mediaTargetManifest']['items'],
            'mediaImageTargetManifestCount' => $mediaReview['mediaTargetManifest']['count'],
            'mediaImageTargetManifestTruncated' => $mediaReview['mediaTargetManifest']['truncated'],
            'repeatedMediaTargets' => $mediaReview['repeatedMediaTargets']['items'],
            'repeatedMediaTargetCount' => $mediaReview['repeatedMediaTargets']['count'],
            'repeatedMediaTargetsTruncated' => $mediaReview['repeatedMediaTargets']['truncated'],
            'missingMediaTargetMetadata' => $mediaReview['missingMediaTargetMetadata']['items'],
            'missingMediaTargetMetadataCount' => $mediaReview['missingMediaTargetMetadata']['count'],
            'missingMediaTargetMetadataTruncated' => $mediaReview['missingMediaTargetMetadata']['truncated'],
            'mediaTargetBasenameGroups' => $mediaReview['mediaTargetBasenameGroups']['items'],
            'mediaTargetBasenameGroupCount' => $mediaReview['mediaTargetBasenameGroups']['count'],
            'mediaTargetBasenameGroupsTruncated' => $mediaReview['mediaTargetBasenameGroups']['truncated'],
            'mediaTargetContentTypeGroups' => $mediaReview['mediaTargetContentTypeGroups']['items'],
            'mediaTargetContentTypeGroupCount' => $mediaReview['mediaTargetContentTypeGroups']['count'],
            'mediaTargetContentTypeGroupsTruncated' => $mediaReview['mediaTargetContentTypeGroups']['truncated'],
            'mediaObjectAssociations' => $mediaReview['mediaObjectAssociations']['items'],
            'mediaObjectAssociationCount' => $mediaReview['mediaObjectAssociations']['count'],
            'mediaObjectAssociationsTruncated' => $mediaReview['mediaObjectAssociations']['truncated'],
            'mediaObjectAssociationDiagnostics' => $mediaReview['mediaObjectAssociationDiagnostics']['items'],
            'mediaObjectAssociationDiagnosticCount' => $mediaReview['mediaObjectAssociationDiagnostics']['count'],
            'mediaObjectAssociationDiagnosticsTruncated' => $mediaReview['mediaObjectAssociationDiagnostics']['truncated'],
            'mediaObjectAssociationDiagnosticCodes' => array_values(array_unique(array_map(
                static fn (array $diagnostic): string => (string) $diagnostic['code'],
                $mediaReview['mediaObjectAssociationDiagnostics']['items']
            ))),
            'mediaIdTargetSummaries' => $mediaReview['mediaIdTargetSummaries']['items'],
            'mediaIdTargetSummaryCount' => $mediaReview['mediaIdTargetSummaries']['count'],
            'mediaIdTargetSummariesTruncated' => $mediaReview['mediaIdTargetSummaries']['truncated'],
            'mediaIdTargets' => $mediaReview['mediaIdTargets'],
            'mediaLinkendReferences' => $mediaReview['mediaLinkendReferences']['items'],
            'mediaLinkendReferenceCount' => $mediaReview['mediaLinkendReferences']['count'],
            'mediaLinkendReferencesTruncated' => $mediaReview['mediaLinkendReferences']['truncated'],
            'xmlIdTargets' => $targetSummary['xmlIdTargets'],
            'idTargets' => $targetSummary['idTargets'],
            'targetSummaries' => $targetSummary['targetSummaries'],
            'targetSummaryCount' => count($targetSummary['targetSummaries']),
            'linkendReferences' => $targetSummary['linkendReferences'],
            'linkendReferenceCount' => count($targetSummary['linkendReferences']),
            'linkendTargets' => $targetSummary['linkendTargets'],
            'missingLinkendTargets' => $targetSummary['missingLinkendTargets'],
            'unsupportedChildDiagnostics' => $unsupportedChildDiagnostics['items'],
            'unsupportedChildDiagnosticCount' => $unsupportedChildDiagnostics['count'],
            'unsupportedChildNames' => array_values(array_unique(array_map(
                static fn (array $item): string => (string) $item['childName'],
                $unsupportedChildDiagnostics['items']
            ))),
            'unsupportedChildDiagnosticsTruncated' => $unsupportedChildDiagnostics['truncated'],
        ];
    }

    /**
     * @return array<string, mixed>
     */
    public static function summarizeDocBookBibliography(\DOMDocument $dom): array
    {
        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement) {
            throw new \InvalidArgumentException('DocBook bibliography review packet requires a document element');
        }

        $bibliographies = self::docBookBibliographySummaries($root);
        $entries = self::docBookBibliographyEntrySummaries($root);
        $entryMetadataDiagnostics = self::docBookBibliographyEntryMetadataDiagnostics($entries);
        $entryMetadataDiagnosticCodes = array_values(array_unique(array_map(
            static fn (array $diagnostic): string => (string) $diagnostic['code'],
            $entryMetadataDiagnostics
        )));
        $idOccurrences = self::docBookBibliographyIdOccurrences($root);
        $duplicateIds = array_values(array_keys(array_filter(
            $idOccurrences,
            static fn (int $count): bool => $count > 1
        )));
        $documentIds = self::docBookBibliographyDocumentIdSet($root);
        $referenceLinks = self::docBookBibliographyReferenceLinks($root);
        $referenceLinkTargets = array_values(array_unique(array_map(
            static fn (array $link): string => (string) $link['target'],
            $referenceLinks
        )));
        $missingReferenceTargets = array_values(array_filter(
            $referenceLinkTargets,
            static fn (string $target): bool => !isset($documentIds[$target])
        ));
        $referenceTargetSummaries = self::docBookBibliographyReferenceTargetSummaries($referenceLinks, $documentIds, $duplicateIds);
        $unsupportedChildren = self::docBookBibliographyUnsupportedChildSummaries($root);
        $directReaderDiagnostics = self::docBookBibliographyDirectReaderDiagnostics(
            count($bibliographies),
            count($entries),
            $duplicateIds,
            $missingReferenceTargets,
            count($unsupportedChildren),
            $entryMetadataDiagnostics
        );

        return [
            'formatFamily' => 'xml-html5-docbook-dom',
            'format' => 'docbook',
            'reviewPolicy' => 'docbook-bibliography-reference-review-only',
            'directReaderParity' => false,
            'directReaderDiagnosticCodes' => array_map(
                static fn (array $diagnostic): string => (string) $diagnostic['code'],
                $directReaderDiagnostics
            ),
            'directReaderDiagnosticCount' => count($directReaderDiagnostics),
            'directReaderDiagnostics' => $directReaderDiagnostics,
            'rootName' => $root->localName,
            'rootAttributes' => self::xmlAttributeMap($root),
            'docbookVersion' => self::attribute($root, 'version'),
            'language' => self::attribute($root, 'lang', 'http://www.w3.org/XML/1998/namespace')
                ?? self::attribute($root, 'lang'),
            'bibliographies' => $bibliographies,
            'bibliographyCount' => count($bibliographies),
            'bibliographyIds' => self::docBookBibliographyIdsForLocalNames($root, ['bibliography']),
            'bibliographyEntries' => $entries,
            'bibliographyEntryCount' => count($entries),
            'bibliographyEntryIds' => self::docBookBibliographyIdsForLocalNames($root, ['biblioentry', 'bibliomixed']),
            'biblioentryIds' => self::docBookBibliographyIdsForLocalNames($root, ['biblioentry']),
            'bibliomixedIds' => self::docBookBibliographyIdsForLocalNames($root, ['bibliomixed']),
            'bibliographyEntryMetadataDiagnostics' => $entryMetadataDiagnostics,
            'bibliographyEntryMetadataDiagnosticCodes' => $entryMetadataDiagnosticCodes,
            'bibliographyEntryMetadataDiagnosticCount' => count($entryMetadataDiagnostics),
            'missingBibliographyEntryMetadataDiagnostics' => array_values(array_filter(
                $entryMetadataDiagnostics,
                static fn (array $diagnostic): bool => str_contains((string) $diagnostic['code'], '-missing-')
            )),
            'duplicateBibliographyEntryMetadataDiagnostics' => array_values(array_filter(
                $entryMetadataDiagnostics,
                static fn (array $diagnostic): bool => str_contains((string) $diagnostic['code'], '-duplicate-')
                    || str_contains((string) $diagnostic['code'], '-conflicting-')
            )),
            'bibliographicIdOccurrences' => $idOccurrences,
            'duplicateBibliographyIds' => $duplicateIds,
            'referenceLinks' => $referenceLinks,
            'referenceLinkTargets' => $referenceLinkTargets,
            'referenceLinkTargetCount' => count($referenceLinkTargets),
            'referenceTargetSummaries' => $referenceTargetSummaries,
            'linkendTargets' => self::docBookBibliographyReferenceTargetsBySource($referenceLinks, ['linkend']),
            'xrefTargets' => self::docBookBibliographyReferenceTargetsByElement($referenceLinks, ['xref', 'biblioref', 'link']),
            'citationTargets' => self::docBookBibliographyReferenceTargetsByElement($referenceLinks, ['citation']),
            'missingReferenceTargets' => $missingReferenceTargets,
            'missingReferenceTargetCount' => count($missingReferenceTargets),
            'unsupportedBibliographyChildren' => $unsupportedChildren,
            'unsupportedBibliographyChildCount' => count($unsupportedChildren),
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function docBookBibliographySummaries(\DOMElement $root): array
    {
        $summaries = [];
        foreach (self::docBookBibliographyElementsWithLocalNames($root, ['bibliography']) as $bibliography) {
            $entryIds = [];
            foreach (self::docBookBibliographyElementsWithLocalNames($bibliography, ['biblioentry', 'bibliomixed'], false) as $entry) {
                $id = self::docBookBibliographyElementId($entry);
                if ($id !== null) {
                    $entryIds[] = $id;
                }
            }

            $summaries[] = [
                'element' => $bibliography->localName,
                'id' => self::docBookBibliographyElementId($bibliography),
                'title' => self::docBookBibliographyFirstDescendantText($bibliography, ['title']),
                'entryIds' => array_values(array_unique($entryIds)),
                'entryCount' => count(self::docBookBibliographyElementsWithLocalNames($bibliography, ['biblioentry', 'bibliomixed'], false)),
            ];
        }

        return $summaries;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function docBookBibliographyEntrySummaries(\DOMElement $root): array
    {
        $entries = [];
        foreach (self::docBookBibliographyElementsWithLocalNames($root, ['biblioentry', 'bibliomixed']) as $index => $entry) {
            $idMetadata = self::docBookBibliographyEntryIdMetadata($entry);
            $titleMetadata = self::docBookBibliographyTextRecords($entry, ['title', 'citetitle']);
            $authors = self::docBookBibliographyContributorSummaries($entry, ['author']);
            $editors = self::docBookBibliographyContributorSummaries($entry, ['editor']);
            $contributors = [...$authors, ...$editors];
            $publishers = self::docBookBibliographyPublisherSummaries($entry);
            $yearLikeMetadata = self::docBookBibliographyYearLikeMetadata($entry);
            $entries[] = [
                'entryIndex' => $index,
                'element' => $entry->localName,
                'id' => $idMetadata['id'],
                'xmlId' => $idMetadata['xmlId'],
                'idAttribute' => $idMetadata['idAttribute'],
                'idSource' => $idMetadata['idSource'],
                'idConflict' => $idMetadata['idConflict'],
                'title' => $titleMetadata[0]['value'] ?? null,
                'titleMetadata' => $titleMetadata,
                'titleCount' => count($titleMetadata),
                'authors' => self::docBookBibliographyContributorNames($authors),
                'authorMetadata' => $authors,
                'authorCount' => count($authors),
                'editors' => self::docBookBibliographyContributorNames($editors),
                'editorMetadata' => $editors,
                'editorCount' => count($editors),
                'contributors' => $contributors,
                'contributorNames' => self::docBookBibliographyContributorNames($contributors),
                'contributorRoles' => array_values(array_unique(array_map(
                    static fn (array $contributor): string => (string) $contributor['role'],
                    $contributors
                ))),
                'publisher' => $publishers[0]['name'] ?? null,
                'publishers' => $publishers,
                'publisherNames' => array_values(array_unique(array_map(
                    static fn (array $publisher): string => (string) $publisher['name'],
                    $publishers
                ))),
                'publisherCount' => count($publishers),
                'yearLikeMetadata' => $yearLikeMetadata,
                'dateMetadata' => $yearLikeMetadata,
                'yearLikeValues' => array_values(array_unique(array_map(
                    static fn (array $metadata): string => (string) $metadata['value'],
                    $yearLikeMetadata
                ))),
                'dateValues' => array_values(array_unique(array_map(
                    static fn (array $metadata): string => (string) $metadata['value'],
                    $yearLikeMetadata
                ))),
            ];
        }

        return $entries;
    }

    /**
     * @return array{id:?string, xmlId:?string, idAttribute:?string, idSource:?string, idConflict:bool}
     */
    private static function docBookBibliographyEntryIdMetadata(\DOMElement $entry): array
    {
        $xmlId = self::docBookBibliographyNormalizedAttribute($entry, 'id', 'http://www.w3.org/XML/1998/namespace');
        $id = self::docBookBibliographyNormalizedAttribute($entry, 'id');
        $source = null;
        if ($xmlId !== null && $id !== null) {
            $source = 'xml:id+id';
        } elseif ($xmlId !== null) {
            $source = 'xml:id';
        } elseif ($id !== null) {
            $source = 'id';
        }

        return [
            'id' => $xmlId ?? $id,
            'xmlId' => $xmlId,
            'idAttribute' => $id,
            'idSource' => $source,
            'idConflict' => $xmlId !== null && $id !== null && $xmlId !== $id,
        ];
    }

    /**
     * @param list<string> $localNames
     * @return list<string>
     */
    private static function docBookBibliographyIdsForLocalNames(\DOMElement $root, array $localNames): array
    {
        $ids = [];
        foreach (self::docBookBibliographyElementsWithLocalNames($root, $localNames) as $element) {
            $id = self::docBookBibliographyElementId($element);
            if ($id !== null) {
                $ids[] = $id;
            }
        }

        return array_values(array_unique($ids));
    }

    /**
     * @return array<string, int>
     */
    private static function docBookBibliographyIdOccurrences(\DOMElement $root): array
    {
        $occurrences = [];
        foreach (self::docBookBibliographyElementsWithLocalNames($root, ['bibliography', 'bibliodiv', 'biblioentry', 'bibliomixed']) as $element) {
            $id = self::docBookBibliographyElementId($element);
            if ($id === null) {
                continue;
            }

            $occurrences[$id] = ($occurrences[$id] ?? 0) + 1;
        }

        return $occurrences;
    }

    /**
     * @return array<string, true>
     */
    private static function docBookBibliographyDocumentIdSet(\DOMElement $root): array
    {
        $ids = [];
        foreach ([$root, ...self::descendantElements($root)] as $element) {
            $id = self::docBookBibliographyElementId($element);
            if ($id !== null) {
                $ids[$id] = true;
            }
        }

        return $ids;
    }

    /**
     * @return list<array{element:string, target:string, targetSource:string, text:string}>
     */
    private static function docBookBibliographyReferenceLinks(\DOMElement $root): array
    {
        $links = [];
        foreach (self::docBookBibliographyElementsWithLocalNames($root, ['xref', 'biblioref', 'link']) as $element) {
            $linkend = self::attribute($element, 'linkend');
            if ($linkend === null || trim($linkend) === '') {
                continue;
            }

            foreach (self::spaceSeparatedTokens($linkend) as $target) {
                $links[] = [
                    'element' => $element->localName,
                    'target' => $target,
                    'targetSource' => 'linkend',
                    'text' => self::normalizedText($element),
                ];
            }
        }

        foreach (self::docBookBibliographyElementsWithLocalNames($root, ['citation']) as $element) {
            $target = self::docBookBibliographyCitationTarget($element);
            if ($target === null) {
                continue;
            }

            $links[] = [
                'element' => $element->localName,
                'target' => $target,
                'targetSource' => 'citation-text',
                'text' => self::normalizedText($element),
            ];
        }

        return $links;
    }

    /**
     * @param list<array{element:string, target:string, targetSource:string, text:string}> $links
     * @param list<string> $elementNames
     * @return list<string>
     */
    private static function docBookBibliographyReferenceTargetsByElement(array $links, array $elementNames): array
    {
        $targets = [];
        foreach ($links as $link) {
            if (in_array($link['element'], $elementNames, true)) {
                $targets[] = $link['target'];
            }
        }

        return array_values(array_unique($targets));
    }

    /**
     * @param list<array{element:string, target:string, targetSource:string, text:string}> $links
     * @param list<string> $targetSources
     * @return list<string>
     */
    private static function docBookBibliographyReferenceTargetsBySource(array $links, array $targetSources): array
    {
        $targets = [];
        foreach ($links as $link) {
            if (in_array($link['targetSource'], $targetSources, true)) {
                $targets[] = $link['target'];
            }
        }

        return array_values(array_unique($targets));
    }

    /**
     * @param list<array{element:string, target:string, targetSource:string, text:string}> $links
     * @param array<string, true> $documentIds
     * @param list<string> $duplicateIds
     * @return list<array<string, mixed>>
     */
    private static function docBookBibliographyReferenceTargetSummaries(array $links, array $documentIds, array $duplicateIds): array
    {
        $summaries = [];
        foreach ($links as $link) {
            $target = (string) $link['target'];
            if (!isset($summaries[$target])) {
                $duplicate = in_array($target, $duplicateIds, true);
                $resolved = isset($documentIds[$target]);
                $summaries[$target] = [
                    'target' => $target,
                    'resolved' => $resolved,
                    'duplicateTargetId' => $duplicate,
                    'missing' => !$resolved,
                    'status' => $duplicate ? 'duplicate-id' : ($resolved ? 'resolved' : 'missing'),
                    'elements' => [],
                    'targetSources' => [],
                    'texts' => [],
                ];
            }

            $summaries[$target]['elements'][] = (string) $link['element'];
            $summaries[$target]['targetSources'][] = (string) $link['targetSource'];
            if ((string) $link['text'] !== '') {
                $summaries[$target]['texts'][] = (string) $link['text'];
            }
        }

        foreach ($summaries as &$summary) {
            $summary['elements'] = array_values(array_unique($summary['elements']));
            $summary['targetSources'] = array_values(array_unique($summary['targetSources']));
            $summary['texts'] = array_values(array_unique($summary['texts']));
        }
        unset($summary);

        return array_values($summaries);
    }

    /**
     * @return list<array{element:string, value:string}>
     */
    private static function docBookBibliographyYearLikeMetadata(\DOMElement $entry): array
    {
        $metadata = [];
        foreach (self::docBookBibliographyElementsWithLocalNames($entry, ['year', 'date', 'pubdate', 'releaseinfo'], false) as $element) {
            $value = self::normalizedText($element);
            if ($value === '') {
                continue;
            }

            $metadata[] = [
                'element' => $element->localName,
                'value' => $value,
            ];
        }

        return $metadata;
    }

    /**
     * @return list<string>
     */
    private static function docBookBibliographyAuthorNames(\DOMElement $entry): array
    {
        return self::docBookBibliographyContributorNames(self::docBookBibliographyContributorSummaries($entry, ['author']));
    }

    /**
     * @param list<string> $localNames
     * @return list<array{element:string, value:string}>
     */
    private static function docBookBibliographyTextRecords(\DOMElement $root, array $localNames): array
    {
        $records = [];
        foreach (self::docBookBibliographyElementsWithLocalNames($root, $localNames, false) as $element) {
            $value = self::normalizedText($element);
            if ($value === '') {
                continue;
            }

            $records[] = [
                'element' => $element->localName,
                'value' => $value,
            ];
        }

        return $records;
    }

    /**
     * @param list<string> $localNames
     * @return list<array{element:string, role:string, name:string}>
     */
    private static function docBookBibliographyContributorSummaries(\DOMElement $entry, array $localNames): array
    {
        $contributors = [];
        foreach (self::docBookBibliographyElementsWithLocalNames($entry, $localNames, false) as $contributor) {
            $name = self::docBookBibliographyContributorName($contributor);
            if ($name === '') {
                continue;
            }

            $contributors[] = [
                'element' => $contributor->localName,
                'role' => $contributor->localName,
                'name' => $name,
            ];
        }

        return $contributors;
    }

    /**
     * @param list<array{element:string, role:string, name:string}> $contributors
     * @return list<string>
     */
    private static function docBookBibliographyContributorNames(array $contributors): array
    {
        return array_values(array_unique(array_map(
            static fn (array $contributor): string => (string) $contributor['name'],
            $contributors
        )));
    }

    private static function docBookBibliographyAuthorName(\DOMElement $author): string
    {
        return self::docBookBibliographyContributorName($author);
    }

    private static function docBookBibliographyContributorName(\DOMElement $author): string
    {
        $personName = self::firstDescendantElement($author, 'personname');
        if ($personName instanceof \DOMElement) {
            $name = self::docBookBibliographyStructuredPersonName($personName);
            if ($name !== '') {
                return $name;
            }
        }

        foreach (['orgname', 'corpname'] as $localName) {
            $element = self::firstDescendantElement($author, $localName);
            if ($element instanceof \DOMElement) {
                $text = self::normalizedText($element);
                if ($text !== '') {
                    return $text;
                }
            }
        }

        $parts = [];
        foreach (['honorific', 'firstname', 'givenname', 'othername', 'surname', 'lineage'] as $localName) {
            $text = self::docBookBibliographyFirstDescendantText($author, [$localName]);
            if ($text !== null) {
                $parts[] = $text;
            }
        }

        return trim(implode(' ', $parts)) ?: self::normalizedText($author);
    }

    private static function docBookBibliographyStructuredPersonName(\DOMElement $personName): string
    {
        $parts = [];
        foreach (['honorific', 'firstname', 'givenname', 'othername', 'surname', 'lineage'] as $localName) {
            $text = self::docBookBibliographyFirstDescendantText($personName, [$localName]);
            if ($text !== null) {
                $parts[] = $text;
            }
        }

        return trim(implode(' ', $parts)) ?: self::normalizedText($personName);
    }

    /**
     * @return list<array{element:string, name:string, text:string}>
     */
    private static function docBookBibliographyPublisherSummaries(\DOMElement $entry): array
    {
        $publishers = [];
        foreach (self::docBookBibliographyElementsWithLocalNames($entry, ['publisher'], false) as $publisher) {
            $name = self::docBookBibliographyFirstDescendantText($publisher, ['publishername', 'orgname', 'corpname'])
                ?? self::normalizedText($publisher);
            if ($name === '') {
                continue;
            }

            $publishers[] = [
                'element' => $publisher->localName,
                'name' => $name,
                'text' => self::normalizedText($publisher),
            ];
        }

        foreach (self::docBookBibliographyElementsWithLocalNames($entry, ['publishername'], false) as $publisherName) {
            $parent = $publisherName->parentNode;
            if ($parent instanceof \DOMElement && $parent->localName === 'publisher') {
                continue;
            }

            $name = self::normalizedText($publisherName);
            if ($name === '') {
                continue;
            }

            $publishers[] = [
                'element' => $publisherName->localName,
                'name' => $name,
                'text' => $name,
            ];
        }

        return $publishers;
    }

    /**
     * @return list<array{parentElement:string, parentId:?string, childName:string, childText:string}>
     */
    private static function docBookBibliographyUnsupportedChildSummaries(\DOMElement $root): array
    {
        $summaries = [];
        foreach (self::docBookBibliographyElementsWithLocalNames($root, ['bibliography', 'bibliodiv', 'biblioentry', 'bibliomixed']) as $parent) {
            $allowedChildren = self::docBookBibliographySupportedChildren($parent->localName);
            foreach (self::childElements($parent) as $child) {
                if (isset($allowedChildren[$child->localName])) {
                    continue;
                }

                $summaries[] = [
                    'parentElement' => $parent->localName,
                    'parentId' => self::docBookBibliographyElementId($parent),
                    'childName' => $child->localName,
                    'childText' => self::docBookBibliographyTextSnippet($child),
                ];
            }
        }

        return $summaries;
    }

    /**
     * @return array<string, true>
     */
    private static function docBookBibliographySupportedChildren(string $parentName): array
    {
        $containerChildren = [
            'bibliodiv' => true,
            'biblioentry' => true,
            'bibliomixed' => true,
            'blockinfo' => true,
            'info' => true,
            'subtitle' => true,
            'title' => true,
            'titleabbrev' => true,
        ];
        if ($parentName === 'bibliography' || $parentName === 'bibliodiv') {
            return $containerChildren;
        }

        return [
            'abbrev' => true,
            'address' => true,
            'affiliation' => true,
            'artpagenums' => true,
            'author' => true,
            'authorgroup' => true,
            'authorinitials' => true,
            'bibliomisc' => true,
            'biblioset' => true,
            'bibliosource' => true,
            'citetitle' => true,
            'collab' => true,
            'confgroup' => true,
            'contractnum' => true,
            'contractsponsor' => true,
            'contrib' => true,
            'copyright' => true,
            'corpauthor' => true,
            'corpcredit' => true,
            'corpname' => true,
            'date' => true,
            'edition' => true,
            'editor' => true,
            'firstname' => true,
            'holder' => true,
            'honorific' => true,
            'invpartnumber' => true,
            'isbn' => true,
            'issn' => true,
            'issuenum' => true,
            'jobtitle' => true,
            'lineage' => true,
            'link' => true,
            'orgname' => true,
            'othercredit' => true,
            'othername' => true,
            'pagenums' => true,
            'personblurb' => true,
            'personname' => true,
            'printhistory' => true,
            'productname' => true,
            'productnumber' => true,
            'pubdate' => true,
            'publisher' => true,
            'publishername' => true,
            'pubsnumber' => true,
            'releaseinfo' => true,
            'revhistory' => true,
            'seriesvolnums' => true,
            'surname' => true,
            'title' => true,
            'titleabbrev' => true,
            'ulink' => true,
            'uri' => true,
            'volumenum' => true,
            'year' => true,
        ];
    }

    /**
     * @param list<string> $localNames
     * @return list<\DOMElement>
     */
    private static function docBookBibliographyElementsWithLocalNames(\DOMElement $root, array $localNames, bool $includeSelf = true): array
    {
        $nameSet = array_fill_keys($localNames, true);
        $elements = [];
        if ($includeSelf && isset($nameSet[$root->localName])) {
            $elements[] = $root;
        }

        foreach (self::descendantElements($root) as $element) {
            if (isset($nameSet[$element->localName])) {
                $elements[] = $element;
            }
        }

        return $elements;
    }

    private static function docBookBibliographyElementId(\DOMElement $element): ?string
    {
        $id = self::attribute($element, 'id', 'http://www.w3.org/XML/1998/namespace')
            ?? self::attribute($element, 'id');
        if ($id === null || trim($id) === '') {
            return null;
        }

        return trim($id);
    }

    /**
     * @param list<string> $localNames
     */
    private static function docBookBibliographyFirstDescendantText(\DOMElement $root, array $localNames): ?string
    {
        foreach ($localNames as $localName) {
            $element = self::firstDescendantElement($root, $localName);
            if (!$element instanceof \DOMElement) {
                continue;
            }

            $text = self::normalizedText($element);
            if ($text !== '') {
                return $text;
            }
        }

        return null;
    }

    private static function docBookBibliographyCitationTarget(\DOMElement $citation): ?string
    {
        $target = self::normalizedText($citation);
        if ($target === '') {
            return null;
        }

        $target = preg_replace('/^\[(.*)\]$/u', '$1', $target) ?? $target;
        $target = trim($target);

        return $target === '' ? null : $target;
    }

    private static function docBookBibliographyNormalizedAttribute(\DOMElement $element, string $localName, ?string $namespace = null): ?string
    {
        $value = self::attribute($element, $localName, $namespace);
        if ($value === null || trim($value) === '') {
            return null;
        }

        return trim($value);
    }

    /**
     * @param list<array<string, mixed>> $entries
     * @return list<array<string, mixed>>
     */
    private static function docBookBibliographyEntryMetadataDiagnostics(array $entries): array
    {
        $diagnostics = [];
        foreach ($entries as $entry) {
            $entryIndex = (int) ($entry['entryIndex'] ?? 0);
            $entryId = is_string($entry['id'] ?? null) ? (string) $entry['id'] : null;

            if ($entryId === null || $entryId === '') {
                self::appendDocBookBibliographyEntryMetadataDiagnostic($diagnostics, $entryIndex, $entryId, 'docbook-bibliography-entry-missing-id', 'id');
            }
            if (($entry['idConflict'] ?? false) === true) {
                self::appendDocBookBibliographyEntryMetadataDiagnostic($diagnostics, $entryIndex, $entryId, 'docbook-bibliography-entry-conflicting-id', 'id');
            }

            $titleValues = array_map(
                static fn (array $record): string => (string) $record['value'],
                is_array($entry['titleMetadata'] ?? null) ? $entry['titleMetadata'] : []
            );
            if ($titleValues === []) {
                self::appendDocBookBibliographyEntryMetadataDiagnostic($diagnostics, $entryIndex, $entryId, 'docbook-bibliography-entry-missing-title', 'title');
            } else {
                foreach (self::duplicateStringValues($titleValues) as $duplicate) {
                    self::appendDocBookBibliographyEntryMetadataDiagnostic($diagnostics, $entryIndex, $entryId, 'docbook-bibliography-entry-duplicate-title', 'title', $duplicate);
                }
            }

            $contributors = is_array($entry['contributors'] ?? null) ? $entry['contributors'] : [];
            if ($contributors === []) {
                self::appendDocBookBibliographyEntryMetadataDiagnostic($diagnostics, $entryIndex, $entryId, 'docbook-bibliography-entry-missing-contributor', 'contributor');
            } else {
                $contributorKeys = array_map(
                    static fn (array $contributor): string => (string) $contributor['role'] . ':' . (string) $contributor['name'],
                    $contributors
                );
                foreach (self::duplicateStringValues($contributorKeys) as $duplicate) {
                    self::appendDocBookBibliographyEntryMetadataDiagnostic($diagnostics, $entryIndex, $entryId, 'docbook-bibliography-entry-duplicate-contributor', 'contributor', $duplicate);
                }
            }

            $dateValues = array_map(
                static fn (array $record): string => (string) $record['value'],
                is_array($entry['dateMetadata'] ?? null) ? $entry['dateMetadata'] : []
            );
            if ($dateValues === []) {
                self::appendDocBookBibliographyEntryMetadataDiagnostic($diagnostics, $entryIndex, $entryId, 'docbook-bibliography-entry-missing-date', 'date');
            } else {
                foreach (self::duplicateStringValues($dateValues) as $duplicate) {
                    self::appendDocBookBibliographyEntryMetadataDiagnostic($diagnostics, $entryIndex, $entryId, 'docbook-bibliography-entry-duplicate-date', 'date', $duplicate);
                }
            }

            $publisherRecords = is_array($entry['publishers'] ?? null) ? $entry['publishers'] : [];
            $publisherNames = array_map(
                static fn (array $publisher): string => (string) $publisher['name'],
                $publisherRecords
            );
            if ($publisherNames === []) {
                self::appendDocBookBibliographyEntryMetadataDiagnostic($diagnostics, $entryIndex, $entryId, 'docbook-bibliography-entry-missing-publisher', 'publisher');
            } else {
                foreach (self::duplicateStringValues($publisherNames) as $duplicate) {
                    self::appendDocBookBibliographyEntryMetadataDiagnostic($diagnostics, $entryIndex, $entryId, 'docbook-bibliography-entry-duplicate-publisher', 'publisher', $duplicate);
                }
            }
        }

        return $diagnostics;
    }

    /**
     * @param list<array<string, mixed>> $diagnostics
     */
    private static function appendDocBookBibliographyEntryMetadataDiagnostic(
        array &$diagnostics,
        int $entryIndex,
        ?string $entryId,
        string $code,
        string $field,
        ?string $value = null
    ): void {
        $diagnostic = [
            'code' => $code,
            'severity' => str_contains($code, '-missing-') ? 'warning' : 'review',
            'entryIndex' => $entryIndex,
            'entryId' => $entryId,
            'field' => $field,
        ];
        if ($value !== null) {
            $diagnostic['value'] = $value;
        }

        $diagnostics[] = $diagnostic;
    }

    /**
     * @param list<string> $values
     * @return list<string>
     */
    private static function duplicateStringValues(array $values): array
    {
        $counts = [];
        foreach ($values as $value) {
            if ($value === '') {
                continue;
            }

            $counts[$value] = ($counts[$value] ?? 0) + 1;
        }

        return array_values(array_map(
            static fn (int|string $value): string => (string) $value,
            array_keys(array_filter(
            $counts,
            static fn (int $count): bool => $count > 1
            ))
        ));
    }

    private static function docBookBibliographyTextSnippet(\DOMElement $element): string
    {
        $text = self::normalizedText($element);
        if (strlen($text) <= 160) {
            return $text;
        }

        return substr($text, 0, 157) . '...';
    }

    /**
     * @param list<string> $duplicateIds
     * @param list<string> $missingReferenceTargets
     * @param list<array<string, mixed>> $entryMetadataDiagnostics
     * @return list<array<string, mixed>>
     */
    private static function docBookBibliographyDirectReaderDiagnostics(
        int $bibliographyCount,
        int $entryCount,
        array $duplicateIds,
        array $missingReferenceTargets,
        int $unsupportedChildCount,
        array $entryMetadataDiagnostics = []
    ): array {
        $diagnostics = [
            self::docBookBibliographyDirectReaderDiagnostic(
                'direct-reader-unsupported',
                'unsupported',
                'DocBook direct reader parity is not implemented; this packet exposes bounded bibliography/reference diagnostics only.',
                false,
                true,
                ['format' => 'docbook']
            ),
        ];

        if ($bibliographyCount > 0 || $entryCount > 0) {
            $diagnostics[] = self::docBookBibliographyDirectReaderDiagnostic(
                'bibliography-review-only',
                'unsupported',
                'DocBook bibliography entries are inventoried for reference review but are not mapped as full Pandoc citation output.',
                false,
                true,
                ['bibliographyCount' => $bibliographyCount, 'entryCount' => $entryCount]
            );
        }

        if ($duplicateIds !== []) {
            $diagnostics[] = self::docBookBibliographyDirectReaderDiagnostic(
                'bibliography-id-duplicates',
                'warning',
                'DocBook bibliography identifiers contain duplicate values that require reviewer resolution.',
                false,
                true,
                ['duplicateIdCount' => count($duplicateIds), 'duplicateIds' => $duplicateIds]
            );
        }

        if ($missingReferenceTargets !== []) {
            $diagnostics[] = self::docBookBibliographyDirectReaderDiagnostic(
                'reference-targets-missing',
                'warning',
                'DocBook citation or xref targets were not found in the document id index.',
                false,
                true,
                ['missingTargetCount' => count($missingReferenceTargets), 'missingTargets' => $missingReferenceTargets]
            );
        }

        $missingMetadataDiagnostics = array_values(array_filter(
            $entryMetadataDiagnostics,
            static fn (array $diagnostic): bool => str_contains((string) $diagnostic['code'], '-missing-')
        ));
        if ($missingMetadataDiagnostics !== []) {
            $diagnostics[] = self::docBookBibliographyDirectReaderDiagnostic(
                'bibliography-entry-metadata-missing',
                'warning',
                'DocBook bibliography entries are missing bounded review metadata fields.',
                false,
                true,
                [
                    'missingMetadataDiagnosticCount' => count($missingMetadataDiagnostics),
                    'missingMetadataCodes' => array_values(array_unique(array_map(
                        static fn (array $diagnostic): string => (string) $diagnostic['code'],
                        $missingMetadataDiagnostics
                    ))),
                ]
            );
        }

        $duplicateMetadataDiagnostics = array_values(array_filter(
            $entryMetadataDiagnostics,
            static fn (array $diagnostic): bool => str_contains((string) $diagnostic['code'], '-duplicate-')
                || str_contains((string) $diagnostic['code'], '-conflicting-')
        ));
        if ($duplicateMetadataDiagnostics !== []) {
            $diagnostics[] = self::docBookBibliographyDirectReaderDiagnostic(
                'bibliography-entry-metadata-duplicates',
                'warning',
                'DocBook bibliography entries contain duplicate or conflicting bounded metadata fields.',
                false,
                true,
                [
                    'duplicateMetadataDiagnosticCount' => count($duplicateMetadataDiagnostics),
                    'duplicateMetadataCodes' => array_values(array_unique(array_map(
                        static fn (array $diagnostic): string => (string) $diagnostic['code'],
                        $duplicateMetadataDiagnostics
                    ))),
                ]
            );
        }

        if ($unsupportedChildCount > 0) {
            $diagnostics[] = self::docBookBibliographyDirectReaderDiagnostic(
                'unsupported-bibliography-children',
                'unsupported',
                'DocBook bibliography children outside the bounded metadata set were summarized but not converted.',
                false,
                true,
                ['unsupportedChildCount' => $unsupportedChildCount]
            );
        }

        return $diagnostics;
    }

    /**
     * @param array<string, mixed> $details
     * @return array<string, mixed>
     */
    private static function docBookBibliographyDirectReaderDiagnostic(
        string $code,
        string $severity,
        string $message,
        bool $directReaderParity,
        bool $coveredByPacket,
        array $details = []
    ): array {
        return [
            'code' => $code,
            'severity' => $severity,
            'message' => $message,
            'directReaderParity' => $directReaderParity,
            'coveredByPacket' => $coveredByPacket,
            'details' => $details,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    public static function summarizeDocBookStructure(\DOMDocument $dom, string $format = 'docbook'): array
    {
        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement) {
            throw new \InvalidArgumentException('DocBook review packet requires a document element');
        }

        $format = strtolower(trim($format));
        if (!in_array($format, ['docbook', 'docbook4', 'docbook5'], true)) {
            throw new \InvalidArgumentException('DocBook review packet format must be docbook, docbook4, or docbook5');
        }

        $rootName = $root->localName;
        if (!isset(self::DOCBOOK_ROOT_ELEMENTS[$rootName])) {
            throw new \InvalidArgumentException('DocBook review packet root must be a DocBook structural element');
        }

        $metadata = self::docBookMetadataElement($root);
        $sections = self::docBookSectionMetadataSummaries($root);
        $figures = self::docBookElementSummaries($root, ['figure', 'informalfigure']);
        $tables = self::docBookElementSummaries($root, ['table', 'informaltable']);
        $admonitions = self::docBookAdmonitionSummaries($root);
        $contributors = $metadata instanceof \DOMElement ? self::docBookContributorSummaries($metadata) : [];
        $identifiers = $metadata instanceof \DOMElement ? self::docBookIdentifierSummaries($metadata) : [];
        $elementIdMap = self::docBookElementIdMap($root);
        $xrefs = self::docBookCrossReferenceSummaries($root, $elementIdMap);
        [$xrefTargets, $externalTargets] = self::docBookLinkTargets($root);
        $captionTargets = self::docBookCaptionTargetSummaries($root, $xrefs);
        $mediaTargetManifest = self::docBookMediaTargetManifest($root, $xrefs);
        $repeatedRoleCaptionPairs = self::docBookRepeatedRoleCaptionPairs($mediaTargetManifest);
        $captionDiagnostics = self::docBookCaptionDiagnostics($xrefs, $repeatedRoleCaptionPairs);
        $captionCrossReferences = self::docBookCaptionCrossReferences($xrefs);
        $missingCaptionTargets = self::docBookMissingCaptionTargets($xrefs);
        $bibliographyMediaCaptionCrosslinks = self::docBookBibliographyMediaCaptionCrosslinks($xrefs);
        $bibliographyEntries = self::docBookBibliographyEntrySummaries($root);
        $bibliographyMediaObjects = self::docBookBibliographyMediaObjectSummaries($root, $bibliographyEntries);
        $bibliographyMediaCrosslinks = self::docBookBibliographyMediaCrosslinkSummary(
            $bibliographyEntries,
            $xrefs,
            $mediaTargetManifest
        );

        return [
            'formatFamily' => 'xml-html5-docbook-dom',
            'format' => $format,
            'reviewPolicy' => 'docbook-structure-review-only',
            'directReaderParity' => false,
            'unsupportedDiagnostics' => [
                'docbook-direct-reader-incomplete',
                'docbook-body-conversion-review-only',
            ],
            'rootName' => $rootName,
            'rootAttributes' => self::xmlAttributeMap($root),
            'docbookVersion' => self::attribute($root, 'version'),
            'namespaceUri' => $root->namespaceURI,
            'language' => self::attribute($root, 'lang', 'http://www.w3.org/XML/1998/namespace')
                ?? self::attribute($root, 'lang'),
            'metadataRoot' => $metadata instanceof \DOMElement ? $metadata->localName : null,
            'hasMetadata' => $metadata instanceof \DOMElement,
            'title' => self::docBookTitleText($root, $metadata),
            'subtitle' => self::docBookSubtitleText($root, $metadata),
            'abstractText' => $metadata instanceof \DOMElement ? self::docBookFirstText($metadata, ['abstract']) : null,
            'identifiers' => $identifiers,
            'identifierCount' => count($identifiers),
            'contributors' => $contributors,
            'contributorCount' => count($contributors),
            'contributorNames' => array_values(array_map(
                static fn (array $contributor): string => (string) $contributor['name'],
                $contributors
            )),
            'contributorRoles' => array_values(array_unique(array_filter(
                array_map(static fn (array $contributor): ?string => $contributor['role'], $contributors),
                static fn (?string $role): bool => $role !== null && $role !== ''
            ))),
            'sectionCount' => count($sections),
            'sectionTitles' => array_values(array_filter(
                array_map(static fn (array $section): ?string => $section['title'], $sections),
                static fn (?string $title): bool => $title !== null && $title !== ''
            )),
            'sections' => $sections,
            'figureIds' => array_values(array_filter(
                array_map(static fn (array $figure): ?string => $figure['id'], $figures),
                static fn (?string $id): bool => $id !== null && $id !== ''
            )),
            'figureCount' => count($figures),
            'figures' => $figures,
            'tableIds' => array_values(array_filter(
                array_map(static fn (array $table): ?string => $table['id'], $tables),
                static fn (?string $id): bool => $id !== null && $id !== ''
            )),
            'tableCount' => count($tables),
            'tables' => $tables,
            'admonitionIds' => array_values(array_filter(
                array_map(static fn (array $admonition): ?string => $admonition['id'], $admonitions),
                static fn (?string $id): bool => $id !== null && $id !== ''
            )),
            'admonitionCount' => count($admonitions),
            'admonitions' => $admonitions,
            'xrefs' => $xrefs,
            'xrefCount' => count($xrefs),
            'xrefTargets' => $xrefTargets,
            'xrefTargetCount' => count($xrefTargets),
            'externalTargets' => $externalTargets,
            'externalTargetCount' => count($externalTargets),
            'captionCrossReferences' => $captionCrossReferences,
            'captionCrossReferenceCount' => count($captionCrossReferences),
            'captionTargets' => $captionTargets,
            'captionTargetCount' => count($captionTargets),
            'captionTargetIds' => array_values(array_filter(
                array_map(static fn (array $target): ?string => $target['id'], $captionTargets),
                static fn (?string $id): bool => $id !== null && $id !== ''
            )),
            'missingCaptionTargets' => $missingCaptionTargets,
            'missingCaptionTargetCount' => count($missingCaptionTargets),
            'captionDiagnostics' => $captionDiagnostics,
            'captionDiagnosticCodes' => array_values(array_unique(array_map(
                static fn (array $diagnostic): string => (string) $diagnostic['code'],
                $captionDiagnostics
            ))),
            'captionDiagnosticCount' => count($captionDiagnostics),
            'repeatedRoleCaptionPairs' => $repeatedRoleCaptionPairs,
            'repeatedRoleCaptionPairCount' => count($repeatedRoleCaptionPairs),
            'bibliographyMediaCaptionCrosslinks' => $bibliographyMediaCaptionCrosslinks,
            'bibliographyMediaCaptionCrosslinkCount' => count($bibliographyMediaCaptionCrosslinks),
            'mediaTargetManifest' => $mediaTargetManifest,
            'mediaTargetManifestCount' => count($mediaTargetManifest),
            'bibliographyCount' => count(self::descendantElements($root, 'bibliography')),
            'bibliographyEntries' => $bibliographyEntries,
            'bibliographyEntryCount' => count($bibliographyEntries),
            'bibliographyMediaObjects' => $bibliographyMediaObjects,
            'bibliographyMediaObjectCount' => count($bibliographyMediaObjects),
            'bibliographyMediaCrosslinks' => $bibliographyMediaCrosslinks,
            'bibliographyMediaCrosslinkDiagnosticCodes' => $bibliographyMediaCrosslinks['diagnosticCodes'],
            'bibliographyMediaCrosslinkDiagnosticCount' => count($bibliographyMediaCrosslinks['diagnosticCodes']),
            'mediaObjectCount' => count(self::descendantElements($root, 'mediaobject'))
                + count(self::descendantElements($root, 'inlinemediaobject')),
            'imageObjectCount' => count(self::descendantElements($root, 'imageobject')),
            'imageDataRefs' => self::docBookImageDataRefs($root),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    public static function summarizeDocBookSectionMetadata(\DOMDocument $dom): array
    {
        $root = $dom->documentElement;
        if (!$root instanceof \DOMElement) {
            throw new \InvalidArgumentException('DocBook review packet requires a document element');
        }

        $rootName = strtolower($root->localName);
        if (!isset(self::DOCBOOK_ROOT_ELEMENTS[$rootName])) {
            throw new \InvalidArgumentException('DocBook review packet root must be article, book, chapter, appendix, part, preface, or section');
        }

        $sections = self::docBookSectionSummaries($root);
        $sectionTargets = self::docBookSectionTargetIndex($sections);
        $xrefLinkTargets = self::docBookXrefLinkTargets($root, $sectionTargets);
        $diagnostics = array_merge(
            self::docBookSectionDiagnostics($sections),
            self::docBookXrefLinkDiagnostics($xrefLinkTargets)
        );
        $xrefLinkTargetStatusCounts = self::docBookXrefLinkTargetStatusCounts($xrefLinkTargets);

        return [
            'formatFamily' => 'xml-html5-jats-dom',
            'format' => 'docbook',
            'reviewPolicy' => 'docbook-section-title-xref-metadata-review-only',
            'directReaderParity' => false,
            'rootName' => $rootName,
            'rootAttributes' => self::xmlAttributeMap($root),
            'documentVersion' => self::normalizedAttribute($root, 'version'),
            'language' => self::normalizedAttribute($root, 'lang', self::XML_NAMESPACE)
                ?? self::normalizedAttribute($root, 'lang'),
            'title' => self::docBookSectionMetadataTitleText($root),
            'titleSource' => self::docBookTitleSource($root),
            'subtitle' => self::docBookSectionMetadataSubtitleText($root),
            'sectionCount' => count($sections),
            'sectionIds' => array_values(array_filter(
                array_map(static fn (array $section): ?string => $section['id'], $sections),
                static fn (?string $id): bool => $id !== null && $id !== ''
            )),
            'sectionTitles' => array_values(array_filter(
                array_map(static fn (array $section): ?string => $section['title'], $sections),
                static fn (?string $title): bool => $title !== null && $title !== ''
            )),
            'sections' => $sections,
            'xrefLinkTargets' => $xrefLinkTargets,
            'xrefLinkTargetCount' => count($xrefLinkTargets),
            'xrefLinkTargetStatuses' => array_keys($xrefLinkTargetStatusCounts),
            'xrefLinkTargetStatusCounts' => $xrefLinkTargetStatusCounts,
            'xrefLinkResolvedCount' => $xrefLinkTargetStatusCounts['resolved-section'] ?? 0,
            'xrefLinkMissingCount' => $xrefLinkTargetStatusCounts['missing-anchor'] ?? 0,
            'xrefLinkDuplicateCount' => $xrefLinkTargetStatusCounts['duplicate-section-id'] ?? 0,
            'xrefLinkUnsafeCount' => $xrefLinkTargetStatusCounts['unsafe-target'] ?? 0,
            'diagnostics' => $diagnostics,
            'diagnosticCodes' => array_values(array_unique(array_map(
                static fn (array $diagnostic): string => (string) $diagnostic['code'],
                $diagnostics
            ))),
            'missingTitleCount' => count(array_filter(
                $diagnostics,
                static fn (array $diagnostic): bool => ($diagnostic['code'] ?? '') === 'docbook-section-missing-title'
            )),
            'duplicateIdCount' => count(array_filter(
                $diagnostics,
                static fn (array $diagnostic): bool => ($diagnostic['code'] ?? '') === 'docbook-section-duplicate-id'
            )),
        ];
    }

    private static function requireFragmentRoot(\DOMDocument $dom): \DOMElement
    {
        $root = self::fragmentRoot($dom);
        if (!$root instanceof \DOMElement) {
            throw new \InvalidArgumentException('DOM document is not a Pandoc HTML fragment document');
        }

        return $root;
    }

    /**
     * @return array<string, string>
     */
    private static function xmlAttributeMap(\DOMElement $element): array
    {
        $attributes = [];
        foreach ($element->attributes ?? [] as $attribute) {
            if (!$attribute instanceof \DOMAttr) {
                continue;
            }

            $name = $attribute->prefix !== ''
                ? $attribute->prefix . ':' . $attribute->localName
                : $attribute->name;
            $attributes[$name] = $attribute->value;
        }
        ksort($attributes);

        return $attributes;
    }

    /**
     * @return list<array{code:string, severity:string, message:string, directReaderParity:bool, coveredByPacket:bool, details:array<string, int|string|bool>}>
     */
    private static function xmlNamespaceDirectReaderDiagnostics(
        int $declarationCount,
        int $prefixReuseCount,
        int $prefixConflictCount
    ): array {
        $diagnostics = [
            self::xmlNamespaceDirectReaderDiagnostic(
                'direct-reader-unsupported',
                'unsupported',
                'XML direct reader parity is not implemented; this packet exposes bounded namespace declaration diagnostics only.',
                false,
                true,
                ['format' => 'xml']
            ),
            self::xmlNamespaceDirectReaderDiagnostic(
                'namespace-declarations-review-only',
                'metadata',
                'Namespace declaration provenance is summarized for review but is not mapped as a full Pandoc direct reader AST.',
                false,
                true,
                ['namespaceDeclarationCount' => $declarationCount]
            ),
        ];

        if ($prefixReuseCount > 0) {
            $diagnostics[] = self::xmlNamespaceDirectReaderDiagnostic(
                'namespace-prefix-reuse-review-only',
                'metadata',
                'Namespace prefix declarations are grouped to expose scoped prefix reuse without claiming reader parity.',
                false,
                true,
                ['namespacePrefixReuseCount' => $prefixReuseCount]
            );
        }

        if ($prefixConflictCount > 0) {
            $diagnostics[] = self::xmlNamespaceDirectReaderDiagnostic(
                'namespace-prefix-conflict-review-only',
                'warning',
                'Namespace prefixes that bind to multiple namespace URIs are flagged for bounded review only.',
                false,
                true,
                ['namespacePrefixConflictCount' => $prefixConflictCount]
            );
        }

        return $diagnostics;
    }

    /**
     * @param array<string, int|string|bool> $details
     * @return array{code:string, severity:string, message:string, directReaderParity:bool, coveredByPacket:bool, details:array<string, int|string|bool>}
     */
    private static function xmlNamespaceDirectReaderDiagnostic(
        string $code,
        string $severity,
        string $message,
        bool $directReaderParity,
        bool $coveredByPacket,
        array $details = []
    ): array {
        return [
            'code' => $code,
            'severity' => $severity,
            'message' => $message,
            'directReaderParity' => $directReaderParity,
            'coveredByPacket' => $coveredByPacket,
            'details' => $details,
        ];
    }

    /**
     * @return list<\DOMElement>
     */
    private static function xmlElementList(\DOMElement $root): array
    {
        return [$root, ...self::descendantElements($root)];
    }

    /**
     * @param list<\DOMElement> $elements
     * @param list<array<string, mixed>> $declarations
     * @return list<string>
     */
    private static function xmlNamespaceKnownPrefixes(array $elements, array $declarations): array
    {
        $prefixes = ['xml' => true];

        foreach ($declarations as $declaration) {
            $prefix = $declaration['prefix'];
            if (is_string($prefix) && $prefix !== '') {
                $prefixes[$prefix] = true;
            }
        }

        foreach ($elements as $element) {
            $elementPrefix = (string) $element->prefix;
            if ($elementPrefix !== '') {
                $prefixes[$elementPrefix] = true;
            }

            foreach ($element->attributes ?? [] as $attribute) {
                if (!$attribute instanceof \DOMAttr) {
                    continue;
                }

                $attributePrefix = (string) $attribute->prefix;
                if ($attributePrefix !== '' && $attributePrefix !== 'xmlns') {
                    $prefixes[$attributePrefix] = true;
                }
            }
        }

        ksort($prefixes);

        return array_keys($prefixes);
    }

    /**
     * @param list<string> $knownPrefixes
     * @return array<string, mixed>
     */
    private static function xmlNamespaceScopeForElement(\DOMElement $element, array $knownPrefixes): array
    {
        $prefixBindings = [];
        foreach ($knownPrefixes as $prefix) {
            $uri = $element->lookupNamespaceURI($prefix);
            if (is_string($uri) && $uri !== '') {
                $prefixBindings[$prefix] = $uri;
            }
        }
        ksort($prefixBindings);

        $defaultNamespaceUri = $element->lookupNamespaceURI(null);

        return [
            'elementPath' => self::xmlElementPath($element),
            'elementName' => $element->tagName,
            'elementNamespaceUri' => $element->namespaceURI !== '' ? $element->namespaceURI : null,
            'defaultNamespaceUri' => is_string($defaultNamespaceUri) && $defaultNamespaceUri !== '' ? $defaultNamespaceUri : null,
            'prefixBindingCount' => count($prefixBindings),
            'prefixBindings' => $prefixBindings,
        ];
    }

    private static function xmlElementsIncludingRoot(\DOMElement $root): array
    {
        return array_merge([$root], self::descendantElements($root));
    }

    private static function xmlNamespaceUri(?string $namespaceUri): string
    {
        return $namespaceUri ?? '';
    }

    private static function xmlNullableNamespaceUri(?string $namespaceUri): ?string
    {
        return $namespaceUri === null || $namespaceUri === '' ? null : $namespaceUri;
    }

    private static function xmlNamespacePrefix(?string $prefix, bool $defaultForMissing): string
    {
        if ($prefix !== null && $prefix !== '') {
            return $prefix;
        }

        return $defaultForMissing ? 'default' : 'none';
    }

    private static function isXmlNamespaceDeclarationAttribute(\DOMAttr $attribute): bool
    {
        return $attribute->namespaceURI === 'http://www.w3.org/2000/xmlns/'
            || $attribute->nodeName === 'xmlns'
            || str_starts_with($attribute->nodeName, 'xmlns:');
    }

    /**
     * @param array<string, array<string, array{namespaceUri:string, count:int, qualifiedNames:array<string, true>}>> $uses
     */
    private static function appendXmlNamespaceUse(
        array &$uses,
        string $localName,
        string $namespaceUri,
        string $qualifiedName
    ): void {
        if (!isset($uses[$localName][$namespaceUri])) {
            $uses[$localName][$namespaceUri] = [
                'namespaceUri' => $namespaceUri,
                'count' => 0,
                'qualifiedNames' => [],
            ];
        }

        $uses[$localName][$namespaceUri]['count']++;
        $uses[$localName][$namespaceUri]['qualifiedNames'][$qualifiedName] = true;
    }

    /**
     * @param array<string, array<string, array{namespaceUri:string, count:int, qualifiedNames:array<string, true>}>> $uses
     * @return list<array{localName:string, namespaceUris:list<string>, namespaceCount:int, useCount:int, qualifiedNames:list<string>, namespaceUses:list<array{namespaceUri:string, useCount:int, qualifiedNames:list<string>}>}>
     */
    private static function xmlNamespaceUseSummaries(array $uses): array
    {
        $summaries = [];
        ksort($uses, SORT_STRING);

        foreach ($uses as $localName => $namespaceUses) {
            ksort($namespaceUses, SORT_STRING);
            $namespaceUris = [];
            $qualifiedNames = [];
            $useCount = 0;
            $namespaceRows = [];

            foreach ($namespaceUses as $namespaceUse) {
                $namespaceQualifiedNames = array_keys($namespaceUse['qualifiedNames']);
                sort($namespaceQualifiedNames, SORT_STRING);
                $namespaceUris[] = $namespaceUse['namespaceUri'];
                $useCount += $namespaceUse['count'];
                array_push($qualifiedNames, ...$namespaceQualifiedNames);
                $namespaceRows[] = [
                    'namespaceUri' => $namespaceUse['namespaceUri'],
                    'useCount' => $namespaceUse['count'],
                    'qualifiedNames' => array_slice($namespaceQualifiedNames, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS),
                ];
            }

            $qualifiedNames = array_values(array_unique($qualifiedNames));
            sort($qualifiedNames, SORT_STRING);

            $summaries[] = [
                'localName' => $localName,
                'namespaceUris' => $namespaceUris,
                'namespaceCount' => count($namespaceUris),
                'useCount' => $useCount,
                'qualifiedNames' => array_slice($qualifiedNames, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS),
                'namespaceUses' => array_slice($namespaceRows, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS),
            ];
        }

        return array_slice($summaries, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS);
    }

    /**
     * @param array<string, array{value:string, useCount:int, elementUseCount:int, attributeUseCount:int, related:array<string, true>, qualifiedNames:array<string, true>}> $uses
     */
    private static function appendXmlNamespaceFrequencyUse(
        array &$uses,
        string $value,
        string $related,
        string $qualifiedName,
        string $kind
    ): void {
        if (!isset($uses[$value])) {
            $uses[$value] = [
                'value' => $value,
                'useCount' => 0,
                'elementUseCount' => 0,
                'attributeUseCount' => 0,
                'related' => [],
                'qualifiedNames' => [],
            ];
        }

        $uses[$value]['useCount']++;
        if ($kind === 'element') {
            $uses[$value]['elementUseCount']++;
        } elseif ($kind === 'attribute') {
            $uses[$value]['attributeUseCount']++;
        }
        $uses[$value]['related'][$related] = true;
        $uses[$value]['qualifiedNames'][$qualifiedName] = true;
    }

    /**
     * @param array<string, array{value:string, useCount:int, elementUseCount:int, attributeUseCount:int, related:array<string, true>, qualifiedNames:array<string, true>}> $uses
     * @return list<array<string, mixed>>
     */
    private static function xmlNamespaceFrequencySummaries(
        array $uses,
        string $valueKey,
        string $relatedKey,
        string $relatedCountKey,
        bool $sortByUseCount = false
    ): array {
        $summaries = [];
        ksort($uses, SORT_STRING);

        foreach ($uses as $use) {
            $related = array_keys($use['related']);
            $qualifiedNames = array_keys($use['qualifiedNames']);
            sort($related, SORT_STRING);
            sort($qualifiedNames, SORT_STRING);

            $summaries[] = [
                $valueKey => $use['value'],
                $relatedKey => array_slice($related, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS),
                $relatedCountKey => count($related),
                'useCount' => $use['useCount'],
                'elementUseCount' => $use['elementUseCount'],
                'attributeUseCount' => $use['attributeUseCount'],
                'qualifiedNames' => array_slice($qualifiedNames, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS),
            ];
        }

        if ($sortByUseCount) {
            usort(
                $summaries,
                static function (array $left, array $right) use ($valueKey): int {
                    $useCountComparison = ((int) $right['useCount']) <=> ((int) $left['useCount']);
                    if ($useCountComparison !== 0) {
                        return $useCountComparison;
                    }

                    $elementUseComparison = ((int) $right['elementUseCount']) <=> ((int) $left['elementUseCount']);
                    if ($elementUseComparison !== 0) {
                        return $elementUseComparison;
                    }

                    $attributeUseComparison = ((int) $right['attributeUseCount']) <=> ((int) $left['attributeUseCount']);
                    if ($attributeUseComparison !== 0) {
                        return $attributeUseComparison;
                    }

                    return strcmp((string) ($left[$valueKey] ?? ''), (string) ($right[$valueKey] ?? ''));
                }
            );
        }

        return array_slice($summaries, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS);
    }

    /**
     * @param list<array<string, mixed>> $uriFrequencies
     * @return list<array<string, mixed>>
     */
    private static function xmlNamespaceUriAliasSummaries(array $uriFrequencies): array
    {
        $aliases = [];
        foreach ($uriFrequencies as $frequency) {
            if (($frequency['namespaceUri'] ?? '') === '' || ($frequency['prefixCount'] ?? 0) < 2) {
                continue;
            }

            $aliases[] = $frequency;
        }

        return array_slice($aliases, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS);
    }

    /**
     * @param list<array<string, mixed>> $prefixFrequencies
     * @return list<array<string, mixed>>
     */
    private static function xmlNamespacePrefixAliasSummaries(array $prefixFrequencies): array
    {
        $aliases = [];
        foreach ($prefixFrequencies as $frequency) {
            if (($frequency['namespaceUriCount'] ?? 0) < 2) {
                continue;
            }

            $aliases[] = $frequency;
        }

        return array_slice($aliases, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS);
    }

    /**
     * @param array<string, array<string, array{namespaceUri:string, count:int, qualifiedNames:array<string, true>}>> $uses
     * @return list<array{localName:string, namespaceUris:list<string>, namespaceCount:int, useCount:int, qualifiedNames:list<string>, namespaceUses:list<array{namespaceUri:string, useCount:int, qualifiedNames:list<string>}>}>
     */
    private static function xmlNamespaceCollisionSummaries(array $uses): array
    {
        $summaries = [];
        ksort($uses, SORT_STRING);

        foreach ($uses as $localName => $namespaceUses) {
            if (count($namespaceUses) < 2) {
                continue;
            }

            ksort($namespaceUses, SORT_STRING);
            $namespaceUris = [];
            $qualifiedNames = [];
            $useCount = 0;
            $namespaceRows = [];

            foreach ($namespaceUses as $namespaceUse) {
                $namespaceQualifiedNames = array_keys($namespaceUse['qualifiedNames']);
                sort($namespaceQualifiedNames, SORT_STRING);
                $namespaceUris[] = $namespaceUse['namespaceUri'];
                $useCount += $namespaceUse['count'];
                array_push($qualifiedNames, ...$namespaceQualifiedNames);
                $namespaceRows[] = [
                    'namespaceUri' => $namespaceUse['namespaceUri'],
                    'useCount' => $namespaceUse['count'],
                    'qualifiedNames' => array_slice($namespaceQualifiedNames, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS),
                ];
            }

            $qualifiedNames = array_values(array_unique($qualifiedNames));
            sort($qualifiedNames, SORT_STRING);

            $summaries[] = [
                'localName' => $localName,
                'namespaceUris' => $namespaceUris,
                'namespaceCount' => count($namespaceUris),
                'useCount' => $useCount,
                'qualifiedNames' => array_slice($qualifiedNames, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS),
                'namespaceUses' => array_slice($namespaceRows, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS),
            ];
        }

        return array_slice($summaries, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS);
    }

    private static function xmlElementPath(\DOMElement $element): string
    {
        $segments = [];
        $current = $element;
        while ($current instanceof \DOMElement) {
            $index = 1;
            $sibling = $current->previousSibling;
            while ($sibling !== null) {
                if ($sibling instanceof \DOMElement && $sibling->tagName === $current->tagName) {
                    ++$index;
                }
                $sibling = $sibling->previousSibling;
            }

            array_unshift($segments, $current->tagName . '[' . $index . ']');
            $parent = $current->parentNode;
            $current = $parent instanceof \DOMElement ? $parent : null;
        }

        return implode('/', $segments);
    }

    private static function xmlElementUsagePath(\DOMElement $element): string
    {
        $segments = [];
        $node = $element;

        while ($node instanceof \DOMElement) {
            $index = 1;
            $sibling = $node->previousSibling;
            while ($sibling instanceof \DOMNode) {
                if ($sibling instanceof \DOMElement && $sibling->tagName === $node->tagName) {
                    $index++;
                }
                $sibling = $sibling->previousSibling;
            }

            $segments[] = $node->tagName . '[' . $index . ']';
            $node = $node->parentNode instanceof \DOMElement ? $node->parentNode : null;
        }

        return '/' . implode('/', array_reverse($segments));
    }

    /**
     * @return array<string, mixed>
     */
    private static function xmlNamespaceSourceUsageSummary(string $xmlSource, string $sourceMode): array
    {
        $declarations = [];
        $unboundUses = [];
        $reservedUses = [];
        $stack = [];
        $rootCounts = [];
        $elementIndex = 0;
        $elementNameUseCount = 0;
        $attributeNameUseCount = 0;

        preg_match_all(
            '/<\s*(\/)?\s*([A-Za-z_][A-Za-z0-9_.:-]*)((?:[^>"\']+|"[^"]*"|\'[^\']*\')*?)(\/)?\s*>/s',
            $xmlSource,
            $matches,
            PREG_SET_ORDER
        );

        foreach ($matches as $match) {
            $closing = ($match[1] ?? '') === '/';
            $elementName = (string) $match[2];

            if ($closing) {
                array_pop($stack);
                continue;
            }

            ++$elementIndex;
            if ($stack === []) {
                $rootCounts[$elementName] = ($rootCounts[$elementName] ?? 0) + 1;
                $elementPath = $elementName . '[' . $rootCounts[$elementName] . ']';
                $bindings = [
                    'xml' => [
                        'uri' => self::XML_NAMESPACE,
                        'declarationIndex' => null,
                    ],
                ];
            } else {
                $parentIndex = count($stack) - 1;
                $childCounts = $stack[$parentIndex]['childCounts'];
                $childCounts[$elementName] = ($childCounts[$elementName] ?? 0) + 1;
                $stack[$parentIndex]['childCounts'] = $childCounts;
                $elementPath = $stack[$parentIndex]['path'] . '/' . $elementName . '[' . $childCounts[$elementName] . ']';
                $bindings = $stack[$parentIndex]['bindings'];
            }

            $attributeSource = (string) ($match[3] ?? '');
            preg_match_all(
                '/\s(xmlns(?::([A-Za-z_][A-Za-z0-9_.:-]*))?)\s*=\s*(?:"([^"]*)"|\'([^\']*)\')/s',
                $attributeSource,
                $namespaceAttributeMatches,
                PREG_SET_ORDER
            );

            foreach ($namespaceAttributeMatches as $attributeMatch) {
                $prefix = isset($attributeMatch[2]) && $attributeMatch[2] !== '' ? $attributeMatch[2] : null;
                $prefixLabel = $prefix ?? 'default';
                $rawUri = $attributeMatch[3] !== '' ? $attributeMatch[3] : ($attributeMatch[4] ?? '');
                $uri = html_entity_decode($rawUri, ENT_QUOTES | ENT_XML1, 'UTF-8');
                $declarationIndex = count($declarations);
                $declarations[] = [
                    'name' => $attributeMatch[1],
                    'prefix' => $prefix,
                    'prefixLabel' => $prefixLabel,
                    'uri' => $uri,
                    'rawUri' => $rawUri,
                    'default' => $prefix === null,
                    'elementName' => $elementName,
                    'elementPath' => $elementPath,
                    'elementIndex' => $elementIndex,
                    'usedCount' => 0,
                ];

                $bindings[$prefixLabel] = [
                    'uri' => $uri,
                    'declarationIndex' => $declarationIndex,
                ];
            }

            ++$elementNameUseCount;
            self::recordXmlNamespaceSourceNameUse(
                $elementName,
                'element',
                $elementPath,
                $bindings,
                $declarations,
                $unboundUses,
                $reservedUses
            );

            preg_match_all(
                '/\s([A-Za-z_][A-Za-z0-9_.:-]*)\s*=\s*(?:"[^"]*"|\'[^\']*\')/s',
                $attributeSource,
                $attributeMatches,
                PREG_SET_ORDER
            );

            foreach ($attributeMatches as $attributeMatch) {
                $attributeName = (string) $attributeMatch[1];
                if ($attributeName === 'xmlns' || str_starts_with($attributeName, 'xmlns:')) {
                    continue;
                }

                ++$attributeNameUseCount;
                self::recordXmlNamespaceSourceNameUse(
                    $attributeName,
                    'attribute',
                    $elementPath,
                    $bindings,
                    $declarations,
                    $unboundUses,
                    $reservedUses
                );
            }

            $selfClosing = ($match[4] ?? '') === '/';
            if (!$selfClosing) {
                $stack[] = [
                    'name' => $elementName,
                    'path' => $elementPath,
                    'childCounts' => [],
                    'bindings' => $bindings,
                ];
            }
        }

        $unusedDeclarations = array_values(array_filter(
            $declarations,
            static fn (array $declaration): bool => (int) $declaration['usedCount'] === 0
        ));
        $unboundPrefixes = self::uniqueSortedStrings(array_map(
            static fn (array $use): string => (string) $use['prefix'],
            $unboundUses
        ));
        $reservedCodes = self::uniqueSortedStrings(array_map(
            static fn (array $use): string => (string) $use['code'],
            $reservedUses
        ));

        return [
            'reviewPolicy' => 'xml-namespace-source-usage-review-only',
            'directReaderParity' => false,
            'sourceMode' => $sourceMode,
            'namespaceSourceElementUseCount' => $elementNameUseCount,
            'namespaceSourceAttributeUseCount' => $attributeNameUseCount,
            'namespaceSourceDeclarationCount' => count($declarations),
            'unboundNamespacePrefixUseCount' => count($unboundUses),
            'unboundNamespacePrefixes' => $unboundPrefixes,
            'unboundNamespacePrefixUses' => array_slice($unboundUses, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS),
            'unusedNamespaceDeclarationCount' => count($unusedDeclarations),
            'unusedNamespaceDeclarations' => array_slice($unusedDeclarations, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS),
            'reservedNamespaceUseCount' => count($reservedUses),
            'reservedNamespaceUseCodes' => $reservedCodes,
            'reservedNamespaceUses' => array_slice($reservedUses, 0, self::XML_NAMESPACE_REVIEW_MAX_ITEMS),
        ];
    }

    /**
     * @param array<string, array{uri:string, declarationIndex:int|null}> $bindings
     * @param list<array<string, mixed>> $declarations
     * @param list<array{prefix:string, kind:string, name:string, elementPath:string}> $unboundUses
     * @param list<array<string, mixed>> $reservedUses
     */
    private static function recordXmlNamespaceSourceNameUse(
        string $qualifiedName,
        string $kind,
        string $elementPath,
        array $bindings,
        array &$declarations,
        array &$unboundUses,
        array &$reservedUses
    ): void {
        if (!str_contains($qualifiedName, ':')) {
            if ($kind === 'element' && isset($bindings['default'])) {
                self::markXmlNamespaceSourceDeclarationUse($declarations, $bindings['default']['declarationIndex']);
                self::recordXmlNamespaceReservedUriUse(
                    $reservedUses,
                    (string) $bindings['default']['uri'],
                    'default',
                    $kind,
                    $qualifiedName,
                    $elementPath
                );
            }

            return;
        }

        [$prefix] = explode(':', $qualifiedName, 2);
        if ($prefix === '') {
            return;
        }

        if (!isset($bindings[$prefix]) || (string) $bindings[$prefix]['uri'] === '') {
            $unboundUses[] = [
                'prefix' => $prefix,
                'kind' => $kind,
                'name' => $qualifiedName,
                'elementPath' => $elementPath,
            ];

            return;
        }

        $uri = (string) $bindings[$prefix]['uri'];
        self::markXmlNamespaceSourceDeclarationUse($declarations, $bindings[$prefix]['declarationIndex']);

        if ($prefix === 'xml') {
            $reservedUses[] = self::xmlNamespaceReservedUse(
                'reserved-xml-prefix-use',
                'info',
                'The reserved xml prefix is used and must remain bound to the XML namespace URI.',
                $prefix,
                $uri,
                $kind,
                $qualifiedName,
                $elementPath
            );
        } elseif ($prefix === 'xmlns') {
            $reservedUses[] = self::xmlNamespaceReservedUse(
                'reserved-xmlns-prefix-use',
                'error',
                'The reserved xmlns prefix must not be used as an element or attribute prefix.',
                $prefix,
                $uri,
                $kind,
                $qualifiedName,
                $elementPath
            );
        }

        self::recordXmlNamespaceReservedUriUse($reservedUses, $uri, $prefix, $kind, $qualifiedName, $elementPath);
    }

    /**
     * @param list<array<string, mixed>> $declarations
     */
    private static function markXmlNamespaceSourceDeclarationUse(array &$declarations, mixed $declarationIndex): void
    {
        if (!is_int($declarationIndex) || !isset($declarations[$declarationIndex])) {
            return;
        }

        $declarations[$declarationIndex]['usedCount'] = (int) $declarations[$declarationIndex]['usedCount'] + 1;
    }

    /**
     * @param list<array<string, mixed>> $reservedUses
     */
    private static function recordXmlNamespaceReservedUriUse(
        array &$reservedUses,
        string $uri,
        string $prefix,
        string $kind,
        string $qualifiedName,
        string $elementPath
    ): void {
        if ($uri === self::XML_NAMESPACE && $prefix !== 'xml') {
            $reservedUses[] = self::xmlNamespaceReservedUse(
                'reserved-xml-uri-use',
                'error',
                'The XML namespace URI is used through a non-xml prefix or default namespace.',
                $prefix,
                $uri,
                $kind,
                $qualifiedName,
                $elementPath
            );
        }

        if ($uri === self::XMLNS_NAMESPACE) {
            $reservedUses[] = self::xmlNamespaceReservedUse(
                'reserved-xmlns-uri-use',
                'error',
                'The xmlns namespace URI is used through an XML element or attribute name.',
                $prefix,
                $uri,
                $kind,
                $qualifiedName,
                $elementPath
            );
        }
    }

    /**
     * @return array{code:string, severity:string, message:string, prefix:string, namespaceUri:string, kind:string, name:string, elementPath:string, directReaderParity:bool}
     */
    private static function xmlNamespaceReservedUse(
        string $code,
        string $severity,
        string $message,
        string $prefix,
        string $namespaceUri,
        string $kind,
        string $name,
        string $elementPath
    ): array {
        return [
            'code' => $code,
            'severity' => $severity,
            'message' => $message,
            'prefix' => $prefix,
            'namespaceUri' => $namespaceUri,
            'kind' => $kind,
            'name' => $name,
            'elementPath' => $elementPath,
            'directReaderParity' => false,
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function xmlNamespaceDeclarationRecords(string $xmlSource): array
    {
        $records = [];
        $stack = [];
        $rootCounts = [];
        $elementIndex = 0;

        preg_match_all(
            '/<\s*(\/)?\s*([A-Za-z_][A-Za-z0-9_.:-]*)((?:[^>"\']+|"[^"]*"|\'[^\']*\')*?)(\/)?\s*>/s',
            $xmlSource,
            $matches,
            PREG_SET_ORDER
        );

        foreach ($matches as $match) {
            $closing = ($match[1] ?? '') === '/';
            $elementName = $match[2];

            if ($closing) {
                array_pop($stack);
                continue;
            }

            ++$elementIndex;
            if ($stack === []) {
                $rootCounts[$elementName] = ($rootCounts[$elementName] ?? 0) + 1;
                $elementPath = $elementName . '[' . $rootCounts[$elementName] . ']';
            } else {
                $parentIndex = count($stack) - 1;
                $childCounts = $stack[$parentIndex]['childCounts'];
                $childCounts[$elementName] = ($childCounts[$elementName] ?? 0) + 1;
                $stack[$parentIndex]['childCounts'] = $childCounts;
                $elementPath = $stack[$parentIndex]['path'] . '/' . $elementName . '[' . $childCounts[$elementName] . ']';
            }

            $attributeSource = $match[3] ?? '';
            preg_match_all(
                '/\s(xmlns(?::([A-Za-z_][A-Za-z0-9_.:-]*))?)\s*=\s*(?:"([^"]*)"|\'([^\']*)\')/s',
                $attributeSource,
                $attributeMatches,
                PREG_SET_ORDER
            );

            foreach ($attributeMatches as $attributeMatch) {
                $prefix = isset($attributeMatch[2]) && $attributeMatch[2] !== '' ? $attributeMatch[2] : null;
                $rawUri = $attributeMatch[3] !== '' ? $attributeMatch[3] : ($attributeMatch[4] ?? '');
                $uri = html_entity_decode($rawUri, ENT_QUOTES | ENT_XML1, 'UTF-8');

                $records[] = [
                    'name' => $attributeMatch[1],
                    'prefix' => $prefix,
                    'prefixLabel' => $prefix ?? 'default',
                    'uri' => $uri,
                    'rawUri' => $rawUri,
                    'default' => $prefix === null,
                    'elementName' => $elementName,
                    'elementPath' => $elementPath,
                    'elementIndex' => $elementIndex,
                ];
            }

            $selfClosing = ($match[4] ?? '') === '/';
            if (!$selfClosing) {
                $stack[] = [
                    'name' => $elementName,
                    'path' => $elementPath,
                    'childCounts' => [],
                ];
            }
        }

        return $records;
    }

    /**
     * @param list<array<string, mixed>> $declarations
     * @return array<string, mixed>
     */
    private static function xmlNamespaceCollisionSummary(array $declarations): array
    {
        $byPrefix = [];
        $byUri = [];

        foreach ($declarations as $declaration) {
            $prefixLabel = (string) $declaration['prefixLabel'];
            $uri = (string) $declaration['uri'];

            if (!isset($byPrefix[$prefixLabel])) {
                $byPrefix[$prefixLabel] = [
                    'prefix' => $prefixLabel,
                    'declarationCount' => 0,
                    'uris' => [],
                    'declarations' => [],
                ];
            }
            ++$byPrefix[$prefixLabel]['declarationCount'];
            $byPrefix[$prefixLabel]['uris'][$uri] = true;
            $byPrefix[$prefixLabel]['declarations'][] = [
                'uri' => $uri,
                'elementPath' => $declaration['elementPath'],
                'elementName' => $declaration['elementName'],
            ];

            if (!isset($byUri[$uri])) {
                $byUri[$uri] = [
                    'uri' => $uri,
                    'declarationCount' => 0,
                    'prefixes' => [],
                    'declarations' => [],
                ];
            }
            ++$byUri[$uri]['declarationCount'];
            $byUri[$uri]['prefixes'][$prefixLabel] = true;
            $byUri[$uri]['declarations'][] = [
                'prefix' => $prefixLabel,
                'elementPath' => $declaration['elementPath'],
                'elementName' => $declaration['elementName'],
            ];
        }

        ksort($byPrefix);
        ksort($byUri);

        $duplicatePrefixSummaries = [];
        $prefixRedefinitions = [];
        foreach ($byPrefix as $prefixSummary) {
            $uris = array_keys($prefixSummary['uris']);
            sort($uris);
            $summary = [
                'prefix' => $prefixSummary['prefix'],
                'declarationCount' => $prefixSummary['declarationCount'],
                'uriCount' => count($uris),
                'uris' => $uris,
                'declarations' => $prefixSummary['declarations'],
            ];

            if ($summary['declarationCount'] > 1) {
                $duplicatePrefixSummaries[] = $summary;
            }
            if ($summary['uriCount'] > 1) {
                $prefixRedefinitions[] = $summary;
            }
        }

        $duplicateUriSummaries = [];
        foreach ($byUri as $uriSummary) {
            $prefixes = array_keys($uriSummary['prefixes']);
            sort($prefixes);
            if (count($prefixes) <= 1) {
                continue;
            }

            $duplicateUriSummaries[] = [
                'uri' => $uriSummary['uri'],
                'declarationCount' => $uriSummary['declarationCount'],
                'prefixCount' => count($prefixes),
                'prefixes' => $prefixes,
                'declarations' => $uriSummary['declarations'],
            ];
        }

        return [
            'prefixRedefinitionCount' => count($prefixRedefinitions),
            'prefixRedefinitions' => $prefixRedefinitions,
            'duplicatePrefixSummaryCount' => count($duplicatePrefixSummaries),
            'duplicatePrefixSummaries' => $duplicatePrefixSummaries,
            'duplicateUriSummaryCount' => count($duplicateUriSummaries),
            'duplicateUriSummaries' => $duplicateUriSummaries,
        ];
    }

    /**
     * @param array<string, mixed> $collisionSummary
     * @param list<array<string, mixed>> $declarations
     * @return list<array<string, mixed>>
     */
    private static function xmlNamespaceDiagnostics(array $collisionSummary, array $declarations): array
    {
        $diagnostics = [];

        if ($collisionSummary['prefixRedefinitionCount'] > 0) {
            $diagnostics[] = self::xmlNamespaceDiagnostic(
                'prefix-redefinition',
                'warning',
                'One or more namespace prefixes are rebound to multiple namespace URIs within the XML document.',
                ['prefixRedefinitionCount' => $collisionSummary['prefixRedefinitionCount']]
            );
        }

        if ($collisionSummary['duplicatePrefixSummaryCount'] > 0) {
            $diagnostics[] = self::xmlNamespaceDiagnostic(
                'duplicate-prefix-declarations',
                'info',
                'One or more namespace prefixes are declared multiple times within the XML document.',
                ['duplicatePrefixSummaryCount' => $collisionSummary['duplicatePrefixSummaryCount']]
            );
        }

        if ($collisionSummary['duplicateUriSummaryCount'] > 0) {
            $diagnostics[] = self::xmlNamespaceDiagnostic(
                'duplicate-uri-bindings',
                'info',
                'One or more namespace URIs are bound to multiple prefixes within the XML document.',
                ['duplicateUriSummaryCount' => $collisionSummary['duplicateUriSummaryCount']]
            );
        }

        foreach ($declarations as $declaration) {
            $prefix = $declaration['prefix'];
            $prefixLabel = (string) $declaration['prefixLabel'];
            $uri = (string) $declaration['uri'];
            $details = [
                'prefix' => $prefixLabel,
                'uri' => $uri,
                'elementPath' => $declaration['elementPath'],
                'elementName' => $declaration['elementName'],
            ];

            if ($prefix === 'xml' && $uri !== self::XML_NAMESPACE) {
                $diagnostics[] = self::xmlNamespaceDiagnostic(
                    'reserved-xml-prefix-rebound',
                    'error',
                    'The reserved xml prefix must remain bound to the XML namespace URI.',
                    $details
                );
            }

            if ($prefix === null && $uri === self::XML_NAMESPACE) {
                $diagnostics[] = self::xmlNamespaceDiagnostic(
                    'reserved-xml-uri-as-default',
                    'error',
                    'The XML namespace URI must not be used as the default namespace.',
                    $details
                );
            } elseif ($prefix !== 'xml' && $uri === self::XML_NAMESPACE) {
                $diagnostics[] = self::xmlNamespaceDiagnostic(
                    'reserved-xml-uri-bound-to-non-xml-prefix',
                    'error',
                    'The XML namespace URI must not be bound to a non-xml prefix.',
                    $details
                );
            }

            if ($prefix === 'xmlns') {
                $diagnostics[] = self::xmlNamespaceDiagnostic(
                    'reserved-xmlns-prefix-declared',
                    'error',
                    'The reserved xmlns prefix must not be declared as an ordinary namespace prefix.',
                    $details
                );
            }

            if ($uri === self::XMLNS_NAMESPACE) {
                $diagnostics[] = self::xmlNamespaceDiagnostic(
                    'reserved-xmlns-uri-declared',
                    'error',
                    'The xmlns namespace URI must not be assigned by XML namespace declarations.',
                    $details
                );
            }
        }

        return $diagnostics;
    }

    /**
     * @param array<string, mixed> $details
     * @return array<string, mixed>
     */
    private static function xmlNamespaceDiagnostic(string $code, string $severity, string $message, array $details): array
    {
        return [
            'code' => $code,
            'severity' => $severity,
            'message' => $message,
            'directReaderParity' => false,
            'details' => $details,
        ];
    }

    /**
     * @return list<array{code:string, severity:string, message:string, directReaderParity:bool, coveredByPacket:bool, details:array<string, int|string|bool>}>
     */
    private static function xmlDirectReaderDiagnostics(
        int $elementNamespaceCollisionCount,
        int $attributeNamespaceCollisionCount,
        int $defaultNamespaceTransitionCount,
        int $defaultNamespaceUseCount,
        int $sameUriMultiplePrefixCount,
        int $samePrefixMultipleUriCount,
        int $unboundNamespacePrefixUseCount,
        int $unusedNamespaceDeclarationCount,
        int $reservedNamespaceUseCount
    ): array {
        $diagnostics = [
            self::xmlDirectReaderDiagnostic(
                'direct-reader-unsupported',
                'unsupported',
                'XML direct reader parity is not implemented; this packet exposes bounded namespace diagnostics only.',
                false,
                true,
                ['format' => 'xml']
            ),
        ];

        if ($elementNamespaceCollisionCount > 0) {
            $diagnostics[] = self::xmlDirectReaderDiagnostic(
                'element-local-name-namespace-collisions',
                'warning',
                'Element local names are reused across namespace URIs and need explicit reader mapping.',
                false,
                true,
                ['collisionCount' => $elementNamespaceCollisionCount]
            );
        }

        if ($attributeNamespaceCollisionCount > 0) {
            $diagnostics[] = self::xmlDirectReaderDiagnostic(
                'attribute-local-name-namespace-collisions',
                'warning',
                'Attribute local names are reused across namespace URIs and need explicit reader mapping.',
                false,
                true,
                ['collisionCount' => $attributeNamespaceCollisionCount]
            );
        }

        if ($defaultNamespaceTransitionCount > 0) {
            $diagnostics[] = self::xmlDirectReaderDiagnostic(
                'default-namespace-transitions',
                'info',
                'Default namespace bindings change within the document and are preserved for review.',
                false,
                true,
                ['transitionCount' => $defaultNamespaceTransitionCount]
            );
        }

        if ($defaultNamespaceUseCount > 0) {
            $diagnostics[] = self::xmlDirectReaderDiagnostic(
                'default-namespace-usage',
                'info',
                'Unprefixed elements use one or more default namespace bindings and are preserved for review.',
                false,
                true,
                ['useCount' => $defaultNamespaceUseCount]
            );
        }

        if ($sameUriMultiplePrefixCount > 0) {
            $diagnostics[] = self::xmlDirectReaderDiagnostic(
                'namespace-uri-multiple-prefixes',
                'warning',
                'Namespace URIs are referenced through multiple prefixes and need prefix-independent reader mapping.',
                false,
                true,
                ['aliasCount' => $sameUriMultiplePrefixCount]
            );
        }

        if ($samePrefixMultipleUriCount > 0) {
            $diagnostics[] = self::xmlDirectReaderDiagnostic(
                'namespace-prefix-multiple-uris',
                'warning',
                'Namespace prefixes are rebound to multiple namespace URIs and need scope-aware reader mapping.',
                false,
                true,
                ['aliasCount' => $samePrefixMultipleUriCount]
            );
        }

        if ($unboundNamespacePrefixUseCount > 0) {
            $diagnostics[] = self::xmlDirectReaderDiagnostic(
                'unbound-namespace-prefix-uses',
                'error',
                'Source-level namespace scanning found prefixed element or attribute names without an in-scope namespace binding.',
                false,
                true,
                ['useCount' => $unboundNamespacePrefixUseCount]
            );
        }

        if ($unusedNamespaceDeclarationCount > 0) {
            $diagnostics[] = self::xmlDirectReaderDiagnostic(
                'unused-namespace-declarations',
                'info',
                'Namespace declarations that are not used by element or attribute names are summarized for review.',
                false,
                true,
                ['declarationCount' => $unusedNamespaceDeclarationCount]
            );
        }

        if ($reservedNamespaceUseCount > 0) {
            $diagnostics[] = self::xmlDirectReaderDiagnostic(
                'reserved-namespace-usage',
                'warning',
                'Reserved xml/xmlns namespace prefix or URI usage is preserved as metadata-only diagnostics.',
                false,
                true,
                ['useCount' => $reservedNamespaceUseCount]
            );
        }

        return $diagnostics;
    }

    /**
     * @param array<string, int|string|bool> $details
     * @return array{code:string, severity:string, message:string, directReaderParity:bool, coveredByPacket:bool, details:array<string, int|string|bool>}
     */
    private static function xmlDirectReaderDiagnostic(
        string $code,
        string $severity,
        string $message,
        bool $directReaderParity,
        bool $coveredByPacket,
        array $details = []
    ): array {
        return [
            'code' => $code,
            'severity' => $severity,
            'message' => $message,
            'directReaderParity' => $directReaderParity,
            'coveredByPacket' => $coveredByPacket,
            'details' => $details,
        ];
    }

    /**
     * @return list<array{element:\DOMElement, path:string, depth:int}>
     */
    private static function xmlElementWalk(\DOMElement $root): array
    {
        $entries = [];
        $stack = [[
            'element' => $root,
            'path' => '/' . self::xmlQualifiedName($root),
            'depth' => 0,
        ]];

        while ($stack !== []) {
            $entry = array_pop($stack);
            if (!is_array($entry) || !$entry['element'] instanceof \DOMElement) {
                continue;
            }

            $element = $entry['element'];
            $path = (string) $entry['path'];
            $depth = (int) $entry['depth'];
            $entries[] = [
                'element' => $element,
                'path' => $path,
                'depth' => $depth,
            ];

            $children = [];
            $siblingCounts = [];
            foreach ($element->childNodes as $child) {
                if (!$child instanceof \DOMElement) {
                    continue;
                }

                $name = self::xmlQualifiedName($child);
                $siblingCounts[$name] = ($siblingCounts[$name] ?? 0) + 1;
                $children[] = [
                    'element' => $child,
                    'path' => $path . '/' . $name . '[' . $siblingCounts[$name] . ']',
                    'depth' => $depth + 1,
                ];
            }

            for ($index = count($children) - 1; $index >= 0; --$index) {
                $stack[] = $children[$index];
            }
        }

        return $entries;
    }

    private static function xmlQualifiedName(\DOMElement $element): string
    {
        $prefix = $element->prefix;
        if (is_string($prefix) && $prefix !== '') {
            return $prefix . ':' . $element->localName;
        }

        return $element->localName !== '' ? $element->localName : $element->tagName;
    }

    private static function isXmlNamespaceDeclaration(\DOMAttr $attribute): bool
    {
        return ($attribute->namespaceURI ?? '') === 'http://www.w3.org/2000/xmlns/'
            || $attribute->name === 'xmlns'
            || str_starts_with($attribute->name, 'xmlns:');
    }

    private static function xmlNamespaceNodePrefix(object $node): string
    {
        return $node->nodeName === 'xmlns' || $node->localName === 'xmlns' ? '' : $node->localName;
    }

    /**
     * @param list<array{prefix:string, namespaceUri:string, attributeName:string, elementPath:string, depth:int, defaultNamespace:bool, observedAs:string}> $declarations
     * @param array<string, true> $declarationKeys
     */
    private static function recordXmlNamespaceDeclaration(
        array &$declarations,
        array &$declarationKeys,
        string $prefix,
        string $namespaceUri,
        string $elementPath,
        int $depth,
        string $observedAs
    ): void {
        if ($namespaceUri === '' || $prefix === 'xml') {
            return;
        }

        $key = $prefix . "\0" . $namespaceUri;
        if (isset($declarationKeys[$key])) {
            return;
        }
        $declarationKeys[$key] = true;

        $declarations[] = [
            'prefix' => $prefix,
            'namespaceUri' => $namespaceUri,
            'attributeName' => $prefix === '' ? 'xmlns' : 'xmlns:' . $prefix,
            'elementPath' => $elementPath,
            'depth' => $depth,
            'defaultNamespace' => $prefix === '',
            'observedAs' => $observedAs,
        ];
    }

    /**
     * @param list<array{prefix:string, namespaceUri:string, attributeName:string, elementPath:string, depth:int, defaultNamespace:bool, observedAs:string}> $declarations
     */
    private static function sortXmlNamespaceDeclarations(array &$declarations): void
    {
        usort(
            $declarations,
            static function (array $left, array $right): int {
                $pathComparison = strcmp($left['elementPath'], $right['elementPath']);
                if ($pathComparison !== 0) {
                    return $pathComparison;
                }

                return strcmp($left['prefix'], $right['prefix']);
            }
        );
    }

    /**
     * @param list<array{prefix:string, namespaceUri:string, attributeName:string, elementPath:string, depth:int, defaultNamespace:bool, observedAs:string}> $declarations
     * @return array<string, array{prefix:string, defaultNamespace:bool, declarationCount:int, namespaceUris:list<string>, elementPaths:list<string>, declarations:list<array{prefix:string, namespaceUri:string, attributeName:string, elementPath:string, depth:int, defaultNamespace:bool, observedAs:string}>}>
     */
    private static function xmlNamespaceDeclarationSummaryByPrefix(array $declarations): array
    {
        $byPrefix = [];
        foreach ($declarations as $declaration) {
            $prefix = $declaration['prefix'];
            $byPrefix[$prefix] ??= [
                'prefix' => $prefix,
                'defaultNamespace' => $prefix === '',
                'declarationCount' => 0,
                'namespaceUris' => [],
                'elementPaths' => [],
                'declarations' => [],
            ];

            ++$byPrefix[$prefix]['declarationCount'];
            $byPrefix[$prefix]['namespaceUris'][] = $declaration['namespaceUri'];
            $byPrefix[$prefix]['elementPaths'][] = $declaration['elementPath'];
            $byPrefix[$prefix]['declarations'][] = $declaration;
        }

        foreach ($byPrefix as &$summary) {
            $summary['namespaceUris'] = self::uniqueSortedStrings($summary['namespaceUris']);
            $summary['elementPaths'] = array_values(array_unique($summary['elementPaths']));
        }
        unset($summary);

        uksort(
            $byPrefix,
            static fn (string $left, string $right): int => $left === ''
                ? ($right === '' ? 0 : -1)
                : ($right === '' ? 1 : strcmp($left, $right))
        );

        return $byPrefix;
    }

    /**
     * @param list<array{prefix:string, namespaceUri:string, attributeName:string, elementPath:string, depth:int, defaultNamespace:bool, observedAs:string}> $declarations
     * @return list<string>
     */
    private static function xmlNamespaceUris(array $declarations): array
    {
        return self::uniqueSortedStrings(array_map(
            static fn (array $declaration): string => $declaration['namespaceUri'],
            $declarations
        ));
    }

    /**
     * @param list<string> $values
     * @return list<string>
     */
    private static function uniqueSortedStrings(array $values): array
    {
        $values = array_values(array_unique($values));
        sort($values, SORT_STRING);

        return $values;
    }

    private static function jatsMetadataElement(\DOMElement $root): ?\DOMElement
    {
        foreach (['article-meta', 'book-meta', 'book-part-meta'] as $name) {
            $metadata = self::firstDescendantElement($root, $name);
            if ($metadata instanceof \DOMElement) {
                return $metadata;
            }
        }

        return null;
    }

    private static function jatsBodyElement(\DOMElement $root): ?\DOMElement
    {
        foreach (['body', 'book-body'] as $name) {
            $body = self::firstChildElement($root, $name);
            if ($body instanceof \DOMElement) {
                return $body;
            }
        }

        foreach (['body', 'book-body'] as $name) {
            $body = self::firstDescendantElement($root, $name);
            if ($body instanceof \DOMElement) {
                return $body;
            }
        }

        return null;
    }

    private static function jatsBackMatterElement(\DOMElement $root): ?\DOMElement
    {
        $names = match ($root->localName) {
            'book' => ['book-back', 'back'],
            'book-part' => ['book-part-back', 'back', 'book-back'],
            default => ['back', 'book-back', 'book-part-back'],
        };

        foreach ($names as $name) {
            $backMatter = self::firstChildElement($root, $name);
            if ($backMatter instanceof \DOMElement) {
                return $backMatter;
            }
        }

        foreach ($names as $name) {
            $backMatter = self::firstDescendantElement($root, $name);
            if ($backMatter instanceof \DOMElement) {
                return $backMatter;
            }
        }

        return null;
    }

    private static function jatsDocumentType(\DOMElement $root): ?string
    {
        foreach (['article-type', 'book-type', 'book-part-type'] as $name) {
            $value = self::attribute($root, $name);
            if ($value !== null && trim($value) !== '') {
                return trim($value);
            }
        }

        return null;
    }

    private static function docBookMetadataElement(\DOMElement $root): ?\DOMElement
    {
        $legacyName = $root->localName . 'info';
        foreach (self::childElements($root) as $child) {
            if ($child->localName === 'info' || $child->localName === $legacyName) {
                return $child;
            }
        }

        return null;
    }

    private static function docBookTitleText(\DOMElement $root, ?\DOMElement $metadata): ?string
    {
        if ($metadata instanceof \DOMElement) {
            $title = self::docBookFirstText($metadata, ['title']);
            if ($title !== null) {
                return $title;
            }
        }

        $title = self::firstChildElement($root, 'title');

        return $title instanceof \DOMElement ? self::normalizedText($title) : null;
    }

    private static function docBookSubtitleText(\DOMElement $root, ?\DOMElement $metadata): ?string
    {
        if ($metadata instanceof \DOMElement) {
            $subtitle = self::docBookFirstText($metadata, ['subtitle']);
            if ($subtitle !== null) {
                return $subtitle;
            }
        }

        $subtitle = self::firstChildElement($root, 'subtitle');

        return $subtitle instanceof \DOMElement ? self::normalizedText($subtitle) : null;
    }

    /**
     * @param list<string> $localNames
     */
    private static function docBookFirstText(\DOMElement $root, array $localNames): ?string
    {
        foreach ($localNames as $localName) {
            $element = self::firstDescendantElement($root, $localName);
            if (!$element instanceof \DOMElement) {
                continue;
            }

            $text = self::normalizedText($element);
            if ($text !== '') {
                return $text;
            }
        }

        return null;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function docBookSectionMetadataSummaries(\DOMElement $root): array
    {
        $sections = [];
        foreach (self::descendantElements($root) as $section) {
            if (!isset(self::DOCBOOK_SECTION_ELEMENTS[$section->localName])) {
                continue;
            }

            $sections[] = [
                'element' => $section->localName,
                'id' => self::docBookSectionMetadataElementId($section),
                'role' => self::attribute($section, 'role'),
                'title' => self::docBookChildTitleText($section),
                'paragraphCount' => self::docBookParagraphCount($section),
                'directParagraphCount' => self::docBookDirectParagraphCount($section),
                'childSectionCount' => self::docBookChildSectionCount($section),
                'figureCount' => count(self::docBookElementsByNames($section, ['figure', 'informalfigure'])),
                'tableCount' => count(self::docBookElementsByNames($section, ['table', 'informaltable'])),
                'admonitionCount' => count(self::docBookAdmonitionElements($section)),
            ];
        }

        return $sections;
    }

    private static function docBookElementId(\DOMElement $element): ?string
    {
        $id = self::attribute($element, 'id')
            ?? self::attribute($element, 'id', 'http://www.w3.org/XML/1998/namespace');

        return $id === null || trim($id) === '' ? null : trim($id);
    }

    /**
     * @return array<string, \DOMElement>
     */
    private static function docBookElementIdMap(\DOMElement $root): array
    {
        $map = [];
        foreach ([$root, ...self::descendantElements($root)] as $element) {
            $id = self::docBookElementId($element);
            if ($id === null || isset($map[$id])) {
                continue;
            }

            $map[$id] = $element;
        }

        return $map;
    }

    private static function docBookChildTitleText(\DOMElement $element): ?string
    {
        $title = self::firstChildElement($element, 'title');
        if (!$title instanceof \DOMElement) {
            $info = self::firstChildElement($element, 'info');
            $title = $info instanceof \DOMElement ? self::firstChildElement($info, 'title') : null;
        }

        if (!$title instanceof \DOMElement) {
            return null;
        }

        $text = self::normalizedText($title);

        return $text === '' ? null : $text;
    }

    private static function docBookChildCaptionText(\DOMElement $element): ?string
    {
        $caption = self::firstChildElement($element, 'caption');
        if (!$caption instanceof \DOMElement
            && in_array($element->localName, ['figure', 'informalfigure', 'mediaobject', 'inlinemediaobject'], true)
        ) {
            $caption = self::firstDescendantElement($element, 'caption');
        }

        if (!$caption instanceof \DOMElement) {
            return null;
        }

        $text = self::docBookReviewText(self::normalizedText($caption));

        return $text === '' ? null : $text;
    }

    private static function docBookCaptionText(\DOMElement $element): ?string
    {
        $caption = self::docBookChildCaptionText($element);
        if ($caption !== null) {
            return $caption;
        }

        if ($element->localName === 'caption' || $element->localName === 'title') {
            $text = self::docBookReviewText(self::normalizedText($element));

            return $text === '' ? null : $text;
        }

        return self::docBookChildTitleText($element);
    }

    private static function docBookCaptionSource(\DOMElement $element): ?string
    {
        if (self::docBookChildCaptionText($element) !== null) {
            return 'caption';
        }

        if ($element->localName === 'caption' || $element->localName === 'title') {
            return $element->localName;
        }

        return self::docBookChildTitleText($element) !== null ? 'title' : null;
    }

    private static function docBookReviewText(string $text): string
    {
        if (strlen($text) <= self::DOCBOOK_REVIEW_TEXT_MAX_BYTES) {
            return $text;
        }

        return rtrim(substr($text, 0, self::DOCBOOK_REVIEW_TEXT_MAX_BYTES)) . '...';
    }

    private static function docBookParagraphCount(\DOMElement $element): int
    {
        return count(self::descendantElements($element, 'para'))
            + count(self::descendantElements($element, 'simpara'));
    }

    private static function docBookDirectParagraphCount(\DOMElement $element): int
    {
        $count = 0;
        foreach (self::childElements($element) as $child) {
            if ($child->localName === 'para' || $child->localName === 'simpara') {
                $count++;
            }
        }

        return $count;
    }

    private static function docBookChildSectionCount(\DOMElement $element): int
    {
        $count = 0;
        foreach (self::childElements($element) as $child) {
            if (isset(self::DOCBOOK_SECTION_ELEMENTS[$child->localName])) {
                $count++;
            }
        }

        return $count;
    }

    /**
     * @param list<string> $localNames
     * @return list<\DOMElement>
     */
    private static function docBookElementsByNames(\DOMElement $root, array $localNames): array
    {
        $nameMap = array_fill_keys($localNames, true);
        $elements = [];
        foreach (self::descendantElements($root) as $element) {
            if (isset($nameMap[$element->localName])) {
                $elements[] = $element;
            }
        }

        return $elements;
    }

    /**
     * @param list<string> $localNames
     * @return list<array{element:string, id:?string, role:?string, title:?string, caption:?string, captionText:?string, captionSource:?string, imageDataRefs:list<string>}>
     */
    private static function docBookElementSummaries(\DOMElement $root, array $localNames): array
    {
        $summaries = [];
        foreach (self::docBookElementsByNames($root, $localNames) as $element) {
            $caption = self::docBookChildCaptionText($element);
            $summaries[] = [
                'element' => $element->localName,
                'id' => self::docBookElementId($element),
                'role' => self::attribute($element, 'role'),
                'title' => self::docBookChildTitleText($element),
                'caption' => $caption,
                'captionText' => $caption ?? self::docBookChildTitleText($element),
                'captionSource' => self::docBookCaptionSource($element),
                'imageDataRefs' => self::docBookImageDataRefs($element),
            ];
        }

        return $summaries;
    }

    private static function docBookTargetKind(\DOMElement $element): string
    {
        return match ($element->localName) {
            'figure', 'informalfigure' => 'figure',
            'mediaobject', 'inlinemediaobject', 'imageobject', 'imagedata' => 'media',
            'biblioentry', 'bibliomixed', 'biblioset' => 'bibliography',
            'caption' => 'caption',
            'title' => 'title',
            'table', 'informaltable' => 'table',
            default => isset(self::DOCBOOK_SECTION_ELEMENTS[$element->localName])
                ? 'section'
                : $element->localName,
        };
    }

    /**
     * @return list<\DOMElement>
     */
    private static function docBookAdmonitionElements(\DOMElement $root): array
    {
        $elements = [];
        foreach (self::descendantElements($root) as $element) {
            if (isset(self::DOCBOOK_ADMONITION_ELEMENTS[$element->localName])) {
                $elements[] = $element;
            }
        }

        return $elements;
    }

    /**
     * @return list<array{id:?string, type:string, title:?string, paragraphCount:int}>
     */
    private static function docBookAdmonitionSummaries(\DOMElement $root): array
    {
        $summaries = [];
        foreach (self::docBookAdmonitionElements($root) as $element) {
            $summaries[] = [
                'id' => self::docBookElementId($element),
                'type' => $element->localName,
                'title' => self::docBookChildTitleText($element),
                'paragraphCount' => self::docBookParagraphCount($element),
            ];
        }

        return $summaries;
    }

    /**
     * @return list<array{element:string, type:?string, value:string}>
     */
    private static function docBookIdentifierSummaries(\DOMElement $metadata): array
    {
        $records = [];
        foreach (['biblioid', 'isbn', 'issn', 'pubsnumber'] as $localName) {
            foreach (self::descendantElements($metadata, $localName) as $element) {
                $value = self::normalizedText($element);
                if ($value === '') {
                    continue;
                }

                $records[] = [
                    'element' => $localName,
                    'type' => self::attribute($element, 'class') ?? self::attribute($element, 'otherclass'),
                    'value' => $value,
                ];
            }
        }

        return $records;
    }

    /**
     * @return list<array{role:?string, name:string}>
     */
    private static function docBookContributorSummaries(\DOMElement $metadata): array
    {
        $contributors = [];
        foreach (self::descendantElements($metadata) as $element) {
            if (!in_array($element->localName, ['author', 'editor', 'othercredit', 'collab'], true)) {
                continue;
            }

            $name = self::docBookContributorName($element);
            if ($name === '') {
                continue;
            }

            $contributors[] = [
                'role' => $element->localName === 'othercredit'
                    ? (self::attribute($element, 'class') ?? 'othercredit')
                    : $element->localName,
                'name' => $name,
            ];
        }

        return $contributors;
    }

    private static function docBookContributorName(\DOMElement $contributor): string
    {
        $parts = [];
        foreach (['firstname', 'othername', 'surname'] as $namePart) {
            $part = self::firstDescendantElement($contributor, $namePart);
            if ($part instanceof \DOMElement) {
                $text = self::normalizedText($part);
                if ($text !== '') {
                    $parts[] = $text;
                }
            }
        }
        if ($parts !== []) {
            return implode(' ', $parts);
        }

        $personName = self::firstDescendantElement($contributor, 'personname');
        if ($personName instanceof \DOMElement) {
            $text = self::normalizedText($personName);
            if ($text !== '') {
                return $text;
            }
        }

        foreach (['orgname', 'collabname'] as $localName) {
            $element = self::firstDescendantElement($contributor, $localName);
            if ($element instanceof \DOMElement) {
                $text = self::normalizedText($element);
                if ($text !== '') {
                    return $text;
                }
            }
        }

        return self::normalizedText($contributor);
    }

    /**
     * @return array{0:list<string>, 1:list<string>}
     */
    private static function docBookLinkTargets(\DOMElement $root): array
    {
        $xrefTargets = [];
        $externalTargets = [];
        $elements = [$root, ...self::descendantElements($root)];
        foreach ($elements as $element) {
            foreach (['linkend', 'endterm'] as $attribute) {
                $target = self::attribute($element, $attribute);
                if ($target === null) {
                    continue;
                }

                foreach (self::spaceSeparatedTokens($target) as $token) {
                    $xrefTargets[] = $token;
                }
            }

            $href = self::attribute($element, 'href', 'http://www.w3.org/1999/xlink');
            if ($href === null || trim($href) === '') {
                continue;
            }

            $href = trim($href);
            if (str_starts_with($href, '#')) {
                $xrefTargets[] = substr($href, 1);
                continue;
            }

            $externalTargets[] = $href;
        }

        return [
            array_values(array_unique($xrefTargets)),
            array_values(array_unique($externalTargets)),
        ];
    }

    /**
     * @param array<string, \DOMElement> $elementIdMap
     * @return list<array<string, mixed>>
     */
    private static function docBookCrossReferenceSummaries(\DOMElement $root, array $elementIdMap): array
    {
        $xrefs = [];
        foreach ([$root, ...self::descendantElements($root)] as $element) {
            foreach (self::docBookElementReferenceTargets($element) as $reference) {
                $target = $reference['target'];
                $targetElement = $elementIdMap[$target] ?? null;
                $sourceBibliography = self::docBookNearestAncestorByNames($element, ['biblioentry', 'bibliomixed', 'biblioset']);
                $sourceMedia = self::docBookNearestAncestorByNames($element, ['figure', 'informalfigure', 'mediaobject', 'inlinemediaobject']);
                $targetCaptionText = $targetElement instanceof \DOMElement ? self::docBookCaptionText($targetElement) : null;

                $xrefs[] = [
                    'sourceElement' => $element->localName,
                    'sourceId' => self::docBookElementId($element),
                    'sourceRole' => self::attribute($element, 'role'),
                    'sourceText' => self::docBookReviewText(self::normalizedText($element)),
                    'sourceBibliographyId' => $sourceBibliography instanceof \DOMElement
                        ? self::docBookElementId($sourceBibliography)
                        : null,
                    'sourceMediaId' => $sourceMedia instanceof \DOMElement
                        ? self::docBookElementId($sourceMedia)
                        : null,
                    'attribute' => $reference['attribute'],
                    'target' => $target,
                    'resolved' => $targetElement instanceof \DOMElement,
                    'missingTargets' => $targetElement instanceof \DOMElement ? [] : [$target],
                    'targetElement' => $targetElement instanceof \DOMElement ? $targetElement->localName : null,
                    'targetKind' => $targetElement instanceof \DOMElement ? self::docBookTargetKind($targetElement) : null,
                    'targetId' => $targetElement instanceof \DOMElement ? self::docBookElementId($targetElement) : null,
                    'targetRole' => $targetElement instanceof \DOMElement ? self::attribute($targetElement, 'role') : null,
                    'targetTitle' => $targetElement instanceof \DOMElement ? self::docBookChildTitleText($targetElement) : null,
                    'targetCaption' => $targetElement instanceof \DOMElement ? self::docBookChildCaptionText($targetElement) : null,
                    'targetCaptionText' => $targetCaptionText,
                    'targetCaptionSource' => $targetElement instanceof \DOMElement
                        ? self::docBookCaptionSource($targetElement)
                        : null,
                    'targetImageDataRefs' => $targetElement instanceof \DOMElement
                        ? self::docBookImageDataRefs($targetElement)
                        : [],
                ];
            }
        }

        return $xrefs;
    }

    /**
     * @return list<array{attribute:string, target:string}>
     */
    private static function docBookElementReferenceTargets(\DOMElement $element): array
    {
        $references = [];
        foreach (['linkend', 'endterm'] as $attribute) {
            $target = self::attribute($element, $attribute);
            if ($target === null) {
                continue;
            }

            foreach (self::spaceSeparatedTokens($target) as $token) {
                $references[] = ['attribute' => $attribute, 'target' => $token];
            }
        }

        $href = self::attribute($element, 'href', 'http://www.w3.org/1999/xlink');
        if ($href !== null && str_starts_with(trim($href), '#')) {
            $references[] = ['attribute' => 'xlink:href', 'target' => substr(trim($href), 1)];
        }

        return $references;
    }

    /**
     * @param list<string> $localNames
     */
    private static function docBookNearestAncestorByNames(\DOMElement $element, array $localNames): ?\DOMElement
    {
        $nameMap = array_fill_keys($localNames, true);
        $parent = $element->parentNode;
        while ($parent instanceof \DOMElement) {
            if (isset($nameMap[$parent->localName])) {
                return $parent;
            }

            $parent = $parent->parentNode;
        }

        return null;
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return array<string, int>
     */
    private static function docBookReferenceCountsByTarget(array $xrefs): array
    {
        $counts = [];
        foreach ($xrefs as $xref) {
            $target = (string) $xref['target'];
            $counts[$target] = ($counts[$target] ?? 0) + 1;
        }

        return $counts;
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return list<array<string, mixed>>
     */
    private static function docBookCaptionCrossReferences(array $xrefs): array
    {
        return array_values(array_filter(
            $xrefs,
            static fn (array $xref): bool => !($xref['resolved'] ?? false)
                || in_array($xref['targetKind'] ?? null, ['figure', 'media', 'caption', 'title', 'bibliography'], true)
                || ($xref['targetCaptionText'] ?? null) !== null
        ));
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return list<string>
     */
    private static function docBookMissingCaptionTargets(array $xrefs): array
    {
        $targets = [];
        foreach ($xrefs as $xref) {
            if ($xref['resolved'] ?? false) {
                continue;
            }

            $targets[] = (string) $xref['target'];
        }

        return array_values(array_unique($targets));
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return list<array<string, mixed>>
     */
    private static function docBookCaptionTargetSummaries(\DOMElement $root, array $xrefs): array
    {
        $counts = self::docBookReferenceCountsByTarget($xrefs);
        $targets = [];
        foreach (self::docBookElementsByNames($root, ['figure', 'informalfigure', 'mediaobject', 'inlinemediaobject', 'biblioentry', 'bibliomixed']) as $element) {
            $id = self::docBookElementId($element);
            $captionText = self::docBookCaptionText($element);
            if ($id === null && $captionText === null) {
                continue;
            }

            $targets[] = [
                'element' => $element->localName,
                'kind' => self::docBookTargetKind($element),
                'id' => $id,
                'role' => self::attribute($element, 'role'),
                'title' => self::docBookChildTitleText($element),
                'caption' => self::docBookChildCaptionText($element),
                'captionText' => $captionText,
                'captionSource' => self::docBookCaptionSource($element),
                'imageDataRefs' => self::docBookImageDataRefs($element),
                'referenceCount' => $id === null ? 0 : ($counts[$id] ?? 0),
                'referenced' => $id !== null && ($counts[$id] ?? 0) > 0,
            ];
        }

        return $targets;
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return list<array<string, mixed>>
     */
    private static function docBookMediaTargetManifest(\DOMElement $root, array $xrefs): array
    {
        $counts = self::docBookReferenceCountsByTarget($xrefs);
        $manifest = [];
        foreach (self::docBookElementsByNames($root, ['figure', 'informalfigure', 'mediaobject', 'inlinemediaobject']) as $element) {
            $id = self::docBookElementId($element);
            $imageDataRefs = self::docBookImageDataRefs($element);
            if ($id === null && $imageDataRefs === []) {
                continue;
            }

            $manifest[] = [
                'element' => $element->localName,
                'id' => $id,
                'role' => self::attribute($element, 'role'),
                'title' => self::docBookChildTitleText($element),
                'caption' => self::docBookChildCaptionText($element),
                'captionText' => self::docBookCaptionText($element),
                'captionSource' => self::docBookCaptionSource($element),
                'imageDataRefs' => $imageDataRefs,
                'referenceCount' => $id === null ? 0 : ($counts[$id] ?? 0),
                'referenced' => $id !== null && ($counts[$id] ?? 0) > 0,
            ];
        }

        return $manifest;
    }

    /**
     * @param list<array<string, mixed>> $mediaTargetManifest
     * @return list<array{role:string, captionText:string, targetIds:list<string>, imageDataRefs:list<string>, count:int}>
     */
    private static function docBookRepeatedRoleCaptionPairs(array $mediaTargetManifest): array
    {
        $groups = [];
        foreach ($mediaTargetManifest as $target) {
            if (!in_array($target['element'] ?? null, ['mediaobject', 'inlinemediaobject'], true)) {
                continue;
            }

            $role = $target['role'] ?? null;
            $captionText = $target['captionText'] ?? null;
            if (!is_string($role) || trim($role) === '' || !is_string($captionText) || trim($captionText) === '') {
                continue;
            }

            $key = trim($role) . "\0" . trim($captionText);
            $groups[$key] ??= [
                'role' => trim($role),
                'captionText' => trim($captionText),
                'targetIds' => [],
                'imageDataRefs' => [],
                'count' => 0,
            ];
            if (is_string($target['id'] ?? null) && $target['id'] !== '') {
                $groups[$key]['targetIds'][] = $target['id'];
            }
            foreach ($target['imageDataRefs'] ?? [] as $ref) {
                if (is_string($ref) && $ref !== '') {
                    $groups[$key]['imageDataRefs'][] = $ref;
                }
            }
            $groups[$key]['count']++;
        }

        $repeated = [];
        foreach ($groups as $group) {
            if ($group['count'] < 2) {
                continue;
            }

            $group['targetIds'] = array_values(array_unique($group['targetIds']));
            $group['imageDataRefs'] = array_values(array_unique($group['imageDataRefs']));
            $repeated[] = $group;
        }

        return $repeated;
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @param list<array<string, mixed>> $repeatedRoleCaptionPairs
     * @return list<array<string, mixed>>
     */
    private static function docBookCaptionDiagnostics(array $xrefs, array $repeatedRoleCaptionPairs): array
    {
        $diagnostics = [];
        foreach ($xrefs as $xref) {
            if (!($xref['resolved'] ?? false)) {
                $diagnostics[] = self::docBookCaptionDiagnostic(
                    'missing-caption-target',
                    'warning',
                    'DocBook cross-reference target is not present in the review packet.',
                    $xref
                );
                continue;
            }

            if (in_array($xref['targetKind'] ?? null, ['figure', 'media'], true)
                && ($xref['targetCaptionText'] ?? null) === null
            ) {
                $diagnostics[] = self::docBookCaptionDiagnostic(
                    'captionless-media-target',
                    'notice',
                    'DocBook media target is referenced without a caption or title summary.',
                    $xref
                );
            }
        }

        foreach ($repeatedRoleCaptionPairs as $pair) {
            $diagnostics[] = [
                'code' => 'repeated-role-caption-pair',
                'severity' => 'notice',
                'message' => 'DocBook media targets share the same role and caption text.',
                'directReaderParity' => false,
                'coveredByPacket' => true,
                'details' => [
                    'role' => $pair['role'] ?? null,
                    'captionText' => $pair['captionText'] ?? null,
                    'targetIds' => $pair['targetIds'] ?? [],
                    'count' => $pair['count'] ?? 0,
                ],
            ];
        }

        return $diagnostics;
    }

    /**
     * @param array<string, mixed> $xref
     * @return array<string, mixed>
     */
    private static function docBookCaptionDiagnostic(
        string $code,
        string $severity,
        string $message,
        array $xref
    ): array {
        return [
            'code' => $code,
            'severity' => $severity,
            'message' => $message,
            'directReaderParity' => false,
            'coveredByPacket' => true,
            'details' => [
                'target' => $xref['target'] ?? null,
                'sourceElement' => $xref['sourceElement'] ?? null,
                'sourceId' => $xref['sourceId'] ?? null,
                'sourceBibliographyId' => $xref['sourceBibliographyId'] ?? null,
                'targetElement' => $xref['targetElement'] ?? null,
                'targetKind' => $xref['targetKind'] ?? null,
            ],
        ];
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return list<array<string, mixed>>
     */
    private static function docBookBibliographyMediaCaptionCrosslinks(array $xrefs): array
    {
        return array_values(array_filter(
            $xrefs,
            static fn (array $xref): bool => ($xref['sourceBibliographyId'] ?? null) !== null
                && in_array($xref['targetKind'] ?? null, ['figure', 'media', 'caption', 'title'], true)
        ));
    }

    /**
     * @param list<array<string, mixed>> $entries
     * @return list<array<string, mixed>>
     */
    private static function docBookBibliographyMediaObjectSummaries(\DOMElement $root, array $entries): array
    {
        $entriesById = self::docBookBibliographyEntriesById($entries);
        $summaries = [];

        foreach (self::docBookElementsByNames($root, ['mediaobject', 'inlinemediaobject']) as $mediaObject) {
            $block = self::docBookNearestAncestorByNames($mediaObject, [
                'biblioentry',
                'bibliodiv',
                'bibliography',
                'bibliomixed',
                'bibliomset',
                'biblioset',
            ]);
            if (!$block instanceof \DOMElement) {
                continue;
            }

            $entry = self::docBookNearestAncestorByNames($mediaObject, ['biblioentry', 'bibliomixed']);
            $entryId = $entry instanceof \DOMElement ? self::docBookBibliographyElementId($entry) : null;
            $entryContext = $entryId !== null && isset($entriesById[$entryId])
                ? self::docBookBibliographyMediaEntryContext($entriesById[$entryId], $entryId)
                : self::docBookBibliographyMediaEntryContext([], $entryId);
            $imageDataRefs = self::docBookImageDataRefs($mediaObject);

            $summaries[] = $entryContext + [
                'element' => $mediaObject->localName,
                'id' => self::docBookElementId($mediaObject),
                'title' => self::docBookChildTitleText($mediaObject),
                'captionText' => self::docBookCaptionText($mediaObject),
                'imageDataRefs' => $imageDataRefs,
                'imageDataRefCount' => count($imageDataRefs),
                'bibliographyBlockElement' => $block->localName,
                'bibliographyBlockId' => self::docBookBibliographyElementId($block),
            ];
        }

        return $summaries;
    }

    /**
     * @param list<array<string, mixed>> $entries
     * @param list<array<string, mixed>> $xrefs
     * @param list<array<string, mixed>> $mediaTargetManifest
     * @return array<string, mixed>
     */
    private static function docBookBibliographyMediaCrosslinkSummary(
        array $entries,
        array $xrefs,
        array $mediaTargetManifest
    ): array {
        $entriesById = self::docBookBibliographyEntriesById($entries);
        [$mediaTargetCounts, $mediaTargetsById] = self::docBookMediaTargetsById($mediaTargetManifest);
        $groups = [];

        foreach ($xrefs as $xref) {
            $entryId = $xref['sourceBibliographyId'] ?? null;
            $target = $xref['target'] ?? null;
            if (!is_string($entryId) || $entryId === '' || !is_string($target) || $target === '') {
                continue;
            }

            $resolved = (bool) ($xref['resolved'] ?? false);
            if ($resolved && !in_array($xref['targetKind'] ?? null, ['figure', 'media'], true)) {
                continue;
            }

            $key = $entryId . "\0" . $target;
            $groups[$key] ??= [
                'entryId' => $entryId,
                'target' => $target,
                'occurrences' => 0,
                'xrefs' => [],
            ];
            ++$groups[$key]['occurrences'];
            $groups[$key]['xrefs'][] = $xref;
        }

        $resolved = [];
        $missing = [];
        $duplicates = [];
        $entriesWithMediaLinks = [];

        foreach ($groups as $group) {
            $entryId = (string) $group['entryId'];
            $target = (string) $group['target'];
            $xref = $group['xrefs'][0] ?? [];
            if (!is_array($xref)) {
                continue;
            }

            self::docBookAppendUniqueString($entriesWithMediaLinks, $entryId);
            $entryContext = self::docBookBibliographyMediaEntryContext($entriesById[$entryId] ?? [], $entryId);
            $manifestTargets = $mediaTargetsById[$target] ?? [];
            $manifestRefs = self::docBookMediaTargetManifestImageDataRefs($manifestTargets);

            if (!($xref['resolved'] ?? false)) {
                $missing[] = $entryContext + [
                    'code' => 'missing-bibliography-media-target',
                    'targetId' => $target,
                    'sourceElement' => $xref['sourceElement'] ?? null,
                    'sourceId' => $xref['sourceId'] ?? null,
                    'attribute' => $xref['attribute'] ?? null,
                ];
                continue;
            }

            if (($mediaTargetCounts[$target] ?? 0) > 1) {
                $duplicates[] = $entryContext + [
                    'code' => 'duplicate-bibliography-media-target-id',
                    'targetId' => $target,
                    'targetCount' => $mediaTargetCounts[$target],
                    'targetElements' => array_values(array_map(
                        static fn (array $manifestTarget): ?string => is_string($manifestTarget['element'] ?? null)
                            ? $manifestTarget['element']
                            : null,
                        $manifestTargets
                    )),
                    'mediaTargetManifestRefs' => $manifestRefs,
                ];
                continue;
            }

            $resolved[] = $entryContext + [
                'targetId' => $target,
                'targetElement' => $xref['targetElement'] ?? null,
                'targetKind' => $xref['targetKind'] ?? null,
                'targetTitle' => $xref['targetTitle'] ?? null,
                'targetCaptionText' => $xref['targetCaptionText'] ?? null,
                'targetImageDataRefs' => $xref['targetImageDataRefs'] ?? [],
                'mediaTargetManifestRefs' => $manifestRefs,
                'mediaTargetManifestRefCount' => count($manifestRefs),
            ];

            if ((int) $group['occurrences'] > 1) {
                $duplicates[] = $entryContext + [
                    'code' => 'duplicate-bibliography-media-crosslink',
                    'targetId' => $target,
                    'occurrences' => (int) $group['occurrences'],
                    'targetKind' => $xref['targetKind'] ?? null,
                    'mediaTargetManifestRefs' => $manifestRefs,
                ];
            }
        }

        $diagnosticCodes = [];
        if ($missing !== []) {
            $diagnosticCodes[] = 'missing-bibliography-media-target';
        }
        foreach (['duplicate-bibliography-media-crosslink', 'duplicate-bibliography-media-target-id'] as $code) {
            foreach ($duplicates as $duplicate) {
                if (($duplicate['code'] ?? null) === $code) {
                    $diagnosticCodes[] = $code;
                    break;
                }
            }
        }

        return [
            'entryCount' => count($entries),
            'entriesWithMediaLinks' => $entriesWithMediaLinks,
            'entriesWithMediaLinkCount' => count($entriesWithMediaLinks),
            'resolved' => $resolved,
            'resolvedCount' => count($resolved),
            'missing' => $missing,
            'missingCount' => count($missing),
            'duplicates' => $duplicates,
            'duplicateCount' => count($duplicates),
            'diagnosticCodes' => $diagnosticCodes,
        ];
    }

    /**
     * @param list<array<string, mixed>> $entries
     * @return array<string, array<string, mixed>>
     */
    private static function docBookBibliographyEntriesById(array $entries): array
    {
        $entriesById = [];
        foreach ($entries as $entry) {
            $id = $entry['id'] ?? null;
            if (is_string($id) && $id !== '' && !isset($entriesById[$id])) {
                $entriesById[$id] = $entry;
            }
        }

        return $entriesById;
    }

    /**
     * @param array<string, mixed> $entry
     * @return array{entryId:?string, entryIndex:?int, entryElement:?string, entryTitle:?string, entryContributorNames:list<string>, entryYear:?string, entryYearLikeValues:list<string>}
     */
    private static function docBookBibliographyMediaEntryContext(array $entry, ?string $fallbackEntryId): array
    {
        $yearLikeValues = array_values(array_filter(
            is_array($entry['yearLikeValues'] ?? null) ? $entry['yearLikeValues'] : [],
            static fn (mixed $value): bool => is_string($value) && $value !== ''
        ));
        $contributorNames = array_values(array_filter(
            is_array($entry['contributorNames'] ?? null) ? $entry['contributorNames'] : [],
            static fn (mixed $value): bool => is_string($value) && $value !== ''
        ));

        return [
            'entryId' => is_string($entry['id'] ?? null) && $entry['id'] !== '' ? $entry['id'] : $fallbackEntryId,
            'entryIndex' => is_int($entry['entryIndex'] ?? null) ? $entry['entryIndex'] : null,
            'entryElement' => is_string($entry['element'] ?? null) ? $entry['element'] : null,
            'entryTitle' => is_string($entry['title'] ?? null) ? $entry['title'] : null,
            'entryContributorNames' => $contributorNames,
            'entryYear' => $yearLikeValues[0] ?? null,
            'entryYearLikeValues' => $yearLikeValues,
        ];
    }

    /**
     * @param list<array<string, mixed>> $mediaTargetManifest
     * @return array{0:array<string, int>, 1:array<string, list<array<string, mixed>>>}
     */
    private static function docBookMediaTargetsById(array $mediaTargetManifest): array
    {
        $counts = [];
        $targetsById = [];

        foreach ($mediaTargetManifest as $target) {
            $id = $target['id'] ?? null;
            if (!is_string($id) || $id === '') {
                continue;
            }

            $counts[$id] = ($counts[$id] ?? 0) + 1;
            $targetsById[$id] ??= [];
            $targetsById[$id][] = $target;
        }

        return [$counts, $targetsById];
    }

    /**
     * @param list<array<string, mixed>> $mediaTargets
     * @return list<string>
     */
    private static function docBookMediaTargetManifestImageDataRefs(array $mediaTargets): array
    {
        $refs = [];
        foreach ($mediaTargets as $target) {
            foreach (is_array($target['imageDataRefs'] ?? null) ? $target['imageDataRefs'] : [] as $ref) {
                self::docBookAppendUniqueString($refs, $ref);
            }
        }

        return $refs;
    }

    /**
     * @return list<string>
     */
    private static function docBookImageDataRefs(\DOMElement $root): array
    {
        $refs = [];
        foreach (self::descendantElements($root, 'imagedata') as $imageData) {
            $ref = self::attribute($imageData, 'fileref')
                ?? self::attribute($imageData, 'href', 'http://www.w3.org/1999/xlink');
            if ($ref !== null && trim($ref) !== '') {
                $refs[] = trim($ref);
            }
        }

        return array_values(array_unique($refs));
    }

    private static function docBookRootLooksLikeDocBook(\DOMElement $root): bool
    {
        if (($root->namespaceURI ?? '') === 'http://docbook.org/ns/docbook') {
            return true;
        }

        return in_array($root->localName, [
            'appendix',
            'article',
            'book',
            'chapter',
            'part',
            'preface',
            'reference',
            'section',
            'sect1',
            'sect2',
            'sect3',
            'sect4',
            'sect5',
            'set',
        ], true);
    }

    /**
     * @return array{count:int, items:list<array<string, mixed>>, truncated:bool}
     */
    private static function docBookStructuralBlockSummaries(\DOMElement $root): array
    {
        $items = [];
        $count = 0;
        foreach (self::descendantElements($root) as $element) {
            if (!isset(self::DOCBOOK_STRUCTURAL_BLOCK_NAMES[$element->localName])) {
                continue;
            }
            ++$count;
            if (count($items) >= self::DOCBOOK_REVIEW_PACKET_MAX_ITEMS) {
                continue;
            }

            $items[] = [
                'name' => $element->localName,
                'path' => self::docBookElementPath($element),
                'parentName' => $element->parentNode instanceof \DOMElement ? $element->parentNode->localName : null,
                'xmlId' => self::docBookXmlId($element),
                'id' => self::attribute($element, 'id'),
                'title' => self::docBookReviewTitleText($element),
                'text' => self::docBookBoundedText($element),
                'childElementNames' => self::docBookChildElementNames($element),
            ];
        }

        return [
            'count' => $count,
            'items' => $items,
            'truncated' => $count > count($items),
        ];
    }

    /**
     * @return array{count:int, items:list<array<string, mixed>>, truncated:bool}
     */
    private static function docBookReviewAdmonitionSummaries(\DOMElement $root): array
    {
        $items = [];
        $count = 0;
        foreach (self::descendantElements($root) as $element) {
            if (!isset(self::DOCBOOK_ADMONITION_ELEMENTS[$element->localName])) {
                continue;
            }
            ++$count;
            if (count($items) >= self::DOCBOOK_REVIEW_PACKET_MAX_ITEMS) {
                continue;
            }

            $items[] = [
                'type' => $element->localName,
                'path' => self::docBookElementPath($element),
                'xmlId' => self::docBookXmlId($element),
                'id' => self::attribute($element, 'id'),
                'title' => self::docBookReviewTitleText($element),
                'text' => self::docBookBoundedText($element),
                'paragraphCount' => self::docBookParagraphCount($element),
                'linkendTargets' => self::docBookLinkendTargets($element),
            ];
        }

        return [
            'count' => $count,
            'items' => $items,
            'truncated' => $count > count($items),
        ];
    }

    /**
     * @return array{count:int, items:list<array<string, mixed>>, truncated:bool}
     */
    private static function docBookFigureSummaries(\DOMElement $root): array
    {
        $items = [];
        $count = 0;
        foreach (self::descendantElements($root) as $element) {
            if (!in_array($element->localName, ['figure', 'informalfigure'], true)) {
                continue;
            }
            ++$count;
            if (count($items) >= self::DOCBOOK_REVIEW_PACKET_MAX_ITEMS) {
                continue;
            }

            $imageDataRefs = self::docBookImageDataReferences($element);
            $items[] = [
                'type' => $element->localName,
                'path' => self::docBookElementPath($element),
                'xmlId' => self::docBookXmlId($element),
                'id' => self::attribute($element, 'id'),
                'title' => self::docBookReviewTitleText($element),
                'mediaObjectCount' => count(self::descendantElements($element, 'mediaobject'))
                    + count(self::descendantElements($element, 'inlinemediaobject')),
                'imageDataRefs' => $imageDataRefs['items'],
                'imageDataRefCount' => $imageDataRefs['count'],
            ];
        }

        return [
            'count' => $count,
            'items' => $items,
            'truncated' => $count > count($items),
        ];
    }

    /**
     * @return array{count:int, items:list<array<string, mixed>>, truncated:bool}
     */
    private static function docBookMediaObjectSummaries(\DOMElement $root): array
    {
        $items = [];
        $count = 0;
        foreach (self::descendantElements($root) as $element) {
            if (!in_array($element->localName, ['mediaobject', 'inlinemediaobject'], true)) {
                continue;
            }
            ++$count;
            if (count($items) >= self::DOCBOOK_REVIEW_PACKET_MAX_ITEMS) {
                continue;
            }

            $figure = self::docBookNearestAncestor($element, ['figure', 'informalfigure']);
            $imageDataRefs = self::docBookImageDataReferences($element);
            $title = self::docBookChildTitleText($element);
            $caption = self::docBookChildCaptionText($element);
            $captionText = $caption ?? $title;
            $textAlternatives = self::docBookReviewTextObjectAlternatives($element);
            $altTexts = self::docBookReviewAltTexts($element);
            $targetRecords = self::docBookReviewMediaTargetRecords($element);
            $roleTargetPairs = [];
            foreach ($targetRecords as $targetRecord) {
                $roleTargetPairs[] = [
                    'role' => $targetRecord['role'],
                    'target' => $targetRecord['target'],
                ];
            }

            $items[] = [
                'type' => $element->localName,
                'path' => self::docBookElementPath($element),
                'xmlId' => self::docBookXmlId($element),
                'id' => self::attribute($element, 'id'),
                'role' => self::normalizedAttribute($element, 'role'),
                'roles' => self::docBookReviewMediaRoles($element),
                'title' => $title,
                'caption' => $caption,
                'captionText' => $captionText,
                'captionSource' => self::docBookCaptionSource($element),
                'hasCaption' => $captionText !== null,
                'textAlternatives' => $textAlternatives,
                'textAlternativeTexts' => array_values(array_map(
                    static fn (array $alternative): string => (string) $alternative['text'],
                    $textAlternatives
                )),
                'textAlternativeCount' => count($textAlternatives),
                'altTexts' => $altTexts,
                'hasTextAlternative' => $textAlternatives !== [] || $altTexts !== [],
                'parentFigureXmlId' => $figure instanceof \DOMElement ? self::docBookXmlId($figure) : null,
                'parentFigureId' => $figure instanceof \DOMElement ? self::attribute($figure, 'id') : null,
                'imageDataRefs' => $imageDataRefs['items'],
                'imageDataRefCount' => $imageDataRefs['count'],
                'targetRecords' => $targetRecords,
                'targetRefs' => self::docBookReviewTargetRefs($targetRecords),
                'targetCount' => count($targetRecords),
                'roleTargetPairs' => $roleTargetPairs,
            ];
        }

        return [
            'count' => $count,
            'items' => $items,
            'truncated' => $count > count($items),
        ];
    }

    /**
     * @param list<array<string, mixed>> $mediaObjects
     * @return list<string>
     */
    private static function docBookMediaObjectStringValues(array $mediaObjects, string $key): array
    {
        $values = [];
        foreach ($mediaObjects as $mediaObject) {
            $value = $mediaObject[$key] ?? null;
            if (is_array($value)) {
                foreach ($value as $item) {
                    if (is_string($item)) {
                        self::docBookAppendUniqueReviewString($values, $item);
                    }
                }
                continue;
            }

            if (is_string($value)) {
                self::docBookAppendUniqueReviewString($values, $value);
            }
        }

        return $values;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function docBookReviewTextObjectAlternatives(\DOMElement $mediaObject): array
    {
        $alternatives = [];
        foreach (self::descendantElements($mediaObject, 'textobject') as $index => $textObject) {
            $text = self::docBookReviewText(self::normalizedText($textObject));
            if ($text === '') {
                continue;
            }

            $alternatives[] = [
                'index' => $index,
                'path' => self::docBookElementPath($textObject),
                'xmlId' => self::docBookXmlId($textObject),
                'id' => self::attribute($textObject, 'id'),
                'role' => self::normalizedAttribute($textObject, 'role'),
                'text' => $text,
                'textLength' => strlen($text),
            ];
        }

        return $alternatives;
    }

    /**
     * @return list<string>
     */
    private static function docBookReviewAltTexts(\DOMElement $mediaObject): array
    {
        $texts = [];
        foreach (self::descendantElements($mediaObject, 'alt') as $alt) {
            self::docBookAppendUniqueReviewString($texts, self::docBookReviewText(self::normalizedText($alt)));
        }

        return $texts;
    }

    /**
     * @return list<string>
     */
    private static function docBookReviewMediaRoles(\DOMElement $mediaObject): array
    {
        $roles = [];
        self::docBookAppendUniqueReviewString($roles, self::normalizedAttribute($mediaObject, 'role'));
        foreach (self::descendantElements($mediaObject) as $element) {
            if (!in_array($element->localName, ['imageobject', 'audioobject', 'videoobject', 'textobject', 'imagedata', 'audiodata', 'videodata'], true)) {
                continue;
            }

            self::docBookAppendUniqueReviewString($roles, self::normalizedAttribute($element, 'role'));
        }

        return $roles;
    }

    /**
     * @return list<array{element:string, target:string, sourceAttribute:string, role:?string, mediaRole:?string, objectRole:?string, dataRole:?string, format:?string}>
     */
    private static function docBookReviewMediaTargetRecords(\DOMElement $mediaObject): array
    {
        $records = [];
        $mediaRole = self::normalizedAttribute($mediaObject, 'role');
        foreach (self::descendantElements($mediaObject) as $element) {
            if (!in_array($element->localName, ['imagedata', 'audiodata', 'videodata'], true)) {
                continue;
            }

            [$target, $sourceAttribute] = self::docBookReviewMediaDataTarget($element);
            if ($target === null || $sourceAttribute === null) {
                continue;
            }

            $object = self::docBookNearestAncestorByNames($element, ['imageobject', 'audioobject', 'videoobject']);
            $objectRole = $object instanceof \DOMElement ? self::normalizedAttribute($object, 'role') : null;
            $dataRole = self::normalizedAttribute($element, 'role');
            $records[] = [
                'element' => $element->localName,
                'target' => $target,
                'sourceAttribute' => $sourceAttribute,
                'role' => $dataRole ?? $objectRole ?? $mediaRole,
                'mediaRole' => $mediaRole,
                'objectRole' => $objectRole,
                'dataRole' => $dataRole,
                'format' => self::normalizedAttribute($element, 'format'),
            ];
        }

        return $records;
    }

    /**
     * @return array{0:?string, 1:?string}
     */
    private static function docBookReviewMediaDataTarget(\DOMElement $element): array
    {
        $fileref = self::normalizedAttribute($element, 'fileref');
        if ($fileref !== null) {
            return [$fileref, 'fileref'];
        }

        $href = self::normalizedAttribute($element, 'href', self::XLINK_NAMESPACE)
            ?? self::normalizedAttribute($element, 'xlink:href')
            ?? self::normalizedAttribute($element, 'href');
        if ($href !== null) {
            return [$href, 'xlink:href'];
        }

        $entityref = self::normalizedAttribute($element, 'entityref');
        if ($entityref !== null) {
            return [$entityref, 'entityref'];
        }

        return [null, null];
    }

    /**
     * @param list<array<string, mixed>> $targetRecords
     * @return list<string>
     */
    private static function docBookReviewTargetRefs(array $targetRecords): array
    {
        $refs = [];
        foreach ($targetRecords as $targetRecord) {
            $target = $targetRecord['target'] ?? null;
            if (is_string($target)) {
                self::docBookAppendUniqueReviewString($refs, $target);
            }
        }

        return $refs;
    }

    /**
     * @param list<array<string, mixed>> $mediaObjects
     * @return list<array<string, mixed>>
     */
    private static function docBookReviewMediaTargetManifest(array $mediaObjects): array
    {
        $manifest = [];
        foreach ($mediaObjects as $mediaObject) {
            foreach (($mediaObject['targetRecords'] ?? []) as $targetRecord) {
                if (!is_array($targetRecord) || !is_string($targetRecord['target'] ?? null)) {
                    continue;
                }

                $target = $targetRecord['target'];
                $manifest[$target] ??= [
                    'target' => $target,
                    'roles' => [],
                    'mediaObjectIds' => [],
                    'mediaObjectXmlIds' => [],
                    'mediaElements' => [],
                    'titleTexts' => [],
                    'captionTexts' => [],
                    'textAlternatives' => [],
                    'occurrenceCount' => 0,
                ];

                ++$manifest[$target]['occurrenceCount'];
                self::docBookAppendUniqueReviewString($manifest[$target]['roles'], is_string($targetRecord['role'] ?? null) ? $targetRecord['role'] : null);
                self::docBookAppendUniqueReviewString($manifest[$target]['mediaObjectIds'], is_string($mediaObject['id'] ?? null) ? $mediaObject['id'] : null);
                self::docBookAppendUniqueReviewString($manifest[$target]['mediaObjectXmlIds'], is_string($mediaObject['xmlId'] ?? null) ? $mediaObject['xmlId'] : null);
                self::docBookAppendUniqueReviewString($manifest[$target]['mediaElements'], is_string($mediaObject['type'] ?? null) ? $mediaObject['type'] : null);
                self::docBookAppendUniqueReviewString($manifest[$target]['titleTexts'], is_string($mediaObject['title'] ?? null) ? $mediaObject['title'] : null);
                self::docBookAppendUniqueReviewString($manifest[$target]['captionTexts'], is_string($mediaObject['captionText'] ?? null) ? $mediaObject['captionText'] : null);
                foreach (($mediaObject['textAlternativeTexts'] ?? []) as $alternativeText) {
                    if (is_string($alternativeText)) {
                        self::docBookAppendUniqueReviewString($manifest[$target]['textAlternatives'], $alternativeText);
                    }
                }
            }
        }

        return array_values($manifest);
    }

    /**
     * @param list<array<string, mixed>> $mediaObjects
     * @return list<array<string, mixed>>
     */
    private static function docBookRepeatedMediaRoleTargetPairs(array $mediaObjects): array
    {
        $pairs = [];
        foreach ($mediaObjects as $mediaObject) {
            foreach (($mediaObject['roleTargetPairs'] ?? []) as $pair) {
                if (!is_array($pair) || !is_string($pair['role'] ?? null) || !is_string($pair['target'] ?? null)) {
                    continue;
                }

                $role = trim($pair['role']);
                $target = trim($pair['target']);
                if ($role === '' || $target === '') {
                    continue;
                }

                $key = $role . "\0" . $target;
                $pairs[$key] ??= [
                    'role' => $role,
                    'target' => $target,
                    'count' => 0,
                    'mediaObjectIds' => [],
                    'mediaObjectXmlIds' => [],
                ];
                ++$pairs[$key]['count'];
                self::docBookAppendUniqueReviewString($pairs[$key]['mediaObjectIds'], is_string($mediaObject['id'] ?? null) ? $mediaObject['id'] : null);
                self::docBookAppendUniqueReviewString($pairs[$key]['mediaObjectXmlIds'], is_string($mediaObject['xmlId'] ?? null) ? $mediaObject['xmlId'] : null);
            }
        }

        return array_values(array_filter(
            $pairs,
            static fn (array $pair): bool => $pair['count'] > 1
        ));
    }

    /**
     * @param list<array<string, mixed>> $mediaObjects
     * @param list<array<string, mixed>> $repeatedRoleTargetPairs
     * @return list<array<string, mixed>>
     */
    private static function docBookMediaObjectDiagnostics(array $mediaObjects, array $repeatedRoleTargetPairs): array
    {
        $diagnostics = [];
        foreach ($mediaObjects as $mediaObject) {
            if (($mediaObject['hasCaption'] ?? false) !== true) {
                $diagnostics[] = self::docBookMediaObjectDiagnostic(
                    'docbook-media-missing-caption',
                    'warning',
                    'DocBook mediaobject or inlinemediaobject has no bounded caption or title summary.',
                    $mediaObject
                );
            }

            if (($mediaObject['hasTextAlternative'] ?? false) !== true && ($mediaObject['targetRecords'] ?? []) !== []) {
                $diagnostics[] = self::docBookMediaObjectDiagnostic(
                    'docbook-media-missing-alt-text',
                    'warning',
                    'DocBook mediaobject or inlinemediaobject has media targets without textobject or alt alternatives.',
                    $mediaObject
                );
            }
        }

        foreach ($repeatedRoleTargetPairs as $pair) {
            $diagnostics[] = [
                'code' => 'docbook-media-repeated-role-target',
                'severity' => 'notice',
                'message' => 'DocBook media targets reuse the same role and target reference.',
                'directReaderParity' => false,
                'coveredByPacket' => true,
                'details' => [
                    'role' => $pair['role'] ?? null,
                    'target' => $pair['target'] ?? null,
                    'count' => $pair['count'] ?? 0,
                    'mediaObjectIds' => $pair['mediaObjectIds'] ?? [],
                    'mediaObjectXmlIds' => $pair['mediaObjectXmlIds'] ?? [],
                ],
            ];
        }

        return $diagnostics;
    }

    /**
     * @param array<string, mixed> $mediaObject
     * @return array<string, mixed>
     */
    private static function docBookMediaObjectDiagnostic(
        string $code,
        string $severity,
        string $message,
        array $mediaObject
    ): array {
        return [
            'code' => $code,
            'severity' => $severity,
            'message' => $message,
            'directReaderParity' => false,
            'coveredByPacket' => true,
            'details' => [
                'type' => $mediaObject['type'] ?? null,
                'path' => $mediaObject['path'] ?? null,
                'xmlId' => $mediaObject['xmlId'] ?? null,
                'id' => $mediaObject['id'] ?? null,
                'role' => $mediaObject['role'] ?? null,
                'targetRefs' => $mediaObject['targetRefs'] ?? [],
            ],
        ];
    }

    /**
     * @param list<string> $values
     */
    private static function docBookAppendUniqueReviewString(array &$values, ?string $value): void
    {
        if ($value === null) {
            return;
        }

        self::appendUniqueString($values, trim($value));
    }

    /**
     * @return array{count:int, items:list<array<string, mixed>>, truncated:bool}
     */
    private static function docBookImageDataReferences(\DOMElement $root): array
    {
        $items = [];
        $count = 0;
        foreach (self::descendantElements($root, 'imagedata') as $element) {
            ++$count;
            if (count($items) >= self::DOCBOOK_REVIEW_PACKET_MAX_ITEMS) {
                continue;
            }

            $items[] = self::docBookImageDataReferenceRecord($element, $count - 1);
        }

        return [
            'count' => $count,
            'items' => $items,
            'truncated' => $count > count($items),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function docBookImageDataReferenceRecord(\DOMElement $imageData, int $index): array
    {
        $mediaObject = self::docBookNearestAncestor($imageData, ['mediaobject', 'inlinemediaobject']);
        $imageObject = self::docBookNearestAncestor($imageData, ['imageobject']);
        $figure = self::docBookNearestAncestor($imageData, ['figure', 'informalfigure']);

        return [
            'index' => $index,
            'path' => self::docBookElementPath($imageData),
            'parentMediaObjectType' => $mediaObject instanceof \DOMElement ? $mediaObject->localName : null,
            'parentMediaObjectId' => $mediaObject instanceof \DOMElement ? self::docBookElementId($mediaObject) : null,
            'parentMediaObjectXmlId' => $mediaObject instanceof \DOMElement ? self::docBookXmlId($mediaObject) : null,
            'parentImageObjectId' => $imageObject instanceof \DOMElement ? self::docBookElementId($imageObject) : null,
            'parentFigureId' => $figure instanceof \DOMElement ? self::docBookElementId($figure) : null,
            'parentFigureXmlId' => $figure instanceof \DOMElement ? self::docBookXmlId($figure) : null,
            'width' => self::attribute($imageData, 'width'),
            'depth' => self::attribute($imageData, 'depth'),
            'contentwidth' => self::attribute($imageData, 'contentwidth'),
            'contentdepth' => self::attribute($imageData, 'contentdepth'),
            'scale' => self::attribute($imageData, 'scale'),
            'scalefit' => self::attribute($imageData, 'scalefit'),
            'align' => self::attribute($imageData, 'align'),
            'valign' => self::attribute($imageData, 'valign'),
        ] + self::docBookImageDataSummary($imageData);
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return array<string, mixed>
     */
    private static function docBookMediaTargetReviewSummary(\DOMElement $root, array $xrefs): array
    {
        $targetGroups = [];
        $missingTargetMetadata = [];
        $mediaObjectAssociations = [];
        $associationDiagnostics = [];
        $imageDataIndex = 0;

        foreach (self::docBookElementsByNames($root, ['mediaobject', 'inlinemediaobject']) as $mediaIndex => $mediaObject) {
            $mediaImageData = [];
            foreach (self::descendantElements($mediaObject, 'imagedata') as $imageData) {
                $record = self::docBookImageDataReferenceRecord($imageData, $imageDataIndex++);
                $mediaImageData[] = $record;
                $target = $record['target'] ?? null;
                if (!is_string($target) || $target === '') {
                    $missingTargetMetadata[] = self::docBookMissingMediaTargetRecord($record);
                    continue;
                }

                $targetGroups[$target] ??= [
                    'target' => $target,
                    'targetPath' => $record['targetPath'] ?? null,
                    'targetBasename' => $record['targetBasename'] ?? null,
                    'targetExtension' => $record['targetExtension'] ?? null,
                    'targetSources' => [],
                    'contentTypes' => [],
                    'contentTypeSources' => [],
                    'mediaObjectIds' => [],
                    'mediaObjectTypes' => [],
                    'mediaObjectPaths' => [],
                    'parentFigureIds' => [],
                    'imageObjectIds' => [],
                    'imageDataPaths' => [],
                    'imageDataCount' => 0,
                    'payloadBytesExposed' => false,
                ];
                ++$targetGroups[$target]['imageDataCount'];
                self::docBookAppendUniqueString($targetGroups[$target]['targetSources'], $record['targetSource'] ?? null);
                self::docBookAppendUniqueString($targetGroups[$target]['contentTypes'], $record['contentType'] ?? null);
                self::docBookAppendUniqueString($targetGroups[$target]['contentTypeSources'], $record['contentTypeSource'] ?? null);
                self::docBookAppendUniqueString($targetGroups[$target]['mediaObjectIds'], $record['parentMediaObjectId'] ?? null);
                self::docBookAppendUniqueString($targetGroups[$target]['mediaObjectTypes'], $record['parentMediaObjectType'] ?? null);
                self::docBookAppendUniqueString($targetGroups[$target]['mediaObjectPaths'], self::docBookElementPath($mediaObject));
                self::docBookAppendUniqueString($targetGroups[$target]['parentFigureIds'], $record['parentFigureId'] ?? null);
                self::docBookAppendUniqueString($targetGroups[$target]['imageObjectIds'], $record['parentImageObjectId'] ?? null);
                self::docBookAppendUniqueString($targetGroups[$target]['imageDataPaths'], $record['path'] ?? null);
            }

            $association = self::docBookMediaObjectAssociationSummary($mediaObject, $mediaIndex, $mediaImageData);
            $mediaObjectAssociations[] = $association;
            foreach (self::docBookMediaObjectAssociationDiagnostics($association) as $diagnostic) {
                $associationDiagnostics[] = $diagnostic;
            }
        }

        $targetManifest = array_values(array_map(
            static function (array $group): array {
                $group['repeated'] = (int) $group['imageDataCount'] > 1;
                $group['mediaObjectCount'] = count($group['mediaObjectIds']);
                $group['contentTypeCount'] = count($group['contentTypes']);

                return $group;
            },
            $targetGroups
        ));
        $repeatedMediaTargets = array_values(array_filter(
            $targetManifest,
            static fn (array $group): bool => ($group['repeated'] ?? false) === true
        ));
        $mediaIdTargetSummaries = self::docBookMediaIdTargetSummaries($root);
        $mediaLinkendReferences = self::docBookMediaLinkendReferences($xrefs);
        $boundedMediaIdTargetSummaries = self::docBookBoundedPacketItems($mediaIdTargetSummaries);

        return [
            'mediaTargetManifest' => self::docBookBoundedPacketItems($targetManifest),
            'repeatedMediaTargets' => self::docBookBoundedPacketItems($repeatedMediaTargets),
            'missingMediaTargetMetadata' => self::docBookBoundedPacketItems($missingTargetMetadata),
            'mediaTargetBasenameGroups' => self::docBookBoundedPacketItems(self::docBookMediaTargetBasenameGroups($targetManifest)),
            'mediaTargetContentTypeGroups' => self::docBookBoundedPacketItems(self::docBookMediaTargetContentTypeGroups($targetManifest)),
            'mediaObjectAssociations' => self::docBookBoundedPacketItems($mediaObjectAssociations),
            'mediaObjectAssociationDiagnostics' => self::docBookBoundedPacketItems($associationDiagnostics),
            'mediaIdTargetSummaries' => $boundedMediaIdTargetSummaries,
            'mediaIdTargets' => array_values(array_map(
                static fn (array $target): string => (string) $target['id'],
                $boundedMediaIdTargetSummaries['items']
            )),
            'mediaLinkendReferences' => self::docBookBoundedPacketItems($mediaLinkendReferences),
        ];
    }

    /**
     * @param list<array<string, mixed>> $items
     * @return array{count:int, items:list<array<string, mixed>>, truncated:bool}
     */
    private static function docBookBoundedPacketItems(array $items): array
    {
        return [
            'count' => count($items),
            'items' => array_slice($items, 0, self::DOCBOOK_REVIEW_PACKET_MAX_ITEMS),
            'truncated' => count($items) > self::DOCBOOK_REVIEW_PACKET_MAX_ITEMS,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function docBookMissingMediaTargetRecord(array $imageData): array
    {
        return [
            'code' => 'docbook-media-target-missing-metadata',
            'severity' => 'warning',
            'path' => $imageData['path'] ?? null,
            'parentMediaObjectType' => $imageData['parentMediaObjectType'] ?? null,
            'parentMediaObjectId' => $imageData['parentMediaObjectId'] ?? null,
            'parentFigureId' => $imageData['parentFigureId'] ?? null,
            'format' => $imageData['format'] ?? null,
            'contentType' => $imageData['contentType'] ?? null,
            'contentTypeSource' => $imageData['contentTypeSource'] ?? null,
            'message' => 'DocBook imagedata is missing fileref, entityref, and xlink:href target metadata.',
            'directReaderParity' => false,
            'coveredByPacket' => true,
            'payloadBytesExposed' => false,
        ];
    }

    /**
     * @param list<array<string, mixed>> $imageData
     * @return array<string, mixed>
     */
    private static function docBookMediaObjectAssociationSummary(\DOMElement $mediaObject, int $index, array $imageData): array
    {
        $imageObjects = self::descendantElements($mediaObject, 'imageobject');
        $textObjects = self::descendantElements($mediaObject, 'textobject');
        $targets = [];
        $targetBasenames = [];
        $contentTypes = [];
        $missingTargetCount = 0;
        foreach ($imageData as $record) {
            if (is_string($record['target'] ?? null) && $record['target'] !== '') {
                self::docBookAppendUniqueString($targets, $record['target']);
            } else {
                ++$missingTargetCount;
            }
            self::docBookAppendUniqueString($targetBasenames, $record['targetBasename'] ?? null);
            self::docBookAppendUniqueString($contentTypes, $record['contentType'] ?? null);
        }

        $imageObjectIds = [];
        foreach ($imageObjects as $imageObject) {
            self::docBookAppendUniqueString($imageObjectIds, self::docBookElementId($imageObject));
        }

        $textObjectIds = [];
        $textObjectTexts = [];
        foreach ($textObjects as $textObject) {
            self::docBookAppendUniqueString($textObjectIds, self::docBookElementId($textObject));
            $text = self::normalizedText($textObject);
            if ($text !== '') {
                self::docBookAppendUniqueString($textObjectTexts, $text);
            }
        }

        $altTexts = self::docBookAltTexts($mediaObject);

        return [
            'index' => $index,
            'type' => $mediaObject->localName,
            'id' => self::docBookElementId($mediaObject),
            'xmlId' => self::docBookXmlId($mediaObject),
            'path' => self::docBookElementPath($mediaObject),
            'parentFigureId' => ($figure = self::docBookNearestAncestor($mediaObject, ['figure', 'informalfigure'])) instanceof \DOMElement
                ? self::docBookElementId($figure)
                : null,
            'imageObjectCount' => count($imageObjects),
            'imageObjectIds' => $imageObjectIds,
            'textObjectCount' => count($textObjects),
            'textObjectIds' => $textObjectIds,
            'textObjectTexts' => $textObjectTexts,
            'altTexts' => $altTexts,
            'hasAccessibleText' => $altTexts !== [] || $textObjectTexts !== [],
            'imageDataCount' => count($imageData),
            'imageDataTargetCount' => count($targets),
            'missingTargetCount' => $missingTargetCount,
            'targets' => $targets,
            'targetBasenames' => $targetBasenames,
            'contentTypes' => $contentTypes,
            'payloadBytesExposed' => false,
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function docBookMediaObjectAssociationDiagnostics(array $association): array
    {
        $diagnostics = [];
        $imageObjectCount = (int) ($association['imageObjectCount'] ?? 0);
        $textObjectCount = (int) ($association['textObjectCount'] ?? 0);
        $missingTargetCount = (int) ($association['missingTargetCount'] ?? 0);
        $hasAccessibleText = ($association['hasAccessibleText'] ?? false) === true;

        if ($imageObjectCount > 0 && $textObjectCount === 0 && !$hasAccessibleText) {
            $diagnostics[] = self::docBookMediaObjectAssociationDiagnostic(
                'docbook-media-imageobject-without-textobject',
                'notice',
                'DocBook mediaobject has imageobject children without textobject or alt fallback text.',
                $association
            );
        }

        if ($textObjectCount > 0 && $imageObjectCount === 0) {
            $diagnostics[] = self::docBookMediaObjectAssociationDiagnostic(
                'docbook-media-textobject-without-imageobject',
                'notice',
                'DocBook mediaobject has textobject fallback text without an associated imageobject.',
                $association
            );
        }

        if ($missingTargetCount > 0) {
            $diagnostics[] = self::docBookMediaObjectAssociationDiagnostic(
                'docbook-media-target-missing-metadata',
                'warning',
                'DocBook mediaobject contains imagedata without fileref, entityref, or xlink:href target metadata.',
                $association
            );
        }

        return $diagnostics;
    }

    /**
     * @return array<string, mixed>
     */
    private static function docBookMediaObjectAssociationDiagnostic(
        string $code,
        string $severity,
        string $message,
        array $association
    ): array {
        return [
            'code' => $code,
            'severity' => $severity,
            'message' => $message,
            'directReaderParity' => false,
            'coveredByPacket' => true,
            'details' => [
                'mediaObjectId' => $association['id'] ?? null,
                'mediaObjectType' => $association['type'] ?? null,
                'parentFigureId' => $association['parentFigureId'] ?? null,
                'imageObjectCount' => $association['imageObjectCount'] ?? 0,
                'textObjectCount' => $association['textObjectCount'] ?? 0,
                'imageDataCount' => $association['imageDataCount'] ?? 0,
                'missingTargetCount' => $association['missingTargetCount'] ?? 0,
                'targets' => $association['targets'] ?? [],
                'payloadBytesExposed' => false,
            ],
        ];
    }

    /**
     * @param list<array<string, mixed>> $targetManifest
     * @return list<array<string, mixed>>
     */
    private static function docBookMediaTargetBasenameGroups(array $targetManifest): array
    {
        $groups = [];
        foreach ($targetManifest as $target) {
            $basename = $target['targetBasename'] ?? null;
            if (!is_string($basename) || $basename === '') {
                continue;
            }

            $groups[$basename] ??= [
                'targetBasename' => $basename,
                'targets' => [],
                'contentTypes' => [],
                'mediaObjectIds' => [],
                'targetCount' => 0,
                'imageDataCount' => 0,
            ];
            self::docBookAppendUniqueString($groups[$basename]['targets'], $target['target'] ?? null);
            foreach ($target['contentTypes'] ?? [] as $contentType) {
                self::docBookAppendUniqueString($groups[$basename]['contentTypes'], is_string($contentType) ? $contentType : null);
            }
            foreach ($target['mediaObjectIds'] ?? [] as $mediaObjectId) {
                self::docBookAppendUniqueString($groups[$basename]['mediaObjectIds'], is_string($mediaObjectId) ? $mediaObjectId : null);
            }
            $groups[$basename]['imageDataCount'] += (int) ($target['imageDataCount'] ?? 0);
        }

        foreach ($groups as &$group) {
            $group['targetCount'] = count($group['targets']);
        }
        unset($group);

        return array_values($groups);
    }

    /**
     * @param list<array<string, mixed>> $targetManifest
     * @return list<array<string, mixed>>
     */
    private static function docBookMediaTargetContentTypeGroups(array $targetManifest): array
    {
        $groups = [];
        foreach ($targetManifest as $target) {
            foreach ($target['contentTypes'] ?? [] as $contentType) {
                if (!is_string($contentType) || $contentType === '') {
                    continue;
                }

                $groups[$contentType] ??= [
                    'contentType' => $contentType,
                    'targets' => [],
                    'targetBasenames' => [],
                    'contentTypeSources' => [],
                    'targetCount' => 0,
                    'imageDataCount' => 0,
                ];
                self::docBookAppendUniqueString($groups[$contentType]['targets'], $target['target'] ?? null);
                self::docBookAppendUniqueString($groups[$contentType]['targetBasenames'], $target['targetBasename'] ?? null);
                foreach ($target['contentTypeSources'] ?? [] as $source) {
                    self::docBookAppendUniqueString($groups[$contentType]['contentTypeSources'], is_string($source) ? $source : null);
                }
                $groups[$contentType]['imageDataCount'] += (int) ($target['imageDataCount'] ?? 0);
            }
        }

        foreach ($groups as &$group) {
            $group['targetCount'] = count($group['targets']);
        }
        unset($group);

        return array_values($groups);
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function docBookMediaIdTargetSummaries(\DOMElement $root): array
    {
        $summaries = [];
        foreach (self::docBookElementsByNames($root, ['figure', 'informalfigure', 'mediaobject', 'inlinemediaobject', 'imageobject', 'imagedata']) as $element) {
            $id = self::docBookElementId($element);
            if ($id === null) {
                continue;
            }

            $summaries[] = [
                'element' => $element->localName,
                'kind' => self::docBookTargetKind($element),
                'id' => $id,
                'path' => self::docBookElementPath($element),
                'title' => self::docBookChildTitleText($element),
                'imageDataRefs' => self::docBookImageDataRefs($element),
            ];
        }

        return $summaries;
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return list<array<string, mixed>>
     */
    private static function docBookMediaLinkendReferences(array $xrefs): array
    {
        $references = [];
        foreach ($xrefs as $xref) {
            if (($xref['attribute'] ?? null) !== 'linkend') {
                continue;
            }
            if (!in_array($xref['targetKind'] ?? null, ['figure', 'media'], true)) {
                continue;
            }

            $targetImageDataRefs = is_array($xref['targetImageDataRefs'] ?? null) ? $xref['targetImageDataRefs'] : [];
            $references[] = [
                'sourceElement' => $xref['sourceElement'] ?? null,
                'sourceId' => $xref['sourceId'] ?? null,
                'sourceText' => $xref['sourceText'] ?? null,
                'target' => $xref['target'] ?? null,
                'targetElement' => $xref['targetElement'] ?? null,
                'targetKind' => $xref['targetKind'] ?? null,
                'targetId' => $xref['targetId'] ?? null,
                'targetRole' => $xref['targetRole'] ?? null,
                'targetTitle' => $xref['targetTitle'] ?? null,
                'targetImageDataRefs' => $targetImageDataRefs,
                'targetImageDataRefCount' => count($targetImageDataRefs),
                'payloadBytesExposed' => false,
            ];
        }

        return $references;
    }

    private static function docBookAppendUniqueString(array &$values, mixed $value): void
    {
        if (!is_string($value) || $value === '' || in_array($value, $values, true)) {
            return;
        }
        if (count($values) >= self::DOCBOOK_REVIEW_PACKET_MAX_ITEMS) {
            return;
        }

        $values[] = $value;
    }

    /**
     * @return array<string, mixed>
     */
    private static function docBookTargetSummary(\DOMElement $root): array
    {
        $targetSummaries = [];
        $xmlIdTargets = [];
        $idTargets = [];
        foreach (self::docBookElementAndDescendants($root) as $element) {
            $xmlId = self::docBookXmlId($element);
            $id = self::attribute($element, 'id');
            if (($xmlId === null || trim($xmlId) === '') && ($id === null || trim($id) === '')) {
                continue;
            }

            if ($xmlId !== null && trim($xmlId) !== '') {
                $xmlIdTargets[] = trim($xmlId);
            }
            if ($id !== null && trim($id) !== '') {
                $idTargets[] = trim($id);
            }
            if (count($targetSummaries) < self::DOCBOOK_REVIEW_PACKET_MAX_ITEMS) {
                $targetSummaries[] = [
                    'name' => $element->localName,
                    'path' => self::docBookElementPath($element),
                    'xmlId' => $xmlId,
                    'id' => $id,
                    'title' => self::docBookReviewTitleText($element),
                ];
            }
        }

        $knownTargets = array_fill_keys(array_merge($xmlIdTargets, $idTargets), true);
        $linkendReferences = [];
        $linkendTargets = [];
        $missingTargets = [];
        foreach (self::docBookElementAndDescendants($root) as $element) {
            $linkend = self::attribute($element, 'linkend');
            if ($linkend === null || trim($linkend) === '') {
                continue;
            }

            $targets = self::spaceSeparatedTokens($linkend);
            $resolved = [];
            $missing = [];
            foreach ($targets as $target) {
                $linkendTargets[] = $target;
                if (isset($knownTargets[$target])) {
                    $resolved[] = $target;
                } else {
                    $missing[] = $target;
                    $missingTargets[] = $target;
                }
            }

            if (count($linkendReferences) < self::DOCBOOK_REVIEW_PACKET_MAX_ITEMS) {
                $endterm = self::attribute($element, 'endterm');
                $linkendReferences[] = [
                    'name' => $element->localName,
                    'path' => self::docBookElementPath($element),
                    'linkendRaw' => $linkend,
                    'targets' => $targets,
                    'resolvedTargets' => $resolved,
                    'missingTargets' => $missing,
                    'endterm' => $endterm,
                    'endtermResolved' => $endterm !== null && isset($knownTargets[$endterm]),
                    'text' => self::docBookBoundedText($element, 80),
                ];
            }
        }

        return [
            'xmlIdTargets' => array_values(array_unique($xmlIdTargets)),
            'idTargets' => array_values(array_unique($idTargets)),
            'targetSummaries' => $targetSummaries,
            'linkendReferences' => $linkendReferences,
            'linkendTargets' => array_values(array_unique($linkendTargets)),
            'missingLinkendTargets' => array_values(array_unique($missingTargets)),
        ];
    }

    /**
     * @return array{count:int, items:list<array<string, mixed>>, truncated:bool}
     */
    private static function docBookUnsupportedChildDiagnostics(\DOMElement $root): array
    {
        $items = [];
        $count = 0;
        foreach (self::docBookElementAndDescendants($root) as $parent) {
            foreach (self::childElements($parent) as $child) {
                if (isset(self::DOCBOOK_REVIEW_PACKET_COVERED_CHILD_NAMES[$child->localName])) {
                    continue;
                }

                ++$count;
                if (count($items) >= self::DOCBOOK_REVIEW_PACKET_MAX_ITEMS) {
                    continue;
                }

                $items[] = [
                    'code' => 'docbook-unsupported-child',
                    'severity' => 'unsupported',
                    'parentName' => $parent->localName,
                    'childName' => $child->localName,
                    'path' => self::docBookElementPath($child),
                    'message' => 'DocBook child element is outside the bounded XML review packet and full direct-reader conversion remains unsupported.',
                    'directReaderParity' => false,
                    'coveredByPacket' => false,
                    'text' => self::docBookBoundedText($child, 80),
                ];
            }
        }

        return [
            'count' => $count,
            'items' => $items,
            'truncated' => $count > count($items),
        ];
    }

    /**
     * @return list<\DOMElement>
     */
    private static function docBookElementAndDescendants(\DOMElement $root): array
    {
        return [$root, ...self::descendantElements($root)];
    }

    private static function docBookReviewTitleText(\DOMElement $element): ?string
    {
        $title = self::firstChildElement($element, 'title') ?? self::firstDescendantElement($element, 'title');
        if (!$title instanceof \DOMElement) {
            return null;
        }

        $text = self::normalizedText($title);

        return $text === '' ? null : $text;
    }

    private static function docBookXmlId(\DOMElement $element): ?string
    {
        $id = self::attribute($element, 'id', self::XML_NAMESPACE);

        return $id === null || trim($id) === '' ? null : trim($id);
    }

    /**
     * @return list<string>
     */
    private static function docBookChildElementNames(\DOMElement $element): array
    {
        return array_values(array_map(
            static fn (\DOMElement $child): string => $child->localName,
            self::childElements($element)
        ));
    }

    /**
     * @return list<string>
     */
    private static function docBookLinkendTargets(\DOMElement $element): array
    {
        $targets = [];
        foreach (self::docBookElementAndDescendants($element) as $candidate) {
            $linkend = self::attribute($candidate, 'linkend');
            if ($linkend === null || trim($linkend) === '') {
                continue;
            }
            foreach (self::spaceSeparatedTokens($linkend) as $target) {
                $targets[] = $target;
            }
        }

        return array_values(array_unique($targets));
    }

    /**
     * @param list<string> $names
     */
    private static function docBookNearestAncestor(\DOMElement $element, array $names): ?\DOMElement
    {
        $lookup = array_fill_keys($names, true);
        $node = $element->parentNode;
        while ($node instanceof \DOMElement) {
            if (isset($lookup[$node->localName])) {
                return $node;
            }
            $node = $node->parentNode;
        }

        return null;
    }

    private static function docBookElementPath(\DOMElement $element): string
    {
        $segments = [];
        $node = $element;
        while ($node instanceof \DOMElement) {
            $segment = $node->localName;
            $xmlId = self::docBookXmlId($node);
            $id = self::attribute($node, 'id');
            if ($xmlId !== null) {
                $segment .= '[@xml:id="' . $xmlId . '"]';
            } elseif ($id !== null && trim($id) !== '') {
                $segment .= '[@id="' . trim($id) . '"]';
            }
            array_unshift($segments, $segment);
            $node = $node->parentNode;
        }

        return '/' . implode('/', $segments);
    }

    private static function docBookBoundedText(\DOMElement $element, int $limit = 160): string
    {
        $text = self::normalizedText($element);
        if (strlen($text) <= $limit) {
            return $text;
        }

        return rtrim(substr($text, 0, $limit)) . '...';
    }

    /**
     * @param list<string> $localNames
     */
    private static function jatsFirstText(\DOMElement $root, array $localNames): ?string
    {
        foreach ($localNames as $localName) {
            $element = self::firstDescendantElement($root, $localName);
            if (!$element instanceof \DOMElement) {
                continue;
            }

            $text = self::normalizedText($element);
            if ($text !== '') {
                return $text;
            }
        }

        return null;
    }

    /**
     * @param list<string> $localNames
     * @return array{element:string, text:string}|null
     */
    private static function jatsFirstTextRecord(\DOMElement $root, array $localNames): ?array
    {
        foreach ($localNames as $localName) {
            $element = self::firstDescendantElement($root, $localName);
            if (!$element instanceof \DOMElement) {
                continue;
            }

            $text = self::normalizedText($element);
            if ($text !== '') {
                return [
                    'element' => $localName,
                    'text' => $text,
                ];
            }
        }

        return null;
    }

    /**
     * @return list<string>
     */
    private static function jatsTextList(\DOMElement $root, string $localName): array
    {
        $values = [];
        foreach (self::descendantElements($root, $localName) as $element) {
            $text = self::normalizedText($element);
            if ($text !== '') {
                $values[] = $text;
            }
        }

        return $values;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function jatsAbstractSummaries(\DOMElement $metadata): array
    {
        $records = [];
        foreach (['abstract', 'trans-abstract'] as $localName) {
            foreach (self::descendantElements($metadata, $localName) as $abstract) {
                $sections = [];
                foreach (self::childElements($abstract, 'sec') as $section) {
                    $sectionTitle = self::jatsElementTextOrNull(self::firstChildElement($section, 'title'));
                    $sectionParagraphs = self::jatsNonEmptyTexts(self::childElements($section, 'p'));
                    $sections[] = [
                        'id' => self::normalizedAttribute($section, 'id'),
                        'type' => self::normalizedAttribute($section, 'sec-type'),
                        'title' => $sectionTitle,
                        'paragraphs' => $sectionParagraphs,
                        'paragraphCount' => count($sectionParagraphs),
                    ];
                }

                $text = self::jatsCompositeElementReviewText($abstract);
                $paragraphs = self::jatsNonEmptyTexts(self::childElements($abstract, 'p'));
                $records[] = [
                    'element' => $localName,
                    'id' => self::normalizedAttribute($abstract, 'id'),
                    'type' => self::normalizedAttribute($abstract, 'abstract-type')
                        ?? self::normalizedAttribute($abstract, 'content-type'),
                    'language' => self::normalizedAttribute($abstract, 'lang', self::XML_NAMESPACE)
                        ?? self::normalizedAttribute($abstract, 'lang'),
                    'title' => self::jatsElementTextOrNull(self::firstChildElement($abstract, 'title')),
                    'text' => $text === '' ? null : $text,
                    'paragraphs' => $paragraphs,
                    'paragraphCount' => count($paragraphs),
                    'sectionCount' => count($sections),
                    'sectionTitles' => array_values(array_filter(
                        array_map(static fn (array $section): ?string => $section['title'], $sections),
                        static fn (?string $title): bool => $title !== null && $title !== ''
                    )),
                    'sections' => $sections,
                    'structured' => $sections !== [],
                    'sourceLine' => max(0, $abstract->getLineNo()),
                ];
            }
        }

        return $records;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function jatsKeywordGroupSummaries(\DOMElement $metadata): array
    {
        $groups = [];
        foreach (self::descendantElements($metadata, 'kwd-group') as $group) {
            $compoundKeywords = [];
            foreach (self::childElements($group, 'compound-kwd') as $compoundKeyword) {
                $parts = [];
                foreach (self::childElements($compoundKeyword, 'compound-kwd-part') as $part) {
                    $parts[] = [
                        'type' => self::normalizedAttribute($part, 'content-type')
                            ?? self::normalizedAttribute($part, 'kwd-part-type'),
                        'text' => self::normalizedText($part),
                    ];
                }

                $compoundKeywords[] = [
                    'text' => self::jatsElementReviewText($compoundKeyword),
                    'partCount' => count($parts),
                    'parts' => $parts,
                ];
            }

            $keywords = self::jatsNonEmptyTexts(self::childElements($group, 'kwd'));
            $groups[] = [
                'id' => self::normalizedAttribute($group, 'id'),
                'type' => self::normalizedAttribute($group, 'kwd-group-type')
                    ?? self::normalizedAttribute($group, 'content-type'),
                'language' => self::normalizedAttribute($group, 'lang', self::XML_NAMESPACE)
                    ?? self::normalizedAttribute($group, 'lang'),
                'title' => self::jatsElementTextOrNull(self::firstChildElement($group, 'title')),
                'keywords' => $keywords,
                'keywordCount' => count($keywords),
                'compoundKeywords' => $compoundKeywords,
                'compoundKeywordCount' => count($compoundKeywords),
                'compoundKeywordPartCount' => array_sum(array_map(
                    static fn (array $compoundKeyword): int => (int) ($compoundKeyword['partCount'] ?? 0),
                    $compoundKeywords
                )),
                'sourceLine' => max(0, $group->getLineNo()),
            ];
        }

        return $groups;
    }

    /**
     * @param list<string> $localNames
     * @param list<string> $typeAttributes
     * @return list<array{element:string, type:?string, value:string}>
     */
    private static function jatsTypedTextRecords(\DOMElement $root, array $localNames, array $typeAttributes): array
    {
        $records = [];
        foreach ($localNames as $localName) {
            foreach (self::descendantElements($root, $localName) as $element) {
                $value = self::normalizedText($element);
                if ($value === '') {
                    continue;
                }

                $type = null;
                foreach ($typeAttributes as $attribute) {
                    $type = self::attribute($element, $attribute);
                    if ($type !== null && trim($type) !== '') {
                        $type = trim($type);
                        break;
                    }
                    $type = null;
                }

                $records[] = [
                    'element' => $localName,
                    'type' => $type,
                    'value' => $value,
                ];
            }
        }

        return $records;
    }

    /**
     * @return array<string, mixed>
     */
    private static function jatsPublicationMetadataSummary(\DOMElement $root, ?\DOMElement $metadata): array
    {
        $journalMeta = self::firstDescendantElement($root, 'journal-meta');
        $serialTitleRecords = [];
        $serialIdentifierRecords = [];
        $publisherRecords = [];

        if ($journalMeta instanceof \DOMElement) {
            $serialTitleRecords = array_merge(
                $serialTitleRecords,
                self::jatsPublicationTextRecords(
                    $journalMeta,
                    ['journal-title', 'journal-subtitle', 'abbrev-journal-title'],
                    'journal-meta',
                    ['journal-title-type', 'abbrev-type']
                )
            );
            $serialIdentifierRecords = array_merge(
                $serialIdentifierRecords,
                self::jatsPublicationTypedTextRecords(
                    $journalMeta,
                    ['journal-id', 'issn', 'issn-l'],
                    ['journal-id-type', 'pub-id-type', 'content-type', 'publication-format'],
                    'journal-meta'
                )
            );
            $publisherRecords = array_merge(
                $publisherRecords,
                self::jatsPublisherRecords($journalMeta, 'journal-meta')
            );
        }

        if ($metadata instanceof \DOMElement) {
            $serialTitleRecords = array_merge(
                $serialTitleRecords,
                self::jatsPublicationTextRecords(
                    $metadata,
                    ['book-title', 'book-subtitle'],
                    $metadata->localName,
                    ['book-title-type']
                )
            );
            $serialIdentifierRecords = array_merge(
                $serialIdentifierRecords,
                self::jatsPublicationTypedTextRecords(
                    $metadata,
                    ['isbn'],
                    ['content-type', 'pub-id-type', 'publication-format'],
                    $metadata->localName
                )
            );
            $publisherRecords = array_merge(
                $publisherRecords,
                self::jatsPublisherRecords($metadata, $metadata->localName)
            );
        }

        $permissions = $metadata instanceof \DOMElement
            ? self::jatsChildPermissionSummaries($metadata)
            : [];
        $permissionIssues = self::jatsPermissionDuplicateLicenseIssues('front-matter', null, null, $permissions);
        $issuePageMetadata = $metadata instanceof \DOMElement
            ? self::jatsIssuePageMetadataSummary($metadata)
            : self::jatsEmptyIssuePageMetadataSummary();
        $historyDates = $metadata instanceof \DOMElement ? self::jatsHistoryDateSummaries($metadata) : [];
        $articleLinks = $metadata instanceof \DOMElement ? self::jatsArticleLinkRecords($metadata) : [];

        $mappedCaseKinds = [];
        if ($serialIdentifierRecords !== []) {
            $mappedCaseKinds[] = 'serial-identifiers';
        }
        if ($publisherRecords !== []) {
            $mappedCaseKinds[] = 'publisher-provenance';
        }
        if ($permissions !== []) {
            $mappedCaseKinds[] = 'front-matter-permissions';
        }
        if ($historyDates !== []) {
            $mappedCaseKinds[] = 'history-dates';
        }
        if ($articleLinks !== []) {
            $mappedCaseKinds[] = 'article-link-targets';
        }
        if ((int) $issuePageMetadata['fieldCount'] > 0) {
            $mappedCaseKinds[] = 'issue-page-metadata';
        }

        $diagnostics = self::jatsPublicationMetadataDiagnostics(
            $serialIdentifierRecords,
            $publisherRecords,
            $permissions,
            $permissionIssues,
            $historyDates,
            $articleLinks,
            $issuePageMetadata
        );

        return [
            'serialTitleRecords' => $serialTitleRecords,
            'serialTitleRecordCount' => count($serialTitleRecords),
            'serialIdentifierRecords' => $serialIdentifierRecords,
            'serialIdentifierRecordCount' => count($serialIdentifierRecords),
            'serialIdentifierTypes' => self::jatsUniqueNonEmptyStrings(array_map(
                static fn (array $record): ?string => $record['type'] ?? null,
                $serialIdentifierRecords
            )),
            'publisherRecords' => $publisherRecords,
            'publisherRecordCount' => count($publisherRecords),
            'publisherNames' => self::jatsUniqueNonEmptyStrings(array_map(
                static fn (array $publisher): ?string => $publisher['name'] ?? null,
                $publisherRecords
            )),
            'issuePageMetadata' => $issuePageMetadata,
            'issuePageMetadataFieldCount' => $issuePageMetadata['fieldCount'],
            'historyDates' => $historyDates,
            'historyDateCount' => count($historyDates),
            'articleLinkRecords' => $articleLinks,
            'articleLinkRecordCount' => count($articleLinks),
            'articleLinkTargets' => self::jatsUniqueNonEmptyStrings(array_map(
                static fn (array $link): ?string => $link['target'] ?? null,
                $articleLinks
            )),
            'permissions' => $permissions,
            'permissionCount' => count($permissions),
            'licenseCount' => self::jatsPermissionRecordCount($permissions, 'licenses'),
            'licenseRefCount' => self::jatsPermissionRecordCount($permissions, 'licenseRefs'),
            'copyrightStatementCount' => self::jatsPermissionRecordCount($permissions, 'copyrightStatements'),
            'permissionIssues' => $permissionIssues,
            'permissionIssueCodes' => self::jatsFigurePermissionIssueCodes($permissionIssues),
            'permissionIssueCount' => count($permissionIssues),
            'mappedCaseKinds' => $mappedCaseKinds,
            'mappedCaseCount' => count($mappedCaseKinds),
            'diagnostics' => $diagnostics,
            'diagnosticCodes' => array_values(array_map(
                static fn (array $diagnostic): string => (string) $diagnostic['code'],
                $diagnostics
            )),
            'diagnosticCount' => count($diagnostics),
        ];
    }

    /**
     * @param list<string> $localNames
     * @param list<string> $typeAttributes
     * @return list<array{context:string, element:string, type:?string, value:string}>
     */
    private static function jatsPublicationTextRecords(
        \DOMElement $container,
        array $localNames,
        string $context,
        array $typeAttributes = []
    ): array {
        $records = [];
        foreach ($localNames as $localName) {
            foreach (self::descendantElements($container, $localName) as $element) {
                $value = self::normalizedText($element);
                if ($value === '') {
                    continue;
                }

                $type = null;
                foreach ($typeAttributes as $attribute) {
                    $attributeValue = self::normalizedAttribute($element, $attribute);
                    if ($attributeValue !== null) {
                        $type = $attributeValue;
                        break;
                    }
                }

                $records[] = [
                    'context' => $context,
                    'element' => $localName,
                    'type' => $type,
                    'value' => $value,
                ];
            }
        }

        return $records;
    }

    /**
     * @param list<string> $localNames
     * @param list<string> $typeAttributes
     * @return list<array{context:string, element:string, type:?string, value:string}>
     */
    private static function jatsPublicationTypedTextRecords(
        \DOMElement $container,
        array $localNames,
        array $typeAttributes,
        string $context
    ): array {
        $records = [];
        foreach (self::jatsTypedTextRecords($container, $localNames, $typeAttributes) as $record) {
            $records[] = ['context' => $context] + $record;
        }

        return $records;
    }

    /**
     * @return list<array{context:string, id:?string, name:?string, location:?string, text:string}>
     */
    private static function jatsPublisherRecords(\DOMElement $container, string $context): array
    {
        $records = [];
        foreach (self::descendantElements($container, 'publisher') as $publisher) {
            $name = self::jatsFirstText($publisher, ['publisher-name']);
            $location = self::jatsFirstText($publisher, ['publisher-loc']);
            $text = self::normalizedText($publisher);
            if ($name === null && $location === null && $text === '') {
                continue;
            }

            $records[] = [
                'context' => $context,
                'id' => self::normalizedAttribute($publisher, 'id'),
                'name' => $name,
                'location' => $location,
                'text' => $text,
            ];
        }

        return $records;
    }

    /**
     * @return array<string, mixed>
     */
    private static function jatsIssuePageMetadataSummary(\DOMElement $metadata): array
    {
        $fields = [];
        foreach ([
            'volume',
            'volume-id',
            'volume-series',
            'issue',
            'issue-id',
            'issue-title',
            'issue-sponsor',
            'fpage',
            'lpage',
            'page-range',
            'elocation-id',
        ] as $localName) {
            $values = self::jatsTextList($metadata, $localName);
            if ($values !== []) {
                $fields[$localName] = $values;
            }
        }

        return [
            'fields' => $fields,
            'fieldNames' => array_keys($fields),
            'fieldCount' => count($fields),
            'volume' => $fields['volume'][0] ?? null,
            'issue' => $fields['issue'][0] ?? null,
            'issueTitle' => $fields['issue-title'][0] ?? null,
            'firstPage' => $fields['fpage'][0] ?? null,
            'lastPage' => $fields['lpage'][0] ?? null,
            'pageRange' => $fields['page-range'][0] ?? null,
            'elocationId' => $fields['elocation-id'][0] ?? null,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function jatsEmptyIssuePageMetadataSummary(): array
    {
        return [
            'fields' => [],
            'fieldNames' => [],
            'fieldCount' => 0,
            'volume' => null,
            'issue' => null,
            'issueTitle' => null,
            'firstPage' => null,
            'lastPage' => null,
            'pageRange' => null,
            'elocationId' => null,
        ];
    }

    /**
     * @return list<array{type:?string, year:?string, month:?string, day:?string, iso:?string, text:string}>
     */
    private static function jatsHistoryDateSummaries(\DOMElement $metadata): array
    {
        $history = self::firstDescendantElement($metadata, 'history');
        if (!$history instanceof \DOMElement) {
            return [];
        }

        $dates = [];
        foreach (self::descendantElements($history, 'date') as $date) {
            $dates[] = self::jatsDateElementSummary($date);
        }

        return $dates;
    }

    /**
     * @return array{type:?string, year:?string, month:?string, day:?string, iso:?string, text:string}
     */
    private static function jatsDateElementSummary(\DOMElement $date): array
    {
        $year = self::jatsFirstText($date, ['year']);
        $month = self::jatsFirstText($date, ['month']);
        $day = self::jatsFirstText($date, ['day']);

        return [
            'type' => self::normalizedAttribute($date, 'date-type')
                ?? self::normalizedAttribute($date, 'publication-format')
                ?? self::normalizedAttribute($date, 'specific-use'),
            'year' => $year,
            'month' => $month,
            'day' => $day,
            'iso' => self::jatsIsoDate($year, $month, $day),
            'text' => self::normalizedText($date),
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function jatsArticleLinkRecords(\DOMElement $metadata): array
    {
        $records = [];
        foreach (['self-uri', 'related-article', 'related-object'] as $localName) {
            foreach (self::descendantElements($metadata, $localName) as $element) {
                $target = self::jatsLinkTarget($element);
                $records[] = [
                    'element' => $localName,
                    'id' => self::normalizedAttribute($element, 'id'),
                    'type' => self::normalizedAttribute($element, 'content-type')
                        ?? self::normalizedAttribute($element, 'self-uri-type')
                        ?? self::normalizedAttribute($element, 'related-article-type')
                        ?? self::normalizedAttribute($element, 'related-object-type')
                        ?? self::normalizedAttribute($element, 'object-id-type')
                        ?? self::normalizedAttribute($element, 'ext-link-type')
                        ?? self::normalizedAttribute($element, 'link-type'),
                    'target' => $target,
                    'targetKind' => self::jatsLinkTargetKind($target),
                    'hrefAttribute' => self::jatsLinkTargetAttribute($element),
                    'mimeType' => self::normalizedAttribute($element, 'mimetype')
                        ?? self::normalizedAttribute($element, 'mime-type'),
                    'mimeSubtype' => self::normalizedAttribute($element, 'mime-subtype'),
                    'text' => self::normalizedText($element),
                    'payloadBytesExposed' => false,
                ];
            }
        }

        return $records;
    }

    private static function jatsLinkTargetKind(?string $target): ?string
    {
        if ($target === null) {
            return null;
        }

        if (preg_match('/^[a-z][a-z0-9+.-]*:/i', $target) === 1) {
            return 'absolute-uri';
        }

        if (str_starts_with($target, '#')) {
            return 'fragment';
        }

        return 'relative';
    }

    private static function jatsLinkTargetAttribute(\DOMElement $element): ?string
    {
        if (self::normalizedAttribute($element, 'href', self::XLINK_NAMESPACE) !== null) {
            return 'xlink:href';
        }

        if (self::normalizedAttribute($element, 'xlink:href') !== null) {
            return 'xlink:href';
        }

        return self::normalizedAttribute($element, 'href') !== null ? 'href' : null;
    }

    /**
     * @param list<array<string, mixed>> $serialIdentifierRecords
     * @param list<array<string, mixed>> $publisherRecords
     * @param list<array<string, mixed>> $permissions
     * @param list<array<string, mixed>> $permissionIssues
     * @param list<array<string, mixed>> $historyDates
     * @param list<array<string, mixed>> $articleLinks
     * @param array<string, mixed> $issuePageMetadata
     * @return list<array<string, mixed>>
     */
    private static function jatsPublicationMetadataDiagnostics(
        array $serialIdentifierRecords,
        array $publisherRecords,
        array $permissions,
        array $permissionIssues,
        array $historyDates,
        array $articleLinks,
        array $issuePageMetadata
    ): array {
        $diagnostics = [];
        if ($serialIdentifierRecords !== []) {
            $diagnostics[] = [
                'code' => 'publication-serial-identifiers-review-only',
                'severity' => 'info',
                'message' => 'JATS/BITS serial identifiers are summarized for review but are not mapped as full reader metadata.',
                'identifierCount' => count($serialIdentifierRecords),
            ];
        }
        if ($publisherRecords !== []) {
            $diagnostics[] = [
                'code' => 'publication-publisher-provenance-review-only',
                'severity' => 'info',
                'message' => 'Publisher names and locations are preserved as bounded review metadata.',
                'publisherCount' => count($publisherRecords),
            ];
        }
        if ($permissions !== []) {
            $diagnostics[] = [
                'code' => 'publication-permissions-review-only',
                'severity' => 'info',
                'message' => 'Front-matter permissions and licenses are summarized without claiming full JATS/BITS reader parity.',
                'permissionCount' => count($permissions),
                'licenseCount' => self::jatsPermissionRecordCount($permissions, 'licenses'),
                'licenseRefCount' => self::jatsPermissionRecordCount($permissions, 'licenseRefs'),
            ];
        }
        foreach ($permissionIssues as $issue) {
            $diagnostics[] = ['severity' => 'warning', 'message' => 'Front-matter permission issue detected.'] + $issue;
        }
        if ($historyDates !== []) {
            $diagnostics[] = [
                'code' => 'publication-history-dates-review-only',
                'severity' => 'info',
                'message' => 'Article history dates are summarized for reviewer handoff.',
                'historyDateCount' => count($historyDates),
            ];
        }
        if ($articleLinks !== []) {
            $diagnostics[] = [
                'code' => 'publication-link-targets-review-only',
                'severity' => 'info',
                'message' => 'Self and related article/object links are summarized without dereferencing targets.',
                'linkCount' => count($articleLinks),
            ];
        }
        if ((int) $issuePageMetadata['fieldCount'] > 0) {
            $diagnostics[] = [
                'code' => 'publication-issue-page-metadata-review-only',
                'severity' => 'info',
                'message' => 'Volume, issue, page, and elocation fields are summarized for review metadata.',
                'fieldCount' => $issuePageMetadata['fieldCount'],
                'fieldNames' => $issuePageMetadata['fieldNames'],
            ];
        }

        return $diagnostics;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function jatsContributorSummaries(\DOMElement $metadata): array
    {
        $contributors = [];
        foreach (self::descendantElements($metadata, 'contrib') as $contrib) {
            $role = self::attribute($contrib, 'contrib-type');
            $xrefTargets = [];
            foreach (self::descendantElements($contrib, 'xref') as $xref) {
                $target = self::attribute($xref, 'rid');
                if ($target !== null && trim($target) !== '') {
                    $xrefTargets[] = trim($target);
                }
            }

            $contributors[] = [
                'role' => $role === null || trim($role) === '' ? null : trim($role),
                'name' => self::jatsContributorName($contrib),
                'xrefTargets' => array_values(array_unique($xrefTargets)),
            ];
        }

        return $contributors;
    }

    private static function jatsContributorName(\DOMElement $contrib): string
    {
        $name = self::firstDescendantElement($contrib, 'name');
        if ($name instanceof \DOMElement) {
            $surname = self::jatsFirstText($name, ['surname']);
            $given = self::jatsFirstText($name, ['given-names']);
            $combined = trim(($given ?? '') . ' ' . ($surname ?? ''));
            if ($combined !== '') {
                return $combined;
            }
        }

        foreach (['string-name', 'collab'] as $localName) {
            $element = self::firstDescendantElement($contrib, $localName);
            if (!$element instanceof \DOMElement) {
                continue;
            }

            $text = self::normalizedText($element);
            if ($text !== '') {
                return $text;
            }
        }

        return self::normalizedText($contrib);
    }

    /**
     * @return list<array{type:?string, year:?string, month:?string, day:?string, iso:?string}>
     */
    private static function jatsPublicationDateSummaries(\DOMElement $metadata): array
    {
        $dates = [];
        foreach (self::descendantElements($metadata, 'pub-date') as $date) {
            $year = self::jatsFirstText($date, ['year']);
            $month = self::jatsFirstText($date, ['month']);
            $day = self::jatsFirstText($date, ['day']);

            $dates[] = [
                'type' => self::attribute($date, 'date-type') ?? self::attribute($date, 'pub-type'),
                'year' => $year,
                'month' => $month,
                'day' => $day,
                'iso' => self::jatsIsoDate($year, $month, $day),
            ];
        }

        return $dates;
    }

    private static function jatsIsoDate(?string $year, ?string $month, ?string $day): ?string
    {
        if ($year === null || preg_match('/^\d{4}$/', $year) !== 1) {
            return null;
        }

        if ($month === null || preg_match('/^\d{1,2}$/', $month) !== 1) {
            return $year;
        }

        $iso = $year . '-' . str_pad($month, 2, '0', STR_PAD_LEFT);
        if ($day === null || preg_match('/^\d{1,2}$/', $day) !== 1) {
            return $iso;
        }

        return $iso . '-' . str_pad($day, 2, '0', STR_PAD_LEFT);
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function jatsSectionSummaries(\DOMElement $body): array
    {
        $sections = [];
        $ordinal = 1;
        self::collectJatsSectionSummaries($body, 1, null, [], $ordinal, $sections);

        return $sections;
    }

    /**
     * @param list<array<string, mixed>> $sections
     * @return list<array<string, mixed>>
     */
    private static function jatsSectionMetadataDiagnostics(array $sections): array
    {
        $missingIds = [];
        $idBuckets = [];
        $labelRecords = [];
        $languageRecords = [];
        $missingTitles = [];
        $duplicateTitles = [];

        foreach ($sections as $index => $section) {
            $reference = self::jatsSectionReference($section, $index);
            $id = self::stringOrNull($section['id'] ?? null);
            if ($id === null) {
                $missingIds[] = $reference;
            } else {
                $idBuckets[$id][] = $reference;
            }

            $label = self::stringOrNull($section['label'] ?? null);
            if ($label !== null) {
                $labelRecords[] = [
                    'section' => $reference,
                    'label' => $label,
                ];
            }

            $language = self::stringOrNull($section['language'] ?? null);
            if ($language !== null) {
                $languageRecords[] = [
                    'section' => $reference,
                    'language' => $language,
                ];
            }

            $titleCount = is_int($section['titleCount'] ?? null) ? $section['titleCount'] : 0;
            if ($titleCount === 0) {
                $missingTitles[] = $reference;
            } elseif ($titleCount > 1) {
                $duplicateTitles[] = [
                    'section' => $reference,
                    'titleCount' => $titleCount,
                ];
            }
        }

        $diagnostics = [];
        if ($missingIds !== []) {
            $diagnostics[] = self::jatsSectionMetadataDiagnostic(
                'section-id-missing',
                'warning',
                'One or more JATS/BITS sections are missing stable id metadata.',
                [
                    'missingSectionIdCount' => count($missingIds),
                    'sections' => $missingIds,
                ]
            );
        }

        $duplicateIds = [];
        foreach ($idBuckets as $id => $references) {
            if (count($references) > 1) {
                $duplicateIds[] = [
                    'id' => $id,
                    'sections' => $references,
                ];
            }
        }
        if ($duplicateIds !== []) {
            $diagnostics[] = self::jatsSectionMetadataDiagnostic(
                'section-id-duplicate',
                'warning',
                'Duplicate JATS/BITS section ids were found in the review packet.',
                [
                    'duplicateSectionIdCount' => count($duplicateIds),
                    'duplicateSectionIds' => array_values(array_map(
                        static fn (array $duplicate): string => (string) $duplicate['id'],
                        $duplicateIds
                    )),
                    'duplicates' => $duplicateIds,
                ]
            );
        }

        if ($labelRecords !== []) {
            $diagnostics[] = self::jatsSectionMetadataDiagnostic(
                'section-labels-review-only',
                'info',
                'JATS/BITS section labels are inventoried for review but are not mapped as numbered Pandoc section labels.',
                [
                    'sectionLabelCount' => count($labelRecords),
                    'labels' => array_values(array_map(
                        static fn (array $record): string => (string) $record['label'],
                        $labelRecords
                    )),
                    'sections' => $labelRecords,
                ]
            );
        }

        if ($languageRecords !== []) {
            $diagnostics[] = self::jatsSectionMetadataDiagnostic(
                'section-languages-review-only',
                'info',
                'JATS/BITS section language tags are inventoried for review but are not mapped as Pandoc section language attributes.',
                [
                    'sectionLanguageCount' => count($languageRecords),
                    'languages' => array_values(array_unique(array_map(
                        static fn (array $record): string => (string) $record['language'],
                        $languageRecords
                    ))),
                    'sections' => $languageRecords,
                ]
            );
        }

        if ($missingTitles !== []) {
            $diagnostics[] = self::jatsSectionMetadataDiagnostic(
                'section-title-missing',
                'warning',
                'One or more JATS/BITS sections have no direct title metadata.',
                [
                    'missingSectionTitleCount' => count($missingTitles),
                    'sections' => $missingTitles,
                ]
            );
        }

        if ($duplicateTitles !== []) {
            $diagnostics[] = self::jatsSectionMetadataDiagnostic(
                'section-title-duplicate',
                'warning',
                'One or more JATS/BITS sections have multiple direct title elements.',
                [
                    'duplicateSectionTitleCount' => count($duplicateTitles),
                    'sections' => $duplicateTitles,
                ]
            );
        }

        return $diagnostics;
    }

    /**
     * @return array<string, mixed>
     */
    private static function jatsSectionMetadataDiagnostic(
        string $code,
        string $severity,
        string $message,
        array $details
    ): array {
        return [
            'code' => $code,
            'severity' => $severity,
            'message' => $message,
            'coveredByPacket' => true,
            'details' => $details,
        ];
    }

    /**
     * @param list<array<string, mixed>> $sections
     * @return list<string>
     */
    private static function jatsSectionValues(array $sections, string $key): array
    {
        $values = [];
        foreach ($sections as $section) {
            $value = self::stringOrNull($section[$key] ?? null);
            if ($value !== null) {
                $values[] = $value;
            }
        }

        return array_values(array_unique($values));
    }

    /**
     * @param array<string, mixed> $section
     */
    private static function jatsSectionReference(array $section, int $index): string
    {
        $id = self::stringOrNull($section['id'] ?? null);
        $path = 'section[' . ($index + 1) . ']';

        return $id === null ? $path : $path . '#' . $id;
    }

    /**
     * @param array<string, mixed> $referenceBackMatter
     * @return array<string, mixed>
     */
    private static function jatsFundingReviewSummary(\DOMElement $root, array $referenceBackMatter): array
    {
        $referenceIds = array_values(array_filter(
            $referenceBackMatter['referenceIds'] ?? [],
            static fn (mixed $id): bool => is_string($id) && $id !== ''
        ));
        $safeReferenceMap = self::jatsSafeReferenceSummaryMap($referenceBackMatter['references'] ?? []);
        $fundingGroups = [];
        foreach (self::descendantElements($root, 'funding-group') as $index => $fundingGroup) {
            $fundingGroups[] = self::jatsFundingGroupSummary($fundingGroup, $index, $referenceIds);
        }

        $fundingSources = [];
        foreach (self::descendantElements($root, 'funding-source') as $index => $fundingSource) {
            $fundingSources[] = self::jatsFundingSourceSummary(
                $fundingSource,
                $index,
                self::jatsFundingGroupIdFor($fundingSource),
                self::jatsAwardGroupIdFor($fundingSource)
            );
        }

        $awardGroups = [];
        foreach (self::descendantElements($root, 'award-group') as $index => $awardGroup) {
            $awardGroups[] = self::jatsAwardGroupSummary($awardGroup, $index, self::jatsFundingGroupIdFor($awardGroup), $referenceIds);
        }

        $awardIdRecords = self::jatsAwardIdRecords($root);
        $awardIds = array_values(array_map(
            static fn (array $record): string => (string) $record['awardId'],
            $awardIdRecords
        ));
        $duplicateAwardIds = self::jatsDuplicateStrings($awardIds);
        $fundingSourceIdentifierRecords = self::jatsFundingSourceIdentifierRecords($fundingSources);
        $fundingInstitutions = self::jatsFundingInstitutionRecords($fundingSources);
        $awardSourcePairs = self::jatsAwardSourcePairs($awardGroups);
        $duplicateAwardSourcePairs = self::jatsDuplicateAwardSourcePairs($awardSourcePairs);
        $duplicateFunderIdentifiers = self::jatsDuplicateFunderIdentifiers($fundingSourceIdentifierRecords);
        $conflictingAwardSourcePairs = self::jatsConflictingAwardSourcePairs($awardSourcePairs);
        $fundingInstitutionSourceMismatches = self::jatsFundingInstitutionSourceMismatches($root, $fundingSources);
        $fundingLinkedReferences = self::jatsFundingLinkedReferenceSummaries(
            $root,
            $referenceIds,
            $safeReferenceMap,
            $conflictingAwardSourcePairs
        );
        $fundingReferenceBacklinks = self::jatsFundingReferenceBacklinkSummaries($fundingLinkedReferences, $safeReferenceMap);
        $fundingDiagnostics = self::jatsFundingDiagnostics(
            $fundingGroups,
            $awardGroups,
            $awardIdRecords,
            $duplicateAwardIds,
            $awardSourcePairs,
            $duplicateAwardSourcePairs,
            $duplicateFunderIdentifiers,
            $conflictingAwardSourcePairs,
            $fundingInstitutionSourceMismatches,
            $fundingReferenceBacklinks
        );

        return [
            'fundingGroups' => $fundingGroups,
            'fundingGroupCount' => count($fundingGroups),
            'fundingSources' => $fundingSources,
            'fundingSourceIds' => array_values(array_filter(
                array_map(static fn (array $source): ?string => $source['id'], $fundingSources),
                static fn (?string $id): bool => $id !== null && $id !== ''
            )),
            'fundingSourceCount' => count($fundingSources),
            'fundingSourceIdentifierRecords' => $fundingSourceIdentifierRecords,
            'fundingSourceIdentifierCount' => count($fundingSourceIdentifierRecords),
            'fundingSourceIdentifierTypes' => self::jatsUniqueNonEmptyStrings(array_map(
                static fn (array $record): ?string => $record['type'] ?? null,
                $fundingSourceIdentifierRecords
            )),
            'duplicateFunderIdentifiers' => $duplicateFunderIdentifiers,
            'duplicateFunderIdentifierCount' => count($duplicateFunderIdentifiers),
            'fundingInstitutions' => $fundingInstitutions,
            'fundingInstitutionNames' => self::jatsUniqueNonEmptyStrings(array_map(
                static fn (array $record): ?string => $record['text'] ?? null,
                $fundingInstitutions
            )),
            'fundingInstitutionCount' => count($fundingInstitutions),
            'fundingInstitutionSourceMismatches' => $fundingInstitutionSourceMismatches,
            'fundingInstitutionSourceMismatchCount' => count($fundingInstitutionSourceMismatches),
            'awardGroups' => $awardGroups,
            'awardGroupCount' => count($awardGroups),
            'awardIds' => $awardIds,
            'awardIdRecords' => $awardIdRecords,
            'awardIdCount' => count($awardIdRecords),
            'duplicateAwardIds' => $duplicateAwardIds,
            'awardSourcePairs' => $awardSourcePairs,
            'awardSourcePairCount' => count($awardSourcePairs),
            'duplicateAwardSourcePairs' => $duplicateAwardSourcePairs,
            'duplicateAwardSourcePairCount' => count($duplicateAwardSourcePairs),
            'conflictingAwardSourcePairs' => $conflictingAwardSourcePairs,
            'conflictingAwardSourcePairCount' => count($conflictingAwardSourcePairs),
            'fundingLinkedReferences' => $fundingLinkedReferences,
            'fundingLinkedReferenceCount' => count($fundingLinkedReferences),
            'fundingReferenceBacklinks' => $fundingReferenceBacklinks,
            'fundingReferenceBacklinkCount' => count($fundingReferenceBacklinks),
            'missingFundingReferenceBacklinkCount' => count(array_filter(
                $fundingReferenceBacklinks,
                static fn (array $backlink): bool => ($backlink['found'] ?? null) === false
            )),
            'duplicateFundingReferenceBacklinkCount' => count(array_filter(
                $fundingReferenceBacklinks,
                static fn (array $backlink): bool => ($backlink['duplicate'] ?? null) === true
            )),
            'fundingDiagnostics' => $fundingDiagnostics,
            'fundingDiagnosticCodes' => array_values(array_map(
                static fn (array $diagnostic): string => (string) $diagnostic['code'],
                $fundingDiagnostics
            )),
            'fundingDiagnosticCount' => count($fundingDiagnostics),
        ];
    }

    /**
     * @param list<string> $referenceIds
     * @return array<string, mixed>
     */
    private static function jatsFundingGroupSummary(\DOMElement $fundingGroup, int $index, array $referenceIds): array
    {
        $fundingGroupId = self::jatsTrimmedAttribute($fundingGroup, 'id');
        $fundingSources = [];
        foreach (self::descendantElements($fundingGroup, 'funding-source') as $sourceIndex => $fundingSource) {
            $fundingSources[] = self::jatsFundingSourceSummary(
                $fundingSource,
                $sourceIndex,
                $fundingGroupId,
                self::jatsAwardGroupIdFor($fundingSource)
            );
        }

        $awardGroups = [];
        foreach (self::descendantElements($fundingGroup, 'award-group') as $awardGroupIndex => $awardGroup) {
            $awardGroups[] = self::jatsAwardGroupSummary($awardGroup, $awardGroupIndex, $fundingGroupId, $referenceIds);
        }

        $awardIdRecords = self::jatsAwardIdRecords($fundingGroup, $fundingGroupId);

        return [
            'index' => $index,
            'id' => $fundingGroupId,
            'fundingSources' => $fundingSources,
            'fundingSourceIds' => array_values(array_filter(
                array_map(static fn (array $source): ?string => $source['id'], $fundingSources),
                static fn (?string $id): bool => $id !== null && $id !== ''
            )),
            'fundingSourceCount' => count($fundingSources),
            'awardGroups' => $awardGroups,
            'awardGroupIds' => array_values(array_filter(
                array_map(static fn (array $awardGroup): ?string => $awardGroup['id'], $awardGroups),
                static fn (?string $id): bool => $id !== null && $id !== ''
            )),
            'awardGroupCount' => count($awardGroups),
            'awardIds' => array_values(array_map(
                static fn (array $record): string => (string) $record['awardId'],
                $awardIdRecords
            )),
            'awardIdRecords' => $awardIdRecords,
            'awardIdCount' => count($awardIdRecords),
        ] + self::jatsReferenceLinkSummary($fundingGroup, $referenceIds);
    }

    /**
     * @param list<string> $referenceIds
     * @return array<string, mixed>
     */
    private static function jatsAwardGroupSummary(
        \DOMElement $awardGroup,
        int $index,
        ?string $fundingGroupId,
        array $referenceIds
    ): array {
        $awardGroupId = self::jatsTrimmedAttribute($awardGroup, 'id');
        $fundingStatementText = self::jatsFundingStatementText($awardGroup);
        $fundingSources = [];
        foreach (self::descendantElements($awardGroup, 'funding-source') as $sourceIndex => $fundingSource) {
            $fundingSources[] = self::jatsFundingSourceSummary($fundingSource, $sourceIndex, $fundingGroupId, $awardGroupId);
        }

        $awardIdRecords = self::jatsAwardIdRecords($awardGroup, $fundingGroupId, $awardGroupId);

        return [
            'index' => $index,
            'id' => $awardGroupId,
            'fundingGroupId' => $fundingGroupId,
            'fundingSources' => $fundingSources,
            'fundingSourceIds' => array_values(array_filter(
                array_map(static fn (array $source): ?string => $source['id'], $fundingSources),
                static fn (?string $id): bool => $id !== null && $id !== ''
            )),
            'fundingSourceCount' => count($fundingSources),
            'awardIds' => array_values(array_map(
                static fn (array $record): string => (string) $record['awardId'],
                $awardIdRecords
            )),
            'awardIdRecords' => $awardIdRecords,
            'awardIdCount' => count($awardIdRecords),
            'fundingStatementTextBlocked' => true,
            'fundingStatementTextLength' => strlen($fundingStatementText),
            'fundingStatementTextSha256' => hash('sha256', $fundingStatementText),
        ] + self::jatsReferenceLinkSummary($awardGroup, $referenceIds);
    }

    private static function jatsFundingStatementText(\DOMElement $root): string
    {
        $texts = [];
        foreach (self::descendantElements($root, 'funding-statement') as $statement) {
            $text = self::normalizedText($statement);
            if ($text !== '') {
                $texts[] = $text;
            }
        }

        return implode(' ', $texts);
    }

    /**
     * @return array<string, mixed>
     */
    private static function jatsFundingSourceSummary(
        \DOMElement $fundingSource,
        int $index,
        ?string $fundingGroupId = null,
        ?string $awardGroupId = null
    ): array {
        $text = self::normalizedText($fundingSource);
        $identifiers = self::jatsTypedTextRecords(
            $fundingSource,
            ['institution-id', 'source-id'],
            ['institution-id-type', 'source-id-type', 'pub-id-type']
        );
        $institutions = self::jatsFundingSourceInstitutionRecords($fundingSource);
        $funderNames = self::jatsFundingSourceFunderNames($fundingSource, $institutions);

        return [
            'index' => $index,
            'id' => self::jatsTrimmedAttribute($fundingSource, 'id'),
            'fundingGroupId' => $fundingGroupId,
            'awardGroupId' => $awardGroupId,
            'sourceType' => self::jatsTrimmedAttribute($fundingSource, 'source-type')
                ?? self::jatsTrimmedAttribute($fundingSource, 'institution-type'),
            'text' => $text,
            'textLength' => strlen($text),
            'textSha256' => hash('sha256', $text),
            'identifiers' => $identifiers,
            'identifierValues' => array_values(array_map(
                static fn (array $identifier): string => (string) $identifier['value'],
                $identifiers
            )),
            'identifierTypes' => self::jatsUniqueNonEmptyStrings(array_map(
                static fn (array $identifier): ?string => $identifier['type'] ?? null,
                $identifiers
            )),
            'identifierCount' => count($identifiers),
            'institutions' => $institutions,
            'institutionNames' => array_values(array_map(
                static fn (array $institution): string => (string) $institution['text'],
                $institutions
            )),
            'institutionCount' => count($institutions),
            'funderNames' => $funderNames,
            'funderNameCount' => count($funderNames),
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function jatsFundingSourceInstitutionRecords(\DOMElement $fundingSource): array
    {
        $institutions = [];
        foreach (self::descendantElements($fundingSource, 'institution') as $index => $institution) {
            $text = self::normalizedText($institution);
            if ($text === '') {
                continue;
            }

            $identifiers = self::jatsTypedTextRecords(
                $institution,
                ['institution-id'],
                ['institution-id-type', 'source-id-type', 'pub-id-type']
            );
            $institutions[] = [
                'index' => $index,
                'id' => self::jatsTrimmedAttribute($institution, 'id'),
                'type' => self::jatsTrimmedAttribute($institution, 'institution-type')
                    ?? self::jatsTrimmedAttribute($institution, 'content-type')
                    ?? self::jatsTrimmedAttribute($institution, 'specific-use'),
                'text' => $text,
                'textLength' => strlen($text),
                'textSha256' => hash('sha256', $text),
                'identifiers' => $identifiers,
                'identifierValues' => array_values(array_map(
                    static fn (array $identifier): string => (string) $identifier['value'],
                    $identifiers
                )),
                'identifierCount' => count($identifiers),
            ];
        }

        return $institutions;
    }

    /**
     * @param list<array<string, mixed>> $institutions
     * @return list<string>
     */
    private static function jatsFundingSourceFunderNames(\DOMElement $fundingSource, array $institutions): array
    {
        $names = array_values(array_map(
            static fn (array $institution): string => (string) $institution['text'],
            $institutions
        ));

        foreach (self::descendantElements($fundingSource) as $element) {
            if ($element->localName === 'funder-name') {
                $text = self::normalizedText($element);
                if ($text !== '') {
                    $names[] = $text;
                }
                continue;
            }

            if ($element->localName !== 'named-content') {
                continue;
            }

            $contentType = self::jatsNormalizedLooseToken(
                self::jatsTrimmedAttribute($element, 'content-type')
                    ?? self::jatsTrimmedAttribute($element, 'specific-use')
            );
            if (!in_array($contentType, ['funder-name', 'funding-agency', 'funding-source', 'institution'], true)) {
                continue;
            }

            $text = self::normalizedText($element);
            if ($text !== '') {
                $names[] = $text;
            }
        }

        return self::jatsUniqueNonEmptyStrings($names);
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function jatsAwardIdRecords(
        \DOMElement $container,
        ?string $fundingGroupId = null,
        ?string $awardGroupId = null
    ): array {
        $records = [];
        $index = 0;
        foreach (self::descendantElements($container) as $awardId) {
            if (!self::jatsAwardIdentifierElement($awardId)) {
                continue;
            }

            $value = self::normalizedText($awardId);
            if ($value === '') {
                continue;
            }

            $type = null;
            $typeSourceAttribute = null;
            foreach (['award-id-type', 'pub-id-type', 'content-type', 'specific-use', 'assigning-authority'] as $attribute) {
                $attributeValue = self::jatsTrimmedAttribute($awardId, $attribute);
                if ($attributeValue === null) {
                    continue;
                }

                $type = $attributeValue;
                $typeSourceAttribute = $attribute;
                break;
            }

            $records[] = [
                'index' => $index,
                'id' => self::jatsTrimmedAttribute($awardId, 'id'),
                'element' => $awardId->localName,
                'fundingGroupId' => $fundingGroupId ?? self::jatsFundingGroupIdFor($awardId),
                'awardGroupId' => $awardGroupId ?? self::jatsAwardGroupIdFor($awardId),
                'type' => $type,
                'typeSourceAttribute' => $typeSourceAttribute,
                'awardId' => $value,
                'normalizedAwardId' => self::jatsNormalizedIdentifierValue($value),
                'sourcePosition' => self::jatsElementSourcePosition($awardId, $container),
            ];
            ++$index;
        }

        return $records;
    }

    private static function jatsAwardIdentifierElement(\DOMElement $element): bool
    {
        if (isset(self::JATS_AWARD_ID_ELEMENTS[$element->localName])) {
            return true;
        }

        if ($element->localName !== 'named-content') {
            return false;
        }

        $contentType = self::jatsNormalizedLooseToken(
            self::jatsTrimmedAttribute($element, 'content-type')
                ?? self::jatsTrimmedAttribute($element, 'specific-use')
        );
        if (!isset(self::JATS_AWARD_ID_NAMED_CONTENT_TYPES[$contentType])) {
            return false;
        }

        return self::jatsFundingGroupIdFor($element) !== null || self::jatsAwardGroupIdFor($element) !== null;
    }

    private static function jatsNormalizedLooseToken(?string $value): string
    {
        $normalized = strtolower(trim((string) $value));

        return str_replace(['_', ' '], '-', $normalized);
    }

    private static function jatsNormalizedIdentifierValue(string $value): string
    {
        return strtolower(trim(preg_replace('/[ \t\r\n\f]+/u', ' ', $value) ?? $value));
    }

    /**
     * @param list<string> $referenceIds
     * @return array{xrefTargets:list<string>, referenceXrefTargets:list<string>, linkedReferenceIds:list<string>, missingReferenceIds:list<string>}
     */
    private static function jatsReferenceLinkSummary(\DOMElement $container, array $referenceIds): array
    {
        $referenceLookup = array_fill_keys($referenceIds, true);
        $xrefTargets = [];
        $referenceXrefTargets = [];
        foreach (self::descendantElements($container, 'xref') as $xref) {
            $rid = self::jatsTrimmedAttribute($xref, 'rid');
            if ($rid === null) {
                continue;
            }

            $refType = strtolower(trim(self::jatsTrimmedAttribute($xref, 'ref-type') ?? ''));
            foreach (self::spaceSeparatedTokens($rid) as $target) {
                $xrefTargets[] = $target;
                if ($refType === 'bibr' || $refType === 'ref' || $refType === 'citation' || isset($referenceLookup[$target])) {
                    $referenceXrefTargets[] = $target;
                }
            }
        }

        $referenceXrefTargets = array_values(array_unique($referenceXrefTargets));

        return [
            'xrefTargets' => array_values(array_unique($xrefTargets)),
            'referenceXrefTargets' => $referenceXrefTargets,
            'linkedReferenceIds' => array_values(array_filter(
                $referenceXrefTargets,
                static fn (string $target): bool => isset($referenceLookup[$target])
            )),
            'missingReferenceIds' => array_values(array_filter(
                $referenceXrefTargets,
                static fn (string $target): bool => !isset($referenceLookup[$target])
            )),
        ];
    }

    private static function jatsFundingGroupIdFor(\DOMElement $element): ?string
    {
        $parent = $element->parentNode;
        while ($parent instanceof \DOMElement) {
            if ($parent->localName === 'funding-group') {
                return self::jatsTrimmedAttribute($parent, 'id');
            }

            $parent = $parent->parentNode;
        }

        return null;
    }

    private static function jatsAwardGroupIdFor(\DOMElement $element): ?string
    {
        $parent = $element->parentNode;
        while ($parent instanceof \DOMElement) {
            if ($parent->localName === 'award-group') {
                return self::jatsTrimmedAttribute($parent, 'id');
            }

            $parent = $parent->parentNode;
        }

        return null;
    }

    /**
     * @param list<array<string, mixed>> $fundingSources
     * @return list<array<string, mixed>>
     */
    private static function jatsFundingSourceIdentifierRecords(array $fundingSources): array
    {
        $records = [];
        foreach ($fundingSources as $fundingSource) {
            foreach (($fundingSource['identifiers'] ?? []) as $identifier) {
                if (!is_array($identifier)) {
                    continue;
                }

                $records[] = [
                    'fundingSourceId' => $fundingSource['id'] ?? null,
                    'fundingGroupId' => $fundingSource['fundingGroupId'] ?? null,
                    'awardGroupId' => $fundingSource['awardGroupId'] ?? null,
                    ...$identifier,
                ];
            }
        }

        return $records;
    }

    /**
     * @param list<array<string, mixed>> $fundingSources
     * @return list<array<string, mixed>>
     */
    private static function jatsFundingInstitutionRecords(array $fundingSources): array
    {
        $records = [];
        foreach ($fundingSources as $fundingSource) {
            foreach (($fundingSource['institutions'] ?? []) as $institution) {
                if (!is_array($institution)) {
                    continue;
                }

                $records[] = [
                    'fundingSourceId' => $fundingSource['id'] ?? null,
                    'fundingGroupId' => $fundingSource['fundingGroupId'] ?? null,
                    'awardGroupId' => $fundingSource['awardGroupId'] ?? null,
                    ...$institution,
                ];
            }
        }

        return $records;
    }

    /**
     * @param list<array<string, mixed>> $awardGroups
     * @return list<array<string, mixed>>
     */
    private static function jatsAwardSourcePairs(array $awardGroups): array
    {
        $pairs = [];
        foreach ($awardGroups as $awardGroup) {
            $awardIdRecords = $awardGroup['awardIdRecords'] ?? [];
            $fundingSources = $awardGroup['fundingSources'] ?? [];
            if (!is_array($awardIdRecords) || !is_array($fundingSources) || $awardIdRecords === [] || $fundingSources === []) {
                continue;
            }

            foreach ($awardIdRecords as $awardRecord) {
                if (!is_array($awardRecord)) {
                    continue;
                }

                foreach ($fundingSources as $fundingSource) {
                    if (!is_array($fundingSource)) {
                        continue;
                    }

                    $fundingSourceKey = self::jatsFundingSourcePairKey($fundingSource);
                    $pairs[] = [
                        'fundingGroupId' => $awardGroup['fundingGroupId'] ?? null,
                        'awardGroupId' => $awardGroup['id'] ?? null,
                        'awardRecordId' => $awardRecord['id'] ?? null,
                        'awardId' => $awardRecord['awardId'] ?? null,
                        'normalizedAwardId' => $awardRecord['normalizedAwardId'] ?? null,
                        'awardIdElement' => $awardRecord['element'] ?? null,
                        'awardIdType' => $awardRecord['type'] ?? null,
                        'awardIdTypeSourceAttribute' => $awardRecord['typeSourceAttribute'] ?? null,
                        'fundingSourceId' => $fundingSource['id'] ?? null,
                        'fundingSourceKey' => $fundingSourceKey,
                        'fundingSourceType' => $fundingSource['sourceType'] ?? null,
                        'fundingSourceIdentifierValues' => $fundingSource['identifierValues'] ?? [],
                        'fundingSourceIdentifierTypes' => $fundingSource['identifierTypes'] ?? [],
                        'fundingSourceInstitutionNames' => $fundingSource['institutionNames'] ?? [],
                        'linkedReferenceIds' => $awardGroup['linkedReferenceIds'] ?? [],
                        'missingReferenceIds' => $awardGroup['missingReferenceIds'] ?? [],
                    ];
                }
            }
        }

        return $pairs;
    }

    /**
     * @param array<string, mixed> $fundingSource
     */
    private static function jatsFundingSourcePairKey(array $fundingSource): string
    {
        $id = self::stringOrNull($fundingSource['id'] ?? null);
        if ($id !== null) {
            return 'id:' . $id;
        }

        $identifierValues = $fundingSource['identifierValues'] ?? [];
        if (is_array($identifierValues)) {
            $identifierValues = self::jatsUniqueNonEmptyStrings($identifierValues);
            if ($identifierValues !== []) {
                return 'identifier:' . implode('|', $identifierValues);
            }
        }

        $textSha256 = self::stringOrNull($fundingSource['textSha256'] ?? null);
        if ($textSha256 !== null) {
            return 'text-sha256:' . $textSha256;
        }

        return 'index:' . (string) ($fundingSource['index'] ?? 0);
    }

    /**
     * @param list<array<string, mixed>> $awardSourcePairs
     * @return list<array<string, mixed>>
     */
    private static function jatsDuplicateAwardSourcePairs(array $awardSourcePairs): array
    {
        $buckets = [];
        foreach ($awardSourcePairs as $pair) {
            $awardId = self::stringOrNull($pair['normalizedAwardId'] ?? null);
            $fundingSourceKey = self::stringOrNull($pair['fundingSourceKey'] ?? null);
            if ($awardId === null || $fundingSourceKey === null) {
                continue;
            }

            $buckets[$awardId . "\0" . $fundingSourceKey][] = $pair;
        }

        $duplicates = [];
        foreach ($buckets as $pairs) {
            if (count($pairs) < 2) {
                continue;
            }

            $first = $pairs[0];
            $duplicates[] = [
                'awardId' => $first['awardId'] ?? null,
                'normalizedAwardId' => $first['normalizedAwardId'] ?? null,
                'fundingSourceId' => $first['fundingSourceId'] ?? null,
                'fundingSourceKey' => $first['fundingSourceKey'] ?? null,
                'count' => count($pairs),
                'awardRecordIds' => self::jatsUniqueNonEmptyStrings(array_map(
                    static fn (array $pair): ?string => $pair['awardRecordId'] ?? null,
                    $pairs
                )),
                'fundingGroupIds' => self::jatsUniqueNonEmptyStrings(array_map(
                    static fn (array $pair): ?string => $pair['fundingGroupId'] ?? null,
                    $pairs
                )),
                'awardGroupIds' => self::jatsUniqueNonEmptyStrings(array_map(
                    static fn (array $pair): ?string => $pair['awardGroupId'] ?? null,
                    $pairs
                )),
                'linkedReferenceIds' => self::jatsUniqueMergedStrings($pairs, 'linkedReferenceIds'),
                'missingReferenceIds' => self::jatsUniqueMergedStrings($pairs, 'missingReferenceIds'),
            ];
        }

        return $duplicates;
    }

    /**
     * @param list<array<string, mixed>> $identifierRecords
     * @return list<array<string, mixed>>
     */
    private static function jatsDuplicateFunderIdentifiers(array $identifierRecords): array
    {
        $buckets = [];
        foreach ($identifierRecords as $record) {
            $value = self::stringOrNull($record['value'] ?? null);
            if ($value === null) {
                continue;
            }

            $normalizedValue = self::jatsNormalizedIdentifierValue($value);
            if ($normalizedValue === '') {
                continue;
            }

            $type = self::stringOrNull($record['type'] ?? null);
            $normalizedType = $type === null ? '' : self::jatsNormalizedLooseToken($type);
            $buckets[$normalizedType . "\0" . $normalizedValue][] = $record;
        }

        $duplicates = [];
        foreach ($buckets as $records) {
            if (count($records) < 2) {
                continue;
            }

            $first = $records[0];
            $duplicates[] = [
                'type' => $first['type'] ?? null,
                'normalizedType' => self::jatsNormalizedLooseToken((string) ($first['type'] ?? '')),
                'value' => $first['value'] ?? null,
                'normalizedValue' => self::jatsNormalizedIdentifierValue((string) ($first['value'] ?? '')),
                'count' => count($records),
                'fundingSourceIds' => self::jatsUniqueNonEmptyStrings(array_map(
                    static fn (array $record): ?string => $record['fundingSourceId'] ?? null,
                    $records
                )),
                'fundingGroupIds' => self::jatsUniqueNonEmptyStrings(array_map(
                    static fn (array $record): ?string => $record['fundingGroupId'] ?? null,
                    $records
                )),
                'awardGroupIds' => self::jatsUniqueNonEmptyStrings(array_map(
                    static fn (array $record): ?string => $record['awardGroupId'] ?? null,
                    $records
                )),
                'elements' => self::jatsUniqueNonEmptyStrings(array_map(
                    static fn (array $record): ?string => $record['element'] ?? null,
                    $records
                )),
            ];
        }

        return $duplicates;
    }

    /**
     * @param list<array<string, mixed>> $awardSourcePairs
     * @return list<array<string, mixed>>
     */
    private static function jatsConflictingAwardSourcePairs(array $awardSourcePairs): array
    {
        $buckets = [];
        foreach ($awardSourcePairs as $pair) {
            $awardId = self::stringOrNull($pair['normalizedAwardId'] ?? null);
            $fundingSourceKey = self::stringOrNull($pair['fundingSourceKey'] ?? null);
            if ($awardId === null || $fundingSourceKey === null) {
                continue;
            }

            $buckets[$awardId][$fundingSourceKey][] = $pair;
        }

        $conflicts = [];
        foreach ($buckets as $normalizedAwardId => $sourcesByKey) {
            if (count($sourcesByKey) < 2) {
                continue;
            }

            ksort($sourcesByKey);
            $sourceSummaries = [];
            foreach ($sourcesByKey as $fundingSourceKey => $pairs) {
                $first = $pairs[0];
                $sourceSummaries[] = [
                    'fundingSourceKey' => $fundingSourceKey,
                    'fundingSourceId' => $first['fundingSourceId'] ?? null,
                    'fundingSourceType' => $first['fundingSourceType'] ?? null,
                    'fundingSourceIdentifierValues' => self::jatsUniqueMergedStrings($pairs, 'fundingSourceIdentifierValues'),
                    'fundingSourceIdentifierTypes' => self::jatsUniqueMergedStrings($pairs, 'fundingSourceIdentifierTypes'),
                    'fundingSourceInstitutionNames' => self::jatsUniqueMergedStrings($pairs, 'fundingSourceInstitutionNames'),
                    'fundingGroupIds' => self::jatsUniqueNonEmptyStrings(array_map(
                        static fn (array $pair): ?string => $pair['fundingGroupId'] ?? null,
                        $pairs
                    )),
                    'awardGroupIds' => self::jatsUniqueNonEmptyStrings(array_map(
                        static fn (array $pair): ?string => $pair['awardGroupId'] ?? null,
                        $pairs
                    )),
                ];
            }

            $allPairs = array_merge(...array_values($sourcesByKey));
            $firstPair = $allPairs[0];
            $conflicts[] = [
                'awardId' => $firstPair['awardId'] ?? null,
                'normalizedAwardId' => $normalizedAwardId,
                'fundingSourceCount' => count($sourceSummaries),
                'fundingSourceIds' => self::jatsUniqueNonEmptyStrings(array_map(
                    static fn (array $summary): ?string => $summary['fundingSourceId'] ?? null,
                    $sourceSummaries
                )),
                'fundingSourceKeys' => array_values(array_keys($sourcesByKey)),
                'fundingSources' => $sourceSummaries,
                'fundingGroupIds' => self::jatsUniqueNonEmptyStrings(array_map(
                    static fn (array $pair): ?string => $pair['fundingGroupId'] ?? null,
                    $allPairs
                )),
                'awardGroupIds' => self::jatsUniqueNonEmptyStrings(array_map(
                    static fn (array $pair): ?string => $pair['awardGroupId'] ?? null,
                    $allPairs
                )),
                'linkedReferenceIds' => self::jatsUniqueMergedStrings($allPairs, 'linkedReferenceIds'),
                'missingReferenceIds' => self::jatsUniqueMergedStrings($allPairs, 'missingReferenceIds'),
            ];
        }

        return $conflicts;
    }

    /**
     * @param list<array<string, mixed>> $fundingSources
     * @return list<array<string, mixed>>
     */
    private static function jatsFundingInstitutionSourceMismatches(\DOMElement $root, array $fundingSources): array
    {
        $mismatches = [];
        foreach ($fundingSources as $fundingSource) {
            $identifierValues = $fundingSource['identifierValues'] ?? [];
            if (!is_array($identifierValues) || $identifierValues === [] || self::jatsFundingSourceSummaryHasName($fundingSource)) {
                continue;
            }

            $mismatches[] = [
                'reason' => 'missing-institution-name',
                'severity' => 'warning',
                'fundingSourceId' => $fundingSource['id'] ?? null,
                'fundingGroupId' => $fundingSource['fundingGroupId'] ?? null,
                'awardGroupId' => $fundingSource['awardGroupId'] ?? null,
                'identifierValues' => self::jatsUniqueNonEmptyStrings($identifierValues),
                'identifierTypes' => $fundingSource['identifierTypes'] ?? [],
            ];
        }

        foreach (self::descendantElements($root, 'institution-id') as $institutionId) {
            if (self::jatsNearestAncestorElement($institutionId, 'funding-source') instanceof \DOMElement) {
                continue;
            }

            $fundingGroup = self::jatsNearestAncestorElement($institutionId, 'funding-group');
            $awardGroup = self::jatsNearestAncestorElement($institutionId, 'award-group');
            if (!$fundingGroup instanceof \DOMElement && !$awardGroup instanceof \DOMElement) {
                continue;
            }

            $value = self::normalizedText($institutionId);
            if ($value === '') {
                continue;
            }

            $mismatches[] = [
                'reason' => 'outside-funding-source',
                'severity' => 'warning',
                'fundingGroupId' => $fundingGroup instanceof \DOMElement ? self::jatsTrimmedAttribute($fundingGroup, 'id') : null,
                'awardGroupId' => $awardGroup instanceof \DOMElement ? self::jatsTrimmedAttribute($awardGroup, 'id') : null,
                'element' => $institutionId->localName,
                'type' => self::jatsTrimmedAttribute($institutionId, 'institution-id-type')
                    ?? self::jatsTrimmedAttribute($institutionId, 'source-id-type')
                    ?? self::jatsTrimmedAttribute($institutionId, 'pub-id-type'),
                'value' => $value,
                'sourcePosition' => self::jatsElementSourcePosition($institutionId, $root),
            ];
        }

        return $mismatches;
    }

    /**
     * @param array<string, mixed> $fundingSource
     */
    private static function jatsFundingSourceSummaryHasName(array $fundingSource): bool
    {
        $names = [
            ...($fundingSource['institutionNames'] ?? []),
            ...($fundingSource['funderNames'] ?? []),
        ];
        if (self::jatsUniqueNonEmptyStrings($names) !== []) {
            return true;
        }

        $text = (string) ($fundingSource['text'] ?? '');
        foreach (($fundingSource['identifierValues'] ?? []) as $identifierValue) {
            if (!is_string($identifierValue) || $identifierValue === '') {
                continue;
            }

            $text = str_replace($identifierValue, '', $text);
        }

        $text = preg_replace('/[ \t\r\n\f;:,.|()[\]{}-]+/u', ' ', $text) ?? $text;

        return trim($text) !== '';
    }

    /**
     * @param list<string> $referenceIds
     * @param array<string, array<string, mixed>> $safeReferenceMap
     * @param list<array<string, mixed>> $conflictingAwardSourcePairs
     * @return list<array<string, mixed>>
     */
    private static function jatsFundingLinkedReferenceSummaries(
        \DOMElement $root,
        array $referenceIds,
        array $safeReferenceMap,
        array $conflictingAwardSourcePairs
    ): array
    {
        $referenceLookup = array_fill_keys($referenceIds, true);
        $conflictingAwardsByNormalizedId = [];
        foreach ($conflictingAwardSourcePairs as $conflict) {
            $normalizedAwardId = self::stringOrNull($conflict['normalizedAwardId'] ?? null);
            $awardId = self::stringOrNull($conflict['awardId'] ?? null);
            if ($normalizedAwardId !== null && $awardId !== null) {
                $conflictingAwardsByNormalizedId[$normalizedAwardId] = $awardId;
            }
        }

        $summaries = [];
        foreach (self::descendantElements($root, 'xref') as $xref) {
            $fundingGroup = self::jatsNearestAncestorElement($xref, 'funding-group');
            if (!$fundingGroup instanceof \DOMElement) {
                continue;
            }

            $rid = self::jatsTrimmedAttribute($xref, 'rid');
            if ($rid === null) {
                continue;
            }

            $targets = self::spaceSeparatedTokens($rid);
            $refType = self::jatsTrimmedAttribute($xref, 'ref-type');
            $referenceTargets = [];
            foreach ($targets as $target) {
                if (isset($referenceLookup[$target]) || in_array($refType, ['bibr', 'citation', 'ref'], true)) {
                    $referenceTargets[] = $target;
                }
            }

            if ($referenceTargets === []) {
                continue;
            }

            $awardGroup = self::jatsNearestAncestorElement($xref, 'award-group');
            $context = $awardGroup instanceof \DOMElement ? $awardGroup : $fundingGroup;
            $fundingGroupId = self::jatsTrimmedAttribute($fundingGroup, 'id');
            $awardGroupId = $awardGroup instanceof \DOMElement ? self::jatsTrimmedAttribute($awardGroup, 'id') : null;
            $awardRecords = self::jatsAwardIdRecords($context, $fundingGroupId, $awardGroupId);
            $awardIds = self::jatsUniqueNonEmptyStrings(array_map(
                static fn (array $record): ?string => $record['awardId'] ?? null,
                $awardRecords
            ));
            $normalizedAwardIds = self::jatsUniqueNonEmptyStrings(array_map(
                static fn (array $record): ?string => $record['normalizedAwardId'] ?? null,
                $awardRecords
            ));
            $conflictingAwardIds = [];
            foreach ($normalizedAwardIds as $normalizedAwardId) {
                if (isset($conflictingAwardsByNormalizedId[$normalizedAwardId])) {
                    $conflictingAwardIds[] = $conflictingAwardsByNormalizedId[$normalizedAwardId];
                }
            }

            $fundingSources = [];
            foreach (self::descendantElements($context, 'funding-source') as $sourceIndex => $fundingSource) {
                $fundingSources[] = self::jatsFundingSourceSummary($fundingSource, $sourceIndex, $fundingGroupId, $awardGroupId);
            }

            $linkText = self::normalizedText($xref);
            $summaries[] = [
                'id' => self::jatsTrimmedAttribute($xref, 'id'),
                'container' => $awardGroup instanceof \DOMElement ? 'award-group' : 'funding-group',
                'fundingGroupId' => $fundingGroupId,
                'awardGroupId' => $awardGroupId,
                'refType' => $refType,
                'targets' => $targets,
                'linkedReferenceIds' => array_values(array_filter(
                    $referenceTargets,
                    static fn (string $target): bool => isset($referenceLookup[$target])
                )),
                'missingReferenceIds' => array_values(array_filter(
                    $referenceTargets,
                    static fn (string $target): bool => !isset($referenceLookup[$target])
                )),
                'linkTextBlocked' => true,
                'linkTextLength' => strlen($linkText),
                'linkTextSha256' => hash('sha256', $linkText),
                'awardIds' => $awardIds,
                'normalizedAwardIds' => $normalizedAwardIds,
                'conflictingAwardIds' => self::jatsUniqueNonEmptyStrings($conflictingAwardIds),
                'awardSourceConflictCount' => count(self::jatsUniqueNonEmptyStrings($conflictingAwardIds)),
                'fundingSourceIds' => self::jatsUniqueNonEmptyStrings(array_map(
                    static fn (array $source): ?string => $source['id'] ?? null,
                    $fundingSources
                )),
                'fundingSourceKeys' => self::jatsUniqueNonEmptyStrings(array_map(
                    static fn (array $source): string => self::jatsFundingSourcePairKey($source),
                    $fundingSources
                )),
                'fundingSourceTextDigests' => self::jatsFundingSourceTextDigests($fundingSources),
                'references' => array_map(
                    static fn (string $target): array => $safeReferenceMap[$target] ?? [
                        'id' => $target,
                        'found' => false,
                        'citationTextBlocked' => true,
                        'textLength' => null,
                        'textSha256' => null,
                        'blockedCitationTextPayloadCount' => 0,
                        'citationElementNames' => [],
                    ],
                    $referenceTargets
                ),
                'sourcePosition' => self::jatsElementSourcePosition($xref, $root),
            ];
        }

        return $summaries;
    }

    /**
     * @param list<array<string, mixed>> $fundingSources
     * @return list<array<string, mixed>>
     */
    private static function jatsFundingSourceTextDigests(array $fundingSources): array
    {
        $digests = [];
        foreach ($fundingSources as $fundingSource) {
            $digests[] = [
                'id' => $fundingSource['id'] ?? null,
                'sourceType' => $fundingSource['sourceType'] ?? null,
                'fundingSourceKey' => self::jatsFundingSourcePairKey($fundingSource),
                'textBlocked' => true,
                'textLength' => (int) ($fundingSource['textLength'] ?? 0),
                'textSha256' => self::stringOrNull($fundingSource['textSha256'] ?? null),
            ];
        }

        return $digests;
    }

    /**
     * @param list<array<string, mixed>> $linkedReferences
     * @param array<string, array<string, mixed>> $safeReferenceMap
     * @return list<array<string, mixed>>
     */
    private static function jatsFundingReferenceBacklinkSummaries(array $linkedReferences, array $safeReferenceMap): array
    {
        $backlinks = [];
        foreach ($linkedReferences as $linkedReference) {
            $linkedReferenceIds = is_array($linkedReference['linkedReferenceIds'] ?? null)
                ? $linkedReference['linkedReferenceIds']
                : [];
            $missingReferenceIds = is_array($linkedReference['missingReferenceIds'] ?? null)
                ? $linkedReference['missingReferenceIds']
                : [];
            $targets = array_values(array_unique([...$linkedReferenceIds, ...$missingReferenceIds]));

            foreach ($targets as $target) {
                if (!is_string($target) || trim($target) === '') {
                    continue;
                }

                $target = trim($target);
                if (!isset($backlinks[$target])) {
                    $reference = $safeReferenceMap[$target] ?? null;
                    $backlinks[$target] = [
                        'referenceId' => $target,
                        'found' => $reference !== null,
                        'label' => $reference['label'] ?? null,
                        'status' => $reference['status'] ?? null,
                        'metadataOnly' => true,
                        'citationTextBlocked' => true,
                        'textLength' => $reference['textLength'] ?? null,
                        'textSha256' => $reference['textSha256'] ?? null,
                        'blockedCitationTextPayloadCount' => $reference['blockedCitationTextPayloadCount'] ?? 0,
                        'citationElementNames' => $reference['citationElementNames'] ?? [],
                        'linkCount' => 0,
                        'duplicate' => false,
                        'fundingGroupIds' => [],
                        'awardGroupIds' => [],
                        'awardIds' => [],
                        'normalizedAwardIds' => [],
                        'conflictingAwardIds' => [],
                        'awardSourceConflictCount' => 0,
                        'fundingSourceIds' => [],
                        'fundingSourceKeys' => [],
                        'links' => [],
                        'duplicateLinkProvenance' => [],
                    ];
                }

                $awardIds = is_array($linkedReference['awardIds'] ?? null) ? $linkedReference['awardIds'] : [];
                $normalizedAwardIds = is_array($linkedReference['normalizedAwardIds'] ?? null) ? $linkedReference['normalizedAwardIds'] : [];
                $conflictingAwardIds = is_array($linkedReference['conflictingAwardIds'] ?? null) ? $linkedReference['conflictingAwardIds'] : [];
                $fundingSourceIds = is_array($linkedReference['fundingSourceIds'] ?? null) ? $linkedReference['fundingSourceIds'] : [];
                $fundingSourceKeys = is_array($linkedReference['fundingSourceKeys'] ?? null) ? $linkedReference['fundingSourceKeys'] : [];
                $link = [
                    'id' => $linkedReference['id'] ?? null,
                    'container' => $linkedReference['container'] ?? null,
                    'fundingGroupId' => $linkedReference['fundingGroupId'] ?? null,
                    'awardGroupId' => $linkedReference['awardGroupId'] ?? null,
                    'refType' => $linkedReference['refType'] ?? null,
                    'awardIds' => self::jatsUniqueNonEmptyStrings($awardIds),
                    'normalizedAwardIds' => self::jatsUniqueNonEmptyStrings($normalizedAwardIds),
                    'conflictingAwardIds' => self::jatsUniqueNonEmptyStrings($conflictingAwardIds),
                    'awardSourceConflictCount' => count(self::jatsUniqueNonEmptyStrings($conflictingAwardIds)),
                    'fundingSourceIds' => self::jatsUniqueNonEmptyStrings($fundingSourceIds),
                    'fundingSourceKeys' => self::jatsUniqueNonEmptyStrings($fundingSourceKeys),
                    'linkTextBlocked' => true,
                    'linkTextLength' => (int) ($linkedReference['linkTextLength'] ?? 0),
                    'linkTextSha256' => self::stringOrNull($linkedReference['linkTextSha256'] ?? null),
                    'sourcePosition' => $linkedReference['sourcePosition'] ?? null,
                ];

                $backlinks[$target]['links'][] = $link;
                $fundingGroupId = self::stringOrNull($linkedReference['fundingGroupId'] ?? null);
                if ($fundingGroupId !== null) {
                    $backlinks[$target]['fundingGroupIds'][] = $fundingGroupId;
                }
                $awardGroupId = self::stringOrNull($linkedReference['awardGroupId'] ?? null);
                if ($awardGroupId !== null) {
                    $backlinks[$target]['awardGroupIds'][] = $awardGroupId;
                }
                array_push($backlinks[$target]['awardIds'], ...$awardIds);
                array_push($backlinks[$target]['normalizedAwardIds'], ...$normalizedAwardIds);
                array_push($backlinks[$target]['conflictingAwardIds'], ...$conflictingAwardIds);
                array_push($backlinks[$target]['fundingSourceIds'], ...$fundingSourceIds);
                array_push($backlinks[$target]['fundingSourceKeys'], ...$fundingSourceKeys);
            }
        }

        ksort($backlinks);
        foreach ($backlinks as $target => $backlink) {
            $conflictingAwardIds = self::jatsUniqueNonEmptyStrings($backlink['conflictingAwardIds']);
            $backlinks[$target]['linkCount'] = count($backlink['links']);
            $backlinks[$target]['duplicate'] = count($backlink['links']) > 1;
            $backlinks[$target]['fundingGroupIds'] = self::jatsUniqueNonEmptyStrings($backlink['fundingGroupIds']);
            $backlinks[$target]['awardGroupIds'] = self::jatsUniqueNonEmptyStrings($backlink['awardGroupIds']);
            $backlinks[$target]['awardIds'] = self::jatsUniqueNonEmptyStrings($backlink['awardIds']);
            $backlinks[$target]['normalizedAwardIds'] = self::jatsUniqueNonEmptyStrings($backlink['normalizedAwardIds']);
            $backlinks[$target]['conflictingAwardIds'] = $conflictingAwardIds;
            $backlinks[$target]['awardSourceConflictCount'] = count($conflictingAwardIds);
            $backlinks[$target]['fundingSourceIds'] = self::jatsUniqueNonEmptyStrings($backlink['fundingSourceIds']);
            $backlinks[$target]['fundingSourceKeys'] = self::jatsUniqueNonEmptyStrings($backlink['fundingSourceKeys']);
            $backlinks[$target]['duplicateLinkProvenance'] = count($backlink['links']) > 1
                ? $backlink['links']
                : [];
        }

        $orderedBacklinks = array_values($backlinks);
        usort(
            $orderedBacklinks,
            static function (array $left, array $right): int {
                $priority = static function (array $backlink): int {
                    if (($backlink['found'] ?? null) === false) {
                        return 0;
                    }

                    return ($backlink['duplicate'] ?? null) === true ? 1 : 2;
                };

                $priorityComparison = $priority($left) <=> $priority($right);
                if ($priorityComparison !== 0) {
                    return $priorityComparison;
                }

                return strcmp((string) ($left['referenceId'] ?? ''), (string) ($right['referenceId'] ?? ''));
            }
        );

        return $orderedBacklinks;
    }

    /**
     * @param list<array<string, mixed>> $references
     * @return array<string, array<string, mixed>>
     */
    private static function jatsSafeReferenceSummaryMap(array $references): array
    {
        $map = [];
        foreach ($references as $reference) {
            if (!is_array($reference)) {
                continue;
            }

            $id = self::stringOrNull($reference['id'] ?? null);
            if ($id === null) {
                continue;
            }

            $map[$id] = [
                'id' => $id,
                'found' => true,
                'label' => self::stringOrNull($reference['label'] ?? null),
                'status' => self::stringOrNull($reference['status'] ?? null),
                'metadataOnly' => true,
                'citationTextBlocked' => true,
                'textLength' => (int) ($reference['textLength'] ?? 0),
                'textSha256' => self::stringOrNull($reference['textSha256'] ?? null),
                'blockedCitationTextPayloadCount' => (int) ($reference['blockedCitationTextPayloadCount'] ?? 0),
                'citationElementNames' => is_array($reference['citationElementNames'] ?? null)
                    ? self::jatsUniqueNonEmptyStrings($reference['citationElementNames'])
                    : [],
            ];
        }

        return $map;
    }

    private static function jatsNearestAncestorElement(\DOMElement $element, string $localName): ?\DOMElement
    {
        $current = $element->parentNode;
        while ($current instanceof \DOMElement) {
            if ($current->localName === $localName) {
                return $current;
            }

            $current = $current->parentNode;
        }

        return null;
    }

    /**
     * @param list<string> $values
     * @return list<string>
     */
    private static function jatsDuplicateStrings(array $values): array
    {
        $counts = [];
        foreach ($values as $value) {
            if ($value === '') {
                continue;
            }

            $counts[$value] = ($counts[$value] ?? 0) + 1;
        }

        return array_values(array_filter(
            array_keys($counts),
            static fn (string $value): bool => $counts[$value] > 1
        ));
    }

    /**
     * @param list<array<string, mixed>> $fundingGroups
     * @param list<array<string, mixed>> $awardGroups
     * @param list<array<string, mixed>> $awardIdRecords
     * @param list<string> $duplicateAwardIds
     * @param list<array<string, mixed>> $awardSourcePairs
     * @param list<array<string, mixed>> $duplicateAwardSourcePairs
     * @param list<array<string, mixed>> $duplicateFunderIdentifiers
     * @param list<array<string, mixed>> $conflictingAwardSourcePairs
     * @param list<array<string, mixed>> $fundingInstitutionSourceMismatches
     * @param list<array<string, mixed>> $fundingReferenceBacklinks
     * @return list<array<string, mixed>>
     */
    private static function jatsFundingDiagnostics(
        array $fundingGroups,
        array $awardGroups,
        array $awardIdRecords,
        array $duplicateAwardIds,
        array $awardSourcePairs,
        array $duplicateAwardSourcePairs,
        array $duplicateFunderIdentifiers,
        array $conflictingAwardSourcePairs,
        array $fundingInstitutionSourceMismatches,
        array $fundingReferenceBacklinks
    ): array {
        $diagnostics = [];
        foreach ($duplicateAwardIds as $duplicateAwardId) {
            $matchingRecords = array_values(array_filter(
                $awardIdRecords,
                static fn (array $record): bool => $record['awardId'] === $duplicateAwardId
            ));
            $diagnostics[] = [
                'code' => 'duplicate-award-id',
                'severity' => 'warning',
                'awardId' => $duplicateAwardId,
                'count' => count($matchingRecords),
                'recordIds' => array_values(array_filter(
                    array_map(static fn (array $record): ?string => $record['id'], $matchingRecords),
                    static fn (?string $id): bool => $id !== null && $id !== ''
                )),
            ];
        }

        foreach ($duplicateAwardSourcePairs as $duplicatePair) {
            $diagnostics[] = [
                'code' => 'duplicate-award-source-pair',
                'severity' => 'warning',
                'awardId' => $duplicatePair['awardId'] ?? null,
                'normalizedAwardId' => $duplicatePair['normalizedAwardId'] ?? null,
                'fundingSourceId' => $duplicatePair['fundingSourceId'] ?? null,
                'fundingSourceKey' => $duplicatePair['fundingSourceKey'] ?? null,
                'count' => $duplicatePair['count'] ?? 0,
                'recordIds' => $duplicatePair['awardRecordIds'] ?? [],
                'fundingGroupIds' => $duplicatePair['fundingGroupIds'] ?? [],
                'awardGroupIds' => $duplicatePair['awardGroupIds'] ?? [],
                'linkedReferenceIds' => $duplicatePair['linkedReferenceIds'] ?? [],
                'missingReferenceIds' => $duplicatePair['missingReferenceIds'] ?? [],
            ];
        }

        foreach ($duplicateFunderIdentifiers as $duplicateIdentifier) {
            $diagnostics[] = [
                'code' => 'duplicate-funder-identifier',
                'severity' => 'warning',
                'type' => $duplicateIdentifier['type'] ?? null,
                'normalizedType' => $duplicateIdentifier['normalizedType'] ?? null,
                'value' => $duplicateIdentifier['value'] ?? null,
                'normalizedValue' => $duplicateIdentifier['normalizedValue'] ?? null,
                'count' => $duplicateIdentifier['count'] ?? 0,
                'fundingSourceIds' => $duplicateIdentifier['fundingSourceIds'] ?? [],
                'fundingGroupIds' => $duplicateIdentifier['fundingGroupIds'] ?? [],
                'awardGroupIds' => $duplicateIdentifier['awardGroupIds'] ?? [],
                'elements' => $duplicateIdentifier['elements'] ?? [],
            ];
        }

        foreach ($conflictingAwardSourcePairs as $conflict) {
            $diagnostics[] = [
                'code' => 'conflicting-award-source-pair',
                'severity' => 'warning',
                'awardId' => $conflict['awardId'] ?? null,
                'normalizedAwardId' => $conflict['normalizedAwardId'] ?? null,
                'fundingSourceCount' => $conflict['fundingSourceCount'] ?? 0,
                'fundingSourceIds' => $conflict['fundingSourceIds'] ?? [],
                'fundingSourceKeys' => $conflict['fundingSourceKeys'] ?? [],
                'fundingGroupIds' => $conflict['fundingGroupIds'] ?? [],
                'awardGroupIds' => $conflict['awardGroupIds'] ?? [],
                'linkedReferenceIds' => $conflict['linkedReferenceIds'] ?? [],
                'missingReferenceIds' => $conflict['missingReferenceIds'] ?? [],
            ];
        }

        foreach ($fundingInstitutionSourceMismatches as $mismatch) {
            $diagnostics[] = [
                'code' => 'institution-id-funding-source-mismatch',
                'severity' => $mismatch['severity'] ?? 'warning',
                'reason' => $mismatch['reason'] ?? null,
                'fundingSourceId' => $mismatch['fundingSourceId'] ?? null,
                'fundingGroupId' => $mismatch['fundingGroupId'] ?? null,
                'awardGroupId' => $mismatch['awardGroupId'] ?? null,
                'identifierValues' => $mismatch['identifierValues'] ?? [],
                'identifierTypes' => $mismatch['identifierTypes'] ?? [],
                'element' => $mismatch['element'] ?? null,
                'type' => $mismatch['type'] ?? null,
                'value' => $mismatch['value'] ?? null,
                'sourcePosition' => $mismatch['sourcePosition'] ?? null,
            ];
        }

        foreach ($awardGroups as $awardGroup) {
            if (($awardGroup['awardIdCount'] ?? 0) > 0) {
                continue;
            }

            $diagnostics[] = [
                'code' => 'missing-award-id',
                'severity' => 'warning',
                'container' => 'award-group',
                'id' => $awardGroup['id'] ?? null,
                'fundingGroupId' => $awardGroup['fundingGroupId'] ?? null,
                'fundingSourceIds' => $awardGroup['fundingSourceIds'] ?? [],
            ];
        }

        foreach ($fundingGroups as $fundingGroup) {
            if (($fundingGroup['awardGroupCount'] ?? 0) > 0 || ($fundingGroup['awardIdCount'] ?? 0) > 0) {
                continue;
            }

            $diagnostics[] = [
                'code' => 'missing-award-id',
                'severity' => 'warning',
                'container' => 'funding-group',
                'id' => $fundingGroup['id'] ?? null,
                'fundingSourceIds' => $fundingGroup['fundingSourceIds'] ?? [],
            ];
        }

        foreach ($awardGroups as $awardGroup) {
            if (($awardGroup['awardIdCount'] ?? 0) === 0 || ($awardGroup['fundingSourceCount'] ?? 0) > 0) {
                continue;
            }

            $diagnostics[] = [
                'code' => 'missing-funding-source',
                'severity' => 'warning',
                'container' => 'award-group',
                'id' => $awardGroup['id'] ?? null,
                'fundingGroupId' => $awardGroup['fundingGroupId'] ?? null,
                'awardIds' => $awardGroup['awardIds'] ?? [],
                'linkedReferenceIds' => $awardGroup['linkedReferenceIds'] ?? [],
                'missingReferenceIds' => $awardGroup['missingReferenceIds'] ?? [],
            ];
        }

        foreach ($fundingGroups as $fundingGroup) {
            if (($fundingGroup['awardIdCount'] ?? 0) === 0 || ($fundingGroup['fundingSourceCount'] ?? 0) > 0) {
                continue;
            }

            $diagnostics[] = [
                'code' => 'missing-funding-source',
                'severity' => 'warning',
                'container' => 'funding-group',
                'id' => $fundingGroup['id'] ?? null,
                'awardIds' => $fundingGroup['awardIds'] ?? [],
                'linkedReferenceIds' => $fundingGroup['linkedReferenceIds'] ?? [],
                'missingReferenceIds' => $fundingGroup['missingReferenceIds'] ?? [],
            ];
        }

        foreach ($fundingReferenceBacklinks as $backlink) {
            if (($backlink['found'] ?? null) !== false) {
                continue;
            }

            $diagnostics[] = [
                'code' => 'missing-funding-reference-backlink',
                'severity' => 'warning',
                'referenceId' => $backlink['referenceId'] ?? null,
                'linkCount' => $backlink['linkCount'] ?? 0,
                'fundingGroupIds' => $backlink['fundingGroupIds'] ?? [],
                'awardGroupIds' => $backlink['awardGroupIds'] ?? [],
                'awardIds' => $backlink['awardIds'] ?? [],
                'fundingSourceIds' => $backlink['fundingSourceIds'] ?? [],
                'conflictingAwardIds' => $backlink['conflictingAwardIds'] ?? [],
                'duplicateLinkProvenance' => $backlink['duplicateLinkProvenance'] ?? [],
            ];
        }

        foreach ($fundingReferenceBacklinks as $backlink) {
            if (($backlink['duplicate'] ?? null) !== true) {
                continue;
            }

            $diagnostics[] = [
                'code' => 'duplicate-funding-reference-backlink',
                'severity' => 'warning',
                'referenceId' => $backlink['referenceId'] ?? null,
                'found' => $backlink['found'] ?? null,
                'linkCount' => $backlink['linkCount'] ?? 0,
                'fundingGroupIds' => $backlink['fundingGroupIds'] ?? [],
                'awardGroupIds' => $backlink['awardGroupIds'] ?? [],
                'awardIds' => $backlink['awardIds'] ?? [],
                'fundingSourceIds' => $backlink['fundingSourceIds'] ?? [],
                'conflictingAwardIds' => $backlink['conflictingAwardIds'] ?? [],
                'duplicateLinkProvenance' => $backlink['duplicateLinkProvenance'] ?? [],
            ];
        }

        return $diagnostics;
    }

    /**
     * @param list<string> $referenceIds
     * @return list<array<string, mixed>>
     */
    private static function jatsAcknowledgmentSummaries(\DOMElement $root, array $referenceIds): array
    {
        $acknowledgments = [];
        foreach (self::descendantElements($root, 'ack') as $index => $acknowledgment) {
            $text = self::normalizedText($acknowledgment);
            $acknowledgments[] = [
                'index' => $index,
                'id' => self::jatsTrimmedAttribute($acknowledgment, 'id'),
                'title' => self::jatsFirstText($acknowledgment, ['title']),
                'paragraphCount' => count(self::descendantElements($acknowledgment, 'p')),
                'textBlocked' => true,
                'textLength' => strlen($text),
                'textSha256' => hash('sha256', $text),
            ] + self::jatsReferenceLinkSummary($acknowledgment, $referenceIds);
        }

        return $acknowledgments;
    }

    /**
     * @param list<array<string, mixed>> $records
     * @return list<string>
     */
    private static function jatsUniqueMergedStrings(array $records, string $key): array
    {
        $values = [];
        foreach ($records as $record) {
            if (!isset($record[$key]) || !is_array($record[$key])) {
                continue;
            }

            foreach ($record[$key] as $value) {
                if (is_string($value) && $value !== '') {
                    $values[] = $value;
                }
            }
        }

        return array_values(array_unique($values));
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return array<string, mixed>
     */
    private static function jatsReferenceBackMatterSummary(\DOMElement $root, array $xrefs): array
    {
        $refLists = [];
        foreach (self::descendantElements($root, 'ref-list') as $refList) {
            $referenceIds = [];
            foreach (self::childElements($refList, 'ref') as $reference) {
                $id = self::jatsTrimmedAttribute($reference, 'id');
                if ($id !== null) {
                    $referenceIds[] = $id;
                }
            }

            $title = self::firstChildElement($refList, 'title');
            $refLists[] = [
                'id' => self::jatsTrimmedAttribute($refList, 'id'),
                'title' => $title instanceof \DOMElement ? self::normalizedText($title) : null,
                'referenceCount' => count(self::childElements($refList, 'ref')),
                'referenceIds' => self::jatsUniqueNonEmptyStrings($referenceIds),
                'nestedRefListCount' => count(self::childElements($refList, 'ref-list')),
            ];
        }

        $referenceElements = self::descendantElements($root, 'ref');
        $referenceIds = [];
        $missingIdReferenceCount = 0;
        foreach ($referenceElements as $reference) {
            $id = self::jatsTrimmedAttribute($reference, 'id');
            if ($id === null) {
                ++$missingIdReferenceCount;
                continue;
            }

            $referenceIds[] = $id;
        }

        $referenceIds = self::jatsUniqueNonEmptyStrings($referenceIds);
        $referenceIdLookup = array_fill_keys($referenceIds, true);
        $allXrefCounts = self::jatsXrefCountsByTarget($xrefs);
        $bibliographyXrefs = [];
        $resolvedReferenceIds = [];
        $unresolvedReferenceIds = [];
        $inboundBibrXrefCounts = [];
        $resolvedBibrXrefCount = 0;

        foreach ($xrefs as $xref) {
            $refType = $xref['refType'] ?? null;
            if (!is_string($refType) || strtolower(trim($refType)) !== 'bibr') {
                continue;
            }

            $targets = $xref['targets'] ?? [];
            if (!is_array($targets)) {
                continue;
            }

            $xrefText = is_string($xref['text'] ?? null) ? $xref['text'] : '';
            foreach ($targets as $targetId) {
                if (!is_string($targetId) || trim($targetId) === '') {
                    continue;
                }

                $targetId = trim($targetId);
                $resolved = isset($referenceIdLookup[$targetId]);
                if ($resolved) {
                    ++$resolvedBibrXrefCount;
                    $resolvedReferenceIds[] = $targetId;
                    $inboundBibrXrefCounts[$targetId] = ($inboundBibrXrefCounts[$targetId] ?? 0) + 1;
                } else {
                    $unresolvedReferenceIds[] = $targetId;
                }

                $bibliographyXrefs[] = [
                    'targetId' => $targetId,
                    'refType' => $refType,
                    'status' => $resolved ? 'resolved' : 'unresolved',
                    'resolved' => $resolved,
                    'sourceTextLength' => strlen($xrefText),
                    'sourceTextSha256' => hash('sha256', $xrefText),
                ];
            }
        }

        $resolvedReferenceIds = self::jatsUniqueNonEmptyStrings($resolvedReferenceIds);
        $unresolvedReferenceIds = self::jatsUniqueNonEmptyStrings($unresolvedReferenceIds);
        $unreferencedReferenceIds = array_values(array_filter(
            $referenceIds,
            static fn (string $id): bool => !isset($inboundBibrXrefCounts[$id])
        ));

        $references = [];
        $safeReferenceLabels = [];
        $safeReferenceAuthors = [];
        $safeReferenceDates = [];
        $safeReferenceYears = [];
        $safeReferenceTitles = [];
        $safeReferenceSources = [];
        $referenceTitleBuckets = [];
        $referenceSourceBuckets = [];
        $referenceSourceTypes = [];
        $referenceSourceTypeCounts = [];
        $referencesMissingTitles = [];
        $referencesMissingSources = [];
        $referenceIdentifiers = [];
        $referenceIdentifierSourceCounts = [];
        $referenceIdentifierTypes = [];
        $referenceIdentifierBuckets = [];
        $referenceIdentifierLookup = [];
        $referencesMissingIdentifiers = [];
        $blockedCitationTextPayloadCount = 0;
        $blockedCitationTextPayloadElementNames = [];
        foreach ($referenceElements as $reference) {
            $id = self::jatsTrimmedAttribute($reference, 'id');
            $summary = self::jatsBibliographyReferenceSummary(
                $reference,
                $id !== null ? ($inboundBibrXrefCounts[$id] ?? 0) : 0,
                $id !== null ? ($allXrefCounts[$id] ?? 0) : 0
            );
            $label = $summary['label'] ?? null;
            if (is_string($label) && $label !== '') {
                $safeReferenceLabels[] = [
                    'id' => $summary['id'] ?? null,
                    'label' => $label,
                ];
            }
            $authorNames = $summary['authorNames'] ?? [];
            if (is_array($authorNames) && $authorNames !== []) {
                $safeReferenceAuthors[] = [
                    'id' => $summary['id'] ?? null,
                    'authorNames' => $authorNames,
                ];
            }
            $dateSummaries = $summary['dates'] ?? [];
            if (is_array($dateSummaries) && $dateSummaries !== []) {
                $safeReferenceDates[] = [
                    'id' => $summary['id'] ?? null,
                    'dates' => $dateSummaries,
                ];
            }
            $years = $summary['years'] ?? [];
            if (is_array($years) && $years !== []) {
                $safeReferenceYears[] = [
                    'id' => $summary['id'] ?? null,
                    'years' => $years,
                ];
            }
            $titleFields = $summary['titleFields'] ?? [];
            if (is_array($titleFields) && $titleFields !== []) {
                $safeReferenceTitles[] = [
                    'id' => $summary['id'] ?? null,
                    'status' => $summary['status'] ?? null,
                    'inboundBibrXrefCount' => $summary['inboundBibrXrefCount'] ?? 0,
                    'titleFields' => $titleFields,
                ];
                foreach ($titleFields as $titleField) {
                    if (!is_array($titleField)) {
                        continue;
                    }
                    self::appendJatsReferenceTextBucket(
                        $referenceTitleBuckets,
                        $summary,
                        $titleField,
                        (string) ($titleField['value'] ?? '')
                    );
                }
            } elseif (($summary['citationElementNames'] ?? []) !== []) {
                $referencesMissingTitles[] = [
                    'id' => $summary['id'] ?? null,
                    'status' => $summary['status'] ?? null,
                    'inboundBibrXrefCount' => $summary['inboundBibrXrefCount'] ?? 0,
                    'citationElementNames' => $summary['citationElementNames'] ?? [],
                ];
            }
            $sourceFields = $summary['sourceFields'] ?? [];
            if (is_array($sourceFields) && $sourceFields !== []) {
                $safeReferenceSources[] = [
                    'id' => $summary['id'] ?? null,
                    'status' => $summary['status'] ?? null,
                    'inboundBibrXrefCount' => $summary['inboundBibrXrefCount'] ?? 0,
                    'sourceFields' => $sourceFields,
                ];
                foreach ($sourceFields as $sourceField) {
                    if (!is_array($sourceField)) {
                        continue;
                    }
                    self::appendJatsReferenceTextBucket(
                        $referenceSourceBuckets,
                        $summary,
                        $sourceField,
                        (string) ($sourceField['value'] ?? '')
                    );
                }
            } elseif (($summary['citationElementNames'] ?? []) !== []) {
                $referencesMissingSources[] = [
                    'id' => $summary['id'] ?? null,
                    'status' => $summary['status'] ?? null,
                    'inboundBibrXrefCount' => $summary['inboundBibrXrefCount'] ?? 0,
                    'citationElementNames' => $summary['citationElementNames'] ?? [],
                ];
            }
            $referenceSourceType = $summary['referenceSourceType'] ?? null;
            if (is_string($referenceSourceType) && $referenceSourceType !== '') {
                $referenceSourceTypes[] = $referenceSourceType;
                $referenceSourceTypeCounts[$referenceSourceType] = ($referenceSourceTypeCounts[$referenceSourceType] ?? 0) + 1;
            }
            $identifiers = $summary['identifiers'] ?? [];
            if (is_array($identifiers) && $identifiers !== []) {
                $contextIdentifiers = [];
                foreach ($identifiers as $identifier) {
                    if (!is_array($identifier)) {
                        continue;
                    }

                    $contextIdentifier = [
                        'id' => $summary['id'] ?? null,
                        'status' => $summary['status'] ?? null,
                        'inboundBibrXrefCount' => $summary['inboundBibrXrefCount'] ?? 0,
                        ...$identifier,
                    ];
                    $contextIdentifiers[] = $contextIdentifier;
                    $referenceIdentifiers[] = $contextIdentifier;

                    $type = (string) ($identifier['type'] ?? '');
                    $normalizedValue = (string) ($identifier['normalizedValue'] ?? '');
                    if ($type !== '') {
                        $referenceIdentifierTypes[] = $type;
                    }
                    if ($type !== '' && $normalizedValue !== '') {
                        $bucketKey = $type . "\0" . $normalizedValue;
                        $referenceIdentifierBuckets[$bucketKey][] = $contextIdentifier;
                    }

                    $sourceKey = implode("\0", [
                        (string) ($identifier['sourceElement'] ?? ''),
                        (string) ($identifier['sourceAttribute'] ?? ''),
                        (string) ($identifier['sourceType'] ?? ''),
                        $type,
                    ]);
                    $referenceIdentifierSourceCounts[$sourceKey] = ($referenceIdentifierSourceCounts[$sourceKey] ?? 0) + 1;
                }

                $referenceId = $summary['id'] ?? null;
                if (is_string($referenceId) && $referenceId !== '') {
                    $referenceIdentifierLookup[$referenceId] = $contextIdentifiers;
                }
            } elseif (($summary['citationElementNames'] ?? []) !== []) {
                $referencesMissingIdentifiers[] = [
                    'id' => $summary['id'] ?? null,
                    'status' => $summary['status'] ?? null,
                    'inboundBibrXrefCount' => $summary['inboundBibrXrefCount'] ?? 0,
                    'citationElementNames' => $summary['citationElementNames'] ?? [],
                ];
            }
            $blockedCitationTextPayloadCount += (int) ($summary['blockedCitationTextPayloadCount'] ?? 0);
            foreach (($summary['citationElementNames'] ?? []) as $elementName) {
                if (is_string($elementName) && $elementName !== '') {
                    $blockedCitationTextPayloadElementNames[] = $elementName;
                }
            }
            $references[] = $summary;
        }

        $resolvedBibrIdentifierTargets = [];
        foreach ($bibliographyXrefs as $index => $xref) {
            $targetId = (string) ($xref['targetId'] ?? '');
            $targetIdentifiers = (bool) ($xref['resolved'] ?? false) && $targetId !== ''
                ? ($referenceIdentifierLookup[$targetId] ?? [])
                : [];
            $targetIdentifierTypes = self::jatsUniqueNonEmptyStrings(array_filter(
                array_map(static fn (array $identifier): ?string => $identifier['type'] ?? null, $targetIdentifiers),
                static fn (?string $type): bool => $type !== null && $type !== ''
            ));

            $bibliographyXrefs[$index]['targetIdentifiers'] = $targetIdentifiers;
            $bibliographyXrefs[$index]['targetIdentifierCount'] = count($targetIdentifiers);
            $bibliographyXrefs[$index]['targetIdentifierTypes'] = $targetIdentifierTypes;

            if ($targetIdentifiers !== []) {
                $resolvedBibrIdentifierTargets[] = [
                    'targetId' => $targetId,
                    'targetIdentifierCount' => count($targetIdentifiers),
                    'targetIdentifierTypes' => $targetIdentifierTypes,
                    'targetIdentifiers' => $targetIdentifiers,
                ];
            }
        }

        $duplicateReferenceIdentifiers = self::jatsDuplicateReferenceIdentifiers($referenceIdentifierBuckets);
        $referenceIdentifierSourceSummaries = self::jatsReferenceIdentifierSourceSummaries($referenceIdentifierSourceCounts);
        $duplicateReferenceTitles = self::jatsDuplicateReferenceTextFields($referenceTitleBuckets);
        $duplicateReferenceSources = self::jatsDuplicateReferenceTextFields($referenceSourceBuckets);
        $referenceSourceTypeSummaries = self::jatsReferenceSourceTypeSummaries($referenceSourceTypeCounts);
        $citationTargetLinkage = [
            'resolvedReferenceIds' => $resolvedReferenceIds,
            'resolvedBibrXrefCount' => count(array_filter(
                $bibliographyXrefs,
                static fn (array $xref): bool => (bool) $xref['resolved']
            )),
            'unresolvedReferenceIds' => $unresolvedReferenceIds,
            'unresolvedBibrXrefCount' => count($bibliographyXrefs) - count(array_filter(
                $bibliographyXrefs,
                static fn (array $xref): bool => (bool) $xref['resolved']
            )),
            'unreferencedReferenceIds' => $unreferencedReferenceIds,
            'unreferencedReferenceCount' => count($unreferencedReferenceIds),
        ];
        $referenceTitleSourceDiagnostics = self::jatsReferenceTitleSourceDiagnostics(
            count($referenceElements),
            array_sum(array_map(
                static fn (array $summary): int => count($summary['titleFields'] ?? []),
                $safeReferenceTitles
            )),
            array_sum(array_map(
                static fn (array $summary): int => count($summary['sourceFields'] ?? []),
                $safeReferenceSources
            )),
            count($referenceSourceTypeSummaries),
            count($duplicateReferenceTitles),
            count($duplicateReferenceSources),
            count($referencesMissingTitles),
            count($referencesMissingSources),
            $citationTargetLinkage['resolvedBibrXrefCount'],
            $citationTargetLinkage['unresolvedBibrXrefCount'],
            $citationTargetLinkage['unreferencedReferenceCount'],
            $blockedCitationTextPayloadCount
        );

        return [
            'refLists' => $refLists,
            'refListCount' => count($refLists),
            'references' => $references,
            'referenceIds' => $referenceIds,
            'referenceCount' => count($referenceElements),
            'safeReferenceLabels' => $safeReferenceLabels,
            'safeReferenceLabelCount' => count($safeReferenceLabels),
            'safeReferenceAuthors' => $safeReferenceAuthors,
            'safeReferenceAuthorCount' => array_sum(array_map(
                static fn (array $summary): int => count($summary['authorNames'] ?? []),
                $safeReferenceAuthors
            )),
            'safeReferenceDates' => $safeReferenceDates,
            'safeReferenceDateCount' => array_sum(array_map(
                static fn (array $summary): int => count($summary['dates'] ?? []),
                $safeReferenceDates
            )),
            'safeReferenceYears' => $safeReferenceYears,
            'safeReferenceYearCount' => array_sum(array_map(
                static fn (array $summary): int => count($summary['years'] ?? []),
                $safeReferenceYears
            )),
            'safeReferenceTitles' => $safeReferenceTitles,
            'safeReferenceTitleFieldCount' => array_sum(array_map(
                static fn (array $summary): int => count($summary['titleFields'] ?? []),
                $safeReferenceTitles
            )),
            'safeReferenceSources' => $safeReferenceSources,
            'safeReferenceSourceCount' => array_sum(array_map(
                static fn (array $summary): int => count($summary['sourceFields'] ?? []),
                $safeReferenceSources
            )),
            'referenceSourceTypes' => self::jatsUniqueNonEmptyStrings($referenceSourceTypes),
            'referenceSourceTypeSummaries' => $referenceSourceTypeSummaries,
            'referenceSourceTypeSummaryCount' => count($referenceSourceTypeSummaries),
            'duplicateReferenceTitles' => $duplicateReferenceTitles,
            'duplicateReferenceTitleCount' => count($duplicateReferenceTitles),
            'duplicateReferenceSources' => $duplicateReferenceSources,
            'duplicateReferenceSourceCount' => count($duplicateReferenceSources),
            'referencesMissingTitles' => $referencesMissingTitles,
            'referencesMissingTitleCount' => count($referencesMissingTitles),
            'referencesMissingSources' => $referencesMissingSources,
            'referencesMissingSourceCount' => count($referencesMissingSources),
            'referenceTitleSourceDiagnostics' => $referenceTitleSourceDiagnostics,
            'referenceTitleSourceDiagnosticCodes' => array_map(
                static fn (array $diagnostic): string => (string) $diagnostic['code'],
                $referenceTitleSourceDiagnostics
            ),
            'referenceTitleSourceDiagnosticCount' => count($referenceTitleSourceDiagnostics),
            'referenceIdentifiers' => $referenceIdentifiers,
            'referenceIdentifierCount' => count($referenceIdentifiers),
            'referenceIdentifierTypes' => self::jatsUniqueNonEmptyStrings($referenceIdentifierTypes),
            'referenceIdentifierSourceSummaries' => $referenceIdentifierSourceSummaries,
            'referenceIdentifierSourceSummaryCount' => count($referenceIdentifierSourceSummaries),
            'resolvedBibrIdentifierTargets' => $resolvedBibrIdentifierTargets,
            'resolvedBibrIdentifierTargetCount' => count($resolvedBibrIdentifierTargets),
            'duplicateReferenceIdentifiers' => $duplicateReferenceIdentifiers,
            'duplicateReferenceIdentifierCount' => count($duplicateReferenceIdentifiers),
            'referencesMissingIdentifiers' => $referencesMissingIdentifiers,
            'referencesMissingIdentifierCount' => count($referencesMissingIdentifiers),
            'blockedCitationTextPayloadCount' => $blockedCitationTextPayloadCount,
            'blockedCitationTextPayloadElementNames' => array_values(array_unique($blockedCitationTextPayloadElementNames)),
            'bibliographyXrefs' => $bibliographyXrefs,
            'bibliographyXrefCount' => count($bibliographyXrefs),
            'citationTargetLinkage' => $citationTargetLinkage,
            'resolvedReferenceIds' => $resolvedReferenceIds,
            'resolvedBibrXrefCount' => $citationTargetLinkage['resolvedBibrXrefCount'],
            'unresolvedReferenceIds' => $unresolvedReferenceIds,
            'unresolvedBibrXrefCount' => $citationTargetLinkage['unresolvedBibrXrefCount'],
            'unreferencedReferenceIds' => $unreferencedReferenceIds,
            'unreferencedReferenceCount' => $citationTargetLinkage['unreferencedReferenceCount'],
            'missingIdReferenceCount' => $missingIdReferenceCount,
            'referenceMetadataSummaryCount' => count($references),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function jatsBibliographyReferenceSummary(
        \DOMElement $reference,
        int $inboundBibrXrefCount,
        int $allXrefCount
    ): array {
        $id = self::jatsTrimmedAttribute($reference, 'id');
        $citationElementNames = [];
        $publicationTypes = [];
        $blockedCitationTextPayloadCount = 0;
        foreach (self::descendantElements($reference) as $element) {
            if (!in_array($element->localName, ['element-citation', 'mixed-citation', 'nlm-citation'], true)) {
                continue;
            }

            $citationElementNames[] = $element->localName;
            if (self::normalizedText($element) !== '') {
                ++$blockedCitationTextPayloadCount;
            }
            $publicationType = self::jatsTrimmedAttribute($element, 'publication-type');
            if ($publicationType !== null) {
                $publicationTypes[] = $publicationType;
            }
        }

        $personGroupTypes = [];
        foreach (self::descendantElements($reference, 'person-group') as $personGroup) {
            $type = self::jatsTrimmedAttribute($personGroup, 'person-group-type');
            if ($type !== null) {
                $personGroupTypes[] = $type;
            }
        }

        $authors = self::jatsReferenceAuthorSummaries($reference);
        $dates = self::jatsReferenceDateSummaries($reference);
        $years = self::jatsReferenceYears($reference);
        $titleFields = self::jatsReferenceTitleFieldSummaries($reference);
        $sourceFields = self::jatsReferenceSourceFieldSummaries($reference);
        $identifiers = self::jatsReferenceIdentifierSummaries($reference);
        $text = self::normalizedText($reference);

        return [
            'id' => $id,
            'label' => self::jatsFirstText($reference, ['label']),
            'status' => $id === null
                ? 'missing-id'
                : ($inboundBibrXrefCount > 0 ? 'resolved-by-bibr-xref' : 'unreferenced'),
            'referenceCount' => $allXrefCount,
            'inboundBibrXrefCount' => $inboundBibrXrefCount,
            'metadataOnly' => true,
            'citationElementNames' => self::jatsUniqueNonEmptyStrings($citationElementNames),
            'blockedCitationTextPayloadCount' => $blockedCitationTextPayloadCount,
            'publicationTypes' => self::jatsUniqueNonEmptyStrings($publicationTypes),
            'publicationIds' => self::jatsTypedTextRecords($reference, ['pub-id'], ['pub-id-type']),
            'articleTitle' => self::jatsFirstText($reference, ['article-title']),
            'articleTitles' => self::jatsReferenceFieldValues($titleFields, 'article-title'),
            'chapterTitle' => self::jatsFirstText($reference, ['chapter-title']),
            'chapterTitles' => self::jatsReferenceFieldValues($titleFields, 'chapter-title'),
            'sourceTitle' => self::jatsFirstText($reference, ['source', 'journal-title', 'book-title']),
            'sourceTitles' => self::jatsReferenceFieldValues($sourceFields, 'source'),
            'titleFields' => $titleFields,
            'titleFieldCount' => count($titleFields),
            'sourceFields' => $sourceFields,
            'sourceFieldCount' => count($sourceFields),
            'referenceSourceType' => self::jatsReferenceSourceType($publicationTypes, $titleFields, $sourceFields),
            'year' => self::jatsFirstText($reference, ['year']),
            'years' => $years,
            'yearCount' => count($years),
            'dates' => $dates,
            'dateCount' => count($dates),
            'authors' => $authors,
            'authorNames' => array_values(array_map(
                static fn (array $author): string => (string) $author['name'],
                $authors
            )),
            'authorCount' => count($authors),
            'identifiers' => $identifiers,
            'identifierCount' => count($identifiers),
            'identifierTypes' => self::jatsUniqueNonEmptyStrings(array_map(
                static fn (array $identifier): string => (string) $identifier['type'],
                $identifiers
            )),
            'personGroupTypes' => self::jatsUniqueNonEmptyStrings($personGroupTypes),
            'nameCount' => count(self::descendantElements($reference, 'name')),
            'collabCount' => count(self::descendantElements($reference, 'collab')),
            'etalCount' => count(self::descendantElements($reference, 'etal')),
            'uriCount' => count(self::descendantElements($reference, 'uri')),
            'extLinkCount' => count(self::descendantElements($reference, 'ext-link')),
            'textLength' => strlen($text),
            'textSha256' => hash('sha256', $text),
        ];
    }

    /**
     * @return list<array{element:string, value:string, sourceType:?string, sourceCitationElement:?string}>
     */
    private static function jatsReferenceTitleFieldSummaries(\DOMElement $reference): array
    {
        $fields = [];
        foreach (self::descendantElements($reference) as $element) {
            if (!in_array($element->localName, ['article-title', 'chapter-title'], true)) {
                continue;
            }

            $value = self::normalizedText($element);
            if ($value === '') {
                continue;
            }

            $fields[] = [
                'element' => $element->localName,
                'value' => $value,
                'sourceType' => self::jatsReferenceFieldSourceType($element),
                'sourceCitationElement' => self::jatsNearestAncestorElementName($element, [
                    'element-citation',
                    'mixed-citation',
                    'nlm-citation',
                ]),
            ];
        }

        return $fields;
    }

    /**
     * @return list<array{element:string, value:string, sourceType:?string, sourceCitationElement:?string}>
     */
    private static function jatsReferenceSourceFieldSummaries(\DOMElement $reference): array
    {
        $fields = [];
        foreach (self::descendantElements($reference, 'source') as $element) {
            $value = self::normalizedText($element);
            if ($value === '') {
                continue;
            }

            $fields[] = [
                'element' => $element->localName,
                'value' => $value,
                'sourceType' => self::jatsReferenceFieldSourceType($element),
                'sourceCitationElement' => self::jatsNearestAncestorElementName($element, [
                    'element-citation',
                    'mixed-citation',
                    'nlm-citation',
                ]),
            ];
        }

        return $fields;
    }

    private static function jatsReferenceFieldSourceType(\DOMElement $field): ?string
    {
        foreach (['source-type', 'publication-type', 'content-type', 'specific-use'] as $attribute) {
            $value = self::jatsTrimmedAttribute($field, $attribute);
            if ($value !== null) {
                return self::jatsReferenceNormalizedType($value);
            }
        }

        $parent = $field->parentNode;
        while ($parent instanceof \DOMElement) {
            if (in_array($parent->localName, ['element-citation', 'mixed-citation', 'nlm-citation'], true)) {
                $publicationType = self::jatsTrimmedAttribute($parent, 'publication-type');

                return $publicationType === null ? null : self::jatsReferenceNormalizedType($publicationType);
            }
            $parent = $parent->parentNode;
        }

        return null;
    }

    private static function jatsReferenceNormalizedType(string $type): string
    {
        $normalized = strtolower(trim(preg_replace('/[ \t\r\n\f_]+/u', '-', $type) ?? $type));
        $normalized = trim((string) preg_replace('/-+/', '-', $normalized), '-');

        return $normalized === '' ? 'unspecified' : $normalized;
    }

    /**
     * @param list<string> $publicationTypes
     * @param list<array{element:string, value:string, sourceType:?string, sourceCitationElement:?string}> $titleFields
     * @param list<array{element:string, value:string, sourceType:?string, sourceCitationElement:?string}> $sourceFields
     */
    private static function jatsReferenceSourceType(array $publicationTypes, array $titleFields, array $sourceFields): ?string
    {
        foreach ([...$sourceFields, ...$titleFields] as $field) {
            $sourceType = $field['sourceType'] ?? null;
            if (is_string($sourceType) && $sourceType !== '') {
                return $sourceType;
            }
        }

        foreach ($publicationTypes as $publicationType) {
            if ($publicationType !== '') {
                return self::jatsReferenceNormalizedType($publicationType);
            }
        }

        if ($titleFields !== [] && $sourceFields !== []) {
            $hasChapterTitle = count(self::jatsReferenceFieldValues($titleFields, 'chapter-title')) > 0;

            return $hasChapterTitle ? 'book-chapter' : 'article-container';
        }
        if ($sourceFields !== []) {
            return 'source-only';
        }
        if ($titleFields !== []) {
            return 'title-only';
        }

        return null;
    }

    /**
     * @param list<array{element:string, value:string, sourceType:?string, sourceCitationElement:?string}> $fields
     * @return list<string>
     */
    private static function jatsReferenceFieldValues(array $fields, string $element): array
    {
        $values = [];
        foreach ($fields as $field) {
            if ($field['element'] === $element) {
                $values[] = $field['value'];
            }
        }

        return array_values(array_unique($values));
    }

    /**
     * @param array<string, list<array<string, mixed>>> $buckets
     * @param array<string, mixed> $summary
     * @param array<string, mixed> $field
     */
    private static function appendJatsReferenceTextBucket(array &$buckets, array $summary, array $field, string $value): void
    {
        $key = self::jatsReferenceTextKey($value);
        if ($key === '') {
            return;
        }

        $buckets[$key][] = [
            'id' => $summary['id'] ?? null,
            'status' => $summary['status'] ?? null,
            'inboundBibrXrefCount' => $summary['inboundBibrXrefCount'] ?? 0,
            'element' => $field['element'] ?? null,
            'value' => $value,
            'sourceType' => $field['sourceType'] ?? null,
            'sourceCitationElement' => $field['sourceCitationElement'] ?? null,
        ];
    }

    private static function jatsReferenceTextKey(string $value): string
    {
        $normalized = trim(preg_replace('/[ \t\r\n\f]+/u', ' ', $value) ?? $value);
        if ($normalized === '') {
            return '';
        }

        return function_exists('mb_strtolower')
            ? mb_strtolower($normalized, 'UTF-8')
            : strtolower($normalized);
    }

    /**
     * @param array<string, list<array<string, mixed>>> $buckets
     * @return list<array{value:string, normalizedValueSha256:string, referenceIds:list<string>, referenceCount:int, sourceCount:int, elements:list<string>, sourceTypes:list<string>}>
     */
    private static function jatsDuplicateReferenceTextFields(array $buckets): array
    {
        $duplicates = [];
        ksort($buckets);
        foreach ($buckets as $key => $fields) {
            if (count($fields) < 2) {
                continue;
            }

            $referenceIds = [];
            $elements = [];
            $sourceTypes = [];
            foreach ($fields as $field) {
                $id = $field['id'] ?? null;
                if (is_string($id) && $id !== '') {
                    $referenceIds[] = $id;
                }
                $element = $field['element'] ?? null;
                if (is_string($element) && $element !== '') {
                    $elements[] = $element;
                }
                $sourceType = $field['sourceType'] ?? null;
                if (is_string($sourceType) && $sourceType !== '') {
                    $sourceTypes[] = $sourceType;
                }
            }

            $duplicates[] = [
                'value' => (string) ($fields[0]['value'] ?? ''),
                'normalizedValueSha256' => hash('sha256', $key),
                'referenceIds' => array_values(array_unique($referenceIds)),
                'referenceCount' => count(array_unique($referenceIds)),
                'sourceCount' => count($fields),
                'elements' => array_values(array_unique($elements)),
                'sourceTypes' => array_values(array_unique($sourceTypes)),
            ];
        }

        return $duplicates;
    }

    /**
     * @param array<string, int> $sourceTypeCounts
     * @return list<array{sourceType:string, referenceCount:int}>
     */
    private static function jatsReferenceSourceTypeSummaries(array $sourceTypeCounts): array
    {
        $summaries = [];
        ksort($sourceTypeCounts);
        foreach ($sourceTypeCounts as $sourceType => $count) {
            $summaries[] = [
                'sourceType' => $sourceType,
                'referenceCount' => $count,
            ];
        }

        return $summaries;
    }

    /**
     * @return list<array{code:string, severity:string, message:string, directReaderParity:bool, coveredByPacket:bool, details:array<string, int|string|bool>}>
     */
    private static function jatsReferenceTitleSourceDiagnostics(
        int $referenceCount,
        int $safeReferenceTitleFieldCount,
        int $safeReferenceSourceCount,
        int $referenceSourceTypeSummaryCount,
        int $duplicateReferenceTitleCount,
        int $duplicateReferenceSourceCount,
        int $referencesMissingTitleCount,
        int $referencesMissingSourceCount,
        int $resolvedBibrXrefCount,
        int $unresolvedBibrXrefCount,
        int $unreferencedReferenceCount,
        int $blockedCitationTextPayloadCount
    ): array {
        if ($referenceCount === 0) {
            return [];
        }

        $diagnostics = [
            self::jatsDirectReaderDiagnostic(
                'reference-title-source-policy',
                'warning',
                'Reference article-title, chapter-title, and source fields are exposed as bounded summaries while citation text payloads stay blocked.',
                false,
                true,
                [
                    'referenceCount' => $referenceCount,
                    'safeReferenceTitleFieldCount' => $safeReferenceTitleFieldCount,
                    'safeReferenceSourceCount' => $safeReferenceSourceCount,
                    'referenceSourceTypeSummaryCount' => $referenceSourceTypeSummaryCount,
                    'blockedCitationTextPayloadCount' => $blockedCitationTextPayloadCount,
                ]
            ),
            self::jatsDirectReaderDiagnostic(
                'reference-citation-target-linkage',
                'warning',
                'Bibliography xref targets are linked to reference title/source summaries without exposing raw citation payload text.',
                false,
                true,
                [
                    'resolvedBibrXrefCount' => $resolvedBibrXrefCount,
                    'unresolvedBibrXrefCount' => $unresolvedBibrXrefCount,
                    'unreferencedReferenceCount' => $unreferencedReferenceCount,
                ]
            ),
        ];

        if ($duplicateReferenceTitleCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'reference-titles-duplicate',
                'warning',
                'Duplicate reference article-title or chapter-title values were found across back-matter references.',
                false,
                true,
                [
                    'duplicateReferenceTitleCount' => $duplicateReferenceTitleCount,
                    'safeReferenceTitleFieldCount' => $safeReferenceTitleFieldCount,
                ]
            );
        }

        if ($duplicateReferenceSourceCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'reference-sources-duplicate',
                'warning',
                'Duplicate reference source values were found across back-matter references.',
                false,
                true,
                [
                    'duplicateReferenceSourceCount' => $duplicateReferenceSourceCount,
                    'safeReferenceSourceCount' => $safeReferenceSourceCount,
                ]
            );
        }

        if ($referencesMissingTitleCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'reference-titles-missing',
                'warning',
                'Some citation-bearing references do not expose article-title or chapter-title metadata.',
                false,
                true,
                [
                    'referencesMissingTitleCount' => $referencesMissingTitleCount,
                    'referenceCount' => $referenceCount,
                ]
            );
        }

        if ($referencesMissingSourceCount > 0) {
            $diagnostics[] = self::jatsDirectReaderDiagnostic(
                'reference-sources-missing',
                'warning',
                'Some citation-bearing references do not expose source metadata.',
                false,
                true,
                [
                    'referencesMissingSourceCount' => $referencesMissingSourceCount,
                    'referenceCount' => $referenceCount,
                ]
            );
        }

        return $diagnostics;
    }

    /**
     * @return list<array{type:string, value:string, normalizedValue:string, sourceElement:string, sourceAttribute:?string, sourceType:?string, sourceCitationElement:?string}>
     */
    private static function jatsReferenceIdentifierSummaries(\DOMElement $reference): array
    {
        $identifiers = [];
        foreach (self::descendantElements($reference) as $element) {
            if (!in_array($element->localName, ['pub-id', 'isbn', 'uri', 'ext-link'], true)) {
                continue;
            }

            $sourceType = self::jatsReferenceIdentifierSourceType($element);
            $sourceAttribute = null;
            $value = self::normalizedText($element);
            if (in_array($element->localName, ['uri', 'ext-link'], true)) {
                $xlinkHref = self::attribute($element, 'href', 'http://www.w3.org/1999/xlink');
                $plainHref = self::jatsTrimmedAttribute($element, 'href');
                if ($xlinkHref !== null && trim($xlinkHref) !== '') {
                    $value = trim($xlinkHref);
                    $sourceAttribute = 'xlink:href';
                } elseif ($plainHref !== null) {
                    $value = $plainHref;
                    $sourceAttribute = 'href';
                }
            }

            $value = trim($value);
            if ($value === '') {
                continue;
            }

            $type = self::jatsReferenceIdentifierType($element->localName, $sourceType, $sourceAttribute);
            if ($type === null) {
                continue;
            }

            self::appendUniqueJatsReferenceIdentifier($identifiers, [
                'type' => $type,
                'value' => $value,
                'normalizedValue' => self::jatsReferenceIdentifierNormalizedValue($type, $value),
                'sourceElement' => $element->localName,
                'sourceAttribute' => $sourceAttribute,
                'sourceType' => $sourceType,
                'sourceCitationElement' => self::jatsNearestAncestorElementName($element, [
                    'element-citation',
                    'mixed-citation',
                    'nlm-citation',
                ]),
            ]);
        }

        return $identifiers;
    }

    private static function jatsReferenceIdentifierSourceType(\DOMElement $element): ?string
    {
        foreach (['pub-id-type', 'ext-link-type', 'content-type', 'specific-use'] as $attribute) {
            $value = self::jatsTrimmedAttribute($element, $attribute);
            if ($value !== null) {
                return $value;
            }
        }

        return null;
    }

    private static function jatsReferenceIdentifierType(string $sourceElement, ?string $sourceType, ?string $sourceAttribute): ?string
    {
        if ($sourceElement === 'isbn') {
            return 'isbn';
        }
        if ($sourceElement === 'uri') {
            return 'uri';
        }
        if ($sourceElement === 'ext-link' && $sourceAttribute !== null && $sourceType === null) {
            return 'uri';
        }

        $type = strtolower(trim((string) $sourceType));
        $type = str_replace(['_', ' '], '-', $type);

        return match ($type) {
            'doi' => 'doi',
            'pmid', 'pubmed', 'pubmed-id' => 'pmid',
            'pmcid', 'pmc', 'pmc-id' => 'pmcid',
            'isbn', 'isbn-10', 'isbn-13' => 'isbn',
            'uri', 'url', 'href', 'link', 'web', 'web-url' => 'uri',
            default => null,
        };
    }

    private static function jatsReferenceIdentifierNormalizedValue(string $type, string $value): string
    {
        $normalized = trim(preg_replace('/[ \t\r\n\f]+/u', ' ', $value) ?? $value);

        return match ($type) {
            'doi' => strtolower((string) preg_replace(
                '~\A(?:doi:\s*|https?://(?:dx\.)?doi\.org/)~i',
                '',
                $normalized
            )),
            'pmid' => preg_replace('/\D+/', '', $normalized) ?? $normalized,
            'pmcid' => strtoupper((string) preg_replace('/\s+/', '', $normalized)),
            'isbn' => strtoupper((string) preg_replace('/[\s-]+/', '', $normalized)),
            default => $normalized,
        };
    }

    /**
     * @param list<array{type:string, value:string, normalizedValue:string, sourceElement:string, sourceAttribute:?string, sourceType:?string, sourceCitationElement:?string}> $identifiers
     * @param array{type:string, value:string, normalizedValue:string, sourceElement:string, sourceAttribute:?string, sourceType:?string, sourceCitationElement:?string} $identifier
     */
    private static function appendUniqueJatsReferenceIdentifier(array &$identifiers, array $identifier): void
    {
        foreach ($identifiers as $existing) {
            if (
                $existing['type'] === $identifier['type']
                && $existing['normalizedValue'] === $identifier['normalizedValue']
                && $existing['sourceElement'] === $identifier['sourceElement']
                && $existing['sourceAttribute'] === $identifier['sourceAttribute']
                && $existing['sourceCitationElement'] === $identifier['sourceCitationElement']
            ) {
                return;
            }
        }

        $identifiers[] = $identifier;
    }

    /**
     * @param array<string, list<array<string, mixed>>> $buckets
     * @return list<array{type:string, value:string, normalizedValue:string, referenceIds:list<string>, referenceCount:int, sourceCount:int}>
     */
    private static function jatsDuplicateReferenceIdentifiers(array $buckets): array
    {
        $duplicates = [];
        ksort($buckets);
        foreach ($buckets as $identifiers) {
            if (count($identifiers) < 2) {
                continue;
            }

            $first = $identifiers[0];
            $referenceIds = [];
            foreach ($identifiers as $identifier) {
                $id = $identifier['id'] ?? null;
                if (is_string($id) && $id !== '') {
                    $referenceIds[] = $id;
                }
            }
            $referenceIds = self::jatsUniqueNonEmptyStrings($referenceIds);

            $duplicates[] = [
                'type' => (string) ($first['type'] ?? ''),
                'value' => (string) ($first['value'] ?? ''),
                'normalizedValue' => (string) ($first['normalizedValue'] ?? ''),
                'referenceIds' => $referenceIds,
                'referenceCount' => count($referenceIds),
                'sourceCount' => count($identifiers),
            ];
        }

        return $duplicates;
    }

    /**
     * @param array<string, int> $sourceCounts
     * @return list<array{sourceElement:string, sourceAttribute:?string, sourceType:?string, type:string, count:int}>
     */
    private static function jatsReferenceIdentifierSourceSummaries(array $sourceCounts): array
    {
        $summaries = [];
        ksort($sourceCounts);
        foreach ($sourceCounts as $key => $count) {
            [$sourceElement, $sourceAttribute, $sourceType, $type] = array_pad(explode("\0", $key), 4, '');
            $summaries[] = [
                'sourceElement' => $sourceElement,
                'sourceAttribute' => $sourceAttribute === '' ? null : $sourceAttribute,
                'sourceType' => $sourceType === '' ? null : $sourceType,
                'type' => $type,
                'count' => $count,
            ];
        }

        return $summaries;
    }

    /**
     * @param list<string> $localNames
     */
    private static function jatsNearestAncestorElementName(\DOMElement $element, array $localNames): ?string
    {
        $lookup = array_fill_keys($localNames, true);
        $current = $element->parentNode;
        while ($current instanceof \DOMElement) {
            if (isset($lookup[$current->localName])) {
                return $current->localName;
            }
            $current = $current->parentNode;
        }

        return null;
    }

    /**
     * @return list<array{role:?string, name:string, source:string}>
     */
    private static function jatsReferenceAuthorSummaries(\DOMElement $reference): array
    {
        $authors = [];
        foreach (self::descendantElements($reference, 'person-group') as $personGroup) {
            $role = self::jatsTrimmedAttribute($personGroup, 'person-group-type');
            foreach (self::jatsReferenceNameTexts($personGroup) as $name) {
                self::appendUniqueJatsReferenceAuthor($authors, [
                    'role' => $role,
                    'name' => $name,
                    'source' => 'person-group',
                ]);
            }
        }

        foreach (self::descendantElements($reference, 'collab') as $collab) {
            if (self::jatsAncestorElement($collab, 'person-group') instanceof \DOMElement) {
                continue;
            }

            $name = self::normalizedText($collab);
            if ($name === '') {
                continue;
            }

            self::appendUniqueJatsReferenceAuthor($authors, [
                'role' => 'collab',
                'name' => $name,
                'source' => 'collab',
            ]);
        }

        return $authors;
    }

    /**
     * @param list<array{role:?string, name:string, source:string}> $authors
     * @param array{role:?string, name:string, source:string} $author
     */
    private static function appendUniqueJatsReferenceAuthor(array &$authors, array $author): void
    {
        foreach ($authors as $existing) {
            if (
                $existing['name'] === $author['name']
                && $existing['role'] === $author['role']
                && $existing['source'] === $author['source']
            ) {
                return;
            }
        }

        $authors[] = $author;
    }

    /**
     * @return list<string>
     */
    private static function jatsReferenceNameTexts(\DOMElement $root): array
    {
        $names = [];
        foreach (self::descendantElements($root) as $element) {
            if (!in_array($element->localName, ['name', 'string-name', 'collab'], true)) {
                continue;
            }
            if (
                $element->localName === 'collab'
                && self::jatsAncestorElement($element, 'person-group') !== $root
            ) {
                continue;
            }

            $text = $element->localName === 'name'
                ? self::jatsPersonNameText($element)
                : self::normalizedText($element);
            if ($text !== '') {
                $names[] = $text;
            }
        }

        return array_values(array_unique($names));
    }

    private static function jatsPersonNameText(\DOMElement $name): string
    {
        $surname = self::jatsFirstText($name, ['surname']);
        $given = self::jatsFirstText($name, ['given-names']);
        $suffix = self::jatsFirstText($name, ['suffix']);
        $combined = trim(($given ?? '') . ' ' . ($surname ?? ''));
        if ($suffix !== null && $suffix !== '') {
            $combined = trim($combined . ' ' . $suffix);
        }

        return $combined !== '' ? $combined : self::normalizedText($name);
    }

    /**
     * @return list<array{element:string, type:?string, year:?string, month:?string, day:?string, iso:?string}>
     */
    private static function jatsReferenceDateSummaries(\DOMElement $reference): array
    {
        $dates = [];
        foreach (self::descendantElements($reference) as $element) {
            if (!in_array($element->localName, ['date', 'pub-date', 'date-in-citation'], true)) {
                continue;
            }

            $year = self::jatsFirstText($element, ['year']);
            $month = self::jatsFirstText($element, ['month']);
            $day = self::jatsFirstText($element, ['day']);
            $iso = self::jatsTrimmedAttribute($element, 'iso-8601-date') ?? self::jatsIsoDate($year, $month, $day);
            $dates[] = [
                'element' => $element->localName,
                'type' => self::jatsTrimmedAttribute($element, 'date-type')
                    ?? self::jatsTrimmedAttribute($element, 'pub-type')
                    ?? self::jatsTrimmedAttribute($element, 'content-type'),
                'year' => $year,
                'month' => $month,
                'day' => $day,
                'iso' => $iso,
            ];
        }

        return $dates;
    }

    /**
     * @return list<string>
     */
    private static function jatsReferenceYears(\DOMElement $reference): array
    {
        $years = [];
        foreach (self::descendantElements($reference, 'year') as $year) {
            $text = self::normalizedText($year);
            if ($text !== '') {
                $years[] = $text;
            }
        }

        return array_values(array_unique($years));
    }

    private static function jatsAncestorElement(\DOMElement $element, string $localName): ?\DOMElement
    {
        $parent = $element->parentNode;
        while ($parent instanceof \DOMElement) {
            if ($parent->localName === $localName) {
                return $parent;
            }

            $parent = $parent->parentNode;
        }

        return null;
    }

    /**
     * @param list<string> $parentTitlePath
     * @param list<array<string, mixed>> $sections
     */
    private static function collectJatsSectionSummaries(
        \DOMElement $container,
        int $depth,
        ?string $parentId,
        array $parentTitlePath,
        int &$ordinal,
        array &$sections
    ): void {
        foreach (self::childElements($container) as $child) {
            if ($child->localName !== 'sec') {
                self::collectJatsSectionSummaries($child, $depth, $parentId, $parentTitlePath, $ordinal, $sections);
                continue;
            }

            $titleTexts = [];
            foreach (self::childElements($child, 'title') as $title) {
                $text = self::normalizedText($title);
                if ($text !== '') {
                    $titleTexts[] = $text;
                }
            }
            $titleText = $titleTexts[0] ?? null;
            $titlePath = $parentTitlePath;
            if ($titleText !== null) {
                $titlePath[] = $titleText;
            }

            $labels = [];
            foreach (self::childElements($child, 'label') as $label) {
                $text = self::normalizedText($label);
                if ($text !== '') {
                    $labels[] = $text;
                }
            }

            $id = self::normalizedAttribute($child, 'id');
            $sections[] = [
                'ordinal' => $ordinal++,
                'id' => $id,
                'parentId' => $parentId,
                'depth' => $depth,
                'type' => self::attribute($child, 'sec-type'),
                'title' => $titleText,
                'titleCount' => count($titleTexts),
                'titleTexts' => $titleTexts,
                'titlePath' => $titlePath,
                'titlePathText' => $titlePath === [] ? null : implode(' > ', $titlePath),
                'label' => $labels[0] ?? null,
                'labelCount' => count($labels),
                'labels' => $labels,
                'language' => self::normalizedAttribute($child, 'lang', self::XML_NAMESPACE)
                    ?? self::normalizedAttribute($child, 'lang'),
                'directParagraphCount' => count(self::childElements($child, 'p')),
                'paragraphCount' => count(self::descendantElements($child, 'p')),
                'childSectionCount' => count(self::childElements($child, 'sec')),
            ];
            self::collectJatsSectionSummaries($child, $depth + 1, $id, $titlePath, $ordinal, $sections);
        }
    }

    /**
     * @return list<string>
     */
    private static function jatsElementIds(\DOMElement $root, string $localName): array
    {
        $ids = [];
        foreach (self::descendantElements($root, $localName) as $element) {
            $id = self::attribute($element, 'id');
            if ($id !== null && trim($id) !== '') {
                $ids[] = trim($id);
            }
        }

        return array_values(array_unique($ids));
    }

    /**
     * @param list<string> $backReferenceIds
     * @param array<string, string> $elementIdMap
     * @return list<array<string, mixed>>
     */
    private static function jatsInlineXrefDiagnostics(\DOMElement $root, array $backReferenceIds, array $elementIdMap): array
    {
        $backReferenceSet = array_fill_keys($backReferenceIds, true);
        $diagnostics = [];

        foreach (self::descendantElements($root, 'xref') as $xref) {
            if (!self::jatsIsBodyInlineMarker($xref)) {
                continue;
            }

            $ridRaw = self::attribute($xref, 'rid');
            if ($ridRaw === null || trim($ridRaw) === '') {
                continue;
            }

            $targets = self::spaceSeparatedTokens($ridRaw);
            if ($targets === []) {
                continue;
            }

            $localReferenceIds = [];
            $unsupportedTargets = [];
            foreach ($targets as $target) {
                if (isset($backReferenceSet[$target])) {
                    $localReferenceIds[] = $target;
                    continue;
                }

                $targetElement = $elementIdMap[$target] ?? null;
                $unsupportedTargets[] = [
                    'id' => $target,
                    'targetElement' => $targetElement,
                    'reason' => $targetElement === null ? 'missing-local-target' : 'target-is-not-back-reference',
                ];
            }

            $markerDiagnostics = [];
            if ($localReferenceIds !== []) {
                $markerDiagnostics[] = 'jats-inline-xref-local-back-reference';
            }
            if ($unsupportedTargets !== []) {
                $markerDiagnostics[] = 'jats-inline-xref-unsupported-citation-target';
            }

            $diagnostics[] = [
                'element' => $xref->localName,
                'refType' => self::jatsNormalizedAttribute($xref, 'ref-type'),
                'ridRaw' => trim($ridRaw),
                'targets' => $targets,
                'text' => self::normalizedText($xref),
                'localBackReferenceIds' => self::jatsUniqueNonEmptyStrings($localReferenceIds),
                'unsupportedTargets' => $unsupportedTargets,
                'unsupportedTargetCount' => count($unsupportedTargets),
                'diagnostics' => $markerDiagnostics,
            ];
        }

        return $diagnostics;
    }

    private static function jatsIsBodyInlineMarker(\DOMElement $element): bool
    {
        $node = $element->parentNode;
        $inBody = false;
        while ($node instanceof \DOMElement) {
            $name = $node->localName;
            if (in_array($name, ['front', 'article-meta', 'book-meta', 'journal-meta', 'back', 'book-back', 'book-part-back', 'ref-list'], true)) {
                return false;
            }
            if (in_array($name, ['body', 'book-body'], true)) {
                $inBody = true;
            }

            $node = $node->parentNode;
        }

        return $inBody;
    }

    /**
     * @return array<string, mixed>
     */
    private static function jatsRelationshipDiagnostics(\DOMElement $root): array
    {
        $targetIndex = self::jatsElementIndexById($root);
        $targetReferenceCounts = [];
        $targetTypeCounts = [];
        $xrefRecords = [];
        $diagnostics = [];
        $resolvedXrefCount = 0;
        $unresolvedXrefCount = 0;
        $unresolvedXrefTargetCount = 0;
        $missingRidXrefCount = 0;
        $multiTargetXrefCount = 0;
        $typeMismatchCount = 0;

        foreach (self::descendantElements($root, 'xref') as $xrefIndex => $xref) {
            $ridRaw = self::attribute($xref, 'rid');
            $refType = self::jatsNormalizedAttribute($xref, 'ref-type');
            $targetIds = $ridRaw === null ? [] : self::spaceSeparatedTokens($ridRaw);
            $resolvedTargetIds = [];
            $unresolvedTargetIds = [];
            $targetElementNames = [];
            $issues = [];

            if ($targetIds === []) {
                $issues[] = 'missing-xref-rid';
                ++$missingRidXrefCount;
                $diagnostics[] = [
                    'type' => 'missing-jats-xref-rid',
                    'xrefIndex' => $xrefIndex,
                    'refType' => $refType,
                    'text' => self::normalizedText($xref),
                ];
            }

            if (count($targetIds) > 1) {
                ++$multiTargetXrefCount;
            }

            foreach ($targetIds as $targetId) {
                if (!isset($targetIndex[$targetId])) {
                    $issues[] = 'unresolved-xref-target';
                    $unresolvedTargetIds[] = $targetId;
                    ++$unresolvedXrefTargetCount;
                    $diagnostics[] = [
                        'type' => 'unresolved-jats-xref-target',
                        'xrefIndex' => $xrefIndex,
                        'refType' => $refType,
                        'targetId' => $targetId,
                        'text' => self::normalizedText($xref),
                    ];
                    continue;
                }

                $resolvedTargetIds[] = $targetId;
                $targetReferenceCounts[$targetId] = ($targetReferenceCounts[$targetId] ?? 0) + 1;
                foreach ($targetIndex[$targetId] as $target) {
                    $targetElementNames[] = $target->localName;
                    $targetTypeCounts[$target->localName] = ($targetTypeCounts[$target->localName] ?? 0) + 1;
                }
            }

            $expectedTargetNames = self::jatsExpectedXrefTargetNames($refType);
            foreach (array_values(array_unique($targetElementNames)) as $targetElementName) {
                if ($expectedTargetNames === [] || in_array($targetElementName, $expectedTargetNames, true)) {
                    continue;
                }

                $issues[] = 'xref-ref-type-target-mismatch';
                ++$typeMismatchCount;
                $diagnostics[] = [
                    'type' => 'jats-xref-ref-type-target-mismatch',
                    'xrefIndex' => $xrefIndex,
                    'refType' => $refType,
                    'expectedTargetNames' => $expectedTargetNames,
                    'actualTargetName' => $targetElementName,
                    'targetIds' => $targetIds,
                ];
            }

            if ($resolvedTargetIds !== []) {
                ++$resolvedXrefCount;
            }
            if ($unresolvedTargetIds !== []) {
                ++$unresolvedXrefCount;
            }

            $xrefRecords[] = [
                'xrefIndex' => $xrefIndex,
                'refType' => $refType,
                'ridRaw' => $ridRaw,
                'targetIds' => $targetIds,
                'resolvedTargetIds' => array_values(array_unique($resolvedTargetIds)),
                'unresolvedTargetIds' => array_values(array_unique($unresolvedTargetIds)),
                'targetElementNames' => array_values(array_unique($targetElementNames)),
                'resolved' => $targetIds !== [] && $unresolvedTargetIds === [],
                'text' => self::normalizedText($xref),
                'issues' => array_values(array_unique($issues)),
            ];
        }

        ksort($targetTypeCounts, SORT_STRING);

        return [
            'reviewPolicy' => 'jats-bits-relationship-diagnostics-review-only',
            'directReaderParity' => false,
            'xrefCount' => count($xrefRecords),
            'resolvedXrefCount' => $resolvedXrefCount,
            'unresolvedXrefCount' => $unresolvedXrefCount,
            'unresolvedXrefTargetCount' => $unresolvedXrefTargetCount,
            'missingRidXrefCount' => $missingRidXrefCount,
            'multiTargetXrefCount' => $multiTargetXrefCount,
            'typeMismatchCount' => $typeMismatchCount,
            'targetTypeCounts' => $targetTypeCounts,
            'figureTargets' => self::jatsRelationshipTargetSummaries($root, 'fig', $targetReferenceCounts),
            'tableWrapTargets' => self::jatsRelationshipTargetSummaries($root, 'table-wrap', $targetReferenceCounts),
            'referenceTargets' => self::jatsRelationshipTargetSummaries($root, 'ref', $targetReferenceCounts),
            'xrefRecords' => $xrefRecords,
            'diagnostics' => $diagnostics,
            'diagnosticCount' => count($diagnostics),
        ];
    }

    /**
     * @return array<string, list<\DOMElement>>
     */
    private static function jatsElementIndexById(\DOMElement $root): array
    {
        $index = [];
        foreach (array_merge([$root], self::descendantElements($root)) as $element) {
            $id = self::jatsNormalizedAttribute($element, 'id');
            if ($id === null) {
                continue;
            }

            $index[$id] ??= [];
            $index[$id][] = $element;
        }

        return $index;
    }

    private static function jatsNormalizedAttribute(\DOMElement $element, string $name): ?string
    {
        $value = self::attribute($element, $name);
        if ($value === null || trim($value) === '') {
            return null;
        }

        return trim($value);
    }

    /**
     * @return list<string>
     */
    private static function jatsExpectedXrefTargetNames(?string $refType): array
    {
        return match ($refType) {
            'aff' => ['aff'],
            'app' => ['app'],
            'bibr', 'ref' => ['ref'],
            'boxed-text' => ['boxed-text'],
            'fig' => ['fig'],
            'fn' => ['fn'],
            'sec' => ['sec'],
            'supplementary-material' => ['supplementary-material'],
            'table', 'table-wrap' => ['table-wrap'],
            default => [],
        };
    }

    /**
     * @param array<string, int> $targetReferenceCounts
     * @return list<array<string, mixed>>
     */
    private static function jatsRelationshipTargetSummaries(\DOMElement $root, string $localName, array $targetReferenceCounts): array
    {
        $summaries = [];
        foreach (self::descendantElements($root, $localName) as $element) {
            $id = self::jatsNormalizedAttribute($element, 'id');
            if ($id === null) {
                continue;
            }

            $summary = [
                'id' => $id,
                'label' => self::jatsFirstChildText($element, 'label'),
                'xrefCount' => $targetReferenceCounts[$id] ?? 0,
            ];

            if ($localName === 'fig' || $localName === 'table-wrap') {
                $summary['captionText'] = self::jatsCaptionText($element);
            } elseif ($localName === 'ref') {
                $referenceText = self::normalizedText($element);
                $summary['referenceTextLength'] = strlen($referenceText);
                $summary['referenceTextSha256'] = hash('sha256', $referenceText);
            }

            $summaries[] = $summary;
        }

        return $summaries;
    }

    /**
     * @return list<array{id:?string, title:?string, referenceIds:list<string>, referenceCount:int}>
     */
    private static function jatsReferenceListSummaries(\DOMElement $backMatter): array
    {
        $lists = [];
        foreach (self::descendantElements($backMatter, 'ref-list') as $refList) {
            $referenceIds = [];
            foreach (self::descendantElements($refList, 'ref') as $reference) {
                $id = self::attribute($reference, 'id');
                if ($id !== null && trim($id) !== '') {
                    $referenceIds[] = trim($id);
                }
            }

            $lists[] = [
                'id' => self::attribute($refList, 'id'),
                'title' => self::jatsFirstChildText($refList, 'title'),
                'referenceIds' => self::jatsUniqueNonEmptyStrings($referenceIds),
                'referenceCount' => count(self::descendantElements($refList, 'ref')),
            ];
        }

        return $lists;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function jatsBackMatterReferenceSummaries(\DOMElement $backMatter): array
    {
        $references = [];
        foreach (self::descendantElements($backMatter, 'ref') as $reference) {
            $elementCitations = self::descendantElements($reference, 'element-citation');
            $mixedCitations = self::descendantElements($reference, 'mixed-citation');
            $citationTypes = [];
            foreach ([...$mixedCitations, ...$elementCitations] as $citation) {
                foreach (['publication-type', 'publication-format', 'citation-type'] as $attribute) {
                    $value = self::attribute($citation, $attribute);
                    if ($value !== null && trim($value) !== '') {
                        $citationTypes[] = trim($value);
                    }
                }
            }

            $personGroupTypes = [];
            foreach (self::descendantElements($reference, 'person-group') as $personGroup) {
                $type = self::attribute($personGroup, 'person-group-type');
                if ($type !== null && trim($type) !== '') {
                    $personGroupTypes[] = trim($type);
                }
            }

            $pubIds = self::jatsTypedTextRecords($reference, ['pub-id'], ['pub-id-type']);
            $text = self::normalizedText($reference);
            $mixedCitationText = self::jatsFirstText($reference, ['mixed-citation']);
            $references[] = [
                'id' => self::attribute($reference, 'id'),
                'label' => self::jatsFirstChildText($reference, 'label'),
                'textLength' => strlen($text),
                'textSha256' => hash('sha256', $text),
                'mixedCitationTextLength' => $mixedCitationText === null ? 0 : strlen($mixedCitationText),
                'mixedCitationTextSha256' => $mixedCitationText === null ? null : hash('sha256', $mixedCitationText),
                'elementCitationCount' => count($elementCitations),
                'citationTypes' => self::jatsUniqueNonEmptyStrings($citationTypes),
                'personGroupTypes' => self::jatsUniqueNonEmptyStrings($personGroupTypes),
                'source' => self::jatsFirstText($reference, ['source']),
                'articleTitle' => self::jatsFirstText($reference, ['article-title']),
                'chapterTitle' => self::jatsFirstText($reference, ['chapter-title']),
                'year' => self::jatsFirstText($reference, ['year']),
                'pubIds' => $pubIds,
                'pubIdCount' => count($pubIds),
            ];
        }

        return $references;
    }

    /**
     * @param list<string> $referenceIds
     * @return list<array{id:?string, refType:?string, ridRaw:?string, targets:list<string>, text:string, resolvedReferenceIds:list<string>, missingReferenceIds:list<string>}>
     */
    private static function jatsCitationXrefSummaries(\DOMElement $root, array $referenceIds): array
    {
        $referenceIdLookup = array_fill_keys($referenceIds, true);
        $citations = [];
        foreach (self::descendantElements($root, 'xref') as $xref) {
            $refType = self::attribute($xref, 'ref-type');
            $refType = $refType === null || trim($refType) === '' ? null : trim($refType);
            $ridRaw = self::attribute($xref, 'rid');
            $targets = $ridRaw === null ? [] : self::spaceSeparatedTokens($ridRaw);
            $resolved = [];
            $missing = [];
            foreach ($targets as $target) {
                if (isset($referenceIdLookup[$target])) {
                    $resolved[] = $target;
                } else {
                    $missing[] = $target;
                }
            }

            $isCitationXref = in_array($refType, ['bibr', 'citation', 'ref'], true) || $resolved !== [];
            if (!$isCitationXref) {
                continue;
            }

            $citations[] = [
                'id' => self::attribute($xref, 'id'),
                'refType' => $refType,
                'ridRaw' => $ridRaw,
                'targets' => $targets,
                'text' => self::normalizedText($xref),
                'resolvedReferenceIds' => self::jatsUniqueNonEmptyStrings($resolved),
                'missingReferenceIds' => self::jatsUniqueNonEmptyStrings($missing),
            ];
        }

        return $citations;
    }

    /**
     * @param list<array<string, mixed>> $records
     * @return list<string>
     */
    private static function jatsFlattenUniqueStringField(array $records, string $field): array
    {
        $values = [];
        foreach ($records as $record) {
            $fieldValue = $record[$field] ?? null;
            if (is_string($fieldValue)) {
                $values[] = $fieldValue;
                continue;
            }

            if (!is_array($fieldValue)) {
                continue;
            }

            foreach ($fieldValue as $value) {
                if (is_string($value)) {
                    $values[] = $value;
                }
            }
        }

        return self::jatsUniqueNonEmptyStrings($values);
    }

    /**
     * @param list<mixed> $values
     * @return list<string>
     */
    private static function jatsUniqueNonEmptyStrings(array $values): array
    {
        $strings = [];
        foreach ($values as $value) {
            if (!is_string($value) || trim($value) === '') {
                continue;
            }

            $strings[] = trim($value);
        }

        return array_values(array_unique($strings));
    }

    /**
     * @param list<array<string, mixed>> $references
     * @param list<array<string, mixed>> $citationXrefs
     * @param list<string> $missingCitationReferenceIds
     * @return list<string>
     */
    private static function jatsReviewDiagnostics(
        bool $hasBackMatter,
        array $references,
        array $citationXrefs,
        array $missingCitationReferenceIds
    ): array {
        $diagnostics = ['jats-bits-direct-reader-parity-not-implemented'];
        if ($hasBackMatter) {
            $diagnostics[] = 'jats-bits-back-matter-review-only';
        }
        if ($references !== []) {
            $diagnostics[] = 'jats-bits-reference-summary-review-only';
        }
        if ($citationXrefs !== []) {
            $diagnostics[] = 'jats-bits-citation-xref-summary-review-only';
        }
        if ($missingCitationReferenceIds !== []) {
            $diagnostics[] = 'jats-bits-citation-target-missing';
        }

        return $diagnostics;
    }

    /**
     * @return array<string, string>
     */
    private static function jatsElementIdMap(\DOMElement $root): array
    {
        $map = [];
        foreach (array_merge([$root], self::descendantElements($root)) as $element) {
            $id = self::attribute($element, 'id');
            if ($id !== null && trim($id) !== '' && !isset($map[trim($id)])) {
                $map[trim($id)] = $element->localName;
            }
        }

        ksort($map);

        return $map;
    }

    /**
     * @param array<string, string> $elementIdMap
     * @return list<array<string, mixed>>
     */
    private static function jatsXrefSummaries(\DOMElement $root, array $elementIdMap): array
    {
        $summaries = [];
        $ordinal = 1;
        foreach (self::descendantElements($root, 'xref') as $xref) {
            $targets = [];
            $rid = self::attribute($xref, 'rid');
            if ($rid !== null) {
                $targets = self::spaceSeparatedTokens($rid);
            }

            $resolvedTargets = [];
            $missingTargets = [];
            $targetElements = [];
            foreach ($targets as $target) {
                $element = $elementIdMap[$target] ?? null;
                $targetElements[] = [
                    'target' => $target,
                    'element' => $element,
                ];
                if ($element === null) {
                    $missingTargets[] = $target;
                } else {
                    $resolvedTargets[] = $target;
                }
            }

            $summaries[] = [
                'ordinal' => $ordinal++,
                'refType' => self::attribute($xref, 'ref-type'),
                'text' => self::normalizedText($xref),
                'targets' => $targets,
                'targetElements' => $targetElements,
                'resolvedTargets' => $resolvedTargets,
                'missingTargets' => $missingTargets,
                'resolved' => $missingTargets === [],
            ];
        }

        return $summaries;
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return list<string>
     */
    private static function jatsXrefTargetsFromSummaries(array $xrefs): array
    {
        $targets = [];
        foreach ($xrefs as $xref) {
            foreach ($xref['targets'] as $target) {
                $targets[] = (string) $target;
            }
        }

        return array_values(array_unique($targets));
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return list<string>
     */
    private static function jatsResolvedXrefTargets(array $xrefs): array
    {
        $targets = [];
        foreach ($xrefs as $xref) {
            foreach ($xref['resolvedTargets'] as $target) {
                $targets[] = (string) $target;
            }
        }

        return array_values(array_unique($targets));
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return list<string>
     */
    private static function jatsUnresolvedXrefTargets(array $xrefs): array
    {
        $targets = [];
        foreach ($xrefs as $xref) {
            foreach ($xref['missingTargets'] as $target) {
                $targets[] = (string) $target;
            }
        }

        return array_values(array_unique($targets));
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return array<string, int>
     */
    private static function jatsXrefCountsByTarget(array $xrefs): array
    {
        $counts = [];
        foreach ($xrefs as $xref) {
            foreach ($xref['targets'] as $target) {
                $target = (string) $target;
                $counts[$target] = ($counts[$target] ?? 0) + 1;
            }
        }
        ksort($counts);

        return $counts;
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @param list<string> $elementNames
     * @return list<string>
     */
    private static function jatsReferenceTargetsForElements(array $xrefs, array $elementNames): array
    {
        $wanted = array_fill_keys($elementNames, true);
        $targets = [];
        foreach ($xrefs as $xref) {
            foreach ($xref['targetElements'] as $targetElement) {
                $element = $targetElement['element'];
                if ($element !== null && isset($wanted[$element])) {
                    $targets[] = (string) $targetElement['target'];
                }
            }

            if ($xref['refType'] !== null && isset($wanted[(string) $xref['refType']])) {
                foreach ($xref['missingTargets'] as $target) {
                    $targets[] = (string) $target;
                }
            }
        }

        return array_values(array_unique($targets));
    }

    /**
     * @param list<string> $ids
     * @param list<array<string, mixed>> $xrefs
     * @return list<string>
     */
    private static function jatsUnreferencedElementIds(array $ids, array $xrefs): array
    {
        $referenced = array_fill_keys(self::jatsXrefTargetsFromSummaries($xrefs), true);
        $unreferenced = [];
        foreach ($ids as $id) {
            if (!isset($referenced[$id])) {
                $unreferenced[] = $id;
            }
        }

        return $unreferenced;
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return list<array<string, mixed>>
     */
    private static function jatsReferenceSummaries(\DOMElement $root, array $xrefs): array
    {
        $counts = self::jatsXrefCountsByTarget($xrefs);
        $references = [];
        foreach (self::descendantElements($root, 'ref') as $reference) {
            $id = self::attribute($reference, 'id');
            $references[] = [
                'id' => $id,
                'label' => self::jatsFirstChildText($reference, 'label'),
                'citationText' => self::normalizedText($reference),
                'referenceCount' => $id === null ? 0 : ($counts[$id] ?? 0),
            ];
        }

        return $references;
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return list<array<string, mixed>>
     */
    private static function jatsFigureSummaries(\DOMElement $root, array $xrefs): array
    {
        $counts = self::jatsXrefCountsByTarget($xrefs);
        $figures = [];
        foreach (self::descendantElements($root, 'fig') as $index => $figure) {
            $id = self::attribute($figure, 'id');
            $labelElement = self::firstChildElement($figure, 'label');
            $figureTitleElement = self::firstChildElement($figure, 'title');
            $caption = self::firstChildElement($figure, 'caption');
            $captionTitleElement = $caption instanceof \DOMElement
                ? self::firstChildElement($caption, 'title')
                : null;
            $titleElement = $figureTitleElement instanceof \DOMElement && self::jatsElementTextOrNull($figureTitleElement) !== null
                ? $figureTitleElement
                : $captionTitleElement;
            $altTextElement = self::jatsFigureAltTextElement($figure);
            $label = self::jatsElementTextOrNull($labelElement);
            $figureTitle = self::jatsElementTextOrNull($figureTitleElement);
            $captionTitle = $caption instanceof \DOMElement
                ? self::jatsElementTextOrNull($captionTitleElement)
                : null;
            $captionParagraphs = $caption instanceof \DOMElement
                ? self::jatsNonEmptyTexts(self::childElements($caption, 'p'))
                : [];
            $captionText = $caption instanceof \DOMElement ? self::jatsElementReviewText($caption) : null;
            if ($captionText === '') {
                $captionText = null;
            }
            $altText = self::jatsElementTextOrNull($altTextElement);
            $title = $figureTitle ?? $captionTitle;
            $hasLabel = $label !== null && $label !== '';
            $hasCaption = $captionText !== null && $captionText !== '';
            $hasTitle = $title !== null && $title !== '';
            $missingMetadata = [];
            if (!$hasLabel) {
                $missingMetadata[] = 'label';
            }
            if (!$hasCaption) {
                $missingMetadata[] = 'caption';
            }
            if (!$hasTitle) {
                $missingMetadata[] = 'title';
            }
            $mediaReferences = self::jatsFigureMediaReferences($figure);
            $figurePermissions = self::jatsChildPermissionSummaries($figure);
            $mediaTargets = self::jatsMediaTargets($mediaReferences);
            $licenseTargets = self::jatsPermissionLicenseTargetsForContext($figurePermissions, 'figure', $id, null);
            $permissionIssues = self::jatsPermissionLicenseIssues(
                'figure',
                $id,
                null,
                $mediaTargets,
                $figurePermissions,
                self::jatsPermissionsHaveLicense($figurePermissions) || self::jatsMediaReferencesHaveLicense($mediaReferences)
            );
            $licenseTargetIssues = self::jatsFigurePermissionLicenseTargetIssues($permissionIssues);
            foreach ($mediaReferences as $reference) {
                foreach (is_array($reference['permissionIssues'] ?? null) ? $reference['permissionIssues'] : [] as $issue) {
                    if (is_array($issue)) {
                        $permissionIssues[] = $issue;
                    }
                }
            }

            $figures[] = [
                'index' => $index,
                'id' => $id,
                'figureId' => $id,
                'sourcePosition' => self::jatsElementSourcePosition($figure, $root),
                'label' => $label,
                'title' => $title,
                'figureTitle' => $figureTitle,
                'captionTitle' => $captionTitle,
                'caption' => $captionText,
                'captionText' => $captionText,
                'captionParagraphCount' => count($captionParagraphs),
                'captionParagraphs' => $captionParagraphs,
                'altText' => $altText,
                'metadataIssueCodes' => self::jatsFigureLocalMetadataIssueCodes($captionText, $title),
                'metadataPositions' => [
                    'label' => $labelElement instanceof \DOMElement ? self::jatsElementSourcePosition($labelElement, $figure) : null,
                    'title' => $titleElement instanceof \DOMElement ? self::jatsElementSourcePosition($titleElement, $figure) : null,
                    'caption' => $caption instanceof \DOMElement ? self::jatsElementSourcePosition($caption, $figure) : null,
                    'altText' => $altTextElement instanceof \DOMElement ? self::jatsElementSourcePosition($altTextElement, $figure) : null,
                ],
                'xrefTargets' => self::jatsXrefTargetsInElement($figure),
                'graphicHrefs' => self::jatsGraphicHrefs($figure),
                'mediaReferences' => $mediaReferences,
                'mediaReferenceCount' => count($mediaReferences),
                'mediaIssueCodes' => self::jatsFigureMediaIssueCodes($mediaReferences),
                'media' => $mediaReferences,
                'mediaCount' => count($mediaReferences),
                'mediaTargets' => $mediaTargets,
                'mediaTargetCount' => count($mediaTargets),
                'permissions' => $figurePermissions,
                'permissionCount' => count($figurePermissions),
                'licenseCount' => self::jatsPermissionRecordCount($figurePermissions, 'licenses'),
                'licenseRefCount' => self::jatsPermissionRecordCount($figurePermissions, 'licenseRefs'),
                'copyrightStatementCount' => self::jatsPermissionRecordCount($figurePermissions, 'copyrightStatements'),
                'licenseTargets' => $licenseTargets,
                'licenseTargetCount' => count($licenseTargets),
                'licenseTargetIssueCodes' => self::jatsFigurePermissionIssueCodes($licenseTargetIssues),
                'licenseTargetIssueCount' => count($licenseTargetIssues),
                'permissionIssues' => $permissionIssues,
                'permissionIssueCodes' => self::jatsFigurePermissionIssueCodes($permissionIssues),
                'permissionIssueCount' => count($permissionIssues),
                'payloadBytesExposed' => false,
                'hasLabel' => $hasLabel,
                'hasCaption' => $hasCaption,
                'hasTitle' => $hasTitle,
                'missingMetadata' => $missingMetadata,
                'reviewPolicy' => 'metadata-only',
                'referenceCount' => $id === null ? 0 : ($counts[$id] ?? 0),
            ];
        }

        return $figures;
    }

    /**
     * @param list<array<string, mixed>> $figures
     * @return array{total:int, withLabel:int, withCaption:int, withTitle:int, missingLabel:int, missingCaption:int, missingTitle:int, incomplete:int}
     */
    private static function jatsFigureMetadataCounts(array $figures): array
    {
        $counts = [
            'total' => count($figures),
            'withLabel' => 0,
            'withCaption' => 0,
            'withTitle' => 0,
            'missingLabel' => 0,
            'missingCaption' => 0,
            'missingTitle' => 0,
            'incomplete' => 0,
        ];

        foreach ($figures as $figure) {
            $missingAny = false;
            foreach ([
                'Label' => 'hasLabel',
                'Caption' => 'hasCaption',
                'Title' => 'hasTitle',
            ] as $suffix => $key) {
                if (($figure[$key] ?? false) === true) {
                    ++$counts['with' . $suffix];
                    continue;
                }

                ++$counts['missing' . $suffix];
                $missingAny = true;
            }

            if ($missingAny) {
                ++$counts['incomplete'];
            }
        }

        return $counts;
    }

    /**
     * @param list<array<string, mixed>> $figures
     * @return list<array{label:string, figureIds:list<string>, figureCount:int}>
     */
    private static function jatsDuplicateFigureLabels(array $figures): array
    {
        $buckets = [];
        foreach ($figures as $figure) {
            $label = $figure['label'] ?? null;
            if (!is_string($label) || trim($label) === '') {
                continue;
            }

            $key = strtolower(trim($label));
            $id = $figure['id'] ?? null;
            $buckets[$key]['label'] ??= trim($label);
            if (is_string($id) && trim($id) !== '') {
                $buckets[$key]['figureIds'][] = trim($id);
            }
        }

        $duplicates = [];
        foreach ($buckets as $bucket) {
            $figureIds = array_values(array_unique($bucket['figureIds'] ?? []));
            if (count($figureIds) < 2) {
                continue;
            }

            $duplicates[] = [
                'label' => (string) $bucket['label'],
                'figureIds' => $figureIds,
                'figureCount' => count($figureIds),
            ];
        }

        return $duplicates;
    }

    /**
     * @param list<array<string, mixed>> $figures
     * @param list<array{label:string, figureIds:list<string>, figureCount:int}> $duplicateLabels
     * @return list<array<string, mixed>>
     */
    private static function jatsFigureMetadataIssues(array $figures, array $duplicateLabels): array
    {
        $duplicateLabelKeys = [];
        foreach ($duplicateLabels as $duplicate) {
            $duplicateLabelKeys[strtolower(trim($duplicate['label']))] = true;
        }

        $issues = [];
        foreach ($figures as $figure) {
            $captionText = $figure['captionText'] ?? null;
            $title = $figure['title'] ?? null;
            $label = $figure['label'] ?? null;
            $positions = is_array($figure['metadataPositions'] ?? null) ? $figure['metadataPositions'] : [];
            $figurePosition = $figure['sourcePosition'] ?? null;

            if (!is_string($captionText) || trim($captionText) === '') {
                $issues[] = self::jatsFigureMetadataIssue(
                    'missing-caption',
                    'warning',
                    'Figure omits a non-empty caption.',
                    $figure,
                    is_array($figurePosition) ? $figurePosition : null
                );
            }

            if (!is_string($title) || trim($title) === '') {
                $issues[] = self::jatsFigureMetadataIssue(
                    'missing-title',
                    'warning',
                    'Figure omits a non-empty title.',
                    $figure,
                    is_array($figurePosition) ? $figurePosition : null
                );
            }

            if (is_string($label) && isset($duplicateLabelKeys[strtolower(trim($label))])) {
                $position = $positions['label'] ?? null;
                $issues[] = self::jatsFigureMetadataIssue(
                    'duplicate-label',
                    'warning',
                    'Figure label is duplicated across figure ids.',
                    $figure,
                    is_array($position) ? $position : null
                );
            }
        }

        return $issues;
    }

    /**
     * @param array<string, mixed> $figure
     * @param array<string, mixed>|null $sourcePosition
     * @return array<string, mixed>
     */
    private static function jatsFigureMetadataIssue(
        string $code,
        string $severity,
        string $message,
        array $figure,
        ?array $sourcePosition
    ): array {
        return [
            'code' => $code,
            'severity' => $severity,
            'message' => $message,
            'figureId' => $figure['id'] ?? null,
            'label' => $figure['label'] ?? null,
            'sourcePosition' => $sourcePosition,
        ];
    }

    /**
     * @param list<array<string, mixed>> $issues
     * @return list<string>
     */
    private static function jatsFigureIssueCodes(array $issues): array
    {
        $codes = [];
        foreach ($issues as $issue) {
            $code = $issue['code'] ?? null;
            if (is_string($code) && $code !== '') {
                $codes[] = $code;
            }
        }

        return self::jatsOrderedIssueCodes($codes, [
            'missing-caption' => 0,
            'missing-title' => 1,
            'duplicate-label' => 2,
        ]);
    }

    /**
     * @param list<array<string, mixed>> $issues
     */
    private static function jatsFigureIssueCount(array $issues, string $code): int
    {
        $count = 0;
        foreach ($issues as $issue) {
            if (($issue['code'] ?? null) === $code) {
                ++$count;
            }
        }

        return $count;
    }

    /**
     * @param list<string> $figureIds
     * @return list<array<string, mixed>>
     */
    private static function jatsFigureXrefLinks(\DOMElement $root, array $figureIds): array
    {
        $figureIdSet = array_fill_keys($figureIds, true);
        $links = [];
        foreach (self::descendantElements($root, 'xref') as $xref) {
            $rid = self::attribute($xref, 'rid');
            if ($rid === null || trim($rid) === '') {
                continue;
            }

            $targetIds = self::spaceSeparatedTokens($rid);
            $resolvedFigureIds = array_values(array_filter(
                $targetIds,
                static fn (string $target): bool => isset($figureIdSet[$target])
            ));
            $refType = self::attribute($xref, 'ref-type');
            $normalizedRefType = is_string($refType) && trim($refType) !== '' ? strtolower(trim($refType)) : null;
            $missingFigureIds = $normalizedRefType === 'fig'
                ? array_values(array_filter(
                    $targetIds,
                    static fn (string $target): bool => !isset($figureIdSet[$target])
                ))
                : [];

            if ($resolvedFigureIds === [] && $missingFigureIds === []) {
                continue;
            }

            $links[] = [
                'refType' => $refType === null || trim($refType) === '' ? null : trim($refType),
                'rid' => trim($rid),
                'targetIds' => $targetIds,
                'figureIds' => $resolvedFigureIds,
                'missingFigureIds' => $missingFigureIds,
                'text' => self::normalizedText($xref),
                'sourcePosition' => self::jatsElementSourcePosition($xref, $root),
            ];
        }

        return $links;
    }

    /**
     * @param list<array<string, mixed>> $links
     * @return list<string>
     */
    private static function jatsFigureXrefTargetIds(array $links): array
    {
        $ids = [];
        foreach ($links as $link) {
            foreach (($link['figureIds'] ?? []) as $id) {
                if (is_string($id) && $id !== '') {
                    $ids[] = $id;
                }
            }
        }

        return array_values(array_unique($ids));
    }

    /**
     * @param list<string> $codes
     * @param array<string, int> $priority
     * @return list<string>
     */
    private static function jatsOrderedIssueCodes(array $codes, array $priority): array
    {
        $codes = array_values(array_unique(array_filter(
            $codes,
            static fn (string $code): bool => $code !== ''
        )));
        usort($codes, static function (string $left, string $right) use ($priority): int {
            return ($priority[$left] ?? 99) <=> ($priority[$right] ?? 99)
                ?: $left <=> $right;
        });

        return $codes;
    }

    /**
     * @param list<array<string, mixed>> $figures
     * @return list<array<string, mixed>>
     */
    private static function jatsFigureMediaReferenceList(array $figures): array
    {
        $references = [];
        foreach ($figures as $figure) {
            foreach (($figure['mediaReferences'] ?? []) as $reference) {
                if (is_array($reference)) {
                    $references[] = $reference;
                }
            }
        }

        return $references;
    }

    /**
     * @param list<array<string, mixed>> $figures
     * @return list<array<string, mixed>>
     */
    private static function jatsFigurePermissionSummaries(array $figures): array
    {
        $summaries = [];
        foreach ($figures as $figure) {
            $media = self::jatsFigurePermissionMediaSummaries(
                is_array($figure['mediaReferences'] ?? null) ? $figure['mediaReferences'] : []
            );
            $summaries[] = [
                'figureId' => is_string($figure['id'] ?? null) ? $figure['id'] : null,
                'label' => is_string($figure['label'] ?? null) ? $figure['label'] : null,
                'captionText' => is_string($figure['captionText'] ?? null) ? $figure['captionText'] : null,
                'mediaTargets' => is_array($figure['mediaTargets'] ?? null) ? array_values($figure['mediaTargets']) : [],
                'mediaTargetCount' => (int) ($figure['mediaTargetCount'] ?? 0),
                'media' => $media,
                'mediaCount' => count($media),
                'permissions' => is_array($figure['permissions'] ?? null) ? array_values($figure['permissions']) : [],
                'permissionCount' => (int) ($figure['permissionCount'] ?? 0),
                'licenseCount' => (int) ($figure['licenseCount'] ?? 0),
                'licenseRefCount' => (int) ($figure['licenseRefCount'] ?? 0),
                'copyrightStatementCount' => (int) ($figure['copyrightStatementCount'] ?? 0),
                'licenseTargets' => is_array($figure['licenseTargets'] ?? null) ? array_values($figure['licenseTargets']) : [],
                'licenseTargetCount' => (int) ($figure['licenseTargetCount'] ?? 0),
                'licenseTargetIssueCodes' => is_array($figure['licenseTargetIssueCodes'] ?? null) ? array_values($figure['licenseTargetIssueCodes']) : [],
                'licenseTargetIssueCount' => (int) ($figure['licenseTargetIssueCount'] ?? 0),
                'payloadBytesExposed' => false,
                'issues' => is_array($figure['permissionIssues'] ?? null) ? array_values($figure['permissionIssues']) : [],
            ];
        }

        return $summaries;
    }

    /**
     * @param list<array<string, mixed>> $mediaReferences
     * @return list<array<string, mixed>>
     */
    private static function jatsFigurePermissionMediaSummaries(array $mediaReferences): array
    {
        $media = [];
        foreach ($mediaReferences as $reference) {
            $media[] = [
                'element' => is_string($reference['element'] ?? null) ? $reference['element'] : '',
                'id' => is_string($reference['id'] ?? null) ? $reference['id'] : null,
                'figureId' => is_string($reference['figureId'] ?? null) ? $reference['figureId'] : null,
                'target' => is_string($reference['target'] ?? null) ? $reference['target'] : null,
                'mimeType' => is_string($reference['mimetype'] ?? null) ? $reference['mimetype'] : null,
                'mimeSubtype' => is_string($reference['mimeSubtype'] ?? null) ? $reference['mimeSubtype'] : null,
                'permissions' => is_array($reference['permissions'] ?? null) ? array_values($reference['permissions']) : [],
                'permissionCount' => (int) ($reference['permissionCount'] ?? 0),
                'licenseCount' => (int) ($reference['licenseCount'] ?? 0),
                'licenseRefCount' => (int) ($reference['licenseRefCount'] ?? 0),
                'copyrightStatementCount' => (int) ($reference['copyrightStatementCount'] ?? 0),
                'licenseTargets' => is_array($reference['licenseTargets'] ?? null) ? array_values($reference['licenseTargets']) : [],
                'licenseTargetCount' => (int) ($reference['licenseTargetCount'] ?? 0),
                'licenseTargetIssueCodes' => is_array($reference['licenseTargetIssueCodes'] ?? null) ? array_values($reference['licenseTargetIssueCodes']) : [],
                'licenseTargetIssueCount' => (int) ($reference['licenseTargetIssueCount'] ?? 0),
                'payloadBytesExposed' => false,
                'issues' => is_array($reference['permissionIssues'] ?? null) ? array_values($reference['permissionIssues']) : [],
            ];
        }

        return $media;
    }

    /**
     * @param list<array<string, mixed>> $summaries
     * @return list<array<string, mixed>>
     */
    private static function jatsFigurePermissionIssues(array $summaries): array
    {
        $issues = [];
        foreach ($summaries as $summary) {
            foreach (is_array($summary['issues'] ?? null) ? $summary['issues'] : [] as $issue) {
                if (is_array($issue)) {
                    $issues[] = $issue;
                }
            }
        }

        return $issues;
    }

    /**
     * @param list<array<string, mixed>> $summaries
     * @return list<array<string, mixed>>
     */
    private static function jatsFigurePermissionLicenseTargets(array $summaries): array
    {
        $targets = [];
        foreach ($summaries as $summary) {
            foreach (is_array($summary['licenseTargets'] ?? null) ? $summary['licenseTargets'] : [] as $target) {
                if (is_array($target)) {
                    $targets[] = $target;
                }
            }

            foreach (is_array($summary['media'] ?? null) ? $summary['media'] : [] as $media) {
                if (!is_array($media)) {
                    continue;
                }

                foreach (is_array($media['licenseTargets'] ?? null) ? $media['licenseTargets'] : [] as $target) {
                    if (is_array($target)) {
                        $targets[] = $target;
                    }
                }
            }
        }

        return $targets;
    }

    /**
     * @param list<array<string, mixed>> $issues
     * @return list<array<string, mixed>>
     */
    private static function jatsFigurePermissionLicenseTargetIssues(array $issues): array
    {
        $targetIssues = [];
        foreach ($issues as $issue) {
            $code = $issue['code'] ?? null;
            if (is_string($code) && self::jatsIsLicenseTargetIssueCode($code)) {
                $targetIssues[] = $issue;
            }
        }

        return $targetIssues;
    }

    private static function jatsIsLicenseTargetIssueCode(string $code): bool
    {
        return in_array($code, [
            'duplicate-license-target',
            'missing-license-target',
            'unsafe-license-target',
        ], true);
    }

    /**
     * @param list<array<string, mixed>> $issues
     * @return list<string>
     */
    private static function jatsFigurePermissionIssueCodes(array $issues): array
    {
        $codes = [];
        foreach ($issues as $issue) {
            $code = $issue['code'] ?? null;
            if (is_string($code) && $code !== '') {
                $codes[] = $code;
            }
        }

        return self::jatsOrderedIssueCodes($codes, [
            'duplicate-license' => 0,
            'duplicate-license-ref' => 1,
            'duplicate-license-target' => 2,
            'missing-license' => 3,
            'missing-license-target' => 4,
            'unsafe-license-target' => 5,
        ]);
    }

    /**
     * @param list<array<string, mixed>> $summaries
     * @return list<string>
     */
    private static function jatsFigureMediaTargets(array $summaries): array
    {
        $targets = [];
        foreach ($summaries as $summary) {
            foreach (is_array($summary['mediaTargets'] ?? null) ? $summary['mediaTargets'] : [] as $target) {
                if (is_string($target) && $target !== '') {
                    $targets[] = $target;
                }
            }
        }

        return array_values(array_unique($targets));
    }

    /**
     * @param list<array<string, mixed>> $media
     * @return list<string>
     */
    private static function jatsMediaTargets(array $media): array
    {
        $targets = [];
        foreach ($media as $item) {
            $target = $item['target'] ?? null;
            if (is_string($target) && $target !== '') {
                $targets[] = $target;
            }
        }

        return array_values(array_unique($targets));
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function jatsChildPermissionSummaries(\DOMElement $element): array
    {
        $summaries = [];
        foreach (self::childElements($element, 'permissions') as $permissions) {
            $licenses = self::jatsLicenseSummaries($permissions);
            $licenseRefs = self::jatsLicenseRefSummaries($permissions);
            $licenseTargets = self::jatsPermissionLicenseTargetSummaries($permissions);
            $licenseTargetIssues = self::jatsPermissionLicenseTargetIssuesForTargets($licenseTargets);
            $copyrightStatements = self::jatsTextList($permissions, 'copyright-statement');
            $summaries[] = [
                'id' => self::normalizedAttribute($permissions, 'id'),
                'copyrightStatements' => $copyrightStatements,
                'copyrightYears' => self::jatsTextList($permissions, 'copyright-year'),
                'copyrightHolders' => self::jatsTextList($permissions, 'copyright-holder'),
                'licenses' => $licenses,
                'licenseRefs' => $licenseRefs,
                'licenseCount' => count($licenses),
                'licenseRefCount' => count($licenseRefs),
                'licenseTargets' => $licenseTargets,
                'licenseTargetCount' => count($licenseTargets),
                'licenseTargetKinds' => self::jatsLicenseTargetKinds($licenseTargets),
                'licenseTargetIssueCodes' => self::jatsFigurePermissionIssueCodes($licenseTargetIssues),
                'licenseTargetIssueCount' => count($licenseTargetIssues),
                'payloadBytesExposed' => false,
                'copyrightStatementCount' => count($copyrightStatements),
            ];
        }

        return $summaries;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function jatsPermissionLicenseTargetSummaries(\DOMElement $permissions): array
    {
        $targets = [];
        foreach (self::descendantElements($permissions) as $element) {
            if (!isset(self::JATS_LICENSE_TARGET_ELEMENTS[$element->localName])) {
                continue;
            }

            $target = self::jatsLinkTarget($element);
            $targetKind = self::jatsLicenseTargetKind($target);
            $targets[] = [
                'element' => $element->localName,
                'id' => self::normalizedAttribute($element, 'id'),
                'type' => self::jatsLicenseTargetType($element),
                'hrefAttribute' => self::jatsLinkTargetAttribute($element),
                'target' => $target,
                'targetKind' => $targetKind,
                'targetScheme' => self::jatsLicenseTargetScheme($target),
                'text' => self::normalizedText($element),
                'sourcePosition' => self::jatsElementSourcePosition($element, $permissions),
                'payloadBytesExposed' => false,
                'issues' => self::jatsLicenseTargetLocalIssues($element, $target, $targetKind),
            ];
        }

        $duplicateTargetKeys = self::jatsDuplicateLicenseTargetKeys($targets);
        foreach ($targets as &$target) {
            $key = self::jatsLicenseTargetIdentity($target['target'] ?? null);
            if ($key !== null && isset($duplicateTargetKeys[$key])) {
                $issues = is_array($target['issues'] ?? null) ? $target['issues'] : [];
                if (!in_array('duplicate-license-target', $issues, true)) {
                    $issues[] = 'duplicate-license-target';
                }
                $target['issues'] = $issues;
            }
        }
        unset($target);

        return $targets;
    }

    private static function jatsLicenseTargetType(\DOMElement $element): ?string
    {
        foreach (['license-type', 'ext-link-type', 'content-type', 'specific-use'] as $attribute) {
            $type = self::normalizedAttribute($element, $attribute);
            if ($type !== null) {
                return $type;
            }
        }

        return null;
    }

    /**
     * @return list<string>
     */
    private static function jatsLicenseTargetLocalIssues(\DOMElement $element, ?string $target, string $targetKind): array
    {
        if ($target === null) {
            if ($element->localName !== 'license' || !self::jatsLicenseElementHasNestedTarget($element)) {
                return ['missing-license-target'];
            }

            return [];
        }

        return $targetKind === 'unsafe' ? ['unsafe-license-target'] : [];
    }

    private static function jatsLicenseElementHasNestedTarget(\DOMElement $license): bool
    {
        foreach (self::descendantElements($license) as $element) {
            if (isset(self::JATS_LICENSE_TARGET_ELEMENTS[$element->localName]) && self::jatsLinkTarget($element) !== null) {
                return true;
            }
        }

        return false;
    }

    private static function jatsLicenseTargetKind(?string $target): string
    {
        if ($target === null || trim($target) === '') {
            return 'missing';
        }

        $target = trim($target);
        if (str_starts_with($target, '#')) {
            return 'fragment';
        }

        if (str_starts_with($target, '//')) {
            return 'external';
        }

        $scheme = self::jatsLicenseTargetScheme($target);
        if ($scheme !== null) {
            return isset(self::JATS_SAFE_LICENSE_TARGET_SCHEMES[$scheme]) ? 'external' : 'unsafe';
        }

        return 'internal';
    }

    private static function jatsLicenseTargetScheme(?string $target): ?string
    {
        if (!is_string($target) || trim($target) === '') {
            return null;
        }

        return preg_match('/^([A-Za-z][A-Za-z0-9+.-]*):/', trim($target), $matches) === 1
            ? strtolower($matches[1])
            : null;
    }

    /**
     * @param list<array<string, mixed>> $targets
     * @return array<string, true>
     */
    private static function jatsDuplicateLicenseTargetKeys(array $targets): array
    {
        $counts = [];
        foreach ($targets as $target) {
            $key = self::jatsLicenseTargetIdentity($target['target'] ?? null);
            if ($key === null) {
                continue;
            }

            $counts[$key] = ($counts[$key] ?? 0) + 1;
        }

        $duplicates = [];
        foreach ($counts as $key => $count) {
            if ($count > 1) {
                $duplicates[$key] = true;
            }
        }

        return $duplicates;
    }

    private static function jatsLicenseTargetIdentity(mixed $target): ?string
    {
        return is_string($target) && trim($target) !== '' ? trim($target) : null;
    }

    /**
     * @param list<array<string, mixed>> $targets
     * @return list<array<string, mixed>>
     */
    private static function jatsPermissionLicenseTargetIssuesForTargets(array $targets): array
    {
        $issues = [];
        foreach ($targets as $target) {
            foreach (is_array($target['issues'] ?? null) ? $target['issues'] : [] as $code) {
                if (!is_string($code) || $code === '') {
                    continue;
                }

                $issues[] = [
                    'code' => $code,
                    'element' => $target['element'] ?? null,
                    'target' => $target['target'] ?? null,
                    'targetKind' => $target['targetKind'] ?? null,
                    'targetScheme' => $target['targetScheme'] ?? null,
                    'hrefAttribute' => $target['hrefAttribute'] ?? null,
                    'sourcePosition' => $target['sourcePosition'] ?? null,
                    'payloadBytesExposed' => false,
                ];
            }
        }

        return $issues;
    }

    /**
     * @param list<array<string, mixed>> $targets
     * @return list<string>
     */
    private static function jatsLicenseTargetKinds(array $targets): array
    {
        $kinds = [];
        foreach ($targets as $target) {
            $kind = $target['targetKind'] ?? null;
            if (is_string($kind) && $kind !== '') {
                $kinds[] = $kind;
            }
        }

        return array_values(array_unique($kinds));
    }

    /**
     * @param list<array<string, mixed>> $permissions
     * @return list<array<string, mixed>>
     */
    private static function jatsPermissionLicenseTargetsForContext(
        array $permissions,
        string $scope,
        ?string $figureId,
        ?string $mediaTarget
    ): array {
        $targets = [];
        foreach ($permissions as $permission) {
            foreach (is_array($permission['licenseTargets'] ?? null) ? $permission['licenseTargets'] : [] as $target) {
                if (!is_array($target)) {
                    continue;
                }

                $targets[] = [
                    'scope' => $scope,
                    'figureId' => $figureId,
                    'mediaTarget' => $mediaTarget,
                    'permissionId' => is_string($permission['id'] ?? null) ? $permission['id'] : null,
                ] + $target;
            }
        }

        return $targets;
    }

    /**
     * @param list<array<string, mixed>> $permissions
     * @return list<array<string, mixed>>
     */
    private static function jatsPermissionLicenseTargetIssues(
        string $scope,
        ?string $figureId,
        ?string $mediaTarget,
        array $permissions
    ): array {
        $targets = self::jatsPermissionLicenseTargetsForContext($permissions, $scope, $figureId, $mediaTarget);
        $issues = [];
        foreach ($targets as $target) {
            foreach (is_array($target['issues'] ?? null) ? $target['issues'] : [] as $code) {
                if (!is_string($code) || $code === '' || $code === 'duplicate-license-target') {
                    continue;
                }

                $issues[] = self::jatsLicenseTargetIssue($code, $target);
            }
        }

        foreach (self::jatsDuplicateLicenseTargetIssueGroups($targets) as $issue) {
            $issues[] = $issue;
        }

        return $issues;
    }

    /**
     * @param array<string, mixed> $target
     * @return array<string, mixed>
     */
    private static function jatsLicenseTargetIssue(string $code, array $target): array
    {
        return [
            'code' => $code,
            'scope' => $target['scope'] ?? null,
            'figureId' => $target['figureId'] ?? null,
            'mediaTarget' => $target['mediaTarget'] ?? null,
            'permissionId' => $target['permissionId'] ?? null,
            'element' => $target['element'] ?? null,
            'target' => $target['target'] ?? null,
            'targetKind' => $target['targetKind'] ?? null,
            'targetScheme' => $target['targetScheme'] ?? null,
            'hrefAttribute' => $target['hrefAttribute'] ?? null,
            'sourcePosition' => $target['sourcePosition'] ?? null,
            'payloadBytesExposed' => false,
        ];
    }

    /**
     * @param list<array<string, mixed>> $targets
     * @return list<array<string, mixed>>
     */
    private static function jatsDuplicateLicenseTargetIssueGroups(array $targets): array
    {
        $groups = [];
        foreach ($targets as $target) {
            $key = self::jatsLicenseTargetIdentity($target['target'] ?? null);
            if ($key === null) {
                continue;
            }

            $groups[$key]['target'] ??= $key;
            $groups[$key]['targetKind'] ??= $target['targetKind'] ?? null;
            $groups[$key]['targetScheme'] ??= $target['targetScheme'] ?? null;
            $groups[$key]['scope'] ??= $target['scope'] ?? null;
            $groups[$key]['figureId'] ??= $target['figureId'] ?? null;
            $groups[$key]['mediaTarget'] ??= $target['mediaTarget'] ?? null;
            $groups[$key]['elements'][] = $target['element'] ?? null;
            $groups[$key]['permissionIds'][] = $target['permissionId'] ?? null;
            $groups[$key]['count'] = ($groups[$key]['count'] ?? 0) + 1;
        }

        $issues = [];
        foreach ($groups as $group) {
            if ((int) ($group['count'] ?? 0) < 2) {
                continue;
            }

            $issues[] = [
                'code' => 'duplicate-license-target',
                'scope' => $group['scope'],
                'figureId' => $group['figureId'],
                'mediaTarget' => $group['mediaTarget'],
                'target' => $group['target'],
                'targetKind' => $group['targetKind'],
                'targetScheme' => $group['targetScheme'],
                'elements' => self::jatsUniqueNonEmptyStrings($group['elements'] ?? []),
                'permissionIds' => self::jatsUniqueNonEmptyStrings($group['permissionIds'] ?? []),
                'count' => (int) $group['count'],
                'payloadBytesExposed' => false,
            ];
        }

        return $issues;
    }

    /**
     * @return list<array{id:?string, licenseType:?string, href:?string, text:string, licenseParagraphs:list<string>}>
     */
    private static function jatsLicenseSummaries(\DOMElement $permissions): array
    {
        $licenses = [];
        foreach (self::descendantElements($permissions, 'license') as $license) {
            $licenses[] = [
                'id' => self::normalizedAttribute($license, 'id'),
                'licenseType' => self::normalizedAttribute($license, 'license-type'),
                'href' => self::jatsLinkTarget($license),
                'text' => self::normalizedText($license),
                'licenseParagraphs' => self::jatsTextList($license, 'license-p'),
            ];
        }

        return $licenses;
    }

    /**
     * @return list<array{id:?string, href:?string, text:string}>
     */
    private static function jatsLicenseRefSummaries(\DOMElement $permissions): array
    {
        $refs = [];
        foreach (self::descendantElements($permissions, 'license-ref') as $ref) {
            $refs[] = [
                'id' => self::normalizedAttribute($ref, 'id'),
                'href' => self::jatsLinkTarget($ref),
                'text' => self::normalizedText($ref),
            ];
        }

        return $refs;
    }

    /**
     * @param list<string> $mediaTargets
     * @param list<array<string, mixed>> $permissions
     * @return list<array<string, mixed>>
     */
    private static function jatsPermissionLicenseIssues(
        string $scope,
        ?string $figureId,
        ?string $mediaTarget,
        array $mediaTargets,
        array $permissions,
        bool $hasAnyLicense
    ): array {
        $issues = [];
        if (($permissions !== [] || ($scope === 'figure' && $mediaTargets !== [])) && !$hasAnyLicense) {
            $issues[] = [
                'code' => 'missing-license',
                'scope' => $scope,
                'figureId' => $figureId,
                'mediaTarget' => $mediaTarget,
                'mediaTargets' => $mediaTargets,
            ];
        }

        foreach (self::jatsPermissionDuplicateLicenseIssues($scope, $figureId, $mediaTarget, $permissions) as $issue) {
            $issues[] = $issue;
        }

        foreach (self::jatsPermissionLicenseTargetIssues($scope, $figureId, $mediaTarget, $permissions) as $issue) {
            $issues[] = $issue;
        }

        return $issues;
    }

    /**
     * @param list<array<string, mixed>> $permissions
     * @return list<array<string, mixed>>
     */
    private static function jatsPermissionDuplicateLicenseIssues(
        string $scope,
        ?string $figureId,
        ?string $mediaTarget,
        array $permissions
    ): array {
        $counts = [];
        foreach ($permissions as $permission) {
            foreach (is_array($permission['licenses'] ?? null) ? $permission['licenses'] : [] as $license) {
                if (is_array($license)) {
                    $key = self::jatsLicenseIdentity($license);
                    $counts['license'][$key] = ($counts['license'][$key] ?? 0) + 1;
                }
            }
            foreach (is_array($permission['licenseRefs'] ?? null) ? $permission['licenseRefs'] : [] as $licenseRef) {
                if (is_array($licenseRef)) {
                    $key = self::jatsLicenseIdentity($licenseRef);
                    $counts['license-ref'][$key] = ($counts['license-ref'][$key] ?? 0) + 1;
                }
            }
        }

        $issues = [];
        foreach ($counts as $kind => $kindCounts) {
            foreach ($kindCounts as $key => $count) {
                if ($count < 2) {
                    continue;
                }
                $issues[] = [
                    'code' => $kind === 'license' ? 'duplicate-license' : 'duplicate-license-ref',
                    'scope' => $scope,
                    'figureId' => $figureId,
                    'mediaTarget' => $mediaTarget,
                    'licenseKey' => $key,
                    'count' => $count,
                ];
            }
        }

        return $issues;
    }

    /**
     * @param array<string, mixed> $license
     */
    private static function jatsLicenseIdentity(array $license): string
    {
        foreach (['href', 'licenseType', 'text'] as $key) {
            $value = $license[$key] ?? null;
            if (is_string($value) && trim($value) !== '') {
                return $key . ':' . trim($value);
            }
        }

        return 'empty-license';
    }

    /**
     * @param list<array<string, mixed>> $permissions
     */
    private static function jatsPermissionsHaveLicense(array $permissions): bool
    {
        foreach ($permissions as $permission) {
            if ((int) ($permission['licenseCount'] ?? 0) > 0 || (int) ($permission['licenseRefCount'] ?? 0) > 0) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param list<array<string, mixed>> $media
     */
    private static function jatsMediaReferencesHaveLicense(array $media): bool
    {
        foreach ($media as $item) {
            if ((int) ($item['licenseCount'] ?? 0) > 0 || (int) ($item['licenseRefCount'] ?? 0) > 0) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param list<array<string, mixed>> $permissions
     */
    private static function jatsPermissionRecordCount(array $permissions, string $key): int
    {
        $count = 0;
        foreach ($permissions as $permission) {
            $records = $permission[$key] ?? [];
            if (is_array($records)) {
                $count += count($records);
            }
        }

        return $count;
    }

    private static function jatsLinkTarget(\DOMElement $element): ?string
    {
        return self::normalizedAttribute($element, 'href', self::XLINK_NAMESPACE)
            ?? self::normalizedAttribute($element, 'xlink:href')
            ?? self::normalizedAttribute($element, 'href');
    }

    /**
     * @param list<array<string, mixed>> $references
     * @return list<string>
     */
    private static function jatsFigureMediaIssueCodes(array $references): array
    {
        $codes = [];
        foreach ($references as $reference) {
            foreach (($reference['issues'] ?? []) as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $codes[] = $issue;
                }
            }
        }

        $codes = array_values(array_unique($codes));
        $priority = [
            'missing-target' => 0,
            'unsupported-external-reference' => 1,
        ];
        usort($codes, static function (string $left, string $right) use ($priority): int {
            return ($priority[$left] ?? 99) <=> ($priority[$right] ?? 99)
                ?: $left <=> $right;
        });

        return $codes;
    }

    /**
     * @param list<array<string, mixed>> $references
     */
    private static function jatsFigureMediaIssueCount(array $references, string $code): int
    {
        $count = 0;
        foreach ($references as $reference) {
            $issues = $reference['issues'] ?? [];
            if (is_array($issues) && in_array($code, $issues, true)) {
                ++$count;
            }
        }

        return $count;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function jatsFigureMediaReferences(\DOMElement $figure): array
    {
        $references = [];
        $figureId = self::attribute($figure, 'id');

        foreach (self::descendantElements($figure) as $element) {
            if (!isset(self::JATS_FIGURE_MEDIA_ELEMENTS[$element->localName])) {
                continue;
            }

            $href = self::jatsFigureMediaHref($element);
            $target = $href['target'];
            $issues = self::jatsFigureMediaIssues($target);
            $permissions = self::jatsChildPermissionSummaries($element);
            $licenseTargets = self::jatsPermissionLicenseTargetsForContext($permissions, 'media', $figureId, $target);
            $permissionIssues = self::jatsPermissionLicenseIssues(
                'media',
                $figureId,
                $target,
                $target === null ? [] : [$target],
                $permissions,
                self::jatsPermissionsHaveLicense($permissions)
            );
            $licenseTargetIssues = self::jatsFigurePermissionLicenseTargetIssues($permissionIssues);

            $references[] = [
                'figureId' => $figureId,
                'element' => $element->localName,
                'id' => self::attribute($element, 'id'),
                'sourcePosition' => self::jatsElementSourcePosition($element, $figure),
                'hrefAttribute' => $href['attribute'],
                'target' => $target,
                'targetBasename' => self::jatsFigureMediaTargetBasename($target),
                'targetKind' => self::jatsFigureMediaTargetKind($target),
                'mimetype' => self::attribute($element, 'mimetype'),
                'mimeSubtype' => self::attribute($element, 'mime-subtype'),
                'mimeType' => self::attribute($element, 'mimetype'),
                'contentType' => self::jatsFigureMediaContentType($element),
                'specificUse' => self::attribute($element, 'specific-use'),
                'position' => self::attribute($element, 'position'),
                'orientation' => self::attribute($element, 'orientation'),
                'payloadBytesExposed' => false,
                'permissions' => $permissions,
                'permissionCount' => count($permissions),
                'licenseCount' => self::jatsPermissionRecordCount($permissions, 'licenses'),
                'licenseRefCount' => self::jatsPermissionRecordCount($permissions, 'licenseRefs'),
                'copyrightStatementCount' => self::jatsPermissionRecordCount($permissions, 'copyrightStatements'),
                'licenseTargets' => $licenseTargets,
                'licenseTargetCount' => count($licenseTargets),
                'licenseTargetIssueCodes' => self::jatsFigurePermissionIssueCodes($licenseTargetIssues),
                'licenseTargetIssueCount' => count($licenseTargetIssues),
                'permissionPayloadBytesExposed' => false,
                'permissionIssues' => $permissionIssues,
                'permissionIssueCodes' => self::jatsFigurePermissionIssueCodes($permissionIssues),
                'permissionIssueCount' => count($permissionIssues),
                'issues' => $issues,
                'issueCount' => count($issues),
            ];
        }

        return $references;
    }

    /**
     * @return array{attribute:?string, target:?string}
     */
    private static function jatsFigureMediaHref(\DOMElement $element): array
    {
        $xlinkHref = self::attribute($element, 'href', 'http://www.w3.org/1999/xlink');
        if ($xlinkHref !== null) {
            return [
                'attribute' => 'xlink:href',
                'target' => trim($xlinkHref) === '' ? null : trim($xlinkHref),
            ];
        }

        $href = self::attribute($element, 'href');
        if ($href !== null) {
            return [
                'attribute' => 'href',
                'target' => trim($href) === '' ? null : trim($href),
            ];
        }

        return [
            'attribute' => null,
            'target' => null,
        ];
    }

    private static function jatsFigureMediaContentType(\DOMElement $element): ?string
    {
        $mimetype = self::attribute($element, 'mimetype');
        $subtype = self::attribute($element, 'mime-subtype');
        if ($mimetype === null || trim($mimetype) === '' || $subtype === null || trim($subtype) === '') {
            return null;
        }

        return strtolower(trim($mimetype)) . '/' . strtolower(trim($subtype));
    }

    /**
     * @return list<string>
     */
    private static function jatsFigureMediaIssues(?string $target): array
    {
        if ($target === null || trim($target) === '') {
            return ['missing-target'];
        }

        if (self::jatsFigureMediaTargetKind($target) === 'external') {
            return ['unsupported-external-reference'];
        }

        return [];
    }

    private static function jatsFigureMediaTargetKind(?string $target): string
    {
        if ($target === null || trim($target) === '') {
            return 'missing';
        }

        $target = trim($target);
        if (str_starts_with($target, '//') || preg_match('/^[A-Za-z][A-Za-z0-9+.-]*:/', $target) === 1) {
            return 'external';
        }

        if (str_starts_with($target, '#')) {
            return 'fragment';
        }

        return 'internal';
    }

    private static function jatsFigureMediaTargetBasename(?string $target): ?string
    {
        if ($target === null || trim($target) === '') {
            return null;
        }

        $target = trim($target);
        $cut = strcspn($target, '?#');
        $path = $cut === 0 ? $target : substr($target, 0, $cut);
        $path = str_replace('\\', '/', $path);
        $basename = basename($path);

        return $basename === '' || $basename === '.' ? null : $basename;
    }

    private static function jatsElementTextOrNull(?\DOMElement $element): ?string
    {
        if (!$element instanceof \DOMElement) {
            return null;
        }

        $text = self::normalizedText($element);

        return $text === '' ? null : $text;
    }

    private static function jatsFigureAltTextElement(\DOMElement $figure): ?\DOMElement
    {
        $altText = self::firstChildElement($figure, 'alt-text');
        if ($altText instanceof \DOMElement) {
            return $altText;
        }

        return self::firstDescendantElement($figure, 'alt-text');
    }

    /**
     * @return list<string>
     */
    private static function jatsFigureLocalMetadataIssueCodes(?string $captionText, ?string $title): array
    {
        $codes = [];
        if ($captionText === null || trim($captionText) === '') {
            $codes[] = 'missing-caption';
        }
        if ($title === null || trim($title) === '') {
            $codes[] = 'missing-title';
        }

        return $codes;
    }

    /**
     * @return list<string>
     */
    private static function jatsXrefTargetsInElement(\DOMElement $root): array
    {
        $targets = [];
        foreach (self::descendantElements($root, 'xref') as $xref) {
            $rid = self::attribute($xref, 'rid');
            if ($rid === null || trim($rid) === '') {
                continue;
            }

            foreach (self::spaceSeparatedTokens($rid) as $target) {
                $targets[] = $target;
            }
        }

        return array_values(array_unique($targets));
    }

    /**
     * @return array{element:string, path:string, parent:?string, childIndex:int, siblingIndex:int, sourceLine:int}
     */
    private static function jatsElementSourcePosition(\DOMElement $element, \DOMElement $scope): array
    {
        $parent = $element->parentNode instanceof \DOMElement ? $element->parentNode : null;

        return [
            'element' => $element->localName,
            'path' => self::jatsElementPathWithin($element, $scope),
            'parent' => $parent instanceof \DOMElement ? $parent->localName : null,
            'childIndex' => self::jatsElementChildIndex($element),
            'siblingIndex' => self::jatsElementSiblingIndex($element),
            'sourceLine' => max(0, $element->getLineNo()),
        ];
    }

    private static function jatsElementPathWithin(\DOMElement $element, \DOMElement $scope): string
    {
        $parts = [$element->localName];
        $node = $element->parentNode;
        while ($node instanceof \DOMElement) {
            array_unshift($parts, $node->localName);
            if ($node->isSameNode($scope)) {
                break;
            }
            $node = $node->parentNode;
        }

        return implode('/', $parts);
    }

    private static function jatsElementChildIndex(\DOMElement $element): int
    {
        $parent = $element->parentNode;
        if (!$parent instanceof \DOMNode) {
            return 0;
        }

        $index = 0;
        foreach ($parent->childNodes as $child) {
            if (!$child instanceof \DOMElement) {
                continue;
            }
            if ($child->isSameNode($element)) {
                return $index;
            }
            ++$index;
        }

        return 0;
    }

    private static function jatsElementSiblingIndex(\DOMElement $element): int
    {
        $parent = $element->parentNode;
        if (!$parent instanceof \DOMNode) {
            return 0;
        }

        $index = 0;
        foreach ($parent->childNodes as $child) {
            if (!$child instanceof \DOMElement || $child->localName !== $element->localName) {
                continue;
            }
            if ($child->isSameNode($element)) {
                return $index;
            }
            ++$index;
        }

        return 0;
    }

    /**
     * @param list<array<string, mixed>> $xrefs
     * @return list<array<string, mixed>>
     */
    private static function jatsTableWrapSummaries(\DOMElement $root, array $xrefs): array
    {
        $counts = self::jatsXrefCountsByTarget($xrefs);
        $tables = [];
        $ordinal = 1;
        foreach (self::descendantElements($root, 'table-wrap') as $tableWrap) {
            $id = self::attribute($tableWrap, 'id');
            $label = self::firstChildElement($tableWrap, 'label');
            $caption = self::firstChildElement($tableWrap, 'caption');
            $captionTitle = $caption instanceof \DOMElement ? self::firstChildElement($caption, 'title') : null;
            $captionParagraphs = $caption instanceof \DOMElement
                ? self::jatsNonEmptyTexts(self::childElements($caption, 'p'))
                : [];
            $captionText = $caption instanceof \DOMElement ? self::jatsElementReviewText($caption) : null;
            if ($captionText === '') {
                $captionText = null;
            }
            $labelText = $label instanceof \DOMElement ? self::normalizedText($label) : null;
            if ($labelText === '') {
                $labelText = null;
            }
            $captionTitleText = $captionTitle instanceof \DOMElement ? self::normalizedText($captionTitle) : null;
            if ($captionTitleText === '') {
                $captionTitleText = null;
            }
            $tableElements = self::descendantElements($tableWrap, 'table');
            $bodyRows = [];
            $bodyOrdinal = 1;
            $tbodyCount = 0;
            $theadRowCount = 0;

            foreach ($tableElements as $table) {
                foreach (self::descendantElements($table, 'thead') as $thead) {
                    $theadRowCount += count(self::childElements($thead, 'tr'));
                }

                foreach (self::descendantElements($table, 'tbody') as $tbody) {
                    ++$tbodyCount;
                    foreach (self::childElements($tbody, 'tr') as $row) {
                        $bodyRows[] = self::jatsTableBodyRowSummary($row, $bodyOrdinal++);
                    }
                }
            }

            $bodyCellCount = array_sum(array_map(static fn (array $row): int => (int) $row['cellCount'], $bodyRows));
            $bodyHeaderCellCount = array_sum(array_map(static fn (array $row): int => (int) $row['headerCellCount'], $bodyRows));
            $bodyDataCellCount = array_sum(array_map(static fn (array $row): int => (int) $row['dataCellCount'], $bodyRows));
            $diagnostics = [];
            if ($tbodyCount > 0) {
                $diagnostics[] = 'jats-bits-table-body-summary-review-only';
            }
            if ($tableElements !== [] && $tbodyCount === 0) {
                $diagnostics[] = 'jats-bits-table-wrap-missing-tbody';
            }
            if ($tbodyCount > 0 && $bodyRows === []) {
                $diagnostics[] = 'jats-bits-table-body-empty';
            }

            $tables[] = [
                'ordinal' => $ordinal++,
                'id' => $id,
                'label' => $labelText,
                'caption' => $captionText,
                'captionText' => $captionText,
                'captionTitle' => $captionTitleText,
                'captionParagraphs' => $captionParagraphs,
                'captionParagraphCount' => count($captionParagraphs),
                'attributes' => self::xmlAttributeMap($tableWrap),
                'tableCount' => count($tableElements),
                'theadRowCount' => $theadRowCount,
                'tbodyCount' => $tbodyCount,
                'rowCount' => count(self::descendantElements($tableWrap, 'tr')),
                'bodyRowCount' => count($bodyRows),
                'bodyCellCount' => $bodyCellCount,
                'bodyHeaderCellCount' => $bodyHeaderCellCount,
                'bodyDataCellCount' => $bodyDataCellCount,
                'bodyRows' => $bodyRows,
                'metadataDiagnostics' => self::jatsTableWrapMetadataDiagnostics($labelText, $captionText, $captionTitleText, $captionParagraphs),
                'diagnostics' => $diagnostics,
                'referenceCount' => $id === null ? 0 : ($counts[$id] ?? 0),
            ];
        }

        return $tables;
    }

    /**
     * @param list<\DOMElement> $elements
     * @return list<string>
     */
    private static function jatsNonEmptyTexts(array $elements): array
    {
        $texts = [];
        foreach ($elements as $element) {
            $text = self::normalizedText($element);
            if ($text !== '') {
                $texts[] = $text;
            }
        }

        return $texts;
    }

    private static function jatsElementReviewText(\DOMElement $element): string
    {
        $childTexts = self::jatsNonEmptyTexts(self::childElements($element));
        if ($childTexts !== []) {
            return implode(' ', $childTexts);
        }

        return self::normalizedText($element);
    }

    private static function jatsCompositeElementReviewText(\DOMElement $element): string
    {
        $childTexts = [];
        foreach (self::childElements($element) as $child) {
            $text = self::jatsElementReviewText($child);
            if ($text !== '') {
                $childTexts[] = $text;
            }
        }

        if ($childTexts !== []) {
            return implode(' ', $childTexts);
        }

        return self::normalizedText($element);
    }

    /**
     * @param list<string> $captionParagraphs
     * @return list<string>
     */
    private static function jatsTableWrapMetadataDiagnostics(
        ?string $labelText,
        ?string $captionText,
        ?string $titleText,
        array $captionParagraphs
    ): array {
        $diagnostics = [];
        $diagnostics[] = $labelText === null
            ? 'jats-bits-table-label-missing'
            : 'jats-bits-table-label-review-only';

        if ($captionText === null) {
            $diagnostics[] = 'jats-bits-table-caption-missing';

            return $diagnostics;
        }

        $diagnostics[] = 'jats-bits-table-caption-review-only';
        $diagnostics[] = $titleText === null
            ? 'jats-bits-table-caption-title-missing'
            : 'jats-bits-table-caption-title-review-only';

        if ($captionParagraphs !== []) {
            $diagnostics[] = 'jats-bits-table-caption-paragraphs-review-only';
        }

        return $diagnostics;
    }

    /**
     * @return array<string, mixed>
     */
    private static function jatsTableBodyRowSummary(\DOMElement $row, int $ordinal): array
    {
        $cells = [];
        $cellOrdinal = 1;
        foreach (self::childElements($row) as $cell) {
            if (!in_array($cell->localName, ['td', 'th'], true)) {
                continue;
            }

            $cells[] = self::jatsTableCellSummary($cell, $cellOrdinal++);
        }

        $diagnostics = [];
        if ($cells === []) {
            $diagnostics[] = 'jats-bits-table-body-row-without-cells';
        }

        return [
            'ordinal' => $ordinal,
            'id' => self::attribute($row, 'id'),
            'attributes' => self::xmlAttributeMap($row),
            'cellCount' => count($cells),
            'headerCellCount' => count(array_filter(
                $cells,
                static fn (array $cell): bool => $cell['name'] === 'th'
            )),
            'dataCellCount' => count(array_filter(
                $cells,
                static fn (array $cell): bool => $cell['name'] === 'td'
            )),
            'texts' => array_values(array_map(
                static fn (array $cell): string => (string) $cell['text'],
                $cells
            )),
            'cells' => $cells,
            'diagnostics' => $diagnostics,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function jatsTableCellSummary(\DOMElement $cell, int $ordinal): array
    {
        $headers = self::attribute($cell, 'headers');

        return [
            'ordinal' => $ordinal,
            'name' => $cell->localName,
            'id' => self::attribute($cell, 'id'),
            'attributes' => self::xmlAttributeMap($cell),
            'text' => self::normalizedText($cell),
            'rowspan' => self::jatsPositiveIntegerAttribute($cell, 'rowspan'),
            'colspan' => self::jatsPositiveIntegerAttribute($cell, 'colspan'),
            'align' => self::jatsTrimmedAttribute($cell, 'align'),
            'valign' => self::jatsTrimmedAttribute($cell, 'valign'),
            'scope' => self::jatsTrimmedAttribute($cell, 'scope'),
            'headers' => $headers === null ? [] : self::spaceSeparatedTokens($headers),
        ];
    }

    private static function jatsPositiveIntegerAttribute(\DOMElement $element, string $name): ?int
    {
        $value = self::attribute($element, $name);
        if ($value === null) {
            return null;
        }

        $value = trim($value);
        if ($value === '' || preg_match('/^\d+$/', $value) !== 1) {
            return null;
        }

        $integer = (int) $value;

        return $integer > 0 ? $integer : null;
    }

    private static function jatsTrimmedAttribute(\DOMElement $element, string $name): ?string
    {
        $value = self::attribute($element, $name);
        if ($value === null) {
            return null;
        }

        $value = trim($value);

        return $value === '' ? null : $value;
    }

    /**
     * @param list<array<string, mixed>> $tableWraps
     * @return list<string>
     */
    private static function jatsTableCaptionDiagnostics(array $tableWraps): array
    {
        $diagnostics = [];
        foreach ($tableWraps as $tableWrap) {
            foreach ($tableWrap['metadataDiagnostics'] as $diagnostic) {
                $diagnostics[] = (string) $diagnostic;
            }
        }

        return array_values(array_unique($diagnostics));
    }

    /**
     * @param list<array<string, mixed>> $tableWraps
     * @return list<string>
     */
    private static function jatsTableBodyDiagnostics(array $tableWraps): array
    {
        $diagnostics = [];
        foreach ($tableWraps as $tableWrap) {
            foreach ($tableWrap['diagnostics'] as $diagnostic) {
                $diagnostics[] = (string) $diagnostic;
            }

            if ((int) $tableWrap['bodyCellCount'] > 0) {
                $diagnostics[] = 'jats-bits-table-cell-summary-review-only';
            }

            foreach ($tableWrap['bodyRows'] as $row) {
                foreach ($row['diagnostics'] as $diagnostic) {
                    $diagnostics[] = (string) $diagnostic;
                }
            }
        }

        return array_values(array_unique($diagnostics));
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function jatsBookPartSummaries(\DOMElement $root): array
    {
        $bookParts = [];
        foreach (self::descendantElements($root, 'book-part') as $bookPart) {
            $body = self::jatsBodyElement($bookPart);
            $bookParts[] = [
                'id' => self::attribute($bookPart, 'id'),
                'type' => self::attribute($bookPart, 'book-part-type'),
                'title' => self::jatsFirstText($bookPart, ['title', 'book-title']),
                'bodyRoot' => $body instanceof \DOMElement ? $body->localName : null,
                'sectionCount' => $body instanceof \DOMElement ? count(self::jatsSectionSummaries($body)) : 0,
                'figureCount' => count(self::descendantElements($bookPart, 'fig')),
                'tableWrapCount' => count(self::descendantElements($bookPart, 'table-wrap')),
            ];
        }

        return $bookParts;
    }

    /**
     * @param list<array<string, mixed>> $sections
     * @param list<array<string, mixed>> $bodyXrefs
     * @param list<array<string, mixed>> $figures
     * @param list<array<string, mixed>> $tableWraps
     * @param list<array<string, mixed>> $bookParts
     * @return array<string, mixed>
     */
    private static function jatsBodySummary(
        ?\DOMElement $body,
        array $sections,
        array $bodyXrefs,
        array $figures,
        array $tableWraps,
        array $bookParts
    ): array {
        $sectionDepths = array_map(
            static fn (array $section): int => (int) $section['depth'],
            $sections
        );
        $sectionTypes = array_values(array_unique(array_filter(
            array_map(static fn (array $section): ?string => $section['type'], $sections),
            static fn (?string $type): bool => $type !== null && $type !== ''
        )));

        return [
            'bodyRoot' => $body instanceof \DOMElement ? $body->localName : null,
            'hasBody' => $body instanceof \DOMElement,
            'paragraphCount' => $body instanceof \DOMElement ? count(self::descendantElements($body, 'p')) : 0,
            'sectionCount' => count($sections),
            'sectionDepthMax' => $sectionDepths === [] ? 0 : max($sectionDepths),
            'sectionTypes' => $sectionTypes,
            'xrefCount' => count($bodyXrefs),
            'resolvedXrefCount' => count(self::jatsResolvedXrefTargets($bodyXrefs)),
            'unresolvedXrefCount' => count(self::jatsUnresolvedXrefTargets($bodyXrefs)),
            'unresolvedXrefTargets' => self::jatsUnresolvedXrefTargets($bodyXrefs),
            'figureCount' => count($figures),
            'figureReferenceTargets' => self::jatsReferenceTargetsForElements($bodyXrefs, ['fig']),
            'tableWrapCount' => count($tableWraps),
            'tableWrapReferenceTargets' => self::jatsReferenceTargetsForElements($bodyXrefs, ['table-wrap', 'table']),
            'bookPartCount' => count($bookParts),
        ];
    }

    private static function jatsFirstChildText(\DOMElement $root, string $localName): ?string
    {
        $child = self::firstChildElement($root, $localName);
        if (!$child instanceof \DOMElement) {
            return null;
        }

        $text = self::normalizedText($child);

        return $text === '' ? null : $text;
    }

    private static function jatsCaptionText(\DOMElement $root): ?string
    {
        $caption = self::firstDescendantElement($root, 'caption');
        if (!$caption instanceof \DOMElement) {
            return null;
        }

        $text = self::normalizedText($caption);

        return $text === '' ? null : $text;
    }

    /**
     * @return list<string>
     */
    private static function jatsGraphicHrefs(\DOMElement $root): array
    {
        $hrefs = [];
        foreach (['graphic', 'inline-graphic'] as $localName) {
            foreach (self::descendantElements($root, $localName) as $graphic) {
                $href = self::attribute($graphic, 'href', 'http://www.w3.org/1999/xlink')
                    ?? self::attribute($graphic, 'href');
                if ($href !== null && trim($href) !== '') {
                    $hrefs[] = trim($href);
                }
            }
        }

        return array_values(array_unique($hrefs));
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function docBookSectionSummaries(\DOMElement $root): array
    {
        $sections = [];
        foreach (self::docBookSectionElements($root) as $section) {
            $sections[] = [
                'element' => strtolower($section->localName),
                'id' => self::docBookElementId($section),
                'xmlId' => self::normalizedAttribute($section, 'id', self::XML_NAMESPACE),
                'label' => self::normalizedAttribute($section, 'label'),
                'role' => self::normalizedAttribute($section, 'role'),
                'language' => self::normalizedAttribute($section, 'lang', self::XML_NAMESPACE)
                    ?? self::normalizedAttribute($section, 'lang'),
                'title' => self::docBookSectionMetadataTitleText($section),
                'titleSource' => self::docBookTitleSource($section),
                'subtitle' => self::docBookSectionMetadataSubtitleText($section),
                'level' => self::docBookSectionLevel($section),
                'paragraphCount' => self::docBookDirectTextBlockCount($section),
                'childSectionCount' => self::docBookDirectChildSectionCount($section),
            ];
        }

        return $sections;
    }

    /**
     * @return list<\DOMElement>
     */
    private static function docBookSectionElements(\DOMElement $root): array
    {
        $sections = [];
        if (self::isDocBookSectionElement($root)) {
            $sections[] = $root;
        }

        foreach (self::descendantElements($root) as $element) {
            if (self::isDocBookSectionElement($element)) {
                $sections[] = $element;
            }
        }

        return $sections;
    }

    private static function isDocBookSectionElement(\DOMElement $element): bool
    {
        return isset(self::DOCBOOK_SECTION_ELEMENTS[strtolower($element->localName)]);
    }

    private static function docBookSectionMetadataTitleText(\DOMElement $element): ?string
    {
        return self::docBookTitleLikeText($element, 'title');
    }

    private static function docBookSectionMetadataSubtitleText(\DOMElement $element): ?string
    {
        return self::docBookTitleLikeText($element, 'subtitle');
    }

    private static function docBookTitleLikeText(\DOMElement $element, string $name): ?string
    {
        $direct = self::firstChildElement($element, $name);
        if ($direct instanceof \DOMElement) {
            $text = self::normalizedText($direct);
            if ($text !== '') {
                return $text;
            }
        }

        $info = self::firstChildElement($element, 'info');
        $infoTitle = $info instanceof \DOMElement ? self::firstChildElement($info, $name) : null;
        if ($infoTitle instanceof \DOMElement) {
            $text = self::normalizedText($infoTitle);
            if ($text !== '') {
                return $text;
            }
        }

        return null;
    }

    private static function docBookTitleSource(\DOMElement $element): ?string
    {
        $direct = self::firstChildElement($element, 'title');
        if ($direct instanceof \DOMElement && self::normalizedText($direct) !== '') {
            return 'direct-title';
        }

        $info = self::firstChildElement($element, 'info');
        $infoTitle = $info instanceof \DOMElement ? self::firstChildElement($info, 'title') : null;
        if ($infoTitle instanceof \DOMElement && self::normalizedText($infoTitle) !== '') {
            return 'info-title';
        }

        return null;
    }

    private static function docBookSectionMetadataElementId(\DOMElement $element): ?string
    {
        return self::normalizedAttribute($element, 'id', self::XML_NAMESPACE)
            ?? self::normalizedAttribute($element, 'id');
    }

    private static function normalizedAttribute(\DOMElement $element, string $localName, ?string $namespace = null): ?string
    {
        $value = self::attribute($element, $localName, $namespace);
        if ($value === null) {
            return null;
        }

        $value = trim($value);

        return $value === '' ? null : $value;
    }

    private static function stringOrNull(mixed $value): ?string
    {
        return is_string($value) && $value !== '' ? $value : null;
    }

    private static function docBookSectionLevel(\DOMElement $section): int
    {
        if (preg_match('/^sect([1-5])$/', strtolower($section->localName), $matches) === 1) {
            return (int) $matches[1];
        }

        $level = 1;
        $parent = $section->parentNode;
        while ($parent instanceof \DOMElement) {
            if (self::isDocBookSectionElement($parent)) {
                $level++;
            }
            $parent = $parent->parentNode;
        }

        return $level;
    }

    /**
     * @param list<array<string, mixed>> $sections
     * @return array<string, list<array<string, mixed>>>
     */
    private static function docBookSectionTargetIndex(array $sections): array
    {
        $index = [];
        foreach ($sections as $sectionIndex => $section) {
            $id = $section['id'] ?? null;
            if (!is_string($id) || $id === '') {
                continue;
            }

            $index[$id][] = [
                'sectionIndex' => $sectionIndex,
                'element' => $section['element'] ?? null,
                'title' => $section['title'] ?? null,
            ];
        }

        return $index;
    }

    /**
     * @param array<string, list<array<string, mixed>>> $sectionTargets
     * @return list<array<string, mixed>>
     */
    private static function docBookXrefLinkTargets(\DOMElement $root, array $sectionTargets): array
    {
        $targets = [];
        foreach (self::descendantElements($root) as $element) {
            $name = strtolower($element->localName);
            if (!isset(self::DOCBOOK_XREF_LINK_ELEMENTS[$name])) {
                continue;
            }

            foreach (self::docBookXrefLinkRawTargets($element) as $rawTarget) {
                foreach (self::docBookXrefLinkTargetRecords($element, $rawTarget, $sectionTargets) as $record) {
                    $targets[] = $record;
                }
            }
        }

        return $targets;
    }

    /**
     * @return list<array{attribute:string, rawTarget:string, target:?string, unsafeReason:?string}>
     */
    private static function docBookXrefLinkRawTargets(\DOMElement $element): array
    {
        $targets = [];

        foreach (['linkend', 'linkends'] as $attribute) {
            $raw = self::normalizedAttribute($element, $attribute);
            if ($raw === null) {
                continue;
            }

            $tokens = $attribute === 'linkends' ? self::spaceSeparatedTokens($raw) : [$raw];
            foreach ($tokens as $token) {
                $targets[] = [
                    'attribute' => $attribute,
                    'rawTarget' => $raw,
                    'target' => $token,
                    'unsafeReason' => self::docBookUnsafeIdTargetReason($token),
                ];
            }
        }

        foreach ([[self::XLINK_NAMESPACE, 'xlink:href'], [null, 'href']] as [$namespace, $attribute]) {
            $raw = $namespace === null
                ? self::normalizedAttribute($element, 'href')
                : self::normalizedAttribute($element, 'href', $namespace);
            if ($raw === null) {
                continue;
            }

            $hrefTarget = self::docBookHrefTarget($raw);
            $targets[] = [
                'attribute' => $attribute,
                'rawTarget' => $raw,
                'target' => $hrefTarget['target'],
                'unsafeReason' => $hrefTarget['unsafeReason'],
            ];
        }

        return $targets;
    }

    /**
     * @return array{target:?string, unsafeReason:?string}
     */
    private static function docBookHrefTarget(string $href): array
    {
        $href = trim($href);
        if ($href === '') {
            return ['target' => null, 'unsafeReason' => 'empty-href'];
        }

        if (preg_match('/[\x00-\x1F\x7F]/', $href) === 1) {
            return ['target' => null, 'unsafeReason' => 'control-byte-href'];
        }

        if (!str_starts_with($href, '#')) {
            return ['target' => null, 'unsafeReason' => 'non-local-href'];
        }

        $target = substr($href, 1);
        if ($target === '') {
            return ['target' => null, 'unsafeReason' => 'empty-fragment'];
        }

        return ['target' => $target, 'unsafeReason' => self::docBookUnsafeIdTargetReason($target)];
    }

    private static function docBookUnsafeIdTargetReason(string $target): ?string
    {
        if ($target === '') {
            return 'empty-target';
        }

        if (preg_match('/[\x00-\x1F\x7F\s\/?#]/', $target) === 1) {
            return 'unsafe-target-token';
        }

        return null;
    }

    /**
     * @param array{attribute:string, rawTarget:string, target:?string, unsafeReason:?string} $rawTarget
     * @param array<string, list<array<string, mixed>>> $sectionTargets
     * @return list<array<string, mixed>>
     */
    private static function docBookXrefLinkTargetRecords(\DOMElement $element, array $rawTarget, array $sectionTargets): array
    {
        $target = $rawTarget['target'];
        $locations = is_string($target) && isset($sectionTargets[$target]) ? $sectionTargets[$target] : [];
        $status = self::docBookXrefLinkTargetStatus($target, $rawTarget['unsafeReason'], $locations);
        $diagnostics = self::docBookXrefLinkTargetDiagnosticCodes($status);
        $text = self::normalizedText($element);

        return [[
            'element' => strtolower($element->localName),
            'attribute' => $rawTarget['attribute'],
            'rawTarget' => $rawTarget['rawTarget'],
            'target' => $target,
            'text' => $text !== '' ? $text : null,
            'status' => $status,
            'unsafeReason' => $rawTarget['unsafeReason'],
            'targetSectionIndexes' => array_map(
                static fn (array $location): int => (int) ($location['sectionIndex'] ?? 0),
                $locations
            ),
            'targetSectionTitles' => array_values(array_filter(
                array_map(static fn (array $location): ?string => $location['title'] ?? null, $locations),
                static fn (?string $title): bool => $title !== null && $title !== ''
            )),
            'diagnostics' => $diagnostics,
        ]];
    }

    /**
     * @param list<array<string, mixed>> $locations
     */
    private static function docBookXrefLinkTargetStatus(?string $target, ?string $unsafeReason, array $locations): string
    {
        if ($unsafeReason !== null) {
            return 'unsafe-target';
        }

        if ($target === null || $locations === []) {
            return 'missing-anchor';
        }

        return count($locations) > 1 ? 'duplicate-section-id' : 'resolved-section';
    }

    /**
     * @return list<string>
     */
    private static function docBookXrefLinkTargetDiagnosticCodes(string $status): array
    {
        return match ($status) {
            'duplicate-section-id' => ['docbook-xref-target-duplicate-section-id'],
            'missing-anchor' => ['docbook-xref-target-missing-anchor'],
            'unsafe-target' => ['docbook-xref-target-unsafe'],
            default => [],
        };
    }

    /**
     * @param list<array<string, mixed>> $targets
     * @return array<string, int>
     */
    private static function docBookXrefLinkTargetStatusCounts(array $targets): array
    {
        $counts = [];
        foreach ($targets as $target) {
            $status = $target['status'] ?? null;
            if (!is_string($status) || $status === '') {
                continue;
            }

            $counts[$status] = ($counts[$status] ?? 0) + 1;
        }

        return $counts;
    }

    private static function docBookDirectTextBlockCount(\DOMElement $section): int
    {
        $count = 0;
        foreach (self::childElements($section) as $child) {
            if (in_array(strtolower($child->localName), ['para', 'simpara'], true)) {
                $count++;
            }
        }

        return $count;
    }

    private static function docBookDirectChildSectionCount(\DOMElement $section): int
    {
        $count = 0;
        foreach (self::childElements($section) as $child) {
            if (self::isDocBookSectionElement($child)) {
                $count++;
            }
        }

        return $count;
    }

    /**
     * @param list<array<string, mixed>> $sections
     * @return list<array<string, mixed>>
     */
    private static function docBookSectionDiagnostics(array $sections): array
    {
        $diagnostics = [];
        $ids = [];

        foreach ($sections as $index => $section) {
            $id = $section['id'] ?? null;
            $title = $section['title'] ?? null;
            if ($title === null || $title === '') {
                $diagnostics[] = [
                    'code' => 'docbook-section-missing-title',
                    'sectionIndex' => $index,
                    'sectionId' => is_string($id) && $id !== '' ? $id : null,
                    'element' => $section['element'] ?? null,
                ];
            }

            if (!is_string($id) || $id === '') {
                continue;
            }

            if (isset($ids[$id])) {
                $diagnostics[] = [
                    'code' => 'docbook-section-duplicate-id',
                    'sectionIndex' => $index,
                    'sectionId' => $id,
                    'firstSectionIndex' => $ids[$id],
                    'element' => $section['element'] ?? null,
                ];
                continue;
            }

            $ids[$id] = $index;
        }

        return $diagnostics;
    }

    /**
     * @param list<array<string, mixed>> $targets
     * @return list<array<string, mixed>>
     */
    private static function docBookXrefLinkDiagnostics(array $targets): array
    {
        $diagnostics = [];
        foreach ($targets as $index => $target) {
            foreach ($target['diagnostics'] ?? [] as $code) {
                if (!is_string($code) || $code === '') {
                    continue;
                }

                $diagnostic = [
                    'code' => $code,
                    'targetIndex' => $index,
                    'element' => $target['element'] ?? null,
                    'attribute' => $target['attribute'] ?? null,
                    'target' => $target['target'] ?? null,
                    'rawTarget' => $target['rawTarget'] ?? null,
                    'status' => $target['status'] ?? null,
                ];
                if (($target['unsafeReason'] ?? null) !== null) {
                    $diagnostic['unsafeReason'] = $target['unsafeReason'];
                }
                if (($target['targetSectionIndexes'] ?? []) !== []) {
                    $diagnostic['targetSectionIndexes'] = $target['targetSectionIndexes'];
                }
                $diagnostics[] = $diagnostic;
            }
        }

        return $diagnostics;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function summarizeChildNodes(\DOMNode $parent): array
    {
        $summary = [];
        foreach ($parent->childNodes as $child) {
            array_push($summary, ...self::summarizeNode($child));
        }

        return self::shouldRepairOrphanHtmlTableChildren($parent)
            ? self::wrapOrphanHtmlTableSummary($summary)
            : $summary;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function summarizeNode(\DOMNode $node): array
    {
        if ($node instanceof \DOMText) {
            $text = $node->nodeValue ?? '';

            return $text === '' ? [] : [['type' => 'text', 'text' => $text]];
        }

        if ($node instanceof \DOMComment) {
            return [['type' => 'comment', 'text' => $node->nodeValue ?? '']];
        }

        if (!$node instanceof \DOMElement) {
            return [];
        }

        $name = self::htmlElementName($node);
        if (self::isHtmlTableModelContext($name)) {
            [$fostered, $summary] = self::summarizeTableElementParts($node, $name);

            return [...$fostered, $summary];
        }

        $children = self::summarizeChildNodes($node);
        $summary = [
            'type' => 'element',
            'name' => $name,
            'attributes' => self::htmlAttributes($node),
            'text' => self::normalizedText($node),
            'children' => $children,
        ];
        $summary += self::customElementTagSummary($name);
        $summary += self::globalHtmlAttributeSummary($node);

        if ($name === 'form') {
            $summary += self::formSubmissionSummary($node);
        }
        if ($name === 'label') {
            $summary += self::labelSummary($node);
        }
        if (in_array($name, ['ol', 'ul', 'menu', 'li'], true)) {
            $summary += self::listSummary($node, $name);
        }
        if (in_array($name, ['dl', 'dt', 'dd'], true)) {
            $summary += self::definitionListSummary($node, $name);
        }
        if (self::isHtmlHeadingElementName($name)) {
            $summary += self::headingSummary($node, $name);
        }
        if ($name === 'hgroup') {
            $summary += self::headingGroupSummary($node);
        }
        if ($name === 'slot') {
            $summary += self::slotElementSummary($node);
        }
        if (self::isHtmlOutlineElementName($name)) {
            $summary += self::outlineSummary($node, $name);
        }
        if ($name === 'search') {
            $summary += self::searchSummary($node);
        }
        if ($name === 'address') {
            $summary += self::addressSummary($node);
        }
        if ($name === 'slot') {
            $summary += self::slotElementSummary($node);
        }
        if (in_array($name, ['caption', 'col', 'td', 'th'], true)) {
            $summary += self::tableElementSummary($node, $name);
        }
        if ($name === 'figure' || $name === 'figcaption') {
            $summary += self::figureSummary($node, $name);
        }
        if ($name === 'select') {
            $options = self::selectOptionSummaries($node);
            $summary['formControl'] = 'select';
            $summary += self::formOwnerSummary($node);
            $summary['labels'] = self::formControlLabels($node);
            $summary['disabled'] = $node->hasAttribute('disabled');
            $summary['effectiveDisabled'] = self::isEffectivelyDisabledFormControl($node);
            $summary['required'] = $node->hasAttribute('required');
            $summary += self::formControlConstraintSummary($node, $name);
            $summary['selectOptions'] = $options;
            $summary['selectedValues'] = array_values(array_map(
                static fn (array $option): string => (string) $option['value'],
                array_filter($options, static fn (array $option): bool => (bool) ($option['selected'] ?? false))
            ));
        }
        if ($name === 'input') {
            $inputType = self::inputTypeSummary($node);
            $summary['formControl'] = 'input';
            $summary += self::formOwnerSummary($node);
            $summary += $inputType;
            $summary['labels'] = self::formControlLabels($node);
            $summary['value'] = $node->getAttribute('value');
            $summary['checked'] = $node->hasAttribute('checked');
            $summary['disabled'] = $node->hasAttribute('disabled');
            $summary['effectiveDisabled'] = self::isEffectivelyDisabledFormControl($node);
            $summary['required'] = $node->hasAttribute('required');
            $summary += self::formControlConstraintSummary($node, $name);
            if ($inputType['inputType'] === 'file' || $node->hasAttribute('accept') || $node->hasAttribute('capture')) {
                $summary += self::fileInputReviewSummary($node, $inputType['inputType']);
            }
            if ($node->hasAttribute('placeholder')) {
                $summary['placeholder'] = $node->getAttribute('placeholder');
            }
            if ($node->hasAttribute('list')) {
                $summary['list'] = $node->getAttribute('list');
                $summary += self::datalistAssociationSummary($node, $node->getAttribute('list'));
            }
            if (self::isInputSubmitterType($inputType['inputType'])) {
                $summary['submitter'] = self::formSubmitterSummary($node);
                $summary += self::formSubmitterActionReviewSummary($node);
            }
            if ($inputType['inputType'] === 'reset') {
                $summary += self::formResetControlSummary($node);
            }
        }
        if ($name === 'textarea') {
            $summary['formControl'] = 'textarea';
            $summary += self::formOwnerSummary($node);
            $summary['labels'] = self::formControlLabels($node);
            $summary['value'] = $node->textContent;
            $summary['disabled'] = $node->hasAttribute('disabled');
            $summary['effectiveDisabled'] = self::isEffectivelyDisabledFormControl($node);
            $summary['readonly'] = $node->hasAttribute('readonly');
            $summary['required'] = $node->hasAttribute('required');
            $summary += self::formControlConstraintSummary($node, $name);
            if ($node->hasAttribute('placeholder')) {
                $summary['placeholder'] = $node->getAttribute('placeholder');
            }
        }
        if ($name === 'button') {
            $buttonType = self::buttonTypeSummary($node);
            $summary['formControl'] = 'button';
            $summary += self::formOwnerSummary($node);
            $summary += $buttonType;
            $summary['labels'] = self::formControlLabels($node);
            $summary['value'] = $node->getAttribute('value');
            $summary['label'] = self::normalizedText($node);
            $summary['disabled'] = $node->hasAttribute('disabled');
            $summary['effectiveDisabled'] = self::isEffectivelyDisabledFormControl($node);
            $summary += self::buttonCommandSummary($node);
            if ($buttonType['buttonSubmitButton']) {
                $summary['submitter'] = self::formSubmitterSummary($node);
                $summary += self::formSubmitterActionReviewSummary($node);
            }
            if ($buttonType['buttonType'] === 'reset') {
                $summary += self::formResetControlSummary($node);
            }
        }
        if ($name === 'output') {
            $forRaw = $node->hasAttribute('for') ? $node->getAttribute('for') : null;
            $summary['formControl'] = 'output';
            $summary += self::formOwnerSummary($node);
            $summary['labels'] = self::formControlLabels($node);
            $summary['value'] = $node->textContent;
            $summary['forRaw'] = $forRaw;
            $summary['forIds'] = $forRaw === null ? [] : self::spaceSeparatedTokens($forRaw);
            if ($forRaw !== null) {
                $summary += self::outputForReferenceSummary($node, $forRaw);
            }
        }
        if ($name === 'datalist') {
            $summary['formControl'] = 'datalist';
            $summary['datalistOptions'] = self::datalistOptionSummaries($node);
        }
        if ($name === 'optgroup') {
            $summary += self::optgroupSummary($node);
        }
        if ($name === 'option') {
            $summary += self::optionSummary($node);
        }
        if ($name === 'selectedcontent') {
            $summary += self::selectedContentSummary($node);
        }
        if ($name === 'fieldset') {
            $summary += self::fieldsetSummary($node);
        }
        if ($name === 'legend') {
            $summary += self::legendSummary($node);
        }
        if ($name === 'details') {
            $summary += self::detailsDisclosureSummary($node);
        }
        if ($name === 'dialog') {
            $summary['dialog'] = 'dialog';
            $summary['dialogOpen'] = $node->hasAttribute('open');
            $summary['dialogText'] = self::normalizedText($node);
        }
        if ($name === 'summary') {
            $summary += self::summaryDisclosureSummary($node);
        }
        if ($name === 'dialog') {
            $summary += self::dialogSummary($node);
        }
        if ($name === 'ins' || $name === 'del') {
            $summary += self::revisionSummary($node, $name);
        }
        if (in_array($name, ['blockquote', 'q', 'cite'], true)) {
            $summary += self::quoteSummary($node, $name);
        }
        if ($name === 'progress') {
            $summary += self::progressMeasurementSummary($node, includeLabels: true);
        }
        if ($name === 'meter') {
            $summary += self::meterMeasurementSummary($node, includeLabels: true);
        }
        if (in_array($name, ['picture', 'img', 'audio', 'video', 'source', 'track', 'iframe', 'embed', 'object', 'param', 'canvas'], true)) {
            $summary += self::embeddedResourceSummary($node, $name);
        }
        if (self::isDocBookMediaElementName($name)) {
            $summary += self::docBookMediaSummary($node, $name);
        }
        if (in_array($name, ['a', 'area'], true)) {
            $summary += self::hyperlinkSummary($node, $name);
        }
        if ($name === 'map') {
            $summary += self::imageMapSummary($node);
        }
        if (in_array($name, ['base', 'link', 'meta'], true)) {
            $summary += self::documentMetadataSummary($node, $name);
        }
        if (in_array($name, ['script', 'style'], true)) {
            $summary += self::activeContentSummary($node, $name);
        }
        if ($name === 'template') {
            $summary += self::templateSummary($node);
            if (self::isDeclarativeShadowRootTemplate($node)) {
                $summary += self::templateShadowRootSummary($node);
            }
        }
        if ($name === 'slot') {
            $summary += self::slotSummary($node);
        }
        if ($name === 'slot') {
            $summary += self::slotElementSummary($node);
        }
        if ($name === 'noscript') {
            $summary += self::noscriptSummary($node);
        }
        if ($name === 'time') {
            $summary += self::timeSummary($node);
        }
        if ($name === 'data') {
            $summary += self::dataElementSummary($node);
        }
        if ($name === 'pre') {
            $summary += self::preformattedBlockSummary($node);
            $summary += self::preformattedSummary($node);
        }
        if (in_array($name, ['ruby', 'rb', 'rt', 'rp', 'rtc'], true)) {
            $summary += self::rubySummary($node, $name);
        }
        if (in_array($name, ['abbr', 'b', 'bdi', 'bdo', 'code', 'dfn', 'em', 'i', 'kbd', 'mark', 's', 'samp', 'small', 'strong', 'sub', 'sup', 'u', 'var'], true)) {
            $summary += self::textSemanticSummary($node, $name);
        }
        if (in_array($name, ['br', 'hr', 'wbr'], true)) {
            $summary += self::breakElementSummary($name);
        }

        return [$summary];
    }

    /**
     * @return array{documentOutline:string, heading:bool, headingTag:string, headingLevel:int, headingText:string}
     */
    private static function headingSummary(\DOMElement $element, string $name): array
    {
        return [
            'documentOutline' => 'heading',
            'heading' => true,
            'headingTag' => $name,
            'headingLevel' => self::htmlHeadingLevel($name),
            'headingText' => self::normalizedText($element),
        ];
    }

    /**
     * @return array{documentOutline:string, outlineRoot:string, sectionHeadingText:?string, sectionHeadingTag:?string, sectionHeadingLevel:?int}
     */
    private static function outlineSummary(\DOMElement $element, string $name): array
    {
        $heading = self::firstScopedHeadingElement($element);
        $headingName = $heading instanceof \DOMElement ? self::htmlElementName($heading) : null;

        return [
            'documentOutline' => match ($name) {
                'nav' => 'navigation',
                default => $name,
            },
            'outlineRoot' => $name,
            'sectionHeadingText' => $heading instanceof \DOMElement ? self::normalizedText($heading) : null,
            'sectionHeadingTag' => $headingName,
            'sectionHeadingLevel' => $headingName === null ? null : self::htmlHeadingLevel($headingName),
        ];
    }

    private static function isHtmlHeadingElementName(string $name): bool
    {
        return in_array($name, ['h1', 'h2', 'h3', 'h4', 'h5', 'h6'], true);
    }

    private static function htmlHeadingLevel(string $name): int
    {
        return (int) substr($name, 1);
    }

    /**
     * @return array<string, mixed>
     */
    private static function headingGroupSummary(\DOMElement $element): array
    {
        $headings = [];
        foreach (self::htmlHeadingGroupHeadingElements($element) as $heading) {
            $name = self::htmlElementName($heading);
            $headings[] = [
                'tag' => $name,
                'level' => self::htmlHeadingLevel($name),
                'text' => self::normalizedText($heading),
            ];
        }

        $mainHeading = self::htmlHeadingGroupMainHeadingElement($element);
        $mainHeadingName = $mainHeading instanceof \DOMElement ? self::htmlElementName($mainHeading) : null;
        $subtitleTexts = self::htmlHeadingGroupSubtitleTexts($element);

        return [
            'documentOutline' => 'heading-group',
            'headingGroup' => 'hgroup',
            'headingGroupText' => self::normalizedText($element),
            'headingGroupHeadingText' => $mainHeading instanceof \DOMElement ? self::normalizedText($mainHeading) : null,
            'headingGroupHeadingTag' => $mainHeadingName,
            'headingGroupHeadingLevel' => $mainHeadingName === null ? null : self::htmlHeadingLevel($mainHeadingName),
            'headingGroupHeadingCount' => count($headings),
            'headingGroupHeadingTexts' => array_values(array_map(
                static fn (array $heading): string => (string) $heading['text'],
                $headings
            )),
            'headingGroupHeadings' => $headings,
            'headingGroupSubtitleCount' => count($subtitleTexts),
            'headingGroupSubtitleTexts' => $subtitleTexts,
        ];
    }

    /**
     * @return list<\DOMElement>
     */
    private static function htmlHeadingGroupHeadingElements(\DOMElement $element): array
    {
        $headings = [];
        foreach (self::childElements($element) as $child) {
            if (self::isHtmlHeadingElementName(self::htmlElementName($child))) {
                $headings[] = $child;
            }
        }

        return $headings;
    }

    private static function htmlHeadingGroupMainHeadingElement(\DOMElement $element): ?\DOMElement
    {
        $mainHeading = null;
        $mainLevel = PHP_INT_MAX;
        foreach (self::htmlHeadingGroupHeadingElements($element) as $heading) {
            $level = self::htmlHeadingLevel(self::htmlElementName($heading));
            if ($level < $mainLevel) {
                $mainHeading = $heading;
                $mainLevel = $level;
            }
        }

        return $mainHeading;
    }

    /**
     * @return list<string>
     */
    private static function htmlHeadingGroupSubtitleTexts(\DOMElement $element): array
    {
        $subtitles = [];
        foreach (self::childElements($element, 'p') as $paragraph) {
            $text = self::normalizedText($paragraph);
            if ($text !== '') {
                $subtitles[] = $text;
            }
        }

        return $subtitles;
    }

    private static function isHtmlOutlineElementName(string $name): bool
    {
        return in_array($name, ['article', 'aside', 'main', 'nav', 'section'], true);
    }

    /**
     * @return array<string, mixed>
     */
    private static function searchSummary(\DOMElement $search): array
    {
        $forms = [];
        foreach (self::descendantHtmlElements($search, 'form') as $form) {
            $forms[] = [
                'id' => self::attributeOrNull($form, 'id'),
                'action' => self::attributeOrNull($form, 'action'),
                'method' => self::formMethod($form, 'method', 'get'),
                'role' => self::attributeOrNull($form, 'role'),
                'controls' => self::searchControlSummaries($form),
            ];
        }

        return [
            'landmark' => 'search',
            'searchRegion' => 'search',
            'searchText' => self::normalizedText($search),
            'searchFormCount' => count($forms),
            'searchForms' => $forms,
            'searchControls' => self::searchControlSummaries($search),
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function searchControlSummaries(\DOMElement $root): array
    {
        $controls = [];
        foreach ($root->getElementsByTagName('*') as $control) {
            if (!$control instanceof \DOMElement) {
                continue;
            }

            $name = self::htmlElementName($control);
            if (!in_array($name, ['button', 'input', 'select', 'textarea'], true)) {
                continue;
            }

            $summary = [
                'control' => $name,
                'id' => self::attributeOrNull($control, 'id'),
                'controlName' => self::attributeOrNull($control, 'name'),
                'label' => self::formControlLabels($control),
            ];
            if ($name === 'input') {
                $summary['type'] = self::inputType($control);
                $summary['value'] = self::attributeOrNull($control, 'value');
            }
            if ($name === 'button') {
                $summary['type'] = self::buttonType($control);
                $summary['value'] = self::attributeOrNull($control, 'value');
                $summary['text'] = self::normalizedText($control);
            }

            $controls[] = $summary;
        }

        return $controls;
    }

    /**
     * @return array<string, mixed>
     */
    private static function addressSummary(\DOMElement $address): array
    {
        $links = [];
        foreach (self::descendantHtmlElements($address, 'a') as $link) {
            $relRaw = self::attributeOrNull($link, 'rel');
            $links[] = [
                'href' => self::attributeOrNull($link, 'href'),
                'label' => self::normalizedText($link),
                'relRaw' => $relRaw,
                'relTokens' => $relRaw === null ? [] : self::spaceSeparatedTokens($relRaw),
            ];
        }

        return [
            'contactInfo' => 'address',
            'contactText' => self::normalizedText($address),
            'contactLinkCount' => count($links),
            'contactLinks' => $links,
            'contactHrefs' => array_values(array_filter(
                array_map(static fn (array $link): ?string => $link['href'], $links),
                static fn (?string $href): bool => $href !== null
            )),
            'contactEmailHrefs' => array_values(array_filter(
                array_map(static fn (array $link): ?string => $link['href'], $links),
                static fn (?string $href): bool => $href !== null && str_starts_with(strtolower($href), 'mailto:')
            )),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function slotElementSummary(\DOMElement $slot): array
    {
        $nameRaw = self::attributeOrNull($slot, 'name');
        $name = $nameRaw === null ? '' : trim($nameRaw);
        $defaultSlot = $name === '';
        $nameValid = $defaultSlot || self::isHtmlReferenceToken($name);
        $fallbackText = self::normalizedText($slot);
        $assignedElements = $nameValid ? self::slotAssignedElementSummaries($slot, $name) : [];
        $scope = $slot->parentNode instanceof \DOMElement ? $slot->parentNode : null;
        $topLevelElementNames = [];
        foreach ($slot->childNodes as $child) {
            if ($child instanceof \DOMElement) {
                $topLevelElementNames[] = self::htmlElementName($child);
            }
        }

        $descendantElementNames = [];
        foreach ($slot->getElementsByTagName('*') as $descendant) {
            if ($descendant instanceof \DOMElement) {
                $descendantElementNames[] = self::htmlElementName($descendant);
            }
        }

        $fallbackControls = [];
        foreach (['button', 'input', 'output', 'select', 'textarea'] as $controlName) {
            foreach (self::descendantHtmlElements($slot, $controlName) as $control) {
                $fallbackControls[] = [
                    'control' => $controlName,
                    'id' => self::attributeOrNull($control, 'id'),
                    'controlName' => self::attributeOrNull($control, 'name'),
                    'text' => self::normalizedText($control),
                    'value' => self::attributeOrNull($control, 'value'),
                ];
            }
        }

        $issues = [];
        if (!$nameValid) {
            $issues[] = [
                'code' => 'invalid-slot-name',
                'slotNameRaw' => $nameRaw,
            ];
        }

        return [
            'slotElement' => 'slot',
            'slotNameRaw' => $nameRaw,
            'slotName' => $name,
            'slotDefault' => $defaultSlot,
            'slotNameValid' => $nameValid,
            'slotReviewPolicy' => 'flat-parent-slot-assignment-review',
            'slotElementNameRaw' => $nameRaw,
            'slotElementName' => $name,
            'slotElementNameValid' => $nameValid,
            'slotAssignmentScope' => $scope instanceof \DOMElement ? self::htmlElementName($scope) : null,
            'slotAssignmentScopeId' => $scope instanceof \DOMElement ? self::attributeOrNull($scope, 'id') : null,
            'slotAssignedElementCount' => count($assignedElements),
            'slotAssignedElementNames' => array_values(array_map(
                static fn (array $element): string => (string) $element['tag'],
                $assignedElements
            )),
            'slotAssignedElementIds' => array_values(array_filter(
                array_map(static fn (array $element): ?string => $element['id'] ?? null, $assignedElements),
                static fn (?string $id): bool => $id !== null && $id !== ''
            )),
            'slotAssignedElements' => $assignedElements,
            'slotHasAssignments' => $assignedElements !== [],
            'slotFallbackReviewPolicy' => 'slot-fallback-content-review',
            'slotFallbackText' => $fallbackText,
            'slotFallbackTextLength' => strlen($fallbackText),
            'slotFallbackTextSha256' => hash('sha256', $fallbackText),
            'slotFallbackElementNames' => $topLevelElementNames,
            'slotFallbackElementCount' => count($topLevelElementNames),
            'slotFallbackTopLevelElementNames' => $topLevelElementNames,
            'slotFallbackTopLevelElementCount' => count($topLevelElementNames),
            'slotFallbackDescendantElementNames' => $descendantElementNames,
            'slotFallbackDescendantElementCount' => count($descendantElementNames),
            'slotHasFallback' => $fallbackText !== '' || $topLevelElementNames !== [],
            'slotFallbackActive' => $assignedElements === [] && ($fallbackText !== '' || $topLevelElementNames !== []),
            'slotFallbackLinkHrefs' => self::inertHtmlFragmentAttributeValues($slot, ['a', 'area'], 'href'),
            'slotFallbackImageSources' => self::inertHtmlFragmentAttributeValues($slot, ['img'], 'src'),
            'slotFallbackControls' => $fallbackControls,
            'slotFallbackControlNames' => array_values(array_filter(
                array_map(static fn (array $control): ?string => $control['controlName'], $fallbackControls),
                static fn (?string $name): bool => $name !== null && $name !== ''
            )),
            'slotIssues' => $issues,
            'slotIssueCodes' => array_values(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            )),
        ];
    }

    private static function firstScopedHeadingElement(\DOMElement $element): ?\DOMElement
    {
        foreach ($element->childNodes as $child) {
            if (!$child instanceof \DOMElement) {
                continue;
            }

            $name = self::htmlElementName($child);
            if ($name === 'hgroup') {
                $heading = self::htmlHeadingGroupMainHeadingElement($child);
                if ($heading instanceof \DOMElement) {
                    return $heading;
                }

                continue;
            }
            if (self::isHtmlHeadingElementName($name)) {
                return $child;
            }
            if (self::isHtmlOutlineElementName($name)) {
                continue;
            }

            $heading = self::firstScopedHeadingElement($child);
            if ($heading instanceof \DOMElement) {
                return $heading;
            }
        }

        return null;
    }

    /**
     * @return array<string, mixed>
     */
    private static function documentMetadataSummary(\DOMElement $element, string $name): array
    {
        if ($name === 'base') {
            return [
                'documentMetadata' => 'base',
                'href' => self::attributeOrNull($element, 'href'),
                'target' => self::attributeOrNull($element, 'target'),
            ];
        }

        if ($name === 'link') {
            $relRaw = self::attributeOrNull($element, 'rel');
            $imageSrcset = self::attributeOrNull($element, 'imagesrcset');
            $blockingRaw = self::attributeOrNull($element, 'blocking');

            $summary = [
                'documentMetadata' => 'link',
                'href' => self::attributeOrNull($element, 'href'),
                'relRaw' => $relRaw,
                'relTokens' => $relRaw === null ? [] : self::spaceSeparatedTokens($relRaw),
                'as' => self::attributeOrNull($element, 'as'),
                'media' => self::attributeOrNull($element, 'media'),
                'hreflang' => self::attributeOrNull($element, 'hreflang'),
                'mimeType' => self::attributeOrNull($element, 'type'),
                'crossorigin' => self::attributeOrNull($element, 'crossorigin'),
                'integrity' => self::attributeOrNull($element, 'integrity'),
                'referrerpolicy' => self::attributeOrNull($element, 'referrerpolicy'),
                'sizes' => self::attributeOrNull($element, 'sizes'),
                'imageSrcset' => $imageSrcset,
                'imageSrcsetCandidates' => self::srcsetCandidateSummaries($imageSrcset),
                'imageSizes' => self::attributeOrNull($element, 'imagesizes'),
                'fetchpriority' => self::attributeOrNull($element, 'fetchpriority'),
                'blockingRaw' => $blockingRaw,
                'blockingTokens' => $blockingRaw === null ? [] : self::spaceSeparatedTokens($blockingRaw),
            ];

            return $summary
                + self::linkResourceReviewSummary($element, $relRaw)
                + self::srcsetResourceReviewSummary($imageSrcset, 'imageSrcset');
        }

        $content = self::attributeOrNull($element, 'content');
        $httpEquivRaw = self::attributeOrNull($element, 'http-equiv');
        $httpEquiv = $httpEquivRaw === null ? null : strtolower(trim($httpEquivRaw));
        $summary = [
            'documentMetadata' => 'meta',
            'charset' => self::attributeOrNull($element, 'charset'),
            'nameAttribute' => self::attributeOrNull($element, 'name'),
            'property' => self::attributeOrNull($element, 'property'),
            'itemprop' => self::attributeOrNull($element, 'itemprop'),
            'httpEquivRaw' => $httpEquivRaw,
            'httpEquiv' => $httpEquiv,
            'content' => $content,
        ];

        if ($httpEquiv === 'refresh') {
            $summary['refresh'] = self::metaRefreshSummary($content);
        }
        if ($httpEquiv === 'content-security-policy' || $httpEquiv === 'content-security-policy-report-only') {
            $summary += self::metaContentSecurityPolicySummary($content, $httpEquiv);
        }
        if ($httpEquiv === 'permissions-policy' || $httpEquiv === 'feature-policy') {
            $summary += self::metaPermissionsPolicySummary($content, $httpEquiv);
        }
        if (strtolower(trim((string) self::attributeOrNull($element, 'name'))) === 'referrer') {
            $summary += self::metaReferrerPolicySummary($content);
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function linkResourceReviewSummary(\DOMElement $link, ?string $relRaw): array
    {
        $tokens = $relRaw === null ? [] : self::spaceSeparatedTokens($relRaw);
        $knownTokens = [
            'alternate' => true,
            'author' => true,
            'canonical' => true,
            'dns-prefetch' => true,
            'expect' => true,
            'help' => true,
            'icon' => true,
            'license' => true,
            'manifest' => true,
            'modulepreload' => true,
            'next' => true,
            'pingback' => true,
            'preconnect' => true,
            'prefetch' => true,
            'preload' => true,
            'prev' => true,
            'prerender' => true,
            'search' => true,
            'stylesheet' => true,
        ];
        $resourceTokenKinds = [
            'alternate' => 'alternate',
            'canonical' => 'canonical',
            'dns-prefetch' => 'resource-hint',
            'icon' => 'icon',
            'manifest' => 'manifest',
            'modulepreload' => 'modulepreload',
            'preconnect' => 'resource-hint',
            'prefetch' => 'resource-hint',
            'preload' => 'preload',
            'prerender' => 'resource-hint',
            'search' => 'search',
            'stylesheet' => 'stylesheet',
        ];
        $resourceHintTokens = ['dns-prefetch' => true, 'preconnect' => true, 'prefetch' => true, 'prerender' => true];
        $preloadDestinations = [
            'audio' => true,
            'document' => true,
            'embed' => true,
            'fetch' => true,
            'font' => true,
            'image' => true,
            'object' => true,
            'script' => true,
            'style' => true,
            'track' => true,
            'video' => true,
            'worker' => true,
        ];

        $normalized = [];
        $counts = [];
        $invalid = [];
        $custom = [];
        $resourceRelTokens = [];
        $resourceKinds = [];
        $resourceHints = [];
        foreach ($tokens as $token) {
            $lower = strtolower($token);
            if (!self::isSafeHtmlRelToken($token)) {
                $invalid[] = $token;
                continue;
            }

            if (!array_key_exists($lower, $counts)) {
                $normalized[] = $lower;
                $counts[$lower] = 0;
            }
            ++$counts[$lower];

            if (!isset($knownTokens[$lower])) {
                $custom[] = $lower;
            }
            if (isset($resourceTokenKinds[$lower]) && !in_array($lower, $resourceRelTokens, true)) {
                $resourceRelTokens[] = $lower;
            }
            if (isset($resourceTokenKinds[$lower]) && !in_array($resourceTokenKinds[$lower], $resourceKinds, true)) {
                $resourceKinds[] = $resourceTokenKinds[$lower];
            }
            if (isset($resourceHintTokens[$lower]) && !in_array($lower, $resourceHints, true)) {
                $resourceHints[] = $lower;
            }
        }

        $duplicates = [];
        foreach ($counts as $token => $count) {
            if ($count > 1) {
                $duplicates[] = $token;
            }
        }

        $asRaw = self::attributeOrNull($link, 'as');
        $as = $asRaw === null ? null : strtolower(trim($asRaw));
        $hasPreload = in_array('preload', $normalized, true);
        $preloadAsValid = !$hasPreload || ($as !== null && isset($preloadDestinations[$as]));
        $href = self::attributeOrNull($link, 'href');
        $hrefRequired = $resourceRelTokens !== [];
        $crossoriginRaw = self::attributeOrNull($link, 'crossorigin');
        $crossorigin = $crossoriginRaw === null ? null : self::htmlCorsSettingsAttributeState($crossoriginRaw);
        $fetchPriorityRaw = self::attributeOrNull($link, 'fetchpriority');
        $fetchPriority = $fetchPriorityRaw === null ? null : self::fetchPriorityState($fetchPriorityRaw);
        $referrerPolicyRaw = self::attributeOrNull($link, 'referrerpolicy');
        $referrerPolicy = $referrerPolicyRaw === null ? null : self::referrerPolicyState($referrerPolicyRaw);
        $integrityRaw = self::attributeOrNull($link, 'integrity');
        $integrityTokens = $integrityRaw === null ? [] : self::spaceSeparatedTokens($integrityRaw);
        $integrityAppliesToResource = $integrityRaw !== null
            && (in_array('preload', $resourceKinds, true)
                || in_array('modulepreload', $resourceKinds, true)
                || in_array('stylesheet', $resourceKinds, true));
        $blockingRaw = self::attributeOrNull($link, 'blocking');
        $blockingTokens = $blockingRaw === null ? [] : self::spaceSeparatedTokens($blockingRaw);
        $blocking = self::htmlBlockingTokenSummary($link);
        $blockingTokenCounts = $blocking['tokenCounts'];
        $invalidBlockingTokens = $blocking['invalid'];
        $duplicateBlockingTokens = $blocking['duplicates'];
        $renderBlockingTokenPresent = isset($blockingTokenCounts['render']);
        $renderBlockingResourceCandidate = in_array('stylesheet', $resourceKinds, true)
            || in_array('preload', $resourceKinds, true)
            || in_array('modulepreload', $resourceKinds, true);
        $blockingReviewKind = match (true) {
            $blockingRaw === null => 'not-declared',
            $blockingTokens === [] => 'empty-blocking-attribute',
            $renderBlockingTokenPresent && $renderBlockingResourceCandidate => 'declared-render-blocking-resource',
            $renderBlockingTokenPresent => 'declared-render-blocking-non-resource',
            default => 'declared-non-render-token',
        };
        $issues = [];
        $loadingIssues = [];
        $fetchPolicyIssues = [];

        foreach ($invalid as $token) {
            $issues[] = ['code' => 'invalid-link-rel-token', 'relToken' => $token];
        }
        foreach ($duplicates as $token) {
            $issues[] = ['code' => 'duplicate-link-rel-token', 'relToken' => $token, 'count' => $counts[$token]];
        }
        if ($hrefRequired && ($href === null || trim($href) === '')) {
            $issues[] = ['code' => 'missing-link-href', 'relTokens' => $resourceRelTokens];
        }
        if ($hasPreload && ($as === null || $as === '')) {
            $issues[] = ['code' => 'missing-preload-as'];
        } elseif ($hasPreload && !isset($preloadDestinations[$as])) {
            $issues[] = ['code' => 'invalid-preload-as', 'asRaw' => $asRaw];
        }
        if ($crossoriginRaw !== null && $crossorigin === null) {
            $fetchPolicyIssues[] = ['code' => 'invalid-link-crossorigin', 'crossoriginRaw' => $crossoriginRaw];
        }
        if ($fetchPriorityRaw !== null && $fetchPriority === null) {
            $fetchPolicyIssues[] = ['code' => 'invalid-link-fetchpriority', 'fetchpriorityRaw' => $fetchPriorityRaw];
        }
        if ($referrerPolicyRaw !== null && $referrerPolicy === null) {
            $fetchPolicyIssues[] = ['code' => 'invalid-link-referrerpolicy', 'referrerpolicyRaw' => $referrerPolicyRaw];
        }
        if ($integrityRaw !== null && $integrityTokens === []) {
            $fetchPolicyIssues[] = ['code' => 'empty-link-integrity'];
        }
        if ($integrityRaw !== null && !$integrityAppliesToResource) {
            $fetchPolicyIssues[] = [
                'code' => 'link-integrity-without-fetch-resource',
                'relTokens' => $resourceRelTokens,
            ];
        }
        array_push($issues, ...$fetchPolicyIssues);
        foreach ($invalidBlockingTokens as $token) {
            $issues[] = [
                'code' => 'invalid-link-blocking-token',
                'blockingToken' => $token,
                'count' => $blockingTokenCounts[$token],
            ];
        }
        foreach ($duplicateBlockingTokens as $token) {
            $issues[] = [
                'code' => 'duplicate-link-blocking-token',
                'blockingToken' => $token,
                'count' => $blockingTokenCounts[$token],
            ];
        }
        if ($crossoriginRaw !== null && $crossorigin === null) {
            $loadingIssues[] = ['code' => 'invalid-link-crossorigin', 'value' => $crossoriginRaw];
        }
        if ($fetchPriorityRaw !== null && $fetchPriority === null) {
            $loadingIssues[] = ['code' => 'invalid-link-fetchpriority', 'value' => $fetchPriorityRaw];
        }
        if ($referrerPolicyRaw !== null && $referrerPolicy === null) {
            $loadingIssues[] = ['code' => 'invalid-link-referrerpolicy', 'value' => $referrerPolicyRaw];
        }
        foreach ($blocking['invalid'] as $token) {
            $loadingIssues[] = ['code' => 'invalid-link-blocking-token', 'token' => $token];
        }
        foreach ($blocking['duplicates'] as $token) {
            $loadingIssues[] = [
                'code' => 'duplicate-link-blocking-token',
                'token' => $token,
                'count' => $blocking['tokenCounts'][$token] ?? 0,
            ];
        }

        return [
            'linkResourceReview' => 'link',
            'linkRelTokens' => $normalized,
            'linkRelTokenCounts' => $counts,
            'duplicateLinkRelTokens' => $duplicates,
            'invalidLinkRelTokens' => $invalid,
            'customLinkRelTokens' => $custom,
            'linkResourceRelTokens' => $resourceRelTokens,
            'linkResourceKinds' => $resourceKinds,
            'linkPrimaryResourceKind' => $resourceKinds[0] ?? null,
            'linkResourceHintTokens' => $resourceHints,
            'linkHrefRequired' => $hrefRequired,
            'linkHrefPresent' => $href !== null && trim($href) !== '',
            'preloadAsRaw' => $asRaw,
            'preloadAs' => $as === '' ? null : $as,
            'preloadAsRequired' => $hasPreload,
            'preloadAsValid' => $preloadAsValid,
            'linkFetchPolicyReviewPolicy' => 'link-fetch-policy-review',
            'linkCrossoriginRaw' => $crossoriginRaw,
            'linkCrossoriginState' => $crossorigin,
            'linkCrossoriginValid' => $crossoriginRaw === null ? null : $crossorigin !== null,
            'linkFetchPriorityRaw' => $fetchPriorityRaw,
            'linkFetchPriority' => $fetchPriority,
            'linkFetchPriorityValid' => $fetchPriorityRaw === null ? null : $fetchPriority !== null,
            'linkReferrerPolicyRaw' => $referrerPolicyRaw,
            'linkReferrerPolicy' => $referrerPolicy,
            'linkReferrerPolicyValid' => $referrerPolicyRaw === null ? null : $referrerPolicy !== null,
            'linkIntegrityRaw' => $integrityRaw,
            'linkIntegrityTokens' => $integrityTokens,
            'linkIntegrityTokenCount' => count($integrityTokens),
            'linkIntegrityPresent' => $integrityRaw !== null,
            'linkIntegrityEmpty' => $integrityRaw !== null && $integrityTokens === [],
            'linkIntegrityAppliesToResource' => $integrityAppliesToResource,
            'linkBlockingReviewPolicy' => 'link-render-blocking-token-review',
            'linkBlockingAttributePresent' => $blockingRaw !== null,
            'linkBlockingTokens' => $blockingTokens,
            'linkBlockingTokenCounts' => $blockingTokenCounts,
            'duplicateLinkBlockingTokens' => $duplicateBlockingTokens,
            'invalidLinkBlockingTokens' => $invalidBlockingTokens,
            'linkRenderBlockingTokenPresent' => $renderBlockingTokenPresent,
            'linkRenderBlockingResourceCandidate' => $renderBlockingResourceCandidate,
            'linkBlockingReviewKind' => $blockingReviewKind,
            'linkIssues' => $issues,
            'linkLoadingPolicyReview' => 'link-loading-policy-metadata-review',
            'linkBlockingAllTokensValid' => $blocking['invalid'] === [],
            'linkLoadingIssues' => $loadingIssues,
            'linkLoadingIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $loadingIssues
            ))),
            'linkFetchPolicyIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) $issue['code'],
                $fetchPolicyIssues
            ))),
            'linkFetchPolicyValid' => $fetchPolicyIssues === [],
        ];
    }

    private static function isSafeHtmlRelToken(string $token): bool
    {
        return $token !== ''
            && preg_match('/^[A-Za-z][A-Za-z0-9_.:-]*$/', $token) === 1;
    }

    /**
     * @return array{contentRaw:?string, delayRaw:?string, delay:?float, urlRaw:?string, url:?string}
     */
    private static function metaRefreshSummary(?string $content): array
    {
        if ($content === null) {
            return [
                'contentRaw' => null,
                'delayRaw' => null,
                'delay' => null,
                'urlRaw' => null,
                'url' => null,
            ];
        }

        $parts = explode(';', $content, 2);
        $delayRaw = trim($parts[0]);
        $delay = is_numeric($delayRaw) ? (float) $delayRaw : null;
        if ($delay !== null && (!is_finite($delay) || $delay < 0.0)) {
            $delay = null;
        }

        $urlRaw = null;
        $url = null;
        if (isset($parts[1]) && preg_match('/^\s*url\s*=\s*(.*)\s*$/i', $parts[1], $matches) === 1) {
            $urlRaw = trim((string) $matches[1]);
            $url = trim($urlRaw, " \t\r\n\f\"'");
        }

        return [
            'contentRaw' => $content,
            'delayRaw' => $delayRaw === '' ? null : $delayRaw,
            'delay' => $delay,
            'urlRaw' => $urlRaw,
            'url' => $url,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function metaReferrerPolicySummary(?string $content): array
    {
        $raw = $content;
        $normalized = $raw === null ? null : strtolower(trim($raw));
        $legacyMappings = [
            'never' => 'no-referrer',
            'default' => 'default-referrer-policy',
            'always' => 'unsafe-url',
            'origin-when-crossorigin' => 'origin-when-cross-origin',
        ];
        $legacyValue = $normalized !== null && isset($legacyMappings[$normalized]) ? $normalized : null;
        $policy = null;
        $policySource = 'none';
        $issues = [];

        if ($raw === null) {
            $issues[] = ['code' => 'missing-meta-referrer-content'];
        } elseif ($normalized === '') {
            $issues[] = ['code' => 'empty-meta-referrer-content'];
        } elseif ($legacyValue !== null) {
            $policy = $legacyMappings[$legacyValue];
            $policySource = 'legacy-alias';
        } else {
            $policy = self::referrerPolicyState($raw);
            $policySource = $policy === null ? 'invalid-token' : 'referrer-policy';
            if ($policy === null) {
                $issues[] = [
                    'code' => 'invalid-meta-referrer-policy',
                    'contentRaw' => $raw,
                ];
            }
        }

        return [
            'metaReferrerReviewPolicy' => 'meta-referrer-policy-review',
            'metaReferrerRaw' => $raw,
            'metaReferrerNormalized' => $normalized,
            'metaReferrerLegacyValue' => $legacyValue,
            'metaReferrerLegacyMapped' => $legacyValue !== null,
            'metaReferrerPolicy' => $policy,
            'metaReferrerPolicySource' => $policySource,
            'metaReferrerDefaultPolicyRequested' => $policy === 'default-referrer-policy',
            'metaReferrerApplies' => $issues === [],
            'metaReferrerIssues' => $issues,
            'metaReferrerIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ))),
            'metaReferrerValid' => $issues === [],
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function metaPermissionsPolicySummary(?string $content, string $httpEquiv): array
    {
        $raw = $content ?? '';
        $directives = [];
        $directiveNames = [];
        $directiveNameCounts = [];
        $features = [];
        $disabledFeatures = [];
        $wildcardFeatures = [];
        $selfFeatures = [];
        $originAllowListTokens = [];
        $invalidDirectiveNames = [];
        $invalidAllowListTokens = [];
        $hasLegacySyntax = $httpEquiv === 'feature-policy';

        foreach (self::permissionsPolicyDirectiveFragments($raw) as $fragmentIndex => $fragment) {
            $directiveRaw = trim($fragment);
            if ($directiveRaw === '') {
                continue;
            }

            $parsed = self::parsePermissionsPolicyDirective($directiveRaw);
            $hasLegacySyntax = $hasLegacySyntax || $parsed['syntax'] === 'legacy-feature-policy';
            $nameRaw = $parsed['nameRaw'];
            $name = strtolower($nameRaw);
            $validName = self::isIframeAllowFeatureToken($name);
            $invalidValues = [];

            if ($validName) {
                if (!isset($directiveNameCounts[$name])) {
                    $directiveNameCounts[$name] = 0;
                    $directiveNames[] = $name;
                }
                ++$directiveNameCounts[$name];
                self::appendUniqueString($features, $name);
            } else {
                $invalidDirectiveNames[] = $nameRaw;
            }

            foreach ($parsed['allowList'] as $token) {
                if (!self::isPermissionsPolicyAllowListToken($token)) {
                    $invalidValues[] = $token;
                    $invalidAllowListTokens[] = $token;
                    continue;
                }

                $normalizedToken = strtolower($token);
                if ($validName && ($token === '*' || $normalizedToken === '"*"')) {
                    self::appendUniqueString($wildcardFeatures, $name);
                }
                if ($validName && in_array($normalizedToken, ['self', "'self'", '"self"'], true)) {
                    self::appendUniqueString($selfFeatures, $name);
                }
                if ($validName && self::isPermissionsPolicyOriginAllowListToken($token)) {
                    self::appendUniqueString($originAllowListTokens, self::unquoteDoubleQuotedToken($token));
                }
            }

            if ($validName && self::permissionsPolicyAllowListDisablesFeature($parsed['allowList'], $parsed['allowListRaw'])) {
                self::appendUniqueString($disabledFeatures, $name);
            }

            $directiveIssues = [];
            if (!$validName) {
                $directiveIssues[] = 'invalid-permissions-policy-directive-name';
            }
            if ($parsed['modernSyntaxMissingParens']) {
                $directiveIssues[] = 'invalid-permissions-policy-allowlist-syntax';
            }
            if ($invalidValues !== []) {
                $directiveIssues[] = 'invalid-permissions-policy-allowlist-token';
            }

            $directives[] = [
                'index' => count($directives),
                'sourceIndex' => $fragmentIndex,
                'raw' => $directiveRaw,
                'nameRaw' => $nameRaw,
                'name' => $validName ? $name : null,
                'syntax' => $parsed['syntax'],
                'allowListRaw' => $parsed['allowListRaw'],
                'allowList' => $parsed['allowList'],
                'allowListCount' => count($parsed['allowList']),
                'allowListEmpty' => $parsed['allowList'] === [],
                'invalidAllowListTokens' => $invalidValues,
                'valid' => $validName && !$parsed['modernSyntaxMissingParens'] && $invalidValues === [],
                'issueCodes' => $directiveIssues,
            ];
        }

        $duplicateDirectiveNames = array_values(array_filter(
            $directiveNames,
            static fn (string $name): bool => ($directiveNameCounts[$name] ?? 0) > 1
        ));
        $issues = [];
        if ($content === null) {
            $issues[] = ['code' => 'missing-meta-permissions-policy-content'];
        } elseif (trim($content) === '') {
            $issues[] = ['code' => 'empty-meta-permissions-policy-content'];
        }
        foreach ($invalidDirectiveNames as $name) {
            $issues[] = ['code' => 'invalid-permissions-policy-directive-name', 'nameRaw' => $name];
        }
        foreach ($invalidAllowListTokens as $token) {
            $issues[] = ['code' => 'invalid-permissions-policy-allowlist-token', 'allowListToken' => $token];
        }
        foreach ($directives as $directive) {
            if (in_array('invalid-permissions-policy-allowlist-syntax', $directive['issueCodes'], true)) {
                $issues[] = [
                    'code' => 'invalid-permissions-policy-allowlist-syntax',
                    'directive' => $directive['nameRaw'],
                    'allowListRaw' => $directive['allowListRaw'],
                ];
            }
        }
        foreach ($duplicateDirectiveNames as $name) {
            $issues[] = [
                'code' => 'duplicate-permissions-policy-directive',
                'directive' => $name,
                'count' => $directiveNameCounts[$name] ?? 0,
            ];
        }
        foreach ($wildcardFeatures as $feature) {
            $issues[] = ['code' => 'wildcard-permissions-policy-allowlist', 'directive' => $feature];
        }

        return [
            'permissionsPolicyReviewPolicy' => 'meta-permissions-policy-review',
            'permissionsPolicyHttpEquiv' => $httpEquiv,
            'permissionsPolicyRaw' => $content,
            'permissionsPolicyByteLength' => strlen($raw),
            'permissionsPolicySha256' => hash('sha256', $raw),
            'permissionsPolicyLegacySyntax' => $hasLegacySyntax,
            'permissionsPolicyDirectiveCount' => count($directives),
            'permissionsPolicyDirectives' => $directives,
            'permissionsPolicyDirectiveNames' => $directiveNames,
            'permissionsPolicyDirectiveNameCounts' => $directiveNameCounts,
            'duplicatePermissionsPolicyDirectiveNames' => $duplicateDirectiveNames,
            'invalidPermissionsPolicyDirectiveNames' => $invalidDirectiveNames,
            'invalidPermissionsPolicyAllowListTokens' => $invalidAllowListTokens,
            'permissionsPolicyFeatures' => $features,
            'permissionsPolicyDisabledFeatures' => $disabledFeatures,
            'permissionsPolicyWildcardFeatures' => $wildcardFeatures,
            'permissionsPolicySelfFeatures' => $selfFeatures,
            'permissionsPolicyOriginAllowListTokens' => $originAllowListTokens,
            'permissionsPolicyIssues' => $issues,
            'permissionsPolicyIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ))),
            'permissionsPolicyValid' => $issues === [],
        ];
    }

    /**
     * @return list<string>
     */
    private static function permissionsPolicyDirectiveFragments(string $value): array
    {
        $fragments = [];
        $fragment = '';
        $parenDepth = 0;
        $quote = null;
        $length = strlen($value);

        for ($offset = 0; $offset < $length; ++$offset) {
            $char = $value[$offset];
            if ($quote !== null) {
                $fragment .= $char;
                if ($char === $quote) {
                    $quote = null;
                }
                continue;
            }

            if ($char === '"' || $char === "'") {
                $quote = $char;
                $fragment .= $char;
                continue;
            }

            if ($char === '(') {
                ++$parenDepth;
                $fragment .= $char;
                continue;
            }

            if ($char === ')' && $parenDepth > 0) {
                --$parenDepth;
                $fragment .= $char;
                continue;
            }

            if (($char === ',' || $char === ';') && $parenDepth === 0) {
                $fragments[] = $fragment;
                $fragment = '';
                continue;
            }

            $fragment .= $char;
        }

        $fragments[] = $fragment;

        return $fragments;
    }

    /**
     * @return array{
     *     nameRaw:string,
     *     syntax:string,
     *     allowListRaw:string,
     *     allowList:list<string>,
     *     modernSyntaxMissingParens:bool
     * }
     */
    private static function parsePermissionsPolicyDirective(string $directiveRaw): array
    {
        if (preg_match('/^([^=\s]+)\s*=\s*(.*)$/u', $directiveRaw, $matches) === 1) {
            $allowListRaw = trim((string) $matches[2]);
            $hasModernParens = str_starts_with($allowListRaw, '(') && str_ends_with($allowListRaw, ')');

            return [
                'nameRaw' => (string) $matches[1],
                'syntax' => 'permissions-policy',
                'allowListRaw' => $allowListRaw,
                'allowList' => self::permissionsPolicyAllowListTokens($allowListRaw),
                'modernSyntaxMissingParens' => !$hasModernParens,
            ];
        }

        $tokens = self::spaceSeparatedTokens($directiveRaw);
        $nameRaw = (string) array_shift($tokens);

        return [
            'nameRaw' => $nameRaw,
            'syntax' => 'legacy-feature-policy',
            'allowListRaw' => implode(' ', $tokens),
            'allowList' => $tokens,
            'modernSyntaxMissingParens' => false,
        ];
    }

    /**
     * @return list<string>
     */
    private static function permissionsPolicyAllowListTokens(string $allowListRaw): array
    {
        $value = trim($allowListRaw);
        if ($value === '' || $value === '()') {
            return [];
        }

        if (str_starts_with($value, '(') && str_ends_with($value, ')')) {
            $value = trim(substr($value, 1, -1));
            if ($value === '') {
                return [];
            }
        }

        return self::spaceSeparatedTokens($value);
    }

    private static function isPermissionsPolicyAllowListToken(string $token): bool
    {
        $lower = strtolower($token);
        if ($token === '*' || in_array($lower, ['self', 'src', 'none', "'self'", "'src'", "'none'", '"self"', '"src"', '"none"', '"*"'], true)) {
            return true;
        }

        if (str_starts_with($token, '"') || str_ends_with($token, '"')) {
            if (!(str_starts_with($token, '"') && str_ends_with($token, '"') && strlen($token) >= 2)) {
                return false;
            }

            $token = substr($token, 1, -1);
        } elseif (str_starts_with($token, "'") || str_ends_with($token, "'")) {
            return false;
        }

        return $token !== '' && preg_match('/[\s<>"`\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/u', $token) === 0;
    }

    /**
     * @param list<string> $allowList
     */
    private static function permissionsPolicyAllowListDisablesFeature(array $allowList, string $allowListRaw): bool
    {
        if (trim($allowListRaw) === '()') {
            return true;
        }

        foreach ($allowList as $token) {
            if (in_array(strtolower($token), ['none', "'none'", '"none"'], true)) {
                return true;
            }
        }

        return false;
    }

    private static function isPermissionsPolicyOriginAllowListToken(string $token): bool
    {
        $token = self::unquoteDoubleQuotedToken($token);

        return self::isCspNetworkSource($token);
    }

    private static function unquoteDoubleQuotedToken(string $token): string
    {
        if (str_starts_with($token, '"') && str_ends_with($token, '"') && strlen($token) >= 2) {
            return substr($token, 1, -1);
        }

        return $token;
    }

    /**
     * @return array<string, mixed>
     */
    private static function metaContentSecurityPolicySummary(?string $content, string $httpEquiv): array
    {
        $raw = $content ?? '';
        $directives = [];
        $directiveNames = [];
        $directiveNameCounts = [];
        $directiveKinds = [];
        $fetchDirectiveNames = [];
        $schemeSources = [];
        $networkSources = [];
        $reportEndpoints = [];
        $unsafeKeywords = [];
        $nonceSourceDigests = [];
        $hashSourceAlgorithms = [];
        $invalidDirectiveNames = [];
        $invalidSourceTokens = [];

        foreach (explode(';', $raw) as $fragmentIndex => $fragment) {
            $directiveRaw = trim($fragment);
            if ($directiveRaw === '') {
                continue;
            }

            $tokens = preg_split('/[\t\n\f\r ]+/', $directiveRaw) ?: [];
            $nameRaw = (string) array_shift($tokens);
            $name = strtolower($nameRaw);
            $validName = self::isSafeCspDirectiveName($nameRaw);
            $kind = $validName ? self::cspDirectiveKind($name) : 'invalid';
            $invalidValues = [];

            if ($validName) {
                if (!isset($directiveNameCounts[$name])) {
                    $directiveNameCounts[$name] = 0;
                    $directiveNames[] = $name;
                }
                ++$directiveNameCounts[$name];
                self::appendUniqueString($directiveKinds, $kind);
                if ($kind === 'fetch') {
                    self::appendUniqueString($fetchDirectiveNames, $name);
                }
            } else {
                $invalidDirectiveNames[] = $nameRaw;
            }

            foreach ($tokens as $token) {
                if (!self::isSafeCspSourceToken($token)) {
                    $invalidValues[] = $token;
                    $invalidSourceTokens[] = $token;
                    continue;
                }

                $lower = strtolower($token);
                if (in_array($lower, ["'unsafe-inline'", "'unsafe-eval'", "'unsafe-hashes'"], true)) {
                    self::appendUniqueString($unsafeKeywords, $lower);
                }

                if (preg_match("/^'nonce-([^']+)'$/i", $token, $matches) === 1) {
                    $nonceSourceDigests[] = hash('sha256', (string) $matches[1]);
                }

                if (preg_match("/^'(sha256|sha384|sha512)-[A-Za-z0-9+\/_-]+=*'$/i", $token, $matches) === 1) {
                    self::appendUniqueString($hashSourceAlgorithms, strtolower((string) $matches[1]));
                }

                if (self::isCspSchemeSource($token)) {
                    self::appendUniqueString($schemeSources, strtolower($token));
                }

                if (self::isCspNetworkSource($token)) {
                    self::appendUniqueString($networkSources, $token);
                }

                if ($name === 'report-uri' && self::isCspNetworkSource($token)) {
                    self::appendUniqueString($reportEndpoints, $token);
                }
            }

            $directiveIssues = [];
            if (!$validName) {
                $directiveIssues[] = 'invalid-csp-directive-name';
            }
            if ($invalidValues !== []) {
                $directiveIssues[] = 'invalid-csp-source-token';
            }

            $directives[] = [
                'index' => count($directives),
                'sourceIndex' => $fragmentIndex,
                'raw' => $directiveRaw,
                'nameRaw' => $nameRaw,
                'name' => $validName ? $name : null,
                'kind' => $kind,
                'values' => $tokens,
                'valueCount' => count($tokens),
                'invalidValues' => $invalidValues,
                'valid' => $validName && $invalidValues === [],
                'issueCodes' => $directiveIssues,
            ];
        }

        $duplicateDirectiveNames = array_values(array_filter(
            $directiveNames,
            static fn (string $name): bool => ($directiveNameCounts[$name] ?? 0) > 1
        ));
        $issues = [];
        if ($content === null || trim($content) === '') {
            $issues[] = ['code' => 'missing-meta-csp-content'];
        }
        foreach ($invalidDirectiveNames as $name) {
            $issues[] = ['code' => 'invalid-csp-directive-name', 'nameRaw' => $name];
        }
        foreach ($invalidSourceTokens as $token) {
            $issues[] = ['code' => 'invalid-csp-source-token', 'sourceToken' => $token];
        }
        foreach ($duplicateDirectiveNames as $name) {
            $issues[] = [
                'code' => 'duplicate-csp-directive',
                'directive' => $name,
                'count' => $directiveNameCounts[$name] ?? 0,
            ];
        }
        foreach ($unsafeKeywords as $keyword) {
            $issues[] = ['code' => 'unsafe-csp-keyword', 'keyword' => $keyword];
        }
        if (in_array('data:', $schemeSources, true)) {
            $issues[] = ['code' => 'data-csp-source'];
        }

        return [
            'contentSecurityPolicyReviewPolicy' => 'meta-content-security-policy-review',
            'contentSecurityPolicyHttpEquiv' => $httpEquiv,
            'contentSecurityPolicyRaw' => $content,
            'contentSecurityPolicyByteLength' => strlen($raw),
            'contentSecurityPolicySha256' => hash('sha256', $raw),
            'cspDirectiveCount' => count($directives),
            'cspDirectives' => $directives,
            'cspDirectiveNames' => $directiveNames,
            'cspDirectiveNameCounts' => $directiveNameCounts,
            'cspDirectiveKinds' => $directiveKinds,
            'cspFetchDirectiveNames' => $fetchDirectiveNames,
            'duplicateCspDirectiveNames' => $duplicateDirectiveNames,
            'invalidCspDirectiveNames' => $invalidDirectiveNames,
            'invalidCspSourceTokens' => $invalidSourceTokens,
            'cspSchemeSources' => $schemeSources,
            'cspNetworkSources' => $networkSources,
            'cspReportEndpoints' => $reportEndpoints,
            'cspUnsafeKeywords' => $unsafeKeywords,
            'cspNonceSourceCount' => count($nonceSourceDigests),
            'cspNonceSourceDigests' => $nonceSourceDigests,
            'cspHashSourceAlgorithms' => $hashSourceAlgorithms,
            'cspIssues' => $issues,
            'cspIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ))),
            'contentSecurityPolicyValid' => $issues === [],
        ];
    }

    private static function isSafeCspDirectiveName(string $name): bool
    {
        return preg_match('/^[A-Za-z][A-Za-z0-9-]*$/', $name) === 1;
    }

    private static function isSafeCspSourceToken(string $token): bool
    {
        return $token !== '' && preg_match('/[\s<>"`\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/u', $token) !== 1;
    }

    private static function cspDirectiveKind(string $name): string
    {
        return match ($name) {
            'default-src',
            'child-src',
            'connect-src',
            'font-src',
            'frame-src',
            'img-src',
            'manifest-src',
            'media-src',
            'object-src',
            'prefetch-src',
            'script-src',
            'script-src-attr',
            'script-src-elem',
            'style-src',
            'style-src-attr',
            'style-src-elem',
            'worker-src' => 'fetch',
            'base-uri',
            'plugin-types',
            'sandbox' => 'document',
            'form-action',
            'frame-ancestors',
            'navigate-to' => 'navigation',
            'report-to',
            'report-uri' => 'reporting',
            'block-all-mixed-content',
            'upgrade-insecure-requests' => 'transport',
            'require-trusted-types-for',
            'trusted-types' => 'trusted-types',
            default => 'other',
        };
    }

    private static function isCspSchemeSource(string $token): bool
    {
        return preg_match('/^[A-Za-z][A-Za-z0-9+.-]*:$/', $token) === 1;
    }

    private static function isCspNetworkSource(string $token): bool
    {
        return preg_match('~^(?:[A-Za-z][A-Za-z0-9+.-]*:)?//~', $token) === 1;
    }

    /**
     * @return array<string, mixed>
     */
    private static function breakElementSummary(string $name): array
    {
        return match ($name) {
            'br' => [
                'breakElement' => 'line-break',
                'breakTag' => 'br',
                'textEquivalent' => "\n",
                'hardBreak' => true,
            ],
            'wbr' => [
                'breakElement' => 'word-break-opportunity',
                'breakTag' => 'wbr',
                'textEquivalent' => '',
                'softBreakOpportunity' => true,
            ],
            'hr' => [
                'breakElement' => 'thematic-break',
                'breakTag' => 'hr',
                'blockSeparator' => true,
            ],
            default => [],
        };
    }

    /**
     * @return array<string, mixed>
     */
    private static function preformattedBlockSummary(\DOMElement $element): array
    {
        $text = $element->textContent;
        $code = self::primaryPreformattedCodeElement($element);
        $codeText = $code instanceof \DOMElement ? $code->textContent : null;
        $contentText = $codeText ?? $text;
        $language = self::preformattedLanguageSummary($element, $code);
        $preClasses = self::spaceSeparatedTokens((string) self::attributeOrNull($element, 'class'));
        $codeClasses = $code instanceof \DOMElement
            ? self::spaceSeparatedTokens((string) self::attributeOrNull($code, 'class'))
            : [];

        return [
            'preformattedBlock' => 'pre',
            'preformattedReviewPolicy' => 'html-pre-code-block-review',
            'preformattedContentSource' => $code instanceof \DOMElement ? 'nested-code' : 'pre-text',
            'preformattedText' => $text,
            'preformattedTextLength' => strlen($text),
            'preformattedTextSha256' => hash('sha256', $text),
            'preformattedLineCount' => self::sourceLineCount($text),
            'preformattedTrailingNewline' => self::hasTrailingSourceNewline($text),
            'preformattedClasses' => $preClasses,
            'preformattedCodeBlock' => $code instanceof \DOMElement,
            'preformattedCodeElementCount' => count(self::childHtmlElements($element, 'code')),
            'preformattedCodeText' => $codeText,
            'preformattedCodeTextLength' => $codeText === null ? null : strlen($codeText),
            'preformattedCodeTextSha256' => $codeText === null ? null : hash('sha256', $codeText),
            'preformattedCodeLineCount' => $codeText === null ? null : self::sourceLineCount($codeText),
            'preformattedCodeTrailingNewline' => $codeText === null ? null : self::hasTrailingSourceNewline($codeText),
            'preformattedCodeClasses' => $codeClasses,
            'preformattedContentLineCount' => self::sourceLineCount($contentText),
            'preformattedNumberedLines' => in_array('numberLines', $preClasses, true)
                || in_array('numberLines', $codeClasses, true),
        ] + $language;
    }

    private static function primaryPreformattedCodeElement(\DOMElement $element): ?\DOMElement
    {
        foreach (self::childHtmlElements($element, 'code') as $code) {
            return $code;
        }

        return null;
    }

    /**
     * @return array{
     *     preformattedLanguage:?string,
     *     preformattedLanguageToken:?string,
     *     preformattedLanguageSource:?string
     * }
     */
    private static function preformattedLanguageSummary(\DOMElement $pre, ?\DOMElement $code): array
    {
        $codeClasses = $code instanceof \DOMElement
            ? self::spaceSeparatedTokens((string) self::attributeOrNull($code, 'class'))
            : [];
        $preClasses = self::spaceSeparatedTokens((string) self::attributeOrNull($pre, 'class'));
        foreach ([
            ['classes' => $codeClasses, 'source' => 'code-class'],
            ['classes' => $preClasses, 'source' => 'pre-class'],
        ] as $candidate) {
            $language = self::languageFromClassTokens($candidate['classes'], $candidate['source']);
            if ($language['preformattedLanguage'] !== null) {
                return $language;
            }
        }

        return [
            'preformattedLanguage' => null,
            'preformattedLanguageToken' => null,
            'preformattedLanguageSource' => null,
        ];
    }

    /**
     * @param list<string> $classes
     * @return array{
     *     preformattedLanguage:?string,
     *     preformattedLanguageToken:?string,
     *     preformattedLanguageSource:?string
     * }
     */
    private static function languageFromClassTokens(array $classes, string $source): array
    {
        foreach ($classes as $token) {
            $lower = strtolower($token);
            if (str_starts_with($lower, 'language-') && strlen($token) > 9) {
                return [
                    'preformattedLanguage' => substr($token, 9),
                    'preformattedLanguageToken' => $token,
                    'preformattedLanguageSource' => $source . '-language-prefix',
                ];
            }
        }

        $sourceCodeIndex = array_search('sourceCode', $classes, true);
        if ($sourceCodeIndex === false) {
            $sourceCodeIndex = array_search('sourcecode', array_map('strtolower', $classes), true);
        }
        if ($sourceCodeIndex !== false) {
            foreach (array_slice($classes, (int) $sourceCodeIndex + 1) as $token) {
                if (in_array($token, ['numberSource', 'numberLines', 'lineAnchors'], true)) {
                    continue;
                }

                return [
                    'preformattedLanguage' => $token,
                    'preformattedLanguageToken' => $token,
                    'preformattedLanguageSource' => $source . '-sourcecode-token',
                ];
            }
        }

        return [
            'preformattedLanguage' => null,
            'preformattedLanguageToken' => null,
            'preformattedLanguageSource' => null,
        ];
    }

    private static function sourceLineCount(string $text): int
    {
        $normalized = str_replace(["\r\n", "\r"], "\n", $text);
        if ($normalized === '') {
            return 0;
        }

        if (str_ends_with($normalized, "\n")) {
            $normalized = substr($normalized, 0, -1);
        }

        return $normalized === '' ? 1 : substr_count($normalized, "\n") + 1;
    }

    private static function hasTrailingSourceNewline(string $text): bool
    {
        return str_ends_with($text, "\n") || str_ends_with($text, "\r");
    }

    /**
     * @return array<string, mixed>
     */
    private static function rubySummary(\DOMElement $element, string $name): array
    {
        if ($name === 'ruby') {
            $baseTexts = self::rubyBaseTexts($element);
            $annotations = self::rubyAnnotationSummaries($element);
            $fallbackTexts = self::rubyFallbackTexts($element);

            return [
                'ruby' => 'ruby',
                'rubyText' => self::normalizedText($element),
                'rubyBaseTexts' => $baseTexts,
                'rubyBaseCount' => count($baseTexts),
                'rubyAnnotationTexts' => array_values(array_map(
                    static fn (array $annotation): string => (string) $annotation['text'],
                    $annotations
                )),
                'rubyAnnotations' => $annotations,
                'rubyAnnotationCount' => count($annotations),
                'rubyFallbackTexts' => $fallbackTexts,
                'rubyFallbackCount' => count($fallbackTexts),
            ];
        }

        if ($name === 'rb') {
            return [
                'rubyPart' => 'base',
                'rubyBaseText' => self::normalizedText($element),
            ];
        }

        if ($name === 'rt') {
            return [
                'rubyPart' => 'annotation',
                'rubyAnnotationText' => self::normalizedText($element),
            ];
        }

        if ($name === 'rp') {
            return [
                'rubyPart' => 'fallback-parenthesis',
                'rubyFallbackText' => self::normalizedText($element),
            ];
        }

        $annotations = array_values(array_map(
            static fn (\DOMElement $annotation): string => self::normalizedText($annotation),
            self::childHtmlElements($element, 'rt')
        ));

        return [
            'rubyPart' => 'annotation-container',
            'rubyAnnotationTexts' => $annotations,
            'rubyAnnotationCount' => count($annotations),
        ];
    }

    /**
     * @return list<string>
     */
    private static function rubyBaseTexts(\DOMElement $ruby): array
    {
        $baseTexts = [];
        foreach ($ruby->childNodes as $child) {
            if ($child instanceof \DOMText) {
                $text = preg_replace('/[ \t\r\n\f]+/u', ' ', $child->nodeValue ?? '') ?? ($child->nodeValue ?? '');
                $text = trim($text);
                if ($text !== '') {
                    $baseTexts[] = $text;
                }
                continue;
            }

            if (!$child instanceof \DOMElement || self::htmlElementName($child) !== 'rb') {
                continue;
            }

            $text = self::normalizedText($child);
            if ($text !== '') {
                $baseTexts[] = $text;
            }
        }

        return $baseTexts;
    }

    /**
     * @return list<array{container:string|null, text:string}>
     */
    private static function rubyAnnotationSummaries(\DOMElement $ruby): array
    {
        $annotations = [];
        foreach ($ruby->childNodes as $child) {
            if (!$child instanceof \DOMElement) {
                continue;
            }

            $name = self::htmlElementName($child);
            if ($name === 'rt') {
                $annotations[] = [
                    'container' => null,
                    'text' => self::normalizedText($child),
                ];
                continue;
            }

            if ($name !== 'rtc') {
                continue;
            }

            foreach (self::childHtmlElements($child, 'rt') as $annotation) {
                $annotations[] = [
                    'container' => 'rtc',
                    'text' => self::normalizedText($annotation),
                ];
            }
        }

        return $annotations;
    }

    /**
     * @return list<string>
     */
    private static function rubyFallbackTexts(\DOMElement $ruby): array
    {
        $fallbackTexts = [];
        foreach (self::childHtmlElements($ruby, 'rp') as $fallback) {
            $fallbackTexts[] = self::normalizedText($fallback);
        }

        return $fallbackTexts;
    }

    /**
     * @return array<string, mixed>
     */
    private static function activeContentSummary(\DOMElement $element, string $name): array
    {
        $text = $element->textContent;
        if ($name === 'script') {
            $typeRaw = self::attributeOrNull($element, 'type');
            $type = $typeRaw === null ? null : strtolower(trim($typeRaw));
            $scriptType = self::scriptTypeSummary($type);
            $loading = self::scriptLoadingReviewSummary($element, $scriptType['scriptPayloadKind']);
            $summary = [
                'activeContent' => 'script',
                'scriptSourceKind' => $element->hasAttribute('src') ? 'external' : 'inline',
                'src' => self::attributeOrNull($element, 'src'),
                'scriptTypeRaw' => $typeRaw,
                'scriptType' => $type,
                'module' => $type === 'module',
                'async' => $element->hasAttribute('async'),
                'defer' => $element->hasAttribute('defer'),
                'nomodule' => $element->hasAttribute('nomodule'),
                'crossorigin' => self::attributeOrNull($element, 'crossorigin'),
                'integrity' => self::attributeOrNull($element, 'integrity'),
                'referrerpolicy' => self::attributeOrNull($element, 'referrerpolicy'),
                'fetchpriority' => self::attributeOrNull($element, 'fetchpriority'),
                'blockingRaw' => self::attributeOrNull($element, 'blocking'),
                'blockingTokens' => $element->hasAttribute('blocking') ? self::spaceSeparatedTokens($element->getAttribute('blocking')) : [],
                'scriptText' => $text,
                'scriptTextLength' => strlen($text),
                'scriptTextSha256' => hash('sha256', $text),
                'activeReviewPolicy' => $element->hasAttribute('src') ? 'external-script-source' : 'inline-script-source',
            ] + $scriptType
                + $loading
                + self::scriptAttributionSrcReviewSummary($element)
                + self::activeContentNonceSummary($element);

            if (in_array($scriptType['scriptPayloadKind'], ['importmap', 'speculationrules', 'json-data'], true)) {
                $summary += self::scriptJsonReviewSummary($text, $scriptType['scriptPayloadKind']);
            }

            return $summary;
        }

        $typeRaw = self::attributeOrNull($element, 'type');
        $type = $typeRaw === null ? null : strtolower(trim($typeRaw));

        return [
            'activeContent' => 'style',
            'styleSourceKind' => 'inline',
            'styleTypeRaw' => $typeRaw,
            'styleType' => $type,
            'media' => self::attributeOrNull($element, 'media'),
            'disabled' => $element->hasAttribute('disabled'),
            'blockingRaw' => self::attributeOrNull($element, 'blocking'),
            'blockingTokens' => $element->hasAttribute('blocking') ? self::spaceSeparatedTokens($element->getAttribute('blocking')) : [],
            'styleText' => $text,
            'styleTextLength' => strlen($text),
            'styleTextSha256' => hash('sha256', $text),
            'activeReviewPolicy' => 'inline-style-source',
        ] + self::activeContentNonceSummary($element) + self::styleLoadingReviewSummary($element);
    }

    /**
     * @return array<string, mixed>
     */
    private static function activeContentNonceSummary(\DOMElement $element): array
    {
        if (!$element->hasAttribute('nonce')) {
            return [];
        }

        $nonce = $element->getAttribute('nonce');

        return [
            'activeContentNonceReviewPolicy' => 'active-content-nonce-provenance-review',
            'activeContentNoncePresent' => true,
            'activeContentNonceByteLength' => strlen($nonce),
            'activeContentNonceSha256' => hash('sha256', $nonce),
            'activeContentNonceEmpty' => $nonce === '',
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function scriptAttributionSrcReviewSummary(\DOMElement $script): array
    {
        if (!$script->hasAttribute('attributionsrc')) {
            return [];
        }

        $raw = $script->getAttribute('attributionsrc');
        $urls = self::spaceSeparatedTokens($raw);
        $records = [];
        $unsafeUrls = [];
        $nonHttpUrls = [];
        $issues = [];

        if (trim($raw) === '') {
            $issues[] = ['code' => 'empty-script-attributionsrc'];
        }

        foreach ($urls as $url) {
            $urlSummary = self::hyperlinkUrlReviewSummary($url);
            $records[] = [
                'url' => $url,
                'kind' => $urlSummary['kind'],
                'scheme' => $urlSummary['scheme'],
                'unsafe' => $urlSummary['unsafe'],
            ];

            if ($urlSummary['unsafe'] === true) {
                $unsafeUrls[] = $url;
                $issues[] = [
                    'code' => 'unsafe-script-attributionsrc-url',
                    'url' => $url,
                    'scheme' => $urlSummary['scheme'],
                ];
                continue;
            }

            if ($urlSummary['kind'] === 'absolute' && !in_array($urlSummary['scheme'], ['http', 'https'], true)) {
                $nonHttpUrls[] = $url;
                $issues[] = [
                    'code' => 'non-http-script-attributionsrc-url',
                    'url' => $url,
                    'scheme' => $urlSummary['scheme'],
                ];
            }
        }
        $issueCodes = array_values(array_unique(array_map(
            static fn (array $issue): string => (string) ($issue['code'] ?? ''),
            $issues
        )));

        return [
            'scriptAttributionSrcReviewPolicy' => 'script-attributionsrc-provenance-review',
            'scriptAttributionSrcRequested' => true,
            'scriptAttributionSrcRaw' => $raw,
            'scriptAttributionSrcEmpty' => trim($raw) === '',
            'scriptAttributionSrcUrls' => $urls,
            'scriptAttributionSrcUrlCount' => count($urls),
            'scriptAttributionSrcUrlRecords' => $records,
            'unsafeScriptAttributionSrcUrls' => $unsafeUrls,
            'nonHttpScriptAttributionSrcUrls' => $nonHttpUrls,
            'scriptAttributionSrcIssues' => $issues,
            'scriptAttributionSrcIssueCodes' => $issueCodes,
            'scriptAttributionSrcIssueCount' => count($issues),
            'scriptAttributionSrcValid' => $issues === [],
        ];
    }

    /**
     * @return array{
     *     scriptPayloadKind:string,
     *     scriptExecutable:bool,
     *     scriptDataBlock:bool,
     *     scriptTypeKnown:bool
     * }
     */
    private static function scriptTypeSummary(?string $type): array
    {
        $javascriptTypes = [
            'application/ecmascript' => true,
            'application/javascript' => true,
            'application/x-ecmascript' => true,
            'application/x-javascript' => true,
            'text/ecmascript' => true,
            'text/javascript' => true,
            'text/javascript1.0' => true,
            'text/javascript1.1' => true,
            'text/javascript1.2' => true,
            'text/javascript1.3' => true,
            'text/javascript1.4' => true,
            'text/javascript1.5' => true,
            'text/jscript' => true,
            'text/livescript' => true,
            'text/x-ecmascript' => true,
            'text/x-javascript' => true,
        ];

        $normalized = $type === null ? '' : strtolower(trim(explode(';', $type, 2)[0]));
        $kind = match (true) {
            $normalized === '', isset($javascriptTypes[$normalized]) => 'classic',
            $normalized === 'module' => 'module',
            $normalized === 'importmap' => 'importmap',
            $normalized === 'speculationrules' => 'speculationrules',
            $normalized === 'application/json',
                $normalized === 'application/ld+json',
                str_ends_with($normalized, '+json') => 'json-data',
            default => 'data-block',
        };

        return [
            'scriptPayloadKind' => $kind,
            'scriptExecutable' => in_array($kind, ['classic', 'module'], true),
            'scriptDataBlock' => !in_array($kind, ['classic', 'module'], true),
            'scriptTypeKnown' => $kind !== 'data-block',
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function scriptLoadingReviewSummary(\DOMElement $script, string $payloadKind): array
    {
        $crossoriginRaw = self::attributeOrNull($script, 'crossorigin');
        $crossorigin = $crossoriginRaw === null ? null : self::htmlCorsSettingsAttributeState($crossoriginRaw);
        $fetchPriorityRaw = self::attributeOrNull($script, 'fetchpriority');
        $fetchPriority = $fetchPriorityRaw === null ? null : self::fetchPriorityState($fetchPriorityRaw);
        $referrerPolicyRaw = self::attributeOrNull($script, 'referrerpolicy');
        $referrerPolicy = $referrerPolicyRaw === null ? null : self::referrerPolicyState($referrerPolicyRaw);
        $blocking = self::htmlBlockingTokenSummary($script);
        $issues = [];

        $sourceKind = $script->hasAttribute('src') ? 'external' : 'inline';
        $loadingMode = match (true) {
            !in_array($payloadKind, ['classic', 'module'], true) => 'inert-data-block',
            $sourceKind === 'inline' => 'inline-executable',
            $script->hasAttribute('async') && $payloadKind === 'module' => 'async-module',
            $script->hasAttribute('async') => 'async-classic',
            $payloadKind === 'module' => 'module-deferred',
            $script->hasAttribute('defer') => 'defer-classic',
            default => 'parser-blocking-classic',
        };

        if ($crossoriginRaw !== null && $crossorigin === null) {
            $issues[] = ['code' => 'invalid-script-crossorigin', 'value' => $crossoriginRaw];
        }
        if ($fetchPriorityRaw !== null && $fetchPriority === null) {
            $issues[] = ['code' => 'invalid-script-fetchpriority', 'value' => $fetchPriorityRaw];
        }
        if ($referrerPolicyRaw !== null && $referrerPolicy === null) {
            $issues[] = ['code' => 'invalid-script-referrerpolicy', 'value' => $referrerPolicyRaw];
        }
        foreach ($blocking['invalid'] as $token) {
            $issues[] = ['code' => 'invalid-script-blocking-token', 'token' => $token];
        }
        foreach ($blocking['duplicates'] as $token) {
            $issues[] = [
                'code' => 'duplicate-script-blocking-token',
                'token' => $token,
                'count' => $blocking['tokenCounts'][$token] ?? 0,
            ];
        }

        return [
            'scriptLoadingReviewPolicy' => 'script-loading-metadata-review',
            'scriptLoadingMode' => $loadingMode,
            'scriptCrossoriginState' => $crossorigin,
            'scriptCrossoriginValid' => $crossoriginRaw === null ? null : $crossorigin !== null,
            'scriptReferrerPolicy' => $referrerPolicy,
            'scriptReferrerPolicyValid' => $referrerPolicyRaw === null ? null : $referrerPolicy !== null,
            'scriptFetchPriority' => $fetchPriority,
            'scriptFetchPriorityValid' => $fetchPriorityRaw === null ? null : $fetchPriority !== null,
            'scriptBlockingTokenCounts' => $blocking['tokenCounts'],
            'duplicateScriptBlockingTokens' => $blocking['duplicates'],
            'invalidScriptBlockingTokens' => $blocking['invalid'],
            'scriptBlockingAllTokensValid' => $blocking['invalid'] === [],
            'scriptLoadingIssues' => $issues,
            'scriptLoadingIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ))),
            'scriptLoadingPolicyValid' => $issues === [],
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function styleLoadingReviewSummary(\DOMElement $style): array
    {
        $blocking = self::htmlBlockingTokenSummary($style);
        $issues = [];
        foreach ($blocking['invalid'] as $token) {
            $issues[] = ['code' => 'invalid-style-blocking-token', 'token' => $token];
        }
        foreach ($blocking['duplicates'] as $token) {
            $issues[] = [
                'code' => 'duplicate-style-blocking-token',
                'token' => $token,
                'count' => $blocking['tokenCounts'][$token] ?? 0,
            ];
        }

        return [
            'styleLoadingPolicyReview' => 'style-loading-policy-metadata-review',
            'styleBlockingTokenCounts' => $blocking['tokenCounts'],
            'duplicateStyleBlockingTokens' => $blocking['duplicates'],
            'invalidStyleBlockingTokens' => $blocking['invalid'],
            'styleBlockingAllTokensValid' => $blocking['invalid'] === [],
            'styleLoadingIssues' => $issues,
            'styleLoadingIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ))),
        ];
    }

    /**
     * @return array{tokenCounts:array<string, int>, duplicates:list<string>, invalid:list<string>}
     */
    private static function htmlBlockingTokenSummary(\DOMElement $element): array
    {
        $tokens = $element->hasAttribute('blocking') ? self::spaceSeparatedTokens($element->getAttribute('blocking')) : [];
        $counts = [];
        $duplicates = [];
        $invalid = [];
        foreach ($tokens as $token) {
            $lower = strtolower($token);
            $counts[$lower] = ($counts[$lower] ?? 0) + 1;
            if ($counts[$lower] > 1 && !in_array($lower, $duplicates, true)) {
                $duplicates[] = $lower;
            }
            if ($lower !== 'render' && !in_array($lower, $invalid, true)) {
                $invalid[] = $lower;
            }
        }

        return [
            'tokenCounts' => $counts,
            'duplicates' => $duplicates,
            'invalid' => $invalid,
        ];
    }

    private static function htmlCorsSettingsAttributeState(string $value): ?string
    {
        $value = strtolower(trim($value));
        if ($value === '' || $value === 'anonymous') {
            return 'anonymous';
        }

        return $value === 'use-credentials' ? $value : null;
    }

    private static function fetchPriorityState(string $value): ?string
    {
        $value = strtolower(trim($value));

        return in_array($value, ['auto', 'high', 'low'], true) ? $value : null;
    }

    /**
     * @return array<string, mixed>
     */
    private static function scriptJsonReviewSummary(string $source, string $payloadKind): array
    {
        $summary = [
            'scriptJsonReviewPolicy' => 'script-json-inert-source-review',
            'scriptJsonParsed' => false,
            'scriptJsonType' => null,
            'scriptJsonObjectKeys' => [],
            'scriptJsonObjectKeyCount' => 0,
            'scriptJsonDiagnostics' => [],
        ];

        try {
            $json = json_decode($source, true, 512, JSON_THROW_ON_ERROR);
        } catch (\JsonException $exception) {
            $summary['scriptJsonDiagnostics'] = ['script-json-syntax-error'];
            $summary['scriptJsonError'] = $exception->getMessage();

            return $summary;
        }

        $summary['scriptJsonParsed'] = true;
        $summary['scriptJsonType'] = self::jsonValueKind($json);
        if (is_array($json) && !self::isJsonList($json)) {
            $summary['scriptJsonObjectKeys'] = array_values(array_map('strval', array_keys($json)));
            $summary['scriptJsonObjectKeyCount'] = count($summary['scriptJsonObjectKeys']);
        }

        $diagnostics = [];
        if ($payloadKind === 'importmap') {
            if (!is_array($json) || self::isJsonList($json)) {
                $diagnostics[] = 'importmap-top-level-not-object';
            } else {
                foreach (['imports', 'scopes', 'integrity'] as $key) {
                    if (array_key_exists($key, $json) && (!is_array($json[$key]) || self::isJsonList($json[$key]))) {
                        $diagnostics[] = 'importmap-' . $key . '-not-object';
                    }
                }
                $summary['importMapImportsCount'] = isset($json['imports']) && is_array($json['imports']) && !self::isJsonList($json['imports'])
                    ? count($json['imports'])
                    : 0;
                $summary['importMapScopesCount'] = isset($json['scopes']) && is_array($json['scopes']) && !self::isJsonList($json['scopes'])
                    ? count($json['scopes'])
                    : 0;
                $summary['importMapIntegrityCount'] = isset($json['integrity']) && is_array($json['integrity']) && !self::isJsonList($json['integrity'])
                    ? count($json['integrity'])
                    : 0;
            }
        }

        if ($payloadKind === 'speculationrules') {
            if (!is_array($json) || self::isJsonList($json)) {
                $diagnostics[] = 'speculationrules-top-level-not-object';
            } else {
                $ruleSetCounts = [];
                foreach (['prefetch', 'prerender'] as $key) {
                    if (!array_key_exists($key, $json)) {
                        continue;
                    }
                    if (!is_array($json[$key]) || !self::isJsonList($json[$key])) {
                        $diagnostics[] = 'speculationrules-' . $key . '-not-array';
                        $ruleSetCounts[$key] = null;
                        continue;
                    }
                    $ruleSetCounts[$key] = count($json[$key]);
                }
                $summary['speculationRuleSetNames'] = array_keys($ruleSetCounts);
                $summary['speculationRuleSetCounts'] = $ruleSetCounts;
            }
        }

        $summary['scriptJsonDiagnostics'] = $diagnostics;

        return $summary;
    }

    private static function jsonValueKind(mixed $value): string
    {
        return match (true) {
            is_array($value) && self::isJsonList($value) => 'array',
            is_array($value) => 'object',
            is_string($value) => 'string',
            is_int($value), is_float($value) => 'number',
            is_bool($value) => 'boolean',
            $value === null => 'null',
            default => 'unknown',
        };
    }

    private static function isJsonList(array $value): bool
    {
        if ($value === []) {
            return true;
        }

        return array_keys($value) === range(0, count($value) - 1);
    }

    /**
     * @return array<string, mixed>
     */
    private static function templateSummary(\DOMElement $element): array
    {
        $text = $element->textContent;

        $summary = [
            'template' => 'inert-source',
            'templateText' => $text,
            'templateTextLength' => strlen($text),
            'templateTextSha256' => hash('sha256', $text),
            'templateContainsMarkupLikeText' => preg_match('/<\s*[A-Za-z!\/?]/', $text) === 1,
            'templateContainsActiveLikeText' => preg_match('/<\s*(script|style|iframe|object|embed|link|meta)\b|<!doctype|<\?/i', $text) === 1,
            'templateReviewPolicy' => 'template-inert-escaped-source',
        ];

        return $summary
            + self::templateContentReviewSummary($text)
            + self::declarativeShadowRootSummary($element, $text);
    }

    /**
     * @return array<string, mixed>
     */
    private static function declarativeShadowRootSummary(\DOMElement $template, string $source): array
    {
        $modeRaw = self::attributeOrNull($template, 'shadowrootmode');
        if ($modeRaw === null) {
            return [];
        }

        $mode = strtolower(trim($modeRaw));
        $modeValid = in_array($mode, ['open', 'closed'], true);
        $host = $template->parentNode instanceof \DOMElement ? $template->parentNode : null;
        $slotReview = self::declarativeShadowRootSlotReview($source);
        $slots = $slotReview['slots'];
        $slotCounts = [];
        $slotNames = [];
        $namedSlotNames = [];
        $fallbackTexts = [];
        $invalidSlotNames = [];
        $defaultSlotCount = 0;

        foreach ($slots as $slot) {
            $name = (string) ($slot['slotName'] ?? '');
            $slotCounts[$name] = ($slotCounts[$name] ?? 0) + 1;
            if (($slot['slotDefault'] ?? false) === true) {
                ++$defaultSlotCount;
            } else {
                self::appendUniqueString($namedSlotNames, $name);
            }
            if (($slot['slotNameValid'] ?? true) !== true) {
                $invalidSlotNames[] = (string) ($slot['slotNameRaw'] ?? '');
            }
            $slotNames[] = $name;
            $fallbackTexts[] = (string) ($slot['slotFallbackText'] ?? '');
        }

        $diagnostics = $slotReview['diagnostics'];
        if (!$modeValid) {
            array_unshift($diagnostics, 'invalid-shadowrootmode');
        }
        if ($invalidSlotNames !== []) {
            $diagnostics[] = 'invalid-shadow-slot-name';
        }
        $duplicateSlotNames = self::duplicateShadowRootSlotNames($slotCounts);
        foreach ($duplicateSlotNames as $duplicateSlotName) {
            $diagnostics[] = 'duplicate-shadow-root-slot-name:' . $duplicateSlotName;
        }
        $diagnostics = array_values(array_unique($diagnostics));

        return [
            'declarativeShadowRoot' => true,
            'shadowRootReviewPolicy' => 'declarative-shadow-root-template-review',
            'shadowRootModeRaw' => $modeRaw,
            'shadowRootMode' => $modeValid ? $mode : null,
            'shadowRootModeValid' => $modeValid,
            'shadowRootDelegatesFocus' => $template->hasAttribute('shadowrootdelegatesfocus'),
            'shadowRootClonable' => $template->hasAttribute('shadowrootclonable'),
            'shadowRootSerializable' => $template->hasAttribute('shadowrootserializable'),
            'shadowRootCustomElementRegistry' => $template->hasAttribute('shadowrootcustomelementregistry'),
            'shadowRootHostTag' => $host instanceof \DOMElement ? self::htmlElementName($host) : null,
            'shadowRootHostId' => $host instanceof \DOMElement ? self::attributeOrNull($host, 'id') : null,
            'shadowRootSlotCount' => count($slots),
            'shadowRootDefaultSlotCount' => $defaultSlotCount,
            'shadowRootNamedSlotCount' => count($slots) - $defaultSlotCount,
            'shadowRootSlotNames' => $slotNames,
            'shadowRootNamedSlotNames' => $namedSlotNames,
            'shadowRootDuplicateSlotNames' => $duplicateSlotNames,
            'invalidShadowSlotNames' => $invalidSlotNames,
            'shadowRootSlotFallbackTexts' => $fallbackTexts,
            'shadowRootSlots' => $slots,
            'shadowRootDiagnostics' => $diagnostics,
        ];
    }

    /**
     * @param array<string, int> $slotCounts
     * @return list<string>
     */
    private static function duplicateShadowRootSlotNames(array $slotCounts): array
    {
        return array_values(array_filter(
            array_keys($slotCounts),
            static fn (string $name): bool => $slotCounts[$name] > 1
        ));
    }

    /**
     * @return array{slots:list<array<string, mixed>>, diagnostics:list<string>}
     */
    private static function declarativeShadowRootSlotReview(string $source): array
    {
        if (strlen($source) > self::TEMPLATE_CONTENT_REVIEW_MAX_BYTES) {
            return [
                'slots' => [],
                'diagnostics' => ['shadow-root-content-review-limit-exceeded'],
            ];
        }

        try {
            $fragment = self::loadHtmlFragment($source, 'declarative shadow root template content');
        } catch (\InvalidArgumentException) {
            return [
                'slots' => [],
                'diagnostics' => ['shadow-root-content-unsafe-or-unparseable'],
            ];
        }

        $root = self::requireFragmentRoot($fragment);
        $slots = [];
        foreach (self::descendantHtmlElements($root, 'slot') as $index => $slot) {
            $slots[] = ['index' => $index] + self::slotElementSummary($slot);
        }

        return [
            'slots' => $slots,
            'diagnostics' => [],
        ];
    }

    /**
     * @return array{raw:?string, name:string, default:bool, valid:bool}
     */
    private static function slotElementNameSummary(?string $value): array
    {
        $name = $value === null ? '' : trim($value);

        return [
            'raw' => $value,
            'name' => $name,
            'default' => $name === '',
            'valid' => $name === '' || self::isHtmlIdReferenceToken($name),
        ];
    }

    private static function isDeclarativeShadowRootTemplate(\DOMElement $element): bool
    {
        return $element->hasAttribute('shadowrootmode')
            || $element->hasAttribute('shadowrootdelegatesfocus')
            || $element->hasAttribute('shadowrootclonable')
            || $element->hasAttribute('shadowrootserializable')
            || $element->hasAttribute('shadowrootcustomelementregistry');
    }

    /**
     * @return array<string, mixed>
     */
    private static function templateShadowRootSummary(\DOMElement $template): array
    {
        $modeRaw = self::attributeOrNull($template, 'shadowrootmode');
        $mode = $modeRaw === null ? null : strtolower(trim($modeRaw));
        $modeValid = in_array($mode, ['open', 'closed'], true);
        $diagnostics = [];
        if (!$modeValid) {
            $diagnostics[] = [
                'code' => 'invalid-shadowroot-mode',
                'attribute' => 'shadowrootmode',
                'value' => $modeRaw,
            ];
        }

        $slots = [];
        $namedSlotNames = [];
        $defaultSlotCount = 0;
        $source = $template->textContent;
        $contentSlots = [];
        try {
            $contentDom = self::loadHtmlFragment($source, 'declarative shadow root template content');
            $contentRoot = self::requireFragmentRoot($contentDom);
            $contentSlots = self::descendantHtmlElements($contentRoot, 'slot');
        } catch (\InvalidArgumentException $exception) {
            $diagnostics[] = [
                'code' => 'shadowroot-template-content-unparseable',
                'message' => $exception->getMessage(),
            ];
        }

        foreach ($contentSlots as $slot) {
            $slotSummary = self::slotSummary($slot);
            $slots[] = [
                'nameRaw' => $slotSummary['slotNameRaw'],
                'name' => $slotSummary['slotName'],
                'nameValid' => $slotSummary['slotNameValid'],
                'fallbackText' => $slotSummary['slotFallbackText'],
                'fallbackElementNames' => $slotSummary['slotFallbackElementNames'],
            ];

            if (($slotSummary['slotNameRaw'] ?? null) === null) {
                ++$defaultSlotCount;
            }
            if (($slotSummary['slotName'] ?? null) !== null) {
                $namedSlotNames[] = (string) $slotSummary['slotName'];
            }
            foreach ($slotSummary['slotDiagnostics'] as $diagnostic) {
                $diagnostics[] = [
                    'code' => (string) ($diagnostic['code'] ?? ''),
                    'element' => 'slot',
                    'attribute' => $diagnostic['attribute'] ?? null,
                    'value' => $diagnostic['value'] ?? null,
                ];
            }
        }

        $aria = [];
        foreach (['aria-label', 'aria-description'] as $attribute) {
            if (!$template->hasAttribute($attribute)) {
                continue;
            }

            $value = self::safeHtmlReviewTextAttribute($template->getAttribute($attribute));
            $aria[$attribute] = [
                'raw' => $template->getAttribute($attribute),
                'value' => $value,
                'valid' => $value !== null,
            ];
            if ($value === null) {
                $diagnostics[] = [
                    'code' => 'invalid-shadowroot-accessibility-text',
                    'attribute' => $attribute,
                ];
            }
        }

        foreach (['aria-describedby', 'aria-labelledby'] as $attribute) {
            if (!$template->hasAttribute($attribute)) {
                continue;
            }

            $summary = self::idReferenceTokenSummary($template->getAttribute($attribute));
            $aria[$attribute] = $summary;
            if (!$summary['valid']) {
                $diagnostics[] = [
                    'code' => 'invalid-shadowroot-accessibility-idref',
                    'attribute' => $attribute,
                    'invalidTokens' => $summary['invalid'],
                ];
            }
        }

        return [
            'declarativeShadowRoot' => true,
            'shadowRootReviewPolicy' => 'declarative-shadow-root-review',
            'shadowRootModeRaw' => $modeRaw,
            'shadowRootMode' => $modeValid ? $mode : null,
            'shadowRootModeValid' => $modeValid,
            'shadowRootDelegatesFocus' => $template->hasAttribute('shadowrootdelegatesfocus'),
            'shadowRootClonable' => $template->hasAttribute('shadowrootclonable'),
            'shadowRootSerializable' => $template->hasAttribute('shadowrootserializable'),
            'shadowRootCustomElementRegistry' => $template->hasAttribute('shadowrootcustomelementregistry'),
            'shadowRootAccessibility' => $aria,
            'shadowRootSlotCount' => count($slots),
            'shadowRootDefaultSlotCount' => $defaultSlotCount,
            'shadowRootNamedSlotNames' => array_values(array_unique($namedSlotNames)),
            'shadowRootSlots' => $slots,
            'shadowRootDiagnostics' => $diagnostics,
            'shadowRootDiagnosticCodes' => array_values(array_unique(array_map(
                static fn (array $diagnostic): string => (string) ($diagnostic['code'] ?? ''),
                $diagnostics
            ))),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function slotSummary(\DOMElement $slot): array
    {
        $nameRaw = self::attributeOrNull($slot, 'name');
        $name = $nameRaw === null ? null : self::normalizeHtmlSlotName($nameRaw);
        $diagnostics = [];
        if ($nameRaw !== null && $name === null) {
            $diagnostics[] = [
                'code' => 'invalid-slot-name',
                'attribute' => 'name',
                'value' => $nameRaw,
            ];
        }

        $fallbackElementNames = [];
        foreach ($slot->childNodes as $child) {
            if ($child instanceof \DOMElement) {
                $fallbackElementNames[] = self::htmlElementName($child);
            }
        }

        return [
            'slot' => 'slot',
            'slotReviewPolicy' => 'slot-fallback-review',
            'slotNameRaw' => $nameRaw,
            'slotName' => $name,
            'slotNamed' => $nameRaw !== null,
            'slotNameValid' => $nameRaw === null ? null : $name !== null,
            'slotFallbackText' => self::normalizedText($slot),
            'slotFallbackElementNames' => $fallbackElementNames,
            'slotFallbackElementCount' => count($fallbackElementNames),
            'slotFallbackLinkHrefs' => array_values(array_filter(
                array_map(static fn (\DOMElement $link): ?string => self::attributeOrNull($link, 'href'), self::descendantHtmlElements($slot, 'a')),
                static fn (?string $href): bool => $href !== null && $href !== ''
            )),
            'slotFallbackImageSources' => array_values(array_filter(
                array_map(static fn (\DOMElement $image): ?string => self::attributeOrNull($image, 'src'), self::descendantHtmlElements($slot, 'img')),
                static fn (?string $src): bool => $src !== null && $src !== ''
            )),
            'slotDiagnostics' => $diagnostics,
            'slotDiagnosticCodes' => array_values(array_unique(array_map(
                static fn (array $diagnostic): string => (string) ($diagnostic['code'] ?? ''),
                $diagnostics
            ))),
        ];
    }

    private static function normalizeHtmlSlotName(string $name): ?string
    {
        $name = self::safeHtmlReviewTextAttribute($name);
        if ($name === null || strlen($name) > 128) {
            return null;
        }
        if (preg_match('/[\s<>"\'`{}\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/u', $name) === 1) {
            return null;
        }

        return $name;
    }

    private static function safeHtmlReviewTextAttribute(string $value): ?string
    {
        $value = preg_replace('/[ \t\r\n\f]+/u', ' ', $value) ?? $value;
        $value = trim($value);
        if ($value === '' || strlen($value) > 512) {
            return null;
        }
        if (preg_match('/[<>{}`\p{Cc}\p{Zl}\p{Zp}]/u', $value) === 1) {
            return null;
        }

        return $value;
    }

    /**
     * @return array<string, mixed>
     */
    private static function templateContentReviewSummary(string $source): array
    {
        $summary = [
            'templateContentReviewPolicy' => 'template-content-inert-fragment-review',
            'templateContentByteLength' => strlen($source),
            'templateContentSha256' => hash('sha256', $source),
            'templateContentParsed' => false,
            'templateContentDiagnostics' => [],
        ];

        if (strlen($source) > self::TEMPLATE_CONTENT_REVIEW_MAX_BYTES) {
            $summary['templateContentDiagnostics'] = ['template-content-review-limit-exceeded'];

            return $summary;
        }

        try {
            $fragment = self::loadHtmlFragment($source, 'template content fragment');
        } catch (\InvalidArgumentException $exception) {
            $summary['templateContentDiagnostics'] = ['template-content-unsafe-or-unparseable'];
            $summary['templateContentError'] = $exception->getMessage();

            return $summary;
        }

        $root = self::requireFragmentRoot($fragment);
        $text = self::normalizedInertHtmlFragmentText($source);
        $topLevelElementNames = [];
        foreach ($root->childNodes as $child) {
            if ($child instanceof \DOMElement) {
                $topLevelElementNames[] = self::htmlElementName($child);
            }
        }

        $summary['templateContentParsed'] = true;
        $summary['templateContentTopLevelElementNames'] = $topLevelElementNames;
        $summary['templateContentTopLevelElementCount'] = count($topLevelElementNames);
        $summary['templateContentTextLength'] = strlen($text);
        $summary['templateContentTextSha256'] = hash('sha256', $text);
        if ($text !== '') {
            $summary['templateContentText'] = $text;
        }
        $summary['templateContentLinkHrefs'] = self::inertHtmlFragmentAttributeValues($root, ['a', 'area'], 'href');
        $summary['templateContentImageSources'] = self::inertHtmlFragmentAttributeValues($root, ['img'], 'src');
        $forms = self::descendantHtmlElements($root, 'form');
        $summary['templateContentFormCount'] = count($forms);
        $summary['templateContentFormActions'] = array_values(array_filter(
            array_map(static fn (\DOMElement $form): ?string => self::attributeOrNull($form, 'action'), $forms),
            static fn (?string $action): bool => $action !== null && $action !== ''
        ));
        $summary['templateContentActiveElementNames'] = self::inertHtmlFragmentDescendantNames($root, ['script' => true, 'style' => true]);
        $summary['templateContentEmbeddedElementNames'] = self::inertHtmlFragmentDescendantNames($root, [
            'audio' => true,
            'canvas' => true,
            'embed' => true,
            'iframe' => true,
            'object' => true,
            'video' => true,
        ]);

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function noscriptSummary(\DOMElement $element): array
    {
        $text = $element->textContent;

        $summary = [
            'noscript' => 'fallback-source',
            'noscriptText' => $text,
            'noscriptTextLength' => strlen($text),
            'noscriptTextSha256' => hash('sha256', $text),
            'noscriptContainsMarkupLikeText' => preg_match('/<\s*[A-Za-z!\/?]/', $text) === 1,
            'noscriptContainsActiveLikeText' => preg_match('/<\s*(script|style|iframe|object|embed|link|meta)\b|<!doctype|<\?/i', $text) === 1,
            'noscriptReviewPolicy' => 'noscript-inert-escaped-source',
        ];

        return $summary + self::noscriptContentReviewSummary($text);
    }

    /**
     * @return array<string, mixed>
     */
    private static function noscriptContentReviewSummary(string $source): array
    {
        $summary = [
            'noscriptContentReviewPolicy' => 'noscript-content-inert-fragment-review',
            'noscriptContentByteLength' => strlen($source),
            'noscriptContentSha256' => hash('sha256', $source),
            'noscriptContentParsed' => false,
            'noscriptContentDiagnostics' => [],
        ];

        if (strlen($source) > self::NOSCRIPT_CONTENT_REVIEW_MAX_BYTES) {
            $summary['noscriptContentDiagnostics'] = ['noscript-content-review-limit-exceeded'];

            return $summary;
        }

        try {
            $fragment = self::loadHtmlFragment($source, 'noscript content fragment');
        } catch (\InvalidArgumentException $exception) {
            $summary['noscriptContentDiagnostics'] = ['noscript-content-unsafe-or-unparseable'];
            $summary['noscriptContentError'] = $exception->getMessage();

            return $summary;
        }

        $root = self::requireFragmentRoot($fragment);
        $text = self::normalizedInertHtmlFragmentText($source);
        $topLevelElementNames = [];
        foreach ($root->childNodes as $child) {
            if ($child instanceof \DOMElement) {
                $topLevelElementNames[] = self::htmlElementName($child);
            }
        }

        $summary['noscriptContentParsed'] = true;
        $summary['noscriptContentTopLevelElementNames'] = $topLevelElementNames;
        $summary['noscriptContentTopLevelElementCount'] = count($topLevelElementNames);
        $summary['noscriptContentTextLength'] = strlen($text);
        $summary['noscriptContentTextSha256'] = hash('sha256', $text);
        if ($text !== '') {
            $summary['noscriptContentText'] = $text;
        }
        $summary['noscriptContentLinkHrefs'] = self::inertHtmlFragmentAttributeValues($root, ['a', 'area'], 'href');
        $summary['noscriptContentImageSources'] = self::inertHtmlFragmentAttributeValues($root, ['img'], 'src');
        $forms = self::descendantHtmlElements($root, 'form');
        $summary['noscriptContentFormCount'] = count($forms);
        $summary['noscriptContentFormActions'] = array_values(array_filter(
            array_map(static fn (\DOMElement $form): ?string => self::attributeOrNull($form, 'action'), $forms),
            static fn (?string $action): bool => $action !== null && $action !== ''
        ));
        $summary['noscriptContentActiveElementNames'] = self::inertHtmlFragmentDescendantNames($root, ['script' => true, 'style' => true]);
        $summary['noscriptContentEmbeddedElementNames'] = self::inertHtmlFragmentDescendantNames($root, [
            'audio' => true,
            'canvas' => true,
            'embed' => true,
            'iframe' => true,
            'object' => true,
            'video' => true,
        ]);

        return $summary;
    }

    private static function normalizedInertHtmlFragmentText(string $source): string
    {
        try {
            $fragment = self::loadHtmlFragment($source, 'inert HTML fragment text review', protectRawTextContentForParse: true);
        } catch (\InvalidArgumentException) {
            return '';
        }

        $root = self::requireFragmentRoot($fragment);
        $raw = self::inertHtmlNodeText($root);
        $text = preg_replace('/[ \t\r\n\f]+/u', ' ', $raw) ?? $raw;

        return trim($text);
    }

    private static function inertHtmlNodeText(\DOMNode $node): string
    {
        if ($node instanceof \DOMText) {
            return $node->nodeValue ?? '';
        }

        if (!$node instanceof \DOMElement && !$node instanceof \DOMDocument && !$node instanceof \DOMDocumentFragment) {
            return '';
        }

        if ($node instanceof \DOMElement && self::isHtmlEscapedSourceTextElement(strtolower(self::htmlElementName($node)))) {
            return html_entity_decode($node->textContent, ENT_QUOTES | ENT_HTML5, 'UTF-8');
        }

        $text = '';
        foreach ($node->childNodes as $child) {
            $text .= self::inertHtmlNodeText($child);
        }

        return $text;
    }

    private static function isHtmlEscapedSourceTextElement(string $tagName): bool
    {
        return isset(self::HTML5_RAW_TEXT_ELEMENTS[$tagName])
            || in_array($tagName, ['xmp', 'noembed', 'noframes', 'title', 'textarea', 'plaintext', 'noscript', 'iframe', 'template'], true);
    }

    /**
     * @return array<string, mixed>
     */
    private static function textSemanticSummary(\DOMElement $element, string $name): array
    {
        $summary = [
            'textSemantic' => match ($name) {
                'abbr' => 'abbreviation',
                'b' => 'bring-attention',
                'bdi' => 'bidirectional-isolate',
                'bdo' => 'bidirectional-override',
                'code' => 'code',
                'dfn' => 'definition',
                'em' => 'stress-emphasis',
                'i' => 'idiomatic-offset',
                'kbd' => 'keyboard-input',
                'mark' => 'mark',
                's' => 'struck-text',
                'samp' => 'sample-output',
                'small' => 'side-comment',
                'strong' => 'strong-importance',
                'sub' => 'subscript',
                'sup' => 'superscript',
                'u' => 'unarticulated-annotation',
                'var' => 'variable',
                default => 'text',
            },
            'semanticTag' => $name,
            'semanticText' => self::normalizedText($element),
        ];

        if ($name === 'abbr') {
            $summary['abbreviationTitle'] = self::attributeOrNull($element, 'title');
            $summary += self::abbreviationTitleReviewSummary($element);
        }
        if ($name === 'dfn') {
            $summary['definitionTerm'] = self::normalizedText($element);
            $summary['definitionTitle'] = self::attributeOrNull($element, 'title');
            $summary += self::definitionTermReviewSummary($element);
        }
        if ($name === 'bdi' || $name === 'bdo') {
            if ($name === 'bdi' && !$element->hasAttribute('dir')) {
                $summary['textDirection'] = 'auto';
                $summary['textDirectionImplicitDefault'] = true;
            } else {
                $direction = strtolower(trim($element->getAttribute('dir')));
                $summary['textDirection'] = in_array($direction, ['auto', 'ltr', 'rtl'], true) ? $direction : null;
            }
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function abbreviationTitleReviewSummary(\DOMElement $abbr): array
    {
        $titleRaw = self::attributeOrNull($abbr, 'title');
        $title = $titleRaw === null ? null : trim($titleRaw);
        $text = self::normalizedText($abbr);
        $issueCodes = [];

        if ($titleRaw === null) {
            $issueCodes[] = 'missing-abbreviation-title';
        } elseif ($title === '') {
            $issueCodes[] = 'empty-abbreviation-title';
        } elseif ($title === $text) {
            $issueCodes[] = 'redundant-abbreviation-title';
        }

        return [
            'abbreviationReviewPolicy' => 'html-abbreviation-title-review',
            'abbreviationText' => $text,
            'abbreviationTitlePresent' => $titleRaw !== null,
            'abbreviationTitleEmpty' => $titleRaw !== null && $title === '',
            'abbreviationExpansion' => $title === null || $title === '' ? null : $title,
            'abbreviationTitleMatchesText' => $title !== null && $title !== '' && $title === $text,
            'abbreviationIssueCodes' => $issueCodes,
            'abbreviationIssues' => array_map(
                static fn (string $code): array => ['code' => $code],
                $issueCodes
            ),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function definitionTermReviewSummary(\DOMElement $dfn): array
    {
        $titleRaw = self::attributeOrNull($dfn, 'title');
        $title = $titleRaw === null ? null : trim($titleRaw);
        $text = self::normalizedText($dfn);
        $childAbbreviation = self::definitionChildAbbreviationReviewSummary($dfn);
        $issueCodes = [];
        $source = 'text-content';
        $resolvedTerm = $text === '' ? null : $text;

        if ($titleRaw !== null) {
            $source = 'title-attribute';
            $resolvedTerm = $title === '' ? null : $title;
            if ($title === '') {
                $issueCodes[] = 'empty-definition-title';
            }
        } elseif ($childAbbreviation !== null && ($childAbbreviation['titleRaw'] ?? null) !== null) {
            $source = 'child-abbr-title';
            $childTitle = trim((string) ($childAbbreviation['titleRaw'] ?? ''));
            $resolvedTerm = $childTitle === '' ? null : $childTitle;
            if ($childTitle === '') {
                $issueCodes[] = 'empty-definition-child-abbr-title';
            }
        } elseif ($resolvedTerm === null) {
            $issueCodes[] = 'empty-definition-term';
        }

        return [
            'definitionReviewPolicy' => 'html-definition-term-source-review',
            'definitionResolvedTerm' => $resolvedTerm,
            'definitionTermSource' => $source,
            'definitionTitlePresent' => $titleRaw !== null,
            'definitionTitleEmpty' => $titleRaw !== null && $title === '',
            'definitionChildAbbreviationText' => $childAbbreviation['text'] ?? null,
            'definitionChildAbbreviationTitle' => $childAbbreviation['titleRaw'] ?? null,
            'definitionIssueCodes' => $issueCodes,
            'definitionIssues' => array_map(
                static fn (string $code): array => ['code' => $code],
                $issueCodes
            ),
        ];
    }

    /**
     * @return array{text:string, titleRaw:?string}|null
     */
    private static function definitionChildAbbreviationReviewSummary(\DOMElement $dfn): ?array
    {
        $elementChildren = [];
        $hasNonWhitespaceText = false;
        foreach ($dfn->childNodes as $child) {
            if ($child instanceof \DOMElement) {
                $elementChildren[] = $child;
                continue;
            }
            if ($child instanceof \DOMText && trim($child->textContent) !== '') {
                $hasNonWhitespaceText = true;
            }
        }

        if ($hasNonWhitespaceText || count($elementChildren) !== 1) {
            return null;
        }

        $child = $elementChildren[0];
        if (strtolower(self::htmlElementName($child)) !== 'abbr') {
            return null;
        }

        return [
            'text' => self::normalizedText($child),
            'titleRaw' => self::attributeOrNull($child, 'title'),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function preformattedSummary(\DOMElement $pre): array
    {
        $code = self::firstChildHtmlElement($pre, 'code');
        $source = $code instanceof \DOMElement ? $code : $pre;
        $text = $source->textContent;

        return [
            'preformatted' => 'pre',
            'codeBlock' => $code instanceof \DOMElement ? 'pre-code' : 'pre',
            'codeBlockSourceElement' => self::htmlElementName($source),
            'codeText' => $text,
            'codeTextLength' => strlen($text),
            'codeTextSha256' => hash('sha256', $text),
            'codeStartsWithNewline' => str_starts_with($text, "\n") || str_starts_with($text, "\r"),
            'codeEndsWithNewline' => str_ends_with($text, "\n") || str_ends_with($text, "\r"),
            'codeLineCount' => self::preformattedLineCount($text),
        ] + self::codeLanguageSummary($source);
    }

    /**
     * @return array{codeLanguage:?string, codeLanguageSource:string, codeLanguageToken:?string, codeClassTokens:list<string>}
     */
    private static function codeLanguageSummary(\DOMElement $element): array
    {
        $classRaw = self::attributeOrNull($element, 'class');
        $classTokens = $classRaw === null ? [] : self::spaceSeparatedTokens($classRaw);
        foreach ($classTokens as $token) {
            if (preg_match('/^(?:language|lang)-(.+)$/i', $token, $matches) !== 1) {
                continue;
            }

            $language = strtolower((string) $matches[1]);
            if (!self::isSafeHtmlSemanticMetadataToken($language)) {
                continue;
            }

            return [
                'codeLanguage' => $language,
                'codeLanguageSource' => 'class-token',
                'codeLanguageToken' => $token,
                'codeClassTokens' => $classTokens,
            ];
        }

        $dataLanguage = self::attributeOrNull($element, 'data-language');
        $language = $dataLanguage === null ? null : strtolower(trim($dataLanguage));
        if ($language !== null && $language !== '' && self::isSafeHtmlSemanticMetadataToken($language)) {
            return [
                'codeLanguage' => $language,
                'codeLanguageSource' => 'data-language',
                'codeLanguageToken' => null,
                'codeClassTokens' => $classTokens,
            ];
        }

        return [
            'codeLanguage' => null,
            'codeLanguageSource' => 'missing',
            'codeLanguageToken' => null,
            'codeClassTokens' => $classTokens,
        ];
    }

    private static function preformattedLineCount(string $text): int
    {
        $normalized = str_replace(["\r\n", "\r"], "\n", $text);
        $trimmed = rtrim($normalized, "\n");
        if ($trimmed === '') {
            return 0;
        }

        return substr_count($trimmed, "\n") + 1;
    }

    /**
     * @return array<string, mixed>
     */
    private static function dataElementSummary(\DOMElement $element): array
    {
        $value = self::attributeOrNull($element, 'value');

        return [
            'dataElement' => 'data',
            'dataText' => self::normalizedText($element),
            'dataValueRaw' => $value,
            'dataValue' => $value === null ? null : trim($value),
            'dataValueSource' => $value === null ? 'missing' : 'value-attribute',
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function timeSummary(\DOMElement $element): array
    {
        $text = self::normalizedText($element);
        $raw = self::attributeOrNull($element, 'datetime');
        $source = $raw === null
            ? ($text === '' ? 'missing' : 'text')
            : 'datetime-attribute';
        $candidate = $raw ?? $text;
        $summary = [
            'time' => 'time',
            'timeElement' => true,
            'timeText' => $text,
            'timeDatetimeRaw' => $raw,
            'timeDatetimeSource' => $source,
            'timeDatetime' => null,
            'timeDatetimeKind' => $source === 'missing' ? 'missing' : null,
            'timeDatetimeValid' => false,
            'timeValueRaw' => $candidate,
            'timeValue' => null,
            'timeValueKind' => null,
            'timeValueValid' => false,
        ];

        if ($source === 'missing') {
            return $summary;
        }

        $datetime = self::timeDatetimeSummary($candidate);
        if ($datetime === null) {
            $summary['timeDatetimeKind'] = 'invalid';
            $summary['timeValueKind'] = 'invalid';

            return $summary;
        }

        $summary['timeDatetime'] = $datetime['value'];
        $summary['timeDatetimeKind'] = $datetime['kind'];
        $summary['timeDatetimeValid'] = true;
        $summary['timeValue'] = $datetime['value'];
        $summary['timeValueKind'] = $datetime['kind'];
        $summary['timeValueValid'] = true;

        return $summary;
    }

    /**
     * @return array{kind:string, value:string}|null
     */
    private static function timeDatetimeSummary(string $value): ?array
    {
        $value = trim($value);
        if ($value === '' || strlen($value) > 128 || preg_match('/[<>{}`]/', $value) === 1) {
            return null;
        }

        $datePattern = '([0-9]{4})-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])';
        $timePattern = '((?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9](?:\.[0-9]{1,3})?)?)';
        $timezonePattern = '([Zz]|[+-](?:[01][0-9]|2[0-3]):?[0-5][0-9])';

        if (preg_match('/^' . $datePattern . '[T ]' . $timePattern . $timezonePattern . '$/', $value, $matches) === 1) {
            if (!self::isValidDateParts((string) $matches[1], (string) $matches[2], (string) $matches[3])) {
                return null;
            }

            return [
                'kind' => 'global-datetime',
                'value' => (string) $matches[1] . '-' . (string) $matches[2] . '-' . (string) $matches[3]
                    . 'T' . (string) $matches[4]
                    . self::normalizeTimezone((string) $matches[5]),
            ];
        }

        if (preg_match('/^' . $datePattern . '[T ]' . $timePattern . '$/', $value, $matches) === 1) {
            if (!self::isValidDateParts((string) $matches[1], (string) $matches[2], (string) $matches[3])) {
                return null;
            }

            return [
                'kind' => 'local-datetime',
                'value' => (string) $matches[1] . '-' . (string) $matches[2] . '-' . (string) $matches[3]
                    . 'T' . (string) $matches[4],
            ];
        }

        if (preg_match('/^' . $datePattern . '$/', $value, $matches) === 1) {
            if (!self::isValidDateParts((string) $matches[1], (string) $matches[2], (string) $matches[3])) {
                return null;
            }

            return [
                'kind' => 'date',
                'value' => (string) $matches[1] . '-' . (string) $matches[2] . '-' . (string) $matches[3],
            ];
        }

        if (preg_match('/^([0-9]{4})-(0[1-9]|1[0-2])$/', $value, $matches) === 1) {
            return ['kind' => 'month', 'value' => (string) $matches[1] . '-' . (string) $matches[2]];
        }

        if (preg_match('/^([0-9]{4})-W(0[1-9]|[1-4][0-9]|5[0-3])$/', $value, $matches) === 1) {
            $year = (int) $matches[1];
            $week = (int) $matches[2];
            $date = (new \DateTimeImmutable())->setISODate($year, $week, 1);
            if ((int) $date->format('o') !== $year || (int) $date->format('W') !== $week) {
                return null;
            }

            return ['kind' => 'week', 'value' => (string) $matches[1] . '-W' . (string) $matches[2]];
        }

        if (preg_match('/^[0-9]{4}$/', $value) === 1) {
            return ['kind' => 'year', 'value' => $value];
        }

        if (preg_match('/^' . $timePattern . $timezonePattern . '$/', $value, $matches) === 1) {
            return [
                'kind' => 'global-time',
                'value' => (string) $matches[1] . self::normalizeTimezone((string) $matches[2]),
            ];
        }

        if (preg_match('/^' . $timePattern . '$/', $value, $matches) === 1) {
            return ['kind' => 'time', 'value' => (string) $matches[1]];
        }

        $duration = self::timeDurationSummary($value);
        if ($duration !== null) {
            return ['kind' => 'duration', 'value' => $duration];
        }

        return null;
    }

    private static function timeDurationSummary(string $value): ?string
    {
        $duration = strtoupper($value);
        if ($duration === '' || preg_match('/^[P0-9YMWDTHS.]+$/', $duration) !== 1) {
            return null;
        }

        if (preg_match('/^P[0-9]+W$/', $duration) === 1) {
            return $duration;
        }

        if (str_contains($duration, 'W')) {
            return null;
        }

        if (preg_match('/^P(?=.*[0-9])(?:[0-9]+Y)?(?:[0-9]+M)?(?:[0-9]+D)?(?:T(?:[0-9]+H)?(?:[0-9]+M)?(?:[0-9]+(?:\.[0-9]{1,3})?S)?)?$/', $duration) !== 1) {
            return null;
        }

        if (str_ends_with($duration, 'T')) {
            return null;
        }

        return $duration;
    }

    /**
     * @return array<string, mixed>
     */
    private static function quoteSummary(\DOMElement $element, string $name): array
    {
        if ($name === 'cite') {
            $text = self::normalizedText($element);

            return [
                'citedWork' => 'cite',
                'citedWorkText' => $text,
                'citation' => 'cite',
                'citationText' => $text,
            ];
        }

        $cite = self::attributeOrNull($element, 'cite');
        $footer = $name === 'blockquote' ? self::firstChildHtmlElement($element, 'footer') : null;
        $citationTexts = array_values(array_map(
            static fn (\DOMElement $citation): string => self::normalizedText($citation),
            self::descendantHtmlElements($element, 'cite'),
        ));

        return [
            'quote' => $name === 'blockquote' ? 'block' : 'inline',
            'quoteTag' => $name,
            'quoteCite' => $cite,
            'quoteCiteRaw' => $cite,
            'quoteCiteNormalized' => $cite === null ? null : trim($cite),
            'quoteText' => self::normalizedText($element),
            'attributionText' => $footer instanceof \DOMElement ? self::normalizedText($footer) : null,
            'citationTexts' => $citationTexts,
            'citationCount' => count($citationTexts),
        ] + self::quoteCiteReviewSummary($cite);
    }

    /**
     * @return array<string, mixed>
     */
    private static function quoteCiteReviewSummary(?string $cite): array
    {
        $url = self::hyperlinkUrlReviewSummary($cite);
        $issues = [];
        if (($url['unsafe'] ?? false) === true) {
            $issues[] = [
                'code' => 'unsafe-quote-cite',
                'cite' => $cite,
                'scheme' => $url['scheme'],
            ];
        }

        return [
            'quoteCitationUrlReview' => 'quote-cite',
            'quoteCitePresent' => $cite !== null && trim($cite) !== '',
            'quoteCiteKind' => $url['kind'],
            'quoteCiteScheme' => $url['scheme'],
            'quoteCiteUnsafe' => $url['unsafe'],
            'quoteCiteIssues' => $issues,
            'quoteCiteIssueCodes' => array_values(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            )),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function figureSummary(\DOMElement $element, string $name): array
    {
        if ($name === 'figure') {
            $captions = self::childHtmlElements($element, 'figcaption');

            return [
                'figurePart' => 'figure',
                'captionText' => isset($captions[0]) ? self::normalizedText($captions[0]) : null,
                'captionCount' => count($captions),
            ];
        }

        return [
            'figurePart' => 'caption',
            'captionText' => self::normalizedText($element),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function tableElementSummary(\DOMElement $element, string $name): array
    {
        if ($name === 'table') {
            $captions = self::childHtmlElements($element, 'caption');

            $summary = [
                'tablePart' => 'table',
                'captionText' => isset($captions[0]) ? self::normalizedText($captions[0]) : null,
                'captionCount' => count($captions),
            ];

            return $summary + self::tableHeaderAssociationSummary($element);
        }

        if ($name === 'caption') {
            return [
                'tablePart' => 'caption',
                'captionText' => self::normalizedText($element),
            ];
        }

        if ($name === 'colgroup') {
            return [
                'tablePart' => 'column-group',
                'spanRaw' => self::attributeOrNull($element, 'span'),
                'span' => self::positiveIntegerAttribute($element, 'span', 1, 1000),
            ];
        }

        if ($name === 'col') {
            return [
                'tablePart' => 'column',
                'spanRaw' => self::attributeOrNull($element, 'span'),
                'span' => self::positiveIntegerAttribute($element, 'span', 1, 1000),
            ];
        }

        if (in_array($name, ['thead', 'tbody', 'tfoot'], true)) {
            return [
                'tablePart' => match ($name) {
                    'thead' => 'header-group',
                    'tfoot' => 'footer-group',
                    default => 'body-group',
                },
            ];
        }

        if ($name === 'tr') {
            return ['tablePart' => 'row'];
        }

        if ($name === 'td' || $name === 'th') {
            $headersRaw = self::attributeOrNull($element, 'headers');
            $headers = $headersRaw === null ? [] : self::spaceSeparatedTokens($headersRaw);
            $summary = [
                'tablePart' => 'cell',
                'tableCell' => $name === 'th' ? 'header' : 'data',
                'colSpanRaw' => self::attributeOrNull($element, 'colspan'),
                'colSpan' => self::positiveIntegerAttribute($element, 'colspan', 1, 1000),
                'rowSpanRaw' => self::attributeOrNull($element, 'rowspan'),
                'rowSpan' => self::nonNegativeIntegerAttribute($element, 'rowspan', 1, 65534),
                'headersRaw' => $headersRaw,
                'headers' => $headers,
            ];
            if ($headersRaw !== null) {
                $summary += self::tableHeaderReferenceSummary($element, $headersRaw);
            }

            if ($name === 'th') {
                $summary['scopeRaw'] = self::attributeOrNull($element, 'scope');
                $summary['scope'] = self::tableHeaderScope($element);
                $summary['abbr'] = self::attributeOrNull($element, 'abbr');
            }

            return $summary;
        }

        return [];
    }

    /**
     * @return array<string, mixed>
     */
    private static function tableHeaderAssociationSummary(\DOMElement $table): array
    {
        $headersById = [];
        $headerIds = [];
        $headerCellCount = 0;
        $dataCellCount = 0;
        $headerReferenceCells = [];
        $elementIndex = 0;

        foreach ($table->getElementsByTagName('*') as $candidate) {
            if (!$candidate instanceof \DOMElement) {
                continue;
            }

            $candidateTable = self::nearestHtmlTable($candidate);
            if (!$candidateTable instanceof \DOMElement || !$candidateTable->isSameNode($table)) {
                continue;
            }

            ++$elementIndex;
            $candidateName = self::htmlElementName($candidate);
            if ($candidateName === 'td') {
                ++$dataCellCount;
            }
            if (($candidateName === 'td' || $candidateName === 'th') && $candidate->hasAttribute('headers')) {
                $headerReferenceCells[] = $candidate;
            }
            if ($candidateName !== 'th') {
                continue;
            }

            ++$headerCellCount;
            $id = self::normalizedNonEmptyAttribute(self::attributeOrNull($candidate, 'id'));
            if ($id === null) {
                continue;
            }

            if (!isset($headersById[$id])) {
                $headerIds[] = $id;
            }
            $headersById[$id][] = [
                'id' => $id,
                'text' => self::normalizedText($candidate),
                'scope' => self::tableHeaderScope($candidate),
                'abbr' => self::attributeOrNull($candidate, 'abbr'),
                'index' => $elementIndex,
            ];
        }

        $duplicateHeaderIds = [];
        $tableHeaderIssues = [];
        foreach ($headersById as $id => $headers) {
            if (count($headers) < 2) {
                continue;
            }

            $duplicateHeaderIds[] = $id;
            $tableHeaderIssues[] = [
                'code' => 'duplicate-table-header-id',
                'headerId' => $id,
                'count' => count($headers),
                'texts' => array_map(
                    static fn (array $header): string => (string) ($header['text'] ?? ''),
                    $headers
                ),
            ];
        }

        $referencedIds = [];
        $duplicateReferenceIds = [];
        $invalidReferenceTokens = [];
        $resolvedReferenceIds = [];
        $missingReferenceIds = [];
        $nonHeaderReferenceIds = [];
        $duplicateHeaderTargetIds = [];
        $referenceIssues = [];
        foreach ($headerReferenceCells as $cell) {
            $headersRaw = self::attributeOrNull($cell, 'headers');
            if ($headersRaw === null) {
                continue;
            }

            $reference = self::tableHeaderReferenceSummary($cell, $headersRaw);
            foreach ($reference['headerReferenceIds'] as $id) {
                self::appendUniqueString($referencedIds, $id);
            }
            foreach ($reference['duplicateHeaderReferenceIds'] as $id) {
                self::appendUniqueString($duplicateReferenceIds, $id);
            }
            foreach ($reference['invalidHeaderReferenceTokens'] as $token) {
                self::appendUniqueString($invalidReferenceTokens, $token);
            }
            foreach ($reference['resolvedHeaderReferenceIds'] as $id) {
                self::appendUniqueString($resolvedReferenceIds, $id);
            }
            foreach ($reference['missingHeaderReferenceIds'] as $id) {
                self::appendUniqueString($missingReferenceIds, $id);
            }
            foreach ($reference['nonHeaderReferenceIds'] as $id) {
                self::appendUniqueString($nonHeaderReferenceIds, $id);
            }
            foreach ($reference['duplicateHeaderTargetIds'] as $id) {
                self::appendUniqueString($duplicateHeaderTargetIds, $id);
            }
            array_push($referenceIssues, ...$reference['headerReferenceIssues']);
        }

        $tableHeaderReferenceIssues = array_merge($tableHeaderIssues, $referenceIssues);

        return [
            'tableHeaderCellCount' => $headerCellCount,
            'tableDataCellCount' => $dataCellCount,
            'tableHeaderIds' => $headerIds,
            'duplicateTableHeaderIds' => $duplicateHeaderIds,
            'tableDuplicateHeaderIds' => $duplicateHeaderIds,
            'tableHeaderIssues' => $tableHeaderIssues,
            'tableHeaderIssueCodes' => array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $tableHeaderIssues
            ),
            'explicitHeaderReferenceCellCount' => count($headerReferenceCells),
            'explicitHeaderReferenceIds' => $referencedIds,
            'duplicateHeaderReferenceIds' => $duplicateReferenceIds,
            'invalidHeaderReferenceTokens' => $invalidReferenceTokens,
            'resolvedHeaderReferenceIds' => $resolvedReferenceIds,
            'missingHeaderReferenceIds' => $missingReferenceIds,
            'nonHeaderReferenceIds' => $nonHeaderReferenceIds,
            'duplicateHeaderTargetIds' => $duplicateHeaderTargetIds,
            'tableHeaderReferenceIssueCount' => count($tableHeaderReferenceIssues),
            'tableHeaderReferenceIssues' => $tableHeaderReferenceIssues,
            'tableHeaderReferenceIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $tableHeaderReferenceIssues
            ))),
            'tableHeaderReferencesResolved' => $tableHeaderReferenceIssues === [],
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function tableHeaderReferenceSummary(\DOMElement $cell, string $headersRaw): array
    {
        $tokens = self::spaceSeparatedTokens($headersRaw);
        $ids = [];
        $invalid = [];
        $duplicateReferences = [];
        $resolved = [];
        $missing = [];
        $nonHeader = [];
        $duplicateTargets = [];
        $references = [];
        $issues = [];
        $resolvedTargets = [];
        $seen = [];

        foreach ($tokens as $index => $token) {
            $record = [
                'index' => $index,
                'token' => $token,
                'state' => 'unresolved',
            ];
            $firstIndex = $seen[$token] ?? null;
            if ($firstIndex === null) {
                $seen[$token] = $index;
            } else {
                $record['duplicateToken'] = true;
                $record['firstIndex'] = $firstIndex;
                if (self::isHtmlIdReferenceToken($token) && !in_array($token, $duplicateReferences, true)) {
                    $duplicateReferences[] = $token;
                }
                $issues[] = [
                    'code' => 'duplicate-table-header-reference-token',
                    'token' => $token,
                    'index' => $index,
                    'firstIndex' => $firstIndex,
                ];
            }

            if (!self::isHtmlIdReferenceToken($token)) {
                if (!in_array($token, $invalid, true)) {
                    $invalid[] = $token;
                }
                $record['state'] = 'invalid-token';
                $issues[] = [
                    'code' => 'invalid-table-header-reference-token',
                    'token' => $token,
                    'index' => $index,
                ];
                $references[] = $record;
                continue;
            }

            if (!in_array($token, $ids, true)) {
                $ids[] = $token;
            }

            $targets = self::nearestTableElementsById($cell, $token);
            if ($targets === []) {
                if (!in_array($token, $missing, true)) {
                    $missing[] = $token;
                }
                $record += [
                    'state' => 'missing-target',
                    'targetState' => 'missing',
                    'targetCount' => 0,
                    'headerTargetCount' => 0,
                    'duplicateHeaderTargetCount' => 0,
                    'nonHeaderTargetCount' => 0,
                    'headerTargets' => [],
                    'nonHeaderTargets' => [],
                    'nonHeaderTargetNames' => [],
                ];
                $issues[] = [
                    'code' => 'missing-table-header-target',
                    'token' => $token,
                    'index' => $index,
                ];
                $references[] = $record;
                continue;
            }

            $headerTargets = [];
            $nonHeaderTargets = [];
            foreach ($targets as $target) {
                if (self::htmlElementName($target) === 'th') {
                    $headerTargets[] = $target;
                    continue;
                }

                $nonHeaderTargets[] = [
                    'name' => self::htmlElementName($target),
                    'id' => self::attributeOrNull($target, 'id'),
                    'text' => self::normalizedText($target),
                ];
            }

            if ($nonHeaderTargets !== []) {
                if (!in_array($token, $nonHeader, true)) {
                    $nonHeader[] = $token;
                }
                $issues[] = [
                    'code' => 'non-header-table-header-target',
                    'token' => $token,
                    'index' => $index,
                    'targetNames' => array_values(array_unique(array_map(
                        static fn (array $target): string => (string) ($target['name'] ?? ''),
                        $nonHeaderTargets,
                    ))),
                    'targetTexts' => array_map(
                        static fn (array $target): string => (string) ($target['text'] ?? ''),
                        $nonHeaderTargets,
                    ),
                ];
            }

            if ($headerTargets === []) {
                $record += [
                    'state' => 'non-header-target',
                    'targetState' => 'non-header-target',
                    'targetCount' => count($targets),
                    'headerTargetCount' => 0,
                    'duplicateHeaderTargetCount' => 0,
                    'nonHeaderTargetCount' => count($nonHeaderTargets),
                    'headerTargets' => [],
                    'nonHeaderTargets' => $nonHeaderTargets,
                    'nonHeaderTargetNames' => array_values(array_unique(array_map(
                        static fn (array $target): string => (string) ($target['name'] ?? ''),
                        $nonHeaderTargets,
                    ))),
                ];
                $references[] = $record;
                continue;
            }

            $targetSummaries = array_map(
                static fn (\DOMElement $target): array => self::tableHeaderReferenceHeaderTargetSummary($target),
                $headerTargets
            );
            $headerCount = count($targetSummaries);
            $nonHeaderCount = count($nonHeaderTargets);
            $state = $nonHeaderCount > 0
                ? 'resolved-with-non-header-target'
                : ($headerCount > 1 ? 'duplicate-header-id' : 'resolved');
            $targetState = $nonHeaderCount > 0
                ? 'mixed-targets'
                : ($headerCount > 1 ? 'duplicate-header-target-id' : 'resolved');

            if ($targetState === 'resolved' && !in_array($token, $resolved, true)) {
                $resolved[] = $token;
            }

            if ($headerCount > 1) {
                if (!in_array($token, $duplicateTargets, true)) {
                    $duplicateTargets[] = $token;
                }
                $issues[] = [
                    'code' => 'duplicate-table-header-id',
                    'token' => $token,
                    'index' => $index,
                    'targetCount' => $headerCount,
                    'targetTexts' => array_map(
                        static fn (array $target): string => (string) ($target['text'] ?? ''),
                        $targetSummaries,
                    ),
                ];
            }

            foreach ($targetSummaries as $targetSummary) {
                $resolvedTargets[] = [
                    'referenceIndex' => $index,
                    'token' => $token,
                ] + $targetSummary;
            }

            $record += [
                'state' => $state,
                'targetState' => $targetState,
                'targetCount' => count($targets),
                'headerTargetCount' => $headerCount,
                'duplicateHeaderTargetCount' => $headerCount > 1 ? $headerCount : 0,
                'nonHeaderTargetCount' => $nonHeaderCount,
                'targets' => $targetSummaries,
                'headerTargets' => $targetSummaries,
                'nonHeaderTargets' => $nonHeaderTargets,
                'nonHeaderTargetNames' => array_values(array_unique(array_map(
                    static fn (array $target): string => (string) ($target['name'] ?? ''),
                    $nonHeaderTargets,
                ))),
                'targetTexts' => array_map(
                    static fn (array $target): string => (string) ($target['text'] ?? ''),
                    $targetSummaries,
                ),
                'targetScopes' => array_map(
                    static fn (array $target): ?string => $target['scope'] ?? null,
                    $targetSummaries,
                ),
            ];

            if ($headerCount === 1) {
                $record['targetId'] = $targetSummaries[0]['id'];
                $record['targetText'] = $targetSummaries[0]['text'];
                $record['targetScope'] = $targetSummaries[0]['scope'];
                $record['targetAbbr'] = $targetSummaries[0]['abbr'];
            }

            $references[] = $record;
        }

        return [
            'headerReferenceReviewPolicy' => 'nearest-table-th-idref-review',
            'headerReferenceIds' => $ids,
            'invalidHeaderReferenceTokens' => $invalid,
            'duplicateHeaderReferenceIds' => $duplicateReferences,
            'resolvedHeaderReferenceIds' => $resolved,
            'missingHeaderReferenceIds' => $missing,
            'nonHeaderReferenceIds' => $nonHeader,
            'duplicateHeaderTargetIds' => $duplicateTargets,
            'headerReferences' => $references,
            'resolvedHeaderIds' => array_map(
                static fn (array $target): ?string => $target['id'] ?? null,
                $resolvedTargets,
            ),
            'resolvedHeaderTexts' => array_map(
                static fn (array $target): string => (string) ($target['text'] ?? ''),
                $resolvedTargets,
            ),
            'resolvedHeaderTargets' => $resolvedTargets,
            'headerReferenceIssues' => $issues,
            'headerReferenceIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues,
            ))),
            'headerReferencesResolved' => $tokens !== []
                && $invalid === []
                && $duplicateReferences === []
                && $missing === []
                && $nonHeader === []
                && $duplicateTargets === [],
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function tableHeaderReferenceHeaderTargetSummary(\DOMElement $header): array
    {
        return [
            'id' => self::attributeOrNull($header, 'id'),
            'text' => self::normalizedText($header),
            'scopeRaw' => self::attributeOrNull($header, 'scope'),
            'scope' => self::tableHeaderScope($header),
            'abbr' => self::attributeOrNull($header, 'abbr'),
            'colSpanRaw' => self::attributeOrNull($header, 'colspan'),
            'colSpan' => self::positiveIntegerAttribute($header, 'colspan', 1, 1000),
            'rowSpanRaw' => self::attributeOrNull($header, 'rowspan'),
            'rowSpan' => self::nonNegativeIntegerAttribute($header, 'rowspan', 1, 65534),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function listSummary(\DOMElement $element, string $name): array
    {
        if ($name === 'li') {
            return [
                'listItem' => true,
            ] + self::listItemOrdinalSummary($element);
        }

        if ($name === 'ol') {
            $startRaw = self::attributeOrNull($element, 'start');

            return [
                'list' => 'ordered',
                'reversed' => $element->hasAttribute('reversed'),
                'startRaw' => $startRaw,
                'start' => self::integerAttribute($element, 'start', 1),
                'markerType' => self::attributeOrNull($element, 'type'),
            ];
        }

        $summary = [
            'list' => $name === 'menu' ? 'menu' : 'unordered',
            'markerType' => self::attributeOrNull($element, 'type'),
        ];

        return $name === 'menu'
            ? $summary + self::menuCommandListSummary($element)
            : $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function menuCommandListSummary(\DOMElement $menu): array
    {
        $items = [];
        $commandControls = [];

        foreach (self::childHtmlElements($menu, 'li') as $index => $item) {
            $commands = self::menuItemCommandControlSummaries($item);
            $items[] = [
                'index' => $index,
                'text' => self::normalizedText($item),
                'commandControlCount' => count($commands),
                'commandLabels' => array_values(array_map(
                    static fn (array $command): string => (string) ($command['label'] ?? ''),
                    $commands
                )),
                'commands' => $commands,
            ];
            array_push($commandControls, ...$commands);
        }

        return [
            'menuReview' => 'command-list',
            'menuItemCount' => count($items),
            'menuCommandItemCount' => count(array_filter(
                $items,
                static fn (array $item): bool => (int) ($item['commandControlCount'] ?? 0) > 0
            )),
            'menuCommandControlCount' => count($commandControls),
            'menuCommandLabels' => array_values(array_map(
                static fn (array $command): string => (string) ($command['label'] ?? ''),
                $commandControls
            )),
            'menuCommandControls' => $commandControls,
            'menuItems' => $items,
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function menuItemCommandControlSummaries(\DOMElement $item): array
    {
        $commands = [];
        foreach ($item->getElementsByTagName('*') as $candidate) {
            if (!$candidate instanceof \DOMElement) {
                continue;
            }

            $name = self::htmlElementName($candidate);
            if ($name === 'button') {
                $type = self::buttonType($candidate);
                $summary = [
                    'tag' => 'button',
                    'type' => $type,
                    'id' => self::attributeOrNull($candidate, 'id'),
                    'name' => self::attributeOrNull($candidate, 'name'),
                    'value' => $candidate->getAttribute('value'),
                    'label' => self::normalizedText($candidate),
                    'disabled' => $candidate->hasAttribute('disabled'),
                    'effectiveDisabled' => self::isEffectivelyDisabledFormControl($candidate),
                    'submitButton' => self::isButtonSubmitButton($candidate),
                ];

                $commands[] = $summary + self::buttonCommandSummary($candidate);
                continue;
            }

            if ($name !== 'input') {
                continue;
            }

            $type = self::inputType($candidate);
            if (!in_array($type, ['button', 'image', 'reset', 'submit'], true)) {
                continue;
            }

            $value = $candidate->getAttribute('value');
            $label = $value !== '' ? $value : self::attributeOrNull($candidate, 'alt');
            $commands[] = [
                'tag' => 'input',
                'type' => $type,
                'id' => self::attributeOrNull($candidate, 'id'),
                'name' => self::attributeOrNull($candidate, 'name'),
                'value' => $value,
                'label' => $label,
                'disabled' => $candidate->hasAttribute('disabled'),
                'effectiveDisabled' => self::isEffectivelyDisabledFormControl($candidate),
                'submitButton' => self::isInputSubmitterType($type),
            ];
        }

        return $commands;
    }

    /**
     * @return array{valueRaw:?string, value:?int, listOrdinal:?int, listOrdinalSource:?string}
     */
    private static function listItemOrdinalSummary(\DOMElement $item): array
    {
        $valueRaw = self::attributeOrNull($item, 'value');
        $value = self::integerAttribute($item, 'value', null);
        $summary = [
            'valueRaw' => $valueRaw,
            'value' => $value,
            'listOrdinal' => null,
            'listOrdinalSource' => null,
        ];

        $parent = $item->parentNode;
        if (!$parent instanceof \DOMElement || self::htmlElementName($parent) !== 'ol') {
            return $summary;
        }

        $items = self::childHtmlElements($parent, 'li');
        $reversed = $parent->hasAttribute('reversed');
        $start = self::integerAttribute($parent, 'start', null);
        $current = $start ?? ($reversed ? count($items) : 1);
        $implicitSource = $start !== null ? 'start-attribute' : ($reversed ? 'reversed-count' : 'default-start');

        foreach ($items as $child) {
            $childValue = self::integerAttribute($child, 'value', null);
            $ordinal = $childValue ?? $current;
            if ($child->isSameNode($item)) {
                $summary['listOrdinal'] = $ordinal;
                $summary['listOrdinalSource'] = $childValue !== null ? 'value-attribute' : $implicitSource;

                return $summary;
            }

            $current = $ordinal + ($reversed ? -1 : 1);
            $implicitSource = $childValue !== null ? 'previous-value' : $implicitSource;
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function definitionListSummary(\DOMElement $element, string $name): array
    {
        if ($name === 'dt') {
            return [
                'definitionListPart' => 'term',
                'termText' => self::normalizedText($element),
            ];
        }

        if ($name === 'dd') {
            return [
                'definitionListPart' => 'definition',
                'definitionText' => self::normalizedText($element),
            ];
        }

        $items = self::definitionListItems($element);
        $terms = [];
        $definitions = [];
        foreach ($items as $item) {
            array_push($terms, ...$item['terms']);
            array_push($definitions, ...$item['definitions']);
        }

        return [
            'definitionList' => 'dl',
            'termCount' => count($terms),
            'definitionCount' => count($definitions),
            'itemCount' => count($items),
            'terms' => $terms,
            'definitions' => $definitions,
            'items' => $items,
        ];
    }

    /**
     * @return list<array{terms:list<string>, definitions:list<string>, termCount:int, definitionCount:int}>
     */
    private static function definitionListItems(\DOMElement $definitionList): array
    {
        $items = [];
        $terms = [];
        $definitions = [];

        foreach ($definitionList->childNodes as $child) {
            if (!$child instanceof \DOMElement) {
                continue;
            }

            $name = strtolower(self::htmlElementName($child));
            if ($name === 'dt') {
                if ($definitions !== []) {
                    $items[] = self::definitionListItemSummary($terms, $definitions);
                    $terms = [];
                    $definitions = [];
                }

                $terms[] = self::normalizedText($child);
                continue;
            }

            if ($name === 'dd') {
                $definitions[] = self::normalizedText($child);
            }
        }

        if ($terms !== [] || $definitions !== []) {
            $items[] = self::definitionListItemSummary($terms, $definitions);
        }

        return $items;
    }

    /**
     * @param list<string> $terms
     * @param list<string> $definitions
     * @return array{terms:list<string>, definitions:list<string>, termCount:int, definitionCount:int}
     */
    private static function definitionListItemSummary(array $terms, array $definitions): array
    {
        return [
            'terms' => $terms,
            'definitions' => $definitions,
            'termCount' => count($terms),
            'definitionCount' => count($definitions),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function globalHtmlAttributeSummary(\DOMElement $element): array
    {
        $summary = [];
        $attributes = self::htmlAttributes($element);

        if (array_key_exists('id', $attributes)) {
            $summary['elementId'] = $attributes['id'];
            $summary += self::htmlDocumentIdReviewSummary($element, $attributes['id']);
        }

        if (array_key_exists('class', $attributes)) {
            $summary += self::classAttributeSummary($attributes['class']);
        }

        $dataAttributes = self::dataAttributeSummary($attributes);
        if ($dataAttributes !== []) {
            $summary['dataAttributes'] = $dataAttributes;
            $summary['dataset'] = self::datasetSummary($dataAttributes);
        }

        $ariaAttributes = self::ariaAttributeSummary($attributes);
        if ($ariaAttributes !== []) {
            $summary['ariaAttributes'] = $ariaAttributes;
            $ariaReferences = self::ariaReferenceSummary($element, $ariaAttributes);
            if ($ariaReferences !== []) {
                $summary['ariaReferences'] = $ariaReferences;
                $summary['ariaReferenceAttributes'] = array_keys($ariaReferences);
                $summary['ariaReferenceCount'] = count($ariaReferences);
                $summary += self::ariaReferenceAggregateSummary($ariaReferences);
            }
        }

        if (array_key_exists('role', $attributes)) {
            $role = self::htmlRoleAttributeSummary($attributes['role']);
            $summary['roleAttributeReviewPolicy'] = 'html-role-token-list-review';
            $summary['roleRaw'] = $attributes['role'];
            $summary['roles'] = $role['tokens'];
            $summary['roleNames'] = $role['names'];
            $summary['roleTokenCounts'] = $role['counts'];
            $summary['invalidRoleTokens'] = $role['invalid'];
            $summary['duplicateRoleTokens'] = $role['duplicates'];
            $summary['roleTokenCount'] = count($role['tokens']);
            $summary['roleNameCount'] = count($role['names']);
            $summary['invalidRoleTokenCount'] = count($role['invalid']);
            $summary['duplicateRoleTokenCount'] = count($role['duplicates']);
            $summary['primaryRole'] = $role['primary'];
            $summary['roleEmpty'] = $role['tokens'] === [];
            $summary['roleHasDuplicates'] = $role['duplicates'] !== [];
            $summary['roleValid'] = $role['valid'];
        }

        $microdata = self::microdataAttributeSummary($element, $attributes);
        if ($microdata !== []) {
            $summary += $microdata;
        }

        $rdfa = self::rdfaAttributeSummary($attributes);
        if ($rdfa !== []) {
            $summary += $rdfa;
        }

        $language = self::htmlLanguageAttributeSummary($attributes);
        if ($language !== []) {
            $summary += $language;
        }

        $summary += self::effectiveLanguageSummary($element, $attributes);

        if (array_key_exists('dir', $attributes)) {
            $dir = self::htmlDirectionState($attributes['dir']);
            $summary['directionTokenReviewPolicy'] = 'html-dir-token-review';
            $summary['dirRaw'] = $attributes['dir'];
            $summary['direction'] = $dir;
            $summary['directionKeyword'] = $dir;
            $summary['directionValid'] = $dir !== null;
            $summary['directionAuto'] = $dir === 'auto';
            $summary['directionInvalidValueIgnored'] = $dir === null;
        }

        $summary += self::effectiveDirectionSummary($element, $attributes);

        if (array_key_exists('title', $attributes)) {
            $summary['titleAttribute'] = $attributes['title'];
        }

        $summary += self::effectiveTitleAttributeSummary($element, $attributes);
        $summary += self::effectiveTitleSummary($element, $attributes);

        if (array_key_exists('style', $attributes)) {
            $summary += self::styleAttributeSummary($attributes['style']);
        }

        if (array_key_exists('nonce', $attributes)) {
            $summary += self::htmlNonceSummary($element, $attributes['nonce']);
        }

        if (array_key_exists('hidden', $attributes)) {
            $hiddenKeyword = self::hiddenKeyword($attributes['hidden']);
            $summary['hiddenRaw'] = $attributes['hidden'];
            $summary['hiddenKeyword'] = $hiddenKeyword;
            $summary['hiddenState'] = $hiddenKeyword ?? 'hidden';
            $summary['hiddenValid'] = $hiddenKeyword !== null;
            $summary['hiddenInvalidValueDefaulted'] = $hiddenKeyword === null;
        }

        $summary += self::effectiveHiddenSummary($element, $attributes);

        if (array_key_exists('inert', $attributes)) {
            $summary['inertRaw'] = $attributes['inert'];
            $summary['inert'] = true;
        }

        $summary += self::effectiveInertSummary($element, $attributes);

        if (array_key_exists('translate', $attributes)) {
            $translate = self::htmlTranslateState($attributes['translate']);
            $summary['translateRaw'] = $attributes['translate'];
            $summary['translate'] = $translate;
            $summary['translateValid'] = $translate !== null;
        }

        $summary += self::effectiveTranslateSummary($element, $attributes);

        if (array_key_exists('contenteditable', $attributes)) {
            $contentEditable = self::contentEditableState($attributes['contenteditable']);
            $summary['contentEditableRaw'] = $attributes['contenteditable'];
            $summary['contentEditable'] = $contentEditable;
            $summary['contentEditableValid'] = $contentEditable !== null;
        }

        $summary += self::effectiveContentEditableSummary($element, $attributes);

        if (array_key_exists('draggable', $attributes)) {
            $summary += self::draggableAttributeSummary($element, $attributes['draggable']);
        }

        if (array_key_exists('dropzone', $attributes)) {
            $dropZone = self::dropZoneSummary($attributes['dropzone']);
            $summary['dropZoneReviewPolicy'] = 'html-dropzone-attribute-review';
            $summary['dropZoneRaw'] = $attributes['dropzone'];
            $summary['dropZoneTokens'] = $dropZone['tokens'];
            $summary['dropZoneItems'] = $dropZone['items'];
            $summary['dropZoneEffects'] = $dropZone['effects'];
            $summary['dropZoneStringTypes'] = $dropZone['stringTypes'];
            $summary['dropZoneFileTypes'] = $dropZone['fileTypes'];
            $summary['invalidDropZoneTokens'] = $dropZone['invalid'];
            $summary['dropZoneMultipleEffects'] = $dropZone['multipleEffects'];
            $summary['dropZoneValid'] = $dropZone['valid'];
        }

        if (array_key_exists('spellcheck', $attributes)) {
            $spellcheck = self::htmlSpellcheckState($attributes['spellcheck']);
            $summary['spellcheckRaw'] = $attributes['spellcheck'];
            $summary['spellcheck'] = $spellcheck;
            $summary['spellcheckValid'] = $spellcheck !== null;
        }

        $summary += self::effectiveSpellcheckSummary($element, $attributes);

        if (array_key_exists('slot', $attributes)) {
            $slot = self::slotAttributeSummary($attributes['slot']);
            $summary['slotRaw'] = $attributes['slot'];
            $summary['slotName'] = $slot['name'];
            $summary['slotValid'] = $slot['valid'];
        }

        if (array_key_exists('part', $attributes)) {
            $parts = self::partTokenListSummary($attributes['part']);
            $summary['partReviewPolicy'] = 'html-part-token-list-review';
            $summary['partRaw'] = $attributes['part'];
            $summary['partTokens'] = $parts['tokens'];
            $summary['partNames'] = $parts['names'];
            $summary['invalidPartTokens'] = $parts['invalid'];
            $summary['duplicatePartTokens'] = $parts['duplicates'];
            $summary['partIssueCodes'] = $parts['issueCodes'];
            $summary['partValid'] = $parts['valid'];
        }

        if (array_key_exists('exportparts', $attributes)) {
            $exportParts = self::exportPartsSummary($attributes['exportparts']);
            $summary['exportPartsReviewPolicy'] = 'html-exportparts-mapping-review';
            $summary['exportPartsRaw'] = $attributes['exportparts'];
            $summary['exportParts'] = $exportParts['items'];
            $summary['exportPartNames'] = $exportParts['names'];
            $summary['exportPartAliases'] = $exportParts['aliases'];
            $summary['invalidExportParts'] = $exportParts['invalid'];
            $summary['duplicateExportPartNames'] = $exportParts['duplicateNames'];
            $summary['duplicateExportPartAliases'] = $exportParts['duplicateAliases'];
            $summary['exportPartsIssueCodes'] = $exportParts['issueCodes'];
            $summary['exportPartsValid'] = $exportParts['valid'];
        }

        if (array_key_exists('part', $attributes) || array_key_exists('exportparts', $attributes)) {
            $summary += self::partExportReviewSummary($element, $attributes);
        }

        if (array_key_exists('is', $attributes)) {
            $custom = self::customElementNameSummary($attributes['is']);
            $summary['isRaw'] = $attributes['is'];
            $summary['customElementName'] = $custom['name'];
            $summary['customElementValid'] = $custom['valid'];
        }

        if (array_key_exists('accesskey', $attributes)) {
            $accessKey = self::accessKeySummary($attributes['accesskey']);
            $summary['accessKeyRaw'] = $attributes['accesskey'];
            $summary['accessKeyTokens'] = $accessKey['tokens'];
            $summary['accessKeys'] = $accessKey['keys'];
            $summary['invalidAccessKeyTokens'] = $accessKey['invalid'];
            $summary['duplicateAccessKeyTokens'] = $accessKey['duplicates'];
            $summary['accessKeyValid'] = $accessKey['valid'];
            $summary += self::accessKeyDocumentSummary($element, $accessKey['keys']);
            if ($accessKey['keys'] !== []) {
                $summary += self::accessKeyCollisionSummary($element, $accessKey['keys']);
            }
            $summary['accessKeyIssueCodes'] = self::accessKeyIssueCodes($summary);
        }

        if (array_key_exists('autofocus', $attributes)) {
            $summary['autofocusRaw'] = $attributes['autofocus'];
            $summary['autofocus'] = true;
            $summary += self::autofocusReviewSummary($element);
        }

        if (array_key_exists('tabindex', $attributes)) {
            $summary['tabIndexRaw'] = $attributes['tabindex'];
            $summary['tabIndex'] = self::integerAttribute($element, 'tabindex', null);
            $summary['tabIndexValid'] = $summary['tabIndex'] !== null;
            $summary['tabIndexIssueCodes'] = $summary['tabIndexValid'] ? [] : ['invalid-tabindex-token'];
        }

        $summary += self::focusNavigationReviewSummary($summary, $attributes);

        if (array_key_exists('inputmode', $attributes)) {
            $inputMode = self::inputModeState($attributes['inputmode']);
            $summary['inputModeRaw'] = $attributes['inputmode'];
            $summary['inputMode'] = $inputMode;
            $summary['inputModeValid'] = $inputMode !== null;
        }

        if (array_key_exists('enterkeyhint', $attributes)) {
            $enterKeyHint = self::enterKeyHintState($attributes['enterkeyhint']);
            $summary['enterKeyHintRaw'] = $attributes['enterkeyhint'];
            $summary['enterKeyHint'] = $enterKeyHint;
            $summary['enterKeyHintValid'] = $enterKeyHint !== null;
        }

        if (array_key_exists('inputmode', $attributes) || array_key_exists('enterkeyhint', $attributes)) {
            $summary += self::inputHintReviewSummary($element, $attributes);
        }

        if (array_key_exists('autocapitalize', $attributes)) {
            $autocapitalize = self::autocapitalizeState($attributes['autocapitalize']);
            $summary['autocapitalizeRaw'] = $attributes['autocapitalize'];
            $summary['autocapitalize'] = $autocapitalize;
            $summary['autocapitalizeValid'] = $autocapitalize !== null;
        }

        $summary += self::effectiveAutocapitalizeSummary($element, $attributes);

        if (array_key_exists('autocorrect', $attributes)) {
            $autocorrect = self::autocorrectState($attributes['autocorrect']);
            $summary['autocorrectRaw'] = $attributes['autocorrect'];
            $summary['autocorrect'] = $autocorrect;
            $summary['autocorrectValid'] = $autocorrect !== null;
        }

        if (array_key_exists('writingsuggestions', $attributes)) {
            $writingSuggestions = self::writingSuggestionsState($attributes['writingsuggestions']);
            $summary['writingSuggestionsRaw'] = $attributes['writingsuggestions'];
            $summary['writingSuggestions'] = $writingSuggestions;
            $summary['writingSuggestionsValid'] = $writingSuggestions !== null;
        }

        if (array_key_exists('virtualkeyboardpolicy', $attributes)) {
            $virtualKeyboardPolicy = self::virtualKeyboardPolicyState($attributes['virtualkeyboardpolicy']);
            $summary['virtualKeyboardPolicyRaw'] = $attributes['virtualkeyboardpolicy'];
            $summary['virtualKeyboardPolicy'] = $virtualKeyboardPolicy;
            $summary['virtualKeyboardPolicyValid'] = $virtualKeyboardPolicy !== null;
        }

        if (
            array_key_exists('autocorrect', $attributes)
            || array_key_exists('writingsuggestions', $attributes)
            || array_key_exists('virtualkeyboardpolicy', $attributes)
        ) {
            $summary += self::editAssistanceReviewSummary($element, $attributes);
        }

        if (array_key_exists('anchor', $attributes)) {
            $summary += self::anchorPositioningSummary($element, $attributes['anchor']);
        }

        if (array_key_exists('popover', $attributes)) {
            $popover = self::popoverState($attributes['popover']);
            $summary['popoverRaw'] = $attributes['popover'];
            $summary['popoverState'] = $popover;
            $summary['popoverValid'] = $popover !== null;
        }

        if (array_key_exists('popovertarget', $attributes)) {
            $targetRaw = $attributes['popovertarget'];
            $target = self::popoverTarget($targetRaw);
            $summary['popoverTargetRaw'] = $attributes['popovertarget'];
            $summary['popoverTarget'] = $target;
            $summary['popoverTargetValid'] = $target !== null;
            $summary += self::popoverTargetReferenceSummary($element, $targetRaw, $target);
        }

        if (array_key_exists('popovertarget', $attributes) || array_key_exists('popovertargetaction', $attributes)) {
            $actionRaw = $attributes['popovertargetaction'] ?? '';
            $action = self::popoverTargetAction($actionRaw);
            $summary['popoverTargetActionRaw'] = $attributes['popovertargetaction'] ?? null;
            $summary['popoverTargetAction'] = $action;
            $summary['popoverTargetActionValid'] = $action !== null;
            $summary['popoverTargetActionDefaulted'] = !array_key_exists('popovertargetaction', $attributes);
        }

        return $summary;
    }

    /**
     * @param array<string, mixed> $summary
     * @param array<string, string> $attributes
     * @return array<string, mixed>
     */
    private static function focusNavigationReviewSummary(array $summary, array $attributes): array
    {
        $focusAttributes = [];
        foreach (['accesskey', 'autofocus', 'tabindex'] as $attribute) {
            if (array_key_exists($attribute, $attributes)) {
                $focusAttributes[] = $attribute;
            }
        }

        if ($focusAttributes === []) {
            return [];
        }

        $issueCodes = [];
        foreach (['accessKeyIssueCodes', 'tabIndexIssueCodes', 'autofocusIssueCodes', 'autofocusOrderIssueCodes'] as $field) {
            $codes = $summary[$field] ?? [];
            if (!is_array($codes)) {
                continue;
            }

            foreach ($codes as $code) {
                if (is_string($code) && $code !== '' && !in_array($code, $issueCodes, true)) {
                    $issueCodes[] = $code;
                }
            }
        }

        return [
            'focusNavigationReviewPolicy' => 'html-focus-navigation-review',
            'focusNavigationAttributes' => $focusAttributes,
            'focusNavigationIssueCodes' => $issueCodes,
            'focusNavigationValid' => $issueCodes === [],
        ];
    }

    /**
     * @return array{classAttributeReviewPolicy:string, classRaw:string, classList:list<string>, classTokenCounts:array<string, int>, classNames:list<string>, duplicateClassTokens:list<string>, classTokenCount:int, uniqueClassTokenCount:int, duplicateClassTokenCount:int, classEmpty:bool, classHasDuplicates:bool}
     */
    private static function classAttributeSummary(string $value): array
    {
        $tokens = self::spaceSeparatedTokens($value);
        $counts = [];
        $names = [];
        $duplicates = [];

        foreach ($tokens as $token) {
            if (!array_key_exists($token, $counts)) {
                $counts[$token] = 0;
                $names[] = $token;
            }

            ++$counts[$token];
            if ($counts[$token] === 2) {
                $duplicates[] = $token;
            }
        }

        $issueCodes = [];
        if ($tokens === []) {
            $issueCodes[] = 'empty-html-class-attribute';
        }
        if ($duplicates !== []) {
            $issueCodes[] = 'duplicate-html-class-token';
        }

        return [
            'classAttributeReviewPolicy' => 'html-class-token-review',
            'classReviewPolicy' => 'html-class-token-review',
            'classRaw' => $value,
            'classList' => $tokens,
            'classTokenCounts' => $counts,
            'classNames' => $names,
            'classUniqueTokens' => $names,
            'duplicateClassTokens' => $duplicates,
            'classTokenCount' => count($tokens),
            'uniqueClassTokenCount' => count($names),
            'classUniqueTokenCount' => count($names),
            'duplicateClassTokenCount' => count($duplicates),
            'classEmpty' => trim($value) === '',
            'classHasDuplicates' => $duplicates !== [],
            'classHasDuplicateTokens' => $duplicates !== [],
            'classIssueCodes' => $issueCodes,
        ];
    }

    /**
     * @param array<string, string> $attributes
     * @return array<string, mixed>
     */
    private static function effectiveHiddenSummary(\DOMElement $element, array $attributes): array
    {
        if (array_key_exists('hidden', $attributes)) {
            return self::hiddenProvenanceSummary($element, $attributes['hidden'], false);
        }

        for ($ancestor = $element->parentNode; $ancestor instanceof \DOMElement; $ancestor = $ancestor->parentNode) {
            $ancestorAttributes = self::htmlAttributes($ancestor);
            if (array_key_exists('hidden', $ancestorAttributes)) {
                return self::hiddenProvenanceSummary($ancestor, $ancestorAttributes['hidden'], true);
            }
        }

        return [];
    }

    /**
     * @return array<string, mixed>
     */
    private static function hiddenProvenanceSummary(\DOMElement $source, string $raw, bool $inherited): array
    {
        $keyword = self::hiddenKeyword($raw);
        $state = $keyword ?? 'hidden';
        $summary = [
            'hiddenReviewPolicy' => 'html-hidden-state-inheritance-review',
            'effectiveHiddenRaw' => $raw,
            'effectiveHiddenKeyword' => $keyword,
            'effectiveHiddenState' => $state,
            'effectiveHidden' => true,
            'effectiveHiddenUntilFound' => $state === 'until-found',
            'effectiveHiddenInvalidValueDefaulted' => $keyword === null,
            'hiddenInherited' => $inherited,
            'hiddenSource' => $inherited ? 'ancestor-hidden' : 'self-hidden',
            'hiddenSourceElement' => self::htmlElementName($source),
        ];

        $sourceId = self::attributeOrNull($source, 'id');
        if ($sourceId !== null && $sourceId !== '') {
            $summary['hiddenSourceElementId'] = $sourceId;
        }

        return $summary;
    }

    private static function hiddenKeyword(string $value): ?string
    {
        $hidden = strtolower(trim($value));

        return match ($hidden) {
            '', 'hidden' => 'hidden',
            'until-found' => 'until-found',
            default => null,
        };
    }

    /**
     * @param array<string, string> $attributes
     * @return array<string, mixed>
     */
    private static function effectiveTitleAttributeSummary(\DOMElement $element, array $attributes): array
    {
        if (array_key_exists('title', $attributes)) {
            return self::titleAttributeProvenanceSummary($element, $attributes['title'], false);
        }

        for ($ancestor = $element->parentNode; $ancestor instanceof \DOMElement; $ancestor = $ancestor->parentNode) {
            $ancestorAttributes = self::htmlAttributes($ancestor);
            if (array_key_exists('title', $ancestorAttributes)) {
                return self::titleAttributeProvenanceSummary($ancestor, $ancestorAttributes['title'], true);
            }
        }

        return [];
    }

    /**
     * @return array<string, mixed>
     */
    private static function titleAttributeProvenanceSummary(\DOMElement $source, string $raw, bool $inherited): array
    {
        $text = self::normalizedAttributeText($raw);
        $empty = $text === '';
        $summary = [
            'titleAttributeReviewPolicy' => 'html-title-advisory-inheritance-review',
            'effectiveTitleAttributeRaw' => $raw,
            'effectiveTitleAttribute' => $empty ? null : $text,
            'titleAttributeEmpty' => $empty,
            'titleAttributeInherited' => $inherited,
            'titleAttributeSource' => $inherited ? 'ancestor-title' : 'self-title',
            'titleAttributeSourceElement' => self::htmlElementName($source),
            'titleAttributeInheritanceBlocked' => $empty,
        ];

        $sourceId = self::attributeOrNull($source, 'id');
        if ($sourceId !== null && $sourceId !== '') {
            $summary['titleAttributeSourceElementId'] = $sourceId;
        }

        return $summary;
    }

    private static function normalizedAttributeText(string $value): string
    {
        return preg_replace('/\s+/u', ' ', trim($value)) ?? trim($value);
    }

    /**
     * @return array<string, mixed>
     */
    private static function htmlNonceSummary(\DOMElement $element, string $value): array
    {
        $trimmed = trim($value);
        $hasAsciiWhitespace = preg_match('/[\t\n\f\r ]/', $value) === 1;
        $base64Candidate = $trimmed !== '' && preg_match('/^[A-Za-z0-9+\/_-]+={0,2}$/', $trimmed) === 1;
        $sameValueElements = self::nonceSameValueElementRecords($element, $value);
        $sameValueElementNames = [];
        $sameValueElementIds = [];
        $issues = [];
        $reviewCodes = [];

        foreach ($sameValueElements as $record) {
            self::appendUniqueString($sameValueElementNames, (string) $record['element']);
            $id = $record['id'] ?? null;
            if (is_string($id) && $id !== '') {
                self::appendUniqueString($sameValueElementIds, $id);
            }
        }

        if ($trimmed === '') {
            $issues[] = 'empty-html-nonce';
            $reviewCodes[] = 'empty-nonce';
        }
        if ($hasAsciiWhitespace) {
            $issues[] = 'html-nonce-ascii-whitespace';
            $reviewCodes[] = 'whitespace-nonce';
        }
        if ($trimmed !== '' && !$base64Candidate) {
            $issues[] = 'html-nonce-non-base64-candidate';
        }
        if (count($sameValueElements) > 1) {
            $reviewCodes[] = 'shared-nonce-in-fragment';
        }

        return [
            'nonceReviewPolicy' => 'html-nonce-token-review',
            'noncePresent' => true,
            'nonceEmpty' => $trimmed === '',
            'nonceLength' => strlen($value),
            'nonceTrimmedLength' => strlen($trimmed),
            'nonceSha256' => hash('sha256', $value),
            'nonceHasAsciiWhitespace' => $hasAsciiWhitespace,
            'nonceBase64Candidate' => $base64Candidate,
            'nonceValid' => $issues === [],
            'nonceIssueCodes' => $issues,
            'nonceContainsWhitespace' => $hasAsciiWhitespace,
            'nonceSameValueElementCount' => count($sameValueElements),
            'nonceSameValueElementNames' => $sameValueElementNames,
            'nonceSameValueElementIds' => $sameValueElementIds,
            'nonceSameValueElements' => $sameValueElements,
            'nonceSharedInFragment' => count($sameValueElements) > 1,
            'nonceReviewCodes' => $reviewCodes,
        ];
    }

    /**
     * @return list<array{element:string, id:?string, source:string}>
     */
    private static function nonceSameValueElementRecords(\DOMElement $element, string $raw): array
    {
        $document = $element->ownerDocument;
        if (!$document instanceof \DOMDocument) {
            return [[
                'element' => self::htmlElementName($element),
                'id' => self::attributeOrNull($element, 'id'),
                'source' => 'self',
            ]];
        }

        $records = [];
        foreach ($document->getElementsByTagName('*') as $candidate) {
            if (!$candidate instanceof \DOMElement) {
                continue;
            }

            $candidateNonce = self::attributeOrNull($candidate, 'nonce');
            if ($candidateNonce !== $raw) {
                continue;
            }

            $records[] = [
                'element' => self::htmlElementName($candidate),
                'id' => self::attributeOrNull($candidate, 'id'),
                'source' => $candidate->isSameNode($element) ? 'self' : 'same-fragment',
            ];
        }

        return $records;
    }

    /**
     * @return array<string, mixed>
     */
    private static function anchorPositioningSummary(\DOMElement $element, string $anchorRaw): array
    {
        $anchorTarget = trim($anchorRaw);
        $anchorTargetValid = $anchorTarget !== '' && self::isHtmlIdReferenceToken($anchorTarget);
        $target = $anchorTargetValid ? self::htmlElementById($element, $anchorTarget) : null;
        $issues = [];

        if ($anchorTarget === '') {
            $issues[] = ['code' => 'missing-html-anchor-positioning-target'];
        } elseif (!$anchorTargetValid) {
            $issues[] = [
                'code' => 'invalid-html-anchor-positioning-target',
                'anchorRaw' => $anchorRaw,
            ];
        } elseif (!$target instanceof \DOMElement) {
            $issues[] = [
                'code' => 'missing-html-anchor-positioning-target-element',
                'anchorTarget' => $anchorTarget,
            ];
        }

        $issueCodes = array_values(array_unique(array_map(
            static fn (array $issue): string => (string) ($issue['code'] ?? ''),
            $issues
        )));

        return [
            'anchorPositioningReviewPolicy' => 'html-anchor-positioning-target-review',
            'anchorRaw' => $anchorRaw,
            'anchorTarget' => $anchorTarget === '' ? null : $anchorTarget,
            'anchorTargetValid' => $anchorTargetValid,
            'anchorTargetFound' => $target instanceof \DOMElement,
            'anchorTargetKind' => self::anchorPositioningTargetKind($target, $anchorTarget, $anchorTargetValid),
            'anchorTargetElement' => $target instanceof \DOMElement ? self::anchorPositioningTargetSummary($target) : null,
            'anchorIssues' => $issues,
            'anchorIssueCodes' => $issueCodes,
            'anchorReferencesTarget' => $issues === [],
        ];
    }

    private static function anchorPositioningTargetKind(
        ?\DOMElement $target,
        string $anchorTarget,
        bool $anchorTargetValid
    ): string {
        if ($target instanceof \DOMElement) {
            return 'element';
        }
        if ($anchorTarget === '') {
            return 'missing-reference';
        }

        return $anchorTargetValid ? 'missing-target' : 'invalid-reference';
    }

    /**
     * @return array<string, mixed>
     */
    private static function anchorPositioningTargetSummary(\DOMElement $target): array
    {
        return [
            'tag' => self::htmlElementName($target),
            'id' => self::attributeOrNull($target, 'id'),
            'text' => self::normalizedText($target),
        ];
    }

    /**
     * @param array<string, string> $attributes
     * @return array<string, mixed>
     */
    private static function effectiveTitleSummary(\DOMElement $element, array $attributes): array
    {
        if (array_key_exists('title', $attributes)) {
            return self::titleProvenanceSummary($element, $attributes['title'], false);
        }

        for ($ancestor = $element->parentNode; $ancestor instanceof \DOMElement; $ancestor = $ancestor->parentNode) {
            $ancestorAttributes = self::htmlAttributes($ancestor);
            if (array_key_exists('title', $ancestorAttributes)) {
                return self::titleProvenanceSummary($ancestor, $ancestorAttributes['title'], true);
            }
        }

        return [];
    }

    /**
     * @return array<string, mixed>
     */
    private static function titleProvenanceSummary(\DOMElement $source, string $raw, bool $inherited): array
    {
        $summary = [
            'effectiveTitleRaw' => $raw,
            'effectiveTitle' => $raw === '' ? null : $raw,
            'titleInherited' => $inherited,
            'titleSource' => $inherited ? 'ancestor-title' : 'self-title',
            'titleSourceElement' => self::htmlElementName($source),
            'titleAdvisoryAvailable' => $raw !== '',
            'titleAdvisoryReset' => $raw === '',
        ];

        $sourceId = self::attributeOrNull($source, 'id');
        if ($sourceId !== null && $sourceId !== '') {
            $summary['titleSourceElementId'] = $sourceId;
        }

        return $summary;
    }

    /**
     * @param array<string, string> $attributes
     * @return array<string, mixed>
     */
    private static function effectiveInertSummary(\DOMElement $element, array $attributes): array
    {
        if (array_key_exists('inert', $attributes)) {
            return self::inertProvenanceSummary($element, $attributes['inert'], false);
        }

        for ($ancestor = $element->parentNode; $ancestor instanceof \DOMElement; $ancestor = $ancestor->parentNode) {
            $ancestorAttributes = self::htmlAttributes($ancestor);
            if (array_key_exists('inert', $ancestorAttributes)) {
                return self::inertProvenanceSummary($ancestor, $ancestorAttributes['inert'], true);
            }
        }

        return [];
    }

    /**
     * @return array<string, mixed>
     */
    private static function inertProvenanceSummary(
        \DOMElement $source,
        string $raw,
        bool $inherited
    ): array {
        $summary = [
            'effectiveInertRaw' => $raw,
            'effectiveInert' => true,
            'inertInherited' => $inherited,
            'inertSource' => $inherited ? 'ancestor-inert' : 'self-inert',
            'inertSourceElement' => self::htmlElementName($source),
        ];

        $sourceId = self::attributeOrNull($source, 'id');
        if ($sourceId !== null && $sourceId !== '') {
