    /**
     * @param array<string, string> $attributes
     * @return array<string, mixed>
     */
    private static function effectiveTranslateSummary(\DOMElement $element, array $attributes): array
    {
        if (array_key_exists('translate', $attributes)) {
            $translate = self::htmlTranslateState($attributes['translate']);
            if ($translate !== null) {
                return self::translateProvenanceSummary($element, $attributes['translate'], $translate, false);
            }
        }

        for ($ancestor = $element->parentNode; $ancestor instanceof \DOMElement; $ancestor = $ancestor->parentNode) {
            $ancestorAttributes = self::htmlAttributes($ancestor);
            if (!array_key_exists('translate', $ancestorAttributes)) {
                continue;
            }

            $translate = self::htmlTranslateState($ancestorAttributes['translate']);
            if ($translate !== null) {
                return self::translateProvenanceSummary($ancestor, $ancestorAttributes['translate'], $translate, true);
            }
        }

        return [];
    }

    /**
     * @return array<string, mixed>
     */
    private static function translateProvenanceSummary(
        \DOMElement $source,
        string $raw,
        bool $translate,
        bool $inherited
    ): array {
        $summary = [
            'effectiveTranslateRaw' => $raw,
            'effectiveTranslate' => $translate,
            'translateInherited' => $inherited,
            'translateSource' => $inherited ? 'ancestor-translate' : 'self-translate',
            'translateSourceElement' => self::htmlElementName($source),
        ];

        $sourceId = self::attributeOrNull($source, 'id');
        if ($sourceId !== null && $sourceId !== '') {
            $summary['translateSourceElementId'] = $sourceId;
        }

        return $summary;
    }

    /**
     * @param array<string, string> $attributes
     * @return array<string, mixed>
     */
    private static function htmlLanguageAttributeSummary(array $attributes): array
    {
        $hasLang = array_key_exists('lang', $attributes);
        $hasXmlLang = array_key_exists('xml:lang', $attributes);
        if (!$hasLang && !$hasXmlLang) {
            return [];
        }

        $sourceAttribute = $hasLang ? 'lang' : 'xml:lang';
        $raw = $attributes[$sourceAttribute];
        $language = trim($raw);
        $languageTag = self::normalizeHtmlLanguageTag($raw);
        $issues = [];

        if ($language === '') {
            $issues[] = ['code' => 'empty-' . $sourceAttribute . '-attribute'];
        } elseif ($languageTag === null) {
            $issues[] = [
                'code' => 'invalid-' . $sourceAttribute . '-attribute',
                'raw' => $raw,
            ];
        }

        $summary = [
            'languageReviewPolicy' => 'html-language-tag-review',
            'languageAttributeReviewPolicy' => 'html-language-attribute-review',
            'languageSourceAttribute' => $sourceAttribute,
            'languageAttribute' => $sourceAttribute,
            'languageRaw' => $raw,
            'language' => $language,
            'languageTag' => $languageTag,
            'languageNormalized' => $languageTag,
            'languageValid' => $languageTag !== null,
            'languageEmptyValueIgnored' => $language === '',
            'languageInvalidValueIgnored' => $language !== '' && $languageTag === null,
        ];
        $summary += self::languageTagReviewSummary($raw, 'language');
        $summary['languagePrimarySubtag'] = $languageTag === null ? null : explode('-', $languageTag)[0];
        $summary['languageSubtags'] = $languageTag === null ? [] : explode('-', $languageTag);
        $summary['languageTagEmpty'] = $language === '';

        if ($hasXmlLang) {
            $xmlRaw = $attributes['xml:lang'];
            $xmlLanguage = trim($xmlRaw);
            $xmlLanguageTag = self::normalizeHtmlLanguageTag($xmlRaw);
            $summary['xmlLanguageRaw'] = $xmlRaw;
            $summary['xmlLanguage'] = $xmlLanguage;
            $summary['xmlLanguageNormalized'] = $xmlLanguageTag;
            $summary['xmlLanguageValid'] = $xmlLanguageTag !== null;

            if ($sourceAttribute !== 'xml:lang' && $xmlLanguage === '') {
                $issues[] = ['code' => 'empty-xml:lang-attribute'];
            } elseif ($sourceAttribute !== 'xml:lang' && $xmlLanguageTag === null) {
                $issues[] = [
                    'code' => 'invalid-xml:lang-attribute',
                    'raw' => $xmlRaw,
                ];
            }
            if (
                $hasLang
                && $languageTag !== null
                && $xmlLanguageTag !== null
                && $languageTag !== $xmlLanguageTag
            ) {
                $issues[] = [
                    'code' => 'conflicting-language-attributes',
                    'lang' => $languageTag,
                    'xml:lang' => $xmlLanguageTag,
                ];
            }
        }

        $issueCodes = array_values(array_unique(array_map(
            static fn (array $issue): string => (string) ($issue['code'] ?? ''),
            $issues
        )));
        $declaredTags = [];
        $declaredNormalized = [];
        foreach (['lang', 'xml:lang'] as $attribute) {
            if (!array_key_exists($attribute, $attributes)) {
                continue;
            }

            $declaredTags[$attribute] = $attributes[$attribute];
            $normalized = self::normalizeHtmlLanguageTag($attributes[$attribute]);
            if ($normalized !== null) {
                $declaredNormalized[$attribute] = $normalized;
            }
        }
        $languageIssueCodeMap = [
            'empty-lang-attribute' => 'empty-html-language-tag',
            'empty-xml:lang-attribute' => 'empty-html-language-tag',
            'invalid-lang-attribute' => 'invalid-html-language-tag',
            'invalid-xml:lang-attribute' => 'invalid-html-language-tag',
            'conflicting-language-attributes' => 'mismatched-html-language-declarations',
        ];
        $languageIssueCodes = array_values(array_unique(array_map(
            static fn (string $code): string => $languageIssueCodeMap[$code] ?? $code,
            $issueCodes
        )));

        $summary['languageAttributeConflict'] = in_array('conflicting-language-attributes', $issueCodes, true);
        $summary['languageAttributeIssues'] = $issues;
        $summary['languageAttributeIssueCodes'] = $issueCodes;
        $summary['languageIssues'] = array_map(
            static function (array $issue) use ($languageIssueCodeMap): array {
                $code = (string) ($issue['code'] ?? '');
                $issue['code'] = $languageIssueCodeMap[$code] ?? $code;

                return $issue;
            },
            $issues
        );
        $summary['languageIssueCodes'] = $languageIssueCodes;
        if (count($declaredTags) > 1) {
            $summary['languageDeclaredTags'] = $declaredTags;
            $summary['languageDeclaredNormalized'] = $declaredNormalized;
            $summary['languageDeclarationMismatch'] = $summary['languageAttributeConflict'];
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function languageTagReviewSummary(string $raw, string $prefix): array
    {
        $analysis = self::htmlLanguageTagAnalysis($raw);

        return [
            $prefix . 'TagReviewPolicy' => 'html-language-tag-review',
            $prefix . 'TagRaw' => $raw,
            $prefix . 'TagCanonical' => $analysis['canonical'],
            $prefix . 'TagSubtags' => $analysis['subtags'],
            $prefix . 'TagPrimarySubtag' => $analysis['primary'],
            $prefix . 'TagScriptSubtag' => $analysis['script'],
            $prefix . 'TagRegionSubtag' => $analysis['region'],
            $prefix . 'TagPrivateUseSubtags' => $analysis['privateUse'],
            $prefix . 'TagValid' => $analysis['valid'],
            $prefix . 'TagIssueCodes' => $analysis['issues'],
        ];
    }

    /**
     * @return array{canonical:?string, subtags:list<string>, primary:?string, script:?string, region:?string, privateUse:list<string>, valid:bool, issues:list<string>}
     */
    private static function htmlLanguageTagAnalysis(string $raw): array
    {
        $trimmed = trim($raw);
        $issues = [];

        if ($trimmed === '') {
            $issues[] = 'empty-language-tag';
        }
        if (preg_match('/[\t\n\f\r ]/', $raw) === 1) {
            $issues[] = 'language-tag-ascii-whitespace';
        }
        if (str_contains($trimmed, '_')) {
            $issues[] = 'language-tag-underscore-separator';
        }

        $subtags = $trimmed === '' ? [] : explode('-', $trimmed);
        foreach ($subtags as $subtag) {
            if ($subtag === '' || preg_match('/^[A-Za-z0-9]{1,8}$/', $subtag) !== 1) {
                $issues[] = 'invalid-language-subtag';
                break;
            }
        }

        $primary = null;
        if ($subtags !== []) {
            $primaryRaw = $subtags[0];
            if (preg_match('/^[A-Za-z]{2,8}$/', $primaryRaw) === 1 || strtolower($primaryRaw) === 'x') {
                $primary = strtolower($primaryRaw);
            } else {
                $issues[] = 'invalid-primary-language-subtag';
            }
        }

        $script = null;
        $region = null;
        $privateUse = [];
        $privateUseStart = $primary === 'x' ? 0 : null;

        foreach ($subtags as $index => $subtag) {
            if ($index === 0) {
                continue;
            }

            if (strtolower($subtag) === 'x') {
                $privateUseStart = $index;
                break;
            }

            if ($script === null && preg_match('/^[A-Za-z]{4}$/', $subtag) === 1) {
                $script = ucfirst(strtolower($subtag));
                continue;
            }

            if ($region === null && preg_match('/^(?:[A-Za-z]{2}|[0-9]{3})$/', $subtag) === 1) {
                $region = strtoupper($subtag);
            }
        }

        if ($privateUseStart !== null) {
            $privateUse = array_map(
                static fn (string $subtag): string => strtolower($subtag),
                array_slice($subtags, $privateUseStart + 1)
            );
        }

        $issues = array_values(array_unique($issues));

        return [
            'canonical' => $issues === [] ? self::normalizeHtmlLanguageTag($raw) : null,
            'subtags' => $subtags,
            'primary' => $primary,
            'script' => $script,
            'region' => $region,
            'privateUse' => $privateUse,
            'valid' => $issues === [],
            'issues' => $issues,
        ];
    }

    /**
     * @param array<string, string> $attributes
     * @return array<string, mixed>
     */
    private static function effectiveLanguageSummary(\DOMElement $element, array $attributes): array
    {
        $firstInvalidCandidate = null;
        foreach (['lang', 'xml:lang'] as $attribute) {
            if (!array_key_exists($attribute, $attributes)) {
                continue;
            }

            $raw = $attributes[$attribute];
            if (trim($raw) === '') {
                continue;
            }

            $language = self::normalizeHtmlLanguageTag($raw);
            if ($language !== null) {
                return self::languageProvenanceSummary(
                    $element,
                    $raw,
                    $language,
                    'self-' . $attribute,
                    false
                );
            }
            $firstInvalidCandidate ??= [$element, $raw, 'self-' . $attribute, false];
        }

        for ($ancestor = $element->parentNode; $ancestor instanceof \DOMElement; $ancestor = $ancestor->parentNode) {
            $ancestorAttributes = self::htmlAttributes($ancestor);
            foreach (['lang', 'xml:lang'] as $attribute) {
                if (!array_key_exists($attribute, $ancestorAttributes)) {
                    continue;
                }

                $raw = $ancestorAttributes[$attribute];
                if (trim($raw) === '') {
                    continue;
                }

                $language = self::normalizeHtmlLanguageTag($raw);
                if ($language !== null) {
                    return self::languageProvenanceSummary(
                        $ancestor,
                        $raw,
                        $language,
                        'ancestor-' . $attribute,
                        true
                    );
                }
                $firstInvalidCandidate ??= [$ancestor, $raw, 'ancestor-' . $attribute, true];
            }
        }

        if ($firstInvalidCandidate !== null) {
            [$source, $raw, $sourceKind, $inherited] = $firstInvalidCandidate;

            return self::languageProvenanceSummary(
                $source,
                $raw,
                trim($raw),
                $sourceKind,
                $inherited
            );
        }

        return [];
    }

    /**
     * @return array<string, mixed>
     */
    private static function languageProvenanceSummary(
        \DOMElement $source,
        string $raw,
        string $language,
        string $sourceKind,
        bool $inherited
    ): array {
        $normalized = self::normalizeHtmlLanguageTag($raw);
        $attribute = str_ends_with($sourceKind, 'xml:lang') ? 'xml:lang' : 'lang';
        $summary = [
            'effectiveLanguageRaw' => $raw,
            'effectiveLanguage' => $normalized ?? $language,
            'effectiveLanguageNormalized' => $normalized,
            'effectiveLanguageValid' => $normalized !== null,
            'effectiveLanguageAttribute' => $attribute,
            'effectiveLanguageTag' => $normalized,
            'effectiveLanguagePrimarySubtag' => $normalized === null ? null : explode('-', $normalized)[0],
            'effectiveLanguageSubtags' => $normalized === null ? [] : explode('-', $normalized),
            'languageInherited' => $inherited,
            'languageSource' => $sourceKind,
            'languageSourceElement' => self::htmlElementName($source),
        ] + self::languageTagReviewSummary($raw, 'effectiveLanguage');

        $sourceId = self::attributeOrNull($source, 'id');
        if ($sourceId !== null && $sourceId !== '') {
            $summary['languageSourceElementId'] = $sourceId;
        }

        return $summary;
    }

    /**
     * @param array<string, string> $attributes
     * @return array<string, mixed>
     */
    private static function effectiveDirectionSummary(\DOMElement $element, array $attributes): array
    {
        if (array_key_exists('dir', $attributes)) {
            $direction = self::htmlDirectionState($attributes['dir']);
            if ($direction !== null) {
                return self::directionProvenanceSummary($element, $attributes['dir'], $direction, false);
            }
        }

        if (self::htmlElementName($element) === 'bdi' && !array_key_exists('dir', $attributes)) {
            return self::implicitBdiDirectionSummary($element);
        }

        for ($ancestor = $element->parentNode; $ancestor instanceof \DOMElement; $ancestor = $ancestor->parentNode) {
            $ancestorAttributes = self::htmlAttributes($ancestor);
            if (!array_key_exists('dir', $ancestorAttributes)) {
                continue;
            }

            $direction = self::htmlDirectionState($ancestorAttributes['dir']);
            if ($direction !== null) {
                return self::directionProvenanceSummary($ancestor, $ancestorAttributes['dir'], $direction, true);
            }
        }

        return [];
    }

    /**
     * @return array<string, mixed>
     */
    private static function implicitBdiDirectionSummary(\DOMElement $element): array
    {
        return self::directionProvenanceSummary(
            $element,
            'auto',
            'auto',
            false,
            'implicit-bdi-dir-auto'
        ) + [
            'directionImplicitDefault' => true,
            'directionImplicitDefaultElement' => 'bdi',
            'bdiDirectionReviewPolicy' => 'html-bdi-default-direction-review',
            'bdiDirectionDefaulted' => true,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function directionProvenanceSummary(
        \DOMElement $source,
        string $raw,
        string $direction,
        bool $inherited,
        ?string $sourceKind = null
    ): array {
        $summary = [
            'effectiveDirectionRaw' => $raw,
            'effectiveDirection' => $direction,
            'effectiveDirectionResolved' => $direction,
            'directionInherited' => $inherited,
            'directionSource' => $sourceKind ?? ($inherited ? 'ancestor-dir' : 'self-dir'),
            'directionSourceElement' => self::htmlElementName($source),
        ];

        $sourceId = self::attributeOrNull($source, 'id');
        if ($sourceId !== null && $sourceId !== '') {
            $summary['directionSourceElementId'] = $sourceId;
        }

        if ($direction === 'auto') {
            $summary += self::directionAutoResolutionSummary($source, $inherited);
            $auto = self::dirAutoResolutionSummary($source, $inherited);
            $summary['effectiveDirectionResolved'] = $auto['dirAutoResolvedDirection'];

            return $summary + $auto;
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function directionAutoResolutionSummary(\DOMElement $source, bool $inherited): array
    {
        $text = self::normalizedText($source);
        $characters = self::unicodeCharacters($text);
        $firstStrong = self::firstStrongDirectionCharacter($characters);
        $direction = $firstStrong['direction'] ?? 'ltr';

        return [
            'directionAutoReviewPolicy' => 'html-dir-auto-first-strong-review',
            'directionAutoState' => $firstStrong === null ? 'no-strong-character' : 'first-strong-' . $direction,
            'directionAutoResolvedDirection' => $direction,
            'directionAutoFirstStrongDirection' => $firstStrong['direction'] ?? null,
            'directionAutoFirstStrongCharacter' => $firstStrong['character'] ?? null,
            'directionAutoFirstStrongIndex' => $firstStrong['index'] ?? null,
            'directionAutoTextLength' => count($characters),
            'directionAutoInherited' => $inherited,
        ];
    }

    /**
     * @return list<string>
     */
    private static function unicodeCharacters(string $text): array
    {
        if ($text === '') {
            return [];
        }

        if (preg_match_all('/./us', $text, $matches) === false) {
            return [];
        }

        return $matches[0];
    }

    /**
     * @param list<string> $characters
     * @return array{direction:string, character:string, index:int}|null
     */
    private static function firstStrongDirectionCharacter(array $characters): ?array
    {
        foreach ($characters as $index => $character) {
            $direction = self::strongDirectionForCharacter($character);
            if ($direction !== null) {
                return [
                    'direction' => $direction,
                    'character' => $character,
                    'index' => $index,
                ];
            }
        }

        return null;
    }

    private static function strongDirectionForCharacter(string $character): ?string
    {
        if (preg_match('/[\p{Bidi_Class:R}\p{Bidi_Class:AL}]/u', $character) === 1) {
            return 'rtl';
        }

        return preg_match('/\p{Bidi_Class:L}/u', $character) === 1 ? 'ltr' : null;
    }

    private static function htmlDirectionState(string $value): ?string
    {
        $direction = strtolower(trim($value));

        return in_array($direction, ['ltr', 'rtl', 'auto'], true) ? $direction : null;
    }

    /**
     * @return array<string, mixed>
     */
    private static function dirAutoResolutionSummary(\DOMElement $source, bool $inherited): array
    {
        $scan = self::firstStrongTextDirection(self::normalizedText($source));
        $summary = [
            'dirAutoReviewPolicy' => 'html-dir-auto-first-strong-character-review',
            'dirAutoResolvedDirection' => $scan['direction'],
            'dirAutoResolved' => $scan['direction'] !== null,
            'dirAutoNeutral' => $scan['direction'] === null,
            'dirAutoInherited' => $inherited,
            'dirAutoSourceElement' => self::htmlElementName($source),
            'dirAutoFirstStrongCharacter' => $scan['character'],
            'dirAutoFirstStrongBidiClass' => $scan['bidiClass'],
            'dirAutoFirstStrongCharacterOffset' => $scan['characterOffset'],
            'dirAutoFirstStrongByteOffset' => $scan['byteOffset'],
        ];

        $sourceId = self::attributeOrNull($source, 'id');
        if ($sourceId !== null && $sourceId !== '') {
            $summary['dirAutoSourceElementId'] = $sourceId;
        }

        return $summary;
    }

    /**
     * @return array{direction:?string, character:?string, bidiClass:?string, characterOffset:?int, byteOffset:?int}
     */
    private static function firstStrongTextDirection(string $text): array
    {
        if (preg_match_all('/./us', $text, $matches, PREG_OFFSET_CAPTURE) !== false) {
            foreach ($matches[0] as $index => $match) {
                $character = (string) $match[0];
                $byteOffset = (int) $match[1];
                if (preg_match('/^\p{Bidi_Class:L}$/u', $character) === 1) {
                    return [
                        'direction' => 'ltr',
                        'character' => $character,
                        'bidiClass' => 'L',
                        'characterOffset' => $index,
                        'byteOffset' => $byteOffset,
                    ];
                }
                if (preg_match('/^\p{Bidi_Class:R}$/u', $character) === 1) {
                    return [
                        'direction' => 'rtl',
                        'character' => $character,
                        'bidiClass' => 'R',
                        'characterOffset' => $index,
                        'byteOffset' => $byteOffset,
                    ];
                }
                if (preg_match('/^\p{Bidi_Class:AL}$/u', $character) === 1) {
                    return [
                        'direction' => 'rtl',
                        'character' => $character,
                        'bidiClass' => 'AL',
                        'characterOffset' => $index,
                        'byteOffset' => $byteOffset,
                    ];
                }
            }
        }

        return [
            'direction' => null,
            'character' => null,
            'bidiClass' => null,
            'characterOffset' => null,
            'byteOffset' => null,
        ];
    }

    private static function htmlTranslateState(string $value): ?bool
