    /**
     * @param array<string, string> $attributes
     * @return array<string, mixed>
     */
    private static function rdfaAttributeSummary(array $attributes): array
    {
        $rdfaAttributes = ['about', 'content', 'datatype', 'inlist', 'prefix', 'property', 'rel', 'resource', 'rev', 'typeof', 'vocab'];
        $present = [];
        foreach ($rdfaAttributes as $attribute) {
            if (array_key_exists($attribute, $attributes)) {
                $present[] = $attribute;
            }
        }

        if ($present === []) {
            return [];
        }

        $triggerAttributes = array_diff($present, ['content', 'rel']);
        if ($triggerAttributes === []) {
            return [];
        }

        $summary = [
            'rdfa' => self::rdfaSummaryKind($attributes),
            'rdfaAttributes' => $present,
        ];

        if (array_key_exists('vocab', $attributes)) {
            $vocab = self::rdfaSingleTokenSummary($attributes['vocab']);
            $summary['rdfaVocabRaw'] = $attributes['vocab'];
            $summary['rdfaVocab'] = $vocab['value'];
            $summary['rdfaVocabValid'] = $vocab['valid'];
        }

        if (array_key_exists('prefix', $attributes)) {
            $prefixes = self::rdfaPrefixSummary($attributes['prefix']);
            $summary['rdfaPrefixRaw'] = $attributes['prefix'];
            $summary['rdfaPrefixTokens'] = $prefixes['tokens'];
            $summary['rdfaPrefixMappings'] = $prefixes['items'];
            $summary['rdfaPrefixes'] = $prefixes['prefixes'];
            $summary['invalidRdfaPrefixMappings'] = $prefixes['invalid'];
            $summary['rdfaPrefixValid'] = $prefixes['valid'];
        }

        if (array_key_exists('typeof', $attributes)) {
            $types = self::semanticMetadataTokenSummary($attributes['typeof']);
            $summary['rdfaTypeofRaw'] = $attributes['typeof'];
            $summary['rdfaTypeofTokens'] = $types['tokens'];
            $summary['rdfaTypes'] = $types['values'];
            $summary['invalidRdfaTypes'] = $types['invalid'];
            $summary['rdfaTypeofValid'] = $types['valid'];
        }

        if (array_key_exists('property', $attributes)) {
            $properties = self::semanticMetadataTokenSummary($attributes['property']);
            $summary['rdfaPropertyRaw'] = $attributes['property'];
            $summary['rdfaPropertyTokens'] = $properties['tokens'];
            $summary['rdfaProperties'] = $properties['values'];
            $summary['invalidRdfaProperties'] = $properties['invalid'];
            $summary['rdfaPropertyValid'] = $properties['valid'];
        }

        if (array_key_exists('rel', $attributes)) {
            $relations = self::semanticMetadataTokenSummary($attributes['rel']);
            $summary['rdfaRelRaw'] = $attributes['rel'];
            $summary['rdfaRelTokens'] = $relations['tokens'];
            $summary['rdfaRelations'] = $relations['values'];
            $summary['invalidRdfaRelations'] = $relations['invalid'];
            $summary['rdfaRelValid'] = $relations['valid'];
        }

        if (array_key_exists('rev', $attributes)) {
            $reverse = self::semanticMetadataTokenSummary($attributes['rev']);
            $summary['rdfaRevRaw'] = $attributes['rev'];
            $summary['rdfaRevTokens'] = $reverse['tokens'];
            $summary['rdfaReverseRelations'] = $reverse['values'];
            $summary['invalidRdfaReverseRelations'] = $reverse['invalid'];
            $summary['rdfaRevValid'] = $reverse['valid'];
        }

        if (array_key_exists('about', $attributes)) {
            $about = self::rdfaSingleTokenSummary($attributes['about']);
            $summary['rdfaAboutRaw'] = $attributes['about'];
            $summary['rdfaAbout'] = $about['value'];
            $summary['rdfaAboutValid'] = $about['valid'];
        }

        if (array_key_exists('resource', $attributes)) {
            $resource = self::rdfaSingleTokenSummary($attributes['resource']);
            $summary['rdfaResourceRaw'] = $attributes['resource'];
            $summary['rdfaResource'] = $resource['value'];
            $summary['rdfaResourceValid'] = $resource['valid'];
        }

        if (array_key_exists('datatype', $attributes)) {
            $datatype = self::rdfaSingleTokenSummary($attributes['datatype']);
            $summary['rdfaDatatypeRaw'] = $attributes['datatype'];
            $summary['rdfaDatatype'] = $datatype['value'];
            $summary['rdfaDatatypeValid'] = $datatype['valid'];
        }

        if (array_key_exists('content', $attributes)) {
            $summary['rdfaContentRaw'] = $attributes['content'];
            $summary['rdfaContent'] = $attributes['content'];
            $summary['rdfaContentValid'] = self::isSafeRdfaLiteral($attributes['content']);
        }

        if (array_key_exists('inlist', $attributes)) {
            $summary['rdfaInListRaw'] = $attributes['inlist'];
            $summary['rdfaInList'] = true;
        }

        return $summary;
    }

    /**
     * @param array<string, string> $attributes
     */
    private static function rdfaSummaryKind(array $attributes): string
    {
        if (array_key_exists('property', $attributes)) {
            return 'property';
        }

        if (array_key_exists('rel', $attributes) || array_key_exists('rev', $attributes)) {
            return 'relationship';
        }

        if (array_key_exists('typeof', $attributes) || array_key_exists('about', $attributes) || array_key_exists('resource', $attributes)) {
            return 'resource';
        }

        return 'metadata';
    }

    /**
     * @return array{value:?string, valid:bool}
     */
    private static function rdfaSingleTokenSummary(string $value): array
    {
        $trimmed = trim($value);

        return [
            'value' => $trimmed === '' ? null : $trimmed,
            'valid' => $trimmed !== '' && self::isSafeHtmlSemanticMetadataToken($trimmed),
        ];
    }

    /**
     * @return array{tokens:list<string>, items:list<array<string, mixed>>, prefixes:array<string, string>, invalid:list<string>, valid:bool}
     */
    private static function rdfaPrefixSummary(string $value): array
    {
        $tokens = self::spaceSeparatedTokens($value);
        $items = [];
        $prefixes = [];
        $invalid = [];
        $count = count($tokens);

        for ($index = 0; $index < $count; $index += 2) {
            $prefixToken = $tokens[$index];
            $iri = $tokens[$index + 1] ?? null;
            $prefix = str_ends_with($prefixToken, ':') ? substr($prefixToken, 0, -1) : null;
            $raw = $iri === null ? $prefixToken : $prefixToken . ' ' . $iri;
            $valid = $iri !== null
                && $prefix !== null
                && preg_match('/^[A-Za-z][A-Za-z0-9._-]*$/', $prefix) === 1
                && self::isSafeHtmlSemanticMetadataToken($iri);

            if ($valid) {
                $prefixes[$prefix] = $iri;
            } else {
                $invalid[] = $raw;
            }

            $items[] = [
                'raw' => $raw,
                'prefix' => $prefix,
                'iri' => $iri,
                'valid' => $valid,
            ];
        }

        return [
            'tokens' => $tokens,
            'items' => $items,
            'prefixes' => $prefixes,
            'invalid' => $invalid,
            'valid' => $tokens !== [] && $invalid === [],
        ];
    }

    private static function isSafeRdfaLiteral(string $value): bool
    {
        return preg_match('/[<\p{Cc}\p{Zl}\p{Zp}]/u', $value) !== 1;
    }

    /**
     * @param array<string, string> $attributes
     * @return array<string, mixed>
     */
    private static function microdataAttributeSummary(\DOMElement $element, array $attributes): array
    {
        $microdataAttributes = ['itemprop', 'itemref', 'itemscope', 'itemtype', 'itemid'];
        $hasMicrodata = false;
        foreach ($microdataAttributes as $attribute) {
            if (array_key_exists($attribute, $attributes)) {
                $hasMicrodata = true;
                break;
            }
        }

        if (!$hasMicrodata) {
            return [];
        }

        $summary = [
            'microdata' => array_key_exists('itemscope', $attributes)
                ? 'item'
                : (array_key_exists('itemprop', $attributes) ? 'property' : 'metadata'),
        ];

        if (array_key_exists('itemscope', $attributes)) {
            $summary['itemScopeRaw'] = $attributes['itemscope'];
            $summary['itemScope'] = true;
        }

        if (array_key_exists('itemprop', $attributes)) {
            $properties = self::semanticMetadataTokenSummary($attributes['itemprop']);
            $summary['itemPropRaw'] = $attributes['itemprop'];
            $summary['itemPropTokens'] = $properties['tokens'];
            $summary['itemProperties'] = $properties['values'];
            $summary['invalidItemProperties'] = $properties['invalid'];
            $summary['itemPropValid'] = $properties['valid'];
            $summary += self::microdataPropertyValueSummary($element);
        }

        if (array_key_exists('itemtype', $attributes)) {
            $types = self::semanticMetadataTokenSummary($attributes['itemtype']);
            $summary['itemTypeRaw'] = $attributes['itemtype'];
            $summary['itemTypeTokens'] = $types['tokens'];
            $summary['itemTypes'] = $types['values'];
            $summary['invalidItemTypes'] = $types['invalid'];
            $summary['itemTypeValid'] = $types['valid'];
        }

        if (array_key_exists('itemid', $attributes)) {
            $itemId = trim($attributes['itemid']);
            $summary['itemIdRaw'] = $attributes['itemid'];
            $summary['itemId'] = $itemId === '' ? null : $itemId;
            $summary['itemIdValid'] = $itemId !== '' && self::isSafeHtmlSemanticMetadataToken($itemId);
        }

        if (array_key_exists('itemref', $attributes)) {
            $references = self::idReferenceTokenSummary($attributes['itemref']);
            $resolved = self::itemRefResolutionSummary($element, $references['values']);
            $summary['itemRefRaw'] = $attributes['itemref'];
            $summary['itemRefTokens'] = $references['tokens'];
            $summary['itemRefIds'] = $references['values'];
            $summary['invalidItemRefIds'] = $references['invalid'];
            $summary['itemRefValid'] = $references['valid'];
            $summary['itemRefResolvedIds'] = $resolved['resolved'];
            $summary['itemRefMissingIds'] = $resolved['missing'];
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function microdataPropertyValueSummary(\DOMElement $element): array
    {
        $name = self::htmlElementName($element);
        $attribute = match ($name) {
            'meta' => 'content',
            'audio', 'embed', 'iframe', 'img', 'source', 'track', 'video' => 'src',
            'a', 'area', 'link' => 'href',
            'object' => 'data',
            'data', 'meter' => 'value',
            'time' => self::attributeOrNull($element, 'datetime') === null ? null : 'datetime',
            default => null,
        };

        if ($attribute !== null) {
            $raw = self::attributeOrNull($element, $attribute);
            $value = $raw === null ? null : trim($raw);

            return [
                'itemValueSource' => 'attribute',
                'itemValueSourceAttribute' => $attribute,
                'itemValueRaw' => $raw,
                'itemValue' => $value === '' ? null : $value,
                'itemValueValid' => $value !== null && $value !== '',
            ];
        }

        $text = self::normalizedText($element);

        return [
            'itemValueSource' => 'text',
            'itemValueSourceAttribute' => null,
            'itemValueRaw' => $text,
            'itemValue' => $text === '' ? null : $text,
            'itemValueValid' => $text !== '',
        ];
    }

    /**
     * @return array{tokens:list<string>, values:list<string>, invalid:list<string>, valid:bool}
     */
    private static function semanticMetadataTokenSummary(string $value): array
    {
        $tokens = self::spaceSeparatedTokens($value);
        $values = [];
        $invalid = [];
        foreach ($tokens as $token) {
            if (!self::isSafeHtmlSemanticMetadataToken($token)) {
                $invalid[] = $token;
                continue;
            }

            if (!in_array($token, $values, true)) {
                $values[] = $token;
            }
        }

        return [
            'tokens' => $tokens,
            'values' => $values,
            'invalid' => $invalid,
            'valid' => $tokens !== [] && $invalid === [],
        ];
    }

    private static function isSafeHtmlSemanticMetadataToken(string $token): bool
    {
        if ($token === '' || preg_match('/[\s<>"\'`{}\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/u', $token) === 1) {
            return false;
        }

        $scheme = strtolower(strstr($token, ':', true) ?: '');
        if (in_array($scheme, ['javascript', 'vbscript', 'data'], true)) {
            return false;
        }
        if (preg_match('/^[A-Za-z][A-Za-z0-9+.-]*:/', $token) === 1 && !str_contains($token, '://')) {
            return preg_match('/^[A-Za-z_][A-Za-z0-9_.-]*:[A-Za-z0-9_.-]+$/', $token) === 1;
        }

        return true;
    }

    /**
     * @return array{tokens:list<string>, values:list<string>, invalid:list<string>, valid:bool}
     */
    private static function idReferenceTokenSummary(string $value): array
    {
        $tokens = self::spaceSeparatedTokens($value);
        $values = [];
        $invalid = [];
        foreach ($tokens as $token) {
            if (!self::isHtmlIdReferenceToken($token)) {
                $invalid[] = $token;
                continue;
            }

            if (!in_array($token, $values, true)) {
                $values[] = $token;
            }
        }

        return [
            'tokens' => $tokens,
            'values' => $values,
            'invalid' => $invalid,
            'valid' => $tokens !== [] && $invalid === [],
        ];
    }

    private static function isHtmlIdReferenceToken(string $token): bool
    {
        return $token !== ''
            && preg_match('/[\s<>"\'`\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/u', $token) !== 1;
    }

    /**
     * @param list<string> $ids
     * @return array{resolved:list<string>, missing:list<string>}
     */
    private static function itemRefResolutionSummary(\DOMElement $element, array $ids): array
    {
        $resolved = [];
        $missing = [];
        foreach ($ids as $id) {
            if (self::htmlElementById($element, $id) instanceof \DOMElement) {
                $resolved[] = $id;
                continue;
            }

            $missing[] = $id;
        }

        return [
            'resolved' => $resolved,
            'missing' => $missing,
        ];
    }

    private static function inputModeState(string $value): ?string
    {
        $value = strtolower(trim($value));

        return in_array($value, ['none', 'text', 'tel', 'email', 'url', 'numeric', 'decimal', 'search'], true)
            ? $value
            : null;
    }

    /**
     * @param array<string, string> $attributes
     * @return array<string, mixed>
     */
    private static function inputHintReviewSummary(\DOMElement $element, array $attributes): array
    {
        $inputMode = array_key_exists('inputmode', $attributes)
            ? self::inputModeState($attributes['inputmode'])
            : null;
        $enterKeyHint = array_key_exists('enterkeyhint', $attributes)
            ? self::enterKeyHintState($attributes['enterkeyhint'])
            : null;
        $issueCodes = [];

        if (array_key_exists('inputmode', $attributes) && $inputMode === null) {
            $issueCodes[] = 'invalid-html-inputmode-token';
        }

        if (array_key_exists('enterkeyhint', $attributes) && $enterKeyHint === null) {
            $issueCodes[] = 'invalid-html-enterkeyhint-token';
        }

        $summary = [
            'inputHintReviewPolicy' => 'html-input-hint-keyboard-review',
            'inputHintElement' => self::htmlElementName($element),
            'inputHintHostKind' => self::inputHintHostKind($element, $attributes),
            'inputHintIssueCodes' => $issueCodes,
            'inputHintValid' => $issueCodes === [],
        ];

        if (array_key_exists('inputmode', $attributes)) {
            $summary['inputModeKeyboardKind'] = $inputMode === null ? null : self::inputModeKeyboardKind($inputMode);
        }

        if (array_key_exists('enterkeyhint', $attributes)) {
            $summary['enterKeyHintActionKind'] = $enterKeyHint === null ? null : self::enterKeyHintActionKind($enterKeyHint);
        }

        return $summary;
    }

    /**
     * @param array<string, string> $attributes
     */
    private static function inputHintHostKind(\DOMElement $element, array $attributes): string
    {
        $name = self::htmlElementName($element);
        if ($name === 'input' || $name === 'textarea') {
            return 'text-entry-control';
        }

        if (array_key_exists('contenteditable', $attributes) && self::contentEditableState($attributes['contenteditable']) !== false) {
            return 'editable-host';
        }

        return 'generic-element';
    }

    private static function inputModeKeyboardKind(string $inputMode): string
    {
        return match ($inputMode) {
            'none' => 'none',
            'tel' => 'telephone',
            'email' => 'email-address',
            'url' => 'url',
            'numeric' => 'numeric',
            'decimal' => 'decimal',
            'search' => 'search',
            default => 'text',
        };
    }

    private static function enterKeyHintActionKind(string $enterKeyHint): string
    {
        return match ($enterKeyHint) {
            'done' => 'completion',
            'go' => 'navigation',
            'next', 'previous' => 'form-navigation',
            'search' => 'search',
            'send' => 'submission',
            default => 'default-enter',
        };
    }

    private static function draggableState(string $value): bool|string|null
    {
        $value = strtolower(trim($value));

        return match ($value) {
            'true' => true,
            'false' => false,
            'auto' => 'auto',
            default => null,
        };
    }

    private static function enterKeyHintState(string $value): ?string
    {
        $value = strtolower(trim($value));

        return in_array($value, ['enter', 'done', 'go', 'next', 'previous', 'search', 'send'], true)
            ? $value
            : null;
    }

    private static function autocapitalizeState(string $value): ?string
    {
        $value = strtolower(trim($value));

        return match ($value) {
            'off', 'none' => 'none',
            'on', 'sentences' => 'sentences',
            'words' => 'words',
            'characters' => 'characters',
            default => null,
        };
    }

    /**
     * @return array<string, mixed>
     */
    private static function draggableAttributeSummary(\DOMElement $element, string $raw): array
    {
        $state = self::draggableState($raw);
        $auto = $state === 'auto' || $state === null;
        $effective = $auto ? self::draggableAutoDefault($element) : $state;
        $summary = [
            'draggableRaw' => $raw,
            'draggable' => $state,
            'draggableKeyword' => match ($state) {
                true => 'true',
                false => 'false',
                'auto' => 'auto',
                default => null,
            },
            'draggableState' => $auto ? 'auto' : ($state ? 'true' : 'false'),
            'draggableValid' => $state !== null,
            'draggableInvalidValueDefaulted' => $state === null,
            'effectiveDraggable' => $effective,
            'draggableSource' => match ($state) {
                true => 'attribute-true',
                false => 'attribute-false',
                'auto' => 'attribute-auto',
                default => 'auto-default',
            },
        ];

        if ($auto) {
            $summary['draggableAutoReason'] = self::draggableAutoReason($element);
        }

        return $summary;
    }

    private static function draggableAutoDefault(\DOMElement $element): bool
    {
        return in_array(self::draggableAutoReason($element), [
            'image-element',
            'hyperlink-element',
            'declared-image-object',
        ], true);
    }

    private static function draggableAutoReason(\DOMElement $element): string
    {
        $name = self::htmlElementName($element);
        if ($name === 'img') {
            return 'image-element';
        }
        if ($name === 'a' && trim(self::attributeOrNull($element, 'href') ?? '') !== '') {
            return 'hyperlink-element';
        }
        if ($name === 'object') {
            $type = strtolower(trim(self::attributeOrNull($element, 'type') ?? ''));
            if (str_starts_with($type, 'image/')) {
                return 'declared-image-object';
            }
        }

        return 'element-default';
    }

    /**
     * @return array<string, mixed>
     */
    private static function styleAttributeSummary(string $raw): array
    {
        $declarations = [];
        $issues = [];
        $propertyNames = [];
        $propertyCounts = [];
        $customProperties = [];
        $importantProperties = [];

        foreach (self::styleDeclarationFragments($raw) as $index => $fragment) {
            $declaration = trim($fragment);
            if ($declaration === '') {
                continue;
            }

            $colonOffset = self::styleDeclarationColonOffset($declaration);
            if ($colonOffset === null) {
                $issues[] = [
                    'index' => $index,
                    'raw' => $declaration,
                    'code' => 'missing-style-declaration-colon',
                ];
                continue;
            }

            $propertyRaw = trim(substr($declaration, 0, $colonOffset));
            $property = strtolower($propertyRaw);
            $value = trim(substr($declaration, $colonOffset + 1));
            if ($propertyRaw === '') {
                $issues[] = [
                    'index' => $index,
                    'raw' => $declaration,
                    'code' => 'missing-style-property',
                ];
                continue;
            }
            if (!self::isSafeStylePropertyName($propertyRaw)) {
                $issues[] = [
                    'index' => $index,
                    'raw' => $declaration,
                    'code' => 'invalid-style-property',
                    'propertyRaw' => $propertyRaw,
                ];
                continue;
            }
            if ($value === '') {
                $issues[] = [
                    'index' => $index,
                    'raw' => $declaration,
                    'code' => 'missing-style-value',
                    'propertyRaw' => $propertyRaw,
                    'property' => $property,
                ];
                continue;
            }

            $important = preg_match('/!\s*important\s*$/i', $value) === 1;
            if ($important) {
                $value = trim((string) preg_replace('/!\s*important\s*$/i', '', $value));
            }

            $declarations[] = [
                'index' => $index,
                'raw' => $declaration,
                'propertyRaw' => $propertyRaw,
                'property' => $property,
                'value' => $value,
                'important' => $important,
            ];

            if (!isset($propertyCounts[$property])) {
                $propertyCounts[$property] = 0;
                $propertyNames[] = $property;
            }
            ++$propertyCounts[$property];

            if (str_starts_with($property, '--') && !in_array($property, $customProperties, true)) {
                $customProperties[] = $property;
            }
            if ($important && !in_array($property, $importantProperties, true)) {
                $importantProperties[] = $property;
            }
        }

        return [
            'styleAttributeReviewPolicy' => 'html-style-attribute-declaration-review',
            'styleRaw' => $raw,
            'styleByteLength' => strlen($raw),
            'styleSha256' => hash('sha256', $raw),
            'styleDeclarations' => $declarations,
            'styleDeclarationCount' => count($declarations),
            'stylePropertyNames' => $propertyNames,
            'stylePropertyCounts' => $propertyCounts,
            'duplicateStyleProperties' => array_values(array_filter(
                $propertyNames,
                static fn (string $property): bool => ($propertyCounts[$property] ?? 0) > 1
            )),
            'customStyleProperties' => $customProperties,
            'importantStyleProperties' => $importantProperties,
            'invalidStyleDeclarations' => $issues,
            'invalidStyleDeclarationCount' => count($issues),
            'styleDeclarationIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ))),
        ];
    }

    /**
     * @return list<string>
     */
    private static function styleDeclarationFragments(string $raw): array
    {
        $fragments = [];
        $current = '';
        $quote = null;
        $escaped = false;
        $parenDepth = 0;
        $length = strlen($raw);

        for ($offset = 0; $offset < $length; ++$offset) {
            $char = $raw[$offset];

            if ($escaped) {
                $current .= $char;
                $escaped = false;
                continue;
            }

            if ($quote !== null) {
                $current .= $char;
                if ($char === '\\') {
                    $escaped = true;
                } elseif ($char === $quote) {
                    $quote = null;
                }
                continue;
            }

            if ($char === '"' || $char === "'") {
                $quote = $char;
                $current .= $char;
                continue;
            }
            if ($char === '(') {
                ++$parenDepth;
                $current .= $char;
                continue;
            }
            if ($char === ')' && $parenDepth > 0) {
                --$parenDepth;
                $current .= $char;
                continue;
            }
            if ($char === ';' && $parenDepth === 0) {
                $fragments[] = $current;
                $current = '';
                continue;
            }

            $current .= $char;
        }

        $fragments[] = $current;

        return $fragments;
    }

    private static function styleDeclarationColonOffset(string $declaration): ?int
    {
        $quote = null;
        $escaped = false;
        $parenDepth = 0;
        $length = strlen($declaration);

        for ($offset = 0; $offset < $length; ++$offset) {
            $char = $declaration[$offset];

            if ($escaped) {
                $escaped = false;
                continue;
            }
            if ($quote !== null) {
                if ($char === '\\') {
                    $escaped = true;
                } elseif ($char === $quote) {
                    $quote = null;
                }
                continue;
            }
            if ($char === '"' || $char === "'") {
                $quote = $char;
                continue;
            }
            if ($char === '(') {
                ++$parenDepth;
                continue;
            }
            if ($char === ')' && $parenDepth > 0) {
                --$parenDepth;
                continue;
            }
            if ($char === ':' && $parenDepth === 0) {
                return $offset;
            }
        }

        return null;
    }

    private static function isSafeStylePropertyName(string $property): bool
    {
        return preg_match('/^(?:--[A-Za-z0-9_-]+|-?[A-Za-z_][A-Za-z0-9_-]*)$/', $property) === 1;
    }

    private static function autocorrectState(string $value): ?string
    {
        $value = strtolower(trim($value));

        return match ($value) {
            '', 'on' => 'on',
            'off' => 'off',
            default => null,
        };
    }

    private static function writingSuggestionsState(string $value): ?bool
    {
        $value = strtolower(trim($value));

        return match ($value) {
            '', 'true' => true,
            'false' => false,
            default => null,
        };
    }

    private static function virtualKeyboardPolicyState(string $value): ?string
    {
        $value = strtolower(trim($value));

        return match ($value) {
            '', 'auto' => 'auto',
            'manual' => 'manual',
            default => null,
        };
    }

    /**
     * @param array<string, string> $attributes
     * @return array<string, mixed>
     */
    private static function editAssistanceReviewSummary(\DOMElement $element, array $attributes): array
    {
        $autocorrect = array_key_exists('autocorrect', $attributes)
            ? self::autocorrectState($attributes['autocorrect'])
            : null;
        $writingSuggestions = array_key_exists('writingsuggestions', $attributes)
            ? self::writingSuggestionsState($attributes['writingsuggestions'])
            : null;
        $virtualKeyboardPolicy = array_key_exists('virtualkeyboardpolicy', $attributes)
            ? self::virtualKeyboardPolicyState($attributes['virtualkeyboardpolicy'])
            : null;
        $issueCodes = [];

        if (array_key_exists('autocorrect', $attributes) && $autocorrect === null) {
            $issueCodes[] = 'invalid-html-autocorrect-token';
        }
        if (array_key_exists('writingsuggestions', $attributes) && $writingSuggestions === null) {
            $issueCodes[] = 'invalid-html-writingsuggestions-token';
        }
        if (array_key_exists('virtualkeyboardpolicy', $attributes) && $virtualKeyboardPolicy === null) {
            $issueCodes[] = 'invalid-html-virtualkeyboardpolicy-token';
        }

        $summary = [
            'editAssistanceReviewPolicy' => 'html-edit-assistance-policy-review',
            'editAssistanceElement' => self::htmlElementName($element),
            'editAssistanceHostKind' => self::editAssistanceHostKind($element, $attributes),
            'editAssistanceAttributes' => array_values(array_filter(
                ['autocorrect', 'writingsuggestions', 'virtualkeyboardpolicy'],
                static fn (string $attribute): bool => array_key_exists($attribute, $attributes)
            )),
            'editAssistanceIssueCodes' => $issueCodes,
            'editAssistanceValid' => $issueCodes === [],
        ];

        if (array_key_exists('autocorrect', $attributes)) {
            $summary['editAutocorrectState'] = $autocorrect;
            $summary['editAutocorrectEnabled'] = $autocorrect === null ? null : $autocorrect === 'on';
        }
        if (array_key_exists('writingsuggestions', $attributes)) {
            $summary['editWritingSuggestionsEnabled'] = $writingSuggestions;
        }
        if (array_key_exists('virtualkeyboardpolicy', $attributes)) {
            $summary['editVirtualKeyboardPolicy'] = $virtualKeyboardPolicy;
            $summary['editVirtualKeyboardControlMode'] = match ($virtualKeyboardPolicy) {
                'auto' => 'automatic',
                'manual' => 'manual',
                default => null,
            };
        }

        return $summary;
    }

    /**
     * @param array<string, string> $attributes
     */
    private static function editAssistanceHostKind(\DOMElement $element, array $attributes): string
    {
        $name = self::htmlElementName($element);
        if ($name === 'input' || $name === 'textarea') {
            return 'text-entry-control';
        }

        if (array_key_exists('contenteditable', $attributes)) {
            $state = self::contentEditableState($attributes['contenteditable']);
            if ($state !== null) {
                return $state === false ? 'explicitly-non-editable' : 'editable-host';
            }
        }

        for ($ancestor = $element->parentNode; $ancestor instanceof \DOMElement; $ancestor = $ancestor->parentNode) {
            $ancestorAttributes = self::htmlAttributes($ancestor);
            if (!array_key_exists('contenteditable', $ancestorAttributes)) {
                continue;
            }

            $state = self::contentEditableState($ancestorAttributes['contenteditable']);
            if ($state !== null) {
                return $state === false ? 'inherited-non-editable' : 'editable-descendant';
            }
        }

        return 'generic-element';
    }

    private static function popoverState(string $value): ?string
    {
        $value = strtolower(trim($value));

        return match ($value) {
            '', 'auto' => 'auto',
            'manual' => 'manual',
            default => null,
        };
    }

    private static function popoverTarget(string $value): ?string
    {
        $target = trim($value);
        if ($target === '' || preg_match('/[\s<>"\'`]/u', $target) === 1) {
            return null;
        }

        return $target;
    }

    /**
     * @return array<string, mixed>
     */
    private static function popoverTargetReferenceSummary(\DOMElement $element, string $targetRaw, ?string $targetId): array
    {
        $target = $targetId === null ? null : self::htmlElementById($element, $targetId);
        $issues = [];

        if ($targetId === null) {
            $issues[] = [
                'code' => 'invalid-popover-target-reference',
                'targetRaw' => $targetRaw,
            ];
        } elseif (!$target instanceof \DOMElement) {
            $issues[] = [
                'code' => 'missing-popover-target',
                'targetId' => $targetId,
            ];
        } else {
            $popoverRaw = self::attributeOrNull($target, 'popover');
            if ($popoverRaw === null) {
                $issues[] = [
                    'code' => 'non-popover-target',
                    'targetId' => $targetId,
                    'targetName' => self::htmlElementName($target),
                ];
            } elseif (self::popoverState($popoverRaw) === null) {
                $issues[] = [
                    'code' => 'invalid-popover-target-state',
                    'targetId' => $targetId,
                    'popoverRaw' => $popoverRaw,
                ];
            }
        }

        return [
            'popoverTargetReviewPolicy' => 'popover-target-idref-review',
            'popoverTargetFound' => $target instanceof \DOMElement,
            'popoverTargetKind' => self::popoverTargetKind($target, $targetRaw, $targetId),
            'popoverTargetElement' => $target instanceof \DOMElement ? self::popoverTargetElementSummary($target) : null,
            'popoverTargetIssues' => $issues,
            'popoverTargetIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ))),
            'popoverTargetInvokesPopover' => $issues === [],
        ];
    }

    private static function popoverTargetKind(?\DOMElement $target, string $targetRaw, ?string $targetId): string
    {
        if (!$target instanceof \DOMElement) {
            if ($targetId === null) {
                return trim($targetRaw) === '' ? 'missing-reference' : 'invalid-reference';
            }

            return 'missing-target';
        }

        return self::attributeOrNull($target, 'popover') === null ? 'element' : 'popover';
    }

    /**
     * @return array<string, mixed>
     */
    private static function popoverTargetElementSummary(\DOMElement $target): array
    {
        $popoverRaw = self::attributeOrNull($target, 'popover');
        $popover = $popoverRaw === null ? null : self::popoverState($popoverRaw);

        return [
            'tag' => self::htmlElementName($target),
            'id' => self::attributeOrNull($target, 'id'),
            'text' => self::normalizedText($target),
            'popoverRaw' => $popoverRaw,
            'popoverState' => $popover,
            'popoverValid' => $popover !== null,
        ];
    }

    private static function popoverTargetAction(string $value): ?string
    {
        $value = strtolower(trim($value));

        return in_array($value, ['', 'hide', 'show', 'toggle'], true) ? ($value === '' ? 'toggle' : $value) : null;
    }

    /**
     * @return array{tokens:list<string>, names:list<string>, counts:array<string, int>, invalid:list<string>, duplicates:list<string>, primary:?string, valid:bool}
     */
    private static function htmlRoleAttributeSummary(string $value): array
    {
        $tokens = self::spaceSeparatedTokens($value);
        $names = [];
        $counts = [];
        $invalid = [];
        $duplicates = [];
        $primary = null;

        foreach ($tokens as $token) {
            if (!self::isHtmlRoleToken($token)) {
                $invalid[] = $token;
                continue;
            }

            $name = strtolower($token);
            if ($primary === null) {
                $primary = $name;
            }

            $counts[$name] = ($counts[$name] ?? 0) + 1;
            if ($counts[$name] === 1) {
                $names[] = $name;
                continue;
            }

            if ($counts[$name] === 2) {
                $duplicates[] = $name;
            }
        }

        return [
            'tokens' => $tokens,
            'names' => $names,
            'counts' => $counts,
            'invalid' => $invalid,
            'duplicates' => $duplicates,
            'primary' => $primary,
            'valid' => $tokens !== [] && $invalid === [],
        ];
    }

    private static function isHtmlRoleToken(string $token): bool
    {
        return preg_match('/^[A-Za-z][A-Za-z0-9_-]*$/', $token) === 1;
    }

    /**
     * @return array{name:?string, valid:bool}
     */
    private static function slotAttributeSummary(string $value): array
    {
        $name = trim($value);

        return [
            'name' => $name === '' ? null : $name,
            'valid' => $name !== '' && self::isHtmlReferenceToken($name),
        ];
    }

    /**
     * @return array{tokens:list<string>, names:list<string>, invalid:list<string>, duplicates:list<string>, issueCodes:list<string>, valid:bool}
     */
    private static function partTokenListSummary(string $value): array
    {
        $tokens = self::spaceSeparatedTokens($value);
        $names = [];
        $invalid = [];
        $duplicates = [];
        foreach ($tokens as $token) {
            if (!self::isHtmlReferenceToken($token)) {
                $invalid[] = $token;
                continue;
            }

            if (in_array($token, $names, true)) {
                if (!in_array($token, $duplicates, true)) {
                    $duplicates[] = $token;
                }
                continue;
            }

            $names[] = $token;
        }
        $issueCodes = [];
        if ($invalid !== []) {
            $issueCodes[] = 'invalid-part-token';
        }
        if ($duplicates !== []) {
            $issueCodes[] = 'duplicate-part-token';
        }

        return [
            'tokens' => $tokens,
            'names' => $names,
            'invalid' => $invalid,
            'duplicates' => $duplicates,
            'issueCodes' => $issueCodes,
            'valid' => $tokens !== [] && $invalid === [],
        ];
    }

    /**
     * @return array{items:list<array<string, mixed>>, names:list<string>, aliases:list<string>, invalid:list<string>, duplicateNames:list<string>, duplicateAliases:list<string>, issueCodes:list<string>, valid:bool}
     */
    private static function exportPartsSummary(string $value): array
    {
        $items = [];
        $names = [];
        $aliases = [];
        $invalid = [];
        $allNames = [];
        $allAliases = [];
        foreach (explode(',', $value) as $rawItem) {
            $raw = trim($rawItem);
            if ($raw === '') {
                continue;
            }

            $segments = array_map('trim', explode(':', $raw));
            $source = $segments[0] ?? '';
            $alias = count($segments) === 1 ? $source : ($segments[1] ?? '');
            $valid = count($segments) <= 2
                && self::isHtmlReferenceToken($source)
                && self::isHtmlReferenceToken($alias);
            if (!$valid) {
                $invalid[] = $raw;
            } else {
                $allNames[] = $source;
                $allAliases[] = $alias;
                if (!in_array($source, $names, true)) {
                    $names[] = $source;
                }
                if (!in_array($alias, $aliases, true)) {
                    $aliases[] = $alias;
                }
            }

            $items[] = [
                'raw' => $raw,
                'source' => $source === '' ? null : $source,
                'alias' => $alias === '' ? null : $alias,
                'renamed' => $valid && $source !== $alias,
                'valid' => $valid,
            ];
        }
        $duplicateNames = self::duplicateStringValues($allNames);
        $duplicateAliases = self::duplicateStringValues($allAliases);
        $issueCodes = [];
        if ($invalid !== []) {
            $issueCodes[] = 'invalid-exportparts-mapping';
        }
        if ($duplicateNames !== []) {
            $issueCodes[] = 'duplicate-exportparts-source';
        }
        if ($duplicateAliases !== []) {
            $issueCodes[] = 'duplicate-exportparts-alias';
        }

        return [
            'items' => $items,
            'names' => $names,
            'aliases' => $aliases,
            'invalid' => $invalid,
            'duplicateNames' => $duplicateNames,
            'duplicateAliases' => $duplicateAliases,
            'issueCodes' => $issueCodes,
            'valid' => $items !== [] && $invalid === [],
        ];
    }

    /**
     * @param array<string, string> $attributes
     * @return array<string, mixed>
     */
    private static function partExportReviewSummary(\DOMElement $element, array $attributes): array
    {
        $part = array_key_exists('part', $attributes)
            ? self::partTokenListSummary($attributes['part'])
            : ['tokens' => [], 'names' => [], 'invalid' => [], 'valid' => true];
        $duplicatePartTokens = self::duplicateStringValues($part['tokens']);
        $visibleParts = self::visiblePartRecords($element);
        $visiblePartNames = [];
        foreach ($visibleParts as $record) {
            self::appendUniqueString($visiblePartNames, (string) $record['name']);
        }

        $exportParts = array_key_exists('exportparts', $attributes)
            ? self::exportPartsSummary($attributes['exportparts'])
            : ['items' => [], 'names' => [], 'aliases' => [], 'invalid' => [], 'valid' => true];
        $exportMappings = [];
        $observedExportPartNames = [];
        $unobservedExportPartNames = [];
        $validSources = [];
        $validAliases = [];
        $renamedCount = 0;
        foreach ($exportParts['items'] as $item) {
            $source = is_string($item['source'] ?? null) ? $item['source'] : null;
            $alias = is_string($item['alias'] ?? null) ? $item['alias'] : null;
            $valid = ($item['valid'] ?? false) === true;
            $matches = $valid && $source !== null ? self::partRecordsForName($visibleParts, $source) : [];

            if ($valid && $source !== null) {
                $validSources[] = $source;
                if ($alias !== null) {
                    $validAliases[] = $alias;
                }
                if (($item['renamed'] ?? false) === true) {
                    ++$renamedCount;
                }
                if ($matches === []) {
                    self::appendUniqueString($unobservedExportPartNames, $source);
                } else {
                    self::appendUniqueString($observedExportPartNames, $source);
                }
            }

            $exportMappings[] = [
                'raw' => $item['raw'] ?? '',
                'source' => $source,
                'alias' => $alias,
                'renamed' => ($item['renamed'] ?? false) === true,
                'valid' => $valid,
                'sourceObservedInFragment' => $matches !== [],
                'sourceElementIds' => self::partRecordFieldValues($matches, 'id'),
                'sourceElementNames' => self::partRecordFieldValues($matches, 'element'),
            ];
        }

        $duplicateExportPartSources = self::duplicateStringValues($validSources);
        $duplicateExportPartAliases = self::duplicateStringValues($validAliases);
        $issueCodes = [];
        if (($part['invalid'] ?? []) !== []) {
            $issueCodes[] = 'invalid-part-token';
        }
        if ($duplicatePartTokens !== []) {
            $issueCodes[] = 'duplicate-part-token';
        }
        if (($exportParts['invalid'] ?? []) !== []) {
            $issueCodes[] = 'invalid-exportparts-mapping';
        }
        if ($duplicateExportPartSources !== []) {
            $issueCodes[] = 'duplicate-exportparts-source';
        }
        if ($duplicateExportPartAliases !== []) {
            $issueCodes[] = 'duplicate-exportparts-alias';
        }
        if ($unobservedExportPartNames !== []) {
            $issueCodes[] = 'unobserved-exportparts-source';
        }

        return [
            'partExportReviewPolicy' => 'html-part-exportparts-fragment-review',
            'partExportElement' => self::htmlElementName($element),
            'partExportElementId' => self::attributeOrNull($element, 'id'),
            'partDuplicateTokens' => $duplicatePartTokens,
            'visiblePartNames' => $visiblePartNames,
            'visiblePartCount' => count($visibleParts),
            'visibleParts' => $visibleParts,
            'exportPartMappingCount' => count($exportParts['items']),
            'validExportPartMappingCount' => count($validSources),
            'renamedExportPartMappingCount' => $renamedCount,
            'exportPartMappings' => $exportMappings,
            'observedExportPartNames' => $observedExportPartNames,
            'unobservedExportPartNames' => $unobservedExportPartNames,
            'duplicateExportPartSources' => $duplicateExportPartSources,
            'duplicateExportPartAliases' => $duplicateExportPartAliases,
            'partExportIssueCodes' => $issueCodes,
            'partExportValid' => $issueCodes === [],
        ];
    }

    /**
     * @return list<array{name:string, element:string, id:?string, source:string}>
     */
    private static function visiblePartRecords(\DOMElement $element): array
    {
        $records = [];
        foreach (self::elementAndDescendantHtmlElements($element) as $candidate) {
            $partRaw = self::attributeOrNull($candidate, 'part');
            if ($partRaw === null) {
                continue;
            }

            $parts = self::partTokenListSummary($partRaw);
            foreach ($parts['names'] as $name) {
                $records[] = [
                    'name' => $name,
                    'element' => self::htmlElementName($candidate),
                    'id' => self::attributeOrNull($candidate, 'id'),
                    'source' => $candidate->isSameNode($element) ? 'self' : 'descendant',
                ];
            }
        }

        return $records;
    }

    /**
     * @return list<\DOMElement>
     */
    private static function elementAndDescendantHtmlElements(\DOMElement $element): array
    {
        $elements = [$element];
        foreach ($element->getElementsByTagName('*') as $descendant) {
            if ($descendant instanceof \DOMElement) {
                $elements[] = $descendant;
            }
        }

        return $elements;
    }

    /**
     * @param list<array{name:string, element:string, id:?string, source:string}> $records
     * @return list<array{name:string, element:string, id:?string, source:string}>
     */
    private static function partRecordsForName(array $records, string $name): array
    {
        return array_values(array_filter(
            $records,
            static fn (array $record): bool => $record['name'] === $name
        ));
    }

    /**
     * @param list<array{name:string, element:string, id:?string, source:string}> $records
     * @return list<string>
     */
    private static function partRecordFieldValues(array $records, string $field): array
    {
        $values = [];
        foreach ($records as $record) {
            $value = $record[$field] ?? null;
            if (is_string($value)) {
                self::appendUniqueString($values, $value);
            }
        }

        return $values;
    }

    /**
     * @return array{name:?string, valid:bool}
     */
    private static function customElementNameSummary(string $value): array
    {
        $name = trim($value);

        return [
            'name' => $name === '' ? null : $name,
            'valid' => $name !== ''
                && preg_match('/^[a-z][.0-9_a-z-]*-[.0-9_a-z-]*$/', $name) === 1
                && self::isHtmlReferenceToken($name),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function customElementTagSummary(string $name): array
    {
        if (!str_contains($name, '-')) {
            return [];
        }

        $customElement = self::customElementNameSummary($name);
        $reserved = isset(self::HTML_CUSTOM_ELEMENT_RESERVED_NAMES[$name]);
        $valid = $customElement['valid'] && !$reserved;
        $issues = [];

        if (!$customElement['valid']) {
            $issues[] = 'invalid-custom-element-name';
        }
        if ($reserved) {
            $issues[] = 'reserved-custom-element-name';
        }

        return [
            'customElementTagReviewPolicy' => 'html-custom-element-tag-review',
            'customElementTagName' => $name,
            'customElementTagValid' => $valid,
            'customElementTagReservedName' => $reserved,
            'customElementTagIssueCodes' => $issues,
            'autonomousCustomElement' => $valid,
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function slotAssignedElementSummaries(\DOMElement $slot, string $slotName): array
    {
        $parent = $slot->parentNode;
        if (!$parent instanceof \DOMElement) {
            return [];
        }

        $assigned = [];
        foreach ($parent->childNodes as $candidate) {
            if (!$candidate instanceof \DOMElement || $candidate->isSameNode($slot)) {
                continue;
            }
            if (self::htmlElementName($candidate) === 'slot') {
                continue;
            }

            $candidateSlotRaw = self::attributeOrNull($candidate, 'slot');
            if ($slotName === '') {
                if ($candidateSlotRaw !== null && trim($candidateSlotRaw) !== '') {
                    continue;
                }
            } else {
                if ($candidateSlotRaw === null) {
                    continue;
                }
                $candidateSlot = self::slotAttributeSummary($candidateSlotRaw);
                if (!$candidateSlot['valid'] || $candidateSlot['name'] !== $slotName) {
                    continue;
                }
            }

            $assigned[] = self::slotAssignedElementSummary($candidate, $candidateSlotRaw);
        }

        return $assigned;
    }

    /**
     * @return array<string, mixed>
     */
    private static function slotAssignedElementSummary(\DOMElement $element, ?string $slotRaw): array
    {
        $slot = $slotRaw === null
            ? ['name' => null, 'valid' => true]
            : self::slotAttributeSummary($slotRaw);

        return [
            'tag' => self::htmlElementName($element),
            'id' => self::attributeOrNull($element, 'id'),
            'slotRaw' => $slotRaw,
            'slotName' => $slot['name'],
            'slotValid' => $slot['valid'],
            'text' => self::normalizedText($element),
        ];
    }

    /**
     * @return list<string>
     */
    private static function slotFallbackElementNames(\DOMElement $slot): array
    {
        $names = [];
        foreach ($slot->childNodes as $child) {
            if ($child instanceof \DOMElement) {
                $names[] = self::htmlElementName($child);
            }
        }

        return $names;
    }

    private static function isHtmlReferenceToken(string $token): bool
    {
        return $token !== ''
            && preg_match('/[\s<>"\'`=,:\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/u', $token) !== 1;
    }

    /**
     * @return array{tokens:list<string>, items:list<array<string, mixed>>, effects:list<string>, stringTypes:list<string>, fileTypes:list<string>, invalid:list<string>, multipleEffects:bool, valid:bool}
     */
    private static function dropZoneSummary(string $value): array
    {
        $tokens = self::spaceSeparatedTokens($value);
        $items = [];
        $effects = [];
        $stringTypes = [];
        $fileTypes = [];
        $invalid = [];

        foreach ($tokens as $token) {
            $lower = strtolower($token);
            $item = [
                'raw' => $token,
                'kind' => null,
                'value' => null,
                'valid' => false,
            ];

            if (in_array($lower, ['copy', 'move', 'link'], true)) {
                $item['kind'] = 'effect';
                $item['value'] = $lower;
                $item['valid'] = true;
                self::appendUniqueString($effects, $lower);
            } elseif (str_starts_with($lower, 'string:')) {
                $type = substr($lower, 7);
                $item['kind'] = 'string';
                $item['value'] = self::isHtmlDropZoneMimeType($type) ? $type : null;
                $item['valid'] = $item['value'] !== null;
                if ($item['valid']) {
                    self::appendUniqueString($stringTypes, $type);
                }
            } elseif (str_starts_with($lower, 'file:')) {
                $type = substr($lower, 5);
                $item['kind'] = 'file';
                $item['value'] = self::isHtmlDropZoneMimeType($type) ? $type : null;
                $item['valid'] = $item['value'] !== null;
                if ($item['valid']) {
                    self::appendUniqueString($fileTypes, $type);
                }
            }

            if (!$item['valid']) {
                $invalid[] = $token;
            }
            $items[] = $item;
        }

        return [
            'tokens' => $tokens,
            'items' => $items,
            'effects' => $effects,
            'stringTypes' => $stringTypes,
            'fileTypes' => $fileTypes,
            'invalid' => $invalid,
            'multipleEffects' => count($effects) > 1,
            'valid' => $tokens !== [] && $invalid === [] && count($effects) <= 1,
        ];
    }

    private static function isHtmlDropZoneMimeType(string $value): bool
    {
        return preg_match('/^[a-z0-9!#$&^_.+-]+\/(?:[a-z0-9!#$&^_.+-]+|\*)$/', $value) === 1;
    }

    /**
     * @return array{tokens:list<string>, keys:list<string>, invalid:list<string>, duplicates:list<string>, valid:bool}
     */
    private static function accessKeySummary(string $value): array
    {
        $tokens = self::spaceSeparatedTokens($value);
        $keys = [];
        $invalid = [];
        $duplicates = [];
        foreach ($tokens as $token) {
            if (!self::isAccessKeyToken($token)) {
                $invalid[] = $token;
                continue;
            }

            if (!in_array($token, $keys, true)) {
                $keys[] = $token;
                continue;
            }

            if (!in_array($token, $duplicates, true)) {
                $duplicates[] = $token;
            }
        }

        return [
            'tokens' => $tokens,
            'keys' => $keys,
            'invalid' => $invalid,
            'duplicates' => $duplicates,
            'valid' => $tokens !== [] && $keys !== [] && $invalid === [],
        ];
    }

    /**
     * @param list<string> $keys
     * @return array<string, mixed>
     */
    private static function accessKeyDocumentSummary(\DOMElement $element, array $keys): array
    {
        if ($keys === []) {
            return [
                'accessKeyReviewPolicy' => 'document-accesskey-assignment-review',
                'accessKeyDocumentAssignmentCount' => 0,
                'accessKeyDocumentAssignments' => [],
                'accessKeyConflictKeys' => [],
                'accessKeyConflictCount' => 0,
                'accessKeyConflicts' => [],
                'accessKeyHasConflict' => false,
            ];
        }

        $assignments = [];
        $document = $element->ownerDocument;
        if ($document instanceof \DOMDocument) {
            $index = 0;
            foreach ($document->getElementsByTagName('*') as $candidate) {
                if (!$candidate instanceof \DOMElement || !$candidate->hasAttribute('accesskey')) {
                    continue;
                }

                $candidateKeys = self::accessKeySummary($candidate->getAttribute('accesskey'))['keys'];
                foreach ($candidateKeys as $key) {
                    if ($keys !== [] && !in_array($key, $keys, true)) {
                        continue;
                    }

                    $assignments[] = [
                        'key' => $key,
                        'index' => $index,
                        'tag' => self::htmlElementName($candidate),
                        'id' => self::attributeOrNull($candidate, 'id'),
                        'current' => $candidate->isSameNode($element),
                        'text' => self::normalizedText($candidate),
                    ];
                }
                ++$index;
            }
        }

        $keyCounts = [];
        foreach ($assignments as $assignment) {
            $key = (string) $assignment['key'];
            $keyCounts[$key] = ($keyCounts[$key] ?? 0) + 1;
        }

        $conflictKeys = [];
        foreach ($keyCounts as $key => $count) {
            if ($count > 1) {
                $conflictKeys[] = $key;
            }
        }

        $conflicts = array_values(array_filter(
            $assignments,
            static fn (array $assignment): bool => in_array((string) $assignment['key'], $conflictKeys, true)
        ));

        return [
            'accessKeyReviewPolicy' => 'document-accesskey-assignment-review',
            'accessKeyDocumentAssignmentCount' => count($assignments),
            'accessKeyDocumentAssignments' => $assignments,
            'accessKeyConflictKeys' => $conflictKeys,
            'accessKeyConflictCount' => count($conflictKeys),
            'accessKeyConflicts' => $conflicts,
            'accessKeyHasConflict' => $conflictKeys !== [],
        ];
    }

    private static function isAccessKeyToken(string $token): bool
    {
        if ($token === '' || preg_match('/[<>"\'`{}]/u', $token) === 1) {
            return false;
        }
        if (preg_match('/[\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/u', $token) === 1) {
            return false;
        }

        return preg_match_all('/./us', $token) === 1;
    }

    /**
     * @param array<string, mixed> $summary
     * @return list<string>
     */
    private static function accessKeyIssueCodes(array $summary): array
    {
        $issueCodes = [];

        $tokens = $summary['accessKeyTokens'] ?? [];
        if ($tokens === []) {
            $issueCodes[] = 'empty-accesskey-token-list';
        }
        if (($summary['invalidAccessKeyTokens'] ?? []) !== []) {
            $issueCodes[] = 'invalid-accesskey-token';
        }
        if (($summary['duplicateAccessKeyTokens'] ?? []) !== []) {
            $issueCodes[] = 'duplicate-accesskey-token';
        }
        if (($summary['accessKeyHasConflict'] ?? false) === true) {
            $issueCodes[] = 'document-accesskey-conflict';
        }

        return $issueCodes;
    }

    /**
     * @param list<string> $keys
     * @return array<string, mixed>
     */
    private static function accessKeyCollisionSummary(\DOMElement $element, array $keys): array
    {
        $collisions = [];

        foreach ($keys as $key) {
            $candidates = self::accessKeyCandidatesForKey($element, $key);
            if (count($candidates) <= 1) {
                continue;
            }

            $currentIndex = null;
            $candidateIds = [];
            $candidateSummaries = [];

            foreach ($candidates as $index => $candidate) {
                $current = $candidate->isSameNode($element);
                if ($current) {
                    $currentIndex = $index;
                }

                $candidateId = self::attributeOrNull($candidate, 'id');
                if ($candidateId !== null && $candidateId !== '') {
                    $candidateIds[] = $candidateId;
                }

                $candidateSummaries[] = self::accessKeyCandidateSummary($candidate, $key, $current);
            }

            if ($currentIndex === null) {
                continue;
            }

            $collisions[] = [
                'key' => $key,
                'candidateCount' => count($candidates),
                'candidateIds' => $candidateIds,
                'currentIndex' => $currentIndex,
                'candidates' => $candidateSummaries,
            ];
        }

        if ($collisions === []) {
            return [];
        }

        return [
            'accessKeyCollisionReviewPolicy' => 'html-accesskey-collision-review',
            'accessKeyCollisionKeys' => array_map(
                static fn (array $collision): string => (string) $collision['key'],
                $collisions
            ),
            'accessKeyCollisionCount' => count($collisions),
            'accessKeyHasCollision' => true,
            'accessKeyCollisions' => $collisions,
        ];
    }

    /**
     * @return list<\DOMElement>
     */
    private static function accessKeyCandidatesForKey(\DOMElement $context, string $key): array
    {
        $document = $context->ownerDocument;
        if (!$document instanceof \DOMDocument) {
            return [];
        }

        $candidates = [];
        foreach ($document->getElementsByTagName('*') as $candidate) {
            if (!$candidate instanceof \DOMElement) {
                continue;
            }

            $attributes = self::htmlAttributes($candidate);
            if (!array_key_exists('accesskey', $attributes)) {
                continue;
            }

            $accessKey = self::accessKeySummary($attributes['accesskey']);
            if (in_array($key, $accessKey['keys'], true)) {
                $candidates[] = $candidate;
            }
        }

        return $candidates;
    }

    /**
     * @return array<string, mixed>
     */
    private static function accessKeyCandidateSummary(\DOMElement $element, string $key, bool $current): array
    {
        $attributes = self::htmlAttributes($element);
        $accessKey = self::accessKeySummary($attributes['accesskey'] ?? '');
        $summary = [
            'tag' => self::htmlElementName($element),
            'id' => self::attributeOrNull($element, 'id'),
            'key' => $key,
            'accessKeyRaw' => $attributes['accesskey'] ?? '',
            'accessKeys' => $accessKey['keys'],
            'accessKeyValid' => $accessKey['valid'],
            'current' => $current,
        ];

        $text = self::normalizedText($element);
        if ($text !== '') {
            $summary['text'] = $text;
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function autofocusReviewSummary(\DOMElement $element): array
    {
        $candidates = self::autofocusCandidateSummaries($element);
        $currentIndex = null;
        foreach ($candidates as $candidate) {
            if (($candidate['current'] ?? false) === true) {
                $currentIndex = (int) $candidate['index'];
                break;
            }
        }

        $candidateIds = [];
        foreach ($candidates as $candidate) {
            $id = $candidate['id'] ?? null;
            if (is_string($id) && $id !== '' && !in_array($id, $candidateIds, true)) {
                $candidateIds[] = $id;
            }
        }

        $currentCandidate = $currentIndex !== null ? ($candidates[$currentIndex] ?? null) : null;
        $previousCandidate = $currentIndex !== null && $currentIndex > 0
            ? ($candidates[$currentIndex - 1] ?? null)
            : null;
        $issueCodes = count($candidates) > 1 ? ['multiple-autofocus-candidates'] : [];
        $orderIssueCodes = $currentIndex !== null && $currentIndex > 0
            ? ['autofocus-suppressed-by-earlier-candidate']
            : [];

        return [
            'autofocusReviewPolicy' => 'document-autofocus-candidate-review',
            'autofocusCandidateCount' => count($candidates),
            'autofocusIndex' => $currentIndex,
            'autofocusFirst' => $currentIndex === 0,
            'autofocusConflict' => count($candidates) > 1,
            'autofocusCandidateIds' => $candidateIds,
            'autofocusCandidateElementNames' => array_values(array_map(
                static fn (array $candidate): string => (string) $candidate['tag'],
                $candidates
            )),
            'autofocusFirstCandidateSelected' => $currentIndex === 0,
            'autofocusSuppressedByEarlierCandidate' => $currentIndex !== null && $currentIndex > 0,
            'autofocusFirstCandidate' => $candidates[0] ?? null,
            'autofocusCurrentCandidate' => $currentCandidate,
            'autofocusPreviousCandidate' => $previousCandidate,
            'autofocusCandidates' => $candidates,
            'autofocusIssueCodes' => $issueCodes,
            'autofocusOrderIssueCodes' => $orderIssueCodes,
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function autofocusCandidateSummaries(\DOMElement $context): array
    {
        $document = $context->ownerDocument;
        if (!$document instanceof \DOMDocument) {
            return [];
        }

        $candidates = [];
        foreach ($document->getElementsByTagName('*') as $candidate) {
            if (!$candidate instanceof \DOMElement) {
                continue;
            }

            if (!array_key_exists('autofocus', self::htmlAttributes($candidate))) {
                continue;
            }

            $candidates[] = self::autofocusCandidateSummary($candidate, count($candidates), $candidate->isSameNode($context));
        }

        return $candidates;
    }

    /**
     * @return array<string, mixed>
     */
    private static function autofocusCandidateSummary(\DOMElement $element, int $index, bool $current): array
    {
        $name = self::htmlElementName($element);
        $isControl = self::isFormControlElement($element);
        $summary = [
            'index' => $index,
            'tag' => $name,
            'id' => self::attributeOrNull($element, 'id'),
            'controlName' => self::attributeOrNull($element, 'name'),
            'kind' => self::autofocusCandidateKind($element, $name, $isControl),
            'formControl' => $isControl,
            'current' => $current,
            'text' => self::normalizedText($element),
        ];

        if ($isControl) {
            $summary['effectiveDisabled'] = self::isEffectivelyDisabledFormControl($element);
        }
        if ($name === 'input') {
            $summary['inputType'] = self::inputType($element);
            $summary['value'] = self::attributeOrNull($element, 'value');
        } elseif ($name === 'button') {
            $summary['buttonType'] = self::buttonType($element);
            $summary['value'] = self::attributeOrNull($element, 'value');
            $summary['label'] = self::normalizedText($element);
        } elseif ($name === 'textarea') {
            $summary['value'] = $element->textContent;
        }

        if ($element->hasAttribute('tabindex')) {
            $summary['tabIndex'] = self::integerAttribute($element, 'tabindex', null);
        }

        return $summary;
    }

    private static function autofocusCandidateKind(\DOMElement $element, string $name, bool $isControl): string
    {
        if ($isControl) {
            return 'form-control';
        }
        if (($name === 'a' || $name === 'area') && $element->hasAttribute('href')) {
            return 'hyperlink';
        }
        if (in_array($name, ['iframe', 'object', 'embed'], true)) {
            return 'embedded';
        }
        if ($element->hasAttribute('tabindex')) {
            return 'tabindex';
        }

        return 'element';
    }

    /**
     * @param array<string, string> $attributes
     * @return array<string, string>
     */
    private static function dataAttributeSummary(array $attributes): array
    {
        $data = [];
        foreach ($attributes as $name => $value) {
            if (!str_starts_with($name, 'data-') || strlen($name) <= 5) {
                continue;
            }

            $data[$name] = $value;
        }

        return $data;
    }

    /**
     * @param array<string, string> $dataAttributes
     * @return array<string, string>
     */
    private static function datasetSummary(array $dataAttributes): array
    {
        $dataset = [];
        foreach ($dataAttributes as $name => $value) {
            $datasetName = self::datasetPropertyName($name);
            if ($datasetName !== '') {
                $dataset[$datasetName] = $value;
            }
        }
        ksort($dataset);

        return $dataset;
    }

    private static function datasetPropertyName(string $attributeName): string
    {
        $name = substr($attributeName, 5);
        $property = '';
        $length = strlen($name);
        for ($index = 0; $index < $length; ++$index) {
            $char = $name[$index];
            $next = $index + 1 < $length ? $name[$index + 1] : '';
            if ($char === '-' && $next >= 'a' && $next <= 'z') {
                $property .= strtoupper($next);
                ++$index;
                continue;
            }

            $property .= $char;
        }

        return $property;
    }

    /**
     * @param array<string, string> $attributes
     * @return array<string, string>
     */
    private static function ariaAttributeSummary(array $attributes): array
    {
        $aria = [];
        foreach ($attributes as $name => $value) {
            if (str_starts_with($name, 'aria-') && strlen($name) > 5) {
                $aria[$name] = $value;
            }
        }

        return $aria;
    }

    /**
     * @param array<string, string> $ariaAttributes
     * @return array<string, array<string, mixed>>
     */
    private static function ariaReferenceSummary(\DOMElement $element, array $ariaAttributes): array
    {
        $knownIds = self::htmlDocumentElementsById($element);
        $references = [];
        foreach (self::ARIA_ID_REFERENCE_ATTRIBUTES as $attribute => $multiple) {
            if (!array_key_exists($attribute, $ariaAttributes)) {
                continue;
            }

            $tokens = self::spaceSeparatedTokens($ariaAttributes[$attribute]);
            $ids = [];
            $duplicates = [];
            $invalid = [];
            $present = [];
            $missing = [];
            $duplicateTargets = [];
            $targetSummaries = [];
            $referenceRecords = [];
            $issues = [];
            $seen = [];

            foreach ($tokens as $index => $token) {
                $record = [
                    'index' => $index,
                    'token' => $token,
                    'state' => 'unresolved',
                ];
                $firstIndex = $seen[$token] ?? null;
                if ($firstIndex === null) {
                    $seen[$token] = $index;
                } else {
                    $record['duplicateToken'] = true;
                    $record['firstIndex'] = $firstIndex;
                }

                if (!self::isHtmlReferenceToken($token)) {
                    $invalid[] = $token;
                    $record['state'] = 'invalid-token';
                    $issues[] = [
                        'code' => 'invalid-aria-reference-token',
                        'token' => $token,
                        'index' => $index,
                    ];
                    $referenceRecords[] = $record;
                    continue;
                }

                if (in_array($token, $ids, true)) {
                    if (!in_array($token, $duplicates, true)) {
                        $duplicates[] = $token;
                    }
                    $issues[] = [
                        'code' => 'duplicate-aria-reference-token',
                        'token' => $token,
                        'index' => $index,
                        'firstIndex' => $firstIndex,
                    ];
                } else {
                    $ids[] = $token;
                }

                $targets = $knownIds[$token] ?? [];
                if ($targets === []) {
                    if (!in_array($token, $missing, true)) {
                        $missing[] = $token;
                    }
                    $record = array_merge($record, [
                        'state' => 'missing-target',
                        'targetState' => 'missing',
                        'targetCount' => 0,
                        'targets' => [],
                    ]);
                    $issues[] = [
                        'code' => 'missing-aria-reference-target',
                        'token' => $token,
                        'index' => $index,
                    ];
                    $referenceRecords[] = $record;
                    continue;
                }

                if (!in_array($token, $present, true)) {
                    $present[] = $token;
                }
                $targets = array_map(
                    static fn (\DOMElement $target): array => self::ariaReferenceTargetSummary($target),
                    $targets
                );
                foreach ($targets as $target) {
                    $targetSummaries[] = [
                        'referenceIndex' => $index,
                        'token' => $token,
                    ] + $target;
                }
                if (count($targets) > 1) {
                    if (!in_array($token, $duplicateTargets, true)) {
                        $duplicateTargets[] = $token;
                    }
                    $issues[] = [
                        'code' => 'duplicate-aria-reference-target-id',
                        'token' => $token,
                        'index' => $index,
                        'targetCount' => count($targets),
                        'targetTexts' => array_map(
                            static fn (array $target): string => (string) ($target['text'] ?? ''),
                            $targets
                        ),
                    ];
                }

                $record = array_merge($record, [
                    'state' => count($targets) > 1 ? 'duplicate-target-id' : 'resolved',
                    'targetState' => count($targets) > 1 ? 'duplicate-target-id' : 'resolved',
                    'targetCount' => count($targets),
                    'targets' => $targets,
                    'targetTexts' => array_map(
                        static fn (array $target): string => (string) ($target['text'] ?? ''),
                        $targets
                    ),
                    'targetElementNames' => array_values(array_unique(array_map(
                        static fn (array $target): string => (string) ($target['tag'] ?? ''),
                        $targets
                    ))),
                ]);
                if (count($targets) === 1) {
                    $record['targetId'] = $targets[0]['id'];
                    $record['targetElementName'] = $targets[0]['tag'];
                    $record['targetText'] = $targets[0]['text'];
                }
                $referenceRecords[] = $record;
            }

            if (!$multiple && count($ids) > 1) {
                $issues[] = [
                    'code' => 'multiple-aria-reference-tokens',
                    'attribute' => $attribute,
                    'idCount' => count($ids),
                    'ids' => $ids,
                ];
            }

            $valid = $tokens !== []
                && $invalid === []
                && ($multiple || count($ids) <= 1);
            $references[$attribute] = [
                'raw' => $ariaAttributes[$attribute],
                'multiple' => $multiple,
                'tokens' => $tokens,
                'ids' => $ids,
                'duplicateIds' => $duplicates,
                'invalidTokens' => $invalid,
                'presentIds' => $present,
                'missingIds' => $missing,
                'duplicateTargetIds' => $duplicateTargets,
                'targets' => $targetSummaries,
                'targetCount' => count($targetSummaries),
                'references' => $referenceRecords,
                'issues' => $issues,
                'issueCodes' => array_values(array_unique(array_map(
                    static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                    $issues
                ))),
                'valid' => $valid,
                'resolved' => $valid && $issues === [],
            ];
        }
        ksort($references);

        return $references;
    }

    /**
     * @param array<string, array<string, mixed>> $ariaReferences
     * @return array<string, mixed>
     */
    private static function ariaReferenceAggregateSummary(array $ariaReferences): array
    {
        $issues = [];
        $targetIds = [];
        $missingIds = [];
        $invalidTokens = [];
        $duplicateIds = [];
        $duplicateTargetIds = [];

        foreach ($ariaReferences as $attribute => $reference) {
            foreach ($reference['presentIds'] ?? [] as $id) {
                self::appendUniqueString($targetIds, (string) $id);
            }
            foreach ($reference['missingIds'] ?? [] as $id) {
                self::appendUniqueString($missingIds, (string) $id);
            }
            foreach ($reference['invalidTokens'] ?? [] as $token) {
                self::appendUniqueString($invalidTokens, (string) $token);
            }
            foreach ($reference['duplicateIds'] ?? [] as $id) {
                self::appendUniqueString($duplicateIds, (string) $id);
            }
            foreach ($reference['duplicateTargetIds'] ?? [] as $id) {
                self::appendUniqueString($duplicateTargetIds, (string) $id);
            }
            foreach ($reference['issues'] ?? [] as $issue) {
                $issues[] = ['attribute' => $attribute] + $issue;
            }
        }

        return [
            'ariaReferenceTargetIds' => $targetIds,
            'ariaReferenceMissingIds' => $missingIds,
            'ariaReferenceInvalidTokens' => $invalidTokens,
            'ariaReferenceDuplicateIds' => $duplicateIds,
            'ariaReferenceDuplicateTargetIds' => $duplicateTargetIds,
            'ariaReferenceIssues' => $issues,
            'ariaReferenceIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ))),
            'ariaReferencesResolved' => $issues === [],
        ];
    }

    /**
     * @return array<string, list<\DOMElement>>
     */
    private static function htmlDocumentElementsById(\DOMElement $element): array
    {
        $document = $element->ownerDocument;
        if (!$document instanceof \DOMDocument) {
            return [];
        }

        $ids = [];
        foreach ($document->getElementsByTagName('*') as $candidate) {
            if (!$candidate instanceof \DOMElement || !$candidate->hasAttribute('id')) {
                continue;
            }

            $id = trim($candidate->getAttribute('id'));
            if ($id !== '' && self::isHtmlReferenceToken($id)) {
                $ids[$id][] = $candidate;
            }
        }

        return $ids;
    }

    /**
     * @return array<string, mixed>
     */
    private static function ariaReferenceTargetSummary(\DOMElement $target): array
    {
        $summary = [
            'tag' => self::htmlElementName($target),
            'id' => self::attributeOrNull($target, 'id'),
            'text' => self::normalizedText($target),
        ];

        $role = self::attributeOrNull($target, 'role');
        if ($role !== null) {
            $summary['role'] = $role;
        }

        $label = self::attributeOrNull($target, 'aria-label');
        if ($label !== null) {
            $summary['ariaLabel'] = $label;
        }

        return $summary;
    }

    /**
     * @return array<string, true>
     */
    private static function htmlDocumentElementIds(\DOMElement $element): array
    {
        $document = $element->ownerDocument;
        if (!$document instanceof \DOMDocument) {
            return [];
        }

        $ids = [];
        foreach ($document->getElementsByTagName('*') as $candidate) {
            if (!$candidate instanceof \DOMElement || !$candidate->hasAttribute('id')) {
                continue;
            }

            $id = trim($candidate->getAttribute('id'));
            if ($id !== '' && self::isHtmlReferenceToken($id)) {
                $ids[$id] = true;
            }
        }

        return $ids;
    }

    /**
     * @return array{id:?string, valid:bool}
     */
    private static function htmlIdAttributeSummary(string $value): array
    {
        $id = trim($value);

        return [
            'id' => $id === '' ? null : $id,
            'valid' => $value !== '' && self::isHtmlIdReferenceToken($value),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function htmlDocumentIdReviewSummary(\DOMElement $element, string $idRaw): array
    {
        $current = self::htmlIdAttributeSummary($idRaw);
        $occurrences = self::htmlDocumentIdOccurrences($element);
        $validOccurrences = [];
        $invalidOccurrences = [];
        $occurrencesById = [];

        foreach ($occurrences as $occurrence) {
            $id = $occurrence['id'] ?? null;
            if (($occurrence['valid'] ?? false) === true && is_string($id)) {
                $validOccurrences[] = $occurrence;
                $occurrencesById[$id][] = $occurrence;
                continue;
            }

            $invalidOccurrences[] = $occurrence;
        }

        $duplicateIds = [];
        $duplicateOccurrences = [];
        foreach ($occurrencesById as $id => $records) {
            if (count($records) <= 1) {
                continue;
            }

            $duplicateIds[] = $id;
            foreach ($records as $record) {
                $duplicateOccurrences[] = $record + ['occurrenceCount' => count($records)];
            }
        }

        $currentId = is_string($current['id']) ? $current['id'] : null;
        $currentOccurrences = $current['valid'] && $currentId !== null
            ? ($occurrencesById[$currentId] ?? [])
            : [];
        $currentDuplicate = count($currentOccurrences) > 1;
        $issues = [];

        if (!$current['valid']) {
            $issues[] = [
                'code' => 'invalid-html-id',
                'idRaw' => $idRaw,
            ];
        }
        if ($currentDuplicate) {
            $issues[] = [
                'code' => 'duplicate-html-id',
                'id' => $currentId,
                'count' => count($currentOccurrences),
            ];
        }

        return [
            'idReviewPolicy' => 'html-document-id-uniqueness-review',
            'elementIdNormalized' => $current['id'],
            'elementIdValid' => $current['valid'],
            'elementIdDuplicate' => $currentDuplicate,
            'elementIdOccurrenceCount' => count($currentOccurrences),
            'elementIdOccurrences' => $currentOccurrences,
            'documentIdCount' => count($occurrences),
            'documentValidIdCount' => count($validOccurrences),
            'documentInvalidIdCount' => count($invalidOccurrences),
            'documentInvalidIdOccurrences' => $invalidOccurrences,
            'documentDuplicateIdCount' => count($duplicateIds),
            'documentDuplicateIds' => $duplicateIds,
            'documentDuplicateIdOccurrences' => $duplicateOccurrences,
            'idIssues' => $issues,
            'idIssueCodes' => array_values(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            )),
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function htmlDocumentIdOccurrences(\DOMElement $current): array
    {
        $document = $current->ownerDocument;
        if (!$document instanceof \DOMDocument) {
            return [];
        }

        $occurrences = [];
        foreach ($document->getElementsByTagName('*') as $candidate) {
            if (!$candidate instanceof \DOMElement || !$candidate->hasAttribute('id')) {
                continue;
            }

            $raw = $candidate->getAttribute('id');
            $id = self::htmlIdAttributeSummary($raw);
            $occurrences[] = [
                'index' => count($occurrences),
                'tag' => self::htmlElementName($candidate),
                'idRaw' => $raw,
                'id' => $id['id'],
                'valid' => $id['valid'],
                'current' => $candidate->isSameNode($current),
                'text' => self::normalizedText($candidate),
            ];
        }

        return $occurrences;
    }

    private static function inputType(\DOMElement $input): string
    {
        return self::inputTypeSummary($input)['inputType'];
    }

    /**
     * @return array{
     *     inputTypeRaw:?string,
     *     inputType:string,
     *     inputTypeState:string,
     *     inputTypeValid:bool,
     *     inputTypeKnown:bool,
     *     inputTypeDefaulted:bool,
     *     inputTypeMissingDefaulted:bool,
     *     inputTypeInvalidValueDefaulted:bool
     * }
     */
    private static function inputTypeSummary(\DOMElement $input): array
    {
        $raw = self::attributeOrNull($input, 'type');
        $token = $raw === null ? null : strtolower(trim($raw));
        $knownTypes = [
            'hidden' => true,
            'text' => true,
            'search' => true,
            'tel' => true,
            'url' => true,
            'email' => true,
            'password' => true,
            'date' => true,
            'month' => true,
            'week' => true,
            'time' => true,
            'datetime-local' => true,
            'number' => true,
            'range' => true,
            'color' => true,
            'checkbox' => true,
            'radio' => true,
            'file' => true,
            'submit' => true,
            'image' => true,
            'reset' => true,
            'button' => true,
        ];
        $known = is_string($token) && isset($knownTypes[$token]);
        $missing = $raw === null;
        $empty = $raw !== null && $token === '';
        $type = $known ? (string) $token : 'text';

        return [
            'inputTypeRaw' => $raw,
            'inputType' => $type,
            'inputTypeState' => $missing ? 'missing' : ($empty ? 'empty' : ($known ? $type : 'invalid')),
            'inputTypeValid' => $missing || $known,
            'inputTypeKnown' => $known,
            'inputTypeDefaulted' => !$known,
            'inputTypeMissingDefaulted' => $missing,
            'inputTypeInvalidValueDefaulted' => !$missing && !$known,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function fileInputReviewSummary(\DOMElement $input, string $inputType): array
    {
        $acceptRaw = self::attributeOrNull($input, 'accept');
        $accept = $acceptRaw === null ? self::emptyFileAcceptSummary() : self::fileAcceptSummary($acceptRaw);
        $captureRaw = self::attributeOrNull($input, 'capture');
        $capture = $captureRaw === null ? null : self::fileInputCaptureState($captureRaw);
        $issues = [];

        if ($inputType !== 'file') {
            $issues[] = 'non-file-input-upload-attribute';
        }
        if ($acceptRaw !== null && !$accept['valid']) {
            $issues[] = 'invalid-file-accept-token';
        }
        if ($captureRaw !== null && $capture === null) {
            $issues[] = 'invalid-file-capture-token';
        }

        return [
            'fileInputReviewPolicy' => 'html-file-input-accept-capture-review',
            'fileInput' => $inputType === 'file',
            'fileInputType' => $inputType,
            'fileInputAcceptRaw' => $acceptRaw,
            'fileInputAcceptTokens' => $accept['tokens'],
            'fileInputAcceptedExtensions' => $accept['extensions'],
            'fileInputAcceptedMimeTypes' => $accept['mimeTypes'],
            'fileInputAcceptedWildcardMimeTypes' => $accept['wildcardMimeTypes'],
            'fileInputInvalidAcceptTokens' => $accept['invalid'],
            'fileInputAcceptValid' => $acceptRaw === null ? null : $accept['valid'],
            'fileInputCaptureRaw' => $captureRaw,
            'fileInputCaptureState' => $capture,
            'fileInputCaptureValid' => $captureRaw === null ? null : $capture !== null,
            'fileInputIssueCodes' => $issues,
            'fileInputValid' => $issues === [],
        ];
    }

    /**
     * @return array{tokens:list<string>, extensions:list<string>, mimeTypes:list<string>, wildcardMimeTypes:list<string>, invalid:list<string>, valid:bool}
     */
    private static function emptyFileAcceptSummary(): array
    {
        return [
            'tokens' => [],
            'extensions' => [],
            'mimeTypes' => [],
            'wildcardMimeTypes' => [],
            'invalid' => [],
            'valid' => true,
        ];
    }

    /**
     * @return array{tokens:list<string>, extensions:list<string>, mimeTypes:list<string>, wildcardMimeTypes:list<string>, invalid:list<string>, valid:bool}
     */
    private static function fileAcceptSummary(string $value): array
    {
        $tokens = [];
        $extensions = [];
        $mimeTypes = [];
        $wildcardMimeTypes = [];
        $invalid = [];

        foreach (explode(',', $value) as $rawToken) {
            $token = trim($rawToken);
            if ($token === '') {
                continue;
            }

            $tokens[] = $token;
            $normalized = strtolower($token);

            if (self::isSafeFileExtensionAcceptToken($normalized)) {
                self::appendUniqueString($extensions, $normalized);
                continue;
            }

            if (self::isSafeMimeAcceptToken($normalized)) {
                if (str_ends_with($normalized, '/*')) {
                    self::appendUniqueString($wildcardMimeTypes, $normalized);
                } else {
                    self::appendUniqueString($mimeTypes, $normalized);
                }
                continue;
            }

            $invalid[] = $token;
        }

        return [
            'tokens' => $tokens,
            'extensions' => $extensions,
            'mimeTypes' => $mimeTypes,
            'wildcardMimeTypes' => $wildcardMimeTypes,
            'invalid' => $invalid,
            'valid' => $tokens !== [] && $invalid === [],
        ];
    }

    private static function isSafeFileExtensionAcceptToken(string $token): bool
    {
        return preg_match('/^\.[a-z0-9][a-z0-9._+-]{0,63}$/', $token) === 1;
    }

    private static function isSafeMimeAcceptToken(string $token): bool
    {
        return preg_match('/^[a-z0-9][a-z0-9!#$&^_.+-]{0,126}\/(?:[a-z0-9][a-z0-9!#$&^_.+-]{0,126}|\*)$/', $token) === 1;
    }

    private static function fileInputCaptureState(string $value): ?string
    {
        $value = strtolower(trim($value));

        return match ($value) {
            '' => 'capture',
            'user', 'environment' => $value,
            default => null,
        };
    }

    private static function buttonType(\DOMElement $button): string
    {
        $type = strtolower(trim($button->getAttribute('type')));

        return in_array($type, ['button', 'reset', 'submit'], true) ? $type : 'submit';
    }

    /**
     * @return array<string, mixed>
     */
    private static function buttonTypeSummary(\DOMElement $button): array
    {
        $raw = self::attributeOrNull($button, 'type');
        $token = $raw === null ? null : strtolower(trim($raw));
        $known = is_string($token) && in_array($token, ['button', 'reset', 'submit'], true);
        $missing = $raw === null;
        $empty = $raw !== null && $token === '';
        $type = $known ? (string) $token : 'submit';

        return [
            'buttonTypeRaw' => $raw,
            'buttonType' => $type,
            'buttonTypeState' => $missing ? 'missing' : ($empty ? 'empty' : ($known ? $type : 'invalid')),
            'buttonTypeValid' => $missing || $known,
            'buttonTypeKnown' => $known,
            'buttonTypeDefaulted' => !$known,
            'buttonTypeMissingDefaulted' => $missing,
            'buttonTypeInvalidValueDefaulted' => !$missing && !$known,
            'buttonSubmitButton' => self::isButtonSubmitButton($button),
        ];
    }

    private static function isButtonSubmitButton(\DOMElement $button): bool
    {
        $typeRaw = self::attributeOrNull($button, 'type');
        $type = $typeRaw === null ? '' : strtolower(trim($typeRaw));

        if ($type === 'submit') {
            return true;
        }
        if ($type === 'button' || $type === 'reset') {
            return false;
        }
        if ($button->hasAttribute('command') || $button->hasAttribute('commandfor')) {
            return false;
        }

        $parent = $button->parentNode;

        return !($parent instanceof \DOMElement && self::htmlElementName($parent) === 'select');
    }

    /**
     * @return array<string, mixed>
     */
    private static function buttonCommandSummary(\DOMElement $button): array
    {
        if (!$button->hasAttribute('command') && !$button->hasAttribute('commandfor')) {
            return [];
        }

        $commandRaw = self::attributeOrNull($button, 'command');
        $command = self::buttonCommandState($commandRaw);
        $commandForRaw = self::attributeOrNull($button, 'commandfor');
        $commandFor = $commandForRaw === null ? null : trim($commandForRaw);
        $commandForValid = $commandFor !== null && $commandFor !== '' && self::isHtmlIdReferenceToken($commandFor);
        $target = $commandForValid ? self::htmlElementById($button, $commandFor) : null;
        $issues = [];

        if ($commandRaw === null || trim($commandRaw) === '') {
            $issues[] = ['code' => 'missing-button-command'];
        } elseif ($command['state'] === 'unknown') {
            $issues[] = [
                'code' => 'unknown-button-command',
                'commandRaw' => $commandRaw,
            ];
        }

        if ($commandForRaw === null || trim($commandForRaw) === '') {
            $issues[] = ['code' => 'missing-button-commandfor'];
        } elseif (!$commandForValid) {
            $issues[] = [
                'code' => 'invalid-button-commandfor-target',
                'commandForRaw' => $commandForRaw,
            ];
        } elseif (!$target instanceof \DOMElement) {
            $issues[] = [
                'code' => 'missing-button-command-target',
                'commandFor' => $commandFor,
            ];
        }

        if ($target instanceof \DOMElement) {
            $targetName = self::htmlElementName($target);
            if (($command['family'] ?? null) === 'popover' && self::attributeOrNull($target, 'popover') === null) {
                $issues[] = [
                    'code' => 'non-popover-button-command-target',
                    'command' => $command['command'],
                    'targetName' => $targetName,
                    'targetId' => self::attributeOrNull($target, 'id'),
                ];
            }
            if (($command['family'] ?? null) === 'dialog' && $targetName !== 'dialog') {
                $issues[] = [
                    'code' => 'non-dialog-button-command-target',
                    'command' => $command['command'],
                    'targetName' => $targetName,
                    'targetId' => self::attributeOrNull($target, 'id'),
                ];
            }
        }

        $issueCodes = array_values(array_unique(array_map(
            static fn (array $issue): string => (string) ($issue['code'] ?? ''),
            $issues
        )));

        return [
            'buttonCommandReviewPolicy' => 'button-commandfor-target-review',
            'buttonSubmitButton' => self::isButtonSubmitButton($button),
            'commandRaw' => $commandRaw,
            'command' => $command['command'],
            'commandState' => $command['state'],
            'commandActionFamily' => $command['family'],
            'commandCustom' => $command['custom'],
            'commandKnown' => $command['known'],
            'commandForRaw' => $commandForRaw,
            'commandFor' => $commandFor === '' ? null : $commandFor,
            'commandForValid' => $commandForValid,
            'commandTargetFound' => $target instanceof \DOMElement,
            'commandTargetKind' => self::buttonCommandTargetKind($target, $commandForRaw, $commandForValid),
            'commandTarget' => $target instanceof \DOMElement ? self::buttonCommandTargetSummary($target) : null,
            'commandIssues' => $issues,
            'commandIssueCodes' => $issueCodes,
            'commandInvokesTarget' => $issues === [],
        ];
    }

    /**
     * @return array{command:?string, state:string, family:?string, custom:bool, known:bool}
     */
    private static function buttonCommandState(?string $commandRaw): array
    {
        if ($commandRaw === null || trim($commandRaw) === '') {
            return [
                'command' => null,
                'state' => 'missing',
                'family' => null,
                'custom' => false,
                'known' => false,
            ];
        }

        $command = strtolower(trim($commandRaw));
        if (isset(self::HTML_BUTTON_COMMAND_STATES[$command])) {
            return [
                'command' => $command,
                'state' => self::HTML_BUTTON_COMMAND_STATES[$command],
                'family' => isset(self::HTML_BUTTON_POPOVER_COMMANDS[$command])
                    ? 'popover'
                    : (isset(self::HTML_BUTTON_DIALOG_COMMANDS[$command]) ? 'dialog' : null),
                'custom' => false,
                'known' => true,
            ];
        }

        if (preg_match('/^--[A-Za-z0-9._:-]+$/', trim($commandRaw)) === 1) {
            return [
                'command' => trim($commandRaw),
                'state' => 'custom',
                'family' => 'custom',
                'custom' => true,
                'known' => true,
            ];
        }

        return [
            'command' => null,
            'state' => 'unknown',
            'family' => null,
            'custom' => false,
            'known' => false,
        ];
    }

    private static function buttonCommandTargetKind(?\DOMElement $target, ?string $commandForRaw, bool $commandForValid): string
    {
        if (!$target instanceof \DOMElement) {
            if ($commandForRaw === null || trim($commandForRaw) === '') {
                return 'missing-reference';
            }

            return $commandForValid ? 'missing-target' : 'invalid-reference';
        }

        $name = self::htmlElementName($target);
        if ($name === 'dialog') {
            return 'dialog';
        }
        if (self::attributeOrNull($target, 'popover') !== null) {
            return 'popover';
        }

        return 'element';
    }

    /**
     * @return array<string, mixed>
     */
    private static function buttonCommandTargetSummary(\DOMElement $target): array
    {
        $name = self::htmlElementName($target);
        $summary = [
            'tag' => $name,
            'id' => self::attributeOrNull($target, 'id'),
            'text' => self::normalizedText($target),
        ];

        if ($name === 'dialog') {
            $summary['dialogOpen'] = $target->hasAttribute('open');
            $summary['dialogState'] = $target->hasAttribute('open') ? 'open' : 'closed';
        }

        $popoverRaw = self::attributeOrNull($target, 'popover');
        if ($popoverRaw !== null) {
            $popover = self::popoverState($popoverRaw);
            $summary['popoverRaw'] = $popoverRaw;
            $summary['popoverState'] = $popover;
            $summary['popoverValid'] = $popover !== null;
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function formSubmissionSummary(\DOMElement $form): array
    {
        $acceptCharsetRaw = self::attributeOrNull($form, 'accept-charset');
        $controls = self::formOwnedControlSummaries($form);

        return [
            'formSubmission' => 'form',
            'action' => self::attributeOrNull($form, 'action'),
            'method' => self::formMethod($form, 'method', 'get'),
            'enctype' => self::formEnctype($form, 'enctype', 'application/x-www-form-urlencoded'),
            'target' => self::attributeOrNull($form, 'target'),
            'autocomplete' => self::formAutocomplete($form),
            'novalidate' => $form->hasAttribute('novalidate'),
            'acceptCharsetRaw' => $acceptCharsetRaw,
            'acceptCharsets' => $acceptCharsetRaw === null ? [] : self::spaceSeparatedTokens($acceptCharsetRaw),
            'controlCount' => count($controls),
            'externalControlCount' => count(array_filter(
                $controls,
                static fn (array $control): bool => ($control['formOwnerSource'] ?? null) === 'form-attribute'
            )),
            'controls' => $controls,
            'controlNames' => self::formOwnedControlNames($controls),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function formOwnerSummary(\DOMElement $control): array
    {
        $form = self::formOwnerElement($control);
        $formAttribute = self::attributeOrNull($control, 'form');
        $formTargetId = $formAttribute === null ? null : trim($formAttribute);
        $source = 'none';
        if ($formAttribute !== null) {
            $source = $form instanceof \DOMElement ? 'form-attribute' : 'missing-form-attribute';
        } elseif ($form instanceof \DOMElement) {
            $source = 'ancestor';
        }

        $summary = [
            'formOwnerRaw' => $formAttribute,
            'formOwnerTargetId' => $formTargetId === '' ? null : $formTargetId,
            'formOwnerId' => $form instanceof \DOMElement ? self::attributeOrNull($form, 'id') : null,
            'formOwnerSource' => $source,
            'formOwnerFound' => $form instanceof \DOMElement,
            'formOwnerAction' => $form instanceof \DOMElement ? self::attributeOrNull($form, 'action') : null,
            'formOwnerMethod' => $form instanceof \DOMElement ? self::formMethod($form, 'method', 'get') : null,
            'formOwnerEnctype' => $form instanceof \DOMElement ? self::formEnctype($form, 'enctype', 'application/x-www-form-urlencoded') : null,
            'formOwnerTarget' => $form instanceof \DOMElement ? self::attributeOrNull($form, 'target') : null,
        ];

        if ($formAttribute !== null) {
            $summary += self::formOwnerReferenceSummary($control, $form, $formAttribute);
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function formOwnerReferenceSummary(\DOMElement $control, ?\DOMElement $form, string $formAttribute): array
    {
        $targetId = trim($formAttribute);
        $valid = $targetId !== '' && self::isHtmlIdReferenceToken($targetId);
        $targets = $valid ? self::htmlElementsById($control, $targetId) : [];
        $formTargets = array_values(array_filter(
            $targets,
            static fn (\DOMElement $target): bool => self::htmlElementName($target) === 'form'
        ));
        $issues = [];

        if ($targetId === '') {
            $issues[] = [
                'code' => 'empty-form-owner-reference',
                'formOwnerRaw' => $formAttribute,
            ];
        } elseif (!$valid) {
            $issues[] = [
                'code' => 'invalid-form-owner-reference',
                'formOwnerRaw' => $formAttribute,
            ];
        } elseif ($targets === []) {
            $issues[] = [
                'code' => 'missing-form-owner-target',
                'formOwnerTargetId' => $targetId,
            ];
        } elseif ($formTargets === []) {
            $issues[] = [
                'code' => 'non-form-owner-target',
                'formOwnerTargetId' => $targetId,
                'targetElementNames' => array_values(array_map(
                    static fn (\DOMElement $target): string => self::htmlElementName($target),
                    $targets
                )),
            ];
        }

        if (count($targets) > 1) {
            $issues[] = [
                'code' => 'duplicate-form-owner-target-id',
                'formOwnerTargetId' => $targetId,
                'count' => count($targets),
                'formCount' => count($formTargets),
            ];
        }

        $issueCodes = array_values(array_unique(array_map(
            static fn (array $issue): string => (string) ($issue['code'] ?? ''),
            $issues
        )));

        return [
            'formOwnerReviewPolicy' => 'form-owner-idref-review',
            'formOwnerTargetValid' => $valid,
            'formOwnerResolutionState' => self::formOwnerResolutionState($targetId, $valid, $targets, $formTargets),
            'formOwnerResolved' => $form instanceof \DOMElement && $issues === [],
            'formOwnerTargetCount' => count($targets),
            'formOwnerFormTargetCount' => count($formTargets),
            'formOwnerTargetElementNames' => array_values(array_map(
                static fn (\DOMElement $target): string => self::htmlElementName($target),
                $targets
            )),
            'formOwnerTargets' => array_values(array_map(
                static fn (\DOMElement $target, int $index): array => self::formOwnerTargetSummary($target, $form, $index),
                $targets,
                array_keys($targets)
            )),
            'formOwnerIssues' => $issues,
            'formOwnerIssueCodes' => $issueCodes,
        ];
    }

    /**
     * @param list<\DOMElement> $targets
     * @param list<\DOMElement> $formTargets
     */
    private static function formOwnerResolutionState(
        string $targetId,
        bool $valid,
        array $targets,
        array $formTargets
    ): string {
        if ($targetId === '') {
            return 'empty-reference';
        }
        if (!$valid) {
            return 'invalid-reference';
        }
        if ($targets === []) {
            return 'missing-target';
        }
        if ($formTargets === []) {
            return 'non-form-target';
        }
        if (count($targets) > 1) {
            return 'duplicate-target-id';
        }

        return 'resolved';
    }

    /**
     * @return array<string, mixed>
     */
    private static function formOwnerTargetSummary(\DOMElement $target, ?\DOMElement $form, int $index): array
    {
        $name = self::htmlElementName($target);
        $summary = [
            'index' => $index,
            'tag' => $name,
            'id' => self::attributeOrNull($target, 'id'),
            'selectedFormOwner' => $form instanceof \DOMElement && $target->isSameNode($form),
            'text' => self::normalizedText($target),
        ];

        if ($name === 'form') {
            $summary['action'] = self::attributeOrNull($target, 'action');
            $summary['method'] = self::formMethod($target, 'method', 'get');
            $summary['enctype'] = self::formEnctype($target, 'enctype', 'application/x-www-form-urlencoded');
            $summary['target'] = self::attributeOrNull($target, 'target');
        }

        return $summary;
    }

    private static function formOwnerElement(\DOMElement $control): ?\DOMElement
    {
        $formAttribute = self::attributeOrNull($control, 'form');
        if ($formAttribute !== null) {
            $formId = trim($formAttribute);
            if ($formId === '') {
                return null;
            }

            $candidate = self::htmlElementById($control, $formId);

            return $candidate instanceof \DOMElement && self::htmlElementName($candidate) === 'form'
                ? $candidate
                : null;
        }

        $parent = $control->parentNode;
        while ($parent instanceof \DOMElement) {
            if (self::htmlElementName($parent) === 'form') {
                return $parent;
            }
            $parent = $parent->parentNode;
        }

        return null;
    }

    /**
     * @return array<string, mixed>
     */
    private static function outputForReferenceSummary(\DOMElement $output, string $forRaw): array
    {
        $tokens = self::spaceSeparatedTokens($forRaw);
        $ids = [];
        $invalid = [];
        $duplicates = [];
        $resolved = [];
        $missing = [];
        $nonControls = [];
        $references = [];
        $controlReferences = [];
        $issues = [];
        $seen = [];

        foreach ($tokens as $index => $token) {
            $record = [
                'index' => $index,
                'token' => $token,
                'state' => 'unresolved',
            ];

            $firstIndex = $seen[$token] ?? null;
            if ($firstIndex === null) {
                $seen[$token] = $index;
            } else {
                $record['duplicateToken'] = true;
                $record['firstIndex'] = $firstIndex;
                if (self::isHtmlIdReferenceToken($token) && !in_array($token, $duplicates, true)) {
                    $duplicates[] = $token;
                }
                $issues[] = [
                    'code' => 'duplicate-output-for-reference-token',
                    'token' => $token,
                    'index' => $index,
                    'firstIndex' => $firstIndex,
                ];
            }

            if (!self::isHtmlIdReferenceToken($token)) {
                if (!in_array($token, $invalid, true)) {
                    $invalid[] = $token;
                }
                $record['state'] = 'invalid-token';
                $issues[] = [
                    'code' => 'invalid-output-for-reference-token',
                    'token' => $token,
                    'index' => $index,
                ];
                $references[] = $record;
                continue;
            }

            if (!in_array($token, $ids, true)) {
                $ids[] = $token;
            }

            $target = self::htmlElementById($output, $token);
            if (!$target instanceof \DOMElement) {
                if (!in_array($token, $missing, true)) {
                    $missing[] = $token;
                }
                $record['state'] = 'missing-target';
                $record['targetState'] = 'missing';
                $issues[] = [
                    'code' => 'missing-output-for-target',
                    'token' => $token,
                    'index' => $index,
                ];
                $references[] = $record;
                continue;
            }

            $targetSummary = self::outputForTargetSummary($target);
            $record['target'] = $targetSummary;
            if (!self::isFormControlElement($target)) {
                if (!in_array($token, $nonControls, true)) {
                    $nonControls[] = $token;
                }
                $record['state'] = 'non-control-target';
                $record['targetState'] = 'non-control';
                $issues[] = [
                    'code' => 'non-control-output-for-target',
                    'token' => $token,
                    'index' => $index,
                    'targetName' => $targetSummary['tag'],
                    'targetText' => $targetSummary['text'],
                ];
                $references[] = $record;
                continue;
            }

            if (!in_array($token, $resolved, true)) {
                $resolved[] = $token;
                $controlReferences[] = $targetSummary;
            }
            $record['state'] = 'resolved-control';
            $record['targetState'] = 'resolved';
            $references[] = $record;
        }

        return [
            'forReferenceReviewPolicy' => 'output-for-idref-review',
            'forReferenceIds' => $ids,
            'invalidForReferenceTokens' => $invalid,
            'duplicateForReferenceIds' => $duplicates,
            'resolvedForReferenceIds' => $resolved,
            'missingForReferenceIds' => $missing,
            'nonControlForReferenceIds' => $nonControls,
            'forReferences' => $references,
            'forControlReferences' => $controlReferences,
            'forControlReferenceCount' => count($controlReferences),
            'forControlNames' => self::outputForControlNames($controlReferences),
            'forReferenceIssues' => $issues,
            'forReferenceIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ))),
            'forReferencesResolved' => $issues === [],
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function outputForTargetSummary(\DOMElement $target): array
    {
        $name = self::htmlElementName($target);
        $summary = [
            'tag' => $name,
            'id' => self::attributeOrNull($target, 'id'),
            'controlName' => self::attributeOrNull($target, 'name'),
            'text' => self::normalizedText($target),
        ];

        if (self::isFormControlElement($target)) {
            $summary += self::formOwnerSummary($target);
            $summary['effectiveDisabled'] = self::isEffectivelyDisabledFormControl($target);
        }
        if ($name === 'input') {
            $summary['inputType'] = self::inputType($target);
            $summary['value'] = self::attributeOrNull($target, 'value');
            $summary['checked'] = $target->hasAttribute('checked');
        } elseif ($name === 'button') {
            $summary['buttonType'] = self::buttonType($target);
            $summary['value'] = self::attributeOrNull($target, 'value');
            $summary['label'] = self::normalizedText($target);
        } elseif ($name === 'select') {
            $summary['selectedValues'] = array_values(array_map(
                static fn (array $option): string => (string) $option['value'],
                array_filter(
                    self::selectOptionSummaries($target),
                    static fn (array $option): bool => (bool) ($option['selected'] ?? false)
                )
            ));
        } elseif ($name === 'textarea' || $name === 'output') {
            $summary['value'] = $target->textContent;
        }

        return $summary;
    }

    /**
     * @param list<array<string, mixed>> $controls
     * @return list<string>
     */
    private static function outputForControlNames(array $controls): array
    {
        $names = [];
        foreach ($controls as $control) {
            $name = $control['controlName'] ?? null;
            if (is_string($name) && $name !== '' && !in_array($name, $names, true)) {
                $names[] = $name;
            }
        }

        return $names;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function formOwnedControlSummaries(\DOMElement $form): array
    {
        $document = $form->ownerDocument;
        if (!$document instanceof \DOMDocument) {
            return [];
        }

        $controls = [];
        foreach ($document->getElementsByTagName('*') as $control) {
            if (!$control instanceof \DOMElement || !self::isFormControlElement($control)) {
                continue;
            }
            if (!self::formOwnerElement($control)?->isSameNode($form)) {
                continue;
            }

            $name = self::htmlElementName($control);
            $summary = [
                'tag' => $name,
                'id' => self::attributeOrNull($control, 'id'),
                'controlName' => self::attributeOrNull($control, 'name'),
                'formOwnerSource' => self::attributeOrNull($control, 'form') === null ? 'ancestor' : 'form-attribute',
                'effectiveDisabled' => self::isEffectivelyDisabledFormControl($control),
            ];

            if ($name === 'input') {
                $summary['type'] = self::inputType($control);
                $summary['value'] = self::attributeOrNull($control, 'value');
                $summary['checked'] = $control->hasAttribute('checked');
            } elseif ($name === 'button') {
                $summary['type'] = self::buttonType($control);
                $summary['value'] = self::attributeOrNull($control, 'value');
                $summary['label'] = self::normalizedText($control);
            } elseif ($name === 'select') {
                $summary['selectedValues'] = array_values(array_map(
                    static fn (array $option): string => (string) $option['value'],
                    array_filter(
                        self::selectOptionSummaries($control),
                        static fn (array $option): bool => (bool) ($option['selected'] ?? false)
                    )
                ));
            } elseif ($name === 'textarea' || $name === 'output') {
                $summary['value'] = $control->textContent;
            }

            $controls[] = $summary;
        }

        return $controls;
    }

    /**
     * @param list<array<string, mixed>> $controls
     * @return list<string>
     */
    private static function formOwnedControlNames(array $controls): array
    {
        $names = [];
        foreach ($controls as $control) {
            $name = $control['controlName'] ?? null;
            if (is_string($name) && $name !== '' && !in_array($name, $names, true)) {
                $names[] = $name;
            }
        }

        return $names;
    }

    /**
     * @return array<string, mixed>
     */
    private static function formSubmitterSummary(\DOMElement $submitter): array
    {
        return [
            'form' => self::attributeOrNull($submitter, 'form'),
            'formAction' => self::attributeOrNull($submitter, 'formaction'),
            'formMethod' => self::formMethod($submitter, 'formmethod', null),
            'formEnctype' => self::formEnctype($submitter, 'formenctype', null),
            'formTarget' => self::attributeOrNull($submitter, 'formtarget'),
            'formNoValidate' => $submitter->hasAttribute('formnovalidate'),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function formSubmitterActionReviewSummary(\DOMElement $submitter): array
    {
        $form = self::formOwnerElement($submitter);
        $name = self::htmlElementName($submitter);
        $type = $name === 'button' ? self::buttonType($submitter) : self::inputType($submitter);

        $formActionRaw = self::attributeOrNull($submitter, 'formaction');
        $ownerActionRaw = $form instanceof \DOMElement ? self::attributeOrNull($form, 'action') : null;
        $actionRaw = $formActionRaw ?? $ownerActionRaw;
        $actionSource = $formActionRaw !== null
            ? 'formaction'
            : ($ownerActionRaw !== null ? 'form-action' : ($form instanceof \DOMElement ? 'document-url-default' : 'missing-form-owner'));
        $action = self::hyperlinkUrlReviewSummary($actionRaw);

        $method = self::formSubmitterEffectiveMethodSummary($submitter, $form);
        $enctype = self::formSubmitterEffectiveEnctypeSummary($submitter, $form);
        $target = self::formSubmitterEffectiveTargetSummary($submitter, $form);
        $noValidate = self::formSubmitterNoValidateSummary($submitter, $form);
        $effectiveDisabled = self::isEffectivelyDisabledFormControl($submitter);
        $issues = [];

        if (!$form instanceof \DOMElement) {
            $issues[] = ['code' => 'missing-form-owner'];
        }
        if ($effectiveDisabled) {
            $issues[] = ['code' => 'disabled-form-submitter'];
        }
        if ($action['unsafe'] === true) {
            $issues[] = [
                'code' => 'unsafe-form-submitter-action-url',
                'action' => $actionRaw,
                'scheme' => $action['scheme'],
                'source' => $actionSource,
            ];
        } elseif ($action['kind'] === 'absolute' && !in_array($action['scheme'], ['http', 'https'], true)) {
            $issues[] = [
                'code' => 'non-http-form-submitter-action-url',
                'action' => $actionRaw,
                'scheme' => $action['scheme'],
                'source' => $actionSource,
            ];
        }
        if ($method['valid'] === false) {
            $issues[] = [
                'code' => 'invalid-form-submitter-method',
                'methodRaw' => $method['raw'],
                'source' => $method['source'],
            ];
        }
        if ($enctype['valid'] === false) {
            $issues[] = [
                'code' => 'invalid-form-submitter-enctype',
                'enctypeRaw' => $enctype['raw'],
                'source' => $enctype['source'],
            ];
        }

        return [
            'formSubmitterActionReviewPolicy' => 'form-submitter-action-provenance-review',
            'formSubmitterElement' => $name,
            'formSubmitterType' => $type,
            'formSubmitterId' => self::attributeOrNull($submitter, 'id'),
            'formSubmitterName' => self::attributeOrNull($submitter, 'name'),
            'formSubmitterValue' => self::attributeOrNull($submitter, 'value'),
            'formSubmitterLabel' => $name === 'button' ? self::normalizedText($submitter) : self::attributeOrNull($submitter, 'value'),
            'formSubmitterOwnerFound' => $form instanceof \DOMElement,
            'formSubmitterOwnerId' => $form instanceof \DOMElement ? self::attributeOrNull($form, 'id') : null,
            'formSubmitterOwnerSource' => self::attributeOrNull($submitter, 'form') === null ? 'ancestor' : 'form-attribute',
            'formSubmitterEffectiveDisabled' => $effectiveDisabled,
            'formSubmitterWouldSubmit' => $form instanceof \DOMElement && !$effectiveDisabled,
            'formSubmitterWouldSubmitNetworkRequest' => $form instanceof \DOMElement
                && !$effectiveDisabled
                && $method['effective'] !== 'dialog',
            'formSubmitterReviewOnlyNoNetworkRequest' => true,
            'formSubmitterActionRaw' => $actionRaw,
            'formSubmitterActionSource' => $actionSource,
            'formSubmitterActionKind' => $action['kind'],
            'formSubmitterActionScheme' => $action['scheme'],
            'formSubmitterActionUnsafe' => $action['unsafe'],
            'formSubmitterActionUsesDocumentUrl' => $form instanceof \DOMElement
                && ($actionRaw === null || trim($actionRaw) === ''),
            'formSubmitterMethodRaw' => $method['raw'],
            'formSubmitterMethodSource' => $method['source'],
            'formSubmitterEffectiveMethod' => $method['effective'],
            'formSubmitterMethodValid' => $method['valid'],
            'formSubmitterEnctypeRaw' => $enctype['raw'],
            'formSubmitterEnctypeSource' => $enctype['source'],
            'formSubmitterEffectiveEnctype' => $enctype['effective'],
            'formSubmitterEnctypeValid' => $enctype['valid'],
            'formSubmitterTargetRaw' => $target['raw'],
            'formSubmitterTargetSource' => $target['source'],
            'formSubmitterEffectiveTarget' => $target['effective'],
            'formSubmitterNoValidate' => $noValidate['effective'],
            'formSubmitterNoValidateSource' => $noValidate['source'],
            'formSubmitterActionIssues' => $issues,
            'formSubmitterActionIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ))),
            'formSubmitterActionValid' => $issues === [],
        ];
    }

    /**
     * @return array{raw:?string, source:string, effective:string, valid:?bool}
     */
    private static function formSubmitterEffectiveMethodSummary(\DOMElement $submitter, ?\DOMElement $form): array
    {
        $raw = self::attributeOrNull($submitter, 'formmethod');
        if ($raw !== null) {
            return [
                'raw' => $raw,
                'source' => 'formmethod',
                'effective' => self::formMethod($submitter, 'formmethod', 'get') ?? 'get',
                'valid' => self::formMethodAttributeState($raw) !== null,
            ];
        }

        if ($form instanceof \DOMElement) {
            $ownerRaw = self::attributeOrNull($form, 'method');

            return [
                'raw' => $ownerRaw,
                'source' => $ownerRaw === null ? 'default-get' : 'form-method',
                'effective' => self::formMethod($form, 'method', 'get') ?? 'get',
                'valid' => $ownerRaw === null ? null : self::formMethodAttributeState($ownerRaw) !== null,
            ];
        }

        return [
            'raw' => null,
            'source' => 'missing-form-owner',
            'effective' => 'get',
            'valid' => null,
        ];
    }

    /**
     * @return array{raw:?string, source:string, effective:string, valid:?bool}
     */
    private static function formSubmitterEffectiveEnctypeSummary(\DOMElement $submitter, ?\DOMElement $form): array
    {
        $raw = self::attributeOrNull($submitter, 'formenctype');
        if ($raw !== null) {
            return [
                'raw' => $raw,
                'source' => 'formenctype',
                'effective' => self::formEnctype($submitter, 'formenctype', 'application/x-www-form-urlencoded')
                    ?? 'application/x-www-form-urlencoded',
                'valid' => self::formEnctypeAttributeState($raw) !== null,
            ];
        }

        if ($form instanceof \DOMElement) {
            $ownerRaw = self::attributeOrNull($form, 'enctype');

            return [
                'raw' => $ownerRaw,
                'source' => $ownerRaw === null ? 'default-urlencoded' : 'form-enctype',
                'effective' => self::formEnctype($form, 'enctype', 'application/x-www-form-urlencoded')
                    ?? 'application/x-www-form-urlencoded',
                'valid' => $ownerRaw === null ? null : self::formEnctypeAttributeState($ownerRaw) !== null,
            ];
        }

        return [
            'raw' => null,
            'source' => 'missing-form-owner',
            'effective' => 'application/x-www-form-urlencoded',
            'valid' => null,
        ];
    }

    /**
     * @return array{raw:?string, source:string, effective:?string}
     */
    private static function formSubmitterEffectiveTargetSummary(\DOMElement $submitter, ?\DOMElement $form): array
    {
        $raw = self::attributeOrNull($submitter, 'formtarget');
        if ($raw !== null) {
            return [
                'raw' => $raw,
                'source' => 'formtarget',
                'effective' => trim($raw) === '' ? null : trim($raw),
            ];
        }

        if ($form instanceof \DOMElement) {
            $ownerRaw = self::attributeOrNull($form, 'target');

            return [
                'raw' => $ownerRaw,
                'source' => $ownerRaw === null ? 'default-self' : 'form-target',
                'effective' => $ownerRaw === null || trim($ownerRaw) === '' ? null : trim($ownerRaw),
            ];
        }

        return [
            'raw' => null,
            'source' => 'missing-form-owner',
            'effective' => null,
        ];
    }

    /**
     * @return array{effective:bool, source:string}
     */
    private static function formSubmitterNoValidateSummary(\DOMElement $submitter, ?\DOMElement $form): array
    {
        if ($submitter->hasAttribute('formnovalidate')) {
            return ['effective' => true, 'source' => 'formnovalidate'];
        }
        if ($form instanceof \DOMElement && $form->hasAttribute('novalidate')) {
            return ['effective' => true, 'source' => 'form-novalidate'];
        }

        return ['effective' => false, 'source' => 'none'];
    }

    /**
     * @return array<string, mixed>
     */
    private static function formResetControlSummary(\DOMElement $resetter): array
    {
        $form = self::formOwnerElement($resetter);
        $controls = $form instanceof \DOMElement ? self::formResettableControlSummaries($form) : [];
        $issues = [];

        if (!$form instanceof \DOMElement) {
            $issues[] = ['code' => 'missing-form-owner'];
        }
        if (self::isEffectivelyDisabledFormControl($resetter)) {
            $issues[] = ['code' => 'disabled-reset-control'];
        }

        return [
            'formResetReviewPolicy' => 'form-reset-control-review',
            'formResetControl' => self::htmlElementName($resetter),
            'formResetControlId' => self::attributeOrNull($resetter, 'id'),
            'formResetFormOwnerId' => $form instanceof \DOMElement ? self::attributeOrNull($form, 'id') : null,
            'formResetFormOwnerFound' => $form instanceof \DOMElement,
            'formResetEffectiveDisabled' => self::isEffectivelyDisabledFormControl($resetter),
            'formResetWouldReset' => $form instanceof \DOMElement && !self::isEffectivelyDisabledFormControl($resetter),
            'formResetControlCount' => count($controls),
            'formResetControlNames' => self::formOwnedControlNames($controls),
            'formResetControlTags' => array_values(array_map(
                static fn (array $control): string => (string) ($control['tag'] ?? ''),
                $controls
            )),
            'formResetControlIds' => array_values(array_filter(
                array_map(static fn (array $control): ?string => $control['id'] ?? null, $controls),
                static fn (?string $id): bool => $id !== null && $id !== ''
            )),
            'formResetControls' => $controls,
            'formResetIssues' => $issues,
            'formResetIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ))),
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function formResettableControlSummaries(\DOMElement $form): array
    {
        $document = $form->ownerDocument;
        if (!$document instanceof \DOMDocument) {
            return [];
        }

        $controls = [];
        foreach ($document->getElementsByTagName('*') as $control) {
            if (!$control instanceof \DOMElement || !self::isResettableFormControlElement($control)) {
                continue;
            }
            if (!self::formOwnerElement($control)?->isSameNode($form)) {
                continue;
            }

            $controls[] = self::formResettableControlSummary($control);
        }

        return $controls;
    }

    private static function isResettableFormControlElement(\DOMElement $control): bool
    {
        $name = self::htmlElementName($control);
        if ($name === 'input') {
            return !in_array(self::inputType($control), ['button', 'image', 'reset', 'submit'], true);
        }

        return in_array($name, ['select', 'textarea'], true);
    }

    /**
     * @return array<string, mixed>
     */
    private static function formResettableControlSummary(\DOMElement $control): array
    {
        $name = self::htmlElementName($control);
        $summary = [
            'tag' => $name,
            'id' => self::attributeOrNull($control, 'id'),
            'controlName' => self::attributeOrNull($control, 'name'),
            'formOwnerSource' => self::attributeOrNull($control, 'form') === null ? 'ancestor' : 'form-attribute',
            'effectiveDisabled' => self::isEffectivelyDisabledFormControl($control),
        ];

        if ($name === 'input') {
            $type = self::inputType($control);
            $summary['type'] = $type;
            $summary['defaultValue'] = $control->getAttribute('value');
            if ($type === 'checkbox' || $type === 'radio') {
                $summary['defaultChecked'] = $control->hasAttribute('checked');
            }

            return $summary;
        }

        if ($name === 'select') {
            $options = self::selectOptionSummaries($control);
            $summary['defaultSelectedValues'] = array_values(array_map(
                static fn (array $option): string => (string) $option['value'],
                array_filter($options, static fn (array $option): bool => (bool) ($option['selected'] ?? false))
            ));
            $summary['optionCount'] = count($options);

            return $summary;
        }

        $summary['defaultValue'] = $control->textContent;

        return $summary;
    }

    private static function isInputSubmitterType(string $type): bool
    {
        return in_array($type, ['image', 'submit'], true);
    }

    private static function formMethod(\DOMElement $element, string $attribute, ?string $missing): ?string
    {
        if (!$element->hasAttribute($attribute)) {
            return $missing;
        }

        return self::formMethodAttributeState($element->getAttribute($attribute)) ?? 'get';
    }

    private static function formEnctype(\DOMElement $element, string $attribute, ?string $missing): ?string
    {
        if (!$element->hasAttribute($attribute)) {
            return $missing;
        }

        return self::formEnctypeAttributeState($element->getAttribute($attribute))
            ?? 'application/x-www-form-urlencoded';
    }

    private static function formMethodAttributeState(string $value): ?string
    {
        $method = strtolower(trim($value));

        return in_array($method, ['dialog', 'get', 'post'], true) ? $method : null;
    }

    private static function formEnctypeAttributeState(string $value): ?string
    {
        $enctype = strtolower(trim($value));

        return in_array($enctype, ['application/x-www-form-urlencoded', 'multipart/form-data', 'text/plain'], true)
            ? $enctype
            : null;
    }

    private static function formAutocomplete(\DOMElement $form): string
    {
        $autocomplete = strtolower(trim($form->getAttribute('autocomplete')));

        return $autocomplete === 'off' ? 'off' : 'on';
    }

    /**
     * @return array<string, mixed>
     */
    private static function formControlConstraintSummary(\DOMElement $control, string $name): array
    {
        $trackedAttributes = ['autocomplete', 'dirname', 'max', 'maxlength', 'min', 'minlength', 'pattern', 'size', 'step'];
        $hasTrackedAttribute = false;
        foreach ($trackedAttributes as $attribute) {
            if ($control->hasAttribute($attribute)) {
                $hasTrackedAttribute = true;
                break;
            }
        }
        if (!$hasTrackedAttribute && !$control->hasAttribute('multiple') && !$control->hasAttribute('readonly')) {
            return [];
        }

        $summary = ['constraintValidation' => 'form-control'];

        if (($name === 'input' || $name === 'textarea') && $control->hasAttribute('readonly')) {
            $summary['readonly'] = true;
        }
        if (($name === 'input' || $name === 'select') && $control->hasAttribute('multiple')) {
            $summary['multiple'] = true;
        }
        if ($control->hasAttribute('minlength')) {
            $minLength = self::nonNegativeIntegerToken($control->getAttribute('minlength'), 1000000);
            $summary['minLengthRaw'] = $control->getAttribute('minlength');
            $summary['minLength'] = $minLength;
            $summary['minLengthValid'] = $minLength !== null;
        }
        if ($control->hasAttribute('maxlength')) {
            $maxLength = self::nonNegativeIntegerToken($control->getAttribute('maxlength'), 1000000);
            $summary['maxLengthRaw'] = $control->getAttribute('maxlength');
            $summary['maxLength'] = $maxLength;
            $summary['maxLengthValid'] = $maxLength !== null;
        }
        if (array_key_exists('minLength', $summary) || array_key_exists('maxLength', $summary)) {
            $summary['lengthRangeValid'] = is_int($summary['minLength'] ?? null) && is_int($summary['maxLength'] ?? null)
                ? $summary['maxLength'] >= $summary['minLength']
                : null;
        }
        if ($control->hasAttribute('min')) {
            $min = self::finiteNumericToken($control->getAttribute('min'));
            $summary['constraintMinRaw'] = $control->getAttribute('min');
            $summary['constraintMin'] = $min;
            $summary['constraintMinValid'] = $min !== null;
        }
        if ($control->hasAttribute('max')) {
            $max = self::finiteNumericToken($control->getAttribute('max'));
            $summary['constraintMaxRaw'] = $control->getAttribute('max');
            $summary['constraintMax'] = $max;
            $summary['constraintMaxValid'] = $max !== null;
        }
        if (array_key_exists('constraintMin', $summary) || array_key_exists('constraintMax', $summary)) {
            $summary['constraintRangeValid'] = is_float($summary['constraintMin'] ?? null) && is_float($summary['constraintMax'] ?? null)
                ? $summary['constraintMax'] >= $summary['constraintMin']
                : null;
        }
        if ($control->hasAttribute('step')) {
            $step = self::stepConstraintToken($control->getAttribute('step'));
            $summary['constraintStepRaw'] = $control->getAttribute('step');
            $summary['constraintStep'] = $step;
            $summary['constraintStepValid'] = $step !== null;
        }
        if ($control->hasAttribute('pattern')) {
            $pattern = $control->getAttribute('pattern');
            $summary['patternRaw'] = $pattern;
            $summary['patternLength'] = strlen($pattern);
            $summary['patternReviewPolicy'] = 'pattern-source-no-regex-execution';
        }
        if ($control->hasAttribute('autocomplete')) {
            $autocomplete = self::formControlAutocompleteSummary($control->getAttribute('autocomplete'));
            $summary['autocompleteRaw'] = $control->getAttribute('autocomplete');
            $summary['autocompleteTokens'] = $autocomplete['tokens'];
            $summary['autocompleteNormalizedTokens'] = $autocomplete['normalizedTokens'];
            $summary['invalidAutocompleteTokens'] = $autocomplete['invalid'];
            $summary['autocompleteState'] = $autocomplete['state'];
            $summary['autocompleteValid'] = $autocomplete['valid'];
        }
        if (($name === 'input' || $name === 'textarea') && $control->hasAttribute('dirname')) {
            $dirname = self::formControlDirnameSummary($control->getAttribute('dirname'));
            $summary['dirnameRaw'] = $control->getAttribute('dirname');
            $summary['dirname'] = $dirname['name'];
            $summary['dirnameValid'] = $dirname['valid'];
        }
        if ($control->hasAttribute('size')) {
            $size = self::positiveIntegerToken($control->getAttribute('size'), 1000000);
            $summary['controlSizeRaw'] = $control->getAttribute('size');
            $summary['controlSize'] = $size;
            $summary['controlSizeValid'] = $size !== null;
        }

        return $summary;
    }

    private static function nonNegativeIntegerToken(string $value, int $max): ?int
    {
        $value = trim($value);
        if (preg_match('/^[0-9]+$/', $value) !== 1) {
            return null;
        }

        $integer = filter_var($value, FILTER_VALIDATE_INT);

        return is_int($integer) && $integer >= 0 ? min($integer, $max) : null;
    }

    private static function positiveIntegerToken(string $value, int $max): ?int
    {
        $integer = self::nonNegativeIntegerToken($value, $max);

        return $integer !== null && $integer > 0 ? $integer : null;
    }

    private static function finiteNumericToken(string $value): ?float
    {
        $value = trim($value);
        if ($value === '' || !is_numeric($value)) {
            return null;
        }

        $number = (float) $value;

        return is_finite($number) ? $number : null;
    }

    private static function stepConstraintToken(string $value): float|string|null
    {
        $value = trim($value);
        if (strtolower($value) === 'any') {
            return 'any';
        }

        $number = self::finiteNumericToken($value);

        return $number !== null && $number > 0.0 ? $number : null;
    }

    /**
     * @return array{tokens:list<string>, normalizedTokens:list<string>, invalid:list<string>, state:?string, valid:bool}
     */
    private static function formControlAutocompleteSummary(string $value): array
    {
        $tokens = self::spaceSeparatedTokens($value);
        $normalized = [];
        $invalid = [];
        foreach ($tokens as $token) {
            if (!self::isHtmlReferenceToken($token)) {
                $invalid[] = $token;
                continue;
            }

            $lower = strtolower($token);
            if (!in_array($lower, $normalized, true)) {
                $normalized[] = $lower;
            }
        }

        $state = match ($normalized) {
            ['on'] => 'on',
            ['off'] => 'off',
            [] => null,
            default => 'detail',
        };

        return [
            'tokens' => $tokens,
            'normalizedTokens' => $normalized,
            'invalid' => $invalid,
            'state' => $state,
            'valid' => $tokens !== [] && $invalid === [],
        ];
    }

    /**
     * @return array{name:?string, valid:bool}
     */
    private static function formControlDirnameSummary(string $value): array
    {
        $name = trim($value);

        return [
            'name' => $name === '' ? null : $name,
            'valid' => $name !== '' && self::isHtmlReferenceToken($name),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function labelSummary(\DOMElement $label): array
    {
        $forRaw = self::attributeOrNull($label, 'for');
        $forId = $forRaw === null ? null : trim($forRaw);
        $nestedControls = self::descendantLabelableElements($label);
        $control = null;
        $source = 'missing';
        if ($forRaw !== null) {
            $source = 'for-attribute';
            $candidate = $forId === '' ? null : self::htmlElementById($label, $forId);
            $control = $candidate instanceof \DOMElement && self::isLabelableElement($candidate) ? $candidate : null;
        } elseif ($nestedControls !== []) {
            $source = 'descendant';
            $control = $nestedControls[0];
        }

        return [
            'formLabel' => 'label',
            'labelText' => self::normalizedText($label),
            'forRaw' => $forRaw,
            'forId' => $forId === '' ? null : $forId,
            'labeledControlSource' => $control instanceof \DOMElement ? $source : ($source === 'for-attribute' ? 'missing-for-target' : 'missing'),
            'labeledControl' => $control instanceof \DOMElement ? self::labelableElementSummary($control) : null,
            'nestedControlCount' => count($nestedControls),
            'nestedControls' => array_map(
                static fn (\DOMElement $control): array => self::labelableElementSummary($control),
                $nestedControls
            ),
        ];
    }

    /**
     * @return list<\DOMElement>
     */
    private static function descendantLabelableElements(\DOMElement $element): array
    {
        $controls = [];
        foreach ($element->getElementsByTagName('*') as $descendant) {
            if ($descendant instanceof \DOMElement && self::isLabelableElement($descendant)) {
                $controls[] = $descendant;
            }
        }

        return $controls;
    }

    private static function htmlElementById(\DOMElement $context, string $id): ?\DOMElement
    {
        return self::htmlElementsById($context, $id)[0] ?? null;
    }

    /**
     * @return list<\DOMElement>
     */
    private static function htmlElementsById(\DOMElement $context, string $id): array
    {
        $document = $context->ownerDocument;
        if (!$document instanceof \DOMDocument) {
            return [];
        }

        $matches = [];
        foreach ($document->getElementsByTagName('*') as $element) {
            if ($element instanceof \DOMElement && $element->getAttribute('id') === $id) {
                $matches[] = $element;
            }
        }

        return $matches;
    }

    /**
     * @return list<\DOMElement>
     */
    private static function htmlNamedAnchorElements(\DOMElement $context, string $name): array
    {
        $document = $context->ownerDocument;
        if (!$document instanceof \DOMDocument) {
            return [];
        }

        $matches = [];
        foreach ($document->getElementsByTagName('a') as $element) {
            if ($element instanceof \DOMElement && $element->getAttribute('name') === $name) {
                $matches[] = $element;
            }
        }

        return $matches;
    }

    private static function isLabelableElement(\DOMElement $element): bool
    {
        $name = self::htmlElementName($element);
        if ($name === 'input' && self::inputType($element) === 'hidden') {
            return false;
        }

        return in_array($name, ['button', 'input', 'meter', 'output', 'progress', 'select', 'textarea'], true);
    }

    /**
     * @return array<string, mixed>
     */
    private static function labelableElementSummary(\DOMElement $control): array
    {
        $name = self::htmlElementName($control);
        $summary = [
            'tag' => $name,
            'id' => self::attributeOrNull($control, 'id'),
            'controlName' => self::attributeOrNull($control, 'name'),
        ];

        if (in_array($name, ['button', 'input', 'output', 'select', 'textarea'], true)) {
            $summary['effectiveDisabled'] = self::isEffectivelyDisabledFormControl($control);
        }
        if ($name === 'input') {
            $summary['type'] = self::inputType($control);
        } elseif ($name === 'button') {
            $summary['type'] = self::buttonType($control);
        } elseif ($name === 'progress') {
            $summary += self::progressMeasurementSummary($control, includeLabels: false);
        } elseif ($name === 'meter') {
            $summary += self::meterMeasurementSummary($control, includeLabels: false);
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function progressMeasurementSummary(\DOMElement $progress, bool $includeLabels): array
    {
        $max = self::positiveNumericAttribute($progress, 'max', 1.0);
        $value = self::numericAttribute($progress, 'value', null);
        $value = $value === null ? null : self::boundedNumber($value, 0.0, $max);
        $summary = [
            'measurement' => 'progress',
            'value' => $value,
            'max' => $max,
            'position' => $value === null ? null : $value / $max,
            'indeterminate' => $value === null,
        ];

        if ($includeLabels) {
            $summary['labels'] = self::formControlLabels($progress);
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function meterMeasurementSummary(\DOMElement $meter, bool $includeLabels): array
    {
        $min = self::numericAttribute($meter, 'min', 0.0) ?? 0.0;
        $max = self::numericAttribute($meter, 'max', 1.0) ?? 1.0;
        if ($max < $min) {
            $max = $min;
        }

        $summary = [
            'measurement' => 'meter',
            'min' => $min,
            'max' => $max,
            'value' => self::boundedNumber(self::numericAttribute($meter, 'value', $min) ?? $min, $min, $max),
        ];

        if ($includeLabels) {
            $summary['labels'] = self::formControlLabels($meter);
        }

        foreach (['low', 'high', 'optimum'] as $threshold) {
            $thresholdValue = self::numericAttribute($meter, $threshold, null);
            if ($thresholdValue !== null) {
                $summary[$threshold] = $thresholdValue;
            }
        }

        return $summary;
    }

    /**
     * @return list<\DOMElement>
     */
    private static function detailsSummaryElements(\DOMElement $details): array
    {
        $summaries = [];
        foreach ($details->childNodes as $child) {
            if ($child instanceof \DOMElement && strtolower(self::htmlElementName($child)) === 'summary') {
                $summaries[] = $child;
            }
        }

        return $summaries;
    }

    /**
     * @return array<string, mixed>
     */
    private static function detailsDisclosureSummary(\DOMElement $details): array
    {
        $summaryElements = self::detailsSummaryElements($details);
        $detailsNameRaw = self::attributeOrNull($details, 'name');
        $detailsName = self::normalizedNonEmptyAttribute($detailsNameRaw);
        $group = self::detailsGroupElements($details, $detailsName);
        $openGroup = array_values(array_filter(
            $group,
            static fn (\DOMElement $groupDetails): bool => $groupDetails->hasAttribute('open')
        ));

        return [
            'disclosure' => 'details',
            'open' => $details->hasAttribute('open'),
            'detailsState' => $details->hasAttribute('open') ? 'open' : 'closed',
            'detailsNameRaw' => $detailsNameRaw,
            'detailsName' => $detailsName,
            'detailsGroupIndex' => self::detailsGroupIndex($details, $group),
            'detailsGroupSize' => count($group),
            'detailsGroupOpenCount' => count($openGroup),
            'detailsGroupOpenConflict' => count($openGroup) > 1,
            'summaryText' => $summaryElements === [] ? null : self::normalizedText($summaryElements[0]),
            'primarySummaryId' => $summaryElements === [] ? null : self::attributeOrNull($summaryElements[0], 'id'),
            'summaryElementCount' => count($summaryElements),
            'summaryElements' => self::detailsSummaryElementRecords($summaryElements),
        ];
    }

    /**
     * @param list<\DOMElement> $summaryElements
     * @return list<array<string, mixed>>
     */
    private static function detailsSummaryElementRecords(array $summaryElements): array
    {
        $records = [];
        foreach ($summaryElements as $index => $summary) {
            $records[] = [
                'index' => $index,
                'id' => self::attributeOrNull($summary, 'id'),
                'text' => self::normalizedText($summary),
                'primary' => $index === 0,
                'childElementCount' => count(self::childElements($summary)),
            ];
        }

        return $records;
    }

    /**
     * @return list<\DOMElement>
     */
    private static function detailsGroupElements(\DOMElement $details, ?string $detailsName): array
    {
        if ($detailsName === null) {
            return [];
        }

        $document = $details->ownerDocument;
        if (!$document instanceof \DOMDocument) {
            return [];
        }

        $group = [];
        foreach ($document->getElementsByTagName('details') as $candidate) {
            if ($candidate instanceof \DOMElement && self::normalizedNonEmptyAttribute(self::attributeOrNull($candidate, 'name')) === $detailsName) {
                $group[] = $candidate;
            }
        }

        return $group;
    }

    /**
     * @param list<\DOMElement> $group
     */
    private static function detailsGroupIndex(\DOMElement $details, array $group): ?int
    {
        foreach ($group as $index => $candidate) {
            if ($candidate->isSameNode($details)) {
                return $index + 1;
            }
        }

        return null;
    }

    /**
     * @return array<string, mixed>
     */
    private static function summaryDisclosureSummary(\DOMElement $summary): array
    {
        $details = self::summaryDetailsParent($summary);
        $summaryIndex = null;
        if ($details instanceof \DOMElement) {
            foreach (self::detailsSummaryElements($details) as $index => $candidate) {
                if ($candidate->isSameNode($summary)) {
                    $summaryIndex = $index;
                    break;
                }
            }
        }

        return [
            'disclosure' => 'summary',
            'label' => self::normalizedText($summary),
            'summaryForDetailsId' => $details instanceof \DOMElement ? self::attributeOrNull($details, 'id') : null,
            'summaryForDetailsName' => $details instanceof \DOMElement ? self::normalizedNonEmptyAttribute(self::attributeOrNull($details, 'name')) : null,
            'summaryIndex' => $summaryIndex,
            'summaryPrimary' => $summaryIndex === null ? null : $summaryIndex === 0,
        ];
    }

    private static function summaryDetailsParent(\DOMElement $summary): ?\DOMElement
    {
        $parent = $summary->parentNode;

        return $parent instanceof \DOMElement && self::htmlElementName($parent) === 'details'
            ? $parent
            : null;
    }

    /**
     * @return array<string, mixed>
     */
    private static function dialogSummary(\DOMElement $dialog): array
    {
        $heading = self::firstScopedHeadingElement($dialog);
        $headingName = $heading instanceof \DOMElement ? self::htmlElementName($heading) : null;
        $methodForms = self::dialogMethodFormSummaries($dialog);

        return [
            'dialog' => 'dialog',
            'dialogOpen' => $dialog->hasAttribute('open'),
            'dialogState' => $dialog->hasAttribute('open') ? 'open' : 'closed',
            'dialogHeadingText' => $heading instanceof \DOMElement ? self::normalizedText($heading) : null,
            'dialogHeadingTag' => $headingName,
            'dialogHeadingLevel' => $headingName === null ? null : self::htmlHeadingLevel($headingName),
            'dialogMethodFormCount' => count($methodForms),
            'dialogMethodForms' => $methodForms,
            'dialogCloseValues' => self::dialogCloseValues($methodForms),
        ] + self::dialogClosedBySummary(self::attributeOrNull($dialog, 'closedby'));
    }

    /**
     * @return array<string, mixed>
     */
    private static function dialogClosedBySummary(?string $raw): array
    {
        $keyword = $raw === null ? null : strtolower(trim($raw));
        $state = match ($keyword) {
            'any' => 'any',
            'closerequest' => 'close-request',
            'none' => 'none',
            default => null,
        };
        $defaulted = $raw === null || $state === null;
        $issueRecords = $raw !== null && $state === null
            ? [['code' => 'invalid-dialog-closedby', 'closedByRaw' => $raw]]
            : [];
        $issues = array_values(array_unique(array_map(
            static fn (array $issue): string => (string) ($issue['code'] ?? ''),
            $issueRecords
        )));
        $computedStaticState = $defaulted
            ? 'none'
            : ($state === 'close-request' ? 'closerequest' : $state);

        return [
            'dialogClosedByReviewPolicy' => 'html-dialog-closedby-policy-review',
            'dialogClosedByRaw' => $raw,
            'dialogClosedByKeyword' => $state === 'close-request' ? 'closerequest' : $state,
            'dialogClosedByState' => $state ?? 'auto',
            'dialogClosedByValid' => $raw === null ? null : $state !== null,
            'dialogClosedByDefaulted' => $defaulted,
            'dialogClosedByAutoState' => $defaulted,
            'dialogClosedByAutoReason' => $defaulted
                ? ($raw === null ? 'missing-value-default' : 'invalid-value-default')
                : null,
            'dialogClosedByAutoModalState' => $defaulted ? 'closerequest' : null,
            'dialogClosedByAutoModelessState' => $defaulted ? 'none' : null,
            'dialogClosedByComputedStaticState' => $computedStaticState,
            'dialogCloseRequestAllowed' => match ($state) {
                'any', 'close-request' => true,
                'none' => false,
                default => null,
            },
            'dialogLightDismissAllowed' => match ($state) {
                'any' => true,
                'close-request', 'none' => false,
                default => null,
            },
            'dialogDeveloperCloseRequired' => $computedStaticState === 'none',
            'dialogClosedByIssues' => $issueRecords,
            'dialogClosedByIssueCodes' => $issues,
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function dialogMethodFormSummaries(\DOMElement $dialog): array
    {
        $forms = [];
        foreach (self::descendantHtmlElements($dialog, 'form') as $form) {
            if (self::formMethod($form, 'method', 'get') !== 'dialog') {
                continue;
            }

            $forms[] = [
                'id' => self::attributeOrNull($form, 'id'),
                'methodRaw' => self::attributeOrNull($form, 'method'),
                'method' => 'dialog',
                'action' => self::attributeOrNull($form, 'action'),
                'submitters' => self::dialogMethodSubmitterSummaries($form),
            ];
        }

        return $forms;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function dialogMethodSubmitterSummaries(\DOMElement $form): array
    {
        $submitters = [];
        foreach ($form->getElementsByTagName('*') as $control) {
            if (!$control instanceof \DOMElement) {
                continue;
            }

            $name = self::htmlElementName($control);
            if ($name === 'button') {
                $type = self::buttonType($control);
                if ($type !== 'submit') {
                    continue;
                }
                $label = self::normalizedText($control);
                $value = $control->hasAttribute('value') ? $control->getAttribute('value') : '';
            } elseif ($name === 'input') {
                $type = self::inputType($control);
                if (!self::isInputSubmitterType($type)) {
                    continue;
                }
                $value = $control->getAttribute('value');
                $label = $value;
            } else {
                continue;
            }

            $formMethod = self::formMethod($control, 'formmethod', null);
            $effectiveMethod = $formMethod ?? 'dialog';
            $submitters[] = [
                'tag' => $name,
                'type' => $type,
                'name' => self::attributeOrNull($control, 'name'),
                'value' => $value,
                'label' => $label,
                'formMethod' => $formMethod,
                'effectiveFormMethod' => $effectiveMethod,
                'disabled' => $control->hasAttribute('disabled'),
                'effectiveDisabled' => self::isEffectivelyDisabledFormControl($control),
                'dialogCloses' => $effectiveMethod === 'dialog',
            ];
        }

        return $submitters;
    }

    /**
     * @param list<array<string, mixed>> $forms
     * @return list<string>
     */
    private static function dialogCloseValues(array $forms): array
    {
        $values = [];
        foreach ($forms as $form) {
            foreach (($form['submitters'] ?? []) as $submitter) {
                if (is_array($submitter) && ($submitter['dialogCloses'] ?? false) === true) {
                    $values[] = (string) ($submitter['value'] ?? '');
                }
            }
        }

        return $values;
    }

    /**
     * @return array<string, mixed>
     */
    private static function revisionSummary(\DOMElement $element, string $name): array
    {
        $summary = [
            'revision' => $name === 'ins' ? 'insertion' : 'deletion',
            'revisionTag' => $name,
            'revisionCite' => self::attributeOrNull($element, 'cite'),
            'revisionDatetimeRaw' => self::attributeOrNull($element, 'datetime'),
            'revisionDatetime' => null,
            'revisionDatetimeKind' => null,
            'revisionDatetimeValid' => false,
        ];

        if ($summary['revisionDatetimeRaw'] === null) {
            return $summary;
        }

        $datetime = self::revisionDatetimeSummary($summary['revisionDatetimeRaw']);
        if ($datetime === null) {
            $summary['revisionDatetimeKind'] = 'invalid';

            return $summary;
        }

        $summary['revisionDatetime'] = $datetime['value'];
        $summary['revisionDatetimeKind'] = $datetime['kind'];
        $summary['revisionDatetimeValid'] = true;

        return $summary;
    }

    /**
     * @return array{kind:string, value:string}|null
     */
    private static function revisionDatetimeSummary(string $value): ?array
    {
        $value = trim($value);
        if ($value === '' || strlen($value) > 128 || preg_match('/[<>{}`]/', $value) === 1) {
            return null;
        }

        $datePattern = '([0-9]{4})-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])';
        $timePattern = '((?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9](?:\.[0-9]{1,3})?)?)';
        $timezonePattern = '([Zz]|[+-](?:[01][0-9]|2[0-3]):?[0-5][0-9])';

        if (preg_match('/^' . $datePattern . '[T ]' . $timePattern . $timezonePattern . '$/', $value, $matches) === 1) {
            if (!self::isValidDateParts((string) $matches[1], (string) $matches[2], (string) $matches[3])) {
                return null;
            }

            return [
                'kind' => 'global-datetime',
                'value' => (string) $matches[1] . '-' . (string) $matches[2] . '-' . (string) $matches[3]
                    . 'T' . (string) $matches[4]
                    . self::normalizeTimezone((string) $matches[5]),
            ];
        }

        if (preg_match('/^' . $datePattern . '[T ]' . $timePattern . '$/', $value, $matches) === 1) {
            if (!self::isValidDateParts((string) $matches[1], (string) $matches[2], (string) $matches[3])) {
                return null;
            }

            return [
                'kind' => 'local-datetime',
                'value' => (string) $matches[1] . '-' . (string) $matches[2] . '-' . (string) $matches[3]
                    . 'T' . (string) $matches[4],
            ];
        }

        if (preg_match('/^' . $datePattern . '$/', $value, $matches) === 1) {
            if (!self::isValidDateParts((string) $matches[1], (string) $matches[2], (string) $matches[3])) {
                return null;
            }

            return [
                'kind' => 'date',
                'value' => (string) $matches[1] . '-' . (string) $matches[2] . '-' . (string) $matches[3],
            ];
        }

        return null;
    }

    /**
     * @return array<string, mixed>
     */
    private static function hyperlinkSummary(\DOMElement $element, string $name): array
    {
        $relRaw = self::attributeOrNull($element, 'rel');
        $pingRaw = self::attributeOrNull($element, 'ping');
        $summary = [
            'hyperlink' => $name,
            'href' => self::attributeOrNull($element, 'href'),
            'target' => self::attributeOrNull($element, 'target'),
            'relRaw' => $relRaw,
            'relTokens' => $relRaw === null ? [] : self::spaceSeparatedTokens($relRaw),
            'download' => self::attributeOrNull($element, 'download'),
            'hreflang' => self::attributeOrNull($element, 'hreflang'),
            'mimeType' => self::attributeOrNull($element, 'type'),
            'pingRaw' => $pingRaw,
            'pingUrls' => $pingRaw === null ? [] : self::spaceSeparatedTokens($pingRaw),
            'referrerpolicy' => self::attributeOrNull($element, 'referrerpolicy'),
            'label' => $name === 'area'
                ? self::attributeOrNull($element, 'alt')
                : self::normalizedText($element),
        ];
        $summary += self::hyperlinkNavigationReviewSummary($element, $name, $relRaw, $pingRaw);
        $summary += self::hyperlinkAttributionSrcReviewSummary($element, $name);

        if ($name === 'area') {
            $summary['shape'] = self::attributeOrNull($element, 'shape');
            $summary['coords'] = self::attributeOrNull($element, 'coords');
            $summary += self::imageMapAreaGeometrySummary($element);
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function hyperlinkNavigationReviewSummary(
        \DOMElement $element,
        string $name,
        ?string $relRaw,
        ?string $pingRaw
    ): array {
        $href = self::attributeOrNull($element, 'href');
        $hrefSummary = self::hyperlinkUrlReviewSummary($href);
        $targetRaw = self::attributeOrNull($element, 'target');
        $targetName = $targetRaw === null ? null : trim($targetRaw);
        $targetLower = $targetName === null ? null : strtolower($targetName);
        $rel = self::hyperlinkRelTokenReviewSummary($relRaw);
        $hasNoopener = isset($rel['counts']['noopener']);
        $hasNoreferrer = isset($rel['counts']['noreferrer']);
        $hasOpener = isset($rel['counts']['opener']);
        $targetBlank = $targetLower === '_blank';
        $targetOpenerAllowed = $targetBlank && $hasOpener && !$hasNoopener && !$hasNoreferrer;
        $downloadRaw = self::attributeOrNull($element, 'download');
        $downloadRequested = $element->hasAttribute('download');
        $referrerPolicyRaw = self::attributeOrNull($element, 'referrerpolicy');
        $referrerPolicy = $referrerPolicyRaw === null ? null : self::referrerPolicyState($referrerPolicyRaw);
        $fragmentTarget = self::hyperlinkFragmentTargetSummary($element, $href);
        $pingUrls = $pingRaw === null ? [] : self::spaceSeparatedTokens($pingRaw);
        $pingRecords = [];
        $unsafePingUrls = [];
        $nonHttpPingUrls = [];
        $issues = [];
        $pingRequested = $pingRaw !== null;

        if (($hrefSummary['unsafe'] ?? false) === true) {
            $issues[] = [
                'code' => 'unsafe-href',
                'href' => $href,
                'scheme' => $hrefSummary['scheme'],
            ];
        }

        if ($targetOpenerAllowed) {
            $issues[] = ['code' => 'target-blank-explicit-opener'];
        }

        foreach ($rel['invalid'] as $token) {
            $issues[] = ['code' => 'invalid-rel-token', 'relToken' => $token];
        }
        foreach ($rel['duplicates'] as $token) {
            $issues[] = [
                'code' => 'duplicate-rel-token',
                'relToken' => $token,
                'count' => $rel['counts'][$token],
            ];
        }

        if ($referrerPolicyRaw !== null && $referrerPolicy === null) {
            $issues[] = ['code' => 'invalid-referrer-policy', 'referrerPolicyRaw' => $referrerPolicyRaw];
        }

        if ($pingRequested && trim($pingRaw) === '') {
            $issues[] = ['code' => 'empty-ping-url-list'];
        }

        foreach ($pingUrls as $url) {
            $urlSummary = self::hyperlinkUrlReviewSummary($url);
            $record = [
                'url' => $url,
                'kind' => $urlSummary['kind'],
                'scheme' => $urlSummary['scheme'],
                'unsafe' => $urlSummary['unsafe'],
            ];
            $pingRecords[] = $record;
            if ($urlSummary['unsafe'] === true) {
                $unsafePingUrls[] = $url;
                $issues[] = [
                    'code' => 'unsafe-ping-url',
                    'url' => $url,
                    'scheme' => $urlSummary['scheme'],
                ];
                continue;
            }
            if ($urlSummary['kind'] === 'absolute' && !in_array($urlSummary['scheme'], ['http', 'https'], true)) {
                $nonHttpPingUrls[] = $url;
                $issues[] = [
                    'code' => 'non-http-ping-url',
                    'url' => $url,
                    'scheme' => $urlSummary['scheme'],
                ];
            }
        }
        $issueCodes = array_values(array_unique(array_map(
            static fn (array $issue): string => (string) ($issue['code'] ?? ''),
            $issues
        )));

        return [
            'hyperlinkNavigationReview' => $name,
            'hrefRaw' => $href,
            'hrefKind' => $hrefSummary['kind'],
            'hrefScheme' => $hrefSummary['scheme'],
            'hrefUnsafe' => $hrefSummary['unsafe'],
            'targetRaw' => $targetRaw,
            'targetName' => $targetName === '' ? null : $targetName,
            'targetReserved' => in_array($targetLower, ['_blank', '_parent', '_self', '_top'], true),
            'targetBlank' => $targetBlank,
            'targetOpenerAllowed' => $targetOpenerAllowed,
            'targetNoopener' => $targetBlank && ($hasNoopener || $hasNoreferrer || !$hasOpener),
            'downloadRequested' => $downloadRequested,
            'downloadRaw' => $downloadRaw,
            'downloadSuggestedFilename' => !$downloadRequested || trim($downloadRaw ?? '') === '' ? null : trim($downloadRaw ?? ''),
            'hyperlinkRelTokens' => $rel['tokens'],
            'hyperlinkRelTokenCounts' => $rel['counts'],
            'duplicateHyperlinkRelTokens' => $rel['duplicates'],
            'invalidHyperlinkRelTokens' => $rel['invalid'],
            'hyperlinkSecurityRelTokens' => array_values(array_filter(
                ['noopener', 'noreferrer', 'opener'],
                static fn (string $token): bool => isset($rel['counts'][$token])
            )),
            'referrerPolicyRaw' => $referrerPolicyRaw,
            'referrerPolicy' => $referrerPolicy,
            'referrerPolicyValid' => $referrerPolicyRaw === null ? null : $referrerPolicy !== null,
            'pingRequested' => $pingRequested,
            'pingRawEmpty' => $pingRequested ? trim($pingRaw) === '' : null,
            'pingSideEffect' => $pingUrls !== [],
            'pingUrlCount' => count($pingUrls),
            'pingUrlRecords' => $pingRecords,
            'unsafePingUrls' => $unsafePingUrls,
            'nonHttpPingUrls' => $nonHttpPingUrls,
            'navigationIssues' => $issues,
            'navigationIssueCodes' => $issueCodes,
            'navigationIssueCount' => count($issues),
            'hyperlinkNavigationValid' => $issues === [],
        ] + $fragmentTarget;
    }

    /**
     * @return array<string, mixed>
     */
    private static function hyperlinkAttributionSrcReviewSummary(\DOMElement $element, string $name): array
    {
        if (!$element->hasAttribute('attributionsrc')) {
            return [];
        }

        $raw = $element->getAttribute('attributionsrc');
        $urls = self::spaceSeparatedTokens($raw);
        $records = [];
        $unsafeUrls = [];
        $nonHttpUrls = [];
        $issues = [];

        foreach ($urls as $url) {
            $urlSummary = self::hyperlinkUrlReviewSummary($url);
            $records[] = [
                'url' => $url,
                'kind' => $urlSummary['kind'],
                'scheme' => $urlSummary['scheme'],
                'unsafe' => $urlSummary['unsafe'],
            ];

            if ($urlSummary['unsafe'] === true) {
                $unsafeUrls[] = $url;
                $issues[] = [
                    'code' => 'unsafe-attributionsrc-url',
                    'url' => $url,
                    'scheme' => $urlSummary['scheme'],
                ];
                continue;
            }

            if ($urlSummary['kind'] === 'absolute' && !in_array($urlSummary['scheme'], ['http', 'https'], true)) {
                $nonHttpUrls[] = $url;
                $issues[] = [
                    'code' => 'non-http-attributionsrc-url',
                    'url' => $url,
                    'scheme' => $urlSummary['scheme'],
                ];
            }
        }

        return [
            'hyperlinkAttributionSrcReviewPolicy' => 'hyperlink-attributionsrc-source-registration-review',
            'attributionSrcElement' => $name,
            'attributionSrcRequested' => true,
            'attributionSrcRaw' => $raw,
            'attributionSrcEmpty' => trim($raw) === '',
            'attributionSrcMode' => trim($raw) === '' ? 'navigation-source-origin' : 'navigation-source-urls',
            'attributionSrcUrls' => $urls,
            'attributionSrcUrlCount' => count($urls),
            'attributionSrcUrlRecords' => $records,
            'unsafeAttributionSrcUrls' => $unsafeUrls,
            'nonHttpAttributionSrcUrls' => $nonHttpUrls,
            'attributionSrcIssues' => $issues,
            'attributionSrcIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ))),
            'attributionSrcValid' => $issues === [],
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function hyperlinkFragmentTargetSummary(\DOMElement $element, ?string $href): array
    {
        $hrefRaw = $href === null ? null : trim($href);
        if ($hrefRaw === null || !str_starts_with($hrefRaw, '#')) {
            return [];
        }

        $fragmentRaw = substr($hrefRaw, 1);
        $fragmentTarget = rawurldecode($fragmentRaw);
        $documentTop = $fragmentTarget === '';
        $targetValid = $documentTop || self::isHtmlIdReferenceToken($fragmentTarget);
        $targetType = null;
        $targets = [];
        $issues = [];

        if (!$targetValid) {
            $issues[] = [
                'code' => 'invalid-hyperlink-fragment-target',
                'fragmentRaw' => $fragmentRaw,
            ];
        } elseif (!$documentTop) {
            $targets = self::htmlElementsById($element, $fragmentTarget);
            $targetType = $targets === [] ? null : 'id';

            if ($targets === []) {
                $targets = self::htmlNamedAnchorElements($element, $fragmentTarget);
                $targetType = $targets === [] ? null : 'anchor-name';
            }

            if ($targets === []) {
                $issues[] = [
                    'code' => 'missing-hyperlink-fragment-target',
                    'fragmentTarget' => $fragmentTarget,
                ];
            } elseif (count($targets) > 1) {
                $issues[] = [
                    'code' => 'duplicate-hyperlink-fragment-target',
                    'fragmentTarget' => $fragmentTarget,
                    'targetType' => $targetType,
                    'count' => count($targets),
                ];
            }
        }

        $targetSummaries = [];
        foreach ($targets as $target) {
            $targetSummaries[] = self::hyperlinkFragmentTargetElementSummary($target, $targetType ?? 'element');
        }

        return [
            'hrefFragmentReviewPolicy' => 'hyperlink-fragment-target-review',
            'hrefFragmentRaw' => $fragmentRaw,
            'hrefFragmentTarget' => $documentTop ? null : $fragmentTarget,
            'hrefFragmentTargetValid' => $targetValid,
            'hrefFragmentDocumentTop' => $documentTop,
            'hrefFragmentTargetFound' => $targetSummaries !== [],
            'hrefFragmentTargetCount' => count($targetSummaries),
            'hrefFragmentTargetKind' => self::hyperlinkFragmentTargetKind(
                $documentTop,
                $targetValid,
                $targetType,
                count($targetSummaries)
            ),
            'hrefFragmentTargetElement' => $targetSummaries[0] ?? null,
            'hrefFragmentTargetElements' => $targetSummaries,
            'hrefFragmentIssueCodes' => array_values(array_map(
                static fn (array $issue): string => (string) $issue['code'],
                $issues
            )),
            'hrefFragmentIssues' => $issues,
        ];
    }

    private static function hyperlinkFragmentTargetKind(
        bool $documentTop,
        bool $targetValid,
        ?string $targetType,
        int $targetCount
    ): string {
        if ($documentTop) {
            return 'document-top';
        }
        if (!$targetValid) {
            return 'invalid-reference';
        }
        if ($targetType === null) {
            return 'missing-target';
        }
        if ($targetCount > 1) {
            return 'duplicate-' . $targetType;
        }

        return $targetType;
    }

    /**
     * @return array<string, mixed>
     */
    private static function hyperlinkFragmentTargetElementSummary(\DOMElement $target, string $targetType): array
    {
        $name = self::htmlElementName($target);
        $summary = [
            'targetType' => $targetType,
            'tag' => $name,
            'id' => self::attributeOrNull($target, 'id'),
            'nameAttribute' => self::attributeOrNull($target, 'name'),
            'text' => self::normalizedText($target),
        ];

        if (self::isHtmlHeadingElementName($name)) {
            $summary['headingLevel'] = self::htmlHeadingLevel($name);
        }

        return $summary;
    }

    /**
     * @return array{tokens:list<string>, counts:array<string, int>, duplicates:list<string>, invalid:list<string>}
     */
    private static function hyperlinkRelTokenReviewSummary(?string $relRaw): array
    {
        $tokens = [];
        $counts = [];
        $duplicates = [];
        $invalid = [];
        foreach ($relRaw === null ? [] : self::spaceSeparatedTokens($relRaw) as $token) {
            if (!self::isSafeHtmlRelToken($token)) {
                $invalid[] = $token;
                continue;
            }

            $lower = strtolower($token);
            if (!isset($counts[$lower])) {
                $tokens[] = $lower;
                $counts[$lower] = 0;
            }
            ++$counts[$lower];
        }

        foreach ($counts as $token => $count) {
            if ($count > 1) {
                $duplicates[] = $token;
            }
        }

        return [
            'tokens' => $tokens,
            'counts' => $counts,
            'duplicates' => $duplicates,
            'invalid' => $invalid,
        ];
    }

    /**
     * @return array{kind:string, scheme:?string, unsafe:bool}
     */
    private static function hyperlinkUrlReviewSummary(?string $url): array
    {
        if ($url === null) {
            return ['kind' => 'missing', 'scheme' => null, 'unsafe' => false];
        }

        $url = trim($url);
        if ($url === '') {
            return ['kind' => 'empty', 'scheme' => null, 'unsafe' => false];
        }
        if (preg_match('/[\p{Cc}\p{Zl}\p{Zp}]/u', $url) === 1) {
            return ['kind' => 'invalid', 'scheme' => null, 'unsafe' => true];
        }
        if (str_starts_with($url, '#')) {
            return ['kind' => 'fragment', 'scheme' => null, 'unsafe' => false];
        }
        if (str_starts_with($url, '//')) {
            return ['kind' => 'scheme-relative', 'scheme' => null, 'unsafe' => false];
        }
        if (preg_match('/^([A-Za-z][A-Za-z0-9+.-]*):/', $url, $matches) === 1) {
            $scheme = strtolower((string) $matches[1]);

            return [
                'kind' => 'absolute',
                'scheme' => $scheme,
                'unsafe' => in_array($scheme, ['data', 'file', 'javascript', 'vbscript'], true),
            ];
        }

        return ['kind' => 'relative', 'scheme' => null, 'unsafe' => false];
    }

    private static function referrerPolicyState(string $value): ?string
    {
        $value = strtolower(trim($value));

        return in_array($value, [
            'no-referrer',
            'no-referrer-when-downgrade',
            'origin',
            'origin-when-cross-origin',
            'same-origin',
            'strict-origin',
            'strict-origin-when-cross-origin',
            'unsafe-url',
        ], true) ? $value : null;
    }

    private static function isValidDateParts(string $year, string $month, string $day): bool
    {
        return checkdate((int) $month, (int) $day, (int) $year);
    }

    private static function normalizeTimezone(string $timezone): string
    {
        if (strtoupper($timezone) === 'Z') {
            return 'Z';
        }

        if (preg_match('/^([+-])([0-9]{2}):?([0-9]{2})$/', $timezone, $matches) === 1) {
            return (string) $matches[1] . (string) $matches[2] . ':' . (string) $matches[3];
        }

        return $timezone;
    }

    /**
     * @return array<string, mixed>
     */
    private static function embeddedResourceSummary(\DOMElement $element, string $name): array
    {
        return match ($name) {
            'picture' => self::pictureSummary($element),
            'img' => self::imageSummary($element),
            'audio', 'video' => self::mediaElementSummary($element, $name),
            'source' => ['embeddedResource' => 'source'] + self::sourceElementSummary($element),
            'track' => ['embeddedResource' => 'track'] + self::trackElementSummary($element),
            'iframe' => self::iframeSummary($element),
            'embed' => self::embedSummary($element),
            'object' => self::objectSummary($element),
            'param' => self::paramElementSummary($element),
            'canvas' => self::canvasSummary($element),
            default => [],
        };
    }

    private static function isDocBookMediaElementName(string $name): bool
    {
        return in_array($name, ['mediaobject', 'inlinemediaobject', 'imageobject', 'imagedata', 'textobject', 'alt'], true);
    }

    /**
     * @return array<string, mixed>
     */
    private static function docBookMediaSummary(\DOMElement $element, string $name): array
    {
        return match ($name) {
            'mediaobject', 'inlinemediaobject' => self::docBookMediaObjectSummary($element, $name),
            'imageobject' => self::docBookImageObjectSummary($element),
            'imagedata' => ['docBookMediaPart' => 'imagedata'] + self::docBookImageDataSummary($element),
            'textobject' => self::docBookTextObjectSummary($element),
            'alt' => self::docBookAltSummary($element),
            default => [],
        };
    }

    /**
     * @return array<string, mixed>
     */
    private static function docBookMediaObjectSummary(\DOMElement $media, string $name): array
    {
        $altTexts = self::docBookAltTexts($media);
        $textObjects = self::docBookTextObjectSummaries($media);
        $imageData = self::docBookImageDataSummaries($media);
        $linkendAssociations = self::docBookLinkendAssociations($media);
        $hasAccessibleText = $altTexts !== [] || array_filter(
            array_map(static fn (array $textObject): string => (string) ($textObject['text'] ?? ''), $textObjects),
            static fn (string $text): bool => $text !== ''
        ) !== [];
        $issues = [];

        if (!$hasAccessibleText && $imageData !== []) {
            $issues[] = [
                'code' => 'missing-docbook-media-alt',
                'media' => $name,
                'imageDataCount' => count($imageData),
            ];
        }

        foreach ($imageData as $index => $image) {
            if (($image['target'] ?? null) === null) {
                $issues[] = [
                    'code' => 'missing-docbook-imagedata-target',
                    'imageDataIndex' => $index,
                ];
            }
        }

        foreach ($linkendAssociations as $association) {
            foreach (($association['invalidIds'] ?? []) as $invalidId) {
                $issues[] = [
                    'code' => 'invalid-docbook-linkend',
                    'element' => $association['element'],
                    'linkendId' => $invalidId,
                ];
            }
            foreach (($association['missingIds'] ?? []) as $missingId) {
                $issues[] = [
                    'code' => 'missing-docbook-linkend-target',
                    'element' => $association['element'],
                    'linkendId' => $missingId,
                ];
            }
        }

        return [
            'docBookMediaObject' => $name,
            'docBookMediaInline' => $name === 'inlinemediaobject',
            'docBookMediaId' => self::docBookElementId($media),
            'docBookAltTexts' => $altTexts,
            'docBookTextObjects' => $textObjects,
            'docBookTextObjectTexts' => array_values(array_filter(
                array_map(static fn (array $textObject): string => (string) ($textObject['text'] ?? ''), $textObjects),
                static fn (string $text): bool => $text !== ''
            )),
            'docBookImageData' => $imageData,
            'docBookImageTargetBasenames' => array_values(array_filter(
                array_map(static fn (array $image): ?string => $image['targetBasename'] ?? null, $imageData),
                static fn (?string $basename): bool => $basename !== null && $basename !== ''
            )),
            'docBookImageContentTypes' => array_values(array_filter(
                array_map(static fn (array $image): ?string => $image['contentType'] ?? null, $imageData),
                static fn (?string $contentType): bool => $contentType !== null && $contentType !== ''
            )),
            'docBookLinkendAssociations' => $linkendAssociations,
            'docBookMissingAlt' => !$hasAccessibleText && $imageData !== [],
            'docBookMediaIssues' => $issues,
            'docBookMediaIssueCount' => count($issues),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function docBookImageObjectSummary(\DOMElement $imageObject): array
    {
        $imageData = self::docBookImageDataSummaries($imageObject);

        return [
            'docBookMediaPart' => 'imageobject',
            'docBookImageData' => $imageData,
            'docBookImageDataCount' => count($imageData),
            'docBookImageTargetBasenames' => array_values(array_filter(
                array_map(static fn (array $image): ?string => $image['targetBasename'] ?? null, $imageData),
                static fn (?string $basename): bool => $basename !== null && $basename !== ''
            )),
            'docBookImageContentTypes' => array_values(array_filter(
                array_map(static fn (array $image): ?string => $image['contentType'] ?? null, $imageData),
                static fn (?string $contentType): bool => $contentType !== null && $contentType !== ''
            )),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function docBookTextObjectSummary(\DOMElement $textObject): array
    {
        $text = self::normalizedText($textObject);

        return [
            'docBookMediaPart' => 'textobject',
            'docBookTextObjectText' => $text,
            'docBookTextObjectTextLength' => strlen($text),
            'docBookTextObjectId' => self::docBookElementId($textObject),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function docBookAltSummary(\DOMElement $alt): array
    {
        $text = self::normalizedText($alt);

        return [
            'docBookMediaPart' => 'alt',
            'docBookAltText' => $text,
            'docBookAltTextLength' => strlen($text),
        ];
    }

    /**
     * @return list<string>
     */
    private static function docBookAltTexts(\DOMElement $media): array
    {
        $texts = [];
        foreach (self::descendantHtmlElements($media, 'alt') as $alt) {
            $text = self::normalizedText($alt);
            if ($text !== '') {
                $texts[] = $text;
            }
        }

        return $texts;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function docBookTextObjectSummaries(\DOMElement $media): array
    {
        $summaries = [];
        foreach (self::descendantHtmlElements($media, 'textobject') as $index => $textObject) {
            $text = self::normalizedText($textObject);
            $summaries[] = [
                'index' => $index,
                'id' => self::docBookElementId($textObject),
                'text' => $text,
                'textLength' => strlen($text),
            ];
        }

        return $summaries;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function docBookImageDataSummaries(\DOMElement $media): array
    {
        $summaries = [];
        foreach (self::descendantHtmlElements($media, 'imagedata') as $index => $imageData) {
            $summaries[] = ['index' => $index] + self::docBookImageDataSummary($imageData);
        }

        return $summaries;
    }

    /**
     * @return array<string, mixed>
     */
    private static function docBookImageDataSummary(\DOMElement $imageData): array
    {
        $fileref = self::attributeOrNull($imageData, 'fileref');
        $entityref = self::attributeOrNull($imageData, 'entityref');
        $xlinkHref = self::attribute($imageData, 'href', self::XLINK_NAMESPACE);
        $format = self::attributeOrNull($imageData, 'format');
        $target = null;
        $targetSource = null;
        foreach (['fileref' => $fileref, 'entityref' => $entityref, 'xlink:href' => $xlinkHref] as $source => $candidate) {
            $target = self::normalizedNonEmptyAttribute($candidate);
            if ($target !== null) {
                $targetSource = $source;
                break;
            }
        }
        $path = $target === null ? null : self::docBookTargetPath($target);
        $basename = $path === null ? null : self::docBookTargetBasename($path);
        $extension = $basename === null ? null : self::docBookTargetExtension($basename);
        $contentType = self::docBookImageContentType($format, $extension);

        return [
            'target' => $target,
            'targetSource' => $targetSource,
            'fileref' => $fileref,
            'entityref' => $entityref,
            'xlinkHref' => $xlinkHref,
            'format' => $format,
            'targetPath' => $path,
            'targetBasename' => $basename,
            'targetExtension' => $extension,
            'contentType' => $contentType['contentType'],
            'contentTypeSource' => $contentType['source'],
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function docBookLinkendAssociations(\DOMElement $context): array
    {
        $knownIds = self::docBookDocumentIds($context);
        $associations = [];
        $elements = [];
        if ($context->hasAttribute('linkend')) {
            $elements[] = $context;
        }
        foreach ($context->getElementsByTagName('*') as $element) {
            if ($element instanceof \DOMElement && $element->hasAttribute('linkend')) {
                $elements[] = $element;
            }
        }

        foreach ($elements as $element) {
            $raw = $element->getAttribute('linkend');
            $ids = self::spaceSeparatedTokens($raw);
            $invalid = [];
            $resolved = [];
            $missing = [];
            foreach ($ids as $id) {
                if (!self::isHtmlReferenceToken($id)) {
                    $invalid[] = $id;
                    continue;
                }
                if (isset($knownIds[$id])) {
                    $resolved[] = $id;
                } else {
                    $missing[] = $id;
                }
            }

            $associations[] = [
                'element' => self::htmlElementName($element),
                'sourceId' => self::docBookElementId($element),
                'linkendRaw' => $raw,
                'linkendIds' => $ids,
                'resolvedIds' => $resolved,
                'missingIds' => $missing,
                'invalidIds' => $invalid,
                'valid' => $ids !== [] && $invalid === [] && $missing === [],
            ];
        }

        return $associations;
    }

    /**
     * @return array<string, true>
     */
    private static function docBookDocumentIds(\DOMElement $context): array
    {
        $document = $context->ownerDocument;
        if (!$document instanceof \DOMDocument) {
            return [];
        }

        $ids = [];
        foreach ($document->getElementsByTagName('*') as $element) {
            if (!$element instanceof \DOMElement) {
                continue;
            }
            foreach (['id', 'xml:id'] as $attribute) {
                if (!$element->hasAttribute($attribute)) {
                    continue;
                }
                $id = trim($element->getAttribute($attribute));
                if ($id !== '' && self::isHtmlReferenceToken($id)) {
                    $ids[$id] = true;
                }
            }
        }

        return $ids;
    }

    private static function docBookTargetPath(string $target): string
    {
        $cut = strlen($target);
        foreach (['#', '?'] as $delimiter) {
            $position = strpos($target, $delimiter);
            if ($position !== false) {
                $cut = min($cut, $position);
            }
        }

        return substr($target, 0, $cut);
    }

    private static function docBookTargetBasename(string $path): ?string
    {
        $path = str_replace('\\', '/', trim($path));
        if ($path === '') {
            return null;
        }

        $basename = basename($path);

        return $basename === '' || $basename === '.' ? null : $basename;
    }

    private static function docBookTargetExtension(string $basename): ?string
    {
        $extension = strtolower(pathinfo($basename, PATHINFO_EXTENSION));

        return $extension === '' ? null : $extension;
    }

    /**
     * @return array{contentType:?string, source:?string}
     */
    private static function docBookImageContentType(?string $format, ?string $extension): array
    {
        $format = self::normalizedNonEmptyAttribute($format);
        if ($format !== null) {
            $normalized = strtolower($format);
            if (str_contains($normalized, ';')) {
                $normalized = trim(strstr($normalized, ';', true) ?: $normalized);
            }
            if (str_contains($normalized, '/')) {
                return ['contentType' => $normalized, 'source' => 'format'];
            }

            $fromFormat = self::docBookImageExtensionContentType($normalized);
            if ($fromFormat !== null) {
                return ['contentType' => $fromFormat, 'source' => 'format'];
            }
        }

        $fromExtension = $extension === null ? null : self::docBookImageExtensionContentType($extension);

        return ['contentType' => $fromExtension, 'source' => $fromExtension === null ? null : 'extension'];
    }

    private static function docBookImageExtensionContentType(string $extension): ?string
    {
        return match (strtolower($extension)) {
            'apng' => 'image/apng',
            'avif' => 'image/avif',
            'bmp' => 'image/bmp',
            'eps', 'epsf', 'ps' => 'application/postscript',
            'gif' => 'image/gif',
            'heic' => 'image/heic',
            'ico' => 'image/x-icon',
            'jpeg', 'jpg', 'jpe' => 'image/jpeg',
            'pdf' => 'application/pdf',
            'png' => 'image/png',
            'svg', 'svgz' => 'image/svg+xml',
            'tif', 'tiff' => 'image/tiff',
            'webp' => 'image/webp',
            default => null,
        };
    }

    /**
     * @return array<string, mixed>
     */
    private static function canvasSummary(\DOMElement $canvas): array
    {
        $fallbackText = self::normalizedText($canvas);
        $fallbackElementNames = [];
        foreach ($canvas->childNodes as $child) {
            if ($child instanceof \DOMElement) {
                $fallbackElementNames[] = self::htmlElementName($child);
            }
        }

        $summary = [
            'embeddedResource' => 'canvas',
            'width' => self::attributeOrNull($canvas, 'width'),
            'height' => self::attributeOrNull($canvas, 'height'),
            'bitmapWidth' => self::nonNegativeIntegerAttribute($canvas, 'width', 300, 100000),
            'bitmapHeight' => self::nonNegativeIntegerAttribute($canvas, 'height', 150, 100000),
            'fallbackElementNames' => $fallbackElementNames,
            'fallbackElementCount' => count($fallbackElementNames),
            'fallbackTextLength' => strlen($fallbackText),
            'fallbackTextSha256' => hash('sha256', $fallbackText),
            'canvasReviewPolicy' => 'canvas-fallback-source',
        ];

        if ($fallbackText !== '') {
            $summary['fallbackText'] = $fallbackText;
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function pictureSummary(\DOMElement $picture): array
    {
        $image = self::firstDescendantHtmlElement($picture, 'img');

        return [
            'embeddedResource' => 'picture',
            'pictureSources' => array_map(
                static fn (\DOMElement $source): array => self::sourceElementSummary($source),
                self::descendantHtmlElements($picture, 'source'),
            ),
            'image' => $image instanceof \DOMElement ? self::imageSummary($image) : null,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function imageSummary(\DOMElement $image): array
    {
        $srcset = self::attributeOrNull($image, 'srcset');
        $summary = [
            'embeddedResource' => 'image',
            'src' => self::attributeOrNull($image, 'src'),
            'alt' => self::attributeOrNull($image, 'alt'),
            'srcset' => $srcset,
            'srcsetCandidates' => self::srcsetCandidateSummaries($srcset),
            'sizes' => self::attributeOrNull($image, 'sizes'),
            'loading' => self::attributeOrNull($image, 'loading'),
            'decoding' => self::attributeOrNull($image, 'decoding'),
            'crossorigin' => self::attributeOrNull($image, 'crossorigin'),
            'referrerpolicy' => self::attributeOrNull($image, 'referrerpolicy'),
            'fetchpriority' => self::attributeOrNull($image, 'fetchpriority'),
        ];
        $summary += self::imageLoadingReviewSummary($image);
        $summary += self::srcsetResourceReviewSummary($srcset, 'srcset');

        if ($image->hasAttribute('usemap')) {
            $useMap = self::useMapAttributeSummary($image->getAttribute('usemap'));
            $summary['useMapRaw'] = $useMap['raw'];
            $summary['useMapName'] = $useMap['name'];
            $summary['useMapValid'] = $useMap['valid'];
            $summary += self::imageUseMapAssociationSummary($image, $useMap);
        }
        if ($image->hasAttribute('ismap')) {
            $summary += self::imageServerMapSummary($image);
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function imageLoadingReviewSummary(\DOMElement $image): array
    {
        $loadingRaw = self::attributeOrNull($image, 'loading');
        $loading = $loadingRaw === null ? null : self::imageLoadingState($loadingRaw);
        $decodingRaw = self::attributeOrNull($image, 'decoding');
        $decoding = $decodingRaw === null ? null : self::imageDecodingState($decodingRaw);
        $fetchPriorityRaw = self::attributeOrNull($image, 'fetchpriority');
        $fetchPriority = $fetchPriorityRaw === null ? null : self::fetchPriorityState($fetchPriorityRaw);
        $crossoriginRaw = self::attributeOrNull($image, 'crossorigin');
        $crossorigin = $crossoriginRaw === null ? null : self::htmlCorsSettingsAttributeState($crossoriginRaw);
        $referrerPolicyRaw = self::attributeOrNull($image, 'referrerpolicy');
        $referrerPolicy = $referrerPolicyRaw === null ? null : self::referrerPolicyState($referrerPolicyRaw);
        $issueCodes = [];

        if ($loadingRaw !== null && $loading === null) {
            $issueCodes[] = 'invalid-image-loading';
        }
        if ($decodingRaw !== null && $decoding === null) {
            $issueCodes[] = 'invalid-image-decoding';
        }
        if ($fetchPriorityRaw !== null && $fetchPriority === null) {
            $issueCodes[] = 'invalid-image-fetchpriority';
        }
        if ($crossoriginRaw !== null && $crossorigin === null) {
            $issueCodes[] = 'invalid-image-crossorigin';
        }
        if ($referrerPolicyRaw !== null && $referrerPolicy === null) {
            $issueCodes[] = 'invalid-image-referrerpolicy';
        }

        return [
            'imageLoadingReviewPolicy' => 'image-loading-metadata-review',
            'imageLoadingState' => $loading,
            'imageLoadingValid' => $loadingRaw === null ? null : $loading !== null,
            'imageDecodingState' => $decoding,
            'imageDecodingValid' => $decodingRaw === null ? null : $decoding !== null,
            'imageFetchPriority' => $fetchPriority,
            'imageFetchPriorityValid' => $fetchPriorityRaw === null ? null : $fetchPriority !== null,
            'imageCrossoriginState' => $crossorigin,
            'imageCrossoriginValid' => $crossoriginRaw === null ? null : $crossorigin !== null,
            'imageReferrerPolicy' => $referrerPolicy,
            'imageReferrerPolicyValid' => $referrerPolicyRaw === null ? null : $referrerPolicy !== null,
            'imageLoadingIssueCodes' => $issueCodes,
            'imageLoadingIssueCount' => count($issueCodes),
        ];
    }

    private static function imageLoadingState(string $value): ?string
    {
        $value = strtolower(trim($value));

        return in_array($value, ['eager', 'lazy'], true) ? $value : null;
    }

    private static function imageDecodingState(string $value): ?string
    {
        $value = strtolower(trim($value));

        return in_array($value, ['sync', 'async', 'auto'], true) ? $value : null;
    }

    /**
     * @return array<string, mixed>
     */
    private static function imageServerMapSummary(\DOMElement $image): array
    {
        $anchor = self::imageServerMapAnchor($image);
        $anchorHref = $anchor instanceof \DOMElement ? self::attributeOrNull($anchor, 'href') : null;
        $anchorHrefUsable = $anchorHref !== null && trim($anchorHref) !== '';
        $hasUseMap = $image->hasAttribute('usemap');
        $issues = [];

        if (!$anchor instanceof \DOMElement) {
            $issues[] = ['code' => 'server-image-map-without-anchor'];
        } elseif (!$anchorHrefUsable) {
            $issues[] = ['code' => 'server-image-map-anchor-missing-href'];
        }
        if ($hasUseMap) {
            $issues[] = [
                'code' => 'server-image-map-has-client-usemap',
                'useMapRaw' => $image->getAttribute('usemap'),
            ];
        }

        return [
            'serverImageMapReviewPolicy' => 'html-server-side-image-map-review',
            'serverImageMap' => true,
            'serverImageMapRaw' => $image->getAttribute('ismap'),
            'serverImageMapAnchorFound' => $anchor instanceof \DOMElement,
            'serverImageMapAnchorHref' => $anchorHref,
            'serverImageMapAnchorHrefUsable' => $anchorHrefUsable,
            'serverImageMapAnchorId' => $anchor instanceof \DOMElement ? self::attributeOrNull($anchor, 'id') : null,
            'serverImageMapAnchorText' => $anchor instanceof \DOMElement ? self::normalizedText($anchor) : null,
            'serverImageMapHasClientMap' => $hasUseMap,
            'serverImageMapUsable' => $anchorHrefUsable,
            'serverImageMapIssueCodes' => array_map(
                static fn (array $issue): string => (string) $issue['code'],
                $issues
            ),
            'serverImageMapIssues' => $issues,
        ];
    }

    private static function imageServerMapAnchor(\DOMElement $image): ?\DOMElement
    {
        for ($ancestor = $image->parentNode; $ancestor instanceof \DOMElement; $ancestor = $ancestor->parentNode) {
            if (self::htmlElementName($ancestor) === 'a') {
                return $ancestor;
            }
        }

        return null;
    }

    /**
     * @return array{imageMap:string, mapNameRaw:?string, mapName:?string, mapNameValid:bool, areaCount:int, areaHrefs:list<string>, areaLabels:list<string>, areas:list<array<string, mixed>>, defaultAreaCount:int, firstDefaultAreaIndex:?int, defaultAreaPrecedenceIssue:?array<string, mixed>, areaGeometryIssueCount:int, areaGeometryIssues:list<array<string, mixed>>}
     */
    private static function imageMapSummary(\DOMElement $map): array
    {
        $name = self::attributeOrNull($map, 'name');
        $normalizedName = $name === null ? null : trim($name);
        $nameValid = $normalizedName !== null && self::isHtmlReferenceToken($normalizedName);
        $areas = array_map(
            static fn (\DOMElement $area): array => self::hyperlinkSummary($area, 'area'),
            self::descendantHtmlElements($map, 'area'),
        );
        $referencingImages = $nameValid ? self::htmlImagesUsingMapName($map, $normalizedName) : [];
        $duplicateNameCount = $nameValid ? count(self::htmlImageMapsByName($map, $normalizedName)) : 0;
        $issues = [];
        if (!$nameValid) {
            $issues[] = ['code' => 'invalid-map-name', 'mapNameRaw' => $name];
        } else {
            if ($duplicateNameCount > 1) {
                $issues[] = ['code' => 'duplicate-map-name', 'mapName' => $normalizedName, 'count' => $duplicateNameCount];
            }
            if ($referencingImages === []) {
                $issues[] = ['code' => 'unreferenced-image-map', 'mapName' => $normalizedName];
            }
        }
        $areaGeometry = self::imageMapAreaGeometryDiagnostics($areas);

        return [
            'imageMap' => 'map',
            'mapNameRaw' => $name,
            'mapName' => $normalizedName,
            'mapNameValid' => $nameValid,
            'areaCount' => count($areas),
            'areaHrefs' => array_values(array_filter(
                array_map(static fn (array $area): ?string => $area['href'] ?? null, $areas),
                static fn (?string $href): bool => $href !== null && $href !== ''
            )),
            'areaLabels' => array_values(array_filter(
                array_map(static fn (array $area): ?string => $area['label'] ?? null, $areas),
                static fn (?string $label): bool => $label !== null && $label !== ''
            )),
            'areas' => $areas,
            'imageMapReferenceCount' => count($referencingImages),
            'imageMapReferenceSources' => array_values(array_filter(
                array_map(static fn (\DOMElement $image): ?string => self::attributeOrNull($image, 'src'), $referencingImages),
                static fn (?string $src): bool => $src !== null && $src !== ''
            )),
            'imageMapDuplicateNameCount' => $duplicateNameCount,
            'imageMapAssociationState' => $nameValid
                ? ($duplicateNameCount > 1 ? 'duplicate-map-name' : ($referencingImages === [] ? 'unreferenced' : 'referenced'))
                : 'invalid-map-name',
            'defaultAreaCount' => $areaGeometry['defaultAreaCount'],
            'firstDefaultAreaIndex' => $areaGeometry['firstDefaultAreaIndex'],
            'defaultAreaPrecedenceIssue' => $areaGeometry['defaultAreaPrecedenceIssue'],
            'areaGeometryIssueCount' => count($areaGeometry['areaGeometryIssues']),
            'areaGeometryIssues' => $areaGeometry['areaGeometryIssues'],
            'imageMapIssues' => $issues,
        ];
    }

    /**
     * @param list<array<string, mixed>> $areas
     * @return array{defaultAreaCount:int, firstDefaultAreaIndex:?int, defaultAreaPrecedenceIssue:?array<string, mixed>, areaGeometryIssues:list<array<string, mixed>>}
     */
    private static function imageMapAreaGeometryDiagnostics(array $areas): array
    {
        $issues = [];
        $defaultAreaIndexes = [];
        foreach ($areas as $index => $area) {
            foreach (($area['areaGeometryIssues'] ?? []) as $issue) {
                if (!is_array($issue)) {
                    continue;
                }
                $issues[] = ['areaIndex' => $index] + $issue;
            }

            if (($area['areaShape'] ?? null) === 'default') {
                $defaultAreaIndexes[] = $index;
            }
        }

        $firstDefaultAreaIndex = $defaultAreaIndexes[0] ?? null;
        $defaultAreaPrecedenceIssue = null;
        if ($firstDefaultAreaIndex !== null) {
            $coveredAreaIndexes = [];
            foreach ($areas as $index => $area) {
                if ($index > $firstDefaultAreaIndex && ($area['areaShape'] ?? null) !== 'default') {
                    $coveredAreaIndexes[] = $index;
                }
            }
            if ($coveredAreaIndexes !== []) {
                $defaultAreaPrecedenceIssue = [
                    'code' => 'default-area-precedes-specific-area',
                    'defaultAreaIndex' => $firstDefaultAreaIndex,
                    'coveredAreaIndexes' => $coveredAreaIndexes,
                ];
                $issues[] = $defaultAreaPrecedenceIssue;
            }
        }

        return [
            'defaultAreaCount' => count($defaultAreaIndexes),
            'firstDefaultAreaIndex' => $firstDefaultAreaIndex,
            'defaultAreaPrecedenceIssue' => $defaultAreaPrecedenceIssue,
            'areaGeometryIssues' => $issues,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function imageMapAreaGeometrySummary(\DOMElement $area): array
    {
        $shapeRaw = self::attributeOrNull($area, 'shape');
        $shapeToken = strtolower(trim($shapeRaw ?? ''));
        $shape = match ($shapeToken) {
            '', 'rect', 'rectangle' => 'rect',
            'circle', 'circ' => 'circle',
            'poly', 'polygon' => 'poly',
            'default' => 'default',
            default => null,
        };
        $coordsRaw = self::attributeOrNull($area, 'coords');
        $coords = self::imageMapAreaCoordinateList($coordsRaw);
        $issues = [];
        $coordsRequired = $shape !== 'default';

        if ($shape === null) {
            $issues[] = ['code' => 'invalid-area-shape', 'shapeRaw' => $shapeRaw];
        } elseif ($shape === 'default') {
            if ($coordsRaw !== null && trim($coordsRaw) !== '') {
                $issues[] = ['code' => 'default-area-coords-ignored'];
            }
        } else {
            if ($coordsRaw === null || trim($coordsRaw) === '') {
                $issues[] = ['code' => 'missing-area-coords', 'shape' => $shape];
            }
            foreach ($coords['invalidTokens'] as $token) {
                $issues[] = ['code' => 'invalid-area-coord-number', 'token' => $token];
            }
            if ($coords['invalidTokens'] === [] && $coordsRaw !== null && trim($coordsRaw) !== '') {
                $issues = array_merge($issues, self::imageMapAreaCoordinateShapeIssues($shape, $coords['numbers']));
            }
        }

        $invalidCodes = [
            'invalid-area-shape' => true,
            'missing-area-coords' => true,
            'invalid-area-coord-number' => true,
            'invalid-area-coord-count' => true,
            'invalid-rect-area-geometry' => true,
            'invalid-circle-area-radius' => true,
        ];

        return [
            'areaShapeRaw' => $shapeRaw,
            'areaShape' => $shape,
            'areaShapeValid' => $shape !== null,
            'coordsNumbers' => $coords['numbers'],
            'coordsValid' => $coords['invalidTokens'] === [],
            'coordsRequired' => $coordsRequired,
            'areaGeometryValid' => count(array_filter(
                $issues,
                static fn (array $issue): bool => isset($invalidCodes[(string) ($issue['code'] ?? '')])
            )) === 0,
            'areaGeometryIssues' => $issues,
        ];
    }

    /**
     * @param list<float> $numbers
     * @return list<array<string, mixed>>
     */
    private static function imageMapAreaCoordinateShapeIssues(string $shape, array $numbers): array
    {
        $count = count($numbers);
        if ($shape === 'rect') {
            if ($count !== 4) {
                return [[
                    'code' => 'invalid-area-coord-count',
                    'shape' => 'rect',
                    'expected' => 4,
                    'actual' => $count,
                ]];
            }
            if ($numbers[2] <= $numbers[0] || $numbers[3] <= $numbers[1]) {
                return [[
                    'code' => 'invalid-rect-area-geometry',
                    'coords' => $numbers,
                ]];
            }

            return [];
        }

        if ($shape === 'circle') {
            if ($count !== 3) {
                return [[
                    'code' => 'invalid-area-coord-count',
                    'shape' => 'circle',
                    'expected' => 3,
                    'actual' => $count,
                ]];
            }
            if ($numbers[2] <= 0.0) {
                return [[
                    'code' => 'invalid-circle-area-radius',
                    'radius' => $numbers[2],
                ]];
            }

            return [];
        }

        if ($count < 6 || $count % 2 !== 0) {
            return [[
                'code' => 'invalid-area-coord-count',
                'shape' => 'poly',
                'expected' => 'even-number-at-least-6',
                'actual' => $count,
            ]];
        }

        return [];
    }

    /**
     * @return array{numbers:list<float>, invalidTokens:list<string>}
     */
    private static function imageMapAreaCoordinateList(?string $coords): array
    {
        if ($coords === null || trim($coords) === '') {
            return ['numbers' => [], 'invalidTokens' => []];
        }

        $numbers = [];
        $invalidTokens = [];
        foreach (explode(',', $coords) as $token) {
            $trimmed = trim($token);
            if ($trimmed === '' || !is_numeric($trimmed)) {
                $invalidTokens[] = $trimmed;
                continue;
            }
            $number = (float) $trimmed;
            if (!is_finite($number)) {
                $invalidTokens[] = $trimmed;
                continue;
            }
            $numbers[] = $number;
        }

        return ['numbers' => $numbers, 'invalidTokens' => $invalidTokens];
    }

    /**
     * @param array{raw:string, name:?string, valid:bool} $useMap
     * @return array<string, mixed>
     */
    private static function imageUseMapAssociationSummary(\DOMElement $image, array $useMap): array
    {
        if ($useMap['valid'] !== true || $useMap['name'] === null) {
            return [
                'useMapAssociationState' => 'invalid-reference',
                'useMapTargetCount' => 0,
                'useMapAreaCount' => 0,
                'useMapAreaHrefs' => [],
                'useMapAreaLabels' => [],
                'useMapIssues' => [[
                    'code' => 'invalid-usemap-reference',
                    'useMapRaw' => $useMap['raw'],
                ]],
            ];
        }

        $maps = self::htmlImageMapsByName($image, $useMap['name']);
        $areaHrefs = [];
        $areaLabels = [];
        $areaCount = 0;
        foreach ($maps as $map) {
            $areas = self::descendantHtmlElements($map, 'area');
            $areaCount += count($areas);
            foreach ($areas as $area) {
                $href = self::attributeOrNull($area, 'href');
                if ($href !== null && $href !== '') {
                    $areaHrefs[] = $href;
                }
                $label = self::attributeOrNull($area, 'alt');
                if ($label !== null && $label !== '') {
                    $areaLabels[] = $label;
                }
            }
        }

        $issues = [];
        if ($maps === []) {
            $issues[] = ['code' => 'missing-image-map', 'mapName' => $useMap['name']];
        } elseif (count($maps) > 1) {
            $issues[] = ['code' => 'duplicate-map-name', 'mapName' => $useMap['name'], 'count' => count($maps)];
        }

        return [
            'useMapAssociationState' => $maps === []
                ? 'missing-map'
                : (count($maps) > 1 ? 'duplicate-map-name' : 'resolved'),
            'useMapTargetCount' => count($maps),
            'useMapAreaCount' => $areaCount,
            'useMapAreaHrefs' => $areaHrefs,
            'useMapAreaLabels' => $areaLabels,
            'useMapIssues' => $issues,
        ];
    }

    /**
     * @return array{raw:string, name:?string, valid:bool}
     */
    private static function useMapAttributeSummary(string $value): array
    {
        $raw = trim($value);
        $name = str_starts_with($raw, '#') ? substr($raw, 1) : $raw;

        return [
            'raw' => $value,
            'name' => $name === '' ? null : $name,
            'valid' => str_starts_with($raw, '#') && self::isHtmlReferenceToken($name),
        ];
    }

    /**
     * @return list<\DOMElement>
     */
    private static function htmlImageMapsByName(\DOMElement $context, string $name): array
    {
        $root = self::htmlFragmentScope($context);
        if (!$root instanceof \DOMElement) {
            return [];
        }

        $maps = [];
        foreach (self::descendantHtmlElements($root, 'map') as $map) {
            $mapName = self::attributeOrNull($map, 'name');
            $normalizedName = $mapName === null ? null : trim($mapName);
            if ($normalizedName !== null && $normalizedName === $name && self::isHtmlReferenceToken($normalizedName)) {
                $maps[] = $map;
            }
        }

        return $maps;
    }

    /**
     * @return list<\DOMElement>
     */
    private static function htmlImagesUsingMapName(\DOMElement $context, string $name): array
    {
        $root = self::htmlFragmentScope($context);
        if (!$root instanceof \DOMElement) {
            return [];
        }

        $images = [];
        foreach (self::descendantHtmlElements($root, 'img') as $image) {
            if (!$image->hasAttribute('usemap')) {
                continue;
            }
            $useMap = self::useMapAttributeSummary($image->getAttribute('usemap'));
            if ($useMap['valid'] === true && $useMap['name'] === $name) {
                $images[] = $image;
            }
        }

        return $images;
    }

    private static function htmlFragmentScope(\DOMElement $context): ?\DOMElement
    {
        $document = $context->ownerDocument;
        if (!$document instanceof \DOMDocument) {
            return null;
        }

        $fragmentRoot = self::fragmentRoot($document);
        if ($fragmentRoot instanceof \DOMElement && self::isDescendantOrSame($context, $fragmentRoot)) {
            return $fragmentRoot;
        }

        return $document->documentElement instanceof \DOMElement ? $document->documentElement : null;
    }

    /**
     * @return array<string, mixed>
     */
    private static function mediaElementSummary(\DOMElement $element, string $name): array
    {
        $summary = [
            'embeddedResource' => $name,
            'media' => $name,
            'src' => self::attributeOrNull($element, 'src'),
            'controls' => $element->hasAttribute('controls'),
            'autoplay' => $element->hasAttribute('autoplay'),
            'loop' => $element->hasAttribute('loop'),
            'muted' => $element->hasAttribute('muted'),
            'preload' => self::mediaPreload($element),
            'sources' => self::mediaSourceSummaries($element),
            'mediaSources' => array_map(
                static fn (\DOMElement $source): array => self::sourceElementSummary($source),
                self::mediaResourceElements($element, 'source'),
            ),
            'tracks' => self::mediaTrackSummaries($element),
        ];
        $summary += self::mediaLoadingPolicyReviewSummary($element);
        $summary += self::mediaTextTrackReviewSummary($element);
        $summary += self::mediaPolicyReviewSummary($element);
        $summary += self::mediaPreloadReviewSummary($element);

        if ($name === 'video') {
            $summary['poster'] = self::attributeOrNull($element, 'poster');
        }

        $fallbackText = self::normalizedTextWithoutMediaResourceChildren($element);
        if ($fallbackText !== '') {
            $summary['fallbackText'] = $fallbackText;
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function mediaLoadingPolicyReviewSummary(\DOMElement $element): array
    {
        $preloadRaw = self::attributeOrNull($element, 'preload');
        $preload = $preloadRaw === null ? null : self::mediaPreloadState($preloadRaw);
        $crossoriginRaw = self::attributeOrNull($element, 'crossorigin');
        $crossorigin = $crossoriginRaw === null
            ? null
            : self::htmlCorsSettingsAttributeState(self::htmlMetadataAttributeValue($crossoriginRaw));
        $widthRaw = self::attributeOrNull($element, 'width');
        $width = $widthRaw === null ? null : self::mediaDimensionState($widthRaw);
        $heightRaw = self::attributeOrNull($element, 'height');
        $height = $heightRaw === null ? null : self::mediaDimensionState($heightRaw);
        $issues = [];

        if ($preloadRaw !== null && $preload === null) {
            $issues[] = ['code' => 'invalid-media-preload', 'value' => $preloadRaw];
        }
        if ($crossoriginRaw !== null && $crossorigin === null) {
            $issues[] = ['code' => 'invalid-media-crossorigin', 'value' => $crossoriginRaw];
        }
        if ($widthRaw !== null && $width === null) {
            $issues[] = ['code' => 'invalid-media-width', 'value' => $widthRaw];
        }
        if ($heightRaw !== null && $height === null) {
            $issues[] = ['code' => 'invalid-media-height', 'value' => $heightRaw];
        }

        return [
            'mediaLoadingPolicyReview' => 'media-loading-policy-metadata-review',
            'mediaPreloadRaw' => $preloadRaw,
            'mediaPreloadState' => $preload,
            'mediaPreloadValid' => $preloadRaw === null ? null : $preload !== null,
            'mediaCrossoriginRaw' => $crossoriginRaw,
            'mediaCrossoriginState' => $crossorigin,
            'mediaCrossoriginValid' => $crossoriginRaw === null ? null : $crossorigin !== null,
            'mediaWidthRaw' => $widthRaw,
            'mediaWidth' => $width,
            'mediaWidthValid' => $widthRaw === null ? null : $width !== null,
            'mediaHeightRaw' => $heightRaw,
            'mediaHeight' => $height,
            'mediaHeightValid' => $heightRaw === null ? null : $height !== null,
            'mediaLoadingIssues' => $issues,
            'mediaLoadingIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ))),
            'mediaLoadingIssueCount' => count($issues),
            'mediaLoadingPolicyValid' => $issues === [],
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function mediaPolicyReviewSummary(\DOMElement $element): array
    {
        $controlsListRaw = self::attributeOrNull($element, 'controlslist');
        $controlsList = $controlsListRaw === null
            ? [
                'controlsListTokens' => [],
                'controlsListValidTokens' => [],
                'invalidControlsListTokens' => [],
                'duplicateControlsListTokens' => [],
                'controlsListTokenCounts' => [],
                'controlsListTokenCount' => 0,
                'controlsListValidTokenCount' => 0,
                'controlsListNormalized' => null,
                'controlsListValid' => null,
            ]
            : self::mediaControlsListSummary($controlsListRaw);
        $issueCodes = [];

        if (($controlsList['controlsListValid'] ?? null) === false) {
            $issueCodes[] = 'invalid-media-controlslist-token';
        }
        if (($controlsList['duplicateControlsListTokens'] ?? []) !== []) {
            $issueCodes[] = 'duplicate-media-controlslist-token';
        }
        $mediaPlaybackIssues = [];
        foreach ($controlsList['invalidControlsListTokens'] as $token) {
            $mediaPlaybackIssues[] = ['code' => 'invalid-media-controlslist-token', 'token' => $token];
        }
        foreach ($controlsList['duplicateControlsListTokens'] as $token) {
            $mediaPlaybackIssues[] = [
                'code' => 'duplicate-media-controlslist-token',
                'token' => $token,
                'count' => $controlsList['controlsListTokenCounts'][$token] ?? 0,
            ];
        }
        if ($controlsListRaw !== null && $controlsList['controlsListTokens'] === []) {
            $mediaPlaybackIssues[] = ['code' => 'empty-media-controlslist'];
        }
        $mediaPlaybackIssueCodes = array_values(array_unique(array_map(
            static fn (array $issue): string => (string) ($issue['code'] ?? ''),
            $mediaPlaybackIssues
        )));

        return [
            'mediaPolicyReview' => 'html-media-controls-policy-review',
            'mediaPlaybackPolicyReview' => 'media-playback-policy-metadata-review',
            'playsInline' => $element->hasAttribute('playsinline'),
            'disablePictureInPicture' => $element->hasAttribute('disablepictureinpicture'),
            'disableRemotePlayback' => $element->hasAttribute('disableremoteplayback'),
            'controlsListRaw' => $controlsListRaw,
            'mediaControlsListRaw' => $controlsListRaw,
            'mediaControlsListRawTokens' => $controlsList['controlsListTokens'],
            'mediaControlsListTokens' => $controlsList['controlsListValidTokens'],
            'mediaControlsListTokenCounts' => $controlsList['controlsListTokenCounts'],
            'duplicateMediaControlsListTokens' => $controlsList['duplicateControlsListTokens'],
            'invalidMediaControlsListTokens' => $controlsList['invalidControlsListTokens'],
            'mediaControlsListValid' => $controlsList['controlsListValid'],
            'mediaDisablePictureInPicture' => $element->hasAttribute('disablepictureinpicture'),
            'mediaDisableRemotePlayback' => $element->hasAttribute('disableremoteplayback'),
            'mediaPlaysInline' => $element->hasAttribute('playsinline'),
            'mediaPolicyIssueCodes' => $issueCodes,
            'mediaPolicyIssueCount' => count($issueCodes),
            'mediaPlaybackIssueCodes' => $mediaPlaybackIssueCodes,
            'mediaPlaybackIssueCount' => count($mediaPlaybackIssues),
            'mediaPlaybackIssues' => $mediaPlaybackIssues,
        ] + $controlsList;
    }

    /**
     * @return array{controlsListTokens:list<string>, controlsListValidTokens:list<string>, invalidControlsListTokens:list<string>, duplicateControlsListTokens:list<string>, controlsListTokenCounts:array<string, int>, controlsListTokenCount:int, controlsListValidTokenCount:int, controlsListNormalized:?string, controlsListValid:bool}
     */
    private static function mediaControlsListSummary(string $value): array
    {
        $tokens = array_map(
            static fn (string $token): string => strtolower(trim($token)),
            self::spaceSeparatedTokens(str_replace("\0", '', $value))
        );
        $valid = [];
        $invalid = [];
        $duplicates = [];
        $counts = [];

        foreach ($tokens as $token) {
            if ($token === '') {
                continue;
            }

            if (!isset(self::HTML_MEDIA_CONTROLSLIST_TOKENS[$token])) {
                if (!in_array($token, $invalid, true)) {
                    $invalid[] = $token;
                }
                continue;
            }

            $counts[$token] = ($counts[$token] ?? 0) + 1;
            if ($counts[$token] > 1) {
                if (!in_array($token, $duplicates, true)) {
                    $duplicates[] = $token;
                }
                continue;
            }

            $valid[] = $token;
        }

        return [
            'controlsListTokens' => $tokens,
            'controlsListValidTokens' => $valid,
            'invalidControlsListTokens' => $invalid,
            'duplicateControlsListTokens' => $duplicates,
            'controlsListTokenCounts' => $counts,
            'controlsListTokenCount' => count($tokens),
            'controlsListValidTokenCount' => count($valid),
            'controlsListNormalized' => $valid === [] ? null : implode(' ', $valid),
            'controlsListValid' => $tokens !== [] && $invalid === [],
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function sourceElementSummary(\DOMElement $source): array
    {
        $srcset = self::attributeOrNull($source, 'srcset');

        return [
            'src' => self::attributeOrNull($source, 'src'),
            'srcset' => $srcset,
            'srcsetCandidates' => self::srcsetCandidateSummaries($srcset),
            'type' => self::attributeOrNull($source, 'type'),
            'media' => self::attributeOrNull($source, 'media'),
            'sizes' => self::attributeOrNull($source, 'sizes'),
        ] + self::srcsetResourceReviewSummary($srcset, 'srcset');
    }

    /**
     * @return array{src:?string, kind:string, srclang:?string, label:?string, default:bool}
     */
    private static function trackElementSummary(\DOMElement $track): array
    {
        return [
            'src' => self::attributeOrNull($track, 'src'),
            'kind' => self::trackKind($track),
            'srclang' => self::attributeOrNull($track, 'srclang'),
            'label' => self::attributeOrNull($track, 'label'),
            'default' => $track->hasAttribute('default'),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function mediaTextTrackReviewSummary(\DOMElement $media): array
    {
        $tracks = [];
        $kindCounts = [];
        $languages = [];
        $subtitleLanguages = [];
        $defaultLabels = [];
        $issues = [];
        $defaultCount = 0;
        $invalidKindCount = 0;
        $invalidLanguageCount = 0;
        $missingLanguageCount = 0;

        foreach (self::mediaResourceElements($media, 'track') as $index => $track) {
            $summary = self::textTrackReviewSummary($track, $index);
            $tracks[] = $summary;

            $kind = (string) $summary['kind'];
            $kindCounts[$kind] = ($kindCounts[$kind] ?? 0) + 1;

            if (($summary['default'] ?? false) === true) {
                ++$defaultCount;
                $label = $summary['label'] ?? null;
                if ($label !== null && $label !== '') {
                    $defaultLabels[] = (string) $label;
                }
            }

            $language = $summary['srclang'] ?? null;
            if ($language !== null) {
                if (!in_array($language, $languages, true)) {
                    $languages[] = (string) $language;
                }
                if (($summary['languageRequired'] ?? false) === true && !in_array($language, $subtitleLanguages, true)) {
                    $subtitleLanguages[] = (string) $language;
                }
            }

            if (($summary['kindValid'] ?? true) !== true) {
                ++$invalidKindCount;
                $issues[] = [
                    'code' => 'invalid-text-track-kind',
                    'trackIndex' => $index,
                    'kindRaw' => $summary['kindRaw'],
                    'normalizedKind' => $kind,
                ];
            }

            if (($summary['srclangRaw'] ?? null) !== null && ($summary['srclangValid'] ?? false) !== true) {
                ++$invalidLanguageCount;
                $issues[] = [
                    'code' => 'invalid-text-track-language',
                    'trackIndex' => $index,
                    'srclangRaw' => $summary['srclangRaw'],
                ];
            }

            if (($summary['languageMissing'] ?? false) === true) {
                ++$missingLanguageCount;
                $issues[] = [
                    'code' => 'missing-text-track-language',
                    'trackIndex' => $index,
                    'kind' => $kind,
                    'label' => $summary['label'],
                    'src' => $summary['src'],
                ];
            }
        }

        if ($tracks === []) {
            return [];
        }

        ksort($kindCounts);
        if ($defaultCount > 1) {
            array_unshift($issues, [
                'code' => 'multiple-default-tracks',
                'count' => $defaultCount,
            ]);
        }

        return [
            'textTrackCount' => count($tracks),
            'textTracks' => $tracks,
            'textTrackKinds' => $kindCounts,
            'textTrackLanguages' => $languages,
            'subtitleTextTrackLanguages' => $subtitleLanguages,
            'defaultTextTrackCount' => $defaultCount,
            'defaultTextTrackLabels' => $defaultLabels,
            'defaultTextTrackConflict' => $defaultCount > 1,
            'invalidTextTrackKindCount' => $invalidKindCount,
            'invalidTextTrackLanguageCount' => $invalidLanguageCount,
            'missingSubtitleLanguageCount' => $missingLanguageCount,
            'textTrackIssues' => $issues,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function textTrackReviewSummary(\DOMElement $track, int $index): array
    {
        $kindRaw = self::attributeOrNull($track, 'kind');
        $kind = self::trackKind($track);
        $srclangRaw = self::attributeOrNull($track, 'srclang');
        $srclang = $srclangRaw === null ? null : self::normalizeHtmlLanguageTag($srclangRaw);
        $languageRequired = in_array($kind, ['captions', 'subtitles'], true);

        return [
            'index' => $index,
            'src' => self::attributeOrNull($track, 'src'),
            'kindRaw' => $kindRaw,
            'kind' => $kind,
            'kindValid' => $kindRaw === null || self::isHtmlTrackKind(strtolower(trim($kindRaw))),
            'srclangRaw' => $srclangRaw,
            'srclang' => $srclang,
            'srclangValid' => $srclangRaw !== null && $srclang !== null,
            'label' => self::attributeOrNull($track, 'label'),
            'default' => $track->hasAttribute('default'),
            'languageRequired' => $languageRequired,
            'languageMissing' => $languageRequired && $srclang === null,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function iframeSummary(\DOMElement $iframe): array
    {
        $srcdoc = self::attributeOrNull($iframe, 'srcdoc');
        $summary = [
            'embeddedResource' => 'iframe',
            'src' => self::attributeOrNull($iframe, 'src'),
            'srcdoc' => $srcdoc,
            'nameAttribute' => self::attributeOrNull($iframe, 'name'),
            'width' => self::attributeOrNull($iframe, 'width'),
            'height' => self::attributeOrNull($iframe, 'height'),
            'loading' => self::attributeOrNull($iframe, 'loading'),
            'referrerpolicy' => self::attributeOrNull($iframe, 'referrerpolicy'),
            'allow' => self::attributeOrNull($iframe, 'allow'),
            'csp' => self::attributeOrNull($iframe, 'csp'),
            'credentialless' => $iframe->hasAttribute('credentialless'),
            'credentiallessRaw' => self::attributeOrNull($iframe, 'credentialless'),
            'sandboxTokens' => $iframe->hasAttribute('sandbox') ? self::spaceSeparatedTokens($iframe->getAttribute('sandbox')) : [],
            'allowFullscreen' => $iframe->hasAttribute('allowfullscreen'),
        ];

        $fallbackText = self::normalizedText($iframe);
        if ($fallbackText !== '') {
            $summary['fallbackText'] = $fallbackText;
        }

        if ($srcdoc !== null) {
            $summary += self::iframeSrcdocReviewSummary($srcdoc);
        }

        $summary += self::iframePolicyReviewSummary($iframe);

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function iframePolicyReviewSummary(\DOMElement $iframe): array
    {
        $summary = [
            'iframePolicyReview' => 'iframe-policy-metadata-review',
            'iframePolicyIssueCodes' => [],
        ];

        if ($iframe->hasAttribute('sandbox')) {
            $sandbox = self::iframeSandboxPolicySummary($iframe->getAttribute('sandbox'));
            $summary += $sandbox;
            if (($sandbox['invalidSandboxTokens'] ?? []) !== []) {
                $summary['iframePolicyIssueCodes'][] = 'invalid-iframe-sandbox-token';
            }
            if (($sandbox['duplicateSandboxTokens'] ?? []) !== []) {
                $summary['iframePolicyIssueCodes'][] = 'duplicate-iframe-sandbox-token';
            }
            if (($sandbox['sandboxAllowsScriptsAndSameOrigin'] ?? false) === true) {
                $summary['iframePolicyIssueCodes'][] = 'iframe-sandbox-allows-scripts-same-origin';
            }
        }

        if ($iframe->hasAttribute('allow')) {
            $allow = self::iframeAllowPolicySummary($iframe->getAttribute('allow'));
            $summary += $allow;
            if (($allow['invalidAllowDirectiveCount'] ?? 0) > 0) {
                $summary['iframePolicyIssueCodes'][] = 'invalid-iframe-allow-directive';
            }
        }

        if ($iframe->hasAttribute('referrerpolicy')) {
            $referrerPolicy = self::iframeReferrerPolicySummary($iframe->getAttribute('referrerpolicy'));
            $summary += $referrerPolicy;
            if (($referrerPolicy['referrerPolicyValid'] ?? true) !== true) {
                $summary['iframePolicyIssueCodes'][] = 'invalid-iframe-referrer-policy';
            }
        }

        if ($iframe->hasAttribute('loading')) {
            $loading = self::iframeLoadingPolicySummary($iframe->getAttribute('loading'));
            $summary += $loading;
            if (($loading['loadingValid'] ?? true) !== true) {
                $summary['iframePolicyIssueCodes'][] = 'invalid-iframe-loading-state';
            }
        }

        if ($iframe->hasAttribute('credentialless')) {
            $summary += self::iframeCredentiallessPolicySummary($iframe->getAttribute('credentialless'));
        }

        if ($iframe->hasAttribute('csp')) {
            $csp = self::iframeContentSecurityPolicySummary($iframe->getAttribute('csp'));
            $summary += $csp;
            if (($csp['iframeCspValid'] ?? true) !== true) {
                $summary['iframePolicyIssueCodes'][] = 'invalid-iframe-csp-policy';
            }
        }

        $summary['allowFullscreen'] = $iframe->hasAttribute('allowfullscreen');

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function iframeCredentiallessPolicySummary(string $value): array
    {
        return [
            'iframeCredentiallessReviewPolicy' => 'iframe-credentialless-attribute-review',
            'iframeCredentiallessRaw' => $value,
            'iframeCredentialless' => true,
            'iframeCredentialMode' => 'credentialless',
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function iframeContentSecurityPolicySummary(string $value): array
    {
        $csp = self::metaContentSecurityPolicySummary($value, 'iframe-csp');
        $issueCodes = array_values(array_map(
            static fn (string $code): string => $code === 'missing-meta-csp-content'
                ? 'empty-iframe-csp'
                : $code,
            $csp['cspIssueCodes']
        ));

        return $csp + [
            'iframeCspReviewPolicy' => 'iframe-csp-attribute-review',
            'iframeCspRaw' => $value,
            'iframeCspByteLength' => strlen($value),
            'iframeCspSha256' => hash('sha256', $value),
            'iframeCspIssueCodes' => $issueCodes,
            'iframeCspValid' => $issueCodes === [],
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function iframeSandboxPolicySummary(string $value): array
    {
        $tokens = array_map(
            static fn (string $token): string => strtolower(trim($token)),
            self::spaceSeparatedTokens($value)
        );
        $valid = [];
        $invalid = [];
        $duplicates = [];
        $seen = [];

        foreach ($tokens as $token) {
            if ($token === '') {
                continue;
            }

            if (!isset(self::HTML_IFRAME_SANDBOX_TOKENS[$token])) {
                $invalid[] = $token;
                continue;
            }

            if (isset($seen[$token])) {
                if (!in_array($token, $duplicates, true)) {
                    $duplicates[] = $token;
                }
                continue;
            }

            $seen[$token] = true;
            $valid[] = $token;
        }

        return [
            'sandboxRaw' => $value,
            'sandboxTokens' => $tokens,
            'sandboxValidTokens' => $valid,
            'invalidSandboxTokens' => $invalid,
            'duplicateSandboxTokens' => $duplicates,
            'sandboxTokenCount' => count($tokens),
            'sandboxValidTokenCount' => count($valid),
            'sandboxAllTokensValid' => $invalid === [],
            'sandboxAllowsScripts' => in_array('allow-scripts', $valid, true),
            'sandboxAllowsSameOrigin' => in_array('allow-same-origin', $valid, true),
            'sandboxAllowsScriptsAndSameOrigin' => in_array('allow-scripts', $valid, true)
                && in_array('allow-same-origin', $valid, true),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function iframeAllowPolicySummary(string $value): array
    {
        $directives = [];
        $features = [];
        $invalid = [];

        foreach (explode(';', $value) as $rawDirective) {
            $raw = trim($rawDirective);
            if ($raw === '') {
                continue;
            }

            $tokens = self::spaceSeparatedTokens($raw);
            $featureRaw = $tokens[0] ?? null;
            $feature = is_string($featureRaw) ? strtolower($featureRaw) : null;
            $allowList = array_slice($tokens, 1);
            $featureValid = $feature !== null && self::isIframeAllowFeatureToken($feature);
            $allowListValid = true;
            foreach ($allowList as $allowListToken) {
                if (!self::isIframeAllowListToken($allowListToken)) {
                    $allowListValid = false;
                    break;
                }
            }
            $valid = $featureValid && $allowListValid;
            if (!$valid) {
                $invalid[] = $raw;
            } elseif (!in_array($feature, $features, true)) {
                $features[] = $feature;
            }

            $directives[] = [
                'raw' => $raw,
                'featureRaw' => $featureRaw,
                'feature' => $featureValid ? $feature : null,
                'allowList' => $allowList,
                'valid' => $valid,
            ];
        }

        return [
            'allowRaw' => $value,
            'allowDirectiveCount' => count($directives),
            'allowDirectives' => $directives,
            'allowFeatures' => $features,
            'invalidAllowDirectiveCount' => count($invalid),
            'invalidAllowDirectives' => $invalid,
            'allowPolicyValid' => $directives !== [] && $invalid === [],
        ];
    }

    private static function isIframeAllowFeatureToken(string $token): bool
    {
        return preg_match('/^[a-z][a-z0-9-]*$/', $token) === 1;
    }

    private static function isIframeAllowListToken(string $token): bool
    {
        if ($token === '*' || in_array($token, ["'self'", "'src'", "'none'"], true)) {
            return true;
        }

        return $token !== '' && preg_match('/[\s<>"`\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/u', $token) === 0;
    }

    /**
     * @return array<string, mixed>
     */
    private static function iframeReferrerPolicySummary(string $value): array
    {
        $policy = strtolower(trim($value));

        return [
            'referrerPolicyRaw' => $value,
            'referrerPolicy' => isset(self::HTML_REFERRER_POLICIES[$policy]) ? $policy : null,
            'referrerPolicyValid' => isset(self::HTML_REFERRER_POLICIES[$policy]),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function iframeLoadingPolicySummary(string $value): array
    {
        $loading = strtolower(trim($value));
        $valid = in_array($loading, ['eager', 'lazy'], true);

        return [
            'loadingRaw' => $value,
            'loadingState' => $valid ? $loading : null,
            'loadingValid' => $valid,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function iframeSrcdocReviewSummary(string $srcdoc): array
    {
        $summary = [
            'srcdocReviewPolicy' => 'iframe-srcdoc-inert-fragment-review',
            'srcdocByteLength' => strlen($srcdoc),
            'srcdocSha256' => hash('sha256', $srcdoc),
            'srcdocParsed' => false,
            'srcdocDiagnostics' => [],
        ];

        if (strlen($srcdoc) > self::IFRAME_SRCDOC_REVIEW_MAX_BYTES) {
            $summary['srcdocDiagnostics'] = ['srcdoc-review-limit-exceeded'];

            return $summary;
        }

        try {
            $fragment = self::loadHtmlFragment($srcdoc, 'iframe srcdoc fragment');
        } catch (\InvalidArgumentException $exception) {
            $summary['srcdocDiagnostics'] = ['srcdoc-unsafe-or-unparseable'];
            $summary['srcdocError'] = $exception->getMessage();

            return $summary;
        }

        $root = self::requireFragmentRoot($fragment);
        $text = self::normalizedText($root);
        $topLevelElementNames = [];
        foreach ($root->childNodes as $child) {
            if ($child instanceof \DOMElement) {
                $topLevelElementNames[] = self::htmlElementName($child);
            }
        }

        $summary['srcdocParsed'] = true;
        $summary['srcdocTopLevelElementNames'] = $topLevelElementNames;
        $summary['srcdocTopLevelElementCount'] = count($topLevelElementNames);
        $summary['srcdocTextLength'] = strlen($text);
        $summary['srcdocTextSha256'] = hash('sha256', $text);
        if ($text !== '') {
            $summary['srcdocText'] = $text;
        }
        $summary['srcdocLinkHrefs'] = self::inertHtmlFragmentAttributeValues($root, ['a', 'area'], 'href');
        $summary['srcdocImageSources'] = self::inertHtmlFragmentAttributeValues($root, ['img'], 'src');
        $forms = self::descendantHtmlElements($root, 'form');
        $summary['srcdocFormCount'] = count($forms);
        $summary['srcdocFormActions'] = array_values(array_filter(
            array_map(static fn (\DOMElement $form): ?string => self::attributeOrNull($form, 'action'), $forms),
            static fn (?string $action): bool => $action !== null && $action !== ''
        ));
        $summary['srcdocActiveElementNames'] = self::inertHtmlFragmentDescendantNames($root, ['script' => true, 'style' => true]);
        $summary['srcdocEmbeddedElementNames'] = self::inertHtmlFragmentDescendantNames($root, [
            'audio' => true,
            'canvas' => true,
            'embed' => true,
            'iframe' => true,
            'object' => true,
            'video' => true,
        ]);

        return $summary;
    }

    /**
     * @param list<string> $names
     * @return list<string>
     */
    private static function inertHtmlFragmentAttributeValues(\DOMElement $root, array $names, string $attribute): array
    {
        $values = [];
        foreach ($names as $name) {
            foreach (self::descendantHtmlElements($root, $name) as $element) {
                $value = self::attributeOrNull($element, $attribute);
                if ($value !== null && $value !== '') {
                    $values[] = $value;
                }
            }
        }

        return $values;
    }

    /**
     * @param array<string, true> $names
     * @return list<string>
     */
    private static function inertHtmlFragmentDescendantNames(\DOMElement $root, array $names): array
    {
        $elementNames = [];
        foreach ($root->getElementsByTagName('*') as $element) {
            if (!$element instanceof \DOMElement) {
                continue;
            }
            $name = strtolower(self::htmlElementName($element));
            if (isset($names[$name])) {
                $elementNames[] = $name;
            }
        }

        return $elementNames;
    }

    /**
     * @return array<string, mixed>
     */
    private static function embedSummary(\DOMElement $embed): array
    {
        return [
            'embeddedResource' => 'embed',
            'src' => self::attributeOrNull($embed, 'src'),
            'mimeType' => self::attributeOrNull($embed, 'type'),
            'width' => self::attributeOrNull($embed, 'width'),
            'height' => self::attributeOrNull($embed, 'height'),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function objectSummary(\DOMElement $object): array
    {
        $fallbackText = self::normalizedText($object);
        $paramDetails = self::objectParamSummaries($object);
        $summary = [
            'embeddedResource' => 'object',
            'data' => self::attributeOrNull($object, 'data'),
            'mimeType' => self::attributeOrNull($object, 'type'),
            'nameAttribute' => self::attributeOrNull($object, 'name'),
            'width' => self::attributeOrNull($object, 'width'),
            'height' => self::attributeOrNull($object, 'height'),
            'typeMustMatch' => $object->hasAttribute('typemustmatch'),
            'params' => self::legacyObjectParamSummaries($paramDetails),
            'paramDetails' => $paramDetails,
        ];
        $summary += self::formOwnerSummary($object);
        if ($object->hasAttribute('usemap')) {
            $useMap = self::useMapAttributeSummary($object->getAttribute('usemap'));
            $summary['useMapRaw'] = $useMap['raw'];
            $summary['useMapName'] = $useMap['name'];
            $summary['useMapValid'] = $useMap['valid'];
        }
        $summary += self::objectParamReviewSummary($paramDetails);

        if ($fallbackText !== '') {
            $summary['fallbackText'] = $fallbackText;
        }

        return $summary;
    }

    /**
     * @return array<string, mixed>
     */
    private static function paramElementSummary(\DOMElement $param): array
    {
        $nameRaw = self::attributeOrNull($param, 'name');
        $name = self::normalizedNonEmptyAttribute($nameRaw);
        $valueTypeRaw = self::attributeOrNull($param, 'valuetype');
        $valueType = self::paramValueTypeSummary($valueTypeRaw);

        return [
            'embeddedResource' => 'param',
            'paramName' => $nameRaw,
            'paramNameRaw' => $nameRaw,
            'paramNameNormalized' => $name,
            'paramNameKey' => $name === null ? null : strtolower($name),
            'paramNameValid' => $name !== null && self::isSafeHtmlParamName($name),
            'value' => self::attributeOrNull($param, 'value'),
            'valueRaw' => self::attributeOrNull($param, 'value'),
            'valueType' => $valueTypeRaw,
            'valueTypeRaw' => $valueTypeRaw,
            'valueTypeState' => $valueType['state'],
            'valueTypeExplicit' => $valueType['explicit'],
            'valueTypeValid' => $valueType['valid'],
            'mimeType' => self::attributeOrNull($param, 'type'),
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function objectParamSummaries(\DOMElement $object): array
    {
        $params = [];
        foreach ($object->childNodes as $child) {
            if (!$child instanceof \DOMElement || strtolower(self::htmlElementName($child)) !== 'param') {
                continue;
            }

            $summary = self::paramElementSummary($child);
            unset($summary['embeddedResource']);
            $params[] = $summary;
        }

        return $params;
    }

    /**
     * @param list<array<string, mixed>> $paramDetails
     * @return list<array{paramName:?string, value:?string, valueType:?string, mimeType:?string}>
     */
    private static function legacyObjectParamSummaries(array $paramDetails): array
    {
        return array_map(
            static fn (array $summary): array => [
                'paramName' => $summary['paramName'],
                'value' => $summary['value'],
                'valueType' => $summary['valueType'],
                'mimeType' => $summary['mimeType'],
            ],
            $paramDetails
        );
    }

    /**
     * @param list<array<string, mixed>> $params
     * @return array<string, mixed>
     */
    private static function objectParamReviewSummary(array $params): array
    {
        $names = [];
        $firstNames = [];
        $nameCounts = [];
        $duplicateNames = [];
        $refParams = [];
        $objectReferenceParams = [];
        $issues = [];
        $unnamedCount = 0;
        $invalidNameCount = 0;
        $invalidValueTypeCount = 0;

        foreach ($params as $index => $param) {
            $key = $param['paramNameKey'] ?? null;
            $name = $param['paramNameNormalized'] ?? null;
            if (!is_string($key) || !is_string($name)) {
                ++$unnamedCount;
                $issues[] = [
                    'code' => 'missing-param-name',
                    'paramIndex' => $index,
                    'value' => $param['value'] ?? null,
                ];
            } elseif (($param['paramNameValid'] ?? false) !== true) {
                ++$invalidNameCount;
                $issues[] = [
                    'code' => 'invalid-param-name',
                    'paramIndex' => $index,
                    'paramNameRaw' => $param['paramNameRaw'] ?? null,
                ];
            } else {
                if (!isset($nameCounts[$key])) {
                    $names[] = $name;
                    $firstNames[$key] = $name;
                    $nameCounts[$key] = 0;
                }
                ++$nameCounts[$key];
                if ($nameCounts[$key] === 2) {
                    $duplicateNames[] = $firstNames[$key];
                    $issues[] = [
                        'code' => 'duplicate-param-name',
                        'paramName' => $firstNames[$key],
                        'paramNameKey' => $key,
                    ];
                }
            }

            if (($param['valueTypeValid'] ?? true) !== true) {
                ++$invalidValueTypeCount;
                $issues[] = [
                    'code' => 'invalid-param-valuetype',
                    'paramIndex' => $index,
                    'paramName' => $name,
                    'valueTypeRaw' => $param['valueTypeRaw'] ?? null,
                ];
            }

            $record = self::objectParamReferenceRecord($param, $index);
            if (($param['valueTypeState'] ?? 'data') === 'ref') {
                $refParams[] = $record;
            }
            if (($param['valueTypeState'] ?? 'data') === 'object') {
                $objectReferenceParams[] = $record;
            }
        }

        return [
            'paramCount' => count($params),
            'paramNames' => $names,
            'duplicateParamNames' => $duplicateNames,
            'unnamedParamCount' => $unnamedCount,
            'invalidParamNameCount' => $invalidNameCount,
            'invalidParamValueTypeCount' => $invalidValueTypeCount,
            'refParamCount' => count($refParams),
            'refParams' => $refParams,
            'objectReferenceParamCount' => count($objectReferenceParams),
            'objectReferenceParams' => $objectReferenceParams,
            'paramIssues' => $issues,
        ];
    }

    /**
     * @param array<string, mixed> $param
     * @return array{index:int, paramName:?string, value:?string, mimeType:?string, valueType:string}
     */
    private static function objectParamReferenceRecord(array $param, int $index): array
    {
        return [
            'index' => $index,
            'paramName' => is_string($param['paramNameNormalized'] ?? null) ? $param['paramNameNormalized'] : null,
            'value' => is_string($param['value'] ?? null) ? $param['value'] : null,
            'mimeType' => is_string($param['mimeType'] ?? null) ? $param['mimeType'] : null,
            'valueType' => is_string($param['valueTypeState'] ?? null) ? $param['valueTypeState'] : 'data',
        ];
    }

    /**
     * @return array{state:string, explicit:bool, valid:bool}
     */
    private static function paramValueTypeSummary(?string $valueType): array
    {
        if ($valueType === null || trim($valueType) === '') {
            return ['state' => 'data', 'explicit' => false, 'valid' => true];
        }

        $normalized = strtolower(trim($valueType));
        if (in_array($normalized, ['data', 'ref', 'object'], true)) {
            return ['state' => $normalized, 'explicit' => true, 'valid' => true];
        }

        return ['state' => 'data', 'explicit' => true, 'valid' => false];
    }

    private static function isSafeHtmlParamName(string $name): bool
    {
        return $name !== ''
            && strlen($name) <= 128
            && preg_match('/[\x00-\x1F\x7F<>"`]/', $name) !== 1;
    }

    /**
     * @return list<array{url:string, descriptor:string, descriptors:list<string>, raw:string}>
     */
    private static function srcsetCandidateSummaries(?string $srcset): array
    {
        if ($srcset === null || trim($srcset) === '') {
            return [];
        }

        $candidates = [];
        foreach (self::splitSrcsetCandidates($srcset) as $candidate) {
            $raw = trim($candidate);
            if ($raw === '') {
                continue;
            }

            $parts = preg_split('/\s+/', $raw, -1, PREG_SPLIT_NO_EMPTY);
            if (!is_array($parts) || $parts === []) {
                continue;
            }

            $url = array_shift($parts);
            $descriptors = array_values($parts);
            $candidates[] = [
                'url' => (string) $url,
                'descriptor' => implode(' ', $descriptors),
                'descriptors' => $descriptors,
                'raw' => $raw,
            ];
        }

        return $candidates;
    }

    /**
     * @return array<string, mixed>
     */
    private static function srcsetResourceReviewSummary(?string $srcset, string $keyPrefix): array
    {
        if ($srcset === null) {
            return [];
        }

        $candidates = self::srcsetCandidateSummaries($srcset);
        $records = [];
        $issues = [];
        $unsafeUrls = [];
        $remoteUrls = [];
        $descriptorKinds = [];
        $descriptorCounts = [];
        $duplicateDescriptors = [];
        $invalidDescriptors = [];

        foreach ($candidates as $index => $candidate) {
            $url = $candidate['url'];
            $urlSummary = self::hyperlinkUrlReviewSummary($url);
            $descriptor = self::srcsetDescriptorReviewSummary($candidate['descriptors']);
            $descriptorKind = $descriptor['descriptorKind'];
            $descriptorNormalized = $descriptor['descriptorNormalized'];

            if ($descriptorKind !== 'implicit') {
                $descriptorKinds[$descriptorKind] = true;
            }
            if ($descriptorNormalized !== null) {
                $descriptorCounts[$descriptorNormalized] = ($descriptorCounts[$descriptorNormalized] ?? 0) + 1;
                if ($descriptorCounts[$descriptorNormalized] > 1 && !in_array($descriptorNormalized, $duplicateDescriptors, true)) {
                    $duplicateDescriptors[] = $descriptorNormalized;
                }
            }

            if ($urlSummary['unsafe']) {
                $unsafeUrls[] = $url;
                $issues[] = [
                    'code' => 'unsafe-srcset-url',
                    'candidateIndex' => $index,
                    'url' => $url,
                    'scheme' => $urlSummary['scheme'],
                ];
            }
            if ($urlSummary['kind'] === 'absolute' && in_array($urlSummary['scheme'], ['http', 'https'], true)) {
                $remoteUrls[] = $url;
            }
            if (!$descriptor['descriptorValid']) {
                $invalidDescriptors[] = $candidate['descriptor'];
                $issues[] = [
                    'code' => 'invalid-srcset-descriptor',
                    'candidateIndex' => $index,
                    'descriptor' => $candidate['descriptor'],
                ];
            }

            $records[] = [
                'index' => $index,
                'raw' => $candidate['raw'],
                'url' => $url,
                'urlKind' => $urlSummary['kind'],
                'urlScheme' => $urlSummary['scheme'],
                'urlUnsafe' => $urlSummary['unsafe'],
                'descriptorRaw' => $candidate['descriptor'],
                'descriptors' => $candidate['descriptors'],
            ] + $descriptor;
        }

        if (isset($descriptorKinds['width'], $descriptorKinds['pixel-density'])) {
            $issues[] = ['code' => 'mixed-srcset-descriptor-kinds'];
        }
        foreach ($duplicateDescriptors as $descriptor) {
            $issues[] = [
                'code' => 'duplicate-srcset-descriptor',
                'descriptor' => $descriptor,
                'count' => $descriptorCounts[$descriptor],
            ];
        }

        $issueCodes = array_values(array_unique(array_map(
            static fn (array $issue): string => (string) ($issue['code'] ?? ''),
            $issues
        )));

        return [
            $keyPrefix . 'ResourceReviewPolicy' => 'html-srcset-resource-metadata-review',
            $keyPrefix . 'CandidateCount' => count($candidates),
            $keyPrefix . 'CandidateUrls' => array_values(array_map(
                static fn (array $candidate): string => (string) $candidate['url'],
                $candidates
            )),
            $keyPrefix . 'CandidateUrlRecords' => $records,
            $keyPrefix . 'RemoteUrls' => $remoteUrls,
            $keyPrefix . 'RemoteUrlCount' => count($remoteUrls),
            $keyPrefix . 'UnsafeUrls' => $unsafeUrls,
            $keyPrefix . 'InvalidDescriptors' => $invalidDescriptors,
            $keyPrefix . 'DuplicateDescriptors' => $duplicateDescriptors,
            $keyPrefix . 'DescriptorKinds' => array_keys($descriptorKinds),
            $keyPrefix . 'Issues' => $issues,
            $keyPrefix . 'IssueCodes' => $issueCodes,
            $keyPrefix . 'Valid' => $issues === [],
        ];
    }

    /**
     * @param list<string> $descriptors
     * @return array{descriptorKind:string, descriptorValue:int|float|null, descriptorNormalized:?string, descriptorValid:bool}
     */
    private static function srcsetDescriptorReviewSummary(array $descriptors): array
    {
        if ($descriptors === []) {
            return [
                'descriptorKind' => 'implicit',
                'descriptorValue' => null,
                'descriptorNormalized' => null,
                'descriptorValid' => true,
            ];
        }

        if (count($descriptors) !== 1) {
            return [
                'descriptorKind' => 'invalid',
                'descriptorValue' => null,
                'descriptorNormalized' => implode(' ', $descriptors),
                'descriptorValid' => false,
            ];
        }

        $descriptor = strtolower($descriptors[0]);
        if (preg_match('/^([0-9]+)w$/', $descriptor, $width) === 1) {
            $pixels = (int) $width[1];

            return [
                'descriptorKind' => 'width',
                'descriptorValue' => $pixels > 0 ? $pixels : null,
                'descriptorNormalized' => $pixels > 0 ? $pixels . 'w' : $descriptor,
                'descriptorValid' => $pixels > 0,
            ];
        }

        if (preg_match('/^(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)x$/', $descriptor) === 1) {
            $density = (float) substr($descriptor, 0, -1);

            return [
                'descriptorKind' => 'pixel-density',
                'descriptorValue' => $density > 0.0 ? $density : null,
                'descriptorNormalized' => $descriptor,
                'descriptorValid' => $density > 0.0,
            ];
        }

        return [
            'descriptorKind' => 'invalid',
            'descriptorValue' => null,
            'descriptorNormalized' => $descriptor,
            'descriptorValid' => false,
        ];
    }

    /**
     * @return list<string>
     */
    private static function splitSrcsetCandidates(string $value): array
    {
        $candidates = [];
        $start = 0;
        $offset = 0;

        while (($comma = strpos($value, ',', $offset)) !== false) {
            $candidatePrefix = substr($value, $start, $comma - $start);
            if (self::isDataUrlPayloadComma($candidatePrefix)) {
                $offset = $comma + 1;
                continue;
            }

            $candidates[] = $candidatePrefix;
            $start = $comma + 1;
            $offset = $start;
        }

        $candidates[] = substr($value, $start);

        return $candidates;
    }

    private static function isDataUrlPayloadComma(string $candidatePrefix): bool
    {
        $trimmed = trim($candidatePrefix);
        if ($trimmed === '' || preg_match('/[\x00-\x20]/', $trimmed) === 1) {
            return false;
        }

        return preg_match('/^data:[^,]*$/i', $trimmed) === 1;
    }

    private static function attributeOrNull(\DOMElement $element, string $name): ?string
    {
        return $element->hasAttribute($name) ? $element->getAttribute($name) : null;
    }

    private static function normalizedNonEmptyAttribute(?string $value): ?string
    {
        if ($value === null) {
            return null;
        }

        $normalized = trim($value);

        return $normalized === '' ? null : $normalized;
    }

    private static function htmlMetadataAttributeValue(string $value): string
    {
        $value = str_replace("\0", '', $value);
        $value = preg_replace('/[\t\r\n\f ]+/u', ' ', $value) ?? $value;

        return trim($value);
    }

    private static function mediaPreload(\DOMElement $media): string
    {
        $preload = self::mediaPreloadState($media->getAttribute('preload'));

        return $preload ?? 'auto';
    }

    private static function mediaPreloadState(string $value): ?string
    {
        $preload = strtolower(self::htmlMetadataAttributeValue($value));
        if ($preload === '') {
            return 'auto';
        }

        return in_array($preload, ['none', 'metadata', 'auto'], true) ? $preload : null;
    }

    private static function mediaDimensionState(string $value): ?string
    {
        $dimension = self::htmlMetadataAttributeValue($value);
        if ($dimension === '' || preg_match('/^[0-9]+$/', $dimension) !== 1) {
            return null;
        }

        $dimension = ltrim($dimension, '0');

        return $dimension === '' ? '0' : $dimension;
    }

    /**
     * @return array<string, mixed>
     */
    private static function mediaPreloadReviewSummary(\DOMElement $media): array
    {
        $raw = self::attributeOrNull($media, 'preload');
        $normalized = $raw === null ? null : strtolower(trim($raw));
        $keyword = match ($normalized) {
            null => null,
            '', 'auto' => 'auto',
            'metadata' => 'metadata',
            'none' => 'none',
            default => null,
        };
        $issueCodes = $raw !== null && $keyword === null ? ['invalid-media-preload-token'] : [];

        return [
            'mediaPreloadReviewPolicy' => 'media-preload-state-review',
            'preloadRaw' => $raw,
            'preloadKeyword' => $keyword,
            'preloadState' => $keyword ?? 'auto',
            'preloadValid' => $raw === null ? null : $keyword !== null,
            'preloadDefaulted' => $raw === null || $normalized === '' || $keyword === null,
            'preloadDefaultReason' => match (true) {
                $raw === null => 'missing-attribute',
                $normalized === '' => 'empty-attribute',
                $keyword === null => 'invalid-token',
                default => null,
            },
            'preloadAutoplayOverride' => $media->hasAttribute('autoplay'),
            'mediaPreloadIssueCodes' => $issueCodes,
            'mediaPreloadIssueCount' => count($issueCodes),
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function mediaSourceSummaries(\DOMElement $media): array
    {
        $sources = [];
        if ($media->hasAttribute('src')) {
            $sources[] = ['src' => $media->getAttribute('src')];
        }
        foreach (self::mediaResourceElements($media, 'source') as $source) {
            $summary = [];
            foreach (['src', 'type', 'media', 'srcset', 'sizes'] as $attribute) {
                if ($source->hasAttribute($attribute)) {
                    $summary[$attribute] = $source->getAttribute($attribute);
                }
            }
            $sources[] = $summary;
        }

        return $sources;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function mediaTrackSummaries(\DOMElement $media): array
    {
        $tracks = [];
        foreach (self::mediaResourceElements($media, 'track') as $track) {
            $summary = [
                'kind' => self::trackKind($track),
                'src' => $track->getAttribute('src'),
                'srclang' => $track->getAttribute('srclang'),
                'label' => $track->getAttribute('label'),
                'default' => $track->hasAttribute('default'),
            ];
            $tracks[] = $summary;
        }

        return $tracks;
    }

    private static function trackKind(\DOMElement $track): string
    {
        $kind = strtolower(trim($track->getAttribute('kind')));

        return self::isHtmlTrackKind($kind)
            ? $kind
            : 'subtitles';
    }

    private static function isHtmlTrackKind(string $kind): bool
    {
        return in_array($kind, ['subtitles', 'captions', 'descriptions', 'chapters', 'metadata'], true);
    }

    private static function normalizeHtmlLanguageTag(string $value): ?string
    {
        $language = trim($value);
        if ($language === '') {
            return null;
        }

        $canonical = [];
        foreach (explode('-', $language) as $index => $part) {
            if (preg_match('/^[A-Za-z0-9]{1,8}$/', $part) !== 1) {
                return null;
            }

            if ($index === 0) {
                if (preg_match('/^(?:[A-Za-z]{2,8}|x)$/', $part) !== 1) {
                    return null;
                }

                $canonical[] = strtolower($part);
                continue;
            }

            if (strlen($part) === 4 && preg_match('/^[A-Za-z]{4}$/', $part) === 1) {
                $canonical[] = ucfirst(strtolower($part));
                continue;
            }
            if (
                (strlen($part) === 2 && preg_match('/^[A-Za-z]{2}$/', $part) === 1)
                || (strlen($part) === 3 && preg_match('/^[0-9]{3}$/', $part) === 1)
            ) {
                $canonical[] = strtoupper($part);
                continue;
            }

            $canonical[] = strtolower($part);
        }

        if ($canonical[0] === 'x' && count($canonical) === 1) {
            return null;
        }

        return implode('-', $canonical);
    }

    private static function normalizedTextWithoutMediaResourceChildren(\DOMElement $media): string
    {
        $text = '';
        foreach ($media->childNodes as $child) {
            $text .= self::mediaFallbackText($child);
        }

        $text = preg_replace('/[ \t\r\n\f]+/u', ' ', $text) ?? $text;

        return trim($text);
    }

    /**
     * @return list<\DOMElement>
     */
    private static function mediaResourceElements(\DOMElement $media, string $name): array
    {
        $resources = [];
        $stack = [];
        for ($index = $media->childNodes->length - 1; $index >= 0; --$index) {
            $child = $media->childNodes->item($index);
            if ($child instanceof \DOMElement) {
                $stack[] = $child;
            }
        }

        while ($stack !== []) {
            $node = array_pop($stack);
            if (!$node instanceof \DOMElement) {
                continue;
            }

            if (strtolower(self::htmlElementName($node)) === $name && self::belongsToMediaResourceList($node, $media)) {
                $resources[] = $node;
            }

            for ($index = $node->childNodes->length - 1; $index >= 0; --$index) {
                $child = $node->childNodes->item($index);
                if ($child instanceof \DOMElement) {
                    $stack[] = $child;
                }
            }
        }

        return $resources;
    }

    private static function belongsToMediaResourceList(\DOMElement $resource, \DOMElement $media): bool
    {
        $parent = $resource->parentNode;
        while ($parent instanceof \DOMElement && !$parent->isSameNode($media)) {
            if (in_array(strtolower(self::htmlElementName($parent)), ['audio', 'video', 'picture'], true)) {
                return false;
            }
            $parent = $parent->parentNode;
        }

        return $parent instanceof \DOMElement && $parent->isSameNode($media);
    }

    private static function mediaFallbackText(\DOMNode $node): string
    {
        if ($node instanceof \DOMText) {
            return $node->nodeValue ?? '';
        }

        if (!$node instanceof \DOMElement) {
            return '';
        }

        $text = '';
        foreach ($node->childNodes as $child) {
            $text .= self::mediaFallbackText($child);
        }

        return $text;
    }

    /**
     * @return list<string>
     */
    private static function spaceSeparatedTokens(string $value): array
    {
        $value = trim($value);
        if ($value === '') {
            return [];
        }

        return preg_split('/\s+/', $value) ?: [];
    }

    private static function numericAttribute(\DOMElement $element, string $name, ?float $default): ?float
    {
        if (!$element->hasAttribute($name)) {
            return $default;
        }

        $value = trim($element->getAttribute($name));
        if ($value === '' || !is_numeric($value)) {
            return $default;
        }

        $number = (float) $value;

        return is_finite($number) ? $number : $default;
    }

    private static function integerAttribute(\DOMElement $element, string $name, ?int $default): ?int
    {
        if (!$element->hasAttribute($name)) {
            return $default;
        }

        $value = trim($element->getAttribute($name));
        if (!preg_match('/^[+-]?[0-9]+$/', $value)) {
            return $default;
        }

        $integer = filter_var($value, FILTER_VALIDATE_INT);

        return is_int($integer) ? $integer : $default;
    }

    private static function positiveNumericAttribute(\DOMElement $element, string $name, float $default): float
    {
        $value = self::numericAttribute($element, $name, $default) ?? $default;

        return $value > 0.0 ? $value : $default;
    }

    private static function positiveIntegerAttribute(\DOMElement $element, string $name, int $default, int $max): int
    {
        $value = self::integerAttribute($element, $name, null);
        if ($value === null || $value < 1) {
            return $default;
        }

        return min($value, $max);
    }

    private static function nonNegativeIntegerAttribute(\DOMElement $element, string $name, int $default, int $max): int
    {
        $value = self::integerAttribute($element, $name, null);
        if ($value === null || $value < 0) {
            return $default;
        }

        return min($value, $max);
    }

    private static function boundedNumber(float $value, float $min, float $max): float
    {
        return max($min, min($max, $value));
    }

    /**
     * @return list<string>
     */
    private static function formControlLabels(\DOMElement $control): array
    {
        $labels = [];
        $id = $control->getAttribute('id');
        $document = $control->ownerDocument;
        if ($id !== '' && $document instanceof \DOMDocument) {
            foreach ($document->getElementsByTagName('label') as $label) {
                if (!$label instanceof \DOMElement || $label->getAttribute('for') !== $id) {
                    continue;
                }
                self::appendFormControlLabel($labels, self::normalizedText($label));
            }
        }

        $parent = $control->parentNode;
        while ($parent instanceof \DOMElement) {
            if (strtolower(self::htmlElementName($parent)) === 'label') {
                self::appendFormControlLabel($labels, self::normalizedText($parent));
            }
            $parent = $parent->parentNode;
        }

        return $labels;
    }

    /**
     * @param list<string> $labels
     */
    private static function appendFormControlLabel(array &$labels, string $label): void
    {
        if ($label !== '' && !in_array($label, $labels, true)) {
            $labels[] = $label;
        }
    }

    private static function isEffectivelyDisabledFormControl(\DOMElement $control): bool
    {
        if ($control->hasAttribute('disabled')) {
            return true;
        }

        $parent = $control->parentNode;
        while ($parent instanceof \DOMElement) {
            if (strtolower(self::htmlElementName($parent)) === 'fieldset' && $parent->hasAttribute('disabled')) {
                $legend = self::firstChildHtmlElement($parent, 'legend');
                if (!$legend instanceof \DOMElement || !self::isDescendantOrSame($control, $legend)) {
                    return true;
                }
            }
            $parent = $parent->parentNode;
        }

        return false;
    }

    private static function firstChildHtmlElement(\DOMElement $element, string $name): ?\DOMElement
    {
        foreach (self::childHtmlElements($element, $name) as $child) {
            return $child;
        }

        return null;
    }

    /**
     * @return list<\DOMElement>
     */
    private static function childHtmlElements(\DOMElement $element, string $name): array
    {
        $children = [];
        foreach ($element->childNodes as $child) {
            if ($child instanceof \DOMElement && strtolower(self::htmlElementName($child)) === $name) {
                $children[] = $child;
            }
        }

        return $children;
    }

    private static function firstDescendantHtmlElement(\DOMElement $element, string $name): ?\DOMElement
    {
        foreach (self::descendantHtmlElements($element, $name) as $descendant) {
            return $descendant;
        }

        return null;
    }

    /**
     * @return list<\DOMElement>
     */
    private static function descendantHtmlElements(\DOMElement $element, string $name): array
    {
        $descendants = [];
        foreach ($element->getElementsByTagName('*') as $descendant) {
            if ($descendant instanceof \DOMElement && strtolower(self::htmlElementName($descendant)) === $name) {
                $descendants[] = $descendant;
            }
        }

        return $descendants;
    }

    /**
     * @return list<\DOMElement>
     */
    private static function nearestTableElementsById(\DOMElement $context, string $id): array
    {
        $table = self::nearestHtmlTable($context);
        if (!$table instanceof \DOMElement) {
            return [];
        }

        $elements = [];
        if (self::attributeOrNull($table, 'id') === $id) {
            $elements[] = $table;
        }

        foreach ($table->getElementsByTagName('*') as $candidate) {
            if (!$candidate instanceof \DOMElement || self::attributeOrNull($candidate, 'id') !== $id) {
                continue;
            }

            $candidateTable = self::nearestHtmlTable($candidate);
            if ($candidateTable instanceof \DOMElement && $candidateTable->isSameNode($table)) {
                $elements[] = $candidate;
            }
        }

        return $elements;
    }

    private static function nearestHtmlTable(\DOMElement $element): ?\DOMElement
    {
        $current = $element;
        while ($current instanceof \DOMElement) {
            if (self::htmlElementName($current) === 'table') {
                return $current;
            }
            $current = $current->parentNode;
        }

        return null;
    }

    private static function isDescendantOrSame(\DOMElement $element, \DOMElement $ancestor): bool
    {
        $current = $element;
        while ($current instanceof \DOMElement) {
            if ($current->isSameNode($ancestor)) {
                return true;
            }
            $current = $current->parentNode;
        }

        return false;
    }

    /**
     * @return list<array{value:string, label:string, text:string, disabled:bool}>
     */
    private static function datalistOptionsForControl(\DOMElement $control): array
    {
        $listId = $control->getAttribute('list');
        if (!self::isHtmlIdReferenceToken($listId)) {
            return [];
        }

        $targets = self::datalistTargetElementsForControl($control, $listId);
        $target = $targets[0] ?? null;

        return $target instanceof \DOMElement ? self::datalistOptionSummaries($target) : [];
    }

    /**
     * @return array<string, mixed>
     */
    private static function datalistAssociationSummary(\DOMElement $control, string $listRaw): array
    {
        $listId = $listRaw === '' ? null : $listRaw;
        $valid = $listId !== null && self::isHtmlIdReferenceToken($listId);
        $targets = $valid ? self::datalistTargetElementsForControl($control, $listId) : [];
        $target = $targets[0] ?? null;
        $options = $target instanceof \DOMElement ? self::datalistOptionSummaries($target) : [];
        $issues = [];

        if (!$valid) {
            $issues[] = [
                'code' => 'invalid-datalist-list-reference',
                'listReferenceRaw' => $listRaw,
            ];
        } elseif ($targets === []) {
            $issues[] = [
                'code' => 'missing-datalist-target',
                'listReferenceId' => $listId,
            ];
        } elseif (count($targets) > 1) {
            $issues[] = [
                'code' => 'duplicate-datalist-target-id',
                'listReferenceId' => $listId,
                'count' => count($targets),
            ];
        }

        return [
            'datalistReviewPolicy' => 'input-list-datalist-idref-review',
            'listReferenceRaw' => $listRaw,
            'listReferenceId' => $listId,
            'listReferenceValid' => $valid,
            'datalistAssociationState' => !$valid
                ? 'invalid-reference'
                : ($targets === [] ? 'missing-datalist' : (count($targets) > 1 ? 'duplicate-datalist' : 'resolved')),
            'datalistResolved' => $valid && count($targets) === 1,
            'datalistTargetCount' => count($targets),
            'datalistOptionCount' => count($options),
            'datalistOptions' => $options,
            'datalistTargets' => array_map(
                static fn (\DOMElement $target): array => self::datalistTargetSummary($target),
                $targets
            ),
            'datalistIssues' => $issues,
            'datalistIssueCodes' => array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ),
        ];
    }

    /**
     * @return list<\DOMElement>
     */
    private static function datalistTargetElementsForControl(\DOMElement $control, string $listId): array
    {
        $root = self::htmlFragmentScope($control);
        if (!$root instanceof \DOMElement) {
            return [];
        }

        $targets = [];
        foreach (self::descendantHtmlElements($root, 'datalist') as $datalist) {
            if ($datalist->getAttribute('id') === $listId) {
                $targets[] = $datalist;
            }
        }

        return $targets;
    }

    /**
     * @return array<string, mixed>
     */
    private static function datalistTargetSummary(\DOMElement $datalist): array
    {
        $options = self::datalistOptionSummaries($datalist);

        return [
            'id' => self::attributeOrNull($datalist, 'id'),
            'optionCount' => count($options),
            'optionValues' => array_values(array_map(
                static fn (array $option): string => (string) $option['value'],
                $options
            )),
            'options' => $options,
        ];
    }

    /**
     * @return list<array{value:string, label:string, text:string, disabled:bool}>
     */
    private static function datalistOptionSummaries(\DOMElement $datalist): array
    {
        $options = [];
        foreach ($datalist->getElementsByTagName('option') as $option) {
            if (!$option instanceof \DOMElement) {
                continue;
            }
            $text = self::normalizedText($option);
            $options[] = [
                'value' => $option->hasAttribute('value') ? $option->getAttribute('value') : $text,
                'label' => $option->hasAttribute('label') ? $option->getAttribute('label') : $text,
                'text' => $text,
                'disabled' => $option->hasAttribute('disabled'),
            ];
        }

        return $options;
    }

    /**
     * @return array<string, mixed>
     */
    private static function fieldsetSummary(\DOMElement $fieldset): array
    {
        $legends = self::childHtmlElements($fieldset, 'legend');
        $legend = $legends[0] ?? null;
        $controls = self::fieldsetControlSummaries($fieldset, $legend);
        $nestedFieldsets = self::nestedFieldsetSummaries($fieldset);
        $issues = self::fieldsetReviewIssues($legends, $nestedFieldsets);

        return [
            'formGroup' => 'fieldset',
            'fieldsetReviewPolicy' => 'fieldset-legend-disabled-control-review',
            'disabled' => $fieldset->hasAttribute('disabled'),
            'legendText' => $legend instanceof \DOMElement ? self::normalizedText($legend) : null,
            'legendTexts' => self::fieldsetLegendTexts($legends),
            'legendCount' => count($legends),
            'controlCount' => count($controls),
            'legendControlCount' => count(array_filter(
                $controls,
                static fn (array $control): bool => (bool) ($control['inFirstLegend'] ?? false)
            )),
            'enabledControlCount' => self::fieldsetEffectiveControlCount($controls, false),
            'disabledControlCount' => self::fieldsetEffectiveControlCount($controls, true),
            'controls' => $controls,
            'controlNames' => self::fieldsetControlNames($controls),
            'enabledControlNames' => self::fieldsetControlNames($controls, false),
            'disabledControlNames' => self::fieldsetControlNames($controls, true),
            'nestedFieldsetCount' => count($nestedFieldsets),
            'nestedDisabledFieldsetCount' => count(array_filter(
                $nestedFieldsets,
                static fn (array $nested): bool => (bool) ($nested['disabled'] ?? false)
            )),
            'nestedFieldsets' => $nestedFieldsets,
            'fieldsetIssueCount' => count($issues),
            'fieldsetIssues' => $issues,
            'fieldsetIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ))),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function legendSummary(\DOMElement $legend): array
    {
        $fieldset = self::parentHtmlElement($legend, 'fieldset');
        $firstLegend = $fieldset instanceof \DOMElement ? self::firstChildHtmlElement($fieldset, 'legend') : null;

        return [
            'formGroupPart' => 'legend',
            'legendText' => self::normalizedText($legend),
            'fieldsetDisabled' => $fieldset instanceof \DOMElement ? $fieldset->hasAttribute('disabled') : null,
            'firstLegend' => $firstLegend instanceof \DOMElement && $legend->isSameNode($firstLegend),
            'fieldsetLegendIndex' => $fieldset instanceof \DOMElement ? self::fieldsetLegendIndex($fieldset, $legend) : null,
            'fieldsetLegendCount' => $fieldset instanceof \DOMElement ? count(self::childHtmlElements($fieldset, 'legend')) : null,
        ];
    }

    /**
     * @param list<\DOMElement> $legends
     * @return list<string>
     */
    private static function fieldsetLegendTexts(array $legends): array
    {
        return array_values(array_filter(
            array_map(static fn (\DOMElement $legend): string => self::normalizedText($legend), $legends),
            static fn (string $text): bool => $text !== ''
        ));
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function nestedFieldsetSummaries(\DOMElement $fieldset): array
    {
        $nested = [];
        foreach (self::descendantHtmlElements($fieldset, 'fieldset') as $nestedFieldset) {
            $legends = self::childHtmlElements($nestedFieldset, 'legend');
            $legend = $legends[0] ?? null;
            $controls = self::fieldsetControlSummaries($nestedFieldset, $legend);
            $nested[] = [
                'id' => self::attributeOrNull($nestedFieldset, 'id'),
                'disabled' => $nestedFieldset->hasAttribute('disabled'),
                'legendText' => $legend instanceof \DOMElement ? self::normalizedText($legend) : null,
                'legendCount' => count($legends),
                'controlCount' => count($controls),
                'enabledControlCount' => self::fieldsetEffectiveControlCount($controls, false),
                'disabledControlCount' => self::fieldsetEffectiveControlCount($controls, true),
                'controlNames' => self::fieldsetControlNames($controls),
            ];
        }

        return $nested;
    }

    /**
     * @param list<\DOMElement> $legends
     * @param list<array<string, mixed>> $nestedFieldsets
     * @return list<array<string, mixed>>
     */
    private static function fieldsetReviewIssues(array $legends, array $nestedFieldsets): array
    {
        $issues = [];
        $legendCount = count($legends);
        if ($legendCount === 0) {
            $issues[] = ['code' => 'missing-fieldset-legend'];
        } elseif ($legendCount > 1) {
            $issues[] = [
                'code' => 'multiple-fieldset-legends',
                'legendCount' => $legendCount,
                'legendTexts' => self::fieldsetLegendTexts($legends),
            ];
        }
        if ($nestedFieldsets !== []) {
            $issues[] = [
                'code' => 'nested-fieldset-review',
                'nestedFieldsetCount' => count($nestedFieldsets),
                'nestedFieldsetIds' => array_values(array_filter(
                    array_map(static fn (array $nested): ?string => $nested['id'] ?? null, $nestedFieldsets),
                    static fn (?string $id): bool => $id !== null && $id !== ''
                )),
            ];
        }

        return $issues;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private static function fieldsetControlSummaries(\DOMElement $fieldset, ?\DOMElement $firstLegend): array
    {
        $controls = [];
        foreach ($fieldset->getElementsByTagName('*') as $control) {
            if (!$control instanceof \DOMElement || !self::isFormControlElement($control)) {
                continue;
            }

            $name = self::htmlElementName($control);
            $controlSummary = [
                'tag' => $name,
                'id' => self::attributeOrNull($control, 'id'),
                'controlName' => self::attributeOrNull($control, 'name'),
                'effectiveDisabled' => self::isEffectivelyDisabledFormControl($control),
                'inFirstLegend' => $firstLegend instanceof \DOMElement && self::isDescendantOrSame($control, $firstLegend),
            ];

            if ($name === 'input') {
                $controlSummary['type'] = self::inputType($control);
            } elseif ($name === 'button') {
                $controlSummary['type'] = self::buttonType($control);
            }

            $controls[] = $controlSummary;
        }

        return $controls;
    }

    private static function isFormControlElement(\DOMElement $element): bool
    {
        return in_array(self::htmlElementName($element), ['button', 'input', 'output', 'select', 'textarea'], true);
    }

    /**
     * @param list<array<string, mixed>> $controls
     * @return list<string>
     */
    private static function fieldsetEffectiveControlCount(array $controls, bool $effectiveDisabled): int
    {
        return count(array_filter(
            $controls,
            static fn (array $control): bool => (bool) ($control['effectiveDisabled'] ?? false) === $effectiveDisabled
        ));
    }

    private static function fieldsetControlNames(array $controls, ?bool $effectiveDisabled = null): array
    {
        $names = [];
        foreach ($controls as $control) {
            if ($effectiveDisabled !== null && (bool) ($control['effectiveDisabled'] ?? false) !== $effectiveDisabled) {
                continue;
            }
            $name = $control['controlName'] ?? null;
            if (is_string($name) && $name !== '' && !in_array($name, $names, true)) {
                $names[] = $name;
            }
        }

        return $names;
    }

    private static function fieldsetLegendIndex(\DOMElement $fieldset, \DOMElement $legend): ?int
    {
        foreach (self::childHtmlElements($fieldset, 'legend') as $index => $candidate) {
            if ($candidate->isSameNode($legend)) {
                return $index;
            }
        }

        return null;
    }

    private static function parentHtmlElement(\DOMElement $element, string $name): ?\DOMElement
    {
        $parent = $element->parentNode;

        return $parent instanceof \DOMElement && self::htmlElementName($parent) === $name ? $parent : null;
    }

    private static function ancestorHtmlElement(\DOMElement $element, string $name): ?\DOMElement
    {
        $parent = $element->parentNode;
        while ($parent instanceof \DOMElement) {
            if (self::htmlElementName($parent) === $name) {
                return $parent;
            }

            $parent = $parent->parentNode;
        }

        return null;
    }

    private static function tableHeaderScope(\DOMElement $header): ?string
    {
        $scope = strtolower(trim($header->getAttribute('scope')));

        return in_array($scope, ['row', 'col', 'rowgroup', 'colgroup'], true) ? $scope : null;
    }

    /**
     * @param list<string> $values
     */
    private static function appendUniqueString(array &$values, string $value): void
    {
        if ($value !== '' && !in_array($value, $values, true)) {
            $values[] = $value;
        }
    }

    private static function serializeNode(\DOMNode $node): string
    {
        if ($node instanceof \DOMText) {
            return htmlspecialchars($node->nodeValue ?? '', ENT_NOQUOTES | ENT_SUBSTITUTE | ENT_HTML5, 'UTF-8');
        }

        if ($node instanceof \DOMComment) {
            $text = self::safeHtmlCommentText($node->nodeValue ?? '');

            return '<!--' . $text . '-->';
        }

        if ($node instanceof \DOMDocument || $node instanceof \DOMDocumentFragment) {
            return self::serializeHtmlChildren($node);
        }

        if (!$node instanceof \DOMElement) {
            return '';
        }

        $name = self::htmlElementName($node);
        if (self::isHtmlTableModelContext($name)) {
            return self::serializeTableElementWithFostered($node, $name);
        }

        return self::serializeElementWithChildren($node, null);
    }

    private static function serializeElementWithChildren(\DOMElement $node, ?string $childrenHtml): string
    {
        $name = self::htmlElementName($node);
        $html = '<' . $name . self::serializeAttributes($node);
        if (isset(self::HTML5_VOID_ELEMENTS[strtolower($name)])) {
            return $html . '>' . self::serializeHtmlChildren($node);
        }

        $html .= '>';
        if ($childrenHtml !== null) {
            $html .= $childrenHtml;
        } elseif (isset(self::HTML5_RAW_TEXT_ELEMENTS[strtolower($name)])) {
            $html .= self::rawTextContent($node);
        } else {
            $html .= self::serializeHtmlChildren($node);
        }

        return $html . '</' . $name . '>';
    }

    private static function serializeTableElementWithFostered(\DOMElement $element, string $context): string
    {
        [$fosteredHtml, $childrenHtml] = self::serializeTableChildren($element, $context);

        return $fosteredHtml . self::serializeElementWithChildren($element, $childrenHtml);
    }

    /**
     * @return array{0:string, 1:string}
     */
    private static function serializeTableElementParts(\DOMElement $element, string $context): array
    {
        [$fosteredHtml, $childrenHtml] = self::serializeTableChildren($element, $context);

        return [$fosteredHtml, self::serializeElementWithChildren($element, $childrenHtml)];
    }

    /**
     * @return array{0:string, 1:string}
     */
    private static function serializeTableChildren(\DOMElement $element, string $context): array
    {
        $fosteredHtml = '';
        $childrenHtml = '';

        foreach ($element->childNodes as $child) {
            if (self::isFosteredHtmlTableChild($child, $context)) {
                $fosteredHtml .= self::serializeNode($child);
                continue;
            }

            if ($child instanceof \DOMElement) {
                $childName = self::htmlElementName($child);
                if (self::isHtmlTableModelContext($childName)) {
                    [$nestedFosteredHtml, $childHtml] = self::serializeTableElementParts($child, $childName);
                    $fosteredHtml .= $nestedFosteredHtml;
                    $childrenHtml .= $childHtml;
                    continue;
                }
            }

            $childrenHtml .= self::serializeNode($child);
        }

        return [$fosteredHtml, $childrenHtml];
    }

    /**
     * @return array{0:list<array<string, mixed>>, 1:array<string, mixed>}
     */
    private static function summarizeTableElementParts(\DOMElement $element, string $context): array
    {
        [$fostered, $children] = self::summarizeTableChildren($element, $context);

        $summary = [
            'type' => 'element',
            'name' => self::htmlElementName($element),
            'attributes' => self::htmlAttributes($element),
            'text' => self::summaryText($children),
            'children' => $children,
        ];
        $summary += self::globalHtmlAttributeSummary($element);
        $summary += self::tableElementSummary($element, self::htmlElementName($element));

        return [$fostered, $summary];
    }

    /**
     * @return array{0:list<array<string, mixed>>, 1:list<array<string, mixed>>}
     */
    private static function summarizeTableChildren(\DOMElement $element, string $context): array
    {
        $fostered = [];
        $children = [];

        foreach ($element->childNodes as $child) {
            if (self::isFosteredHtmlTableChild($child, $context)) {
                array_push($fostered, ...self::summarizeNode($child));
                continue;
            }

            if ($child instanceof \DOMElement) {
                $childName = self::htmlElementName($child);
                if (self::isHtmlTableModelContext($childName)) {
                    [$nestedFostered, $summary] = self::summarizeTableElementParts($child, $childName);
                    array_push($fostered, ...$nestedFostered);
                    $children[] = $summary;
                    continue;
                }
            }

            array_push($children, ...self::summarizeNode($child));
        }

        return [$fostered, $children];
    }

    /**
     * @return list<array{value:string, label:string, text:string, selected:bool, disabled:bool, group?:string, groupDisabled?:bool}>
     */
    private static function selectOptionSummaries(\DOMElement $select): array
    {
        $options = [];
        foreach ($select->childNodes as $child) {
            self::collectSelectOptionSummaries($child, null, false, $options);
        }

        return $options;
    }

    /**
     * @return array<string, mixed>
     */
    private static function optgroupSummary(\DOMElement $optgroup): array
    {
        $label = $optgroup->hasAttribute('label') ? $optgroup->getAttribute('label') : null;
        $options = [];
        foreach (self::childHtmlElements($optgroup, 'option') as $option) {
            $optionSummary = self::optionRecord($option);
            unset($optionSummary['group'], $optionSummary['groupDisabled']);
            $options[] = $optionSummary;
        }

        return [
            'optionGroup' => 'optgroup',
            'optionGroupLabel' => $label,
            'disabled' => $optgroup->hasAttribute('disabled'),
            'optionCount' => count($options),
            'selectedOptionCount' => count(array_filter(
                $options,
                static fn (array $option): bool => (bool) ($option['selected'] ?? false)
            )),
            'optionValues' => array_values(array_map(
                static fn (array $option): string => (string) $option['value'],
                $options
            )),
            'selectedValues' => array_values(array_map(
                static fn (array $option): string => (string) $option['value'],
                array_filter($options, static fn (array $option): bool => (bool) ($option['selected'] ?? false))
            )),
            'options' => $options,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function optionSummary(\DOMElement $option): array
    {
        $record = self::optionRecord($option);

        return [
            'option' => 'option',
            'optionValue' => $record['value'],
            'optionLabel' => $record['label'],
            'optionText' => $record['text'],
            'selected' => $record['selected'],
            'optionDisabled' => $option->hasAttribute('disabled'),
            'disabled' => $record['disabled'],
            'effectiveDisabled' => $record['disabled'],
            'optionGroupLabel' => $record['group'] ?? null,
            'optionGroupDisabled' => $record['groupDisabled'] ?? null,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    private static function selectedContentSummary(\DOMElement $selectedContent): array
    {
        $select = self::ancestorHtmlElement($selectedContent, 'select');
        $button = self::ancestorHtmlElement($selectedContent, 'button');
        $options = $select instanceof \DOMElement ? self::selectOptionSummaries($select) : [];
        $selectedOptions = array_values(array_filter(
            $options,
            static fn (array $option): bool => (bool) ($option['selected'] ?? false)
        ));
        $selectedContents = $select instanceof \DOMElement
            ? self::descendantHtmlElements($select, 'selectedcontent')
            : [];
        $elementIndex = null;
        foreach ($selectedContents as $index => $candidate) {
            if ($candidate->isSameNode($selectedContent)) {
                $elementIndex = $index + 1;
                break;
            }
        }

        $selectedValues = array_values(array_map(
            static fn (array $option): string => (string) ($option['value'] ?? ''),
            $selectedOptions
        ));
        $selectedLabels = array_values(array_map(
            static fn (array $option): string => (string) ($option['label'] ?? ''),
            $selectedOptions
        ));
        $selectedTexts = array_values(array_map(
            static fn (array $option): string => (string) ($option['text'] ?? ''),
            $selectedOptions
        ));
        $issues = [];

        if (!$select instanceof \DOMElement) {
            $issues[] = ['code' => 'selectedcontent-missing-select-ancestor'];
        }
        if (!$select instanceof \DOMElement || !$button instanceof \DOMElement || !self::isDescendantOrSame($button, $select)) {
            $issues[] = ['code' => 'selectedcontent-outside-select-button'];
        }
        if ($select instanceof \DOMElement && count($selectedContents) > 1) {
            $issues[] = [
                'code' => 'duplicate-selectedcontent-element',
                'count' => count($selectedContents),
            ];
        }
        if ($select instanceof \DOMElement && $selectedOptions === []) {
            $issues[] = ['code' => 'selectedcontent-missing-selected-option'];
        }
        if ($select instanceof \DOMElement && !$select->hasAttribute('multiple') && count($selectedOptions) > 1) {
            $issues[] = [
                'code' => 'multiple-selected-options-for-single-select',
                'count' => count($selectedOptions),
            ];
        }

        return [
            'selectedContent' => 'selectedcontent',
            'selectedContentReviewPolicy' => 'html-select-selectedcontent-review',
            'selectedContentStaticText' => self::normalizedText($selectedContent),
            'selectedContentInSelect' => $select instanceof \DOMElement,
            'selectedContentSelectId' => $select instanceof \DOMElement ? self::attributeOrNull($select, 'id') : null,
            'selectedContentSelectName' => $select instanceof \DOMElement ? self::attributeOrNull($select, 'name') : null,
            'selectedContentSelectMultiple' => $select instanceof \DOMElement ? $select->hasAttribute('multiple') : null,
            'selectedContentInButton' => $button instanceof \DOMElement,
            'selectedContentButtonText' => $button instanceof \DOMElement ? self::normalizedText($button) : null,
            'selectedContentElementIndex' => $elementIndex,
            'selectedContentCount' => count($selectedContents),
            'selectedContentOptionCount' => count($options),
            'selectedContentSelectedOptionCount' => count($selectedOptions),
            'selectedContentSelectedValues' => $selectedValues,
            'selectedContentSelectedLabels' => $selectedLabels,
            'selectedContentSelectedTexts' => $selectedTexts,
            'selectedContentSelectedOptions' => $selectedOptions,
            'selectedContentEffectiveText' => $selectedTexts === [] ? null : implode(' ', $selectedTexts),
            'selectedContentIssues' => $issues,
            'selectedContentIssueCodes' => array_values(array_unique(array_map(
                static fn (array $issue): string => (string) ($issue['code'] ?? ''),
                $issues
            ))),
            'selectedContentValid' => $issues === [],
        ];
    }

    /**
     * @return array{value:string, label:string, text:string, selected:bool, disabled:bool, group?:string, groupDisabled?:bool}
     */
    private static function optionRecord(\DOMElement $option): array
    {
        $text = self::normalizedText($option);
        $record = [
            'value' => $option->hasAttribute('value') ? $option->getAttribute('value') : $text,
            'label' => $option->hasAttribute('label') ? $option->getAttribute('label') : $text,
            'text' => $text,
            'selected' => $option->hasAttribute('selected'),
            'disabled' => $option->hasAttribute('disabled'),
        ];

        $parent = $option->parentNode;
        if ($parent instanceof \DOMElement && self::htmlElementName($parent) === 'optgroup') {
            $record['group'] = $parent->hasAttribute('label') ? $parent->getAttribute('label') : '';
            $record['groupDisabled'] = $parent->hasAttribute('disabled');
            $record['disabled'] = $record['disabled'] || $record['groupDisabled'];
        }

        return $record;
    }

    /**
     * @param list<array{value:string, label:string, text:string, selected:bool, disabled:bool, group?:string, groupDisabled?:bool}> $options
     */
    private static function collectSelectOptionSummaries(\DOMNode $node, ?string $group, bool $groupDisabled, array &$options): void
    {
        if (!$node instanceof \DOMElement) {
            return;
        }

        $name = strtolower(self::htmlElementName($node));
        if ($name === 'optgroup') {
            $nextGroup = $node->getAttribute('label');
            $nextGroupDisabled = $groupDisabled || $node->hasAttribute('disabled');
            foreach ($node->childNodes as $child) {
                self::collectSelectOptionSummaries($child, $nextGroup, $nextGroupDisabled, $options);
            }

            return;
        }

        if ($name === 'option') {
            $option = self::optionRecord($node);
            if ($group !== null) {
                $option['group'] = $group;
                $option['groupDisabled'] = $groupDisabled;
                $option['disabled'] = $option['disabled'] || $groupDisabled;
            }
            $options[] = $option;

            return;
        }

        foreach ($node->childNodes as $child) {
            self::collectSelectOptionSummaries($child, $group, $groupDisabled, $options);
        }
    }

    /**
     * @param list<array<string, mixed>> $summary
     */
    private static function summaryText(array $summary): string
    {
        $text = '';
        foreach ($summary as $node) {
            if (($node['type'] ?? '') === 'text') {
                $text .= (string) ($node['text'] ?? '');
                continue;
            }
            if (($node['type'] ?? '') === 'element') {
                $text .= (string) ($node['text'] ?? '');
            }
        }

        $normalized = preg_replace('/[ \t\r\n\f]+/u', ' ', $text) ?? $text;

        return trim($normalized);
    }

    private static function isHtmlTableModelContext(string $name): bool
    {
        return isset(self::HTML5_TABLE_ALLOWED_CHILDREN[strtolower($name)]);
    }

    private static function shouldRepairOrphanHtmlTableChildren(\DOMNode $node): bool
    {
        if (!$node instanceof \DOMElement) {
            return true;
        }

        $name = self::htmlElementName($node);
        if (self::isHtmlTableModelContext($name)) {
            return false;
        }

        return self::htmlForeignContext($node) === null;
    }

    private static function serializeHtmlChildrenWithTableRepair(\DOMNode $node): string
    {
        $html = '';
        $pendingTableChildren = '';
        $pendingRows = '';
        $pendingCells = '';
        $pendingColumns = '';

        $flushPendingCells = static function () use (&$pendingCells, &$pendingRows): void {
            if ($pendingCells === '') {
                return;
            }

            $pendingRows .= '<tr>' . $pendingCells . '</tr>';
            $pendingCells = '';
        };
        $flushPendingRows = static function () use (&$pendingRows, &$pendingTableChildren): void {
            if ($pendingRows === '') {
                return;
            }

            $pendingTableChildren .= $pendingRows;
            $pendingRows = '';
        };
        $flushPendingColumns = static function () use (&$pendingColumns, &$pendingTableChildren): void {
            if ($pendingColumns === '') {
                return;
            }

            $pendingTableChildren .= '<colgroup>' . $pendingColumns . '</colgroup>';
            $pendingColumns = '';
        };
        $flushPendingTable = static function () use (
            &$html,
            &$pendingTableChildren,
            $flushPendingCells,
            $flushPendingRows,
            $flushPendingColumns
        ): void {
            $flushPendingColumns();
            $flushPendingCells();
            $flushPendingRows();
            if ($pendingTableChildren === '') {
                return;
            }

            $html .= '<table>' . $pendingTableChildren . '</table>';
            $pendingTableChildren = '';
        };

        foreach ($node->childNodes as $child) {
            if (!$child instanceof \DOMElement) {
                $flushPendingTable();
                $html .= self::serializeNode($child);
                continue;
            }

            $name = self::htmlElementName($child);
            if (self::isHtmlTableColumnElementName($name)) {
                $flushPendingCells();
                $flushPendingRows();
                $pendingColumns .= self::serializeNode($child);
                continue;
            }

            if (self::isHtmlTableOrphanContainerElementName($name)) {
                $flushPendingColumns();
                $flushPendingCells();
                $flushPendingRows();
                [$fosteredHtml, $childHtml] = self::serializeTableElementParts($child, $name);
                if ($fosteredHtml !== '') {
                    $flushPendingTable();
                    $html .= $fosteredHtml;
                }
                $pendingTableChildren .= $childHtml;
                continue;
            }

            if (self::isHtmlTableRowElementName($name)) {
                $flushPendingColumns();
                $flushPendingCells();
                [$fosteredHtml, $childHtml] = self::serializeTableElementParts($child, $name);
                if ($fosteredHtml !== '') {
                    $flushPendingTable();
                    $html .= $fosteredHtml;
                }
                $pendingRows .= $childHtml;
                continue;
            }

            if (self::isHtmlTableCellElementName($name)) {
                $flushPendingColumns();
                $pendingCells .= self::serializeNode($child);
                continue;
            }

            $flushPendingTable();
            $html .= self::serializeNode($child);
        }

        $flushPendingTable();

        return $html;
    }

    /**
     * @param list<array<string, mixed>> $nodes
     * @return list<array<string, mixed>>
     */
    private static function wrapOrphanHtmlTableSummary(array $nodes): array
    {
        $wrapped = [];
        $pendingTableChildren = [];
        $pendingRows = [];
        $pendingCells = [];
        $pendingColumns = [];

        $flushPendingCells = static function () use (&$pendingCells, &$pendingRows): void {
            if ($pendingCells === []) {
                return;
            }

            $pendingRows[] = self::generatedHtmlTableRowSummary($pendingCells);
            $pendingCells = [];
        };
        $flushPendingRows = static function () use (&$pendingRows, &$pendingTableChildren): void {
            if ($pendingRows === []) {
                return;
            }

            array_push($pendingTableChildren, ...$pendingRows);
            $pendingRows = [];
        };
        $flushPendingColumns = static function () use (&$pendingColumns, &$pendingTableChildren): void {
            if ($pendingColumns === []) {
                return;
            }

            $pendingTableChildren[] = self::generatedHtmlTableColumnGroupSummary($pendingColumns);
            $pendingColumns = [];
        };
        $flushPendingTable = static function () use (
            &$pendingTableChildren,
            &$wrapped,
            $flushPendingCells,
            $flushPendingRows,
            $flushPendingColumns
        ): void {
            $flushPendingColumns();
            $flushPendingCells();
            $flushPendingRows();
            if ($pendingTableChildren === []) {
                return;
            }

            $wrapped[] = self::generatedHtmlTableSummary($pendingTableChildren);
            $pendingTableChildren = [];
        };

        foreach ($nodes as $node) {
            $name = strtolower((string) ($node['name'] ?? ''));
            if (self::isHtmlTableColumnElementName($name)) {
                $flushPendingCells();
                $flushPendingRows();
                $pendingColumns[] = $node;
                continue;
            }

            if (self::isHtmlTableOrphanContainerElementName($name)) {
                $flushPendingColumns();
                $flushPendingCells();
                $flushPendingRows();
                $pendingTableChildren[] = $node;
                continue;
            }

            if (self::isHtmlTableRowElementName($name)) {
                $flushPendingColumns();
                $flushPendingCells();
                $pendingRows[] = $node;
                continue;
            }

            if (self::isHtmlTableCellElementName($name)) {
                $flushPendingColumns();
                $pendingCells[] = $node;
                continue;
            }

            $flushPendingTable();
            $wrapped[] = $node;
        }

        $flushPendingTable();

        return $wrapped;
    }

    private static function isHtmlTableOrphanContainerElementName(string $name): bool
    {
        return in_array(strtolower($name), ['caption', 'colgroup', 'thead', 'tbody', 'tfoot'], true);
    }

    private static function isHtmlTableRowElementName(string $name): bool
    {
        return strtolower($name) === 'tr';
    }

    private static function isHtmlTableCellElementName(string $name): bool
    {
        return in_array(strtolower($name), ['td', 'th'], true);
    }

    private static function isHtmlTableColumnElementName(string $name): bool
    {
        return strtolower($name) === 'col';
    }

    /**
     * @param list<array<string, mixed>> $children
     * @return array<string, mixed>
     */
    private static function generatedHtmlTableSummary(array $children): array
    {
        return [
            'type' => 'element',
            'name' => 'table',
            'attributes' => [],
            'text' => self::summaryText($children),
            'children' => $children,
            'tablePart' => 'table',
        ];
    }

    /**
     * @param list<array<string, mixed>> $cells
     * @return array<string, mixed>
     */
    private static function generatedHtmlTableRowSummary(array $cells): array
    {
        return [
            'type' => 'element',
            'name' => 'tr',
            'attributes' => [],
            'text' => self::summaryText($cells),
            'children' => $cells,
            'tablePart' => 'row',
        ];
    }

    /**
     * @param list<array<string, mixed>> $columns
     * @return array<string, mixed>
     */
    private static function generatedHtmlTableColumnGroupSummary(array $columns): array
    {
        return [
            'type' => 'element',
            'name' => 'colgroup',
            'attributes' => [],
            'text' => '',
            'children' => $columns,
            'tablePart' => 'column-group',
        ];
    }

    private static function isFosteredHtmlTableChild(\DOMNode $node, string $context): bool
    {
        $allowed = self::HTML5_TABLE_ALLOWED_CHILDREN[strtolower($context)] ?? null;
        if ($allowed === null) {
            return false;
        }

        if ($node instanceof \DOMText) {
            return preg_match('/\S/u', $node->nodeValue ?? '') === 1;
        }

        if (!$node instanceof \DOMElement) {
            return false;
        }

        $name = strtolower(self::htmlElementName($node));

        return !isset($allowed[$name]);
    }

    private static function rawTextContent(\DOMElement $element): string
    {
        $text = '';
        foreach ($element->childNodes as $child) {
            $text .= $child->nodeValue ?? '';
        }

        return $text;
    }

    private static function escapeHtmlRawTextContent(string $content): string
    {
        return strtr($content, ['&' => '&amp;', '<' => '&lt;', '>' => '&gt;']);
    }

    private static function protectHtmlCdataSections(string $html): string
    {
        return preg_replace_callback(
            '/<!\[CDATA\[(.*?)\]\]>/s',
            static fn (array $matches): string => self::escapeHtmlRawTextContent((string) $matches[1]),
            $html
        ) ?? $html;
    }

    private static function normalizeHtml5NamedCharacterReferences(string $html): string
    {
        return preg_replace_callback(
            '/&([A-Za-z][A-Za-z0-9]+);|&([A-Za-z][A-Za-z0-9]+)(?![A-Za-z0-9=])/',
            static function (array $matches): string {
                $semicolonName = (string) ($matches[1] ?? '');
                $legacyName = (string) ($matches[2] ?? '');
                $name = $semicolonName !== '' ? $semicolonName : $legacyName;
                if ($semicolonName === '' && !isset(self::HTML5_LEGACY_SEMICOLONLESS_CHARACTER_REFERENCES[$name])) {
                    return (string) $matches[0];
                }

                return self::HTML5_ADDITIONAL_NAMED_CHARACTER_REFERENCES[$name]
                    ?? self::decodeHtml5NamedCharacterReference($name, $semicolonName !== '')
                    ?? (string) $matches[0];
            },
            $html
        ) ?? $html;
    }

    private static function decodeHtml5NamedCharacterReference(string $name, bool $semicolonTerminated): ?string
    {
        if (!$semicolonTerminated || isset(self::HTML5_MARKUP_SENSITIVE_CHARACTER_REFERENCES[$name])) {
            return null;
        }

        $source = '&' . $name . ';';
        $decoded = html_entity_decode($source, ENT_QUOTES | ENT_HTML5, 'UTF-8');
        if ($decoded === $source || strpbrk($decoded, "&<>\"'") !== false) {
            return null;
        }

        return $decoded;
    }

    private static function escapeHtmlRcdataContent(string $content): string
    {
        return strtr($content, ['<' => '&lt;', '>' => '&gt;']);
    }

    private static function safeHtmlCommentText(string $text): string
    {
        while (str_contains($text, '--')) {
            $text = str_replace('--', '- -', $text);
        }

        return str_ends_with($text, '-') ? $text . ' ' : $text;
    }

    private static function serializeAttributes(\DOMElement $element): string
    {
        $attributes = self::htmlAttributes($element);
        if ($attributes === []) {
            return '';
        }

        $html = '';
        foreach ($attributes as $name => $value) {
            $lowerName = strtolower($name);
            if (isset(self::HTML5_BOOLEAN_ATTRIBUTES[$lowerName]) && ($value === '' || strtolower($value) === $lowerName)) {
                $html .= ' ' . $name;
                continue;
            }

            $html .= ' ' . $name . '="' . htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE | ENT_HTML5, 'UTF-8') . '"';
        }

        return $html;
    }

    private static function assertSafeSource(string $source, string $label): void
    {
        if (str_contains($source, "\0")) {
            throw new \InvalidArgumentException($label . ' must not contain NUL bytes');
        }
    }

    private static function assertNoDoctype(string $source, string $label): void
    {
        $declarationScanSource = self::sourceForDeclarationScan($source);
        if (preg_match('/<!\s*DOCTYPE\b/i', $declarationScanSource) === 1) {
            throw new \InvalidArgumentException($label . ' must not declare a document type');
        }
    }

    private static function assertNoHtmlFragmentDeclarations(string $source, string $label): void
    {
        $declarationScanSource = self::sourceForDeclarationScan($source);
        if (preg_match('/<!\s*(?:ENTITY|ELEMENT|ATTLIST|NOTATION)\b/i', $declarationScanSource) === 1) {
            throw new \InvalidArgumentException($label . ' must not declare DTDs or entities');
        }
        if (preg_match('/<\?[A-Za-z_][A-Za-z0-9_.:-]*/', $declarationScanSource) === 1) {
            throw new \InvalidArgumentException($label . ' must not include processing instructions');
        }
    }

    private static function sourceForDeclarationScan(string $source): string
    {
        $length = strlen($source);
        $scan = '';
        $offset = 0;

        while ($offset < $length) {
            if (str_starts_with(substr($source, $offset, 9), '<![CDATA[')) {
                $cdataEnd = strpos($source, ']]>', $offset + 9);
                if ($cdataEnd === false) {
                    $scan .= substr($source, $offset);
                    break;
                }

                $cdataLength = $cdataEnd + 3 - $offset;
                $scan .= str_repeat(' ', $cdataLength);
                $offset += $cdataLength;
                continue;
            }

            if (str_starts_with(substr($source, $offset, 4), '<!--')) {
                $commentEnd = strpos($source, '-->', $offset + 4);
                if ($commentEnd === false) {
                    $scan .= substr($source, $offset);
                    break;
                }

                $commentLength = $commentEnd + 3 - $offset;
                $scan .= str_repeat(' ', $commentLength);
                $offset += $commentLength;
                continue;
            }

            if ($source[$offset] === '<' && self::isHtmlTagStartForDeclarationScan($source, $offset)) {
                [$tagSource, $nextOffset] = self::maskQuotedTagAttributeValuesForDeclarationScan($source, $offset);
                $scan .= $tagSource;
                $offset = $nextOffset;
                continue;
            }

            $scan .= $source[$offset];
            ++$offset;
        }

        return $scan;
    }

    private static function isHtmlTagStartForDeclarationScan(string $source, int $offset): bool
    {
        $length = strlen($source);
        $nameOffset = $offset + 1;
        if ($nameOffset >= $length) {
            return false;
        }

        if ($source[$nameOffset] === '/') {
            ++$nameOffset;
        }

        return $nameOffset < $length && preg_match('/[A-Za-z]/', $source[$nameOffset]) === 1;
    }

    /**
     * @return array{0:string, 1:int}
     */
    private static function maskQuotedTagAttributeValuesForDeclarationScan(string $source, int $offset): array
    {
        $length = strlen($source);
        $tag = '';

        while ($offset < $length) {
            $char = $source[$offset];
            if ($char === '"' || $char === "'") {
                $quoteEnd = strpos($source, $char, $offset + 1);
                if ($quoteEnd === false) {
                    $tag .= substr($source, $offset);

                    return [$tag, $length];
                }

                $tag .= $char . str_repeat(' ', $quoteEnd - $offset - 1) . $char;
                $offset = $quoteEnd + 1;
                continue;
            }

            $tag .= $char;
            ++$offset;
            if ($char === '>') {
                break;
            }
        }

        return [$tag, $offset];
    }

    private static function assertNoProcessingInstructions(\DOMNode $node, string $label): void
    {
        if ($node instanceof \DOMProcessingInstruction) {
            throw new \InvalidArgumentException($label . ' must not include processing instructions');
        }

        foreach ($node->childNodes as $child) {
            self::assertNoProcessingInstructions($child, $label);
        }
    }

    private static function isHtmlForeignElement(\DOMElement $element): bool
    {
        return self::htmlForeignContext($element) !== null;
    }

    private static function htmlForeignContext(\DOMElement $element): ?string
    {
        $node = $element;
        $child = null;
        $isSelf = true;
        while ($node instanceof \DOMElement) {
            $name = strtolower($node->localName);
            if (!$isSelf && self::isHtmlIntegrationPoint($node)) {
                if (
                    !self::isMathMlTextIntegrationPointName($name)
                    || !$child instanceof \DOMElement
                    || !self::isMathMlTextIntegrationExceptionName(strtolower($child->localName))
                ) {
                    return null;
                }
            }
            if ($name === 'svg' || $name === 'math') {
                return $name;
            }
            if ($name === 'html' || $name === 'body') {
                return null;
            }

            $parent = $node->parentNode;
            $child = $node;
            $node = $parent instanceof \DOMElement ? $parent : null;
            $isSelf = false;
        }

        return null;
    }

    private static function isHtmlIntegrationPoint(\DOMElement $element): bool
    {
        $name = strtolower($element->localName);
        if (self::isSvgHtmlIntegrationPointName($name)) {
            return true;
        }
        if (self::isMathMlTextIntegrationPointName($name)) {
            return true;
        }
        if ($name !== 'annotation-xml') {
            return false;
        }

        $encoding = strtolower(trim($element->getAttribute('encoding')));

        return $encoding === 'text/html' || $encoding === 'application/xhtml+xml';
    }

    private static function isSvgHtmlIntegrationPointName(string $name): bool
    {
        return in_array($name, ['foreignobject', 'desc', 'title'], true);
    }

    private static function isMathMlTextIntegrationPointName(string $name): bool
    {
        return in_array($name, ['mi', 'mn', 'mo', 'ms', 'mtext'], true);
    }

    private static function isMathMlTextIntegrationExceptionName(string $name): bool
    {
        return $name === 'mglyph' || $name === 'malignmark';
    }

    /**
     * @param list<\LibXMLError> $errors
     */
    private static function parseErrorMessage(string $prefix, array $errors): string
    {
        if ($errors === []) {
            return $prefix;
        }

        $error = $errors[0];
        $message = trim($error->message);
        if ($message === '') {
            return $prefix;
        }

        return $prefix . ' at line ' . $error->line . ', column ' . $error->column . ': ' . $message;
    }
}
